-- Migration: add_2022_winter_substantive_q1_to_q40
--
-- Source: 2024 winter substantive-law batch (פברואר 2024, חלק ג', דין מהותי).
-- Two .docx files from the LawPass Content Pipeline Drive folder:
--   * (דין מהותי) 1-20  JSON.docx
--   * (דין מהותי) 21-40.docx  (contains Q21–Q40, with one duplicate of Q23)
--
-- Pipeline: scripts/ingestion/{parse_docx,normalize,generate_migration}.py +
-- the per-batch classification at scripts/ingestion/classifications/
-- 2024_winter_substantive.json. Re-classifies every question against the
-- substantive taxonomy from migration 20260526000001 (the JSON's own
-- chapter/subtopic — procedural placeholders from a stale Nevo template —
-- is ignored). source_metadata is also derived from the folder path, not
-- from the JSON's stale 2019/summer default.
--
-- Drops:
--   * 2024-W-S-Q20 — exact-content dup of Q18 (same question_text + choices).
--   * 2024-W-S-Q27 — JSON structurally broken beyond automatic repair.
--   * one in-file Q23 duplicate (the second of two consecutive Q23 fences).
--
-- Idempotency: each DO $$ block early-returns (RAISE NOTICE) if its
-- external_id already exists. Safe to re-run.

-- ============================================================
-- Q01 — 2022-W-S-Q01 — chapter=family_inheritance subtopic=inheritance_will
-- classifier_note: Widow died intestate; creditor's options against the estate before probate (צו ירושה)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '2884ff35-a9c3-4987-b1e8-2bce7f486317'::uuid;
  v_group_id uuid := '8ac2110c-0e60-4fd4-9cab-778e8af427f2'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '16c1f85b-a712-4896-a60e-bdc105757352'::uuid;
  v_ang_1 uuid := '112492d9-f75b-420b-a297-882eba073dbb'::uuid;
  v_ang_2 uuid := 'ce82198e-3cf8-4088-97d1-8909adbf1286'::uuid;
  v_ang_3 uuid := '7a39216f-fa84-449d-a922-de04df5ab918'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q01';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 1, '2022-W-S-Q01';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'family_inheritance';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'family_inheritance';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'inheritance_will' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'inheritance_will', 'family_inheritance';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q01', v_chapter_id, v_subtopic_id, 'אלמנה נפטרה, ובהיעדר צוואה נותרו 3 ילדיה הבגירים כיורשים. לימים התברר שהמנוחה הותירה אחריה רק 90,000 ש"ח וחוב חלוט לחברה פרטית בגובה 140,000 ש"ח. בהנחה שטרם הוצא צו ירושה, מה יכולה החברה לעשות?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 1}'::jsonb, 'השאלה עוסקת באחריות יורשים לחובות עיזבון לפני חלוקתו, בהתאם לסעיף 126 לחוק הירושה. היא מדגישה את העיקרון לפיו אחריות היורשים מוגבלת לנכסי העיזבון בלבד, ואינה חלה על נכסיהם האישיים, כל עוד העיזבון לא חולק. במקרה של חוב העולה על נכסי העיזבון, יתרת החוב אבודה עבור הנושה.', 'סעיף 126 לחוק הירושה, תשכ"ה-1965, קובע במפורש כי "עד לחלוקת העזבון אין היורשים אחראים לחובות העזבון אלא בנכסי העזבון". עיקרון זה מבטא את הרעיון שחוק הירושה גורס אחריות של יורשים מנכסי העיזבון בלבד, ואין לתבוע מהם מאומה מעבר לכך. במקרה הנדון, העיזבון טרם חולק (טרם הוצא צו ירושה), ולכן היורשים אינם אחראים לחובות העיזבון מנכסיהם האישיים. החברה הנושה יכולה לגבות את חובה רק מתוך נכסי העיזבון הקיימים, שהם 90,000 ש"ח. יתרת החוב, 50,000 ש"ח, אינה ניתנת לגבייה מהיורשים באופן אישי. הפסיקה מדגישה כי הנטל להוכיח שהעיזבון חולק מוטל על הנושה. ראו סעיף 126 לחוק הירושה, תשכ"ה-1965, וכן ת"א (מחוזי י-ם) 40350-07-19 בנק דיסקונט לישראל בע"מ נ'' רות בן אבי (26.6.2022), ת"א (שלום חי'') 59395-12-15 בנק יהב לעובדי המדינה בע"מ נ'' אנדרי זוביק רסולוב (המנוח) (27.5.2018). צו ירושה הוא דקלרטיבי בלבד ואינו מהווה חלוקת עיזבון. ראו ע"א 513/82 עדנה רייזמן נ'' גבריאלה וושצ''ין (12.5.1983).', 'הטעות הנפוצה היא לחשוב שהיורשים אחראים לחובות העיזבון באופן אישי, או שניתן לגבות מהם את יתרת החוב לאחר מיצוי נכסי העיזבון, גם לפני חלוקת העיזבון.',
    '["חוק הירושה", "אחריות יורשים", "חובות עיזבון", "חלוקת עיזבון", "סעיף 126 לחוק הירושה", "עיקרון הנפילה המיידית"]'::jsonb, '**וריאציה 1 — אחריות לפני חלוקה:** האם יורשים אחראים לחובות עיזבון מנכסיהם האישיים לפני חלוקה? ← לא, רק מנכסי העיזבון (סעיף 126 לחוק הירושה).
**וריאציה 2 — חוב גדול מנכסים:** מה קורה אם חוב העיזבון גדול מנכסיו לפני חלוקה? ← הנושה יגבה רק את שווי נכסי העיזבון, היתרה אבודה (ת"א בנק דיסקונט).
**וריאציה 3 — צו ירושה:** האם הוצאת צו ירושה מהווה חלוקת עיזבון? ← לא, צו ירושה הוא דקלרטיבי בלבד ואינו חלוקה (ע"א רייזמן).
**וריאציה 4 — נטל ההוכחה:** על מי מוטל הנטל להוכיח שהעיזבון חולק? ← על הנושה (ת"א בנק יהב).', 'לפני חלוקת עיזבון ← אחריות יורשים מוגבלת לנכסי העיזבון בלבד ← חובות העולים על נכסי העיזבון אבודים.', '["חוק הירושה, תשכ\"ה-1965: סע'' 126", "ת\"א (מחוזי י-ם) 40350-07-19 בנק דיסקונט לישראל בע\"מ נ'' רות בן אבי (26.6.2022)", "ת\"א (שלום חי'') 59395-12-15 בנק יהב לעובדי המדינה בע\"מ נ'' אנדרי זוביק רסולוב (המנוח) (27.5.2018)", "שמואל שילה פירוש לחוק הירושה כרך ג (2002) | סעיף 126: אחריות בנפסי העיזבון | א. כללי", "ע\"א 513/82 עדנה רייזמן נ'' גבריאלה וושצ''ין (12.5.1983)"]'::jsonb,
    'classification_review: original chapter=''הוצאה לפועל'' subtopic=''זכויות החייב'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Widow died intestate; creditor''s options against the estate before probate (צו ירושה) | source_review_note: השאלה עוסקת בדיני ירושה, שהם דין מהותי, ואינה משתלבת באופן מלא באף אחד מהפרקים הדיוניים הקיימים ברשימה הסגורה. סווגה תחת ''הוצאה לפועל - זכויות החייב'' כקירוב הטוב ביותר לנושא אחריות לחובות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לגבות 90,000 ש"ח מהעיזבון כיום, ו-50,000 ש"ח שווה בשווה מהיורשים בעתיד.', false, 'טענה זו שגויה. כל עוד העיזבון לא חולק, אחריות היורשים מוגבלת לנכסי העיזבון בלבד, ואין לגבות מהם באופן אישי את יתרת החוב.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לגבות 90,000 ש"ח מהעיזבון, ולפתוח הליך הוצאה לפועל נגד אחד או יותר מהיורשים בעתיד.', false, 'טענה זו שגויה. הליך הוצאה לפועל נגד היורשים באופן אישי אפשרי רק לאחר חלוקת העיזבון, וגם אז אחריותם מוגבלת בהתאם לסעיפים 127 ו-128 לחוק הירושה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לגבות 90,000 ש"ח בלבד מהעיזבון, יתרת החוב אבודה.', true, 'זוהי התשובה הנכונה. סעיף 126 לחוק הירושה קובע כי עד לחלוקת העיזבון, היורשים אחראים לחובות העיזבון רק מנכסי העיזבון. במקרה זה, נכסי העיזבון מסתכמים ב-90,000 ש"ח, ולכן יתרת החוב אבודה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לגבות מהיורשים את החוב כולו אחרי שהם יוציאו צו ירושה.', false, 'טענה זו שגויה. הוצאת צו ירושה אינה מהווה חלוקת עיזבון, והיא אינה משנה את אחריות היורשים לחובות העיזבון מנכסיהם האישיים כל עוד העיזבון לא חולק בפועל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות יורש יחיד לחובות עיזבון',
    1, 'אדם נפטר והותיר אחריו יורש יחיד. ליורש זה יש נכסים אישיים רבים. העיזבון טרם חולק, וטרם בוצע כל אקט חיצוני המעיד על מיזוג נכסי העיזבון עם נכסיו האישיים של היורש. נושה של המנוח מעוניין לגבות חוב מהעיזבון. מה הדין לגבי אחריות היורש?', 'שאלה זו בוחנת את אחריותו של יורש יחיד לחובות עיזבון לפני חלוקה. היא מדגישה כי גם במקרה של יורש יחיד, אחריותו מוגבלת לנכסי העיזבון בלבד כל עוד לא בוצע אקט חיצוני המעיד על מיזוג נכסי העיזבון עם נכסיו האישיים, וזאת בניגוד לטענה לפיה במקרה כזה העיזבון נחשב כחולק אוטומטית.', 'סעיף 126 לחוק הירושה, תשכ"ה-1965, קובע כי "עד לחלוקת העזבון אין היורשים אחראים לחובות העזבון אלא בנכסי העזבון". הפסיקה, ובפרט פסק הדין בעניין ת"א (מחוזי י-ם) 40350-07-19 בנק דיסקונט לישראל בע"מ נ'' רות בן אבי (26.6.2022), הבהירה כי המשמעות שיש לתת למונח "חלוקה" בכל הנוגע לחובות העיזבון, איננה חלוקה של נכסי העיזבון בין היורשים, אלא מדובר באקט שבו נכסי המוריש מתמזגים עם נכסי היורש. לכן, גם כאשר מדובר ביורש יחיד ולא מתבצעת חלוקה של נכסים בין היורשים, אין לומר שהעיזבון חולק מיד במות המוריש, אלא יש לבחון האם בוצע אקט שהביא למיזוג נכסי היורש עם נכסי המוריש. כל עוד לא מוזגו נכסי המוריש והיורש, חלה הוראת סעיף 126 לחוק הירושה, והנושה רשאי לגבות את חובו רק מנכסי העיזבון. זאת, כדי לאפשר ליורש היחיד את ההזדמנות למלא אחר הוראות חוק הירושה בקשר עם הזמנת הנושים קודם לביצוע החלוקה, ולזכות באחריות המופחתת שלה היה זוכה אילו היו מספר יורשים. ראו גם ת"א (שלום רחובות) 9456-07-20 ש"פ נ'' ל"י (3.9.2024).',
    'הנחה שגויה כי במקרה של יורש יחיד, העיזבון נחשב כחולק אוטומטית במות המוריש, ולכן אחריותו של היורש אינה מוגבלת לנכסי העיזבון.', '["חוק הירושה", "אחריות יורשים", "יורש יחיד", "חלוקת עיזבון", "מיזוג נכסים", "סעיף 126 לחוק הירושה"]'::jsonb, '**וריאציה 1 — יורש יחיד לפני מיזוג:** האם יורש יחיד אחראי לחובות עיזבון מנכסיו האישיים לפני מיזוג נכסים? ← לא, רק מנכסי העיזבון (סעיף 126 לחוק הירושה, ת"א בנק דיסקונט).
**וריאציה 2 — מהי ''חלוקה'' ליורש יחיד?** מהי המשמעות של ''חלוקת עיזבון'' במקרה של יורש יחיד? ← אקט חיצוני של מיזוג נכסי העיזבון עם נכסיו האישיים (ת"א בנק דיסקונט).
**וריאציה 3 — מטרת ההבחנה:** מדוע קיימת הבחנה זו גם ליורש יחיד? ← כדי לאפשר ליורש לזמן נושים ולזכות באחריות מופחתת (ת"א בנק דיסקונט).
**וריאציה 4 — נטל ההוכחה:** על מי מוטל הנטל להוכיח מיזוג נכסים? ← על הנושה (ת"א בנק דיסקונט).', 'יורש יחיד ← אחריות מוגבלת לנכסי עיזבון בלבד ← עד למיזוג נכסים באקט חיצוני.',
    '["חוק הירושה, תשכ\"ה-1965: סע'' 126", "ת\"א (מחוזי י-ם) 40350-07-19 בנק דיסקונט לישראל בע\"מ נ'' רות בן אבי (26.6.2022)", "ת\"א (שלום רחובות) 9456-07-20 ש\"פ נ'' ל\"י (3.9.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'אחריות היורש מוגבלת לנכסי העיזבון בלבד, ואין לגבות את החוב מנכסיו האישיים.', true, 'זוהי התשובה הנכונה. גם במקרה של יורש יחיד, כל עוד לא בוצע אקט חיצוני המעיד על מיזוג נכסי העיזבון עם נכסיו האישיים, אחריותו מוגבלת לנכסי העיזבון בלבד, בהתאם לסעיף 126 לחוק הירושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'במקרה של יורש יחיד, העיזבון נחשב כחולק מיד במות המוריש, ולכן ניתן לגבות את החוב מנכסיו האישיים של היורש.', false, 'טענה זו שגויה. הפסיקה קבעה כי גם במקרה של יורש יחיד, נדרש אקט חיצוני של מיזוג נכסים כדי שהעיזבון ייחשב כחולק, ואין חלוקה אוטומטית במות המוריש.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'היורש אחראי לחובות העיזבון עד שווי נכסיו האישיים, שכן הוא היורש היחיד.', false, 'טענה זו שגויה. אחריות היורש אינה חלה על נכסיו האישיים כל עוד העיזבון לא חולק, גם אם הוא יורש יחיד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הנושה יכול לבחור אם לגבות את החוב מנכסי העיזבון או מנכסיו האישיים של היורש.', false, 'טענה זו שגויה. בחירת הנושה מוגבלת על ידי הוראות חוק הירושה, וכל עוד העיזבון לא חולק, הגבייה מוגבלת לנכסי העיזבון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מועד חלוקת העיזבון',
    2, 'חוק הירושה אינו מגדיר במפורש את מועד ''חלוקת העיזבון''. מהם הקריטריונים המרכזיים שנקבעו בפסיקה לקביעת מועד זה לעניין אחריות יורשים לחובות?', 'שאלה זו עוסקת בפרשנות המונח ''חלוקת העיזבון'' בחוק הירושה, שאינו מוגדר במפורש. היא מתמקדת בקריטריונים שנקבעו בפסיקה, המדגישים את הצורך באקט חיצוני המעיד על חלוקה בפועל או מיזוג נכסים, בניגוד לצו ירושה דקלרטיבי או לעיקרון הנפילה המיידית.', 'חוק הירושה אינו מגדיר את מועד ''חלוקת העיזבון'', אך מונח זה מופיע בו ביחס למספר הסדרים, לרבות אחריות יורשים לחובות. הפסיקה קבעה כי מועד מתן צו ירושה או צו קיום צוואה אינו ''מועד חלוקת העיזבון'', מאחר והצו הוא דקלרטיבי בלבד ואינו מקנה זכות בנכס ספציפי. במקום זאת, נקבע כי כדי שיהיה אפשר לומר שהעיזבון חולק, יש צורך באקט חיצוני כלשהו המעיד על קיומה של חלוקה בפועל. אקט חיצוני כזה יכול להיות רישום נכס על שם יורש, הסכם חלוקה בין היורשים (בכתב או בעל פה), או מיזוג נכסי העיזבון עם נכסיו הפרטיים של היורש. ראו ת"א (מחוזי י-ם) 40350-07-19 בנק דיסקונט לישראל בע"מ נ'' רות בן אבי (26.6.2022), ע"א 810/77 נורי דרויש נ'' מלכה לוסטהאוז (20.5.1979), וכן ת"א (שלום חי'') 59395-12-15 בנק יהב לעובדי המדינה בע"מ נ'' אנדרי זוביק רסולוב (המנוח) (27.5.2018).',
    'הנחה שגויה שצו ירושה או צו קיום צוואה מהווים את מועד חלוקת העיזבון, או בלבול בין ''עיקרון הנפילה המיידית'' לבין חלוקה בפועל.', '["חלוקת עיזבון", "אקט חיצוני", "צו ירושה", "צו קיום צוואה", "עיקרון הנפילה המיידית", "אחריות יורשים"]'::jsonb, '**וריאציה 1 — צו ירושה כחלוקה:** האם צו ירושה הוא ''חלוקת עיזבון''? ← לא, הוא דקלרטיבי בלבד (ת"א בנק יהב).
**וריאציה 2 — מהו אקט חיצוני?** מה יכול להיחשב כ''אקט חיצוני'' המעיד על חלוקה? ← רישום נכס על שם יורש, הסכם חלוקה, מיזוג נכסים (ת"א בנק דיסקונט).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח שהעיזבון חולק? ← על הנושה (ת"א בנק דיסקונט).
**וריאציה 4 — מטרת ההבחנה:** מדוע חשובה ההבחנה בין ''נפילה מיידית'' ל''חלוקה''? ← ''נפילה מיידית'' אינה יוצרת בעלות קונקרטית בנכסים, ו''חלוקה'' היא השלב השני בהליך ההורשה (ת"א בנק דיסקונט).', 'מועד חלוקת עיזבון ← לא צו ירושה ← אקט חיצוני של חלוקה/מיזוג נכסים.',
    '["חוק הירושה, תשכ\"ה-1965", "ת\"א (מחוזי י-ם) 40350-07-19 בנק דיסקונט לישראל בע\"מ נ'' רות בן אבי (26.6.2022)", "ע\"א 810/77 נורי דרויש נ'' מלכה לוסטהאוז (20.5.1979)", "ת\"א (שלום חי'') 59395-12-15 בנק יהב לעובדי המדינה בע\"מ נ'' אנדרי זוביק רסולוב (המנוח) (27.5.2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מועד מתן צו ירושה או צו קיום צוואה, שכן אלו קובעים את זהות היורשים.', false, 'טענה זו שגויה. צו ירושה או צו קיום צוואה הם דקלרטיביים בלבד ואינם מהווים ''מועד חלוקת עיזבון'' לעניין אחריות יורשים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיומו של אקט חיצוני המעיד על חלוקה בפועל של נכסי העיזבון בין היורשים, או מיזוג נכסי העיזבון עם נכסי היורש.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי ''חלוקת עיזבון'' לעניין אחריות יורשים מתרחשת כאשר יש אקט חיצוני המעיד על חלוקה בפועל או מיזוג נכסים, ולא רק מתן צו ירושה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מועד פטירת המוריש, שכן אז עובר העיזבון ליורשים מכוח ''עיקרון הנפילה המיידית''.', false, 'טענה זו שגויה. ''עיקרון הנפילה המיידית'' אינו יוצר בעלות קונקרטית בנכסים ואינו מהווה ''חלוקת עיזבון'' לעניין אחריות לחובות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מועד סילוק כל חובות העיזבון, שכן רק אז ניתן לחלק את היתרה ליורשים.', false, 'טענה זו שגויה. סילוק חובות הוא שלב מקדים לחלוקה, אך אינו מהווה את מועד החלוקה עצמו, אלא אם כן הוא חלק מאקט חיצוני של חלוקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות יורש שהעלים נכסים',
    3, 'לאחר חלוקת עיזבון, התגלה כי אחד היורשים העלים במכוון נכסים מהעיזבון, ובכך מנע סילוק מלא של חובות העיזבון. מהי אחריותו של יורש זה לחובות שלא סולקו?', 'שאלה זו עוסקת בחריגים לאחריות המוגבלת של יורשים לחובות עיזבון לאחר חלוקה. היא מתמקדת בסעיף 129 לחוק הירושה, המטיל אחריות רחבה יותר על יורש שפעל בחוסר תום לב, כגון העלמת נכסים או חובות, ובכך מנע סילוקם של חובות העיזבון.', 'סעיף 129 לחוק הירושה, תשכ"ה-1965, קובע חריגים לאחריות המוגבלת של יורשים לאחר חלוקת העיזבון, המפורטת בסעיפים 127 ו-128. סעיף 129(1) קובע כי "על אף האמור בסעיפים 127 ו-128 - יורש שהעלים מנכסי העזבון ומנע בכך סילוקם של חובות, אחראי לכל החובות שלא סולקו כדי שוויו של כל העזבון בזמן החלוקה". כלומר, יורש שפעל בחוסר תום לב והעלים נכסים, מאבד את ההגנה של אחריות מוגבלת ונושא באחריות רחבה יותר. סעיף 129(2) קובע הוראה דומה לגבי יורש שהעלים קיומו של חוב או הכשיל בדרך אחרת את סילוקו. מטרת סעיף זה היא להרתיע יורשים ממעשי מרמה ולהבטיח את פירעון חובות העיזבון. ראו סעיף 129 לחוק הירושה, תשכ"ה-1965, וכן נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | אחריות במקרים מיוחדים.',
    'התעלמות מהחריגים הקבועים בסעיף 129 לחוק הירושה, והנחה שגויה שאחריות היורשים מוגבלת בכל מקרה, גם במעשי מרמה.', '["חוק הירושה", "אחריות יורשים", "העלמת נכסים", "חוסר תום לב", "סעיף 129 לחוק הירושה", "חובות עיזבון"]'::jsonb, '**וריאציה 1 — העלמת נכסים:** יורש העלים נכסים מהעיזבון. מה אחריותו לחובות שלא סולקו? ← אחראי לכל החובות עד שווי כל העיזבון (סעיף 129(1) לחוק הירושה).
**וריאציה 2 — העלמת חוב:** יורש העלים קיומו של חוב. מה אחריותו? ← אחראי לאותו חוב עד שווי כל העיזבון (סעיף 129(2) לחוק הירושה).
**וריאציה 3 — מטרת הסעיף:** מהי מטרת סעיף 129? ← להרתיע ממעשי מרמה ולהבטיח פירעון חובות (נבו - המתמחה).
**וריאציה 4 — אחריות מוגבלת:** האם אחריות זו מוגבלת למה שקיבל היורש? ← לא, היא רחבה יותר במקרה זה (סעיף 129 לחוק הירושה).', 'יורש שהעלים נכסים/חובות ← אחריות רחבה ← עד שווי כל העיזבון.',
    '["חוק הירושה, תשכ\"ה-1965: סע'' 129", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | אחריות במקרים מיוחדים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הוא אחראי לכל החובות שלא סולקו עד לשווי כל העיזבון בזמן החלוקה.', true, 'זוהי התשובה הנכונה. סעיף 129(1) לחוק הירושה קובע חריג לאחריות המוגבלת של יורשים, ומטיל אחריות רחבה על יורש שהעלים נכסים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הוא אחראי רק עד לשווי מה שקיבל מהעיזבון, שכן זוהי אחריות יורש לאחר חלוקה.', false, 'טענה זו שגויה. סעיף 129(1) לחוק הירושה קובע חריג מפורש לכלל זה במקרה של העלמת נכסים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הוא אחראי רק לחלק היחסי של החובות שלא סולקו, בהתאם לחלקו בעיזבון.', false, 'טענה זו שגויה. העלמת נכסים מטילה אחריות רחבה יותר על היורש, מעבר לחלקו היחסי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הוא פטור מאחריות, שכן הנושים היו צריכים לגלות את הנכסים בעצמם.', false, 'טענה זו שגויה. העלמת נכסים היא מעשה חמור המטיל אחריות על היורש, ואינה פוטרת אותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'גביית חובות קטנים מרשויות',
    4, 'רשות המיסים מעוניינת לגבות חוב חלוט בסך 15,000 ש"ח ממוריש שנפטר לפני שנה. טרם הוצא צו ירושה ואין מנהל עיזבון. מהו ההליך החלופי שרשות המיסים יכולה לנקוט לגביית החוב?', 'שאלה זו עוסקת בהליך חלופי ייחודי שנוסף לחוק הירושה (סימן ה''1) ולחוק ההוצאה לפועל (סעיף 78א), המאפשר לרשויות ולנושים לגבות חובות חלוטים קטנים מכספי עיזבון, ללא צורך במינוי מנהל עיזבון או בהמתנה לצו ירושה. היא מדגישה את התנאים והפרוצדורות הנדרשים להפעלת הליך זה, לרבות פרסום הודעות ומתן אפשרות להתנגדות.', 'סימן ה''1 לחוק הירושה, תשכ"ה-1965 (סעיפים 125א-125יב), קובע הליך חלופי לגביית חובות חלוטים של מוריש מכספי עיזבון המוחזקים בתאגיד בנקאי, על ידי רשויות המנויות בתוספת לחוק (כגון רשות המיסים). סעיף 125ג(א) לחוק מפרט את התנאים להפעלת הליך זה, ובהם: חלפה שנה לפחות מיום פטירת המוריש, סך החוב אינו עולה על הסכום המרבי (20,000 ש"ח, אלא אם נקבע אחרת), אין בקשה תלויה ועומדת לצו ירושה/קיום צוואה, לא ניתן צו ירושה/קיום צוואה (או שחלפו 6 חודשים והיורשים לא הזמינו נושים), לא מונה מנהל עיזבון, ועוד. סעיף 125ד לחוק מחייב את הרשות לפרסם הודעה על כוונתה לגבות את החוב ולשלוח הודעות ליורשים ולנושים הידועים לה, וזאת כדי לאפשר להם להגיש התנגדות. במקרה הנדון, רשות המיסים יכולה לפנות לתאגיד הבנקאי בבקשה לגביית החוב, בכפוף לתנאים אלו. ראו סעיף 125ג לחוק הירושה, תשכ"ה-1965, וכן נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק ה:1 - הליך חלופי לסילוק חובות מכספי העיזבון בלא מינוי מנהל עיזבון ושלא בידי היורשים.',
    'אי-הכרת ההליך החלופי הייחודי לגביית חובות קטנים מרשויות, והנחה שגויה שיש לנקוט בהליכים משפטיים רגילים או להמתין להוצאת צו ירושה.', '["חוק הירושה", "הליך חלופי", "חוב חלוט", "רשות המיסים", "תאגיד בנקאי", "סעיף 125ג לחוק הירושה"]'::jsonb, '**וריאציה 1 — גביית חוב קטן מרשות:** רשות המיסים רוצה לגבות חוב של 15,000 ש"ח ממוריש. מה הדרך? ← פנייה לתאגיד בנקאי לאחר פרסום הודעות (סעיפים 125ג, 125ד לחוק הירושה).
**וריאציה 2 — תנאים להליך:** מהם התנאים להפעלת הליך זה? ← חלפה שנה, חוב עד 20,000 ש"ח, אין צו ירושה/מנהל עיזבון (סעיף 125ג לחוק הירושה).
**וריאציה 3 — זכות התנגדות:** האם ליורשים/נושים יש זכות להתנגד? ← כן, בתוך 45 ימים מיום ההודעה (סעיף 125ה לחוק הירושה).
**וריאציה 4 — הליך דומה בהוצאה לפועל:** האם קיים הליך דומה לנושים פרטיים? ← כן, סעיף 78א לחוק ההוצאה לפועל (נבו - המתמחה).', 'רשות + חוב קטן + מוריש ← פנייה לבנק ← לאחר הודעות ← אפשרות התנגדות.',
    '["חוק הירושה, תשכ\"ה-1965: סע'' 125א, 125ב, 125ג, 125ד, 125ה, 125ז, 125ח, 125י", "חוק ההוצאה לפועל, תשכ\"ז-1967: סע'' 78א", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק ה:1 - הליך חלופי לסילוק חובות מכספי העיזבון בלא מינוי מנהל עיזבון ושלא בידי היורשים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לפנות לתאגיד בנקאי שבו מוחזקים כספי העיזבון, בבקשה לגביית החוב, לאחר פרסום ושליחת הודעות ליורשים ולנושים.', true, 'זוהי התשובה הנכונה. סעיפים 125ג ו-125ד לחוק הירושה קובעים הליך חלופי לרשויות לגביית חובות חלוטים קטנים מכספי עיזבון, באמצעות פנייה לתאגיד בנקאי, בכפוף לתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'להגיש תביעה לבית המשפט נגד היורשים הפוטנציאליים, שכן חלפה שנה מיום הפטירה.', false, 'טענה זו שגויה. למרות שחלפה שנה, קיימת דרך ייעודית ויעילה יותר לרשויות לגביית חובות קטנים, והגשת תביעה נגד יורשים פוטנציאליים לפני צו ירושה מורכבת יותר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לפנות לרשם ההוצאה לפועל בבקשה לצו לגביית חוב מכספי עיזבון, ללא צורך בפרסום הודעות.', false, 'טענה זו שגויה. סעיף 78א לחוק ההוצאה לפועל מאפשר הליך דומה, אך הוא מחייב פרסום ושליחת הודעות, ואינו מיועד לרשויות בלבד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'להמתין להוצאת צו ירושה ורק אז לגבות את החוב מהיורשים.', false, 'טענה זו שגויה. הליך חלופי זה נועד לאפשר גבייה מהירה ויעילה יותר של חובות קטנים, ללא צורך בהמתנה להוצאת צו ירושה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 1, '2022-W-S-Q01';
END
$$;

