-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e6bd46b3-4be6-488e-80e6-f5f8e5350129'::uuid;
  v_group_id uuid := '7fe1ec28-6485-4d7e-a0a3-cf7f3d63f622'::uuid;
