  v_ang_0 uuid := '29bb3a75-692c-4ab3-b377-212adb9cd3f1'::uuid;
  v_ang_1 uuid := '092a43dd-7601-4dde-952a-c7ca6b10e1ca'::uuid;
  v_ang_2 uuid := '3269c893-20c1-42dc-90ea-255c4d209d66'::uuid;
  v_ang_3 uuid := '62c1549c-7219-464a-962e-85772bc0664f'::uuid;
