-- classifier_note: Continuation of Q02 facts — Prof. Raphael's wink/promise to Mr. Lang = breach of fiduciary duty in M&A
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '1e40beed-d949-4ccb-a75d-b19de2e7cd26'::uuid;
  v_group_id uuid := 'c48e323b-90c9-45a0-8333-d0ff08f5f2dd'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '66f23298-ae65-433a-8ae6-307c7425aabb'::uuid;
  v_ang_1 uuid := '19b394a2-1a67-4064-bf5d-9577ecc807ac'::uuid;
  v_ang_2 uuid := '176f3e99-2bcc-42b5-b770-e3a2a4692aec'::uuid;
  v_ang_3 uuid := '7126d5cf-53c4-4c30-bd20-422e7edde1c5'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q03';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 3, '2022-W-S-Q03';
