  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q03', v_chapter_id, v_subtopic_id, 'הניחו כי לנתונים שהובאו בשאלה לעיל מתווספות העובדות הבאות (במצטבר): טרם הצגתו של פרופ'' רפאל לחברי הדירקטוריון וקבלת חוות דעת מטעמו הבטיח פרופ'' רפאל למר לנג "בקריצה" כי יגמול לו בהמשך היות שמר לנג קישר בין פרופ'' רפאל לבין החברה; מר לנג לא סיפר לחברי הדירקטוריון על הבטחה זו והאמין כי אין בכך כל פסול משום שסבר כי פרופ'' רפאל הוא איש רציני והוא ייתן חוות דעת ראויה לחברה, ובנסיבות אלה אין מניעה שייהנה מכך. בהינתן מכלול הנסיבות המתוארות לעיל מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 3}'::jsonb, 'השאלה עוסקת בהבחנה בין תביעה אישית לתביעה נגזרת בדיני חברות, ובפרט בסיווג הנזק שנגרם לבעל מניות כתוצאה מפעולות הדירקטוריון. היא מדגישה את עקרון האישיות המשפטית הנפרדת של החברה, הקובע כי נזק שנגרם לחברה מקים עילת תביעה לחברה עצמה, ואילו נזק לבעל מניות הנובע מירידת ערך מניותיו הוא נזק משני, המצריך הגשת תביעה נגזרת בשם החברה. בנוסף, השאלה מתייחסת לחובת הזהירות של דירקטורים כלפי החברה ולחובת האמונים של נושא משרה, במיוחד במקרה של ניגוד עניינים.', 'הכלל המנחה בדיני חברות הוא עקרון האישיות המשפטית הנפרדת של החברה. בהתאם לכך, כאשר נגרם נזק לחברה, עילת התביעה שייכת לחברה עצמה. נזק שנגרם לבעל מניות כתוצאה מירידת ערך מניותיו עקב נזק שנגרם לחברה, נחשב לנזק משני ואינו מקים לבעל המניות עילת תביעה אישית. במקרה כזה, הדרך הנכונה לבעל המניות לפעול היא באמצעות תביעה נגזרת, המוגשת בשם החברה ולטובתה (סעיף 194 לחוק החברות). הפיצוי, אם ייפסק, יועבר לקופת החברה, ובעל המניות ייהנה מכך בעקיפין באמצעות עליית ערך מניותיו. במקרה הנדון, מר לנג, שקיבל הבטחה לגמול מפרופ'' רפאל ולא גילה זאת לדירקטוריון, הפר את חובת אמונים כלפי החברה, ובפרט את האיסור על ניגוד עניינים (סעיף 254(א)(1) לחוק החברות). יתר חברי הדירקטוריון, שאשרו את העסקה על בסיס חוות דעת יחידה שהוצגה על ידי דירקטור עם קשר אישי למומחה, ללא בדיקה מעמיקה מספקת, הפרו את חובת הזהירות שלהם כלפי החברה (סעיפים 252 ו-253 לחוק החברות). לפיכך, לשמעון אין עילת תביעה אישית, אך החברה יכולה לתבוע את הדירקטורים בגין הפרת חובת אמונים (מר לנג) וחובת זהירות (יתר הדירקטורים). שמעון צריך לפנות לחברה בדרישה שתגיש תביעה נגזרת. ראו ת"צ (כלכלית ) 1525-09-18 מרדכי גבריאלי נ'' הראל ויזל (22.1.2019), ע"א 3417/16 פינרוס החזקות בע"מ נ'' התובע הייצוגי דב גולדשטיין (12.7.2021), וכן סעיפים 194, 252, 253, 254 לחוק החברות, התשנ"ט-1999.', 'הטעות הנפוצה היא בלבול בין נזק ישיר לבעל המניות לבין נזק משני, והגשת תביעה אישית במקום תביעה נגזרת, או אי-הבחנה בין חובת אמונים לחובת זהירות של נושאי משרה.',
    '["תביעה אישית", "תביעה נגזרת", "אישיות משפטית נפרדת", "נזק משני", "חובת זהירות", "חובת אמונים", "ניגוד עניינים", "סעיף 194 לחוק החברות"]'::jsonb, '**וריאציה 1 — נזק לירידת שווי מניות:** אם הנזק לבעל המניות הוא ירידת שווי מניות, מה סוג התביעה? ← נזק משני, עילת תביעה של החברה, תביעה נגזרת (גבריאלי, פינרוס).
**וריאציה 2 — הפרת חובת אמונים:** אם דירקטור לא גילה על טובת הנאה אישית מעסקה, איזו חובה הופרה? ← חובת אמונים (ניגוד עניינים) כלפי החברה (סעיף 254(א)(1) לחוק החברות).
**וריאציה 3 — הפרת חובת זהירות:** אם דירקטורים אישרו עסקה ללא בדיקה מספקת, איזו חובה הופרה? ← חובת זהירות כלפי החברה (סעיפים 252, 253 לחוק החברות).
**וריאציה 4 — פנייה לחברה:** מה הצעד הראשון של בעל מניות המעוניין בתביעה נגזרת? ← פנייה לחברה בדרישה שתגיש תביעה (סעיף 194(ב) לחוק החברות).', 'נזק משני לבעל מניות ← עילת תביעה של החברה ← תביעה נגזרת ← הפרת חובת אמונים (ניגוד עניינים) / חובת זהירות.', '["חוק החברות, תשנ\"ט-1999: סע'' 194, 252, 253, 254", "ת\"צ (כלכלית ) 1525-09-18 מרדכי גבריאלי נ'' הראל ויזל (22.1.2019)", "ע\"א 3417/16 פינרוס החזקות בע\"מ נ'' התובע הייצוגי דב גולדשטיין (12.7.2021)", "ת\"צ (מחוזי תל אביב-יפו) 29424-11-22 ברק שנהב נ'' אי.בי.אי. ניהול וחיתום בע\"מ (14.7.2025)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Continuation of Q02 facts — Prof. Raphael''s wink/promise to Mr. Lang = breach of fiduciary duty in M&A', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לשמעון עילת תביעה אישית נגד מר לנג בגין הפרת חובת אמונים כלפיו, וכן עילת תביעה אישית נגד יתר חברי הדירקטוריון בגין הפרת חובת הזהירות כלפיו.', false, 'טענה זו שגויה. הנזק שנגרם לשמעון הוא נזק משני הנובע מירידת ערך מניות החברה, ואינו מקים לו עילת תביעה אישית. חובות האמונים והזהירות של נושאי המשרה הן כלפי החברה, ולא כלפי בעלי המניות באופן אישי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לשמעון עילת תביעה אישית נגד כל חברי הדירקטוריון בגין הפרת חובת אמונים כלפיו.', false, 'טענה זו שגויה. לשמעון אין עילת תביעה אישית. בנוסף, רק מר לנג הפר חובת אמונים, בעוד שיתר הדירקטורים הפרו חובת זהירות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לשמעון לא קיימת עילת תביעה אישית נגד מי מחברי הדירקטוריון, ואולם לחברה קיימת עילת תביעה נגד מר לנג בגין הפרת חובת אמונים כלפיה ונגד חברי הדירקטוריון בגין הפרת חובת זהירות כלפיה. לפיכך על שמעון לפנות לחברה בדרישה כי זו תגיש תביעה נגד חברי הדירקטוריון בעילות כאמור.', true, 'זוהי התשובה הנכונה. הנזק לשמעון הוא נזק משני, ולכן עילת התביעה היא של החברה. מר לנג הפר את חובת אמונים כלפי החברה בכך שלא גילה על הבטחת הגמול (ניגוד עניינים). יתר הדירקטורים הפרו חובת זהירות בכך שלא פעלו ברמת מיומנות סבירה באישור העסקה. שמעון, כבעל מניות, רשאי לפנות לחברה בדרישה שתגיש תביעה נגזרת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לשמעון לא קיימת עילת תביעה אישית נגד מי מחברי הדירקטוריון, ואולם לחברה קיימת עילת תביעה נגד כל חברי הדירקטוריון בגין הפרת חובת אמונים כלפיה. לפיכך על שמעון לפנות לחברה בדרישה כי זו תגיש תביעה נגד חברי הדירקטוריון בעילה כאמור.', false, 'טענה זו שגויה בחלקה. אמנם לשמעון אין עילת תביעה אישית, והוא צריך לפנות לחברה, אך לא כל חברי הדירקטוריון הפרו חובת אמונים. רק מר לנג הפר חובת אמונים, בעוד שיתר הדירקטורים הפרו חובת זהירות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תביעה אישית בחברת מעטים',
    1, 'חברת ''סטארט-אפ חדש בע"מ'' היא חברת מעטים, בה שלושה בעלי מניות בלבד, שהם גם המייסדים והמנהלים. אחד מהם, דני, טוען כי שני השותפים האחרים, רונן וגלית, קיבלו החלטות עסקיות שגויות במכוון, שהביאו להפסדים כבדים לחברה ולירידה דרסטית בשווי מניותיו. דני מעוניין להגיש תביעה אישית נגד רונן וגלית. מה הדין?', 'שאלה זו בוחנת את החריג לכלל הנזק המשני, המאפשר לבעל מניות בחברת מעטים להגיש תביעה אישית גם כאשר הנזק נגרם לחברה. חברות מעטים נתפסות לעיתים כדומות לשותפויות, ולכן הפסיקה מכירה בחובות הדדיות מוגברות בין בעלי המניות, המצדיקות הכרה בעילת תביעה אישית במקרים מסוימים.', 'הכלל הוא כי כאשר נזק נגרם לחברה, עילת התביעה היא של החברה, ונזקם של בעלי המניות הוא נזק משני (ירידת ערך מניות) המצריך תביעה נגזרת. אולם, הפסיקה הכירה בחריג לכלל זה במקרים של חברות מעטים, שהן חברות פרטיות הדומות במהותן לשותפות. במקרים אלו, בשל יחסי האמון המיוחדים והחובות ההדדיות בין בעלי המניות, ניתן לאפשר לבעל מניות שנפגע להגיש תביעה אישית בגין נזק לו הוא טוען, גם אם ייתכן שנגרם נזק גם לחברה עצמה. זאת, כיוון שבחברות מעטים קשה יותר להבחין בין נזקים הנגרמים לחברה לבין פגיעה באינטרסים הלגיטימיים של בעלי המניות השותפים בה. ראו תנ"ג (כלכלית ) 47683-11-14 ביואסוסייאט ייעוץ וניהול בע"מ נ'' אופיר לוי (27.5.2016), ת"א (מחוזי מרכז) 52872-09-12 רועי ליאון נ'' איתי סחיש (15.6.2021), וכן ת"א (מחוזי י-ם) 35921-04-20 מרכז אירועים שירה חדשה בע"מ נ'' נתן נח שטיינברג (12.7.2021).',
    'התעלמות מהחריג של חברות מעטים ויישום הכלל הרגיל של נזק משני, או בלבול בין חברת מעטים לחברה ציבורית.', '["חברת מעטים", "תביעה אישית", "תביעה נגזרת", "נזק משני", "חובות הדדיות", "קיפוח המיעוט"]'::jsonb, '**וריאציה 1 — חברת מעטים ונזק לחברה:** האם בחברת מעטים ניתן להגיש תביעה אישית גם אם הנזק נגרם לחברה? ← כן, בשל אופיין דמוי השותפות (תנ"ג ביואסוסייאט).
**וריאציה 2 — יחסי אמון:** מה מצדיק את החריג בחברות מעטים? ← יחסי אמון מיוחדים וחובות הדדיות מוגברות בין בעלי המניות (ת"א רועי ליאון).
**וריאציה 3 — הבחנה בין סוגי חברות:** האם החריג חל גם בחברות ציבוריות? ← לא, החריג מיועד לחברות מעטים בלבד (ת"א מרכז אירועים שירה חדשה).
**וריאציה 4 — קיפוח המיעוט:** האם קיפוח המיעוט בחברת מעטים יכול להקים עילת תביעה אישית? ← כן, זהו אחד החריגים המוכרים (ת"א רועי ליאון).', 'חברת מעטים ← חריג לכלל הנזק המשני ← אפשרות לתביעה אישית גם בנזק לחברה.',
    '["תנ\"ג (כלכלית ) 47683-11-14 ביואסוסייאט ייעוץ וניהול בע\"מ נ'' אופיר לוי (27.5.2016)", "ת\"א (מחוזי מרכז) 52872-09-12 רועי ליאון נ'' איתי סחיש (15.6.2021)", "ת\"א (מחוזי י-ם) 35921-04-20 מרכז אירועים שירה חדשה בע\"מ נ'' נתן נח שטיינברג (12.7.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לדני קיימת עילת תביעה אישית נגד רונן וגלית, שכן בחברת מעטים הדומה במהותה לשותפות, ניתן להכיר בתביעה אישית גם כאשר נגרם נזק לחברה.', true, 'זוהי התשובה הנכונה. הפסיקה הכירה בחריג לכלל הנזק המשני בחברות מעטים, המאפשר הגשת תביעה אישית גם כאשר הנזק נגרם לחברה, בשל אופיין דמוי השותפות של חברות אלו והחובות ההדדיות המוגברות בין בעלי המניות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לדני אין עילת תביעה אישית, שכן הנזק שנגרם לו הוא נזק משני הנובע מירידת ערך החברה, ועליו להגיש תביעה נגזרת בשם החברה.', false, 'טענה זו שגויה. למרות שהנזק הוא משני, בחברות מעטים קיים חריג המאפשר הגשת תביעה אישית, ואין חובה להגיש תביעה נגזרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לדני אין עילת תביעה כלל, שכן החלטות עסקיות של דירקטורים חסינות מביקורת שיפוטית מכוח כלל שיקול הדעת העסקי.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי אינו חסינות מוחלטת, והוא אינו חל במקרים של חוסר תום לב או קבלת החלטות לא מיודעת. בנוסף, בחברת מעטים יש גמישות רבה יותר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לדני קיימת עילת תביעה אישית רק אם יוכיח שרונן וגלית פעלו בחוסר תום לב מובהק וגרמו לו נזק ישיר שאינו קשור לנזקי החברה.', false, 'טענה זו שגויה. בחברות מעטים, ההכרה בתביעה אישית רחבה יותר ואינה מוגבלת רק לנזק ישיר שאינו קשור לנזקי החברה, אלא יכולה לכלול גם נזקים משניים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני סיווג תביעה אישית מול נגזרת',
    2, 'מהם המבחנים העיקריים שנקבעו בפסיקה להבחנה בין תביעה אישית של בעל מניות לבין תביעה נגזרת, במקרים בהם נגרם נזק לחברה?', 'שאלה זו מתמקדת במבחנים המהותיים שנקבעו בפסיקה להבחנה בין תביעה אישית לתביעה נגזרת בדיני חברות. המבחן המרכזי הוא ''מבחן הנזק'', הבוחן האם הנזק לבעל המניות הוא ישיר ובלתי תלוי בנזק החברה, או נזק משני המשקף את נזקי החברה. מבחן נוסף הוא ''מבחן האם הנזק יישאר בעינו'' גם אם החברה תפוצה.', 'הפסיקה קבעה מספר מבחנים להבחנה בין תביעה אישית של בעל מניות לבין תביעה נגזרת. המבחן המרכזי, שנקבע בהלכת מגן וקשת בע"מ נ'' טמפו תעשיות בירה בע"מ (14.4.1997) ובהלכת ברוך דרין נ'' חברת השקעות דיסקונט בע"מ (9.9.2004), הוא האם הנזק שנגרם לבעל המניות הוא נזק בלתי תלוי בנזק שנגרם לחברה (אז זו תביעה אישית), או נזק משני המשקף את נזקי החברה (אז זו תביעה נגזרת). מבחן נוסף שהוצע הוא ''מבחן האם הנזק יישאר בעינו'' גם אם החברה תפוצה על נזקיה. אם התשובה חיובית, מדובר בנזק אישי. אם התשובה שלילית, מדובר בנזק משני. ראו ת"א (כלכלית ) 26028-01-19 תומאס קראפף נ'' אייל ברסלר (7.2.2021), ת"א (מחוזי מרכז) 7157-01-17 נילי אבידר ואח'' נ'' רפאל אוראל (9.5.2018), וכן תנ"ג (כלכלית ) 41104-06-17 נחום אלפונסו נ'' ד"ר יעקב רפאל (6.2.2020).',
    'בלבול בין נזק ישיר לבעל המניות לבין נזק משני הנובע מירידת ערך החברה, או אי-הבנה של ההשלכות של כל סוג נזק על סוג התביעה המתאים.', '["תביעה אישית", "תביעה נגזרת", "נזק ישיר", "נזק משני", "מבחן הנזק", "הלכת מגן וקשת", "הלכת דרין"]'::jsonb, '**וריאציה 1 — נזק בלתי תלוי:** אם הנזק לבעל המניות בלתי תלוי בנזק החברה, מה סוג התביעה? ← תביעה אישית (מגן וקשת).
**וריאציה 2 — נזק משני:** אם הנזק לבעל המניות נובע מירידת ערך החברה, מה סוג התביעה? ← תביעה נגזרת (דרין).
**וריאציה 3 — מבחן ''האם הנזק יישאר בעינו'':** מהו מבחן נוסף לסיווג? ← האם נזקו של בעל המניות יישאר בעינו גם אם החברה תפוצה (ציפורה כהן, אלפונסו).
**וריאציה 4 — מטרת ההבחנה:** מדוע חשובה ההבחנה? ← לשמירה על עקרון האישיות המשפטית הנפרדת, מניעת ריבוי תביעות והעדפת נושים (דרין, רע"א כץ).', 'סיווג תביעה ← נזק בלתי תלוי (אישית) או נזק משני (נגזרת) ← מבחן ''האם הנזק יישאר בעינו''.',
    '["ע\"א 2967/95 מגן וקשת בע\"מ נ'' טמפו תעשיות בירה בע\"מ, נא(2) 312 (14.4.1997)", "ע\"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע\"מ, נט(1) 673 (9.9.2004)", "ע\"א 3506/09 שלמה צאייג נ'' קסלמן וקסלמן רואי חשבון (4.4.2011)", "ת\"א (כלכלית ) 26028-01-19 תומאס קראפף נ'' אייל ברסלר (7.2.2021)", "ת\"א (מחוזי מרכז) 7157-01-17 נילי אבידר ואח'' נ'' רפאל אוראל (9.5.2018)", "תנ\"ג (כלכלית ) 41104-06-17 נחום אלפונסו נ'' ד\"ר יעקב רפאל (6.2.2020)", "רע\"א 5337/17 דוד כץ נ'' יעקב כץ (31.7.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המבחן העיקרי הוא האם הנזק שנגרם לבעל המניות הוא נזק בלתי תלוי בנזק שנגרם לחברה, או נזק משני המשקף את נזקי החברה.', true, 'זוהי התשובה הנכונה. זהו המבחן המרכזי שנקבע בהלכת מגן וקשת ודרין, וחוזר על עצמו בפסיקה, להבחנה בין תביעה אישית לתביעה נגזרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המבחן העיקרי הוא האם בעל המניות מחזיק באחוז מסוים ממניות החברה, שכן רק אז קמה לו זכות תביעה אישית.', false, 'טענה זו שגויה. אחוז ההחזקה במניות אינו המבחן העיקרי לסיווג התביעה כאישית או נגזרת, אלא רלוונטי יותר לתנאים להגשת תביעה נגזרת או ייצוגית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המבחן העיקרי הוא האם הנזק נגרם כתוצאה מהפרת חובת אמונים או חובת זהירות, שכן רק הפרת חובת אמונים מקנה עילת תביעה אישית.', false, 'טענה זו שגויה. סוג החובה שהופרה (אמונים או זהירות) אינו המבחן המכריע לסיווג התביעה כאישית או נגזרת, אלא מהות הנזק שנגרם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'המבחן העיקרי הוא האם החברה ציבורית או פרטית, שכן רק בחברה פרטית קמה עילת תביעה אישית.', false, 'טענה זו שגויה. סוג החברה (ציבורית/פרטית) אינו המבחן העיקרי, אלא חריג לכלל הנזק המשני, המאפשר גמישות בחברות מעטים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פטור מפנייה מוקדמת לחברה',
    3, 'שמעון, בעל מניות מיעוט בחברה ציבורית, מעוניין להגיש תביעה נגזרת נגד דירקטורים בחברה בגין הפרת חובת זהירות. הדירקטוריון מורכב מחמישה דירקטורים, ושלושה מהם הם הנתבעים הפוטנציאליים בתביעה. האם שמעון חייב לפנות לחברה בדרישה מוקדמת לפני הגשת הבקשה לאישור תביעה נגזרת?', 'שאלה זו עוסקת בתנאים הדיוניים להגשת תביעה נגזרת, ובפרט בחריגים לדרישת הפנייה המוקדמת לחברה. סעיף 194(ד) לחוק החברות קובע שני חריגים עיקריים, כאשר המרכזי שבהם הוא קיומו של עניין אישי למחצית או יותר מחברי האורגן המוסמך להחליט על הגשת התביעה, מצב המצדיק פטור מהפנייה המוקדמת.', 'סעיף 194(ב) לחוק החברות, תשנ"ט-1999, קובע כי בעל מניות המעוניין להגיש תביעה נגזרת יפנה לחברה בכתב וידרוש ממנה למצות את זכויותיה. דרישה זו היא תנאי דיוני מהותי, שמטרתו למנוע הגשת תביעות בלתי בשלות ולאפשר לחברה לפעול בעצמה. אולם, סעיף 194(ד) לחוק קובע שני חריגים לדרישה זו. החריג הרלוונטי לענייננו הוא סעיף 194(ד)(1), הקובע כי המעוניין להגיש תביעה נגזרת אינו חייב לפנות בדרישה לחברה אם "לאורגן החברה המוסמך להחליט על הגשת התביעה, עניין אישי בהחלטה, ואם האורגן כאמור מורכב מכמה יחידים למחצית או יותר מיחידה האורגן עניין אישי בהחלטה". במקרה זה, שלושה מתוך חמישה דירקטורים הם הנתבעים הפוטנציאליים, ולכן יש להם עניין אישי בהחלטה אם להגיש תביעה נגדם. מכיוון שמספרם (3) עולה על מחצית חברי הדירקטוריון (2.5), שמעון פטור מחובת הפנייה המוקדמת. ראו סעיף 194(ד) לחוק החברות, תשנ"ט-1999, תנ"ג (כלכלית ) 47683-11-14 ביואסוסייאט ייעוץ וניהול בע"מ נ'' אופיר לוי (27.5.2016), וכן תנ"ג (מחוזי מרכז) 22387-05-15 שמחה שילוני נ'' שלמה טום ויילר (16.6.2019).',
    'הנחה שגויה כי דרישת הפנייה המוקדמת היא מוחלטת, או אי-הבנה של תנאי החריג הקשור לעניין אישי של חברי הדירקטוריון.', '["תביעה נגזרת", "פנייה מוקדמת לחברה", "חוק החברות", "עניין אישי", "דירקטוריון", "סעיף 194(ד) לחוק החברות"]'::jsonb, '**וריאציה 1 — עניין אישי של רוב הדירקטוריון:** אם רוב הדירקטורים הם הנתבעים הפוטנציאליים, האם נדרשת פנייה מוקדמת? ← לא, פטור לפי סעיף 194(ד)(1) לחוק החברות.
**וריאציה 2 — חשש לפגיעה בסעד:** מהו חריג נוסף לפטור מפנייה מוקדמת? ← חשש סביר שפנייה תפגע באפשרות לקבל את הסעד (סעיף 194(ד)(2) לחוק החברות).
**וריאציה 3 — מטרת הפנייה המוקדמת:** מדוע קיימת דרישת הפנייה המוקדמת? ← למנוע תביעות בלתי בשלות ולאפשר לחברה למצות זכויותיה בעצמה (פר"ק אי.די.בי).
**וריאציה 4 — נטל ההוכחה לפטור:** על מי מוטל הנטל להוכיח התקיימות חריג לפטור? ← על התובע (תנ"ג שילוני).', 'תביעה נגזרת ← פנייה מוקדמת לחברה ← פטור אם לרוב הדירקטוריון עניין אישי או חשש לפגיעה בסעד.',
    '["חוק החברות, תשנ\"ט-1999: סע'' 194(ד)", "תנ\"ג (כלכלית ) 47683-11-14 ביואסוסייאט ייעוץ וניהול בע\"מ נ'' אופיר לוי (27.5.2016)", "תנ\"ג (מחוזי מרכז) 22387-05-15 שמחה שילוני נ'' שלמה טום ויילר (16.6.2019)", "פר\"ק (מחוזי ת\"א) 11478-06-13 אי.די.בי חברה לפיתוח בע\"מ נ'' כונס הנכסים הרשמי מחלקת תאגידים (20.1.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שמעון חייב לפנות לחברה בדרישה מוקדמת, שכן זו דרישה דיונית מהותית שאין ממנה פטור.', false, 'טענה זו שגויה. קיימים חריגים לדרישת הפנייה המוקדמת, ובמקרה זה מתקיים אחד מהם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שמעון פטור מפנייה מוקדמת, שכן למחצית או יותר מחברי האורגן המוסמך להחליט על הגשת התביעה יש עניין אישי בהחלטה.', true, 'זוהי התשובה הנכונה. סעיף 194(ד)(1) לחוק החברות קובע פטור מפנייה מוקדמת כאשר למחצית או יותר מחברי האורגן המוסמך (הדירקטוריון) יש עניין אישי בהחלטה, כפי שקורה כאשר הם הנתבעים הפוטנציאליים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן יוכיח שפנייה מוקדמת תפגע באפשרות לקבל את הסעד המבוקש.', false, 'טענה זו שגויה. למרות שזהו חריג נוסף (סעיף 194(ד)(2)), במקרה זה מתקיים החריג של עניין אישי, שפוטר מפנייה מוקדמת באופן מובהק יותר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, שמעון פטור מפנייה מוקדמת, שכן הוא בעל מניות מיעוט בחברה ציבורית.', false, 'טענה זו שגויה. מעמדו כבעל מניות מיעוט או סוג החברה אינם פוטרים אותו אוטומטית מפנייה מוקדמת, אלא רק התקיימות אחד מהחריגים המפורטים בחוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'כלל שיקול הדעת העסקי בתביעה נגזרת',
    4, 'דירקטוריון חברת ''השקעות בטוחות בע"מ'' החליט שלא להגיש תביעה נגד מנהל לשעבר, למרות המלצת יועץ משפטי חיצוני. בעל מניות מיעוט מעוניין להגיש תביעה נגזרת נגד המנהל לשעבר, וטוען כי החלטת הדירקטוריון שלא לתבוע היא שגויה. האם כלל שיקול הדעת העסקי יגן על הדירקטוריון מפני ביקורת שיפוטית על החלטתו שלא לתבוע?', 'שאלה זו בוחנת את תחולתו של כלל שיקול הדעת העסקי (Business Judgment Rule) על החלטות דירקטוריון שלא להפעיל את כוח התביעה של החברה. הכלל מקנה חזקת תקינות להחלטות דירקטוריון שהתקבלו בתום לב, ללא ניגוד עניינים ועל בסיס מידע מספק, ומגן עליהן מפני ביקורת שיפוטית, גם כאשר מדובר בהחלטות הנוגעות להליכים משפטיים.', 'כלל שיקול הדעת העסקי קובע ''חזקת תקינות'' לפיה החלטת דירקטוריון שהתקבלה בהליך תקין תהיה, ככלל, חסינה מפני ביקורת שיפוטית. הפסיקה קבעה כי כלל זה חל גם על החלטה של הדירקטוריון אם להפעיל או לא להפעיל את כוח התביעה של החברה על רקע בקשה של בעל מניות. החלטה כזו נחשבת להחלטה עסקית, ככל החלטה עסקית אחרת, כאשר על הדירקטוריון להעריך האם התביעה וניהולה הן לטובת החברה, את עלות ניהול התביעה, השפעתה על המוניטין של החברה ועוד. תנאי תחולת הכלל הם שהדירקטורים לא היו נגועים בניגוד עניינים, פעלו בתום לב וקיבלו את ההחלטה באופן מיודע (לאחר עיון בנתונים ושקילת השיקולים הרלוונטיים). אם תנאים אלו מתקיימים, בית המשפט לא יתערב בהחלטת הדירקטוריון. ראו ע"א 4857/16 אפרים מנשה נ'' יווז''ין אייר בע"מ (24.4.2018), וכן רע"א 4024/14 אפריקה ישראל להשקעות בע"מ נ'' רפאל כהן (26.4.2015).',
    'הנחה שגויה שכלל שיקול הדעת העסקי אינו חל על החלטות דירקטוריון בנוגע להליכים משפטיים, או אי-הבנה של תנאי תחולתו.', '["כלל שיקול הדעת העסקי", "תביעה נגזרת", "דירקטוריון", "חובת זהירות", "תום לב", "ניגוד עניינים", "החלטה מיודעת"]'::jsonb, '**וריאציה 1 — תחולת הכלל:** האם כלל שיקול הדעת העסקי חל על החלטה שלא לתבוע? ← כן, זו החלטה עסקית (ע"א בטר פלייס).
**וריאציה 2 — תנאי תחולה:** מהם תנאי תחולת הכלל? ← תום לב, היעדר ניגוד עניינים, החלטה מיודעת (ע"א בטר פלייס).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל לסתור את חזקת התקינות? ← על התובע (ע"א בטר פלייס).
**וריאציה 4 — מטרת הכלל:** מהי מטרת הכלל בהקשר זה? ← למנוע תביעות סרק, להפחית הרתעת יתר של נושאי משרה (ע"א בטר פלייס).', 'כלל שיקול הדעת העסקי ← חל גם על החלטה שלא לתבוע ← בתנאי תום לב, היעדר ניגוד עניינים ומידע מספק.',
    '["ע\"א 4857/16 אפרים מנשה נ'' יווז''ין אייר בע\"מ (24.4.2018)", "רע\"א 4024/14 אפריקה ישראל להשקעות בע\"מ נ'' רפאל כהן (26.4.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, כלל שיקול הדעת העסקי חל גם על החלטות דירקטוריון שלא להפעיל את כוח התביעה של החברה, ובלבד שההחלטה התקבלה בתום לב, ללא ניגוד עניינים ועל בסיס מידע מספק.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי כלל שיקול הדעת העסקי חל גם על החלטות דירקטוריון בנוגע להפעלת כוח התביעה של החברה, ומהווה הגנה מפני ביקורת שיפוטית, אם התקיימו תנאיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, כלל שיקול הדעת העסקי חל רק על החלטות עסקיות הנוגעות לניהול השוטף של החברה, ולא על החלטות הנוגעות להליכים משפטיים.', false, 'טענה זו שגויה. הפסיקה הרחיבה את תחולת כלל שיקול הדעת העסקי גם להחלטות דירקטוריון בנוגע להפעלת כוח התביעה של החברה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם הדירקטוריון קיבל את ההחלטה פה אחד, ללא כל התנגדות.', false, 'טענה זו שגויה. קבלת החלטה פה אחד אינה תנאי לתחולת כלל שיקול הדעת העסקי, אלא התנאים המהותיים של תום לב, היעדר ניגוד עניינים וקבלת החלטה מיודעת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, שכן המלצת יועץ משפטי חיצוני מחייבת את הדירקטוריון, וסטייה ממנה מהווה הפרת חובת זהירות.', false, 'טענה זו שגויה. המלצת יועץ משפטי היא שיקול חשוב, אך אינה מחייבת את הדירקטוריון באופן מוחלט, ואין בסטייה ממנה כשלעצמה כדי לשלול את תחולת כלל שיקול הדעת העסקי.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 3, '2022-W-S-Q03';
END
$$;

