-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '074b801f-2a94-4de9-90f3-541efc2f7e7f'::uuid;
  v_group_id uuid := 'c910a442-48d5-44c3-8f32-ab906660bfb7'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '3ce2282d-4427-44e0-8f9f-37bf69a23599'::uuid;
  v_ang_1 uuid := '900ce402-0e5c-4e88-9094-4c49bfdeb3ac'::uuid;
  v_ang_2 uuid := '572c4ec5-3b5a-4169-aa83-3fff34a103a2'::uuid;
  v_ang_3 uuid := '76d89042-d522-491b-9463-d099c39eea67'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q04';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 4, '2022-W-S-Q04';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'pledge' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'pledge', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q04', v_chapter_id, v_subtopic_id, 'לראובן יאכטה העוגנת במרינה בהרצליה. יצחק נתן לראובן הלוואה בסך 100,000 ש"ח בשנת 2000, והיה עליו לפרוע אותה בתוך שנתיים (בשנת 2002). בגין חוב זה נרשם כדין שעבוד ספציפי על היאכטה של ראובן. ראובן לא פרע את חובו, ובשנת 2022 פנה יצחק ללשכת ההוצאה לפועל כדי לממש את השעבוד. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 4}'::jsonb, 'השאלה עוסקת בהבחנה בין התיישנות עילת תביעה להתיישנות זכות קניינית של שעבוד רשום, בהתאם לסעיף 20 לחוק ההתיישנות. היא מדגישה את העיקרון לפיו שעבוד רשום אינו מתיישן, וניתן למימוש גם אם החוב האובליגטורי שהוא מבטיח התיישן.', 'סעיף 20 לחוק ההתיישנות, תשי"ח-1958, קובע במפורש כי "התיישנה תביעה לא יזקק בית המשפט לתובענה, אך אין בכך כדי למנוע קיזוז או כדי לבטל שעבוד ממושכן או משכון שהיו קיימים לפני ההתיישנות". עיקרון זה מבטא את ההבחנה בין התיישנות של זכות תביעה (זכות דיונית) לבין התיישנות של זכות מהותית או קניינית. במקרה זה, החוב האובליגטורי של ראובן ליצחק, שהיה אמור להיפרע בשנת 2002, התיישן לאחר 7 שנים, כלומר בשנת 2009 (בהתאם לסעיפים 5(1) ו-6 לחוק ההתיישנות). אולם, השעבוד הרשום על היאכטה של ראובן הוא זכות קניינית, וסעיף 20 לחוק ההתיישנות קובע כי זכות זו אינה מתבטלת עקב התיישנות החוב. לכן, יצחק יכול לפנות ללשכת ההוצאה לפועל ולממש את השעבוד על היאכטה, גם בשנת 2022, שכן השעבוד עצמו טרם התיישן. ראו סעיף 20 לחוק ההתיישנות, תשי"ח-1958, וכן ע"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע"מ (9.9.2004), וכן ע"א 16/89 "ורד" חברה לייבוא ושיווק (1983) בע"מ נ'' בנק לאומי לישראל בע"מ (28.12.1992).', 'הטעות הנפוצה היא בלבול בין התיישנות חוב אובליגטורי (שמתיישן לאחר 7 שנים) לבין התיישנות שעבוד רשום (שאינו מתיישן).',
    '["חוק ההתיישנות", "שעבוד", "משכון", "התיישנות", "זכות קניינית", "זכות אובליגטורית", "הוצאה לפועל", "סעיף 20 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — חוב רגיל:** חוב רגיל משנת 2000, מועד פירעון 2002. מתי התיישן? ← 2009 (7 שנים ממועד הפירעון).
**וריאציה 2 — שעבוד על מקרקעין:** שעבוד על מקרקעין משנת 2000, מועד פירעון 2002. מתי התיישן? ← לעולם לא, שעבוד על מקרקעין אינו מתיישן (סעיף 20 לחוק ההתיישנות).
**וריאציה 3 — שעבוד על מיטלטלין:** שעבוד על מיטלטלין משנת 2000, מועד פירעון 2002. מתי התיישן? ← השעבוד עצמו אינו מתיישן, רק עילת התביעה בגין החוב (סעיף 20 לחוק ההתיישנות).
**וריאציה 4 — מימוש שעבוד:** האם ניתן לממש שעבוד על מיטלטלין גם אם החוב התיישן? ← כן, סעיף 20 לחוק ההתיישנות מאפשר זאת.', 'שעבוד רשום ← אינו מתיישן ← גם אם החוב התיישן ← ניתן למימוש.', '["חוק ההתיישנות, תשי\"ח-1958: סע'' 5(1), 6, 20", "ע\"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע\"מ, נט(1) 673 (9.9.2004)", "ע\"א 16/89 \"ורד\" חברה לייבוא ושיווק (1983) בע\"מ נ'' בנק לאומי לישראל בע\"מ, מז(3) 491 (28.12.1992)"]'::jsonb,
    'classification_review: original chapter=''הוצאה לפועל'' subtopic=''פתיחת תיקים'' → mapped chapter=''property'' subtopic=''pledge'' | classifier_note: Yacht specific charge (שעבוד ספציפי) for loan default; pledge realization', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'השעבוד התיישן בשנת 2002.', false, 'טענה זו שגויה. שנת 2002 היא מועד הפירעון של החוב, לא מועד התיישנות השעבוד. השעבוד עצמו אינו מתיישן.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'השעבוד התיישן בשנת 2007.', false, 'טענה זו שגויה. שנת 2007 אינה מועד התיישנות רלוונטי לשעבוד. חוב רגיל מתיישן לאחר 7 שנים, כלומר בשנת 2009.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'השעבוד התיישן בשנת 2009.', false, 'טענה זו שגויה. בשנת 2009 התיישן החוב האובליגטורי, אך השעבוד עצמו, כזכות קניינית, אינו מתיישן.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'השעבוד טרם התיישן.', true, 'זוהי התשובה הנכונה. סעיף 20 לחוק ההתיישנות קובע כי התיישנות תביעה אינה מבטלת שעבוד ממושכן או משכון. השעבוד על היאכטה, כזכות קניינית, אינו מתיישן וניתן למימוש גם אם החוב האובליגטורי התיישן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'התיישנות חוב רגיל ללא שעבוד',
    1, 'לראובן חוב ליצחק בסך 100,000 ש"ח משנת 2000, שהיה עליו לפרוע בתוך שנתיים (בשנת 2002). לא נרשם כל שעבוד בגין חוב זה. ראובן לא פרע את חובו. בשנת 2022 פנה יצחק לבית המשפט כדי לתבוע את ראובן. מה הדין?', 'שאלה זו בוחנת את כלל ההתיישנות הרגיל של חוב אובליגטורי, ללא שעבוד, בהתאם לסעיף 5(1) לחוק ההתיישנות. היא מדגישה את מועד תחילת מרוץ ההתיישנות ואת תקופת ההתיישנות הכללית לחובות שאינם במקרקעין.', 'סעיף 5(1) לחוק ההתיישנות, תשי"ח-1958, קובע כי תקופת ההתיישנות בתובענה שאינה במקרקעין היא שבע שנים. סעיף 6 לחוק קובע כי תקופת ההתיישנות מתחילה ביום שבו נולדה עילת התביעה. במקרה זה, עילת התביעה נולדה במועד הפירעון, בשנת 2002. לכן, החוב התיישן 7 שנים לאחר מכן, בשנת 2009. משמעות ההתיישנות היא שבית המשפט לא יזקק לתובענה, אם הנתבע טוען להתיישנות (סעיף 2 לחוק ההתיישנות).',
    'בלבול בין תקופות התיישנות שונות או אי-זיהוי מועד תחילת מרוץ ההתיישנות הנכון לחוב אובליגטורי.', '["חוק ההתיישנות", "התיישנות חוב", "עילת תביעה", "תקופת התיישנות", "זכות אובליגטורית"]'::jsonb, '**וריאציה 1 — מועד פירעון:** מתי מתחיל מרוץ ההתיישנות לחוב? ← מיום היווצרות עילת התביעה, לרוב מועד הפירעון (סעיף 6 לחוק ההתיישנות).
**וריאציה 2 — תקופת התיישנות:** מהי תקופת ההתיישנות לחוב שאינו במקרקעין? ← 7 שנים (סעיף 5(1) לחוק ההתיישנות).
**וריאציה 3 — חוב שהתיישן:** האם ניתן לתבוע חוב שהתיישן? ← לא, בית המשפט לא יזקק לתובענה אם נטענה טענת התיישנות (סעיף 2 לחוק ההתיישנות).
**וריאציה 4 — התיישנות כטענת הגנה:** האם התיישנות מכבה את הזכות? ← לא, היא טענת הגנה דיונית בלבד (סעיף 2 לחוק ההתיישנות).', 'חוב רגיל ← 7 שנים מיום עילת התביעה ← התיישנות דיונית.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 2, 5(1), 6"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'התביעה טרם התיישנה, שכן יצחק פנה לבית המשפט בתוך 20 שנה מיום היווצרות החוב.', false, 'טענה זו שגויה. תקופת ההתיישנות לחוב שאינו במקרקעין היא 7 שנים, לא 20 שנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'התביעה התיישנה בשנת 2002.', false, 'טענה זו שגויה. שנת 2002 היא מועד הפירעון של החוב, ממנו מתחיל מרוץ ההתיישנות, לא מועד ההתיישנות עצמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'התביעה התיישנה בשנת 2009.', true, 'זוהי התשובה הנכונה. חוב רגיל מתיישן לאחר 7 שנים מיום היווצרות עילת התביעה (מועד הפירעון), בהתאם לסעיף 5(1) לחוק ההתיישנות. עילת התביעה נולדה בשנת 2002, ולכן התביעה התיישנה בשנת 2009.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'התביעה טרם התיישנה, שכן מרוץ ההתיישנות מתחיל רק מיום הפנייה לבית המשפט.', false, 'טענה זו שגויה. מרוץ ההתיישנות מתחיל מיום היווצרות עילת התביעה, ולא מיום הגשת התביעה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מועד תחילת מרוץ ההתיישנות בשעבוד',
    2, 'ראובן נתן ליצחק שעבוד רשום על יאכטה בשנת 2000, בגין הלוואה שהיה עליו לפרוע בשנת 2002. ראובן לא פרע את חובו. בשנת 2022 פנה יצחק ללשכת ההוצאה לפועל כדי לממש את השעבוד. מהו מועד תחילת מרוץ ההתיישנות של השעבוד, אם בכלל?', 'שאלה זו מתמקדמת בהבנת מהות השעבוד כזכות קניינית שאינה מתיישנת, בניגוד לחוב האובליגטורי שהיא מבטיחה. היא מדגישה את ההבחנה המהותית בין התיישנות זכות תביעה להתיישנות זכות קניינית.', 'סעיף 20 לחוק ההתיישנות, תשי"ח-1958, קובע כי "התיישנה תביעה לא יזקק בית המשפט לתובענה, אך אין בכך כדי למנוע קיזוז או כדי לבטל שעבוד ממושכן או משכון שהיו קיימים לפני ההתיישנות". המשמעות היא שהשעבוד, כזכות קניינית, אינו כפוף לדיני ההתיישנות. הזכות למימוש השעבוד נשארת בתוקף גם אם החוב האובליגטורי שהשעבוד מבטיח התיישן. לכן, אין מרוץ התיישנות לשעבוד עצמו, והוא אינו מתיישן.',
    'יישום כללי התיישנות של חובות אובליגטוריים על זכויות קנייניות כגון שעבודים, או בלבול בין מועד תחילת מרוץ ההתיישנות של החוב לבין זה של השעבוד.', '["שעבוד", "משכון", "התיישנות", "זכות קניינית", "זכות אובליגטורית", "סעיף 20 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — התיישנות זכות קניינית:** האם זכות קניינית מתיישנת? ← ככלל, לא (סעיף 20 לחוק ההתיישנות).
**וריאציה 2 — התיישנות חוב מובטח:** האם חוב המובטח בשעבוד מתיישן? ← כן, לפי הכללים הרגילים (7 שנים).
**וריאציה 3 — מימוש שעבוד לאחר התיישנות חוב:** האם ניתן לממש שעבוד גם אם החוב התיישן? ← כן, סעיף 20 לחוק ההתיישנות מאפשר זאת.
**וריאציה 4 — מטרת סעיף 20:** מהי מטרת סעיף 20 לחוק ההתיישנות? ← להגן על זכויות קנייניות מפני התיישנות, ולאפשר לנושה מובטח לממש את בטוחתו.', 'שעבוד ← זכות קניינית ← אינו מתיישן ← גם אם החוב התיישן.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 20"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מרוץ ההתיישנות מתחיל בשנת 2000, מיום רישום השעבוד.', false, 'טענה זו שגויה. מועד רישום השעבוד אינו רלוונטי לתחילת מרוץ התיישנות, שכן השעבוד עצמו אינו מתיישן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מרוץ ההתיישנות מתחיל בשנת 2002, מיום הפירעון של החוב.', false, 'טענה זו שגויה. מועד הפירעון רלוונטי לתחילת מרוץ ההתיישנות של החוב האובליגטורי, אך לא של השעבוד עצמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מרוץ ההתיישנות מתחיל בשנת 2009, מיום התיישנות החוב האובליגטורי.', false, 'טענה זו שגויה. מועד התיישנות החוב אינו מועד תחילת מרוץ התיישנות השעבוד. השעבוד אינו מתיישן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'השעבוד עצמו אינו מתיישן, ולכן אין מרוץ התיישנות לגביו.', true, 'זוהי התשובה הנכונה. סעיף 20 לחוק ההתיישנות קובע כי התיישנות תביעה אינה מבטלת שעבוד ממושכן או משכון. כלומר, השעבוד עצמו, כזכות קניינית, אינו כפוף לדיני ההתיישנות ואינו מתיישן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התיישנות שעבוד במקרקעין',
    3, 'ראובן נתן ליצחק משכנתא רשומה על דירתו בשנת 2000, בגין הלוואה שהיה עליו לפרוע בשנת 2002. ראובן לא פרע את חובו. בשנת 2022 פנה יצחק ללשכת ההוצאה לפועל כדי לממש את המשכנתא. מה הדין לגבי התיישנות המשכנתא?', 'שאלה זו בוחנת את ההבחנה בין התיישנות שעבוד על מיטלטלין לבין התיישנות שעבוד על מקרקעין (משכנתא). היא מדגישה את העיקרון ששעבוד על מקרקעין אינו מתיישן כלל, גם אם החוב האובליגטורי המובטח בו התיישן, וזאת בהתאם לסעיף 20 לחוק ההתיישנות ופרשנות הפסיקה.', 'סעיף 20 לחוק ההתיישנות, תשי"ח-1958, קובע כי התיישנות תביעה אינה מבטלת שעבוד ממושכן או משכון. הפסיקה הרחיבה וקבעה כי שעבוד על מקרקעין (משכנתא) אינו מתיישן כלל, גם אם החוב האובליגטורי המובטח בו התיישן. זאת, בניגוד לתביעה לקיום זכות במקרקעין, שמתיישנת לאחר 15 או 25 שנה (סעיף 5(2) לחוק ההתיישנות). המשכנתא היא זכות קניינית רשומה, והרישום מעניק לה תוקף מתמשך שאינו כפוף לדיני ההתיישנות. לכן, יצחק יכול לממש את המשכנתא גם בשנת 2022. ראו ע"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע"מ (9.9.2004), וכן ע"א 16/89 "ורד" חברה לייבוא ושיווק (1983) בע"מ נ'' בנק לאומי לישראל בע"מ (28.12.1992).',
    'בלבול בין התיישנות תביעה לקיום זכות במקרקעין לבין התיישנות שעבוד על מקרקעין, או יישום כללי התיישנות של חובות אובליגטוריים על זכויות קנייניות רשומות במקרקעין.', '["משכנתא", "שעבוד מקרקעין", "התיישנות", "זכות קניינית", "חוק ההתיישנות", "סעיף 20 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — התיישנות משכנתא:** האם משכנתא מתיישנת? ← לא, שעבוד על מקרקעין אינו מתיישן (ע"א דרין).
**וריאציה 2 — התיישנות חוב מובטח במשכנתא:** האם חוב המובטח במשכנתא מתיישן? ← כן, לפי הכללים הרגילים (7 שנים).
**וריאציה 3 — מימוש משכנתא לאחר התיישנות חוב:** האם ניתן לממש משכנתא גם אם החוב התיישן? ← כן, סעיף 20 לחוק ההתיישנות.
**וריאציה 4 — תביעה לקיום זכות במקרקעין:** מהי תקופת ההתיישנות לתביעה לקיום זכות במקרקעין? ← 15 שנה במקרקעין מוסדרים, 25 שנה במקרקעין לא מוסדרים (סעיף 5(2) לחוק ההתיישנות).', 'משכנתא ← שעבוד מקרקעין ← אינו מתיישן לעולם ← גם אם החוב התיישן.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 5(2), 20", "ע\"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע\"מ, נט(1) 673 (9.9.2004)", "ע\"א 16/89 \"ורד\" חברה לייבוא ושיווק (1983) בע\"מ נ'' בנק לאומי לישראל בע\"מ, מז(3) 491 (28.12.1992)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'המשכנתא התיישנה בשנת 2009, בדומה לשעבוד על מיטלטלין.', false, 'טענה זו שגויה. משכנתא על מקרקעין אינה מתיישנת, ואין להשוותה לשעבוד על מיטלטלין לעניין זה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'המשכנתא התיישנה בשנת 2022, שכן מרוץ ההתיישנות מתחיל מיום הפנייה ללשכת ההוצאה לפועל.', false, 'טענה זו שגויה. משכנתא אינה מתיישנת, ומועד הפנייה להוצאה לפועל אינו רלוונטי לתחילת מרוץ התיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'המשכנתא טרם התיישנה, שכן שעבוד על מקרקעין אינו מתיישן לעולם.', true, 'זוהי התשובה הנכונה. סעיף 20 לחוק ההתיישנות קובע כי התיישנות תביעה אינה מבטלת שעבוד ממושכן או משכון. הפסיקה קבעה כי שעבוד על מקרקעין (משכנתא) אינו מתיישן כלל, גם אם החוב האובליגטורי התיישן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'המשכנתא התיישנה לאחר 15 שנה, שכן זו תקופת ההתיישנות במקרקעין.', false, 'טענה זו שגויה. תקופת ההתיישנות של 15 שנה (או 25 שנה במקרקעין לא מוסדרים) מתייחסת לתביעה לקיום זכות במקרקעין, לא לשעבוד עצמו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השפעת התיישנות על זכות הקיזוז',
    4, 'ראובן חייב ליצחק 100,000 ש"ח משנת 2000, שהיה עליו לפרוע בשנת 2002. החוב התיישן בשנת 2009. בשנת 2022, יצחק חייב לראובן 50,000 ש"ח. האם יצחק יכול לקזז את חובו לראובן כנגד החוב הישן של ראובן אליו, למרות שהחוב של ראובן התיישן?', 'שאלה זו עוסקת בהשפעת ההתיישנות על זכות הקיזוז, בהתאם לסעיף 20 לחוק ההתיישנות. היא מדגישה את העיקרון לפיו התיישנות היא טענת הגנה דיונית שמונעת הגשת תביעה, אך אינה מכבה את הזכות המהותית, ולכן ניתן להשתמש בחוב שהתיישן כעילת קיזוז.', 'סעיף 20 לחוק ההתיישנות, תשי"ח-1958, קובע כי "התיישנה תביעה לא יזקק בית המשפט לתובענה, אך אין בכך כדי למנוע קיזוז או כדי לבטל שעבוד ממושכן או משכון שהיו קיימים לפני ההתיישנות". כלומר, למרות שהחוב של ראובן ליצחק התיישן בשנת 2009, יצחק עדיין יכול להשתמש בו כעילת קיזוז כנגד חובו לראובן. הסיבה לכך היא שהתיישנות היא טענת הגנה דיונית, שמונעת הגשת תביעה בגין החוב, אך אינה מבטלת את הזכות המהותית עצמה. לכן, החוב עדיין קיים, וניתן לקזז אותו. ראו ע"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע"מ (9.9.2004), וכן ע"א 16/89 "ורד" חברה לייבוא ושיווק (1983) בע"מ נ'' בנק לאומי לישראל בע"מ (28.12.1992).',
    'הנחה שגויה כי חוב שהתיישן נמחק לחלוטין ואינו יכול לשמש עוד לכל מטרה משפטית, כולל קיזוז.', '["התיישנות", "קיזוז", "חוב שהתיישן", "זכות מהותית", "טענת הגנה דיונית", "סעיף 20 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — קיזוז חוב שהתיישן:** האם ניתן לקזז חוב שהתיישן? ← כן, סעיף 20 לחוק ההתיישנות קובע שהתיישנות אינה מונעת קיזוז.
**וריאציה 2 — התיישנות ככיבוי זכות:** האם התיישנות מכבה את הזכות המהותית? ← לא, היא רק מונעת הגשת תביעה (ע"א דרין).
**וריאציה 3 — תנאי לקיזוז:** האם יש תנאים מיוחדים לקיזוז חוב שהתיישן? ← לא, כללי הקיזוז הרגילים חלים, בתוספת סעיף 20 לחוק ההתיישנות.
**וריאציה 4 — מטרת סעיף 20 לקיזוז:** מהי מטרת סעיף 20 בהקשר לקיזוז? ← למנוע מצב שבו חייב יתחמק מתשלום חובו שהתיישן, כאשר הוא עצמו חייב לנושה.', 'חוב שהתיישן ← ניתן לקיזוז ← התיישנות אינה מכבה זכות מהותית.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 20", "ע\"א 3051/98 ברוך דרין נ'' חברת השקעות דיסקונט בע\"מ, נט(1) 673 (9.9.2004)", "ע\"א 16/89 \"ורד\" חברה לייבוא ושיווק (1983) בע\"מ נ'' בנק לאומי לישראל בע\"מ, מז(3) 491 (28.12.1992)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, יצחק אינו יכול לקזז את החוב, שכן חוב שהתיישן אינו ניתן לקיזוז.', false, 'טענה זו שגויה. סעיף 20 לחוק ההתיישנות קובע במפורש כי התיישנות אינה מונעת קיזוז.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, יצחק יכול לקזז את החוב, שכן התיישנות אינה מבטלת את הזכות המהותית, אלא רק מונעת תביעה בגינה.', true, 'זוהי התשובה הנכונה. סעיף 20 לחוק ההתיישנות קובע כי התיישנות תביעה אינה מונעת קיזוז. כלומר, למרות שהחוב התיישן ולא ניתן לתבוע אותו, הוא עדיין קיים כזכות מהותית וניתן לקיזוז.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם החוב של ראובן ליצחק היה מובטח בשעבוד.', false, 'טענה זו שגויה. זכות הקיזוז של חוב שהתיישן אינה תלויה בקיומו של שעבוד, אלא נובעת מהוראת סעיף 20 לחוק ההתיישנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן ראובן הסכים לקיזוז לאחר שהחוב התיישן.', false, 'טענה זו שגויה. זכות הקיזוז של חוב שהתיישן אינה דורשת הסכמה של הצד השני, אלא היא זכות קבועה בחוק.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 4, '2022-W-S-Q04';
END
$$;

