-- Q05 — 2022-W-S-Q05 — chapter=contracts subtopic=sale
-- classifier_note: Defective chocolate goods, prepaid; sale-of-goods + return obligations
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '21a638fb-4b6e-498e-8426-2a7ac931ad06'::uuid;
  v_group_id uuid := '70127029-b80f-4f4d-a389-9294d0d9a74a'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '76a01427-e601-4727-aefd-9c83e2cab1bc'::uuid;
  v_ang_1 uuid := 'ec5d8caf-7f3a-4875-8956-5f19da7986ff'::uuid;
  v_ang_2 uuid := '48f3b0b6-52a2-4476-b128-daa016ed439f'::uuid;
  v_ang_3 uuid := '438f6fb5-2192-45d5-a968-81b485ade86d'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q05';
