  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q05', v_chapter_id, v_subtopic_id, 'דוד רכש סחורה של שוקולד מחברת "שושנת העמקים בע"מ" ושילם מראש על הסחורה. לאחר מסירת הסחורה לידיו של דוד התברר שהשוקולד נגוע בזיהום בקטריאלי. החברה הודיעה לדוד על הזיהום והודיעה לו שעליו להחזיר את הסחורה למפעל מיד ושהוא יקבל את מלוא התשלום ששילם בתוספת פיצוי. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 5}'::jsonb, 'השאלה עוסקת בזכות העיכבון (Lien) כסעד עצמי בדיני חוזים ומכר. היא בוחנת את זכותו של קונה ששילם מראש וקיבל סחורה פגומה לעכב את הסחורה עד לקבלת החזר תשלום, בהתאם לסעיף 31 לחוק המכר וסעיף 19 לחוק החוזים (תרופות בשל הפרת חוזה).', 'הדין הישראלי מכיר בזכות העיכבון כסעד עצמי המאפשר לנושה להחזיק בנכס של החייב הנמצא ברשותו כדין, עד שהחייב יסלק את חובו. במקרה זה, דוד רכש שוקולד ושילם מראש, אך קיבל סחורה פגומה, המהווה הפרת חוזה מצד חברת "שושנת העמקים בע"מ". כתוצאה מההפרה, קמה לדוד זכות לבטל את החוזה ולדרוש השבה של התשלום ששילם. סעיף 31(א) לחוק המכר, התשכ"ח-1968, קובע במפורש כי "למוכר תהא זכות עכבון על הממכר... וכן תהא זכות עכבון לקונה כדי תשלום הסכומים המגיעים לו מן המוכר, אם קיבל את הממכר ועליו להחזירו למוכר". בנוסף, סעיף 19 לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970, קובע באופן כללי יותר כי "קיבל הנפגע עקב החוזה נכס של המפר שעליו להחזירו, תהא לנפגע זכות עיכבון באותו נכס כדי תשלום הסכומים המגיעים לו מן המפר עקב ההפרה". לפיכך, דוד, כקונה וכנפגע מהפרת החוזה, רשאי לעכב את השוקולד הפגום שקיבל ועליו להחזירו, עד שהחברה תשיב לו את מלוא התשלום ששילם. חובות ההשבה במקרה של ביטול חוזה הן הדדיות, וזכות העיכבון מאפשרת לדוד להבטיח את קבלת כספו. ראו סעיף 31 לחוק המכר, תשכ"ח-1968, סעיף 19 לחוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970, וכן ע"א 4588/06 אלוניאל בע"מ נ'' כונס הנכסים עו"ד שי גרנות (30.9.2009).', 'הטעות הנפוצה היא בלבול בין חובת השבה לבין זכות עיכבון, או אי-הבנה של היקף זכות העיכבון של קונה ששילם מראש וקיבל סחורה פגומה.',
    '["זכות עיכבון", "חוק המכר", "חוק החוזים (תרופות)", "הפרת חוזה", "השבה", "סעד עצמי", "חיובים שלובים", "סחורה פגומה"]'::jsonb, '**וריאציה 1 — קונה ששילם מראש וקיבל סחורה פגומה:** האם הקונה יכול לעכב את הסחורה עד לקבלת כספו? ← כן, מכוח סעיף 31 לחוק המכר וסעיף 19 לחוק החוזים (תרופות).
**וריאציה 2 — מוכר שקיבל תשלום מראש ומסר סחורה פגומה:** האם המוכר יכול לדרוש את הסחורה בחזרה לפני השבת התשלום? ← לא, חובת ההשבה הדדית וניתן לעכב את הסחורה.
**וריאציה 3 — מהות זכות העיכבון:** האם זכות העיכבון מאפשרת מימוש הנכס? ← לא, היא רק מאפשרת החזקה בנכס כאמצעי לחץ (ע"א סולל בונה).
**וריאציה 4 — תום לב בהפעלת עיכבון:** האם יש מגבלות על הפעלת זכות העיכבון? ← כן, יש להפעילה בתום לב ובמידתיות (ע"א שלדות מפעלי מתכת).', 'קונה ששילם מראש וקיבל סחורה פגומה ← זכות עיכבון על הסחורה ← עד לקבלת החזר תשלום ← סעיף 31 לחוק המכר, סעיף 19 לחוק החוזים (תרופות).', '["חוק המכר, תשכ\"ח-1968: סע'' 31", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970: סע'' 19", "ע\"א 4588/06 אלוניאל בע\"מ נ'' כונס הנכסים עו\"ד שי גרנות (30.9.2009)", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (19.8.2002)", "ע\"א 79/89 סולל בונה בע\"מ נ'' אחים גולדשטיין חברה לשיכון ופיתוח בע\"מ (בפירוק), מו(3) 058 (3.5.1992)", "רע\"א 7204/18 אריגים תוצרת ארצנו בע\"מ נ'' עוה\"ד מור נרדיה וליזה חדש - בתפקידם כנאמנים ‏זמניים (13.5.2019)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''sale'' | classifier_note: Defective chocolate goods, prepaid; sale-of-goods + return obligations', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'חברת "שושנת העמקים בע"מ" רשאית שלא להשיב לדוד את התשלום ששילם עד להגעת הסחורה למפעל.', false, 'טענה זו שגויה. החברה היא המפרה, ודוד זכאי לעכב את הסחורה עד לקבלת התשלום בחזרה, בהתאם לזכות העיכבון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דוד רשאי שלא להשיב לחברת "שושנת העמקים בע"מ" את הסחורה עד לקבלת החזר התשלום בפועל מהחברה.', true, 'זוהי התשובה הנכונה. דוד, כנפגע מהפרת חוזה (סחורה פגומה), זכאי לעכב את הסחורה שקיבל ועליו להחזירה, עד לקבלת הסכומים המגיעים לו מהמפר (החזר התשלום), מכוח סעיף 31 לחוק המכר וסעיף 19 לחוק החוזים (תרופות בשל הפרת חוזה).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לשני הצדדים זכות שלא להשיב את הסחורה ואת התשלום (בהתאמה), ואם שני הצדדים עומדים על זכותם, עליהם לארגן את ההשבה ההדדית כך שתתבצע בו זמנית.', false, 'טענה זו שגויה. רק לדוד, כנפגע, עומדת זכות העיכבון. החברה היא המפרה ואינה יכולה לעכב את התשלום המגיע לדוד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אין למי מן הצדדים זכות להתנות את ההשבה, ולפיכך על כל צד לקיים את חובת ההשבה המוטלת עליו ללא תלות במעשי הצד השני.', false, 'טענה זו שגויה. זכות העיכבון היא סעד עצמי המאפשר להתנות את ההשבה, והיא מעוגנת בחוקים הרלוונטיים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'זכות עיכבון של קבלן',
    1, 'ראובן הזמין מקבלן שיפוצים, שמעון, לבצע עבודות שיפוץ בדירתו. שמעון סיים את העבודות, אך ראובן מסרב לשלם את מלוא התמורה בטענה לליקויים. שמעון, שעדיין מחזיק בחלק מהציוד שהביא לדירה לצורך השיפוץ, מעוניין לעכב את הציוד עד שראובן ישלם לו. האם שמעון רשאי לעשות כן?', 'שאלה זו בוחנת את תנאי היסוד לזכות עיכבון של קבלן, ובפרט את הדרישה שהנכס המעוכב יהיה שייך למזמין העבודה ונמסר לקבלן לצורך ביצוע המלאכה. זכות העיכבון אינה חלה על ציוד שבבעלות הקבלן עצמו.', 'סעיף 5 לחוק חוזה קבלנות, התשל"ד-1974, קובע כי "לקבלן תהא זכות עיכבון על נכס שמסר לו המזמין לביצוע מלאכתו או למתן שירותו, כדי תשלום הסכומים המגיעים לו מן המזמין עקב עסקת הקבלנות". זכות העיכבון היא זכות קניינית המאפשרת לנושה להחזיק בנכס של החייב עד לפירעון החוב. תנאי מהותי לקיומה של זכות עיכבון הוא שהנכס המעוכב יהיה שייך לחייב (המזמין במקרה זה) ונמצא בחזקת הנושה (הקבלן). במקרה הנדון, הציוד ששמעון מעוניין לעכב הוא ציוד שהוא עצמו הביא לדירה, כלומר ציוד שבבעלותו. זכות עיכבון אינה יכולה לחול על נכס שבבעלות הנושה עצמו, שכן הנושה אינו צריך ''לעכב'' את רכושו שלו. הוא פשוט מחזיק בו כבעליו. לכן, שמעון אינו רשאי לעכב את הציוד שלו מכוח זכות עיכבון. ראו ע"א 6492/00 שלדות מפעלי מתכת בע"מ נ'' מאזן אמין שחיבר (19.8.2002), וכן פש"ר (מחוזי ת"א) 1710-09 אשיש דיאמונדס בע"מ נ'' כונס נכסים רשמי תל אביב (12.4.2016).',
    'הנחה שגויה שזכות עיכבון חלה על כל נכס הנמצא בחזקת הנושה, ללא קשר לבעלות עליו.', '["זכות עיכבון", "חוק חוזה קבלנות", "נכס המזמין", "בעלות", "חזקה", "סעד עצמי"]'::jsonb, '**וריאציה 1 — עיכבון על ציוד הקבלן:** האם קבלן יכול לעכב ציוד שבבעלותו? ← לא, זכות עיכבון חלה על נכס של המזמין (סעיף 5 לחוק חוזה קבלנות).
**וריאציה 2 — עיכבון על נכס המזמין:** אם הקבלן מחזיק בנכס של המזמין שעליו עבד, האם יכול לעכב אותו? ← כן, עד לתשלום חובו (סעיף 5 לחוק חוזה קבלנות).
**וריאציה 3 — תנאי לזכות עיכבון:** מהו תנאי מהותי לזכות עיכבון? ← שהנושה מחזיק בנכס של החייב (ע"א שלדות מפעלי מתכת).
**וריאציה 4 — מטרת העיכבון:** מהי מטרת זכות העיכבון? ← להפעיל לחץ על החייב לפרוע את חובו (ע"א ליבוביץ).', 'קבלן ← זכות עיכבון ← רק על נכס של המזמין ← שנמסר לו לביצוע מלאכה.',
    '["חוק חוזה קבלנות, תשל\"ד-1974: סע'' 5", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (19.8.2002)", "פש\"ר (מחוזי ת\"א) 1710-09 אשיש דיאמונדס בע\"מ נ'' כונס נכסים רשמי תל אביב (12.4.2016)", "ע\"א 1776/97 אאורליה ליבוביץ – בית מלאכה לתפירה נ'' גדעון אוברזון – תעשיות אופנה (1976) בע\"מ, נד(3) 49 (2.7.2000)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שמעון רשאי לעכב את הציוד מכוח סעיף 5 לחוק חוזה קבלנות, התשל"ד-1974, שכן הציוד נמסר לו לביצוע מלאכתו.', false, 'טענה זו שגויה. סעיף 5 לחוק חוזה קבלנות מאפשר לקבלן לעכב נכס של המזמין שנמסר לו לביצוע מלאכתו, אך לא ציוד שבבעלות הקבלן עצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, שמעון אינו רשאי לעכב את הציוד, שכן הציוד שייך לו ולא נמסר לו על ידי ראובן.', true, 'זוהי התשובה הנכונה. זכות העיכבון חלה רק על נכסים השייכים לחייב ונמצאים בחזקת הנושה. ציוד שבבעלות הקבלן אינו יכול להיות מושא לזכות עיכבון כנגד המזמין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, שמעון רשאי לעכב את הציוד מכוח סעיף 19 לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970, שכן ראובן הפר את החוזה.', false, 'טענה זו שגויה. סעיף 19 לחוק החוזים (תרופות) חל על נכס של המפר שקיבל הנפגע ועליו להחזירו. ציוד הקבלן אינו נכס של המפר שעל הקבלן להחזירו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שמעון אינו רשאי לעכב את הציוד, שכן זכות עיכבון חלה רק על נכסים שהושבחו על ידי הקבלן.', false, 'טענה זו שגויה. זכות העיכבון של קבלן חלה על נכס של המזמין שנמסר לו לביצוע מלאכתו, ללא קשר לשאלה אם הושבח או לא, אך היא אינה חלה על ציוד שבבעלות הקבלן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי קיום זכות עיכבון',
    2, 'מהם התנאים המצטברים העיקריים לקיומה של זכות עיכבון על פי דין?', 'שאלה זו מתמקדת בתנאים המצטברים הנדרשים לקיומה של זכות עיכבון על פי דין, כפי שהם עולים מחוק המיטלטלין ומחוקים ספציפיים נוספים. התנאים כוללים קיום חוב, חזקה כדין בנכס של החייב, וזיקה מספקת בין החוב לנכס.', 'זכות העיכבון מוגדרת בסעיף 11(א) לחוק המיטלטלין, התשל"א-1971, כ"זכות על פי דין לעכב מיטלטלין כערובה לחיוב עד שיסולק החוב". הפסיקה והספרות המשפטית מפרטות את התנאים המצטברים לקיומה של זכות עיכבון על פי דין: 1. קיום חוב כספי שהגיע מועד פירעונו. 2. חזקה פיזית בנכס של החייב. 3. החזקה בנכס הושגה כדין. 4. קיומה של זיקה (קשר) בין החוב לנכס המעוכב. הזיקה הנדרשת משתנה בין סוגי העיכבונות השונים (למשל, סעיף 19 לחוק החוזים (תרופות) דורש שהנכס התקבל ''עקב החוזה'', בעוד שסעיף 5 לחוק חוזה קבלנות דורש שהנכס נמסר ''לביצוע מלאכתו''). ראו ת"א (שלום ת"א) 16725-04-24 גרין הום צמחים לכל החיים בע"מ נ'' תנופורט (1990) בע"מ (11.7.2024), ע"א 6492/00 שלדות מפעלי מתכת בע"מ נ'' מאזן אמין שחיבר (19.8.2002), וכן רע"א 7204/18 אריגים תוצרת ארצנו בע"מ נ'' עוה"ד מור נרדיה וליזה חדש - בתפקידם כנאמנים ‏זמניים (13.5.2019).',
    'התעלמות מאחד התנאים המצטברים, במיוחד דרישת הזיקה בין החוב לנכס או שהחזקה בנכס הושגה כדין.', '["זכות עיכבון", "חוק המיטלטלין", "חזקה כדין", "חוב שהגיע מועד פירעונו", "זיקה בין החוב לנכס", "סעד עצמי"]'::jsonb, '**וריאציה 1 — תנאי יסוד:** מהם שלושת התנאים העיקריים לזכות עיכבון? ← חוב, חזקה כדין בנכס של החייב, וזיקה בין החוב לנכס (ת"א גרין הום).
**וריאציה 2 — חזקה בנכס:** האם חזקה בנכס חייבת להיות פיזית? ← כן, לזכות העיכבון אופי פוססורי (ע"א שלדות מפעלי מתכת).
**וריאציה 3 — זיקה בין החוב לנכס:** מהי הזיקה הנדרשת בסעיף 19 לחוק התרופות? ← שהנכס התקבל ''עקב החוזה'' (רע"א אריגים תוצרת ארצנו).
**וריאציה 4 — מועד פירעון החוב:** האם חוב שטרם הגיע מועד פירעונו יכול להקים זכות עיכבון? ← לא, החוב צריך להיות בר פירעון (ת"א כהן צבי יזמות).', 'זכות עיכבון ← חוב בר פירעון + חזקה כדין בנכס החייב + זיקה בין החוב לנכס.',
    '["חוק המיטלטלין, תשל\"א-1971: סע'' 11(א)", "ת\"א (שלום ת\"א) 16725-04-24 גרין הום צמחים לכל החיים בע\"מ נ'' תנופורט (1990) בע\"מ (11.7.2024)", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (19.8.2002)", "רע\"א 7204/18 אריגים תוצרת ארצנו בע\"מ נ'' עוה\"ד מור נרדיה וליזה חדש - בתפקידם כנאמנים ‏זמניים (13.5.2019)", "ת\"א (שלום ת\"א) 56938-12-19 כהן צבי יזמות והשקעות בע\"מ נ'' אליהו נדל (17.3.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'קיום חוב כספי, חזקה בנכס של החייב, והסכמה מפורשת של הצדדים על זכות העיכבון.', false, 'טענה זו שגויה. הסכמה מפורשת נדרשת לעיכבון הסכמי, אך לא לעיכבון על פי דין. בנוסף, נדרשת זיקה בין החוב לנכס.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיום חוב כספי שהגיע מועד פירעונו, חזקה פיזית בנכס של החייב, והיעדר ויתור על זכות העיכבון.', false, 'טענה זו שגויה. למרות שאלו תנאים חשובים, חסר התנאי המהותי של זיקה בין החוב לנכס, וכן שהחזקה בנכס הושגה כדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'קיום חוב כספי שהגיע מועד פירעונו, חזקה פיזית בנכס של החייב שהושגה כדין, וזיקה בין החוב לנכס המעוכב.', true, 'זוהי התשובה הנכונה. אלו הם התנאים המצטברים העיקריים שנקבעו בפסיקה לקיומה של זכות עיכבון על פי דין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'קיום חוב כספי, חזקה בנכס של החייב, והשבחת הנכס על ידי הנושה.', false, 'טענה זו שגויה. השבחת הנכס היא שיקול רלוונטי לעדיפות העיכבון על פני שעבודים אחרים, אך אינה תנאי הכרחי לקיומה של זכות העיכבון עצמה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פקיעת זכות עיכבון',
    3, 'ראובן, קבלן שיפוצים, עיכב ציוד של מזמין העבודה, שמעון, בגין חוב שלא שולם. לאחר מספר שבועות, ראובן הסכים לשחרר את הציוד לשמעון באופן זמני, לצורך שימוש חד פעמי, והציוד הוחזר לשמעון. האם זכות העיכבון של ראובן פקעה?', 'שאלה זו עוסקת באחד התנאים המהותיים ביותר לזכות העיכבון – החזקה בנכס. היא בוחנת את הוראת סעיף 11(ד) לחוק המיטלטלין, הקובעת כי אובדן חזקה מרצון בנכס המעוכב מפקיע את זכות העיכבון, בשל אופיה הפוססורי של הזכות.', 'זכות העיכבון היא זכות בעלת אופי פוססורי, כלומר היא תלויה בקיומה של חזקה פיזית בנכס המעוכב. סעיף 11(ד) לחוק המיטלטלין, התשל"א-1971, קובע במפורש כי "הוציא הנושה ברצונו את המיטלטלין המעוכבים משליטתו, יפקע העיכבון". משמעות הדבר היא שברגע שהנושה מוציא את הנכס מרשותו מרצון, גם אם באופן זמני או לצורך מסוים, זכות העיכבון פוקעת. היא אינה מושעית ואינה קמה לתחייה אוטומטית עם החזרת הנכס. לכן, במקרה זה, כאשר ראובן הסכים לשחרר את הציוד לשמעון, זכות העיכבון שלו פקעה. ראו ע"א 6492/00 שלדות מפעלי מתכת בע"מ נ'' מאזן אמין שחיבר (19.8.2002), וכן ע"א 79/89 סולל בונה בע"מ נ'' אחים גולדשטיין חברה לשיכון ופיתוח בע"מ (בפירוק) (3.5.1992).',
    'הנחה שגויה כי שחרור זמני או מוסכם של הנכס אינו מפקיע את זכות העיכבון, או בלבול בין השעיה לפקיעה.', '["זכות עיכבון", "חוק המיטלטלין", "חזקה", "פקיעת עיכבון", "אופי פוססורי", "סעיף 11(ד) לחוק המיטלטלין"]'::jsonb, '**וריאציה 1 — אובדן חזקה מרצון:** אם הנושה משחרר את הנכס מרצונו, מה קורה לזכות העיכבון? ← פוקעת (סעיף 11(ד) לחוק המיטלטלין).
**וריאציה 2 — אופי פוססורי:** מהו המאפיין המרכזי של זכות העיכבון? ← אופי פוססורי, כלומר תלויה בחזקה רציפה (ע"א שלדות מפעלי מתכת).
**וריאציה 3 — שחרור זמני:** האם שחרור זמני של הנכס מפקיע את העיכבון? ← כן, כל הוצאה מרצון מפקיעה (ע"א סולל בונה).
**וריאציה 4 — חזרה לחזקה:** האם חזרה לחזקה לאחר פקיעה מקימה את העיכבון מחדש? ← לא, אלא אם קמה עילה חדשה (ע"א שלדות מפעלי מתכת).', 'זכות עיכבון ← תלויה בחזקה ← אובדן חזקה מרצון ← פקיעת העיכבון.',
    '["חוק המיטלטלין, תשל\"א-1971: סע'' 11(ד)", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (19.8.2002)", "ע\"א 79/89 סולל בונה בע\"מ נ'' אחים גולדשטיין חברה לשיכון ופיתוח בע\"מ (בפירוק), מו(3) 058 (3.5.1992)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, זכות העיכבון לא פקעה, שכן השחרור היה זמני ובהסכמה.', false, 'טענה זו שגויה. סעיף 11(ד) לחוק המיטלטלין קובע כי הוצאת הנכס מרצון משליטת הנושה מפקיעה את העיכבון, גם אם השחרור זמני.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, זכות העיכבון פקעה, שכן הוצאת המיטלטלין מרצון משליטת הנושה מפקיעה את העיכבון.', true, 'זוהי התשובה הנכונה. סעיף 11(ד) לחוק המיטלטלין קובע במפורש כי הוצאת המיטלטלין המעוכבים מרצון משליטת הנושה מפקיעה את העיכבון, שכן זכות העיכבון היא בעלת אופי פוססורי (מבוססת על חזקה).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, זכות העיכבון לא פקעה, אלא הושעתה, והיא תשוב לתוקפה עם החזרת הציוד לראובן.', false, 'טענה זו שגויה. זכות העיכבון אינה מושעית אלא פוקעת עם אובדן החזקה מרצון, ואינה קמה לתחייה אוטומטית עם החזרת הנכס.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, זכות העיכבון פקעה, אך ראובן יכול להקים אותה מחדש אם יתפוס את הציוד שוב.', false, 'טענה זו שגויה. תפיסה מחודשת של הציוד לא תקים זכות עיכבון מחדש על בסיס החוב הישן, אלא אם כן קמה עילה חדשה לעיכבון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'עיכבון מול קיזוז',
    4, 'מהו ההבדל העיקרי בין זכות עיכבון לבין זכות קיזוז, בהקשר של סעד עצמי?', 'שאלה זו עורכת השוואה בין שני סעדים עצמיים מרכזיים בדיני החוזים והקניין: זכות עיכבון וזכות קיזוז. היא מדגישה את ההבדלים המהותיים ביניהם, בעיקר באופיים המשפטי (קנייני מול אובליגטורי) ובאופן הפעלתם.', 'זכות העיכבון (Lien) היא זכות קניינית המאפשרת לנושה להחזיק בנכס של החייב הנמצא ברשותו כדין, כאמצעי לחץ להבטחת פירעון חוב שהגיע מועד פירעונו. היא אינה מאפשרת לנושה לממש את הנכס, אלא רק לעכב את מסירתו. לעומתה, זכות הקיזוז (Set-off) היא זכות אובליגטורית המאפשרת לצדדים החבים זה לזה חובות כספיים לסלק אותם באופן הדדי, עד לגובה החוב הנמוך מביניהם. הקיזוז מביא לפקיעת החובות באופן חלקי או מלא. בעוד שעיכבון דורש חזקה בנכס, קיזוז עוסק אך ורק בחובות כספיים. שתי הזכויות הן סעדים עצמיים, אך אופיין ותחולתן שונים. ראו בש"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל (24.10.2023), ת"א (שלום ת"א) 56938-12-19 כהן צבי יזמות והשקעות בע"מ נ'' אליהו נדל (17.3.2024), וכן ת"א (שלום חי'') 13633-07-16 חביב נג''יב חאג'' נ'' עיזבון המנוח בשארה ג''אד חאג'' ז"ל (20.4.2022).',
    'בלבול בין זכות עיכבון לזכות קיזוז, או אי-הבנה של האופי הקנייני של העיכבון לעומת האופי האובליגטורי של הקיזוז.', '["זכות עיכבון", "זכות קיזוז", "סעד עצמי", "זכות קניינית", "זכות אובליגטורית", "חזקה", "חוק החוזים (חלק כללי)", "חוק המיטלטלין"]'::jsonb, '**וריאציה 1 — אופי הזכות:** מהו האופי המשפטי של עיכבון לעומת קיזוז? ← עיכבון קנייני (החזקה בנכס), קיזוז אובליגטורי (סילוק חובות) (בש"פ בנק לאומי, ת"א כהן צבי).
**וריאציה 2 — דרישת חזקה:** האם קיזוז דורש חזקה בנכס? ← לא, רק עיכבון (ת"א חביב נג''יב).
**וריאציה 3 — מטרת הזכות:** מהי מטרת העיכבון לעומת הקיזוז? ← עיכבון: לחץ לפירעון חוב באמצעות החזקה בנכס. קיזוז: סילוק חובות הדדיים (ת"א כהן צבי, ת"א חביב נג''יב).
**וריאציה 4 — מימוש הנכס:** האם עיכבון מאפשר מימוש הנכס? ← לא, רק החזקה. קיזוז מסלק את החובות (בש"פ בנק לאומי).', 'עיכבון ← זכות קניינית, החזקה בנכס. קיזוז ← זכות אובליגטורית, סילוק חובות.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973: סע'' 53(א)", "חוק המיטלטלין, תשל\"א-1971: סע'' 11", "בש\"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל (24.10.2023)", "ת\"א (שלום ת\"א) 56938-12-19 כהן צבי יזמות והשקעות בע\"מ נ'' אליהו נדל (17.3.2024)", "ת\"א (שלום חי'') 13633-07-16 חביב נג''יב חאג'' נ'' עיזבון המנוח בשארה ג''אד חאג'' ז\"ל (20.4.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'זכות עיכבון היא זכות קניינית המאפשרת החזקה בנכס, בעוד שזכות קיזוז היא זכות אובליגטורית המאפשרת סילוק הדדי של חובות כספיים.', true, 'זוהי התשובה הנכונה. ההבחנה המרכזית היא בין אופי קנייני (עיכבון) לאופי אובליגטורי (קיזוז), ובהתאם לכך, עיכבון עוסק בהחזקת נכס וקיזוז בסילוק חובות כספיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'זכות עיכבון דורשת הסכמה מפורשת של הצדדים, בעוד שזכות קיזוז קמה מכוח דין בלבד.', false, 'טענה זו שגויה. זכות עיכבון יכולה לקום גם מכוח דין, וזכות קיזוז יכולה לקום גם מכוח הסכם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'זכות עיכבון מאפשרת מימוש הנכס המעוכב, בעוד שזכות קיזוז אינה מאפשרת זאת.', false, 'טענה זו שגויה. זכות עיכבון אינה מאפשרת מימוש הנכס, אלא רק החזקה בו כאמצעי לחץ. זכות קיזוז, לעומת זאת, מסלקת חובות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'זכות קיזוז חלה רק על חובות קצובים, בעוד שזכות עיכבון חלה על כל סוגי החובות.', false, 'טענה זו שגויה. זכות קיזוז יכולה לחול גם על חובות לא קצובים אם הם נובעים מאותה עסקה. זכות עיכבון חלה על חובות שהגיע מועד פירעונם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 5, '2022-W-S-Q05';
END
$$;

