  v_ang_0 uuid := '7ae1a667-c2e9-4c29-b8e7-13ad4b2738fb'::uuid;
  v_ang_1 uuid := '9f28d9e9-c2a7-49dc-9e62-aeb33785b1a8'::uuid;
  v_ang_2 uuid := 'eea0f332-000f-486e-a12b-f37729759186'::uuid;
  v_ang_3 uuid := 'd051aa83-7b17-4f56-9d6a-a8458fa5eebf'::uuid;
