  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q06', v_chapter_id, v_subtopic_id, 'הניחו באופן תאורטי כי הדין הנוגע לאחריות פלילית במצב של טעות במצב משפטי לפי סעיף 34יט לחוק העונשין תוקן כך שכל טעות כנה במצב המשפטי תפטור מאחריות פלילית. על מה תחול ההגנה לאור התיקון?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 6}'::jsonb, 'השאלה עוסקת בתחולה בזמן של שינויים בחוק העונשין, ובפרט ביצירת הגנה פלילית חדשה (טעות במצב משפטי). היא בוחנת את עקרון ה''חוק המקל'' (Lex Mitior) הקבוע בסעיף 5(א) לחוק העונשין, הקובע כי דין מקל יחול על עבירות שבוצעו לפני כניסתו לתוקף, כל עוד לא ניתן פסק דין חלוט בעניינן.', 'סעיף 5(א) לחוק העונשין, התשל"ז-1977, קובע את עקרון ה''חוק המקל'': ''נעברה עבירה, ולאחר מכן שונה החוק, יחול על הענין החוק המקל עם העושה; אולם אין בהוראה זו כדי למנוע הטלת עונש מאסר שהיה קבוע בחוק בעת ביצוע העבירה, אם העבירה היתה עבירת אלימות חמורה''. יצירת הגנה פלילית חדשה, כגון הרחבת הגנת הטעות במצב משפטי, נחשבת לשינוי מקל בדין המהותי. לכן, בהתאם לסעיף 5(א), הגנה זו תחול על כל ההליכים הפליליים שטרם הסתיימו במתן פסק דין חלוט, גם אם העבירה בוצעה לפני כניסת התיקון לתוקף. מטרת העיקרון היא למנוע ענישה בחומרה רבה יותר ממה שהחברה רואה לנכון במועד מתן פסק הדין. ראו סעיף 5 לחוק העונשין, התשל"ז-1977.', 'הטעות הנפוצה היא בלבול בין תחולת חוק מקל על הליכים שטרם חלוטים לבין תחולתו על פסקי דין חלוטים, או אי-הבחנה בין שינוי מהותי (כמו יצירת הגנה) לשינוי דיוני.',
    '["תחולת חוק בזמן", "חוק העונשין", "טעות במצב משפטי", "הגנה פלילית", "חוק מקל", "פסק דין חלוט", "סעיף 5 לחוק העונשין"]'::jsonb, '**וריאציה 1 — חוק מקל בהגנה:** חוק עונשין חדש יוצר הגנה פלילית. על אילו הליכים יחול? ← על כל ההליכים שטרם ניתן בהם פסק דין חלוט (סעיף 5(א) לחוק העונשין).
**וריאציה 2 — חוק מחמיר בהגנה:** חוק עונשין חדש מבטל הגנה פלילית. על אילו הליכים יחול? ← רק על עבירות שבוצעו לאחר כניסתו לתוקף (סעיף 5(א) לחוק העונשין).
**וריאציה 3 — שינוי דיוני:** חוק חדש משנה כלל דיוני (למשל, כלל ראיות). על אילו הליכים יחול? ← על כל ההליכים, גם אלה שהחלו לפני כניסתו לתוקף (סעיף 5(ב) לחוק העונשין).
**וריאציה 4 — פסק דין חלוט:** האם חוק מקל חל על פסק דין חלוט? ← לא באופן אוטומטי, אלא אם מדובר בביטול העבירה כולה (סעיף 5(א) לחוק העונשין).', 'שינוי חוק עונשין מקל (כולל הגנה חדשה) ← חל על הליכים שטרם חלוטים ← סעיף 5(א) לחוק העונשין.', '["חוק העונשין, התשל\"ז-1977: סע'' 5, 34יט"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משפט חוזר'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Hypothetical reform of sec. 34יט (mistake of law) — application in time | source_review_note: הסיווג לתת-נושא ''משפט חוזר'' אינו מדויק לחלוטין, שכן השאלה עוסקת בתחולה כללית של חוק עונשין בזמן ולא רק במשפט חוזר. עם זאת, זהו התת-נושא הקרוב ביותר מתוך הרשימה הסגורה העוסק בהשפעת שינויי חוק על הליכים פליליים קיימים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על כל ההעמדות לדין ממועד תיקון החוק.', false, 'טענה זו שגויה. תיקון חוק עונשין מקל חל גם על עבירות שבוצעו לפני התיקון, כל עוד לא ניתן פסק דין חלוט.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על כל פסקי הדין החלוטים מ-7 השנים האחרונות.', false, 'טענה זו שגויה. חוק עונשין מקל אינו חל באופן אוטומטי על פסקי דין חלוטים, אלא רק על הליכים שטרם הסתיימו. פסקי דין חלוטים דורשים הליך של משפט חוזר, וגם אז לא כל שינוי בחוק יצדיק זאת.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על כל ההליכים שטרם ניתן בהם פסק דין חלוט.', true, 'זוהי התשובה הנכונה. סעיף 5(א) לחוק העונשין קובע כי אם שונה דין לאחר עשיית העבירה ולפני מתן פסק דין חלוט, יחול הדין המקל. יצירת הגנה חדשה היא שינוי מקל בדין המהותי, ולכן תחול על כל ההליכים שטרם הסתיימו בפסק דין חלוט.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על כל פסקי הדין החלוטים שטרם החל ביצוע העונש בהם.', false, 'טענה זו שגויה. חוק עונשין מקל אינו חל על פסקי דין חלוטים, גם אם ביצוע העונש טרם החל. פסק דין חלוט הוא סוף ההליך המשפטי הרגיל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחולת חוק עונשין מקל על עבירה שבוצעה',
    1, 'ראובן ביצע עבירה פלילית בשנת 2018. בשנת 2019, לפני שניתן פסק דין בעניינו, תוקן חוק העונשין והופחת העונש המקסימלי לעבירה שביצע ראובן. איזה עונש יחול על ראובן?', 'שאלה זו בוחנת את עקרון ה''חוק המקל'' (Lex Mitior) בדיני העונשין, כפי שהוא מעוגן בסעיף 5(א) לחוק העונשין. העיקרון קובע כי כאשר חוק עונשין משתנה לאחר ביצוע עבירה אך לפני מתן פסק דין חלוט, והשינוי מקל עם הנאשם (למשל, מפחית עונש), הדין המקל הוא שיחול.', 'סעיף 5(א) לחוק העונשין, התשל"ז-1977, קובע כי ''נעברה עבירה, ולאחר מכן שונה החוק, יחול על העניין החוק המקל עם העושה; אולם אין בהוראה זו כדי למנוע הטלת עונש מאסר שהיה קבוע בחוק בעת ביצוע העבירה, אם העבירה היתה עבירת אלימות חמורה''. במקרה הנדון, העונש המקסימלי הופחת לאחר ביצוע העבירה ולפני מתן פסק דין חלוט, ולכן מדובר בשינוי מקל. בהתאם לעקרון ה''חוק המקל'', בית המשפט יחיל על ראובן את העונש המופחת שנקבע בחוק המתוקן. עקרון זה מבטא את הרצון שלא להעניש אדם בחומרה רבה יותר ממה שהחברה רואה לנכון במועד מתן פסק הדין. ראו סעיף 5(א) לחוק העונשין, התשל"ז-1977.',
    'הנחה שגויה כי הדין החל הוא תמיד הדין שהיה בתוקף בעת ביצוע העבירה, ללא התחשבות בעקרון ה''חוק המקל''.', '["חוק העונשין", "תחולה בזמן", "חוק מקל", "עונש", "פסק דין חלוט", "סעיף 5(א) לחוק העונשין"]'::jsonb, '**וריאציה 1 — חוק מקל בעונש:** אם חוק חדש מפחית עונש, על אילו עבירות יחול? ← על עבירות שבוצעו לפני התיקון, כל עוד לא ניתן פסק דין חלוט (סעיף 5(א) לחוק העונשין).
**וריאציה 2 — חוק מחמיר בעונש:** אם חוק חדש מחמיר עונש, על אילו עבירות יחול? ← רק על עבירות שבוצעו לאחר כניסתו לתוקף (סעיף 5(א) לחוק העונשין).
**וריאציה 3 — עבירת אלימות חמורה:** האם יש חריג לעקרון החוק המקל בעבירות אלימות חמורות? ← כן, ניתן להטיל עונש מאסר שהיה קבוע בחוק בעת ביצוע העבירה (סעיף 5(א) סיפא לחוק העונשין).
**וריאציה 4 — מטרת העיקרון:** מהי המטרה העומדת בבסיס עקרון החוק המקל? ← למנוע ענישה בחומרה רבה יותר ממה שהחברה רואה לנכון במועד מתן פסק הדין.', 'חוק עונשין מקל ← חל רטרואקטיבית ← על הליכים שטרם חלוטים.',
    '["חוק העונשין, התשל\"ז-1977: סע'' 5(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'העונש שנקבע בחוק כפי שהיה בתוקף במועד ביצוע העבירה.', false, 'טענה זו שגויה. במקרה של חוק מקל, הדין החדש הוא שיחול, ולא הדין שהיה בתוקף בעת ביצוע העבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'העונש המופחת שנקבע בחוק המתוקן.', true, 'זוהי התשובה הנכונה. סעיף 5(א) לחוק העונשין קובע את עקרון ה''חוק המקל'', לפיו אם שונה דין לאחר עשיית העבירה ולפני מתן פסק דין חלוט, יחול הדין המקל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט יחליט לפי שיקול דעתו איזה עונש להטיל, בהתחשב בנסיבות המקרה.', false, 'טענה זו שגויה. שיקול הדעת של בית המשפט מוגבל על ידי הוראות החוק, ובמקרה של חוק מקל, חובה עליו להחיל את הדין המקל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'העונש המופחת יחול רק אם ראובן יבקש זאת מבית המשפט.', false, 'טענה זו שגויה. תחולת הדין המקל היא אוטומטית ואינה תלויה בבקשת הנאשם, שכן זהו עקרון יסוד בדיני העונשין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'עקרונות תחולת חוק עונשין בזמן',
    2, 'מהם העקרונות המנחים את תחולתו של חוק עונשין חדש בזמן, בהתאם לחוק העונשין?', 'שאלה זו עוסקת בעקרונות הכלליים של תחולת חוק עונשין בזמן, כפי שנקבעו בסעיף 5 לחוק העונשין. היא מדגישה את ההבחנה בין שינויים מהותיים (הקלה או החמרה בעונש, יצירת או ביטול עבירה/הגנה) לבין שינויים דיוניים (כללי ראיות, סדרי דין), ואת כללי התחולה השונים לכל אחד מהם.', 'סעיף 5 לחוק העונשין, התשל"ז-1977, קובע את הכללים לתחולת חוק עונשין בזמן. סעיף 5(א) קובע כי אם שונה דין לאחר עשיית העבירה ולפני מתן פסק דין חלוט, יחול הדין המקל עם העושה (עקרון ה''חוק המקל''). אם הדין מחמיר, הוא יחול רק על עבירות שבוצעו לאחר כניסתו לתוקף. אם החוק החדש מבטל את העבירה, לא ייענש עליה איש. סעיף 5(ב) קובע כי ''על ענין שבסדרי דין וראיות יחול הדין שהיה קיים ביום הדיון''. כלומר, שינויים דיוניים חלים באופן מיידי, גם על הליכים שהחלו לפני כניסתם לתוקף. העקרונות הללו מבטיחים הגנה על זכויות הנאשם ומאזנים בין עקרון החוקיות לבין עקרונות של צדק והגינות. ראו סעיף 5 לחוק העונשין, התשל"ז-1977.',
    'אי-הבחנה בין דין מהותי לדין דיוני, ובין חוק מקל לחוק מחמיר, והחלת כלל אחיד על כל סוגי השינויים בחוק העונשין.', '["תחולת חוק בזמן", "חוק העונשין", "חוק מקל", "חוק מחמיר", "דין מהותי", "דין דיוני", "פסק דין חלוט", "סעיף 5 לחוק העונשין"]'::jsonb, '**וריאציה 1 — שינוי מהותי מקל:** אם חוק עונשין חדש מקל (עונש, הגנה, ביטול עבירה), מתי יחול? ← רטרואקטיבית, על הליכים שטרם חלוטים (סעיף 5(א) לחוק העונשין).
**וריאציה 2 — שינוי מהותי מחמיר:** אם חוק עונשין חדש מחמיר, מתי יחול? ← פרוספקטיבית, רק על עבירות שבוצעו לאחר כניסתו לתוקף (סעיף 5(א) לחוק העונשין).
**וריאציה 3 — שינוי דיוני:** אם חוק חדש משנה כלל דיוני (למשל, סדרי דין או ראיות), מתי יחול? ← באופן מיידי, על כל ההליכים, גם אלה שהחלו לפני כניסתו לתוקף (סעיף 5(ב) לחוק העונשין).
**וריאציה 4 — ביטול עבירה:** אם חוק חדש מבטל עבירה, מה דין מי שביצע אותה לפני הביטול? ← לא ייענש עליה איש (סעיף 5(א) לחוק העונשין).', 'תחולת חוק עונשין בזמן ← מקל רטרואקטיבי, מחמיר פרוספקטיבי, דיוני מיידי.',
    '["חוק העונשין, התשל\"ז-1977: סע'' 5"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'חוק עונשין חדש חל תמיד באופן פרוספקטיבי (קדימה), למעט אם נקבע אחרת במפורש בחוק.', false, 'טענה זו שגויה. עקרון ה''חוק המקל'' מהווה חריג מפורש לתחולה פרוספקטיבית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'חוק עונשין חדש מקל חל רטרואקטיבית, וחוק עונשין חדש מחמיר חל פרוספקטיבית, ואילו שינויים דיוניים חלים באופן מיידי.', true, 'זוהי התשובה הנכונה. סעיף 5 לחוק העונשין מבחין בין שינויים מהותיים (מקל/מחמיר) לבין שינויים דיוניים, וקובע כללים שונים לתחולתם בזמן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כל שינוי בחוק העונשין חל תמיד באופן רטרואקטיבי (אחורה), על כל העבירות שבוצעו לפני התיקון.', false, 'טענה זו שגויה. חוק עונשין מחמיר אינו חל רטרואקטיבית, וגם חוק מקל חל רק על הליכים שטרם חלוטים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הדין החל הוא תמיד הדין שהיה בתוקף במועד ביצוע העבירה, ללא קשר לשינויים מאוחרים.', false, 'טענה זו שגויה. עקרון ה''חוק המקל'' סותר טענה זו, וגם שינויים דיוניים חלים באופן מיידי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'טעות במצב משפטי כהגנה',
    3, 'ראובן, אזרח שומר חוק, ביצע פעולה מסוימת לאחר שקיבל ייעוץ משפטי מעורך דין מוסמך, לפיו הפעולה מותרת. בדיעבד התברר כי הייעוץ היה שגוי, והפעולה מהווה עבירה פלילית. האם ראובן יוכל לטעון להגנת טעות במצב משפטי לפי סעיף 34יט לחוק העונשין (לפני התיקון התיאורטי שבשאלה המקורית)?', 'שאלה זו בוחנת את היקף תחולתה של הגנת טעות במצב משפטי לפי סעיף 34יט לחוק העונשין, לפני התיקון התיאורטי. היא מדגישה את הכלל הבסיסי ''בורות החוק אינה פוטרת'' ואת הפרשנות המצמצמת של ההגנה, הדורשת שהטעות תהיה בלתי נמנעת באורח סביר.', 'סעיף 34יט לחוק העונשין, התשל"ז-1977, קובע כי ''לעניין אחריות פלילית, אין נפקא מינה אם האדם דימה שהמעשה אסור, אלא אם כן הטעות היתה בלתי נמנעת באורח סביר ולא ניתן היה למנוע אותה''. כלל זה מבטא את העיקרון ''בורות החוק אינה פוטרת'' (Ignorantia juris non excusat). הפסיקה פירשה את סעיף 34יט בצמצום רב, וקבעה כי הגנה זו חלה רק במקרים נדירים וחריגים ביותר, כאשר הטעות היא כה מהותית ובלתי צפויה עד שלא ניתן היה למנוע אותה בשום דרך סבירה. הסתמכות על ייעוץ משפטי שגוי, גם אם מעורך דין מוסמך, אינה נחשבת בדרך כלל לטעות ''בלתי נמנעת באורח סביר'', שכן מצופה מאדם לנקוט בזהירות יתרה ולוודא את חוקיות מעשיו, ובמקרים רבים ניתן היה לקבל חוות דעת נוספת או לפנות לרשויות. לכן, במקרה זה, ראובן לא יוכל לטעון בהצלחה להגנה זו. ראו סעיף 34יט לחוק העונשין, התשל"ז-1977, וכן ע"פ 2831/95 אלבה נ'' מדינת ישראל, נ(1) 221 (19.12.1996).',
    'הנחה שגויה כי הסתמכות על ייעוץ משפטי שגוי מהווה הגנה מספקת לפי סעיף 34יט, או אי-הבנה של הפרשנות המצמצמת של ההגנה.', '["טעות במצב משפטי", "חוק העונשין", "הגנה פלילית", "בורות החוק אינה פוטרת", "סעיף 34יט לחוק העונשין", "טעות בלתי נמנעת באורח סביר"]'::jsonb, '**וריאציה 1 — הסתמכות על ייעוץ שגוי:** האם הסתמכות על ייעוץ משפטי שגוי מהווה הגנה לפי סעיף 34יט? ← לרוב לא, הטעות אינה ''בלתי נמנעת באורח סביר'' (ע"פ אלבה).
**וריאציה 2 — תנאי ההגנה:** מהם התנאים לתחולת הגנת טעות במצב משפטי? ← הטעות הייתה בלתי נמנעת באורח סביר ולא ניתן היה למנוע אותה (סעיף 34יט לחוק העונשין).
**וריאציה 3 — בורות החוק:** מהו הכלל הבסיסי לגבי בורות החוק? ← בורות החוק אינה פוטרת מאחריות פלילית (Ignorantia juris non excusat).
**וריאציה 4 — פרשנות מצמצמת:** כיצד מפרשת הפסיקה את סעיף 34יט? ← בצמצום רב, למקרים נדירים וחריגים ביותר (ע"פ אלבה).', 'טעות במצב משפטי ← הגנה צרה מאוד ← טעות בלתי נמנעת באורח סביר ← בורות החוק אינה פוטרת.',
    '["חוק העונשין, התשל\"ז-1977: סע'' 34יט", "ע\"פ 2831/95 אלבה נ'' מדינת ישראל, נ(1) 221 (19.12.1996)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן טעותו הייתה כנה וסבירה, והוא הסתמך על ייעוץ מקצועי.', false, 'טענה זו שגויה. סעיף 34יט דורש שהטעות תהיה בלתי נמנעת באורח סביר, והסתמכות על ייעוץ משפטי שגוי אינה עומדת בדרך כלל ברף מחמיר זה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן בורות החוק אינה פוטרת מאחריות פלילית, וסעיף 34יט חל רק במקרים נדירים וחריגים ביותר.', true, 'זוהי התשובה הנכונה. סעיף 34יט לחוק העונשין מפרש את הכלל ''בורות החוק אינה פוטרת'' וקובע הגנה צרה מאוד, הדורשת שהטעות תהיה בלתי נמנעת באורח סביר ולא ניתן היה למנוע אותה. הסתמכות על ייעוץ משפטי שגוי אינה נחשבת בדרך כלל לטעות בלתי נמנעת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם יוכיח כי עורך הדין שנתן את הייעוץ היה מומחה בתחום המשפטי הרלוונטי.', false, 'טענה זו שגויה. מומחיות עורך הדין אינה משנה את העובדה שהטעות לא הייתה בלתי נמנעת באורח סביר, וכי ראובן יכול היה לנקוט בצעדים נוספים לוודא את חוקיות הפעולה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן עורך הדין שנתן את הייעוץ הורשע בעצמו בעבירה פלילית בגין הייעוץ השגוי.', false, 'טענה זו שגויה. אחריותו הפלילית של עורך הדין אינה תנאי לתחולת הגנת הטעות במצב משפטי של ראובן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השפעת ביטול חוק על הליכים',
    4, 'ראובן הורשע בעבירה פלילית ונגזר עליו עונש מאסר. לאחר שפסק הדין הפך חלוט, אך לפני שראובן החל לרצות את עונשו, בוטל החוק שעל פיו הורשע, והמעשה שביצע אינו מהווה עוד עבירה פלילית. מה הדין?', 'שאלה זו עוסקת בהשפעה הדרמטית של ביטול חוק עונשין על אחריות פלילית, כולל על פסקי דין חלוטים. היא מדגישה את העיקרון לפיו אין להעניש אדם על מעשה שאינו מהווה עוד עבירה פלילית, גם אם הורשע בו בעבר, וזאת מכוח סעיף 5(א) לחוק העונשין.', 'סעיף 5(א) לחוק העונשין, התשל"ז-1977, קובע כי ''אם החוק החדש מבטל את העבירה, לא ייענש עליה איש''. עיקרון זה חל גם כאשר פסק הדין חלוט, שכן אין טעם להמשיך ולהעניש אדם על מעשה שאינו נחשב עוד לעבירה פלילית בעיני החברה. במקרה כזה, העונש יבוטל, וראובן לא ירצה את המאסר. זהו מקרה קיצוני של ''חוק מקל'' שבו המעשה עצמו הוצא מחוץ לגדר העבירות הפליליות. אין צורך בהליך של משפט חוזר, שכן ביטול העבירה הוא שינוי מהותי בחוק המבטל את עצם האחריות הפלילית. ראו סעיף 5(א) לחוק העונשין, התשל"ז-1977.',
    'הנחה שגויה כי פסק דין חלוט הוא סופי ובלתי ניתן לשינוי בכל מקרה, גם כאשר החוק שעל פיו ניתנה ההרשעה בוטל לחלוטין.', '["ביטול חוק", "עבירה פלילית", "פסק דין חלוט", "תחולת חוק בזמן", "חוק העונשין", "סעיף 5(א) לחוק העונשין"]'::jsonb, '**וריאציה 1 — ביטול עבירה לפני פסק דין חלוט:** אם עבירה בוטלה לפני פסק דין חלוט, מה דין הנאשם? ← לא ייענש עליה איש (סעיף 5(א) לחוק העונשין).
**וריאציה 2 — ביטול עבירה לאחר פסק דין חלוט:** אם עבירה בוטלה לאחר פסק דין חלוט, מה דין המורשע? ← העונש יבוטל, לא ייענש (סעיף 5(א) לחוק העונשין).
**וריאציה 3 — הבדל בין ביטול להקלה:** מה ההבדל בין ביטול עבירה להקלה בעונש? ← ביטול מבטל את עצם האחריות, הקלה משנה את סנקציה (סעיף 5(א) לחוק העונשין).
**וריאציה 4 — מטרת העיקרון:** מהי המטרה העומדת בבסיס ביטול ענישה על עבירה שבוטלה? ← למנוע ענישה על מעשה שאינו נחשב עוד לעבירה בעיני החברה.', 'ביטול חוק עונשין ← מבטל אחריות פלילית ← גם בפסק דין חלוט.',
    '["חוק העונשין, התשל\"ז-1977: סע'' 5(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ראובן ירצה את עונשו כרגיל, שכן פסק הדין חלוט ואין לו השפעה רטרואקטיבית.', false, 'טענה זו שגויה. ביטול חוק המגדיר עבירה הוא מקרה חריג שמשפיע גם על פסקי דין חלוטים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'העונש של ראובן יבוטל, והוא לא ירצה מאסר, שכן המעשה אינו מהווה עוד עבירה פלילית.', true, 'זוהי התשובה הנכונה. סעיף 5(א) לחוק העונשין קובע כי ''אם החוק החדש מבטל את העבירה, לא ייענש עליה איש''. עיקרון זה חל גם על פסקי דין חלוטים, שכן אין טעם להעניש אדם על מעשה שאינו נחשב עוד לעבירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ראובן יוכל להגיש בקשה למשפט חוזר, ובית המשפט יבחן את נסיבות המקרה.', false, 'טענה זו שגויה. במקרה של ביטול מוחלט של העבירה, אין צורך בהליך של משפט חוזר, אלא העונש מתבטל באופן ישיר מכוח החוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'העונש של ראובן יופחת, אך הוא עדיין ירצה חלק ממנו.', false, 'טענה זו שגויה. ביטול העבירה אינו הפחתת עונש, אלא ביטול מוחלט של האחריות הפלילית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 6, '2022-W-S-Q06';
END
$$;

