-- classifier_note: Res ipsa loquitur — 'הדבר מעיד על עצמו' interpretation
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '862f7b43-8562-4e5c-9bb1-42cc49b910f2'::uuid;
  v_group_id uuid := 'c6bb25b8-6f28-4bce-a72c-aeb688cf5032'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '44bf145a-c908-4c96-8f87-e6af4e4962ac'::uuid;
  v_ang_1 uuid := 'a799942f-9a07-4edd-afdb-9850d4972811'::uuid;
  v_ang_2 uuid := '087f3333-6333-43e7-b3c1-48ce7573feb0'::uuid;
  v_ang_3 uuid := '19042e28-d531-4a01-a374-545a9b821e08'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q07';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 7, '2022-W-S-Q07';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'negligence' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'negligence', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q07', v_chapter_id, v_subtopic_id, 'אחד התנאים לשימוש בכלל המשפטי של "הדבר מעיד על עצמו" הוא "כי לתובע לא הייתה ידיעה או לא הייתה לו יכולת לדעת מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק". מבין הבאים מהו הפירוש הנכון ביותר של התנאי?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 7}'::jsonb, 'השאלה עוסקת בכלל "הדבר מעיד על עצמו" (Res Ipsa Loquitur) הקבוע בסעיף 41 לפקודת הנזיקין, ובפרט בפרשנות התנאי הראשון שלו, הדורש "אי-ידיעה או חוסר יכולת לדעת" את נסיבות גרימת הנזק. בית המשפט העליון קבע כי תנאי זה מתמקד בעמימות אובייקטיבית בסיום ההליך המשפטי, ולא בידיעתו הסובייקטיבית של הניזוק בעת האירוע.', 'סעיף 41 לפקודת הנזיקין [נוסח חדש] קובע שלושה תנאים מצטברים להחלת כלל "הדבר מעיד על עצמו", המעביר את נטל השכנוע לנתבע. התנאי הראשון הוא "כי לתובע לא הייתה ידיעה או לא הייתה לו יכולת לדעת מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק". הפסיקה, ובפרט פסק הדין ברע"א 7002/17 פלוני נ'' פלוני, הבהירה כי פרשנות תנאי זה אינה מתמקדת בידיעתו הסובייקטיבית של הניזוק בעת התרחשות הנזק, אלא ב"עמימות האובייקטיבית" שנותרה לגבי נסיבות האירוע בסיום ההליך המשפטי. כלומר, המועד הרלוונטי לבחינת אי-הידיעה הוא מועד הדיון המשפטי, והכלל יופעל "מקום בו נותרו פרטי ההתרחשות המזיקה עלומים גם במהלך המשפט". אם עד תום המשפט נסיבות המקרה התבררו, אין מקום להחלת הכלל. לכן, הפירוש הנכון ביותר הוא שאין אפשרות לדעת בסיום ההליך המשפטי מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק. ראו סעיף 41 לפקודת הנזיקין [נוסח חדש], וכן רע"א 7002/17 פלוני נ'' פלוני (21.5.2018).', 'הטעות הנפוצה היא בלבול בין ידיעתו הסובייקטיבית של הניזוק בעת האירוע לבין העמימות האובייקטיבית בסיום ההליך המשפטי, וכן אי-הבנה של המועד הרלוונטי לבחינת תנאי אי-הידיעה.',
    '["הדבר מעיד על עצמו", "פקודת הנזיקין", "אי-ידיעה", "עמימות עובדתית", "נטל ההוכחה", "מועד בחינת הידיעה", "רע\"א 7002/17"]'::jsonb, '**וריאציה 1 — מועד בחינת הידיעה:** מתי נבחנת אי-הידיעה של התובע? ← בסיום ההליך המשפטי, אם נותרה עמימות עובדתית (רע"א 7002/17).
**וריאציה 2 — ידיעת הניזוק:** האם ידיעת הניזוק בעת האירוע שוללת את הכלל? ← לא בהכרח, אם התובע (יורשיו) אינו יודע בסיום המשפט (רע"א 7002/17).
**וריאציה 3 — עמימות אובייקטיבית:** מהי מהות תנאי אי-הידיעה? ← דרישה לקיומה של עמימות עובדתית אובייקטיבית (רע"א 7002/17).
**וריאציה 4 — תובע שיכול להביא ראיות:** אם התובע יכול להביא ראיות ולא עושה כן, האם הכלל יחול? ← לא, כי אז לא מתקיים התנאי הראשון (רע"א 7002/17).', 'תנאי אי-הידיעה ב"הדבר מעיד על עצמו" ← עמימות אובייקטיבית ← נבחן בסיום ההליך המשפטי.', '["פקודת הנזיקין [נוסח חדש]: סע'' 41", "רע\"א 7002/17 פלוני נ'' פלוני (21.5.2018)", "ע\"א (מחוזי נצ'') 1078/06 עזבון המנוח יעקב בירג נ'' אנואר סלימאן (13.3.2007)", "ת\"ק (תביעות קטנות נת'') 24006-11-19 מרק קוניס נ'' סיוון אופיר סחר בע\"מ (23.11.2020)", "ת\"א (מחוזי חי'') 52288-01-11 פלוני נ'' קיבוץ אלונים (27.4.2017)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Res ipsa loquitur — ''הדבר מעיד על עצמו'' interpretation', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הניזוק עצמו לא ידע או לא הייתה לו יכולת לדעת בעת התרחשות המקרה מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק.', false, 'טענה זו שגויה. הפסיקה קבעה כי אי-הידיעה אינה נבחנת ביחס לידיעתו הסובייקטיבית של הניזוק בעת התרחשות המקרה, אלא מתמקדת בעמימות אובייקטיבית בסיום ההליך המשפטי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התובע בהליך המשפטי לא ידע או לא הייתה לו יכולת לדעת בעת התרחשות המקרה מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק.', false, 'טענה זו שגויה. המועד הרלוונטי לבחינת אי-הידיעה הוא מועד הדיון המשפטי, אך לא נבחנת ידיעת התובע בעת התרחשות המקרה, אלא העמימות האובייקטיבית בסיום ההליך.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אין אפשרות לדעת בסיום ההליך המשפטי מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק.', true, 'זוהי התשובה הנכונה. בית המשפט העליון קבע כי התנאי הראשון מתמקד בעמימות אובייקטיבית, וכי המועד הרלוונטי לבחינת אי-הידיעה הוא מועד הדיון המשפטי, כלומר, אם נותרו פרטי ההתרחשות המזיקה עלומים גם במהלך המשפט.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אין אפשרות לדעת בעת התרחשות הנזק מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק.', false, 'טענה זו שגויה. המועד הקובע לבחינת אי-הידיעה הוא מועד הדיון המשפטי, ולא מועד התרחשות הנזק. גם אם הניזוק ידע בזמן אמת, אם נותרה עמימות אובייקטיבית בסיום המשפט, התנאי יכול להתקיים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'יישום כלל "הדבר מעיד על עצמו" בתאונת דרכים',
    1, 'רכבו של ראובן חנה בחניון סגור השייך לחברת "חניוני העיר בע"מ". כאשר חזר ראובן לרכבו, גילה נזק משמעותי בחלקו האחורי, אך לא היו עדים לאירוע והוא אינו יודע כיצד נגרם הנזק. חברת החניונים אחראית על אבטחת החניון ותחזוקתו. האם ראובן יכול להסתמך על כלל "הדבר מעיד על עצמו" כדי להעביר את נטל ההוכחה לחברת החניונים?', 'שאלה זו בוחנת את יישום כלל "הדבר מעיד על עצמו" במקרה קונקרטי של נזק לרכב בחניון. היא מדגישה את הצורך בקיום שלושת התנאים המצטברים של סעיף 41 לפקודת הנזיקין, ובפרט את פרשנות תנאי אי-הידיעה כעמימות אובייקטיבית בסיום ההליך המשפטי.', 'כלל "הדבר מעיד על עצמו" הקבוע בסעיף 41 לפקודת הנזיקין [נוסח חדש] חל בהתקיים שלושה תנאים מצטברים: 1. לתובע לא הייתה ידיעה או לא הייתה לו יכולת לדעת מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק. תנאי זה מתפרש כדרישה לקיומה של עמימות עובדתית בסיום ההליך המשפטי, ולא בידיעת הניזוק בעת האירוע. במקרה זה, ראובן אינו יודע כיצד נגרם הנזק לרכבו, ובהיעדר ראיות אחרות, עמימות זו יכולה להתקיים. 2. הנזק נגרם על ידי נכס שלנתבע הייתה שליטה מלאה עליו. חניון סגור, על מתקניו ואבטחתו, נחשב לנכס שבשליטת חברת החניונים. 3. נראה לבית המשפט שאירוע המקרה שגרם לנזק מתיישב יותר עם המסקנה שהנתבע לא נקט זהירות סבירה מאשר עם המסקנה שהוא נקט זהירות סבירה. נזק לרכב בחניון מאובטח, ללא עדים, יכול להתיישב יותר עם רשלנות של החברה באבטחה או בתחזוקה. אם שלושת התנאים מתקיימים, נטל השכנוע עובר לחברת החניונים להוכיח שלא התרשלה. ראו סעיף 41 לפקודת הנזיקין [נוסח חדש], וכן רע"א 7002/17 פלוני נ'' פלוני (21.5.2018).',
    'הנחה שגויה כי היעדר עדים או חוסר ידיעה סובייקטיבית מספיקים, מבלי לבחון את העמימות האובייקטיבית בסיום המשפט ואת שאר התנאים.', '["הדבר מעיד על עצמו", "פקודת הנזיקין", "נטל ההוכחה", "עמימות עובדתית", "שליטה בנכס", "התרשלות מסתברת"]'::jsonb, '**וריאציה 1 — נזק בחניון:** רכב נפגע בחניון סגור, הבעלים לא יודע איך. האם חל "הדבר מעיד על עצמו"? ← כן, אם מתקיימים שלושת התנאים: עמימות אובייקטיבית, שליטת החניון, והסתברות לרשלנות (סעיף 41 לפקודת הנזיקין).
**וריאציה 2 — עמימות אובייקטיבית:** מתי נבחנת העמימות העובדתית? ← בסיום ההליך המשפטי, אם פרטי ההתרחשות נותרו עלומים (רע"א 7002/17).
**וריאציה 3 — שליטה בנכס:** האם חניון נחשב לנכס שבשליטת החברה? ← כן, החניון על מתקניו ואבטחתו (סעיף 41 לפקודת הנזיקין).
**וריאציה 4 — הסתברות לרשלנות:** האם נזק בחניון סגור מעיד על רשלנות? ← סביר יותר שכן, אם אין הסבר אחר, בשל אחריות החניון לאבטחה ותחזוקה (סעיף 41 לפקודת הנזיקין).', 'נזק בחניון סגור ← עמימות אובייקטיבית + שליטת החניון + הסתברות לרשלנות ← העברת נטל הוכחה.',
    '["פקודת הנזיקין [נוסח חדש]: סע'' 41", "רע\"א 7002/17 פלוני נ'' פלוני (21.5.2018)", "נבו - המתמחה דיני נזיקין (2026) | חובת הראיה ברשלנות כשהדבר מעיד על עצמו"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן ראובן יכול היה להתקין מצלמת רכב שתתעד את האירוע, ולכן לא מתקיים תנאי אי-הידיעה.', false, 'טענה זו שגויה. תנאי אי-הידיעה מתמקד בעמימות אובייקטיבית בסיום ההליך המשפטי, ולא ביכולת תיאורטית של התובע למנוע את אי-הידיעה מראש. בנוסף, אין חובה חוקית להתקין מצלמת רכב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, אם יוכיח כי חברת החניונים התרשלה באבטחת החניון, וכי הנזק מתיישב יותר עם רשלנותה.', false, 'טענה זו שגויה. אם ראובן יוכיח רשלנות ספציפית, אין צורך בכלל "הדבר מעיד על עצמו". הכלל נועד למקרים של עמימות עובדתית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם יתקיימו שלושת התנאים המצטברים: עמימות עובדתית בסיום המשפט, שליטה מלאה של החברה על החניון, והסתברות גבוהה יותר לרשלנות החברה.', true, 'זוהי התשובה הנכונה. במקרה זה, מתקיימים לכאורה התנאים: ראובן אינו יודע את נסיבות הנזק (עמימות אובייקטיבית), לחברת החניונים שליטה מלאה על הנכס (החניון), וסביר יותר שהנזק נגרם עקב רשלנותה (למשל, באבטחה או תחזוקה).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שכן הנזק נגרם לרכבו של ראובן, ולא על ידי נכס שבשליטת חברת החניונים.', false, 'טענה זו שגויה. החניון עצמו, על מתקניו ואבטחתו, נחשב לנכס שבשליטת חברת החניונים, ופגיעה ברכב בחניון יכולה להיגרם על ידי נכס זה (למשל, רכב אחר שנכנס ויצא, או כשל במתקן).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'התנאים המצטברים לכלל "הדבר מעיד על עצמו"',
    2, 'מהם שלושת התנאים המצטברים הנדרשים להחלת כלל "הדבר מעיד על עצמו" לפי סעיף 41 לפקודת הנזיקין?', 'שאלה זו בוחנת את הידע של הסטודנטים לגבי שלושת התנאים המצטברים להחלת כלל "הדבר מעיד על עצמו" כפי שמעוגנים בסעיף 41 לפקודת הנזיקין וכפי שפורשו בפסיקה, ובפרט את פרשנותו העדכנית של התנאי הראשון.', 'סעיף 41 לפקודת הנזיקין [נוסח חדש] קובע שלושה תנאים מצטברים להחלת כלל "הדבר מעיד על עצמו": 1. אי-ידיעה (עמימות עובדתית): לתובע לא הייתה ידיעה או לא הייתה לו יכולת לדעת מה היו למעשה הנסיבות שגרמו למקרה אשר הביא לידי הנזק. תנאי זה מתפרש כדרישה לקיומה של עמימות עובדתית בסיום ההליך המשפטי, ולא בידיעת הניזוק בעת האירוע. 2. שליטה על הנכס: הנזק נגרם על ידי נכס שלנתבע הייתה שליטה מלאה עליו. 3. התרשלות מסתברת: נראה לבית המשפט שאירוע המקרה שגרם לנזק מתיישב יותר עם המסקנה שהנתבע לא נקט זהירות סבירה מאשר עם המסקנה שהוא נקט זהירות סבירה. רק בהתקיים שלושתם במצטבר, עובר נטל השכנוע לנתבע להוכיח שלא התרשל. ראו סעיף 41 לפקודת הנזיקין [נוסח חדש], וכן רע"א 7002/17 פלוני נ'' פלוני (21.5.2018).',
    'אי-זכירה של אחד התנאים, או בלבול בין התנאים השונים, במיוחד התנאי הראשון והשלישי.', '["הדבר מעיד על עצמו", "פקודת הנזיקין", "תנאים מצטברים", "אי-ידיעה", "שליטה בנכס", "התרשלות מסתברת", "נטל השכנוע"]'::jsonb, '**וריאציה 1 — התנאי הראשון:** מהו התנאי הראשון ל"הדבר מעיד על עצמו"? ← עמימות עובדתית בסיום המשפט (סעיף 41 לפקודת הנזיקין, רע"א 7002/17).
**וריאציה 2 — התנאי השני:** מהו התנאי השני ל"הדבר מעיד על עצמו"? ← שליטה מלאה של הנתבע על הנכס שגרם לנזק (סעיף 41 לפקודת הנזיקין).
**וריאציה 3 — התנאי השלישי:** מהו התנאי השלישי ל"הדבר מעיד על עצמו"? ← הסתברות שהאירוע נגרם מרשלנות הנתבע (סעיף 41 לפקודת הנזיקין).
**וריאציה 4 — חשיבות התנאים:** האם כל התנאים חייבים להתקיים? ← כן, הם מצטברים (רע"א 7002/17).', 'הדבר מעיד על עצמו ← 3 תנאים מצטברים ← עמימות, שליטה, הסתברות לרשלנות.',
    '["פקודת הנזיקין [נוסח חדש]: סע'' 41", "רע\"א 7002/17 פלוני נ'' פלוני (21.5.2018)", "עמוס הרמן דיני נזיקין (2020) | פרק ז הדבר מעיד על עצמו"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'התובע לא ידע את נסיבות הנזק, הנתבע שלט בנכס שגרם לנזק, והנזק נגרם כתוצאה מכוח עליון.', false, 'טענה זו שגויה. התנאי השלישי אינו שהנזק נגרם מכוח עליון, אלא שהאירוע מתיישב יותר עם רשלנות הנתבע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'עמימות עובדתית בסיום המשפט, שליטה מלאה של הנתבע על הנכס שגרם לנזק, והסתברות שהאירוע נגרם מרשלנות הנתבע.', true, 'זוהי התשובה הנכונה. אלו הם שלושת התנאים המצטברים כפי שפורשו בפסיקה: אי-ידיעה (עמימות אובייקטיבית), שליטה בנכס, והתרשלות מסתברת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'התובע לא יכול היה לדעת את נסיבות הנזק, הנתבע היה בעל הנכס שגרם לנזק, והנזק נגרם כתוצאה ממעשה מכוון של הנתבע.', false, 'טענה זו שגויה. התנאי השני הוא שליטה מלאה בנכס, לא בהכרח בעלות. התנאי השלישי אינו מעשה מכוון, אלא רשלנות מסתברת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הניזוק לא ידע את נסיבות הנזק, הנתבע היה מודע לסיכון, והנזק נגרם כתוצאה מהפרת חובה חקוקה.', false, 'טענה זו שגויה. אי-הידיעה נבחנת בסיום המשפט ולא בידיעת הניזוק. הכלל עוסק ברשלנות, לא בהפרת חובה חקוקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הצגת גרסה עובדתית וכלל "הדבר מעיד על עצמו"',
    3, 'דוד הגיש תביעת נזיקין נגד חברת בנייה, בטענה כי נפל לבור שנפער באתר הבנייה עקב רשלנות החברה שלא גידרה את הבור. דוד הציג גרסה מפורטת של האירוע, אך במהלך המשפט התקשה להוכיח את טענותיו. האם דוד יכול, באופן חלופי, להסתמך על כלל "הדבר מעיד על עצמו"?', 'שאלה זו עוסקת במגבלה על תחולת כלל "הדבר מעיד על עצמו" כאשר התובע מציג גרסה עובדתית ספציפית לנסיבות הנזק. היא מדגישה את העיקרון לפיו הצגת גרסה כזו שוללת את תנאי אי-הידיעה, שהוא תנאי מהותי להחלת הכלל.', 'כלל "הדבר מעיד על עצמו" נועד למקרים של עמימות עובדתית, כאשר התובע אינו יודע ואינו יכול לדעת את נסיבות גרימת הנזק. כאשר התובע מציג גרסה עובדתית מפורטת באשר לנסיבות התאונה, הוא למעשה טוען שהוא יודע את העובדות שגרמו לנזק. במצב כזה, לא מתקיים התנאי הראשון של אי-הידיעה, ולכן הכלל אינו חל. הצגת גרסה עובדתית ספציפית והסתמכות על כלל "הדבר מעיד על עצמו" יכולה להיות בבחינת "תרתי דסתרי". אם התובע יודע את העובדות, הבעיה שלו היא בהוכחתן, ולא בחוסר ידיעה. ראו ע"א 1071/96 עיזבון המנוח אמין פואד אלעבד נאצר נ'' מדינת ישראל (6.2.2006), וכן עמוס הרמן דיני נזיקין (2020) | פרק ז הדבר מעיד על עצמו.',
    'הנחה שגויה כי ניתן להשתמש בכלל "הדבר מעיד על עצמו" כטענה חלופית לגרסה עובדתית שלא הוכחה, מבלי להבין שהצגת גרסה ספציפית שוללת את תנאי אי-הידיעה.', '["הדבר מעיד על עצמו", "אי-ידיעה", "גרסה עובדתית", "נטל ההוכחה", "עמימות עובדתית", "תרתי דסתרי"]'::jsonb, '**וריאציה 1 — גרסה ספציפית:** אם התובע מציג גרסה מפורטת לנזק, האם יכול להסתמך על "הדבר מעיד על עצמו"? ← לא, כי הצגת גרסה שוללת את תנאי אי-הידיעה (ע"א נאצר).
**וריאציה 2 — עמימות מול ידיעה:** מתי חל הכלל? ← רק כשיש עמימות עובדתית ואין ידיעה על נסיבות הנזק (ע"א נאצר).
**וריאציה 3 — קושי בהוכחה:** האם קושי להוכיח גרסה ספציפית מצדיק את הכלל? ← לא, הכלל אינו תחליף לקושי בהוכחת עובדות ידועות (עמוס הרמן, דיני נזיקין).
**וריאציה 4 — מטרת הכלל:** מהי מטרת כלל "הדבר מעיד על עצמו"? ← לסייע לתובע במצבים של חיסרון ראייתי מובהק ועמימות עובדתית (רע"א 7002/17).', 'הצגת גרסה עובדתית ← שוללת אי-ידיעה ← לא ניתן להחיל "הדבר מעיד על עצמו".',
    '["פקודת הנזיקין [נוסח חדש]: סע'' 41", "ע\"א 1071/96 עיזבון המנוח אמין פואד אלעבד נאצר נ'' מדינת ישראל, ס(4) 337 (6.2.2006)", "עמוס הרמן דיני נזיקין (2020) | פרק ז הדבר מעיד על עצמו"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן כלל "הדבר מעיד על עצמו" נועד לסייע לתובעים במצבים של קושי ראייתי.', false, 'טענה זו שגויה. למרות שהכלל נועד לסייע, הוא אינו חל כאשר התובע מציג גרסה עובדתית ספציפית, שכן אז לא מתקיים תנאי אי-הידיעה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן הצגת גרסה עובדתית מפורטת שוללת את תנאי אי-הידיעה הנדרש להחלת הכלל.', true, 'זוהי התשובה הנכונה. אם התובע מציג גרסה עובדתית ספציפית, הוא למעשה טוען שהוא יודע את נסיבות הנזק, ובכך שולל את קיומו של התנאי הראשון של אי-הידיעה, שהוא תנאי מהותי להחלת הכלל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם בית המשפט יקבע כי גרסתו של דוד הייתה סבירה, למרות שלא הוכחה במלואה.', false, 'טענה זו שגויה. סבירות הגרסה אינה רלוונטית לשאלת קיום תנאי אי-הידיעה. עצם הצגת הגרסה שוללת את התנאי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן יוכיח דוד כי חברת הבנייה הסתירה ממנו ראיות מהותיות.', false, 'טענה זו שגויה. הסתרת ראיות היא עניין נפרד שעשוי להשפיע על נטל ההוכחה בדרכים אחרות, אך אינה משנה את העובדה שהצגת גרסה ספציפית שוללת את תנאי אי-הידיעה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'מהות העברת הנטל ב"הדבר מעיד על עצמו"',
    4, 'כאשר מתקיימים שלושת התנאים להחלת כלל "הדבר מעיד על עצמו" לפי סעיף 41 לפקודת הנזיקין, איזה נטל עובר אל הנתבע?', 'שאלה זו מתמקדת במהות העברת הנטל המשפטי כאשר כלל "הדבר מעיד על עצמו" מוחל. היא בוחנת את ההבחנה בין נטל הבאת הראיות לנטל השכנוע, ומדגישה את ההלכה הפסוקה בישראל לפיה הכלל מעביר את נטל השכנוע אל הנתבע.', 'הפסיקה הישראלית, בעקבות פסק הדין המכונן בד"נ 4/69 נוימן נ'' כהן, קבעה כי כאשר מתקיימים שלושת התנאים המצטברים של סעיף 41 לפקודת הנזיקין, עובר אל הנתבע נטל השכנוע, ולא רק נטל הבאת הראיות. משמעות הדבר היא שעל הנתבע לשכנע את בית המשפט, על פי מאזן ההסתברויות, כי לא התרשל וכי רשלנותו לא גרמה לנזק. אם הנתבע לא מצליח להרים נטל זה, כלומר אם כפות המאזניים נותרות מעוינות בסיום ההליך, התובע יזכה בתביעתו. עקרון זה מבוסס על שיקולי מדיניות, הגינות ויעילות, שכן במצבים של עמימות עובדתית ויתרון ראייתי לנתבע, הצדק דורש להטיל עליו את הסיכון של אי-ההוכחה. ראו ד"נ 4/69 יצחק נוימן ו-בנין חברה לביטוח בע"מ נ'' פולה פסיה כהן (16.9.1970), וכן עמוס הרמן דיני נזיקין (2020) | פרק ז הדבר מעיד על עצמו.',
    'בלבול בין נטל השכנוע לנטל הבאת הראיות, או אי-הבנה של המשמעות האופרטיבית של העברת נטל השכנוע.', '["הדבר מעיד על עצמו", "נטל השכנוע", "נטל הבאת הראיות", "פקודת הנזיקין", "ד\"נ נוימן נ'' כהן", "מאזן הסתברויות"]'::jsonb, '**וריאציה 1 — נטל השכנוע:** איזה נטל עובר לנתבע ב"הדבר מעיד על עצמו"? ← נטל השכנוע (ד"נ נוימן, עמוס הרמן).
**וריאציה 2 — נטל הבאת ראיות:** האם עובר רק נטל הבאת ראיות? ← לא, הפסיקה דחתה גישה זו (ד"נ נוימן).
**וריאציה 3 — כפות מאזניים מעוינות:** אם כפות המאזניים מעוינות לאחר העברת הנטל, מי זוכה? ← התובע (עמוס הרמן, דיני נזיקין).
**וריאציה 4 — מטרת העברת הנטל:** מהי מטרת העברת נטל השכנוע? ← להטיל על הנתבע את הסיכון של אי-ההוכחה במצבים של עמימות ויתרון ראייתי (עמוס הרמן, דיני נזיקין).', 'הדבר מעיד על עצמו ← העברת נטל השכנוע לנתבע ← אם לא הרים, התובע זוכה.',
    '["פקודת הנזיקין [נוסח חדש]: סע'' 41", "ד\"נ 4/69 יצחק נוימן ו-בנין חברה לביטוח בע\"מ נ'' פולה פסיה כהן, כד(2) 229 (16.9.1970)", "עמוס הרמן דיני נזיקין (2020) | פרק ז הדבר מעיד על עצמו", "יניב ואקי דיני ראיות כרך ד (2021) | פרק 62 נטל ההוכחה במשפט האזרחי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'נטל הבאת הראיות בלבד, כלומר על הנתבע להביא ראיות נגדיות, אך נטל השכנוע נשאר על התובע.', false, 'טענה זו שגויה. הפסיקה הישראלית קבעה כי הכלל מעביר את נטל השכנוע, ולא רק את נטל הבאת הראיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'נטל השכנוע, כלומר על הנתבע לשכנע את בית המשפט שלא התרשל, ואם כפות המאזניים מעוינות, התובע יזכה.', true, 'זוהי התשובה הנכונה. הפסיקה הישראלית, בעקבות ד"נ 4/69 נוימן נ'' כהן, קבעה כי סעיף 41 מעביר את נטל השכנוע אל הנתבע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'נטל השכנוע, אך רק אם התובע הוכיח את רשלנות הנתבע מעבר לכל ספק סביר.', false, 'טענה זו שגויה. הכלל נועד למקרים בהם התובע אינו יכול להוכיח רשלנות באופן ישיר, ומידת ההוכחה הנדרשת במשפט אזרחי היא מאזן הסתברויות, לא מעבר לכל ספק סביר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'נטל הבאת הראיות ונטל השכנוע, אך רק אם הנתבע לא הציג כל גרסה לאירוע הנזק.', false, 'טענה זו שגויה. העברת הנטל אינה תלויה בהצגת גרסה על ידי הנתבע, אלא בקיום התנאים המצטברים של הכלל.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 7, '2022-W-S-Q07';
END
$$;

-- ============================================================
-- Q08 — 2022-W-S-Q08 — chapter=family_inheritance subtopic=inheritance_will
-- classifier_note: Terminally-ill testator wishing to bequeath all to disability charity — testamentary disposition
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e4e8d211-e4d4-4212-84c2-fa6d39f74f89'::uuid;
  v_group_id uuid := '0d265625-7318-4ccf-a9a5-1ea463abc4ef'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '6810c226-2684-4d84-a90d-a730fb967623'::uuid;
  v_ang_1 uuid := 'a70087ef-af09-4b6b-876b-6ff1125e850f'::uuid;
  v_ang_2 uuid := 'b2c54e81-1c7a-4313-a2e4-346bb9c35f1f'::uuid;
  v_ang_3 uuid := '41d0fd08-4882-49f4-91b7-78252df9a809'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q08';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 8, '2022-W-S-Q08';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'family_inheritance';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'family_inheritance';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'inheritance_will' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'inheritance_will', 'family_inheritance';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q08', v_chapter_id, v_subtopic_id, 'אלון התבשר כי תוחלת חייו קצרה. בעקבות בשורה זו אלון מעוניין להעביר את כל רכושו לעמותה הפועלת לרווחתם של אנשים עם מוגבלויות ומשתף ברצונו את גלי, חברתו ואשת סודו. כיצד יכול אלון להבטיח את מילוי רצונו?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 8}'::jsonb, 'השאלה עוסקת בדרכים משפטיות להעברת רכוש לאחר המוות, תוך התמקדות בהבחנה בין הסכמי ירושה אסורים, מגבלות ייפוי כוח מתמשך, והאפשרות ליצור הקדש. היא בוחנת את הוראות חוק הירושה, חוק הנאמנות וחוק הכשרות המשפטית והאפוטרופסות.', 'סעיף 8(א) לחוק הירושה, התשכ"ה-1965, קובע כי הסכם בדבר ירושתו של אדם שנעשה בחייו בטל, כדי לשמור על חופש המצווה לצוות ולחזור בו מצוואתו עד יום מותו. לכן, הסכם עם עמותה להעברת רכוש לאחר המוות אינו תקף. סעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות, התשכ"ב-1962, קובע במפורש כי מיופה כוח אינו מוסמך לערוך צוואה בשם הממנה, שכן עריכת צוואה היא פעולה אישית ביותר. לעומת זאת, יצירת הקדש (נאמנות למטרה מסוימת) היא דרך לגיטימית להקצות נכסים לאחר המוות. סעיף 17(א)(1) לחוק הנאמנות, התשל"ט-1979, מאפשר ליצור הקדש באמצעות מסמך חתום בפני נוטריון, המפרט את מטרות ההקדש, נכסיו ותנאיו. סעיף 17(א)(2) לחוק הנאמנות קובע כי הקדש יכול להיווצר גם באמצעות צוואה, אך למעט צוואה בעל פה, כלומר צוואה ליצירת הקדש חייבת להיות בכתב. לפיכך, הדרך הנכונה עבור אלון להבטיח את מילוי רצונו היא באמצעות יצירת הקדש במסמך חתום בפני נוטריון. ראו סעיף 8 לחוק הירושה, תשכ"ה-1965, סעיף 32ו לחוק הכשרות המשפטית והאפוטרופסות, תשכ"ב-1962, וכן סעיף 17 לחוק הנאמנות, תשל"ט-1979.', 'הטעות הנפוצה היא בלבול בין חופש הציווי לבין האיסור על עסקאות בירושה עתידית, או אי-הכרת המגבלות הספציפיות על ייפוי כוח מתמשך ועל צורת יצירת הקדש.',
    '["חוק הירושה", "חוק הנאמנות", "ייפוי כוח מתמשך", "הקדש", "צוואה", "עסקאות בירושה עתידית", "חופש הציווי", "סעיף 8(א) לחוק הירושה", "סעיף 17 לחוק הנאמנות", "סעיף 32ו לחוק הכשרות המשפטית והאפוטרופסות"]'::jsonb, '**וריאציה 1 — הסכם ירושה עתידי:** האם הסכם עם עמותה להעברת רכוש לאחר מוות תקף? ← לא, בטל לפי סעיף 8(א) לחוק הירושה.
**וריאציה 2 — ייפוי כוח מתמשך לצוואה:** האם מיופה כוח יכול לערוך צוואה בשם הממנה? ← לא, אסור במפורש לפי סעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות.
**וריאציה 3 — יצירת הקדש:** כיצד ניתן ליצור הקדש למטרה מסוימת לאחר המוות? ← באמצעות מסמך חתום בפני נוטריון או צוואה בכתב (סעיף 17(א) לחוק הנאמנות).
**וריאציה 4 — צוואה בעל פה להקדש:** האם צוואה בעל פה יכולה ליצור הקדש? ← לא, צוואה ליצירת הקדש חייבת להיות בכתב (סעיף 17(א)(2) לחוק הנאמנות).', 'העברת רכוש לאחר מוות לעמותה ← הקדש בכתב בפני נוטריון או בצוואה בכתב ← לא הסכם ירושה ולא ייפוי כוח מתמשך לצוואה.', '["חוק הירושה, תשכ\"ה-1965: סע'' 8", "חוק הכשרות המשפטית והאפוטרופסות, תשכ\"ב-1962: סע'' 32ו", "חוק הנאמנות, תשל\"ט-1979: סע'' 17", "ת\"ע (משפחה תל אביב-יפו) 26289-03-18 ר.ב. מנהל עיזבון המנוח נ'' ר.ש. (6.4.2019)", "ה\"פ (מחוזי חי'') 61556-07-17 אירית נוי לויט נ'' כלל חברה לביטוח בע\"מ (22.10.2019)", "שלמה כרם חוק הנאמנות (2004) | סעיף 17: יצירה ותחילה של הקדש"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Terminally-ill testator wishing to bequeath all to disability charity — testamentary disposition | source_review_note: הסיווג לתת-נושא ''הליכים'' תחת ''סדר דין אזרחי'' הוא הולם ביותר מבין האפשרויות הסגורות, שכן השאלה עוסקת בדרכים הפרוצדורליות ליצירת מכשירים משפטיים (צוואה, הקדש, ייפוי כוח) שנועדו להסדיר העברת רכוש לאחר המוות, ובבחינת תוקפם המשפטי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אלון יכול לפנות לעמותה הפועלת לרווחתם של אנשים עם מוגבלויות ולחתום עימה על הסכם שלפיו יעבור כל רכושו לעמותה לאחר מותו.', false, 'טענה זו שגויה. הסכם בדבר ירושתו של אדם שנעשה בחייו בטל לפי סעיף 8(א) לחוק הירושה, שכן הוא פוגע בחופש המצווה לצוות ולחזור בו מצוואתו עד יום מותו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אלון יכול לערוך לטובת גלי ייפוי כוח מתמשך כדי שתוכל לערוך את צוואתו בשמו אם כשרותו המשפטית תוגבל.', false, 'טענה זו שגויה. ייפוי כוח מתמשך אינו מאפשר למיופה הכוח לערוך צוואה בשם הממנה, כפי שקבוע בסעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אלון יכול לערוך מסמך חתום בפני נוטריון, ובמסגרתו ליצור הקדש שמטרתו לפעול לרווחתם של אנשים עם מוגבלויות ולציין את נכסיו ותנאיו של ההקדש.', true, 'זוהי התשובה הנכונה. יצירת הקדש באמצעות מסמך חתום בפני נוטריון היא דרך תקפה להקצות נכסים למטרה מסוימת לאחר המוות, בהתאם לסעיף 17(א)(1) לחוק הנאמנות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אלון יכול לערוך צוואה בעל פה, שדרכה יביע את רצונו וייצור הקדש לעמותה הפועלת לרווחתם של אנשים עם מוגבלויות.', false, 'טענה זו שגויה. צוואה בעל פה אינה יכולה לשמש ליצירת הקדש, שכן סעיף 17(א)(2) לחוק הנאמנות דורש צוואה בכתב, למעט צוואה בעל פה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תוקף הסכם שותפות הכולל הוראות לאחר מוות',
    1, 'ראובן ושמעון הם שותפים בחברה. בהסכם המייסדים של החברה נקבע כי במקרה של פטירת אחד מהם, מניותיו בחברה תועברנה לידי השותף הנותר. לאחר פטירתו של ראובן, מנהל עיזבונו טוען כי סעיף זה בטל מכוח סעיף 8(א) לחוק הירושה. מה הדין?', 'שאלה זו בוחנת את תוקפם של הסכמי שותפות הכוללים הוראות להעברת מניות במקרה של פטירה, לאור האיסור על עסקאות בירושה עתידית הקבוע בסעיף 8(א) לחוק הירושה. היא מדגישה את הפרשנות המצמצמת של סעיף זה בפסיקה, המבחינה בין הסכמי ירושה לבין עסקאות בנכסי עיזבון.', 'סעיף 8(א) לחוק הירושה, התשכ"ה-1965, קובע כי "הסכם בדבר ירושתו של אדם וויתור על ירושתו שנעשו בחייו של אותו אדם - בטלים". הפסיקה, ובראשה פסק הדין בעניין יקותיאל וברדיגו, פירשה סעיף זה בצמצום מרבי. נקבע כי האיסור חל רק על הסכמים המתיימרים להעביר יורש מירושתו או לעשות ליורש את מי שאינו יורש, ולא על עסקאות הנוגעות לנכסי עיזבון ספציפיים. הסכם שותפות הקובע העברת מניות במקרה פטירה נחשב לעסקה בנכסי עיזבון, שהיא מותרת, ולא להסכם ירושה אסור. בית המשפט לענייני משפחה בת"ע 26289-03-18 אישר גישה זו, בקובעו כי סעיף בהסכם מייסדים הקובע העברת מניות במקרה פטירה אינו סותר את סעיף 8(א) לחוק הירושה. מדובר בהסדר מסחרי לגיטימי המאפשר לשותפים להבטיח את המשך פעילות החברה. ראו ת"ע (משפחה תל אביב-יפו) 26289-03-18 ר.ב. מנהל עיזבון המנוח נ'' ר.ש. (6.4.2019), וכן ה"פ (מחוזי חי'') 61556-07-17 אירית נוי לויט נ'' כלל חברה לביטוח בע"מ (22.10.2019).',
    'הטעות הנפוצה היא אי-הבחנה בין הסכם בדבר ירושה עתידית (האסור) לבין עסקה בנכסי עיזבון (המותרת), והחלת האיסור באופן גורף על כל הסכם שיש לו השלכות לאחר המוות.', '["חוק הירושה", "סעיף 8(א) לחוק הירושה", "עסקאות בירושה עתידית", "עסקאות בנכסי עיזבון", "הסכם מייסדים", "מניות", "פרשנות מצמצמת"]'::jsonb, '**וריאציה 1 — הסכם שותפות ומניות:** האם סעיף בהסכם שותפות המעביר מניות לשותף הנותר לאחר מוות תקף? ← כן, אינו סותר סעיף 8(א) לחוק הירושה (ת"ע ר.ב. מנהל עיזבון).
**וריאציה 2 — הבחנה בין ירושה לעיזבון:** מהי ההבחנה המרכזית בסעיף 8(א) לחוק הירושה? ← בין עסקה ב"ירושה" (אסור) לעסקה ב"עיזבון" (מותר) (ה"פ אירית נוי לויט).
**וריאציה 3 — פרשנות סעיף 8(א):** כיצד מפרשת הפסיקה את סעיף 8(א) לחוק הירושה? ← על דרך הצמצום המרבי והקפדנות החמורה (ה"פ אירית נוי לויט).
**וריאציה 4 — חופש החוזים:** האם סעיף 8(א) פוגע בחופש החוזים? ← כן, ולכן יש לפרשו בצמצום (ת"ע ר.ב. מנהל עיזבון).', 'הסכם שותפות להעברת מניות לאחר מוות ← תקף ← נחשב לעסקה בנכסי עיזבון ← לא סותר סעיף 8(א) לחוק הירושה.',
    '["חוק הירושה, תשכ\"ה-1965: סע'' 8(א)", "ת\"ע (משפחה תל אביב-יפו) 26289-03-18 ר.ב. מנהל עיזבון המנוח נ'' ר.ש. (6.4.2019)", "ה\"פ (מחוזי חי'') 61556-07-17 אירית נוי לויט נ'' כלל חברה לביטוח בע\"מ (22.10.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הסעיף בטל, שכן הוא מהווה הסכם בדבר ירושה עתידית האסור לפי סעיף 8(א) לחוק הירושה.', false, 'טענה זו שגויה. הפסיקה מפרשת את סעיף 8(א) לחוק הירושה בצמצום, ומבחינה בין הסכם בדבר ירושה לבין עסקה בנכסי עיזבון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'הסעיף תקף, שכן הוא אינו נחשב להסכם בדבר ירושה עתידית, אלא להסכם הנוגע לנכסי עיזבון ספציפיים (מניות), והוא חלק מההסדר המסחרי בין השותפים.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי סעיף בהסכם מייסדים הקובע העברת מניות במקרה פטירה אינו סותר את סעיף 8(א) לחוק הירושה, שכן מדובר בעסקה בנכסי עיזבון ולא בהסכם ירושה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הסעיף תקף רק אם אושר על ידי בית המשפט לענייני משפחה בחייו של ראובן.', false, 'טענה זו שגויה. הסכם כזה אינו דורש אישור בית משפט כדי להיות תקף, שכן הוא אינו נחשב להסכם ירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הסעיף בטל, אלא אם כן נערך בצוואה כדין.', false, 'טענה זו שגויה. הסכם כזה אינו חייב להיערך בצוואה כדי להיות תקף, שכן הוא אינו נחשב להסכם ירושה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני ההבחנה בין עסקה בירושה לעסקה בעיזבון',
    2, 'מהם המבחנים העיקריים שנקבעו בפסיקה להבחנה בין "הסכם בדבר ירושתו של אדם" (האסור לפי סעיף 8(א) לחוק הירושה) לבין "עסקה בנכסי עיזבון" (המותרת)?', 'שאלה זו מתמקדת במבחנים שפיתחה הפסיקה להבחנה בין הסכמים אסורים בדבר ירושה עתידית לבין עסקאות מותרות בנכסי עיזבון, בהתאם לסעיף 8(א) לחוק הירושה. היא מדגישה את הגישה הפרגמטית והמצמצמת של בתי המשפט בפרשנות הסעיף.', 'הפסיקה בישראל, ובראשה פסק הדין בד"נ 39/80 ברדיגו נ'' פדרליין, הרחיבה את הגישה המצמצמת של סעיף 8(א) לחוק הירושה. השופט א'' ברק הבחין בין שני סוגי הסכמים: הסכם הכולל העברה פיזית ממשית של זכות מאדם לרעהו עם פטירתו (האסור), לבין הסכם שבו לא קיימת העברה פיזית של הזכות, אלא מדובר בהתרבות זכותו העצמאית של האחר בשל פגיעת זכותו של המוריש (המותר). בנוסף, המבחן המרכזי הוא האם ההסכם מתיימר להעביר יורש מירושתו או לעשות ליורש את מי שאינו יורש לא על-פי-דין ולא על-פי-צוואה. רק הסכמים מהסוג הראשון, המנסים לשנות את סדר הירושה שלא בדרך של צוואה, נופלים לגדר האיסור. ראו ת"ע (משפחה תל אביב-יפו) 26289-03-18 ר.ב. מנהל עיזבון המנוח נ'' ר.ש. (6.4.2019), וכן ה"פ (מחוזי חי'') 61556-07-17 אירית נוי לויט נ'' כלל חברה לביטוח בע"מ (22.10.2019).',
    'אי-הבנה של ההבחנה הדקה בין העברה פיזית לבין התרבות זכות, ואי-זכירה שהאיסור מתמקד בשינוי מעמד היורש ולא בעסקאות בנכסים ספציפיים.', '["סעיף 8(א) לחוק הירושה", "עסקאות בירושה עתידית", "עסקאות בנכסי עיזבון", "העברה פיזית של זכות", "התרבות זכות", "ד\"נ ברדיגו נ'' פדרליין", "פרשנות מצמצמת"]'::jsonb, '**וריאציה 1 — העברה פיזית מול התרבות זכות:** מהו המבחן העיקרי להבחנה בין עסקה אסורה למותרת? ← האם יש העברה פיזית של זכות עם המוות (אסור) או התרבות זכות קיימת (מותר) (ת"ע ר.ב. מנהל עיזבון).
**וריאציה 2 — שינוי מעמד יורש:** האם הסכם המתיימר להעביר יורש מירושתו אסור? ← כן, זהו הסכם ירושה אסור (ה"פ אירית נוי לויט).
**וריאציה 3 — עסקה בנכס ספציפי:** האם עסקה בנכס ספציפי מתוך העיזבון מותרת? ← כן, אינה נחשבת להסכם ירושה אסור (ה"פ אירית נוי לויט).
**וריאציה 4 — גישת השופט ברק:** מהי הגישה הפרגמטית של השופט ברק בסוגיה? ← לאפשר למשקיעים להשיג מטרות עסקיות, תוך פרשנות מצמצמת של סעיף 8(א) (ת"ע ר.ב. מנהל עיזבון).', 'הבחנה בין עסקה בירושה לעסקה בעיזבון ← העברה פיזית אסורה, התרבות זכות מותרת ← שינוי מעמד יורש אסור.',
    '["חוק הירושה, תשכ\"ה-1965: סע'' 8(א)", "ת\"ע (משפחה תל אביב-יפו) 26289-03-18 ר.ב. מנהל עיזבון המנוח נ'' ר.ש. (6.4.2019)", "ה\"פ (מחוזי חי'') 61556-07-17 אירית נוי לויט נ'' כלל חברה לביטוח בע\"מ (22.10.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המבחן הוא האם ההסכם נערך בכתב או בעל פה, כאשר רק הסכם בכתב יכול להיחשב לעסקה בנכסי עיזבון.', false, 'טענה זו שגויה. צורת ההסכם אינה המבחן המרכזי להבחנה, אלא מהותו ותוכנו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המבחן הוא האם ההסכם כולל העברה פיזית ממשית של זכות מאדם לרעהו עם פטירתו (אסור), או שמא מדובר בהתרבות זכות קיימת (מותר), וכן האם ההסכם מתיימר להעביר יורש מירושתו או לעשות ליורש את מי שאינו יורש.', true, 'זוהי התשובה הנכונה. הפסיקה, ובפרט השופט ברק, הבחינה בין העברה פיזית של זכות (האסורה) לבין התרבות זכות קיימת (המותרת), וכן התמקדה בשאלה האם ההסכם משנה את מעמד היורש.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המבחן הוא האם ההסכם נערך בין קרובי משפחה או בין זרים, כאשר רק הסכמים בין קרובי משפחה יכולים להיחשב לעסקאות בנכסי עיזבון.', false, 'טענה זו שגויה. זהות הצדדים אינה המבחן המרכזי להבחנה, אלא מהות ההסכם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'המבחן הוא האם ההסכם נוגע לכלל רכושו של המוריש או רק לחלק מסוים ממנו, כאשר רק הסכם הנוגע לחלק מסוים מותר.', false, 'טענה זו שגויה. למרות שסעיף 8(א) מתייחס ל"ירושתו של אדם" באופן כללי, הפסיקה התמקדה במהות הזכות המועברת ולא בהיקף הרכוש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תוקף נאמנות לאחר המוות שלא בצוואה',
    3, 'ראובן מעוניין ליצור נאמנות שתחול רק לאחר מותו, לטובת נכדיו שטרם נולדו. הוא עושה זאת באמצעות חוזה עם נאמן, שבו הוא מפרט את מטרות הנאמנות, נכסיה ותנאיה, אך אינו עורך צוואה. האם נאמנות כזו תקפה?', 'שאלה זו בוחנת את הדרישות הפורמליות ליצירת הקדש (נאמנות) שתחול לאחר המוות, תוך התייחסות לחוק הנאמנות ולחוק הירושה. היא מדגישה כי יצירת הקדש לאחר המוות מחייבת צורה ספציפית (צוואה בכתב או מסמך נוטריוני) ואינה יכולה להיעשות באמצעות חוזה רגיל.', 'חוק הנאמנות, התשל"ט-1979, מאפשר יצירת הקדש שתחול לאחר פטירת היוצר. אולם, סעיף 17(א) לחוק הנאמנות קובע כי הקדש טעון מסמך בכתב, והמסמך הוא אחד מאלה: (1) כתב חתום בידי יוצר ההקדש בפני נוטריון; (2) צוואה של יוצר ההקדש, למעט צוואה בעל-פה; (3) הוראת תשלום לעניין סעיף 147 לחוק הירושה. יצירת נאמנות שתחול לאחר המוות באמצעות חוזה רגיל, שאינו עומד בדרישות אלו, אינה תקפה. זאת, בין היתר, כדי לשמור על ההרמוניה עם חוק הירושה, הקובע בסעיף 8(ב) כי מתנה שאדם נותן על מנת שתוקנה למקבל רק לאחר מותו, אינה בת-תוקף אלא אם נעשתה בצוואה. לכן, חוזה נאמנות שנועד לצאת אל הפועל עם מות הבעלים, אם אינו עומד בדרישות צוואה, חסר תוקף משפטי. ראו סעיף 17(א) לחוק הנאמנות, תשל"ט-1979, וכן שלמה כרם חוק הנאמנות (2004) | סעיף 17: יצירה ותחילה של הקדש.',
    'הנחה שגויה כי כל חוזה יכול ליצור נאמנות לאחר המוות, מבלי להכיר בדרישות הצורניות הספציפיות של חוק הנאמנות.', '["חוק הנאמנות", "הקדש", "צוואה בכתב", "מסמך נוטריוני", "נאמנות לאחר המוות", "סעיף 17(א) לחוק הנאמנות", "חוק הירושה"]'::jsonb, '**וריאציה 1 — יצירת הקדש בחוזה:** האם ניתן ליצור הקדש לאחר המוות באמצעות חוזה רגיל? ← לא, נדרשת צוואה בכתב או מסמך נוטריוני (סעיף 17(א) לחוק הנאמנות).
**וריאציה 2 — הרמוניה בין חוקים:** מדוע נדרשת צוואה ליצירת הקדש לאחר המוות? ← לשמירה על הרמוניה עם סעיף 8(ב) לחוק הירושה (שלמה כרם, חוק הנאמנות).
**וריאציה 3 — מתנה לאחר המוות:** האם חוזה נאמנות לאחר המוות נחשב למתנה לאחר המוות? ← כן, ולכן חייב לעמוד בדרישות צוואה (סעיף 8(ב) לחוק הירושה).
**וריאציה 4 — צוואה בעל פה להקדש:** האם צוואה בעל פה יכולה ליצור הקדש? ← לא, צוואה ליצירת הקדש חייבת להיות בכתב (סעיף 17(א)(2) לחוק הנאמנות).', 'נאמנות לאחר המוות ← רק בצוואה בכתב או מסמך נוטריוני ← לא בחוזה רגיל.',
    '["חוק הנאמנות, תשל\"ט-1979: סע'' 17(א)", "חוק הירושה, תשכ\"ה-1965: סע'' 8(ב)", "שלמה כרם חוק הנאמנות (2004) | סעיף 17: יצירה ותחילה של הקדש"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, חוק הנאמנות מאפשר יצירת נאמנות באמצעות חוזה, ואין חובה לערוך צוואה.', false, 'טענה זו שגויה. חוק הנאמנות דורש צורה מסוימת ליצירת הקדש לאחר המוות, והיא צוואה בכתב או מסמך נוטריוני, ולא חוזה רגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, נאמנות שתחול לאחר המוות חייבת להיעשות בצוואה בכתב או במסמך חתום בפני נוטריון, ולא בחוזה רגיל, בהתאם לסעיף 17(א) לחוק הנאמנות.', true, 'זוהי התשובה הנכונה. חוק הנאמנות מכיר ביצירת הקדש לאחר המוות, אך קובע כי הדבר ייעשה באמצעות צוואה (למעט צוואה בעל פה) או מסמך חתום בפני נוטריון, ולא באמצעות חוזה רגיל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם הנאמן הסכים לכהן בתפקידו בחייו של ראובן.', false, 'טענה זו שגויה. הסכמת הנאמן היא תנאי למינויו, אך אינה מכשירה את צורת יצירת הנאמנות אם אינה עומדת בדרישות החוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, שכן מדובר במתנה שאדם נותן על מנת שתוקנה למקבל רק לאחר מותו, והיא בטלה לפי סעיף 8(ב) לחוק הירושה.', false, 'טענה זו שגויה חלקית. אמנם מדובר במתנה לאחר המוות, אך סעיף 8(ב) מאפשר זאת אם נעשתה בצוואה. הבעיה כאן היא שזה לא נעשה בצוואה, אך התשובה הנכונה מתמקדת בדרישות חוק הנאמנות עצמו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות מיופה כוח לערוך צוואה',
    4, 'ראובן ערך ייפוי כוח מתמשך לטובת שמעון, ובו הסמיך אותו לטפל בכל ענייניו הרכושיים והאישיים. ראובן איבד את כשרותו המשפטית. האם שמעון, כמיופה כוח, רשאי לערוך צוואה בשם ראובן?', 'שאלה זו עוסקת במגבלות סמכותו של מיופה כוח מתמשך, ובפרט באיסור המפורש על עריכת צוואה בשם הממנה. היא מדגישה את אופייה האישי ביותר של פעולת עריכת הצוואה, שאינה ניתנת להאצלה, כפי שמעוגן בחוק הכשרות המשפטית והאפוטרופסות.', 'סעיף 32ו(א) לחוק הכשרות המשפטית והאפוטרופסות, התשכ"ב-1962, קובע כי מיופה כוח מוסמך לקבל החלטות ולבצע פעולות בשם הממנה, למעט פעולה שלפי מהותה או לפי דין יש לבצעה באופן אישי. סעיף 32ו(ב)(6) לחוק זה מפרט במפורש כי מיופה כוח לא יהיה מוסמך לבצע בשם הממנה פעולות אלה: "עריכת צוואה, קביעת מוטבים לגבי סכומים שיש לשלם עקב מותו של אדם לפי סעיף 147 לחוק הירושה, התשכ"ה-1965". עריכת צוואה היא פעולה אישית ביותר, המשקפת את רצונו החופשי והאמיתי של המצווה, ועל כן החוק אוסר על מיופה כוח לעשותה בשם הממנה. איסור זה הוא מוחלט ואינו ניתן להתניה או לאישור בית משפט. ראו סעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות, תשכ"ב-1962.',
    'הנחה שגויה כי ייפוי כוח מתמשך מעניק סמכות גורפת לכל פעולה, כולל עריכת צוואה, או אי-הכרת האיסור המפורש בחוק.', '["ייפוי כוח מתמשך", "חוק הכשרות המשפטית והאפוטרופסות", "עריכת צוואה", "פעולה אישית", "סמכויות מיופה כוח", "סעיף 32ו(ב)(6)"]'::jsonb, '**וריאציה 1 — איסור מפורש:** האם מיופה כוח רשאי לערוך צוואה בשם הממנה? ← לא, אסור במפורש לפי סעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות.
**וריאציה 2 — פעולה אישית:** מדוע אסור למיופה כוח לערוך צוואה? ← עריכת צוואה היא פעולה אישית ביותר המשקפת את רצון המצווה.
**וריאציה 3 — היקף ייפוי כוח:** האם ייפוי כוח מתמשך יכול להסמיך לכל פעולה? ← לא, יש פעולות אישיות שאינן ניתנות להאצלה (סעיף 32ו(א) לחוק הכשרות המשפטית והאפוטרופסות).
**וריאציה 4 — קביעת מוטבים:** האם מיופה כוח רשאי לקבוע מוטבים לפי סעיף 147 לחוק הירושה? ← לא, גם פעולה זו אסורה במפורש (סעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות).', 'ייפוי כוח מתמשך ← אינו כולל סמכות לערוך צוואה ← פעולה אישית בלבד.',
    '["חוק הכשרות המשפטית והאפוטרופסות, תשכ\"ב-1962: סע'' 32ו(ב)(6)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, אם ייפוי הכוח המתמשך הסמיך אותו במפורש לערוך צוואה.', false, 'טענה זו שגויה. גם אם ייפוי הכוח המתמשך יכלול סעיף מפורש כזה, הוא יהיה בטל, שכן החוק אוסר זאת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, שכן עריכת צוואה היא פעולה אישית ביותר שאינה ניתנת לביצוע באמצעות מיופה כוח, בהתאם לסעיף 32ו(ב)(6) לחוק הכשרות המשפטית והאפוטרופסות.', true, 'זוהי התשובה הנכונה. החוק קובע במפורש כי מיופה כוח אינו מוסמך לערוך צוואה בשם הממנה, ללא קשר להיקף הסמכויות שניתנו לו בייפוי הכוח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אם קיבל אישור מבית המשפט לענייני משפחה.', false, 'טענה זו שגויה. בית המשפט אינו יכול לאשר פעולה שהחוק אוסר עליה במפורש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן ראובן ציין בייפוי הכוח המתמשך את תוכן הצוואה המדויק שברצונו לערוך.', false, 'טענה זו שגויה. גם אם ראובן יציין את תוכן הצוואה, מיופה הכוח אינו מוסמך לערוך אותה בשמו, שכן עריכת צוואה היא פעולה אישית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 8, '2022-W-S-Q08';
END
$$;

