-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '585c8533-f662-4b65-a563-524fafb68dae'::uuid;
  v_group_id uuid := '3cab03e1-a53a-4f87-a677-9018c9649952'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '990290dd-47fa-4948-bd44-7489465846bb'::uuid;
  v_ang_1 uuid := '9d05152f-20a9-4357-8804-14730103653a'::uuid;
  v_ang_2 uuid := '2ec6956b-64ac-44ff-99d1-251efd603ae8'::uuid;
  v_ang_3 uuid := 'a21e05d0-421c-4d0a-b612-6c293488565a'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q10';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 10, '2022-W-S-Q10';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'licensing_bar_membership' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'licensing_bar_membership', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q10', v_chapter_id, v_subtopic_id, 'משה סיים את התמחותו במקצוע עריכת הדין בהצלחה והחליט עם חברו אפרים, שהוא רואה חשבון במקצועו, לפתוח עסק אחד שיעניק שירותים משולבים של ראיית חשבון ועריכת דין. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 10}'::jsonb, 'השאלה עוסקת באיסור על שיתוף במקצוע עריכת הדין או בהכנסות ממנו עם מי שאינו עורך דין, כפי שקבוע בסעיף 58 לחוק לשכת עורכי הדין. איסור זה נועד לשמור על עצמאות המקצוע, כבודו, ועל אי-הטעיית הציבור בדבר אופי השירות המשפטי.', 'סעיף 58 לחוק לשכת עורכי הדין, התשכ"א-1961, קובע במפורש כי "עורך דין לא ישתף במקצועו או בהכנסותיו מן המקצוע מי שאינו עורך דין". איסור זה הוא מוחלט ונועד להבטיח שעורך הדין יפעל באופן עצמאי, ללא השפעות זרות, ולמנוע מצג שווא כלפי הציבור לגבי הכישורים והאחריות המקצועית. פתיחת עסק משותף המעניק שירותים משולבים של ראיית חשבון ועריכת דין, כפי שמתואר בשאלה, מהווה שיתוף במקצוע ובהכנסות עם מי שאינו עורך דין (רואה חשבון), ולכן היא אסורה. הפרת סעיף זה עלולה לגרור סנקציות משמעתיות חמורות מצד לשכת עורכי הדין. ראו סעיף 58 לחוק לשכת עורכי הדין, תשכ"א-1961.', 'הטעות הנפוצה היא אי-הבנה של היקף האיסור שבסעיף 58, והנחה שגויה כי שיתוף פעולה עם בעלי מקצועות אחרים מותר כל עוד הוא מועיל ללקוח או אינו פוגע ישירות בו.',
    '["שיתוף במקצוע", "שיתוף בהכנסות", "חוק לשכת עורכי הדין", "אתיקה מקצועית", "עצמאות מקצועית", "הגנה על הציבור"]'::jsonb, '**וריאציה 1 — שיתוף עם רואה חשבון:** האם עו"ד יכול לפתוח עסק משותף עם רואה חשבון ולשתף בהכנסות? ← לא, אסור לפי סעיף 58 לחוק לשכת עורכי הדין.
**וריאציה 2 — מטרת האיסור:** מהי מטרת האיסור על שיתוף במקצוע? ← לשמור על עצמאות המקצוע וכבודו, ולמנוע הטעיית הציבור.
**וריאציה 3 — "מי שאינו עורך דין":** מי נכלל בהגדרה "מי שאינו עורך דין"? ← כל מי שאינו חבר לשכת עורכי הדין בישראל.
**וריאציה 4 — השלכות הפרה:** מהן ההשלכות של הפרת סעיף 58? ← דין משמעתי וסנקציות מצד לשכת עורכי הדין (סעיף 61 לחוק לשכת עורכי הדין).', 'שיתוף עו"ד עם מי שאינו עו"ד ← אסור בחוק ← סעיף 58 לחוק לשכת עורכי הדין.', '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 58"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''ethics'' subtopic=''licensing_bar_membership'' | classifier_note: Lawyer + accountant joint practice — bar rules on multi-disciplinary partnership | source_review_note: הסיווג לתת-נושא ''הליכים'' תחת ''סדר דין אזרחי'' הוא הולם ביותר מבין האפשרויות הסגורות, שכן השאלה עוסקת בכללי אתיקה מקצועית החלים על עורכי דין במהלך עיסוקם, וכללי אתיקה נחשבים חלק מהדין הדיוני.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'נאסר על עורך דין שיתוף במקצוע או בהכנסות מן העיסוק במקצוע עריכת הדין בין מי שהוא עורך דין למי שאינו עורך דין.', true, 'זוהי התשובה הנכונה. סעיף 58 לחוק לשכת עורכי הדין אוסר במפורש על שיתוף במקצוע או בהכנסות מן העיסוק במקצוע עריכת הדין עם מי שאינו עורך דין, כדי לשמור על עצמאות המקצוע וכבודו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עורך דין יכול לפתוח כל עסק עם כל אחד לפי רצונו.', false, 'טענה זו שגויה. על עורכי דין חלות מגבלות אתיות ומשפטיות רבות, ובכללן האיסור על שיתוף פעולה מסוג זה עם מי שאינו עורך דין.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מותר לשתף הכנסות שנובעות מן העיסוק במקצוע עריכת הדין עם מי שאינו עורך דין, ואין על כך כל הגבלה.', false, 'טענה זו שגויה לחלוטין. סעיף 58 לחוק לשכת עורכי הדין מטיל איסור מפורש על שיתוף בהכנסות מן העיסוק במקצוע עריכת הדין עם מי שאינו עורך דין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ועדת האתיקה היא זו שמחליטה אם רשאי עורך דין לפתוח עסק ובאיזה אופן.', false, 'טענה זו שגויה. האיסור על שיתוף פעולה מסוג זה קבוע בחוק לשכת עורכי הדין עצמו, ואינו נתון לשיקול דעתה של ועדת האתיקה, אלא לאכיפתה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שיתוף פעולה בין עורך דין לבעל מקצוע אחר',
    1, 'עו"ד שרה ויועץ המס דני פתחו משרד משותף באותו בניין, עם קבלה משותפת ומזכירה אחת. הם מקפידים על הפרדה מוחלטת בין תיקי הלקוחות, חשבונות הבנק, ואינם משתפים זה את זה בהכנסות מפעילותם המקצועית. האם פעילותם זו מותרת?', 'שאלה זו בוחנת את גבולות האיסור על שיתוף במקצוע או בהכנסות עם מי שאינו עורך דין, כפי שנקבע בסעיף 58 לחוק לשכת עורכי הדין. היא מתמקדת בהבחנה בין שיתוף אסור לבין שיתוף פעולה לגיטימי במשרד משותף, תוך שמירה על הפרדה מהותית.', 'סעיף 58 לחוק לשכת עורכי הדין, התשכ"א-1961, אוסר על עורך דין "לשתף במקצועו או בהכנסותיו מן המקצוע מי שאינו עורך דין". הפסיקה והכללים האתיים פירשו איסור זה כמתייחס לשיתוף מהותי במקצוע או בהכנסות, ולא לשיתוף פעולה פיזי גרידא. מותר לעורך דין לחלוק משרד, קבלה, או מזכירה עם בעל מקצוע אחר, כל עוד נשמרת הפרדה מוחלטת בין תחומי העיסוק, אין שיתוף בהכנסות, ואין מצג שווא כלפי הציבור כאילו מדובר בשיתוף מקצועי. כלל 11(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי "עורך דין לא ישתף פעולה עם מי שאינו עורך דין באופן שיש בו כדי להטעות את הציבור או לפגוע בכבוד המקצוע". במקרה זה, שרה ודני מקפידים על הפרדה מוחלטת, ולכן פעילותם מותרת. ראו סעיף 58 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע.',
    'הנחה שגויה כי כל שיתוף פעולה פיזי עם מי שאינו עורך דין אסור, מבלי להבחין בין שיתוף מהותי (אסור) לשיתוף לוגיסטי (מותר, בתנאים).', '["שיתוף במקצוע", "שיתוף בהכנסות", "חוק לשכת עורכי הדין", "כללי אתיקה מקצועית", "הפרדה מהותית", "מצג שווא"]'::jsonb, '**וריאציה 1 — משרד משותף:** האם עו"ד יכול לחלוק משרד עם יועץ מס? ← כן, אם יש הפרדה מוחלטת ואין שיתוף בהכנסות או מצג שווא (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 2 — שיתוף בהכנסות:** האם מותר לעו"ד לשתף יועץ מס בהכנסותיו מן המקצוע? ← לא, אסור במפורש לפי סעיף 58 לחוק לשכת עורכי הדין.
**וריאציה 3 — קבלה משותפת:** האם קבלה משותפת עם בעל מקצוע אחר אסורה? ← לא בהכרח, כל עוד הלקוחות מודעים להפרדה ואין הטעיה (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 4 — מטרת האיסור:** מהי מטרת האיסור על שיתוף במקצוע? ← לשמור על עצמאות המקצוע, כבודו, ואי-הטעיית הציבור (סעיף 58 לחוק לשכת עורכי הדין, כלל 11(א) לכללי האתיקה).', 'שיתוף עו"ד עם מי שאינו עו"ד ← משרד משותף מותר בתנאים ← שיתוף בהכנסות/מקצוע אסור.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 58", "כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986: כלל 11(א)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן עצם קיומו של משרד משותף עם מי שאינו עורך דין אסור, גם אם יש הפרדה בהכנסות.', false, 'טענה זו שגויה. הפסיקה והכללים מאפשרים שיתוף פעולה פיזי, כל עוד נשמרת הפרדה מהותית ואין שיתוף במקצוע או בהכנסות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, אם הם מקפידים על הפרדה מוחלטת בין תחומי העיסוק, אינם משתפים בהכנסות, ומונעים מצג שווא של שיתוף מקצועי.', true, 'זוהי התשובה הנכונה. הפסיקה והכללים מאפשרים שיתוף פעולה פיזי (כגון משרד משותף) עם בעלי מקצוע אחרים, כל עוד נשמרת הפרדה מהותית ואין שיתוף במקצוע או בהכנסות, ואין מצג שווא של שיתוף מקצועי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, שכן קבלה משותפת ומזכירה אחת יוצרות מצג שווא של שיתוף מקצועי האסור על פי כללי האתיקה.', false, 'טענה זו שגויה. קבלה משותפת ומזכירה אחת אינן אסורות כשלעצמן, כל עוד הלקוחות מודעים להפרדה ואין מצג שווא של שיתוף מקצועי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם יועץ המס דני הוא גם עורך דין מוסמך במדינה אחרת.', false, 'טענה זו שגויה. סעיף 58 מתייחס למי שאינו עורך דין בישראל. מעמדו המקצועי במדינה אחרת אינו רלוונטי לעניין זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הרציונל מאחורי האיסור על שיתוף במקצוע',
    2, 'מהו הרציונל העיקרי העומד בבסיס האיסור על עורך דין לשתף במקצועו או בהכנסותיו מן המקצוע מי שאינו עורך דין?', 'שאלה זו בוחנת את ההבנה העמוקה של הרציונל האתי והציבורי העומד מאחורי האיסור על שיתוף במקצוע או בהכנסות עם מי שאינו עורך דין. היא מדגישה את חשיבות השמירה על עצמאות המקצוע, כבודו, ואמון הציבור.', 'האיסור הקבוע בסעיף 58 לחוק לשכת עורכי הדין נובע ממספר רציונלים מרכזיים. ראשית, הוא נועד לשמור על עצמאותו המקצועית של עורך הדין, ולוודא ששיקוליו המקצועיים לא יושפעו מאינטרסים זרים של מי שאינו כפוף לכללי האתיקה של עורכי הדין. שנית, האיסור נועד להגן על כבוד המקצוע ועל מעמדו הציבורי, ולמנוע מצב שבו עורך הדין יהפוך לכלי שרת בידי גורמים שאינם עורכי דין. שלישית, הוא נועד למנוע הטעיית הציבור, שעלול לחשוב כי הוא מקבל שירות משפטי מלא ואיכותי מעורך דין, בעוד שבפועל השירות ניתן על ידי גורם שאינו מוסמך או שאינו כפוף לכללי האתיקה. הרציונל המרכזי הוא להבטיח שהשירות המשפטי יינתן על ידי מי שהוסמך לכך, תוך שמירה על הסטנדרטים האתיים והמקצועיים הגבוהים הנדרשים מעורך דין. ראו נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע.',
    'התמקדות ברציונלים משניים או שגויים, במקום ברציונלים המרכזיים של עצמאות המקצוע, כבודו והגנה על הציבור.', '["סעיף 58 לחוק לשכת עורכי הדין", "עצמאות מקצועית", "כבוד המקצוע", "הגנה על הציבור", "אתיקה מקצועית", "שיתוף במקצוע"]'::jsonb, '**וריאציה 1 — עצמאות המקצוע:** מהי אחת המטרות המרכזיות של סעיף 58? ← לשמור על עצמאות מקצוע עריכת הדין (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 2 — כבוד המקצוע:** כיצד סעיף 58 מגן על כבוד המקצוע? ← מונע מצב שעו"ד יהפוך לכלי שרת בידי גורמים שאינם עו"ד (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 3 — הטעיית הציבור:** מהו החשש העיקרי בהטעיית הציבור? ← שהציבור יחשוב שהוא מקבל שירות משפטי מלא ממי שאינו מוסמך (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 4 — השפעות זרות:** מדוע חשוב למנוע השפעות זרות על שיקולי עו"ד? ← כדי להבטיח שעו"ד יפעל באופן עצמאי וללא ניגוד אינטרסים (נבו - המתמחה, אתיקה מקצועית).', 'רציונל סעיף 58 ← עצמאות + כבוד המקצוע + מניעת הטעיית הציבור.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 58", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'למנוע תחרות בלתי הוגנת בין עורכי דין לבעלי מקצועות אחרים.', false, 'טענה זו שגויה. מטרת האיסור אינה למנוע תחרות, אלא לשמור על עקרונות יסוד של מקצוע עריכת הדין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לשמור על עצמאות מקצוע עריכת הדין, כבודו, ועל אי-הטעיית הציבור בדבר אופי השירות המשפטי.', true, 'זוהי התשובה הנכונה. האיסור נועד להבטיח שעורך הדין יפעל באופן עצמאי, ללא השפעות זרות, ולמנוע מצג שווא כלפי הציבור לגבי הכישורים והאחריות המקצועית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'להבטיח שעורכי דין ירוויחו יותר מבעלי מקצועות אחרים.', false, 'טענה זו שגויה. מטרת האיסור אינה כלכלית גרידא, אלא אתית ומקצועית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'למנוע העלמת מס על ידי עורכי דין המשתפים פעולה עם בעלי מקצועות אחרים.', false, 'טענה זו שגויה. למרות ששיתוף פעולה עלול לעורר חששות מסוימים, מטרת האיסור אינה קשורה ישירות למניעת העלמת מס, אלא לעקרונות האתיקה המקצועית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שיתוף בהכנסות עם עורך דין זר',
    3, 'עו"ד יעל, חברת לשכת עורכי הדין בישראל, מעוניינת לשתף פעולה עם עו"ד ז''אן, עורך דין מוסמך בצרפת שאינו חבר לשכת עורכי הדין בישראל. הם מתכננים לפתוח משרד משותף ולשתף בהכנסות מתיקים בינלאומיים. האם שיתוף פעולה זה מותר?', 'שאלה זו בוחנת את היקף תחולתו של סעיף 58 לחוק לשכת עורכי הדין, ובפרט האם האיסור על שיתוף במקצוע או בהכנסות חל גם על שיתוף פעולה עם עורך דין זר שאינו חבר לשכת עורכי הדין בישראל. היא מדגישה את הפרשנות המרחיבה של המונח ''מי שאינו עורך דין''.', 'סעיף 58 לחוק לשכת עורכי הדין, התשכ"א-1961, אוסר על עורך דין לשתף במקצועו או בהכנסותיו מן המקצוע "מי שאינו עורך דין". המונח "מי שאינו עורך דין" מתייחס למי שאינו חבר לשכת עורכי הדין בישראל. לכן, גם אם עו"ד ז''אן הוא עורך דין מוסמך בצרפת, הוא נחשב "מי שאינו עורך דין" לצורך סעיף 58. שיתוף בהכנסות מתיקים בינלאומיים עם עורך דין זר אסור, שכן הדבר פוגע בעקרונות של עצמאות המקצוע וכבודו, ועלול להטעות את הציבור. לשכת עורכי הדין עמדה על כך שהאיסור חל גם על שיתוף פעולה עם עורכי דין זרים, אלא אם כן הם קיבלו רישיון לעסוק בעריכת דין בישראל. ראו סעיף 58 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע.',
    'הנחה שגויה כי מעמד מקצועי במדינה זרה מקנה פטור מהאיסור שבסעיף 58, או אי-הבנה של ההגדרה של "מי שאינו עורך דין" בהקשר הישראלי.', '["שיתוף במקצוע", "שיתוף בהכנסות", "עורך דין זר", "חוק לשכת עורכי הדין", "אתיקה מקצועית", "רישיון עריכת דין בישראל"]'::jsonb, '**וריאציה 1 — עו"ד זר ושותפות:** האם עו"ד ישראלי יכול לשתף בהכנסות עם עו"ד זר? ← לא, עו"ד זר נחשב "מי שאינו עורך דין" לצורך סעיף 58 לחוק לשכת עורכי הדין.
**וריאציה 2 — הגדרת "מי שאינו עו"ד":** מי נחשב "מי שאינו עורך דין" בהקשר של סעיף 58? ← כל מי שאינו חבר לשכת עורכי הדין בישראל (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 3 — תיקים בינלאומיים:** האם יש חריג לתיקים בינלאומיים? ← לא, האיסור חל גם על תיקים אלו אם יש שיתוף בהכנסות (נבו - המתמחה, אתיקה מקצועית).
**וריאציה 4 — רישיון ישראלי:** מהו התנאי היחיד לשיתוף בהכנסות עם עו"ד זר? ← שעו"ד הזר יקבל רישיון לעסוק בעריכת דין בישראל (נבו - המתמחה, אתיקה מקצועית).', 'שיתוף בהכנסות עם עו"ד זר ← אסור ← סעיף 58 לחוק לשכת עורכי הדין.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 58", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן עו"ד ז''אן הוא עורך דין מוסמך במדינה אחרת, ולכן האיסור שבסעיף 58 אינו חל עליו.', false, 'טענה זו שגויה. סעיף 58 מתייחס למי שאינו עורך דין בישראל, ללא קשר למעמדו המקצועי במדינה אחרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן סעיף 58 לחוק לשכת עורכי הדין אוסר על שיתוף בהכנסות עם מי שאינו עורך דין בישראל, גם אם הוא עורך דין מוסמך במדינה זרה.', true, 'זוהי התשובה הנכונה. האיסור שבסעיף 58 חל על כל מי שאינו חבר לשכת עורכי הדין בישראל, ללא קשר להסמכתו במדינות אחרות. שיתוף בהכנסות עם עו"ד זר אסור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם שיתוף הפעולה מוגבל לתיקים בינלאומיים בלבד.', false, 'טענה זו שגויה. תחום התיקים אינו משנה את תחולת האיסור על שיתוף בהכנסות עם מי שאינו עורך דין בישראל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן עו"ד ז''אן יקבל רישיון זמני לעסוק בעריכת דין בישראל.', false, 'טענה זו שגויה. קבלת רישיון זמני משנה את מעמדו של עו"ד ז''אן ל''עורך דין בישראל'', ואז האיסור לא יחול, אך השאלה מתייחסת למצב שבו הוא אינו כזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלכות הפרת האיסור על שיתוף',
    4, 'עו"ד דוד שיתף פעולה עם מתווך נדל"ן, והעביר לו 10% מכל שכר טרחה שקיבל מלקוחות שהופנו אליו על ידי המתווך. מהן ההשלכות המשפטיות והאתיות של פעולה זו?', 'שאלה זו עוסקת בהשלכות המעשיות של הפרת האיסור על שיתוף במקצוע או בהכנסות עם מי שאינו עורך דין. היא מדגישה כי הפרה זו אינה רק עניין תיאורטי, אלא עבירה אתית חמורה שעלולה לגרור סנקציות משמעתיות מצד לשכת עורכי הדין.', 'שיתוף בהכנסות מן המקצוע עם מי שאינו עורך דין, כגון מתווך נדל"ן, מהווה הפרה מובהקת של סעיף 58 לחוק לשכת עורכי הדין, התשכ"א-1961. הפרה זו נחשבת לעבירה אתית חמורה, ועורך הדין המפר אותה צפוי לעמוד לדין משמעתי בפני בתי הדין המשמעתיים של לשכת עורכי הדין. הסנקציות המשמעתיות יכולות לכלול אזהרה, נזיפה, השעיה זמנית מעיסוק במקצוע, ואף הוצאה לצמיתות מלשכת עורכי הדין, בהתאם לחומרת העבירה ונסיבותיה. מטרת הסנקציות היא להרתיע עורכי דין מלהפר את כללי האתיקה, לשמור על טוהר המקצוע ועל אמון הציבור. ראו סעיף 58 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן סעיף 61 לחוק לשכת עורכי הדין, תשכ"א-1961.',
    'הנחה שגויה כי הפרת כללי אתיקה היא עניין פנימי של הלשכה ללא השלכות משמעותיות, או אי-הכרת מגוון הסנקציות המשמעתיות.', '["שיתוף בהכנסות", "עבירה אתית", "דין משמעתי", "לשכת עורכי הדין", "סנקציות משמעתיות", "סעיף 58 לחוק לשכת עורכי הדין", "סעיף 61 לחוק לשכת עורכי הדין"]'::jsonb, '**וריאציה 1 — שיתוף עם מתווך:** האם תשלום אחוזים למתווך נדל"ן מותר? ← לא, זו הפרה של סעיף 58 לחוק לשכת עורכי הדין.
**וריאציה 2 — סנקציות משמעתיות:** מהן הסנקציות האפשריות על הפרת סעיף 58? ← אזהרה, נזיפה, השעיה, הוצאה לצמיתות (סעיף 61 לחוק לשכת עורכי הדין).
**וריאציה 3 — מטרת הסנקציות:** מהי מטרת הסנקציות המשמעתיות? ← להרתיע, לשמור על טוהר המקצוע ואמון הציבור.
**וריאציה 4 — חומרת העבירה:** האם שיתוף בהכנסות נחשב לעבירה חמורה? ← כן, זו הפרה מובהקת של עקרונות יסוד במקצוע (נבו - המתמחה, אתיקה מקצועית).', 'הפרת סעיף 58 ← עבירה אתית חמורה ← סנקציות משמעתיות.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 58, 61", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | שיתוף במקצוע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הפעולה אסורה, ועו"ד דוד צפוי לסנקציות משמעתיות מצד לשכת עורכי הדין.', true, 'זוהי התשובה הנכונה. שיתוף בהכנסות עם מי שאינו עורך דין מהווה עבירה אתית חמורה, ועורך הדין צפוי לעמוד לדין משמעתי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הפעולה מותרת, שכן מדובר בהפניית לקוחות לגיטימית.', false, 'טענה זו שגויה. תשלום אחוזים משכר הטרחה למתווך מהווה שיתוף בהכנסות, האסור על פי סעיף 58 לחוק לשכת עורכי הדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הפעולה אסורה, אך אין לה השלכות משפטיות או אתיות, אלא רק המלצה של ועדת האתיקה להימנע מכך.', false, 'טענה זו שגויה. מדובר באיסור חוקי ואתי מפורש, שהפרתו גוררת סנקציות משמעתיות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הפעולה מותרת, אם המתווך אינו עוסק בעריכת דין בעצמו.', false, 'טענה זו שגויה. דווקא העובדה שהמתווך אינו עורך דין היא זו שהופכת את שיתוף ההכנסות לאסור.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 10, '2022-W-S-Q10';
END
$$;

