-- classifier_note: Privacy Law (Section 5) criminal offense — no dedicated 'privacy' subtopic; general_part is the closest fit
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '0d0f0d92-3153-497d-8127-15debb94b384'::uuid;
  v_group_id uuid := 'c94113e3-2cfa-4e18-b0e2-82e8f7d2fffe'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '9433b046-ad9b-479f-b7bc-4a1b25ce4b90'::uuid;
  v_ang_1 uuid := '03b8f22a-415d-49e8-9fc9-9073582a2540'::uuid;
  v_ang_2 uuid := '4fd533be-c02d-4ae2-8368-5fc284846df3'::uuid;
  v_ang_3 uuid := 'f95c3ff1-302a-418c-a9a9-e8997f31f7f3'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q11';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 11, '2022-W-S-Q11';
