  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q11', v_chapter_id, v_subtopic_id, 'איזה מן המקרים הבאים עלול לעלות כדי עבירה פלילית בהתאם לחוק הגנת הפרטיות, התשמ"א – 1981?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 11}'::jsonb, 'השאלה עוסקת בעבירות פליליות של פגיעה בפרטיות לפי חוק הגנת הפרטיות, התשמ"א-1981, ובפרט בפרשנות התיבה "הטרדה אחרת" בסעיף 2(1) לחוק. היא בוחנת את גבולות האיסור הפלילי, את האיזון בין הזכות לפרטיות לבין חופש הביטוי, ואת ההבחנה בין סוגי פגיעות שונים.', 'חוק הגנת הפרטיות, התשמ"א-1981, קובע בסעיף 1 כי "לא יפגע אדם בפרטיות של זולתו ללא הסכמתו". סעיף 2 לחוק מפרט רשימה של מצבים המהווים פגיעה בפרטיות. סעיף 5 לחוק קובע כי "הפוגע במזיד בפרטיות זולתו, באחת הדרכים האמורות בסעיף 2(1), (3) עד (7) ו-(9) עד (11), דינו - מאסר 5 שנים". המקרה המתואר בסעיף ד'' בשאלה, של תליית שלט מחאה נגד עובדת ציבור הכולל את תמונתה ופרטיה האישיים מול בית מגוריה במטרה להפעיל עליה לחץ, נדון בהרחבה בהלכת לייבל (רע"פ 4743/20). בית המשפט העליון קבע כי מעשים כאלה עולים כדי "הטרדה אחרת" לפי סעיף 2(1) לחוק, ומהווים עבירה פלילית לפי סעיף 5 לחוק, כאשר הפגיעה נעשית במזיד. בית המשפט הדגיש כי מדובר במקרה קיצוני וחריג, שבו ההטרדה היא התכלית ולא המסר, וכי חופש הביטוי אינו החופש לרדת לחיי הזולת בביתו. לעומת זאת, פרסום תצלום גופת אדם (סעיף 2א) והאזנה אסורה (סעיף 2(2)) אינם נכללים ברשימת הסעיפים המפלילים שבסעיף 5. שידור מידי של תצלום נפגע אקראי (סעיף 2(4א)) נופל בגדר חריג מפורש בחוק ואינו מהווה פגיעה בפרטיות. ראו סעיף 5 לחוק הגנת הפרטיות, תשמ"א-1981, סעיף 2(1) לחוק הגנת הפרטיות, תשמ"א-1981, וכן רע"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022).', 'הטעות הנפוצה היא אי-הבחנה בין פגיעה בפרטיות המהווה עוולה אזרחית לבין פגיעה בפרטיות המהווה עבירה פלילית, וכן אי-הכרת החריגים והמגבלות הספציפיות הקבועות בחוק הגנת הפרטיות.',
    '["חוק הגנת הפרטיות", "עבירה פלילית", "הטרדה אחרת", "חופש הביטוי", "זכות לפרטיות", "עובד ציבור", "הלכת לייבל"]'::jsonb, '**וריאציה 1 — פרסום גופת נפטר:** האם פרסום תצלום גופת נפטר הוא עבירה פלילית? ← לא, סעיף 2א אינו נכלל בסעיף 5 לחוק הגנת הפרטיות.
**וריאציה 2 — האזנה אסורה:** האם האזנה אסורה היא עבירה פלילית לפי חוק הגנת הפרטיות? ← לא, אלא לפי חוק האזנת סתר.
**וריאציה 3 — שידור מידי של נפגע:** האם שידור מידי של תצלום נפגע אקראי הוא עבירה פלילית? ← לא, קיים חריג מפורש בסעיף 2(4א) לחוק הגנת הפרטיות.
**וריאציה 4 — מחאה מול בית עובד ציבור:** האם תליית שלט מחאה פוגעני מול בית עובד ציבור היא עבירה פלילית? ← כן, "הטרדה אחרת" לפי סעיף 2(1) ו-5 לחוק הגנת הפרטיות (הלכת לייבל).', 'עבירה פלילית של פגיעה בפרטיות ← רק במקרים מוגדרים בסעיף 5 לחוק הגנת הפרטיות ← תליית שלט מחאה פוגעני מול בית עובד ציבור היא "הטרדה אחרת" פלילית.', '["חוק הגנת הפרטיות, תשמ\"א-1981: סע'' 1, 2(1), 2(2), 2(4א), 2א, 5", "רע\"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022)", "נבו - המתמחה דיני נזיקין (2026) | פגיעה בפרטיות מהי", "נבו - המתמחה דיני נזיקין (2026) | פגיעה בפרטיות – עבירה", "מיכאל בירנהק פרטיות מידעית (2024) | 1. פגיעה במזיד בפרטיות"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Privacy Law (Section 5) criminal offense — no dedicated ''privacy'' subtopic; general_part is the closest fit | source_review_note: הסיווג לתת-נושא ''ערעור פלילי'' תחת ''סדר דין פלילי'' הוא הולם ביותר מבין האפשרויות הסגורות, שכן השאלה עוסקת בעבירה פלילית שפורשה בהרחבה בפסק דין של בית המשפט העליון במסגרת ערעור פלילי, והיא בוחנת את גבולות האחריות הפלילית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'פרסום ברבים של סרטון וידאו שבו נראית גופת אדם גלויה באופן שניתן לזהותה ללא הסכמתו לכך בחייו.', false, 'טענה זו שגויה. פרסום תצלום גופת אדם גלויה, גם אם ניתן לזהותה, אינו מהווה עבירה פלילית לפי סעיף 5 לחוק הגנת הפרטיות, שכן סעיף 2א לחוק אינו נכלל ברשימת הסעיפים המפלילים בסעיף 5.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'האזנה אסורה על פי חוק.', false, 'טענה זו שגויה. האזנה אסורה על פי חוק, למרות שהיא פגיעה בפרטיות לפי סעיף 2(2) לחוק הגנת הפרטיות, אינה מהווה עבירה פלילית לפי סעיף 5 לחוק זה, אלא לפי חוק האזנת סתר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'שידור מידי ברבים של תצלום של נפגע אקראי ברשות הרבים, שצולם באקראי בזמן הפגיעה, באופן שניתן לזהותו.', false, 'טענה זו שגויה. סעיף 2(4א) לחוק הגנת הפרטיות קובע חריג לפגיעה בפרטיות במקרה של פרסום תצלום של נפגע ברבים, כאשר מדובר בפרסום מידי וללא השהיות שאינו חורג מהסביר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'תליית שלט מחאה נגד עובדת ציבור, הכולל את תמונתה ופרטיה האישיים, מול בית מגוריה במטרה להפעיל עליה לחץ.', true, 'זוהי התשובה הנכונה. תליית שלטי מחאה פוגעניים הכוללים פרטים אישיים מזהים מול בית מגוריה של עובדת ציבור, במטרה להטריד ולהפעיל לחץ, מהווה "הטרדה אחרת" לפי סעיף 2(1) לחוק הגנת הפרטיות, ועלולה לעלות כדי עבירה פלילית לפי סעיף 5 לחוק, כפי שנקבע בהלכת לייבל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פגיעה בפרטיות עובד ציבור במקום עבודתו',
    1, 'ראובן, אזרח המוחה נגד מדיניות משרד הרווחה, תלה כרזות בגנות עובדת סוציאלית ראשית, א'', במקום עבודתה, משרד הרווחה. הכרזות כללו את שמה המלא, תמונתה ותיאורים פוגעניים על תפקודה המקצועי. האם מעשיו של ראובן עלולים לעלות כדי עבירה פלילית של פגיעה בפרטיות?', 'שאלה זו בוחנת את ההבחנה בין מחאה נגד עובד ציבור בביתו הפרטי לבין מחאה נגדו במקום עבודתו, בהקשר של עבירת פגיעה בפרטיות. היא מדגישה את האיזון בין הזכות לפרטיות לבין חופש הביטוי והמחאה, ואת חשיבות קיומה של חלופה אפקטיבית למחאה.', 'הלכת לייבל (רע"פ 4743/20) קבעה כי כאשר מדובר בזכות לפרטיות של עובד ציבור בביתו הפרטי, וכאשר קיימת חלופה אפקטיבית לקיום פעולת המחאה בקשר לתפקידו הציבורי של עובד הציבור (למשל: ליד מקום העבודה או ליד מוסדות ציבור), תגבר ההגנה על הזכות לפרטיות מפני פגיעה משמעותית. במקרה של מחאה במקום העבודה, חופש הביטוי והמחאה מקבלים משקל רב יותר, שכן זהו המקום הלגיטימי לביקורת על תפקודו הציבורי של עובד הציבור. בית המשפט הדגיש כי הפגיעה בחופש הביטוי והמחאה של מי שמבקש למחות דווקא בסמוך למעונו הפרטי של עובד הציבור היא מינימלית, וניתן לממש את זכות המחאה נגד עובד סוציאלי ליד משרד הרווחה או ליד מקום אחר בו העובד ממלא תפקידו הציבורי, ובכך להגשים במלואו את חופש הביטוי. לכן, מחאה במקום העבודה, גם אם היא כוללת פרטים מזהים וביקורת פוגענית, תיחשב פחות חמורה מבחינת הפגיעה בפרטיות מאשר מחאה בבית הפרטי, וסביר שלא תעלה כדי עבירה פלילית של פגיעה בפרטיות, אלא אם כן היא חורגת באופן קיצוני מהמקובל. ראו רע"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022), וכן בש"פ 813/05 ברוך מרזל נ'' מדינת ישראל (27.2.2005).',
    'הטעות הנפוצה היא אי-הבחנה בין המרחב הפרטי (הבית) למרחב הציבורי (מקום העבודה) בהקשר של איזון בין פרטיות לחופש ביטוי, והחלת אותם כללים על שני המצבים.', '["חוק הגנת הפרטיות", "הטרדה אחרת", "חופש הביטוי", "עובד ציבור", "מקום עבודה", "איזון זכויות", "הלכת לייבל"]'::jsonb, '**וריאציה 1 — מחאה בבית מול מחאה בעבודה:** האם מחאה נגד עובד ציבור בביתו הפרטי נבחנת כמו מחאה במקום עבודתו? ← לא, ההגנה על הפרטיות בבית חזקה יותר (רע"פ לייבל).
**וריאציה 2 — חלופה אפקטיבית:** מתי קיומה של חלופה אפקטיבית למחאה משפיע על האיזון? ← כאשר יש חלופה, ההגנה על הפרטיות בבית הפרטי גוברת (רע"פ לייבל).
**וריאציה 3 — חופש הביטוי במקום העבודה:** האם חופש הביטוי מוגן יותר במקום העבודה של עובד ציבור? ← כן, זהו המרחב הלגיטימי לביקורת על תפקודו הציבורי (רע"פ לייבל).
**וריאציה 4 — מטרת המחאה:** האם מטרת המחאה משנה? ← כן, אם ההטרדה היא התכלית ולא המסר, חופש הביטוי נסוג (רע"פ לייבל).', 'מחאה נגד עובד ציבור ← בבית פרטי: פגיעה חמורה בפרטיות ← במקום עבודה: מוגן יותר בחופש ביטוי.',
    '["רע\"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022)", "בש\"פ 813/05 ברוך מרזל נ'' מדינת ישראל (27.2.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שכן גם במקום העבודה קיימת לעובד ציבור זכות לפרטיות, והכרזות הפוגעניות מהוות "הטרדה אחרת".', false, 'טענה זו שגויה. למרות שקיימת זכות לפרטיות גם במקום העבודה, הפסיקה קבעה כי כאשר קיימת חלופה אפקטיבית לקיום המחאה, ההגנה על פרטיות עובד הציבור בביתו הפרטי גוברת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, שכן מקום העבודה הוא מרחב ציבורי, וביקורת על תפקוד עובד ציבור במסגרת תפקידו מוגנת על ידי חופש הביטוי.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי כאשר קיימת חלופה אפקטיבית לקיום פעולת המחאה בקשר לתפקידו הציבורי של עובד הציבור (למשל: ליד מקום העבודה), תגבר ההגנה על חופש הביטוי והמחאה, ופגיעה בפרטיות במקום זה תיחשב פחות חמורה מאשר בבית הפרטי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם הכרזות כללו פרטים אישיים שאינם קשורים לתפקודה המקצועי של העובדת.', false, 'טענה זו שגויה. למרות שפרסום פרטים אישיים שאינם קשורים לתפקיד מחמיר את הפגיעה, עצם המחאה במקום העבודה נבחנת אחרת ממחאה בבית הפרטי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן המחאה נמשכה זמן רב והפריעה באופן ניכר לעבודת המשרד.', false, 'טענה זו שגויה. משך המחאה והפרעה לעבודה הם שיקולים רלוונטיים, אך אינם המבחן המכריע להבחנה בין פגיעה בפרטיות במקום העבודה לבין פגיעה בפרטיות בבית הפרטי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני עזר לפרשנות "הטרדה אחרת"',
    2, 'מהם מבחני העזר הפרשניים שנקבעו בפסיקה, ובפרט בהלכת לייבל, לצורך תיחום גבולות העבירה של פגיעה בפרטיות בחלופה של "הטרדה אחרת" לפי סעיף 2(1) לחוק הגנת הפרטיות?', 'שאלה זו מתמקדת במבחנים הפרשניים שפיתחה הפסיקה, ובפרט בית המשפט העליון בהלכת לייבל, לצורך יישום העבירה הפלילית של פגיעה בפרטיות בחלופה של "הטרדה אחרת". היא מדגישה את הצורך בתיחום גבולותיה של עבירה בעלת "רקמה פתוחה" זו.', 'בית המשפט המחוזי, ובעקבותיו בית המשפט העליון בהלכת לייבל (רע"פ 4743/20), קבעו שני מבחני עזר פרשניים לצורך תיחום גבולות העבירה של פגיעה בפרטיות בחלופה של "הטרדה אחרת" בסעיף 2(1) לחוק הגנת הפרטיות: המבחן המהותי והמבחן ההסתברותי. המבחן המהותי בוחן האם יש פוטנציאל לפגיעה ניכרת בערכים המוגנים בעבירה (הזכות לפרטיות), תוך איזון עם ערכים מתחרים (כמו חופש הביטוי והמחאה). במסגרת זו נבחנים אופי הפרסום ותוכנו, תדירותו, מעמדם של המפרסם והנפגע, מידת הפומביות, אופן הפרסום ומקומו. המבחן ההסתברותי בוחן את רמת הסיכון לפגיעה בערכים המוגנים כחלק מנסיבות העבירה על פי אמת מידה נורמטיבית-אובייקטיבית. בית המשפט קבע כי לשם הפללתו של המעשה "המטריד" אין די בפוטנציאל לפגיעה ברף הנמוך בזכות לפרטיות, אלא נדרש פוטנציאל לפגיעה בעוצמה ניכרת. ראו רע"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022), וכן רע"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022).',
    'הטעות הנפוצה היא אי-הבנה של המורכבות בפרשנות עבירות בעלות "רקמה פתוחה" והצורך במבחנים אובייקטיביים-נורמטיביים, ולא רק סובייקטיביים.', '["חוק הגנת הפרטיות", "הטרדה אחרת", "עבירה פלילית", "מבחן מהותי", "מבחן הסתברותי", "רקמה פתוחה", "הלכת לייבל"]'::jsonb, '**וריאציה 1 — מבחנים ל"הטרדה אחרת":** מהם המבחנים שנקבעו לפרשנות "הטרדה אחרת"? ← מבחן מהותי והסתברותי (רע"פ לייבל).
**וריאציה 2 — המבחן המהותי:** מה בוחן המבחן המהותי? ← פוטנציאל לפגיעה ניכרת בערכים המוגנים, תוך איזון עם חופש הביטוי (רע"פ לייבל).
**וריאציה 3 — המבחן ההסתברותי:** מה בוחן המבחן ההסתברותי? ← רמת הסיכון לפגיעה בערכים המוגנים על פי אמת מידה אובייקטיבית (רע"פ לייבל).
**וריאציה 4 — רף הפגיעה הנדרש:** איזה רף פגיעה נדרש להפללת מעשה מטריד? ← פוטנציאל לפגיעה בעוצמה ניכרת, לא רק רף נמוך (רע"פ לייבל).', '"הטרדה אחרת" ← מבחן מהותי + מבחן הסתברותי ← פוטנציאל פגיעה ניכרת.',
    '["רע\"פ 4743/20 מרדכי לייבל נ'' מדינת ישראל (21.7.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן סובייקטיבי בלבד, הבוחן את תחושתו של הנפגע מהמעשה המטריד.', false, 'טענה זו שגויה. הפסיקה קבעה מבחנים אובייקטיביים-נורמטיביים, כאשר התחושה הסובייקטיבית של הנפגע מהווה אינדיקציה בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המבחן המהותי (הבוחן פוטנציאל לפגיעה ניכרת בערכים המוגנים) והמבחן ההסתברותי (הבוחן את רמת הסיכון לפגיעה בערכים המוגנים).', true, 'זוהי התשובה הנכונה. בית המשפט המחוזי, ובעקבותיו העליון בהלכת לייבל, קבעו שני מבחני עזר פרשניים: המבחן המהותי והמבחן ההסתברותי, אשר בהתקיימם יחד יחול האיסור הפלילי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן הכוונה הבלעדית של המטריד, האם התכוון לפגוע בפרטיות או למחות.', false, 'טענה זו שגויה. למרות שהיסוד הנפשי של "במזיד" דורש מודעות, הפסיקה התמקדה גם בתוצאה האובייקטיבית של המעשה ובפוטנציאל ההטרדה, ולא רק בכוונה הבלעדית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן תדירות המעשים בלבד, כאשר רק מעשים חוזרים ונשנים ייחשבו להטרדה.', false, 'טענה זו שגויה. הפסיקה קבעה כי גם משמרת מחאה חד-פעמית יכולה להשתכלל לעבירה של פגיעה בפרטיות, וכי היות המעשה "חד פעמי" אינו שולל את קיומה של העבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פגיעה בפרטיות של תאגיד',
    3, 'חברת "אלפא בע"מ" טוענת כי פרטיותה נפגעה עקב פרסום מידע מסחרי סודי אודותיה. האם חברת "אלפא בע"מ" יכולה להגיש תביעה בגין פגיעה בפרטיות לפי חוק הגנת הפרטיות?', 'שאלה זו בוחנת את היקף תחולתו של חוק הגנת הפרטיות, ובפרט את ההבחנה בין "אדם" לתאגיד לעניין הזכות לפרטיות. היא מדגישה כי חוק הגנת הפרטיות נועד להגן על פרטיותו של אדם בשר ודם בלבד.', 'חוק הגנת הפרטיות, התשמ"א-1981, נועד להגן על פרטיותו של "אדם" בשר ודם. סעיף 3 לחוק, בהגדרת המונח "אדם" לעניין סעיפים 2, 13, 14, 15א, 17ב, 17ב1, 17ב2, 17ו, 23ב, 23מו ו-25 וכן לעניין ההגדרות "דיוור ישיר", "מאגר מידע", "מזהה ביומטרי", "מידע אישי" ו"מידע בעל רגישות מיוחדת", קובע במפורש "למעט תאגיד". משמעות הדבר היא שלא ניתן לבצע עוולה אזרחית או עבירה פלילית של פגיעה בפרטיותו של תאגיד לפי חוק הגנת הפרטיות. תאגיד יכול להיפגע מפרסום לשון הרע (לפי חוק איסור לשון הרע), או מעוולות אחרות, אך לא מפגיעה בפרטיות כהגדרתה בחוק הגנת הפרטיות. ראו סעיף 3 לחוק הגנת הפרטיות, תשמ"א-1981, וכן נבו - המתמחה דיני נזיקין (2026) | הגדרת מונחים.',
    'הטעות הנפוצה היא להניח שזכות לפרטיות חלה באופן גורף גם על תאגידים, בדומה לזכויות אחרות כמו הזכות לשם טוב.', '["חוק הגנת הפרטיות", "תאגיד", "אדם", "הגדרת מונחים", "עוולה אזרחית", "עבירה פלילית"]'::jsonb, '**וריאציה 1 — פרטיות תאגיד:** האם תאגיד יכול להיפגע בפרטיותו לפי חוק הגנת הפרטיות? ← לא, החוק חל רק על אדם בשר ודם (סעיף 3 לחוק הגנת הפרטיות).
**וריאציה 2 — הגדרת "אדם" בחוק:** מהי ההגדרה של "אדם" לעניין חוק הגנת הפרטיות? ← למעט תאגיד (סעיף 3 לחוק הגנת הפרטיות).
**וריאציה 3 — לשון הרע לתאגיד:** האם תאגיד יכול לתבוע בגין לשון הרע? ← כן, חוק איסור לשון הרע חל גם על תאגידים (נבו - המתמחה, דיני נזיקין).
**וריאציה 4 — מידע מסחרי סודי:** האם מידע מסחרי סודי של תאגיד מוגן? ← כן, אך לא במסגרת חוק הגנת הפרטיות, אלא בחוקים אחרים כמו חוק סודות מסחריים.', 'חוק הגנת הפרטיות ← מגן על אדם בלבד ← לא על תאגיד.',
    '["חוק הגנת הפרטיות, תשמ\"א-1981: סע'' 3", "נבו - המתמחה דיני נזיקין (2026) | הגדרת מונחים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן גם לתאגיד יש זכות לפרטיות, במיוחד בכל הנוגע למידע מסחרי סודי.', false, 'טענה זו שגויה. חוק הגנת הפרטיות מגן על פרטיותו של "אדם" כהגדרתו בחוק, ואינו חל על תאגידים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן חוק הגנת הפרטיות חל רק על "אדם" כהגדרתו בחוק, למעט תאגיד, ולכן לא ניתן לבצע עוולה אזרחית או עבירה פלילית של פגיעה בפרטיותו של תאגיד.', true, 'זוהי התשובה הנכונה. סעיף 3 לחוק הגנת הפרטיות מגדיר "אדם" לעניין סעיפים מסוימים בחוק, ובמפורש קובע "למעט תאגיד". לכן, תאגיד אינו יכול להיפגע בפרטיותו לפי חוק זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם הפרסום נעשה במזיד ובכוונה לפגוע במוניטין של החברה.', false, 'טענה זו שגויה. גם אם הפרסום נעשה במזיד, חוק הגנת הפרטיות אינו חל על תאגידים. ייתכן שניתן לתבוע בגין לשון הרע או עוולות אחרות, אך לא פגיעה בפרטיות לפי חוק זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן המידע המסחרי הסודי מוגן גם על פי חוק סודות מסחריים.', false, 'טענה זו שגויה. הגנה על סודות מסחריים היא עניין נפרד מחוק הגנת הפרטיות, ואינה משנה את העובדה שחוק הגנת הפרטיות אינו חל על תאגידים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'קובלנה פלילית פרטית בגין פגיעה בפרטיות',
    4, 'דנה נפגעה בפרטיותה עקב פרסום תמונתה ברבים בנסיבות משפילות, והיא מעוניינת להגיש קובלנה פלילית נגד המפרסם. האם דנה רשאית להגיש קובלנה פלילית פרטית בגין עבירה זו?', 'שאלה זו עוסקת באפשרות להגיש קובלנה פלילית פרטית בגין עבירה של פגיעה בפרטיות. היא בוחנת את החריג לכלל לפיו המדינה היא המאשימה הבלעדית בהליכים פליליים, ואת התנאים להגשת קובלנה פרטית לפי חוק סדר הדין הפלילי.', 'על פי עקרונות היסוד של שיטת המשפט בישראל, המדינה היא הנושאת באחריות לאכיפת החוק הפלילי ולהבאת עבריינים לדין. אולם, קיים חריג מוכר לכלל זה והוא הקובלנה הפלילית הפרטית, המוסדרת בסעיפים 68 עד 73 לחוק סדר הדין הפלילי [נוסח משולב], התשמ"ב-1982. סעיף 68 לחוק קובע כי "על אף האמור בסעיף 11, רשאי כל אדם להאשים בעבירה מן המנויות בתוספת השניה על ידי הגשת קובלנה לבית המשפט". עבירות על חוק הגנת הפרטיות, התשמ"א-1981, ובפרט עבירות לפי סעיף 5 לחוק, נכללות בתוספת השנייה לחוק סדר הדין הפלילי (פסקה 13 לתוספת). לכן, דנה, שנפגעה בפרטיותה באופן המהווה עבירה פלילית לפי סעיף 5 לחוק הגנת הפרטיות, רשאית להגיש קובלנה פלילית פרטית נגד המפרסם. ראו חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982: תוספת שנייה, פסקה (13), וכן בג"ץ 4957/08 שורת הדין - Israel Law Center ועוד 159 אח'' נ'' היועץ המשפטי לממשלה (17.10.2010).',
    'הטעות הנפוצה היא לחשוב שכל העבירות הפליליות נתונות אך ורק לטיפול התביעה הכללית, מבלי להכיר בחריג של הקובלנה הפלילית הפרטית.', '["קובלנה פלילית פרטית", "חוק סדר הדין הפלילי", "חוק הגנת הפרטיות", "עבירה פלילית", "תוספת שנייה", "זכות נפגע עבירה"]'::jsonb, '**וריאציה 1 — הגשת קובלנה פרטית:** האם נפגע פגיעה בפרטיות יכול להגיש קובלנה פלילית פרטית? ← כן, עבירות לפי סעיף 5 לחוק הגנת הפרטיות נכללות בתוספת השנייה לחוק סדר הדין הפלילי.
**וריאציה 2 — תפקיד המדינה:** מי המאשימה העיקרית בהליך פלילי? ← המדינה, אך קובלנה פרטית היא חריג (בג"ץ שורת הדין).
**וריאציה 3 — רשימה סגורה:** האם רשימת העבירות לקובלנה פרטית היא סגורה? ← כן, מנויות בתוספת השנייה לחוק סדר הדין הפלילי (בג"ץ שורת הדין).
**וריאציה 4 — אופי העבירות:** מה מאפיין את העבירות המאפשרות קובלנה פרטית? ← לרוב בעלות יסוד דומיננטי של סכסוך פרטי בין פוגע לנפגע (בג"ץ שורת הדין).', 'פגיעה בפרטיות ← עבירה פלילית ← אפשרות לקובלנה פרטית.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982: סע'' 68, תוספת שנייה", "חוק הגנת הפרטיות, תשמ\"א-1981: סע'' 5", "בג\"ץ 4957/08 שורת הדין - Israel Law Center ועוד 159 אח'' נ'' היועץ המשפטי לממשלה (17.10.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן רק המדינה רשאית להגיש כתב אישום בגין עבירות פליליות, ופגיעה בפרטיות אינה חריג לכך.', false, 'טענה זו שגויה. למרות שהמדינה היא המאשימה העיקרית, קיימים חריגים המאפשרים הגשת קובלנה פלילית פרטית לעבירות מסוימות, ובכללן פגיעה בפרטיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, שכן עבירות לפי סעיף 5 לחוק הגנת הפרטיות נכללות בתוספת השנייה לחוק סדר הדין הפלילי, המאפשרת הגשת קובלנה פלילית פרטית.', true, 'זוהי התשובה הנכונה. סעיף 68 לחוק סדר הדין הפלילי קובע כי ניתן להגיש קובלנה פרטית לעבירות המנויות בתוספת השנייה, ועבירות על חוק הגנת הפרטיות (לפי סעיף 5) נכללות בתוספת זו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, אלא אם כן היועץ המשפטי לממשלה אישר את הגשת הקובלנה הפרטית.', false, 'טענה זו שגויה. אישור היועץ המשפטי לממשלה נדרש במקרים מסוימים, אך לא לעבירות המנויות בתוספת השנייה לחוק סדר הדין הפלילי, המאפשרות קובלנה פרטית ללא אישור כזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם הנזק שנגרם לדנה הוא נזק ממון משמעותי.', false, 'טענה זו שגויה. הזכות להגיש קובלנה פלילית פרטית אינה תלויה בהיקף נזק הממון, אלא בסיווג העבירה ככזו המאפשרת קובלנה פרטית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 11, '2022-W-S-Q11';
END
$$;

-- ============================================================
-- Q12 — 2022-W-S-Q12 — chapter=contracts subtopic=limitation
-- classifier_note: Solitary man, accident, lost consciousness, limitation period with incapacity (sec. 11 חוק ההתיישנות)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '70418cfe-d70a-4309-8e98-f62654834ef7'::uuid;
  v_group_id uuid := '14440a53-a7a6-4d74-bdab-53f925d1a8f2'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '3cc46793-c75d-44ed-88ea-61b0eaf7bf93'::uuid;
  v_ang_1 uuid := '59eb110c-d76b-40df-84f5-93b0ad4bea61'::uuid;
  v_ang_2 uuid := '231c26ae-d852-4211-b710-fa88b0d43352'::uuid;
  v_ang_3 uuid := 'a8db2dd2-ca17-4537-89c0-e604e4a15af2'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q12';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 12, '2022-W-S-Q12';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q12', v_chapter_id, v_subtopic_id, 'ג''ורג'', אדם ערירי ללא קרובי משפחה או חברים, עבר תאונה קשה בשנת 2013. בתאונה איבד את הכרתו מיד ברגע הפגיעה, ושב אליה רק בתחילת שנת 2014. כשהתעורר גילה כי שתי רגליו נקטעו. הרופאים אמרו לו שלא היה מנוס מכך. בשנת 2016 שמע ג''ורג'' באקראי עובד בבית החולים מספר שקטיעת הרגל הימנית הייתה מיותרת והדבר נעשה בשל רשלנות הצוות, שאף הוציא את המסמך המעיד על כך מהתיק הרפואי. ג''ורג'' מעוניין לתבוע את בית החולים. האם תביעתו של ג''ורג'' התיישנה?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 12}'::jsonb, 'השאלה עוסקת בכלל הגילוי המאוחר (סעיף 8 לחוק ההתיישנות) בתביעות נזיקין, ובפרט בתביעות רשלנות רפואית. היא בוחנת את ההבחנה בין גילוי מאוחר של הנזק עצמו לבין גילוי מאוחר של יסודות אחרים בעוולה (כמו התרשלות וקשר סיבתי), ואת השלכותיה על מניין תקופת ההתיישנות.', 'תקופת ההתיישנות הכללית לתביעה שאינה במקרקעין היא 7 שנים, והיא מתחילה ביום שבו נולדה עילת התביעה (סעיפים 5(1) ו-6 לחוק ההתיישנות). עם זאת, סעיף 8 לחוק ההתיישנות קובע חריג המכונה "כלל הגילוי המאוחר" או "התיישנות שלא מדעת". לפי כלל זה, אם נעלמו מן התובע העובדות המהוות את עילת התובענה, מסיבות שלא היו תלויות בו ושאף בזהירות סבירה לא יכול היה למנוע אותן, תתחיל תקופת ההתיישנות ביום שבו נודעו לתובע עובדות אלה. הפסיקה מבחינה בין גילוי מאוחר של הנזק עצמו, עליו חל סעיף 89(2) לפקודת הנזיקין עם מחסום 10 שנים מיום אירוע הנזק, לבין גילוי מאוחר של יתר רכיבי העוולה (כמו ההתרשלות או הקשר הסיבתי), עליהם חל סעיף 8 לחוק ההתיישנות ללא מחסום 10 השנים. במקרה של ג''ורג'', הנזק (קטיעת הרגליים) נודע לו בתחילת 2014. אולם, עובדות ההתרשלות והקשר הסיבתי (שקטיעת הרגל הימנית הייתה מיותרת ונגרמה ברשלנות) נודעו לו רק בשנת 2016. מכיוון שמדובר בגילוי מאוחר של רכיב ההתרשלות והקשר הסיבתי, חל סעיף 8 לחוק ההתיישנות. מרוץ ההתיישנות של 7 שנים יחל בשנת 2016, ולכן התביעה תתיישן בשנת 2023. ראו סעיף 8 לחוק ההתיישנות, תשי"ח-1958, וכן ע"א 4381/08 קופת חולים כללית נ'' אהרון מוסקוביץ (16.1.2012), וכן ת"א (מחוזי חי'') 25610-03-20 מוחמד מחאג''נה נ'' בנק הפועלים בע"מ (1.2.2022).', 'הטעות הנפוצה היא אי-הבחנה בין גילוי מאוחר של הנזק (הכפוף למחסום 10 השנים) לבין גילוי מאוחר של ההתרשלות או הקשר הסיבתי (שאינו כפוף למחסום זה), והחלת הכלל הלא נכון על המקרה.',
    '["התיישנות", "כלל הגילוי המאוחר", "סעיף 8 לחוק ההתיישנות", "רשלנות רפואית", "עילת תביעה", "גילוי נזק", "גילוי התרשלות"]'::jsonb, '**וריאציה 1 — גילוי מאוחר של התרשלות:** מתי מתחיל מרוץ ההתיישנות כשמתגלה רשלנות באיחור? ← ביום שבו נודעו לתובע עובדות ההתרשלות (סעיף 8 לחוק ההתיישנות).
**וריאציה 2 — מחסום 10 שנים:** האם מחסום 10 השנים חל על גילוי מאוחר של התרשלות? ← לא, הוא חל רק על גילוי מאוחר של הנזק עצמו (ת"א מחאג''נה).
**וריאציה 3 — ידיעה סובייקטיבית ואובייקטיבית:** מה נדרש כדי שכלל הגילוי המאוחר יחול? ← אי-ידיעה בפועל ואי-יכולת לדעת בזהירות סבירה (ע"א מוסקוביץ).
**וריאציה 4 — קצה חוט:** האם נדרשת ידיעה מלאה? ← לא, די ב"קצה חוט" או "חשד בכוח" כדי להתחיל את מרוץ ההתיישנות (ע"א מוסקוביץ).', 'גילוי מאוחר של התרשלות ← מרוץ התיישנות של 7 שנים מיום הגילוי ← ללא מחסום 10 שנים.', '["חוק ההתיישנות, תשי\"ח-1958: סע'' 8", "ע\"א 4381/08 קופת חולים כללית נ'' אהרון מוסקוביץ (16.1.2012)", "ת\"א (מחוזי חי'') 25610-03-20 מוחמד מחאג''נה נ'' בנק הפועלים בע\"מ (1.2.2022)", "ת\"א (מחוזי ת\"א) 4392-03-23 פלוני נ'' קופת חולים כללית (24.8.2023)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות שלא מדעת (כלל הגילוי המאוחר)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Solitary man, accident, lost consciousness, limitation period with incapacity (sec. 11 חוק ההתיישנות)', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'התביעה התיישנה בשנת 2020.', false, 'טענה זו שגויה. חישוב זה מתבסס ככל הנראה על כלל 10 השנים מיום אירוע הנזק, אך כלל זה חל רק על גילוי מאוחר של הנזק עצמו, ולא על גילוי מאוחר של ההתרשלות או הקשר הסיבתי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התביעה התיישנה בשנת 2021.', false, 'טענה זו שגויה. חישוב זה אינו תואם את כללי ההתיישנות הקבועים בחוק ההתיישנות ובפסיקה לעניין כלל הגילוי המאוחר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התביעה תתיישן בשנת 2023.', true, 'זוהי התשובה הנכונה. מרוץ ההתיישנות החל בשנת 2016, עם גילוי עובדות ההתרשלות והקשר הסיבתי, ולכן התביעה תתיישן בחלוף 7 שנים, כלומר בשנת 2023.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'התביעה תתיישן בשנת 2026.', false, 'טענה זו שגויה. חישוב זה אינו תואם את כללי ההתיישנות הקבועים בחוק ההתיישנות ובפסיקה לעניין כלל הגילוי המאוחר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הבחנה בין גילוי נזק לגילוי התרשלות',
    1, 'ראובן נחשף לחומר מסוכן במקום עבודתו בשנת 2000. בשנת 2008 החל לחוש בתסמינים מוזרים, ובשנת 2009 אובחן כחולה במחלה נדירה שנגרמה מחשיפה לחומר. מתי תתיישן תביעתו של ראובן נגד המעסיק?', 'שאלה זו בוחנת את ההבחנה בין כלל הגילוי המאוחר הכללי שבסעיף 8 לחוק ההתיישנות לבין כלל הגילוי המיוחד לנזקי גוף שבסעיף 89(2) לפקודת הנזיקין. היא מדגישה את מחסום 10 השנים החל על גילוי מאוחר של הנזק עצמו, בניגוד לגילוי מאוחר של יסודות אחרים בעוולה.', 'עוולת הרשלנות הרפואית באה בגדרו של סעיף 89(2) לפקודת הנזיקין, כאשר מרוץ ההתיישנות יפתח במועד אירוע הנזק. אולם, אם הנזק לא נתגלה במועד האירוע, יושעה מרוץ ההתיישנות עד לגילויו, ובלבד שהתביעה תתיישן בחלוף מחסום סופי של 10 שנים מהמעשה או המחדל שגרם לו. במקרה זה, אירוע הנזק (החשיפה לחומר) היה בשנת 2000. הנזק (המחלה) התגלה בשנת 2009. מרוץ ההתיישנות של 7 שנים יחל בשנת 2009, אך מחסום 10 השנים מיום אירוע הנזק (2000) יחול בשנת 2010. לכן, התביעה התיישנה בשנת 2010. חשוב להבחין כי סעיף 89(2) חל על גילוי מאוחר של רכיב הנזק בלבד, בעוד סעיף 8 לחוק ההתיישנות חל על גילוי מאוחר של יתר רכיבי העוולה (התרשלות, קשר סיבתי), ובמקרה כזה לא חל מחסום 10 השנים. ראו ת"א (מחוזי ת"א) 4392-03-23 פלוני נ'' קופת חולים כללית (24.8.2023), וכן רע"א 6614/19 מדינת ישראל נ'' שלמה ג''הסי (30.6.2021).',
    'הטעות הנפוצה היא אי-הבחנה בין גילוי מאוחר של הנזק (סעיף 89(2) לפקודת הנזיקין) לבין גילוי מאוחר של יסודות אחרים בעוולה (סעיף 8 לחוק ההתיישנות), והחלת מחסום 10 השנים באופן שגוי.', '["התיישנות", "כלל הגילוי המאוחר", "סעיף 89(2) לפקודת הנזיקין", "מחסום 10 שנים", "גילוי נזק", "רשלנות רפואית"]'::jsonb, '**וריאציה 1 — גילוי מאוחר של נזק:** מתי תתיישן תביעה אם הנזק התגלה באיחור? ← 7 שנים מיום הגילוי, אך לא יאוחר מ-10 שנים מיום אירוע הנזק (סעיף 89(2) לפקודת הנזיקין).
**וריאציה 2 — גילוי מאוחר של התרשלות:** מתי תתיישן תביעה אם ההתרשלות התגלתה באיחור? ← 7 שנים מיום גילוי ההתרשלות, ללא מחסום 10 השנים (סעיף 8 לחוק ההתיישנות).
**וריאציה 3 — מטרת מחסום 10 השנים:** מהי מטרת מחסום 10 השנים? ← לקבוע מחסום אחרון וסופי להתיישנות תביעות בהן הנזק מתגלה באיחור (ישראל גלעד, התיישנות בדין האזרחי).
**וריאציה 4 — תחילת מרוץ ההתיישנות:** מתי מתחיל מרוץ ההתיישנות בעוולת רשלנות רפואית? ← במועד אירוע הנזק, או במועד גילוי הנזק אם לא נתגלה במועד האירוע (סעיף 89(2) לפקודת הנזיקין).', 'גילוי מאוחר של נזק ← 7 שנים מיום הגילוי, עד 10 שנים מיום האירוע. גילוי מאוחר של התרשלות/קשר סיבתי ← 7 שנים מיום הגילוי, ללא מגבלת 10 שנים.',
    '["פקודת הנזיקין [נוסח חדש]: סע'' 89(2)", "חוק ההתיישנות, תשי\"ח-1958: סע'' 8", "רע\"א 6614/19 מדינת ישראל נ'' שלמה ג''הסי (30.6.2021)", "ת\"א (מחוזי ת\"א) 4392-03-23 פלוני נ'' קופת חולים כללית (24.8.2023)", "ישראל גלעד התיישנות בדין האזרחי (2022) | הבעייתיות שבהסדר הגילוי הנזיקי בסעיף 89(2) לפקודת הנזיקין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'התביעה התיישנה בשנת 2007 (7 שנים מיום החשיפה).', false, 'טענה זו שגויה. מרוץ ההתיישנות לא יכול להתחיל לפני גילוי הנזק, שכן הנזק הוא רכיב מהותי בעילת התביעה הנזיקית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'התביעה התיישנה בשנת 2010 (10 שנים מיום החשיפה).', true, 'זוהי התשובה הנכונה. במקרה של גילוי מאוחר של הנזק, סעיף 89(2) לפקודת הנזיקין קובע כי מרוץ ההתיישנות יחל ביום גילוי הנזק, אך התביעה תתיישן לכל המאוחר בחלוף 10 שנים מיום אירוע הנזק. מכיוון שהחשיפה (אירוע הנזק) הייתה בשנת 2000, התביעה התיישנה בשנת 2010.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'התביעה תתיישן בשנת 2016 (7 שנים מיום גילוי המחלה).', false, 'טענה זו שגויה. למרות שמרוץ ההתיישנות מתחיל ביום גילוי המחלה (2009), חל מחסום 10 השנים מיום אירוע הנזק (2000), ולכן התביעה התיישנה קודם לכן, בשנת 2010.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'התביעה תתיישן בשנת 2018 (10 שנים מיום גילוי המחלה).', false, 'טענה זו שגויה. מחסום 10 השנים בסעיף 89(2) לפקודת הנזיקין נמנה מיום אירוע הנזק, ולא מיום גילוי הנזק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן הידיעה בכלל הגילוי המאוחר',
    2, 'מהו המבחן לקביעת מועד תחילת מרוץ ההתיישנות לפי סעיף 8 לחוק ההתיישנות?', 'שאלה זו מתמקדת במבחנים הפרשניים של כלל הגילוי המאוחר הקבוע בסעיף 8 לחוק ההתיישנות. היא מדגישה את הצורך בשילוב של רכיב סובייקטיבי (אי-ידיעה בפועל) ורכיב אובייקטיבי (אי-יכולת לדעת בזהירות סבירה) לצורך הפעלת הכלל.', 'סעיף 8 לחוק ההתיישנות קובע כי מרוץ ההתיישנות יחל ביום שבו נודעו לתובע העובדות המהוות את עילת התובענה, וזאת בתנאי ש"נעלמו מן התובע העובדות המהוות את עילת התובענה, מסיבות שלא היו תלויות בו ושאף בזהירות סבירה לא יכול היה למנוע אותן". הפסיקה פירשה הוראה זו כדורשת קיומם של שני תנאים מצטברים: האחד, תנאי סובייקטיבי של אי-ידיעה בפועל של התובע על העובדות המהוות את עילת התביעה. השני, תנאי אובייקטיבי-נורמטיבי, לפיו אי-הידיעה נבעה מסיבות שלא היו תלויות בתובע, ושאף בזהירות סבירה לא יכול היה למנוע אותן. מבחן זה הוא של "האדם הסביר" בנסיבות העניין. אין די בחוסר ידיעה בפועל, אלא נדרש שהעובדות נעלמו מסיבות שלא היו תלויות בתובע ושאף בזהירות סבירה לא יכול היה למנוע אותן. ראו סעיף 8 לחוק ההתיישנות, תשי"ח-1958, וכן ע"א 4381/08 קופת חולים כללית נ'' אהרון מוסקוביץ (16.1.2012), וכן ת"א (מחוזי מרכז) 35346-07-23 פלוני נ'' בית חולים שיבא (24.8.2025).',
    'הטעות הנפוצה היא התמקדות באחד המבחנים (סובייקטיבי או אובייקטיבי) בלבד, במקום בשילוב הנדרש של שניהם.', '["התיישנות שלא מדעת", "כלל הגילוי המאוחר", "מבחן סובייקטיבי", "מבחן אובייקטיבי", "זהירות סבירה", "קצה חוט", "סעיף 8 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — אי-ידיעה בפועל:** האם די בכך שהתובע לא ידע בפועל? ← לא, נדרש גם שלא יכול היה לדעת בזהירות סבירה (סעיף 8 לחוק ההתיישנות).
**וריאציה 2 — מבחן האדם הסביר:** מהי אמת המידה ל"זהירות סבירה"? ← אמת מידה אובייקטיבית של האדם הסביר (ע"א מוסקוביץ).
**וריאציה 3 — קצה חוט:** האם נדרשת ידיעה ודאית? ← לא, די ב"קצה חוט" או "חשד בכוח" (ת"א שיבא).
**וריאציה 4 — נטל ההוכחה:** על מי מוטל הנטל להוכיח את תנאי סעיף 8? ← על התובע הטוען לתחולת החריג (ת"א שיבא).', 'סעיף 8 לחוק ההתיישנות ← אי-ידיעה סובייקטיבית + אי-יכולת לדעת אובייקטיבית בזהירות סבירה.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 8", "ע\"א 4381/08 קופת חולים כללית נ'' אהרון מוסקוביץ (16.1.2012)", "ת\"א (מחוזי מרכז) 35346-07-23 פלוני נ'' בית חולים שיבא (24.8.2025)", "ע\"א 5592765 פלונית נ'' קופת חולים כללית שרותי בריאות (21.10.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן סובייקטיבי בלבד, הבוחן האם התובע ידע בפועל על העובדות המהוות את עילת התביעה.', false, 'טענה זו שגויה. סעיף 8 כולל גם רכיב אובייקטיבי, הבוחן האם התובע יכול היה לדעת את העובדות בזהירות סבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן אובייקטיבי בלבד, הבוחן האם אדם סביר היה יכול לדעת את העובדות המהוות את עילת התביעה.', false, 'טענה זו שגויה. סעיף 8 כולל גם רכיב סובייקטיבי, הבוחן את אי-ידיעתו בפועל של התובע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'שילוב של מבחן סובייקטיבי (אי-ידיעה בפועל) ומבחן אובייקטיבי (אי-יכולת לדעת בזהירות סבירה).', true, 'זוהי התשובה הנכונה. סעיף 8 לחוק ההתיישנות דורש קיומם של שני תנאים מצטברים: אי-ידיעה בפועל של התובע, ואי-יכולת לדעת את העובדות בזהירות סבירה, לפי מבחן האדם הסביר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן של "קצה חוט" בלבד, ללא התייחסות לזהירות סבירה.', false, 'טענה זו שגויה. מבחן "קצה החוט" הוא חלק מהמבחן האובייקטיבי, אך אינו המבחן היחיד, והוא נבחן בהקשר של זהירות סבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אי-ידיעת הדין כעובדה נעלמה',
    3, 'ראובן נפגע בתאונת דרכים בשנת 2010. הוא ידע על נזקיו ועל נסיבות התאונה. בשנת 2018, לאחר שקרא מאמר משפטי, נודע לו על הלכה חדשה שמרחיבה את זכויותיהם של נפגעי תאונות דרכים במקרים מסוימים, והוא סבור שהלכה זו חלה על עניינו. האם מרוץ ההתיישנות יחל בשנת 2018 מכוח כלל הגילוי המאוחר?', 'שאלה זו בוחנת את גבולות תחולתו של כלל הגילוי המאוחר, ובפרט את ההבחנה בין אי-ידיעת עובדות לבין אי-ידיעת הדין. היא מדגישה כי אי-ידיעת הדין אינה מהווה עילה לדחיית מרוץ ההתיישנות, שכן הדין אינו נחשב ל"עובדה" לעניין סעיף 8 לחוק ההתיישנות.', 'כלל הגילוי המאוחר הקבוע בסעיף 8 לחוק ההתיישנות חל כאשר "נעלמו מן התובע העובדות המהוות את עילת התובענה". הפסיקה קבעה כי "הדין עצמו אינו אחד מ''העובדות המהוות את עילת התובענה''. לכן אי-ידיעת הדין או הסתמכות על דין ישן אינן דוחות את תחילת מרוץ ההתיישנות". במקרה זה, ראובן ידע על נזקיו ועל נסיבות התאונה כבר בשנת 2010. העובדה שנודע לו על הלכה חדשה בשנת 2018 אינה משנה את מועד תחילת מרוץ ההתיישנות, שכן מדובר בידיעת הדין ולא בידיעת עובדות מהותיות לעילת התביעה. לכן, מרוץ ההתיישנות החל בשנת 2010, והתביעה התיישנה בשנת 2017. ראו נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות שלא מדעת (כלל הגילוי המאוחר).',
    'הטעות הנפוצה היא לבלבל בין אי-ידיעת עובדות לבין אי-ידיעת הדין, ולהניח שכל סוג של אי-ידיעה דוחה את מרוץ ההתיישנות.', '["התיישנות", "כלל הגילוי המאוחר", "אי-ידיעת הדין", "עובדות מהותיות", "עילת תביעה", "סעיף 8 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — ידיעת הדין:** האם אי-ידיעת הדין דוחה את מרוץ ההתיישנות? ← לא, הדין אינו נחשב ל"עובדה" לעניין סעיף 8 (נבו - המתמחה, ירושה וברירת הדין).
**וריאציה 2 — הלכה חדשה:** האם גילוי הלכה חדשה דוחה את מרוץ ההתיישנות? ← לא, אם העובדות היו ידועות (נבו - המתמחה, ירושה וברירת הדין).
**וריאציה 3 — מועד תחילת מרוץ:** מתי יחל מרוץ ההתיישנות אם העובדות ידועות אך הדין לא? ← במועד שבו נולדה עילת התביעה על בסיס העובדות הידועות.
**וריאציה 4 — רציונל:** מדוע אי-ידיעת הדין אינה דוחה את ההתיישנות? ← כדי למנוע מצב שבו התובע שולט במועד תחילת מרוץ ההתיישנות (ע"א זוארס).', 'אי-ידיעת הדין ← לא דוחה התיישנות ← סעיף 8 חל על עובדות בלבד.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 8", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות שלא מדעת (כלל הגילוי המאוחר)", "ע\"א 1442/13 אליהו זוארס ואח'' נ'' התעשיה הצבאית ישראל בע\"מ (18.8.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן אי-ידיעת הדין היא עובדה נעלמה המצדיקה את דחיית מרוץ ההתיישנות.', false, 'טענה זו שגויה. הפסיקה קבעה כי אי-ידיעת הדין אינה נחשבת לעובדה נעלמה לצורך סעיף 8 לחוק ההתיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן אי-ידיעת הדין אינה נחשבת לעובדה המהווה את עילת התובענה לצורך סעיף 8 לחוק ההתיישנות.', true, 'זוהי התשובה הנכונה. כלל הגילוי המאוחר חל על עובדות מהותיות המהוות את עילת התביעה, אך אינו חל על אי-ידיעת הדין או הסתמכות על דין ישן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם ההלכה החדשה פורסמה רק בשנת 2018 ולא ניתן היה לדעת עליה קודם לכן.', false, 'טענה זו שגויה. גם אם ההלכה חדשה, ידיעת הדין אינה נחשבת לעובדה נעלמה לצורך סעיף 8.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן ראובן הוכיח שלא היה לו ייצוג משפטי עד שנת 2018.', false, 'טענה זו שגויה. היעדר ייצוג משפטי אינו משנה את העיקרון שאי-ידיעת הדין אינה דוחה את מרוץ ההתיישנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'כלל הגילוי המאוחר בתביעת תאגיד נגד נושאי משרה',
    4, 'חברת "אומגה בע"מ" גילתה בשנת 2020 כי דירקטורים שכיהנו בה בשנים 2010-2015 ביצעו מעשים שהסבו לחברה נזק כספי משמעותי. הדירקטורים המעורבים היו היחידים בחברה שידעו על המעשים בזמן אמת. מתי יחל מרוץ ההתיישנות בתביעת החברה נגד הדירקטורים?', 'שאלה זו עוסקת ביישום כלל הגילוי המאוחר (סעיף 8 לחוק ההתיישנות) במקרים מיוחדים של תביעת תאגיד נגד נושאי משרה בו. היא מדגישה את ההלכה לפיה ידיעת נושאי המשרה המעורבים אינה נחשבת לידיעת התאגיד לצורך מניין ההתיישנות, וכי מרוץ ההתיישנות יחל רק כאשר גורם "נקי כפיים" בתאגיד ידע או יכול היה לדעת על המעשים.', 'בפסיקה נקבע כי במקרים שבהם מדובר בתביעה של תאגיד נגד נושאי משרה בו, ידיעת נושאי המשרה הנתבעים על העובדות המקימות את עילת התביעה נגדם, אינה מהווה ידיעה שממועד התגבשותה תחל תקופת ההתיישנות. זאת, על מנת למנוע מצב שבו "חוטא יצא נשכר" וליתן מענה ל"בעיית הנציג" בדיני החברות. תקופת ההתיישנות של תביעת תאגיד נגד נושאי משרה בו תחל במועד שבו מעשיהם של נושאי המשרה הנתבעים נתגלו, או יכלו להתגלות בשקידה ראויה, לגורם רלוונטי אחר בתאגיד, כגון מנהלים נוספים ש"ידם לא הייתה במעל". במקרה זה, החברה גילתה את המעשים רק בשנת 2020, ועד אז הדירקטורים המעורבים היו היחידים שידעו. לכן, מרוץ ההתיישנות יחל בשנת 2020, ומשם תימנה תקופת ההתיישנות הרגילה של 7 שנים. ראו נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות שלא מדעת (כלל הגילוי המאוחר), וכן ישראל גלעד התיישנות בדין האזרחי (2022) | כלל הגילוי במצבים מיוחדים.',
    'הטעות הנפוצה היא להחיל את כלל הידיעה הרגיל על תאגידים, מבלי להתחשב ב"בעיית הנציג" ובצורך להגן על התאגיד מפני מעשי אורגנים "נגועים".', '["התיישנות", "כלל הגילוי המאוחר", "תאגיד", "נושאי משרה", "בעיית הנציג", "ידיעת התאגיד", "סעיף 8 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — ידיעת דירקטורים מעורבים:** האם ידיעת דירקטורים שביצעו מעשים אסורים נחשבת לידיעת החברה? ← לא, כדי למנוע "חוטא יצא נשכר" (נבו - המתמחה, ירושה וברירת הדין).
**וריאציה 2 — מועד תחילת מרוץ:** מתי יחל מרוץ ההתיישנות בתביעת חברה נגד דירקטורים? ← במועד שבו גורם "ידו לא הייתה במעל" ידע או יכול היה לדעת (ישראל גלעד, התיישנות בדין האזרחי).
**וריאציה 3 — גורם רלוונטי:** מי נחשב "גורם רלוונטי"? ← מנהלים נוספים, ועד רוכשים, ועדת ביקורת (ישראל גלעד, התיישנות בדין האזרחי).
**וריאציה 4 — רציונל ההלכה:** מהו הרציונל מאחורי הלכה זו? ← מתן מענה ל"בעיית הנציג" בדיני החברות והגנה על התאגיד (ישראל גלעד, התיישנות בדין האזרחי).', 'תביעת תאגיד נגד נושאי משרה ← מרוץ התיישנות יחל בגילוי ע"י גורם "נקי כפיים" בחברה.',
    '["חוק ההתיישנות, תשי\"ח-1958: סע'' 8", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות שלא מדעת (כלל הגילוי המאוחר)", "ישראל גלעד התיישנות בדין האזרחי (2022) | כלל הגילוי במצבים מיוחדים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בשנת 2010, שכן ידיעת הדירקטורים נחשבת לידיעת החברה.', false, 'טענה זו שגויה. במקרים של תביעת תאגיד נגד נושאי משרה, ידיעת הדירקטורים המעורבים אינה נחשבת לידיעת החברה לצורך מרוץ ההתיישנות, כדי למנוע מצב של "חוטא יצא נשכר".', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בשנת 2015, עם סיום כהונתם של הדירקטורים המעורבים.', false, 'טענה זו שגויה. סיום כהונתם אינו בהכרח המועד שבו גורם "ידו לא הייתה במעל" ידע או יכול היה לדעת על המעשים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בשנת 2020, שכן רק אז גורם בחברה ש"ידו לא הייתה במעל" ידע על המעשים.', true, 'זוהי התשובה הנכונה. במקרים של תביעת תאגיד נגד נושאי משרה, מרוץ ההתיישנות יחל רק במועד שבו גורם רלוונטי בחברה, שידו לא הייתה במעל, ידע או יכול היה לדעת על העובדות המקימות את עילת התביעה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בשנת 2027, בחלוף 7 שנים מיום גילוי המעשים על ידי החברה.', false, 'טענה זו שגויה. מרוץ ההתיישנות יחל בשנת 2020, ולכן התביעה תתיישן בשנת 2027, אך השאלה היא מתי יחל מרוץ ההתיישנות, והוא יחל בשנת 2020.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 12, '2022-W-S-Q12';
END
$$;

