-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'ead3cda1-e465-4ddf-9030-2e4e1f0229ba'::uuid;
  v_group_id uuid := '627cbb32-4920-481e-8316-4cb9aaa954a9'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '20201052-64d4-47fe-a0a0-7910753ab44b'::uuid;
  v_ang_1 uuid := '4c5985eb-839a-41b9-8bc3-8042277928b9'::uuid;
  v_ang_2 uuid := 'a1cfbfe0-ce58-45ba-a429-4342e0a943be'::uuid;
  v_ang_3 uuid := '95f82937-5432-4ae1-9d7c-9535e6289dba'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q15';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 15, '2022-W-S-Q15';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'administrative';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'administrative';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'constitutional_rights' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'constitutional_rights', 'administrative';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q15', v_chapter_id, v_subtopic_id, 'מי רשאית להיות מועמדת לכהונת נשיאת המדינה?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 15}'::jsonb, 'השאלה עוסקת בתנאי הכשירות לכהונת נשיא המדינה, כפי שנקבעו בחוק-יסוד: נשיא המדינה. היא בוחנת את הדרישות הבסיסיות של אזרחות ותושבות ישראלית, ומדגישה כי אין דרישת גיל ספציפית לתפקיד זה.', 'סעיף 4 לחוק-יסוד: נשיא המדינה קובע במפורש כי "כל אזרח ישראלי שהוא תושב ישראל כשיר להיות מועמד לכהונת נשיא המדינה." הוראה זו מציבה שני תנאי סף מצטברים: אזרחות ישראלית ותושבות ישראל. בניגוד לתפקידים ציבוריים אחרים, כמו חבר כנסת (שדורש גיל 21 ומעלה), חוק-יסוד: נשיא המדינה אינו קובע דרישת גיל מינימלית ספציפית. כמו כן, נשיא המדינה מכהן תקופת כהונה אחת בלבד של 7 שנים, ולכן הנשיא היוצא אינו כשיר להיות מועמד שוב. ראו סעיף 4 לחוק-יסוד: נשיא המדינה, וכן סעיף 3(ב) לחוק-יסוד: נשיא המדינה, וכן נבו - המתמחה חוקי יסוד (2026) | חוק-יסוד: נשיא המדינה.', 'הטעות הנפוצה היא להחיל דרישות כשירות מתפקידים ציבוריים אחרים (כגון דרישת גיל) על מועמדים לנשיאות, או להתעלם מאחד מתנאי הסף הקבועים בחוק-יסוד: נשיא המדינה.',
    '["נשיא המדינה", "חוק-יסוד: נשיא המדינה", "כשירות לכהונה", "אזרחות ישראלית", "תושבות ישראל", "תקופת כהונה"]'::jsonb, '**וריאציה 1 — כשירות לנשיאות:** מי כשיר להיות מועמד לנשיא המדינה? ← כל אזרח ישראלי שהוא תושב ישראל (סעיף 4 לחוק-יסוד: נשיא המדינה).
**וריאציה 2 — גיל לנשיאות:** האם יש דרישת גיל מינימלית לנשיא המדינה? ← לא, בניגוד לחבר כנסת (נבו - המתמחה, חוקי יסוד, עמ'' 58).
**וריאציה 3 — אזרחות כפולה:** האם אזרחות כפולה פוסלת מועמדות לנשיאות? ← לא, כל עוד הוא אזרח ישראלי ותושב ישראל (סעיף 4 לחוק-יסוד: נשיא המדינה).
**וריאציה 4 — תקופת כהונה:** כמה תקופות כהונה יכול נשיא לכהן? ← תקופת כהונה אחת בלבד (סעיף 3(ב) לחוק-יסוד: נשיא המדינה).', 'נשיא המדינה ← אזרח ישראלי + תושב ישראל ← אין דרישת גיל ספציפית.', '["חוק-יסוד: נשיא המדינה: סע'' 3(ב), 4", "נבו - המתמחה חוקי יסוד (2026) | ג. חוקי יסוד שעניינם סמכויות שלטון והיחסים בין הרשויות", "אהרן ברק חוק-יסוד: כבוד האדם וחירותו וחוק-יסוד: חופש העיסוק - כרך ג - זכויות חוקתיות (2023) | פרק חמישי יציאה מישראל וכניסה אליה"]'::jsonb,
    'classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''ביטול סמכות בג"ץ'' → mapped chapter=''administrative'' subtopic=''constitutional_rights'' | classifier_note: Presidential candidate eligibility (Basic Law: The President) — constitutional governance | source_review_note: הסיווג לתת-נושא ''ביטול סמכות בג"ץ'' תחת ''חוקתי + בינלאומי פרטי'' הוא הולם ביותר מבין האפשרויות הסגורות, שכן השאלה עוסקת בתנאי כשירות לכהונה חוקתית, נושאים הנמצאים בליבת המשפט החוקתי ופעמים רבות נבחנים בבג"ץ. למרות שהשאלה אינה עוסקת ישירות ב''ביטול סמכות בג"ץ'', היא נוגעת לגבולות הסמכות של הרשויות בהקשר חוקתי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'נשיאת המדינה היוצאת.', false, 'טענה זו שגויה. נשיא המדינה מכהן תקופת כהונה אחת בלבד, ולכן הנשיא היוצא אינו כשיר להיות מועמד שוב.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כל אזרחית ישראל.', false, 'טענה זו שגויה. בנוסף לדרישת האזרחות, נדרשת גם תושבות ישראל.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כל אזרחית ישראל שהיא תושבת ישראל.', true, 'זוהי התשובה הנכונה. סעיף 4 לחוק-יסוד: נשיא המדינה קובע כי כל אזרח ישראלי שהוא תושב ישראל כשיר להיות מועמד לכהונת נשיא המדינה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כל אזרחית ישראל שהיא תושבת ישראל שחצתה את גיל 21.', false, 'טענה זו שגויה. חוק-יסוד: נשיא המדינה אינו קובע דרישת גיל מינימלית למועמד לנשיאות, בניגוד לדרישת הגיל לחבר כנסת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תנאי כשירות לכהונת שר',
    1, 'מי כשיר להתמנות לשר בממשלת ישראל?', 'שאלה זו בוחנת את תנאי הכשירות הבסיסיים לכהונת שר בממשלת ישראל, כפי שנקבעו בחוק-יסוד: הממשלה. היא מדגישה את הדרישות המצטברות של אזרחות ותושבות ישראלית.', 'סעיף 6(א) לחוק-יסוד: הממשלה קובע במפורש כי "לא יתמנה לשר מי שאינו אזרח ישראלי ותושב ישראל". הוראה זו מציבה שני תנאי סף מצטברים לכהונת שר: אזרחות ישראלית ותושבות ישראלית. בנוסף, קיימות הגבלות נוספות בסעיף 6 לחוק-יסוד: הממשלה, כגון אי-כהונה במשרות מסוימות (סעיף 6(ב)), תנאים לגבי אזרחות נוספת (סעיף 6(ד)) והגבלות עקב עבר פלילי (סעיף 6(ג)). אולם, תנאי הסף הבסיסיים הם אזרחות ותושבות. ראו סעיף 6(א) לחוק-יסוד: הממשלה, וכן נבו - המתמחה חוקי יסוד (2026) | תנאי כשירות של חברי כנסת וחברי ממשלה*.',
    'הטעות הנפוצה היא להתעלם מאחד מתנאי הסף (אזרחות או תושבות) או להוסיף תנאים שאינם קבועים בחוק באופן מוחלט.', '["שר בממשלה", "חוק-יסוד: הממשלה", "כשירות לכהונה", "אזרחות ישראלית", "תושבות ישראל", "תנאי סף"]'::jsonb, '**וריאציה 1 — כשירות לשר:** מי כשיר להתמנות לשר? ← אזרח ישראלי ותושב ישראל (סעיף 6(א) לחוק-יסוד: הממשלה).
**וריאציה 2 — משרות נוספות:** האם שר יכול לכהן במשרה נוספת? ← לא יתמנה לשר מי שמכהן במשרה המפורטת בסעיף 7 לחוק-יסוד: הכנסת, אלא אם חדל לכהן בה (סעיף 6(ב) לחוק-יסוד: הממשלה).
**וריאציה 3 — אזרחות נוספת:** האם אזרחות נוספת פוסלת? ← לא יתמנה לשר מי שהוא בעל אזרחות שאינה ישראלית, אם דיני המדינה שהוא אזרח שלה מאפשרים את שחרורו מאזרחות זו, אלא לאחר שעשה את כל הדרוש מצדו לשם שחרורו ממנה (סעיף 6(ד) לחוק-יסוד: הממשלה).
**וריאציה 4 — עבר פלילי:** האם עבר פלילי פוסל? ← לא יתמנה לשר מי שהורשע בעבירה ונידון למאסר בפועל וטרם עברו 7 שנים, אלא אם יו"ר ועדת הבחירות המרכזית קבע שאין קלון (סעיף 6(ג) לחוק-יסוד: הממשלה).', 'שר ← אזרח ישראלי + תושב ישראל ← יש הגבלות על משרות נוספות, אזרחות נוספת ועבר פלילי.',
    '["חוק-יסוד: הממשלה: סע'' 6", "נבו - המתמחה חוקי יסוד (2026) | ג. חוקי יסוד שעניינם סמכויות שלטון והיחסים בין הרשויות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כל אזרח ישראלי ותושב ישראל.', true, 'זוהי התשובה הנכונה. סעיף 6(א) לחוק-יסוד: הממשלה קובע כי לא יתמנה לשר מי שאינו אזרח ישראלי ותושב ישראל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כל אזרח ישראלי, גם אם אינו תושב ישראל.', false, 'טענה זו שגויה. תושבות ישראל היא תנאי כשירות הכרחי לכהונת שר, בנוסף לאזרחות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כל אזרח ישראלי ותושב ישראל, שאינו מכהן במשרה ציבורית אחרת.', false, 'טענה זו שגויה. סעיף 6(ב) לחוק-יסוד: הממשלה קובע הגבלות על משרות מסוימות, אך לא על כל משרה ציבורית אחרת באופן גורף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כל אזרח ישראלי ותושב ישראל, שאינו בעל אזרחות נוספת.', false, 'טענה זו שגויה. סעיף 6(ד) לחוק-יסוד: הממשלה קובע תנאים לגבי אזרחות נוספת, אך אינו פוסל אותה באופן מוחלט אם לא ניתן לוותר עליה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן "קלון" בכהונה ציבורית',
    2, 'מהו המבחן לקביעת קלון בעבירה לצורך פסילת מועמד לכהונה ציבורית?', 'שאלה זו עוסקת במבחן המשפטי לקביעת "קלון" בעבירה, שהוא גורם מכריע בפסילת מועמדים לכהונה ציבורית. היא מדגישה את אופיו המוסרי-ערכי של מבחן הקלון ואת חשיבותו לשמירה על טוהר המידות ואמון הציבור.', 'הפסיקה קבעה כי "הקלון" המצדיק הגבלת כשירותו של אדם לכהן במשרה ציבורית הוא דופי מוסרי הדבק במעשהו, הפוגם ביכולתו לשאת באחריות הנדרשת במילוי התפקיד, הן בשל הפגיעה במעמדו הערכי והן עקב הפגיעה הצפויה באמון הציבור במשרה ובנושא המשרה, ואף במערכת הציבורית כולה. מבחן זה אינו טכני אלא מהותי, ודורש בחינה של נסיבות העבירה, מהותה, חומרתה והשלכותיה על תפקודו של המועמד בתפקיד הציבורי ועל אמון הציבור. ראו בג"ץ 5853/07 אמונה תנועת האישה הדתית לאומית נ'' ראש הממשלה, אהוד אולמרט (6.12.2007), וכן נבו - המתמחה דיני עונשין - כרך ג: הענישה הפלילית (2022) | הנפקות לקיומו של קלון בעבירה.',
    'הטעות הנפוצה היא להתמקד רק בהיבטים הפורמליים של העבירה (כגון סוג העבירה או העונש) במקום בבחינה המהותית של הדופי המוסרי והפגיעה באמון הציבור.', '["קלון", "טוהר המידות", "אמון הציבור", "כשירות לכהונה ציבורית", "עבירה פלילית", "מבחן אובייקטיבי"]'::jsonb, '**וריאציה 1 — הגדרת קלון:** מהו קלון בהקשר של כהונה ציבורית? ← דופי מוסרי הדבק במעשה, הפוגם ביכולת לשאת באחריות ובאמון הציבור (בג"ץ אמונה, פסקה 15).
**וריאציה 2 — מבחן אובייקטיבי:** האם המבחן לקלון הוא סובייקטיבי? ← לא, זהו מבחן אובייקטיבי-נורמטיבי המתייחס לטוהר המידות ואמון הציבור (בג"ץ אמונה, פסקה 15).
**וריאציה 3 — השלכות קלון:** מהן ההשלכות של קביעת קלון? ← פסילת כשירות לכהונה ציבורית, לעיתים לפרק זמן ממושך או לצמיתות (נבו - המתמחה, דיני עונשין, עמ'' 7).
**וריאציה 4 — סמכות קביעת קלון:** מי קובע אם יש קלון? ← בית המשפט, או יו"ר ועדת הבחירות המרכזית במקרים מסוימים (סעיף 6(ג) לחוק-יסוד: הממשלה).', 'קלון ← דופי מוסרי במעשה ← פוגע באחריות וביכולת לתפקיד ציבורי ובאמון הציבור.',
    '["בג\"ץ 5853/07 אמונה תנועת האישה הדתית לאומית נ'' ראש הממשלה, אהוד אולמרט (6.12.2007)", "נבו - המתמחה דיני עונשין - כרך ג: הענישה הפלילית (2022) | הנפקות לקיומו של קלון בעבירה", "חוק-יסוד: הממשלה: סע'' 6(ג)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן סובייקטיבי בלבד, הבוחן את תחושת הציבור הספציפי כלפי העבירה.', false, 'טענה זו שגויה. מבחן הקלון אינו סובייקטיבי אלא אובייקטיבי-נורמטיבי, הבוחן את הדופי המוסרי של המעשה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן אובייקטיבי, הבוחן את הדופי המוסרי הדבק במעשה, הפוגם ביכולת לשאת באחריות הנדרשת בתפקיד ציבורי ובאמון הציבור.', true, 'זוהי התשובה הנכונה. קלון הוא דופי מוסרי הדבק במעשה, הפוגם ביכולת המועמד לשאת באחריות הנדרשת בתפקיד ציבורי ופוגע באמון הציבור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן טכני, הבוחן רק את סוג העבירה וחומרת העונש שנקבע בחוק.', false, 'טענה זו שגויה. למרות שסוג העבירה וחומרת העונש נלקחים בחשבון, המבחן אינו טכני בלבד אלא מהותי וערכי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן של בית המשפט בלבד, ללא התייחסות לשיקולי הרשות הממנה.', false, 'טענה זו שגויה. הרשות הממנה חייבת להפעיל שיקול דעת עצמאי בנוסף לתנאי הכשירות הפורמליים, ובית המשפט מפקח על סבירות שיקול דעתה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חסינות נשיא המדינה מביקורת שיפוטית',
    3, 'האם ניתן לתבוע את נשיא המדינה בבית משפט בגין פעולה הקשורה לתפקידיו או סמכויותיו?', 'שאלה זו בוחנת את היקף החסינות המוקנית לנשיא המדינה בגין פעולותיו במסגרת תפקידו. היא מדגישה את ההבחנה בין חסינות מפני תקיפה ישירה לבין האפשרות לביקורת שיפוטית עקיפה על חוקיות פעולותיו.', 'סעיף 13(א) לחוק-יסוד: נשיא המדינה קובע כי "לא ייתן נשיא המדינה את הדין לפני כל בית-משפט או בית-דין בשל דבר הקשור בתפקידיו או בסמכויותיו, ויהיה חסין בפני כל פעולה משפטית בשל דבר כזה." זוהי חסינות מהותית, החלה גם לאחר סיום כהונתו. עם זאת, הפסיקה קבעה כי למרות החסינות המוקנית לנשיא מפני תקיפה ישירה של פעולותיו, אין מניעה לתקוף את חוקיות פעולותיו באופן עקיף. כלומר, מעשיו של הנשיא בתחום המשפט אינם מעל למשפט ונתונים לביקורת שיפוטית. ראו סעיף 13(א) לחוק-יסוד: נשיא המדינה, וכן בג"ץ 9631/07 משה כץ נ'' נשיא המדינה (14.4.2008).',
    'הטעות הנפוצה היא להניח שהחסינות המוקנית לנשיא היא מוחלטת ומונעת כל ביקורת שיפוטית, מבלי להבחין בין תקיפה ישירה לתקיפה עקיפה.', '["נשיא המדינה", "חסינות מהותית", "ביקורת שיפוטית", "חוק-יסוד: נשיא המדינה", "תקיפה ישירה", "תקיפה עקיפה"]'::jsonb, '**וריאציה 1 — חסינות ישירה:** האם ניתן לתבוע את הנשיא ישירות על פעולה בתפקיד? ← לא, הוא חסין מפני תביעה ישירה (סעיף 13(א) לחוק-יסוד: נשיא המדינה).
**וריאציה 2 — ביקורת עקיפה:** האם ניתן לתקוף את חוקיות פעולותיו של הנשיא? ← כן, באופן עקיף, שכן מעשיו אינם מעל החוק (בג"ץ כץ).
**וריאציה 3 — חסינות דיונית:** האם הנשיא יכול להיות מובא לדין פלילי במהלך כהונתו? ← לא, הוא נהנה מחסינות דיונית (סעיף 14 לחוק-יסוד: נשיא המדינה).
**וריאציה 4 — חתימת קיום:** האם חתימת הנשיא על מסמך רשמי דורשת חתימת קיום? ← כן, בדרך כלל נדרשת חתימת קיום של ראש הממשלה או שר (סעיף 12 לחוק-יסוד: נשיא המדינה).', 'נשיא המדינה ← חסינות מהותית מתביעה ישירה על פעולות בתפקיד ← ביקורת שיפוטית עקיפה אפשרית.',
    '["חוק-יסוד: נשיא המדינה: סע'' 12, 13(א), 14", "בג\"ץ 9631/07 משה כץ נ'' נשיא המדינה (14.4.2008)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, ניתן לתבוע אותו במישרין, אך רק בבית המשפט העליון.', false, 'טענה זו שגויה. נשיא המדינה נהנה מחסינות מהותית מפני תביעה ישירה בגין פעולות הקשורות לתפקידיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, נשיא המדינה נהנה מחסינות מהותית מפני תביעה ישירה בגין פעולות הקשורות לתפקידיו, אך ניתן לתקוף את חוקיות פעולותיו באופן עקיף.', true, 'זוהי התשובה הנכונה. סעיף 13(א) לחוק-יסוד: נשיא המדינה מקנה לנשיא חסינות מהותית, אך הפסיקה קבעה שניתן לתקוף את חוקיות פעולותיו באופן עקיף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק לאחר סיום כהונתו, ובאישור היועץ המשפטי לממשלה.', false, 'טענה זו שגויה. החסינות המהותית חלה גם לאחר סיום הכהונה, ואינה תלויה באישור היועץ המשפטי לממשלה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, נשיא המדינה חסין לחלוטין מכל תביעה משפטית, הן במישרין והן בעקיפין.', false, 'טענה זו שגויה. למרות החסינות המהותית, פעולותיו של הנשיא אינן מעל החוק ונתונות לביקורת שיפוטית עקיפה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תנאי כשירות לתפקידים ציבוריים אחרים',
    4, 'מהם תנאי הכשירות העיקריים לכהונת מבקר המדינה?', 'שאלה זו בוחנת את תנאי הכשירות לכהונת מבקר המדינה, כפי שנקבעו בחוק-יסוד: מבקר המדינה. היא מדגישה את הדרישות הבסיסיות של אזרחות ותושבות, ואת האפשרות לקבוע תנאים נוספים בחוק רגיל.', 'סעיף 8 לחוק-יסוד: מבקר המדינה קובע כי "כל אזרח ישראלי שהוא תושב ישראל כשיר להיות מועמד לכהונת מבקר המדינה; חוק יכול שיקבע תנאי כשירות נוספים." מכאן שתנאי הסף הם אזרחות ישראלית ותושבות ישראל. המחוקק המכונן השאיר פתח לקביעת תנאי כשירות נוספים בחוק רגיל, ככל שיידרש. חשוב לציין כי תפקידים ציבוריים שונים דורשים תנאי כשירות שונים, המותאמים לאופי התפקיד. ראו סעיף 8 לחוק-יסוד: מבקר המדינה, וכן נבו - המתמחה חוקי יסוד (2026) | תנאי כשירות של חברי כנסת וחברי ממשלה*.',
    'הטעות הנפוצה היא להניח שתנאי הכשירות זהים לכל התפקידים הציבוריים, או להתעלם מהאפשרות לקביעת תנאים נוספים בחוק רגיל.', '["מבקר המדינה", "חוק-יסוד: מבקר המדינה", "כשירות לכהונה", "אזרחות ישראלית", "תושבות ישראל", "תנאי כשירות נוספים"]'::jsonb, '**וריאציה 1 — כשירות למבקר המדינה:** מי כשיר להיות מועמד למבקר המדינה? ← אזרח ישראלי ותושב ישראל, וחוק יכול שיקבע תנאים נוספים (סעיף 8 לחוק-יסוד: מבקר המדינה).
**וריאציה 2 — כשירות לראש המטה לביטחון לאומי:** מהם תנאי הכשירות לראש המטה לביטחון לאומי? ← אזרח ישראלי ותושב ישראל, בעל מומחיות וניסיון, ללא הרשעה בעבירה חמורה או כתב אישום תלוי ועומד (סעיף 3 לחוק המטה לביטחון לאומי).
**וריאציה 3 — כשירות לשמאי מכריע:** מהם תנאי הכשירות לשמאי מכריע? ← אזרח ישראלי או תושב קבע, שמאי רשום 7 שנים לפחות, ללא הרשעה בעבירה חמורה (סעיף 202ה לחוק התכנון והבניה).
**וריאציה 4 — כשירות לשופט:** מי כשיר להתמנות לשופט? ← אזרח ישראל (סעיף 5 לחוק-יסוד: השפיטה).', 'מבקר המדינה ← אזרח ישראלי + תושב ישראל + תנאים נוספים בחוק רגיל.',
    '["חוק-יסוד: מבקר המדינה: סע'' 8", "חוק המטה לביטחון לאומי, תשס\"ח-2008: סע'' 3", "חוק התכנון והבניה, תשכ\"ה-1965: סע'' 202ה", "חוק-יסוד: השפיטה: סע'' 5", "נבו - המתמחה חוקי יסוד (2026) | תנאי כשירות של חברי כנסת וחברי ממשלה*"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'אזרח ישראלי ותושב ישראל, ללא דרישת גיל ספציפית.', false, 'טענה זו שגויה. למרות שנדרשת אזרחות ותושבות, חוק-יסוד: מבקר המדינה מאפשר לקבוע תנאי כשירות נוספים, ובפועל קיימת דרישת גיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'אזרח ישראלי ותושב ישראל, ובעל תואר אקדמי במשפטים או ראיית חשבון.', false, 'טענה זו שגויה. דרישות השכלה ספציפיות אינן תנאי סף בחוק-יסוד: מבקר המדינה, אלא עשויות להיות רלוונטיות לתפקידים אחרים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'אזרח ישראלי ותושב ישראל, וכן חוק יכול שיקבע תנאי כשירות נוספים.', true, 'זוהי התשובה הנכונה. סעיף 8 לחוק-יסוד: מבקר המדינה קובע אזרחות ותושבות כתנאי סף, ומאפשר לחוק רגיל לקבוע תנאים נוספים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'אזרח ישראלי בלבד, ללא דרישת תושבות או גיל.', false, 'טענה זו שגויה. נדרשת גם תושבות ישראל, בנוסף לאזרחות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 15, '2022-W-S-Q15';
END
$$;

