DO $$
DECLARE
  v_sq_id uuid := '2a32201a-2ecf-4f30-aed9-f14d9a4e8de4'::uuid;
  v_group_id uuid := 'd834dfa9-e3ab-46aa-9fc7-d442096bf2c3'::uuid;
  v_chapter_id uuid;
