  v_ang_0 uuid := 'f903279a-596e-4b89-ae47-c4c0efb63499'::uuid;
  v_ang_1 uuid := 'bc4f21f2-3078-461d-a119-cccdd5bad185'::uuid;
  v_ang_2 uuid := '453ff478-05a2-4287-955e-1d0b6ef6cae2'::uuid;
  v_ang_3 uuid := '4e769d82-81a2-40a1-809b-94a3ffed2f3f'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q17';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 17, '2022-W-S-Q17';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fees_client_funds_advertising' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fees_client_funds_advertising', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q17', v_chapter_id, v_subtopic_id, 'עורכת דין הפסיקה להיות חברה בלשכה ביום 1.11.2022. האם באפשרותה לגבות את שכרה על עבודתה כעורכת דין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 17}'::jsonb, 'השאלה עוסקת בזכותו של עורך דין שחברותו בלשכה פקעה לגבות שכר טרחה עבור שירותים שנתן לפני כן. היא מתבססת על סעיף 50 לחוק לשכת עורכי הדין, המאזן בין זכותו של עורך הדין לשכר לבין שמירת מרותה של הלשכה על מעשיו שקדמו לפקיעת החברות.', 'סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961, קובע במפורש כי "מי שפרש מן הלשכה או שחברותו פקעה מסיבה אחרת, נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות; וכן רשאי הוא לגבות שכרו בעד שירותים שנתן לפני כן." הוראה זו מבטיחה כי עורך דין שסיים את חברותו בלשכה, מכל סיבה שהיא (פרישה מרצון, השעיה, הוצאה מהלשכה), עדיין זכאי לגבות שכר טרחה עבור שירותים משפטיים שנתן כדין בעת שהיה חבר לשכה. הזכות לגבות שכר טרחה מתייחסת אך ורק לשירותים שניתנו לפני מועד פקיעת החברות. הרציונל הוא שהעבודה בוצעה כדין בעת שהעורך דין היה מוסמך, ופקיעת החברות אינה מבטלת את תוקף אותם שירותים או את הזכות לתמורה בגינם. ראו סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961.', 'הטעות הנפוצה היא להניח שפקיעת חברות בלשכה שוללת באופן גורף את כל הזכויות והחובות של עורך הדין, כולל הזכות לשכר טרחה עבור עבודות שבוצעו לפני פקיעת החברות.',
    '["חוק לשכת עורכי הדין", "פקיעת חברות", "גביית שכר טרחה", "שמירת מרות וזכויות", "ייחוד המקצוע", "זכויות קנייניות"]'::jsonb, '**וריאציה 1 — פרישה וגביית שכר:** האם עורך דין שפרש יכול לגבות שכר טרחה? ← כן, רק על שירותים שנתן לפני הפרישה (סעיף 50 לחוק לשכת עורכי הדין).
**וריאציה 2 — הגבלת זמן:** האם יש הגבלת זמן לגביית שכר טרחה לאחר פרישה? ← לא, כל עוד השירותים ניתנו לפני הפרישה (סעיף 50 לחוק לשכת עורכי הדין).
**וריאציה 3 — שירותים חדשים:** האם עורך דין שפרש יכול לתת שירותים משפטיים חדשים? ← לא, עקרון ייחוד המקצוע מונע זאת.
**וריאציה 4 — שמירת מרות:** האם הלשכה שומרת על מרותה על עורך דין שפרש? ← כן, בכל מה שאירע לפני פקיעת החברות (סעיף 50 לחוק לשכת עורכי הדין).', 'פקיעת חברות בלשכה ← זכות לגבות שכר טרחה על עבודות קודמות נשמרת ← סעיף 50 לחוק לשכת עורכי הדין.', '[]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fees_client_funds_advertising'' | classifier_note: Lawyer whose bar membership ended — collecting fees for completed work | source_review_note: הסיווג לתת-נושא ''משמעת עורכי דין'' תחת ''סדר דין פלילי'' הוא הולם ביותר מבין האפשרויות הסגורות, שכן הוא עוסק במעמד עורכי הדין ובכללי האתיקה והמשמעת החלים עליהם, נושאים הנמצאים בליבת דיני המשמעת המקצועיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא, בגלל עקרון ייחוד המקצוע.', false, 'טענה זו שגויה. סעיף 50 לחוק לשכת עורכי הדין מאפשר במפורש גביית שכר טרחה עבור שירותים שניתנו לפני פקיעת החברות, גם אם עקרון ייחוד המקצוע מונע מתן שירותים חדשים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'רק על שירותים משפטיים שנתנה לפני 1.11.2022.', true, 'זוהי התשובה הנכונה. סעיף 50 לחוק לשכת עורכי הדין קובע במפורש כי מי שחברותו פקעה רשאי לגבות שכרו בעד שירותים שנתן לפני כן.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כן, ללא הגבלה.', false, 'טענה זו שגויה. הזכות לגבות שכר טרחה מוגבלת לשירותים שניתנו לפני פקיעת החברות, ולא חלה על שירותים שניתנו לאחר מכן.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'רק אם היא סיימה לתת את השירות המשפטי במלואו והלקוח לא נדרש לעורך דין אחר במקומה.', false, 'טענה זו שגויה. החוק אינו מתנה את הזכות לגביית שכר טרחה בתנאים אלו, אלא מתייחס לשירותים שניתנו לפני פקיעת החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'גביית שכר טרחה בעת השעיה',
    1, 'עורך דין הושעה מחברותו בלשכה לתקופה קצובה. האם הוא רשאי לגבות שכר טרחה עבור שירותים משפטיים שנתן לפני ההשעיה?', 'שאלה זו בוחנת את תחולת סעיף 50 לחוק לשכת עורכי הדין גם במקרה של השעיה, ולא רק פרישה. היא מדגישה כי הזכות לגבות שכר טרחה עבור שירותים שניתנו כדין לפני ההשעיה נשמרת, למרות הגבלות העיסוק בתקופת ההשעיה.', 'סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961, קובע כי "מי שפרש מן הלשכה או שחברותו פקעה מסיבה אחרת, נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות; וכן רשאי הוא לגבות שכרו בעד שירותים שנתן לפני כן." למרות שהמילים "או הושעתה" נמחקו מסעיף 50 בתיקון משנת 2000, הפסיקה מפרשת את הסעיף באופן רחב, כך שהוא חל גם על עורך דין שהושעה. הרציונל הוא שעורך הדין ביצע את העבודה כדין בעת שהיה חבר לשכה, וההשעיה אינה מבטלת את זכותו לשכר בגין אותם שירותים. בית הדין המשמעתי המחוזי בתל אביב-יפו קבע בבד"מ 20/03 כי "קיימת סמכות לבית-הדין מכח סעיף 50 לחוק לשכת עורכי-הדין תשכ"א 1961, גם אם היה בשנת 1989 מושעה מהלשכה". מכאן, שהזכות לגבות שכר טרחה עבור שירותים שניתנו לפני ההשעיה נשמרת. ראו סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן בד"מ (ועדת משמעת לשכת עוה"ד תל אביב-יפו) 20/03 הועד המחוזי של לשכת עורכי הדין בתל-אביב יפו נ'' מר פלוני (28.3.2003).',
    'הטעות הנפוצה היא להניח שהשעיה שוללת באופן גורף את כל הזכויות והחובות של עורך הדין, כולל הזכות לשכר טרחה עבור עבודות שבוצעו לפני ההשעיה.', '["חוק לשכת עורכי הדין", "השעיה", "גביית שכר טרחה", "שמירת מרות וזכויות", "עקרון ייחוד המקצוע", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — השעיה וגביית שכר:** האם עורך דין מושעה יכול לגבות שכר טרחה? ← כן, עבור שירותים שניתנו לפני ההשעיה (סעיף 50 לחוק לשכת עורכי הדין).
**וריאציה 2 — שינוי חקיקה:** האם מחיקת המילים "או הושעתה" מסעיף 50 שינתה את הדין? ← לא, הפסיקה עדיין מפרשת את הסעיף כחל גם על מושעים (בד"מ 20/03).
**וריאציה 3 — ייחוד המקצוע:** האם עורך דין מושעה יכול לתת שירותים חדשים? ← לא, עקרון ייחוד המקצוע מונע זאת.
**וריאציה 4 — סמכות משמעתית:** האם הלשכה שומרת על סמכות משמעתית על עורך דין מושעה? ← כן, בכל מה שאירע לפני ההשעיה (סעיף 50 לחוק לשכת עורכי הדין).', 'השעיה ← זכות לגבות שכר טרחה על עבודות קודמות נשמרת ← סעיף 50 לחוק לשכת עורכי הדין.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 50", "בד\"מ (ועדת משמעת לשכת עוה\"ד תל אביב-יפו) 20/03 הועד המחוזי של לשכת עורכי הדין בתל-אביב יפו נ'' מר פלוני (28.3.2003)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, ללא הגבלה.', false, 'טענה זו שגויה. הזכות לגבות שכר טרחה מוגבלת לשירותים שניתנו לפני ההשעיה, ולא חלה על שירותים שניתנו במהלכה או לאחריה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, בגלל עקרון ייחוד המקצוע.', false, 'טענה זו שגויה. סעיף 50 לחוק לשכת עורכי הדין מאפשר במפורש גביית שכר טרחה עבור שירותים שניתנו לפני ההשעיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'רק על שירותים משפטיים שנתן לפני ההשעיה.', true, 'זוהי התשובה הנכונה. סעיף 50 לחוק לשכת עורכי הדין קובע כי מי שחברותו פקעה או הושעתה נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות, וכן רשאי הוא לגבות שכרו בעד שירותים שנתן לפני כן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'רק אם ההשעיה אינה לצמיתות.', false, 'טענה זו שגויה. הזכות לגבות שכר טרחה עבור שירותים שניתנו לפני ההשעיה אינה תלויה באופי ההשעיה (קצובה או לצמיתות).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הרציונל מאחורי גביית שכר טרחה לאחר פקיעת חברות',
    2, 'מהו הרציונל העיקרי העומד בבסיס הוראת סעיף 50 לחוק לשכת עורכי הדין, המאפשרת לעורך דין שחברותו פקעה לגבות שכר טרחה עבור שירותים שנתן לפני כן?', 'שאלה זו בוחנת את התכלית והרציונל מאחורי סעיף 50 לחוק לשכת עורכי הדין, המאפשר לעורך דין שחברותו פקעה לגבות שכר טרחה עבור שירותים שניתנו לפני כן. היא מדגישה את האיזון בין זכותו של עורך הדין לשכר לבין שמירת מרותה של הלשכה.', 'סעיף 50 לחוק לשכת עורכי הדין קובע כי מי שפרש מן הלשכה או שחברותו פקעה מסיבה אחרת, נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות, וכן רשאי הוא לגבות שכרו בעד שירותים שנתן לפני כן. הרציונל מאחורי הוראה זו הוא כפול: ראשית, הכרה בזכותו של עורך הדין לשכר עבור עבודה שבוצעה כדין בעת שהיה חבר לשכה מוסמך. פקיעת החברות אינה מבטלת את תוקף השירותים שניתנו בעבר. שנית, ההוראה משלימה את החלק הראשון של הסעיף, הקובע את שמירת מרות הלשכה על עורך הדין לגבי מעשיו שקדמו לפקיעת החברות. כפי שצוין בעל"ע 2531/01 חרמון, "אם עורך-דין רשאי לקבל שכר על עבודתו שלפני הפרישה, חזקה שהמחוקק גם ביקש לחייבו באחריות על פעולות אלה ואחרות, שעשה לפני פרישתו". כלומר, יש קשר בין הזכות לשכר לבין האחריות המשמעתית על אותן פעולות. ראו סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן על"ע 2531/01 שמעון חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו (16.3.2004).',
    'הטעות הנפוצה היא להתמקד רק באחד ממרכיבי הסעיף (גביית שכר או שמירת מרות) במקום לראות את הקשר והאיזון ביניהם, או לייחס לסעיף מטרות שאינן משפטיות מובהקות.', '["חוק לשכת עורכי הדין", "פקיעת חברות", "גביית שכר טרחה", "שמירת מרות", "רציונל חקיקתי", "אחריות משמעתית"]'::jsonb, '**וריאציה 1 — זכות לשכר:** מדוע עורך דין שחברותו פקעה רשאי לגבות שכר? ← השירותים ניתנו כדין בעת שהיה חבר לשכה (סעיף 50 לחוק לשכת עורכי הדין).
**וריאציה 2 — קשר לאחריות:** מה הקשר בין גביית שכר לאחריות משמעתית? ← המחוקק שמר על הזכות לגבות שכר, ולכן גם על האחריות למעשים שקדמו לפרישה (על"ע חרמון).
**וריאציה 3 — מניעת התעשרות:** האם מניעת התעשרות שלא כדין היא הרציונל? ← זהו היבט משני, העיקר הוא הכרה בזכות לשכר עבור עבודה שבוצעה כדין.
**וריאציה 4 — תכלית כפולה:** מהי התכלית הכפולה של סעיף 50? ← שמירת מרות הלשכה על מעשים קודמים והכרה בזכות לגבות שכר עבורם (על"ע חרמון).', 'סעיף 50 ← זכות לשכר על עבודות קודמות ← כי בוצעו כדין + איזון עם שמירת מרות הלשכה.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 50", "על\"ע 2531/01 שמעון חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו (16.3.2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'למנוע התעשרות שלא כדין של הלקוח על חשבון עורך הדין.', false, 'טענה זו משקפת היבט מסוים, אך אינה הרציונל העיקרי והמלא של ההוראה, שכן היא מתמקדת בזכותו של עורך הדין לשכר עבור עבודה שבוצעה כדין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הכרה בכך שהשירותים ניתנו כדין בעת שהיה חבר לשכה, ופקיעת החברות אינה מבטלת את זכותו לשכר בגינם, תוך איזון עם שמירת מרות הלשכה על מעשיו הקודמים.', true, 'זוהי התשובה הנכונה. הרציונל הוא כפול: הכרה בזכות לשכר עבור עבודה שבוצעה כדין, ואיזון עם שמירת סמכות הלשכה לדון במעשים שנעשו לפני פקיעת החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לאפשר לעורך הדין להתפרנס עד שימצא עיסוק חלופי.', false, 'טענה זו שגויה. מטרת הסעיף אינה סוציאלית או תעסוקתית, אלא הכרה בזכות קניינית לשכר עבור עבודה שבוצעה כדין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'רק אם הלשכה אישרה זאת במפורש, כחלק משיקום עורך הדין.', false, 'טענה זו שגויה. הזכות לגבות שכר טרחה היא סטטוטורית ואינה תלויה באישור הלשכה, אלא נובעת מהעובדה שהשירותים ניתנו כדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'גביית שכר טרחה לאחר הוצאה מהלשכה',
    3, 'עורך דין הוצא לצמיתות מלשכת עורכי הדין בגין עבירת משמעת חמורה. האם הוא רשאי לגבות שכר טרחה עבור שירותים משפטיים שנתן לפני הוצאתו מהלשכה?', 'שאלה זו בוחנת את היקף תחולתו של סעיף 50 לחוק לשכת עורכי הדין במקרה של הוצאה לצמיתות מהלשכה. היא מדגישה כי גם במקרים חמורים של עבירות משמעת, הזכות לגבות שכר טרחה עבור שירותים שניתנו כדין לפני ההוצאה מהלשכה נשמרת.', 'סעיף 50 לחוק לשכת עורכי הדין קובע כי "מי שפרש מן הלשכה או שחברותו פקעה מסיבה אחרת, נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות; וכן רשאי הוא לגבות שכרו בעד שירותים שנתן לפני כן." הוצאה לצמיתות מהלשכה היא אחת הדרכים שבהן חברות פוקעת. הפסיקה, כפי שבאה לידי ביטוי בעל"ע 2531/01 חרמון, דנה במקרה של עורך דין שהורשע ברצח והוצא מהלשכה. למרות חומרת המעשה, הסעיף מאפשר גביית שכר טרחה עבור שירותים שניתנו לפני פקיעת החברות. הזכות לגבות שכר טרחה עבור שירותים שניתנו בעת שהעורך דין היה חבר לשכה מוסמך אינה נשללת בשל חומרת העבירה שהובילה להוצאתו מהלשכה. ראו סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן על"ע 2531/01 שמעון חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו (16.3.2004).',
    'הטעות הנפוצה היא להניח כי עונש חמור כמו הוצאה לצמיתות מהלשכה שולל באופן גורף את כל הזכויות, כולל זכויות קנייניות שנצברו כדין לפני הטלת העונש.', '["חוק לשכת עורכי הדין", "הוצאה מהלשכה", "גביית שכר טרחה", "עבירת משמעת", "קלון", "זכויות קנייניות"]'::jsonb, '**וריאציה 1 — הוצאה וגביית שכר:** האם עורך דין שהוצא מהלשכה יכול לגבות שכר טרחה? ← כן, עבור שירותים שניתנו לפני ההוצאה (סעיף 50 לחוק לשכת עורכי הדין).
**וריאציה 2 — חומרת העבירה:** האם חומרת העבירה משפיעה על הזכות לגבות שכר? ← לא, הזכות לגבות שכר עבור שירותים שניתנו כדין לפני פקיעת החברות אינה תלויה בחומרת העבירה (על"ע חרמון).
**וריאציה 3 — חידוש חברות:** האם הוצאה מהלשכה משפיעה על חידוש חברות? ← כן, ניתן לבקש חידוש רק לאחר עשר שנים, וללשכה שיקול דעת רחב (סעיף 52 לחוק לשכת עורכי הדין).
**וריאציה 4 — שמירת מרות:** האם הלשכה שומרת על מרותה על עורך דין שהוצא? ← כן, בכל מה שאירע לפני ההוצאה (סעיף 50 לחוק לשכת עורכי הדין).', 'הוצאה מהלשכה ← זכות לגבות שכר טרחה על עבודות קודמות נשמרת ← סעיף 50 לחוק לשכת עורכי הדין.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 50, 52", "על\"ע 2531/01 שמעון חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו (16.3.2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, הוצאה מהלשכה שוללת כל זכות לגביית שכר טרחה, גם על עבודות קודמות.', false, 'טענה זו שגויה. סעיף 50 לחוק לשכת עורכי הדין מאפשר גביית שכר טרחה עבור שירותים שניתנו לפני פקיעת החברות, גם אם זו נבעה מהוצאה מהלשכה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אך רק אם ההוצאה מהלשכה לא הייתה בגין עבירה שיש עמה קלון.', false, 'טענה זו שגויה. החוק אינו מבחין בין סוגי העבירות לעניין הזכות לגבות שכר טרחה עבור שירותים שניתנו לפני פקיעת החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, על שירותים משפטיים שנתן לפני הוצאתו מהלשכה.', true, 'זוהי התשובה הנכונה. סעיף 50 לחוק לשכת עורכי הדין חל גם על מי שחברותו פקעה עקב הוצאה מהלשכה, ומאפשר לו לגבות שכר טרחה עבור שירותים שניתנו לפני כן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'רק אם בית הדין המשמעתי אישר זאת במפורש.', false, 'טענה זו שגויה. הזכות לגבות שכר טרחה היא סטטוטורית ואינה תלויה באישור בית הדין המשמעתי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות הלשכה לדון עורך דין שחברותו פקעה',
    4, 'עורך דין ביצע עבירת משמעת חמורה בעת שהיה חבר לשכה, ולאחר מכן הודיע על פרישתו מרצון מהלשכה. האם לשכת עורכי הדין מוסמכת להגיש נגדו קובלנה משמעתית בגין העבירה שביצע לפני פרישתו?', 'שאלה זו בוחנת את היקף סמכותה של לשכת עורכי הדין לדון עורך דין שחברותו פקעה, בגין מעשים שביצע בעת שהיה חבר. היא מדגישה את תכלית סעיף 50 לחוק לשכת עורכי הדין למנוע התחמקות מהליכי משמעת על ידי פרישה.', 'סעיף 50 לחוק לשכת עורכי הדין קובע כי "מי שפרש מן הלשכה או שחברותו פקעה מסיבה אחרת, נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות". הפסיקה מפרשת הוראה זו באופן רחב, כך שהיא מאפשרת ללשכה להפעיל הליכי משמעת נגד עורך דין שפרש, בגין מעשים שביצע בעת שהיה חבר לשכה, גם אם הליכי המשמעת טרם החלו. תכלית הסעיף היא למנוע מעורכי דין להתחמק מדין משמעתי על ידי פרישה מרצון. בית המשפט העליון בעל"ע 2531/01 חרמון קבע כי "ניתוק הזיקה בין עורך-הדין ללשכה אינו מוחק את אשר אירע טרם פקיעת החברות, ומרות כללי המשמעת נותרת בתוקפה לגבי פעולותיו והתנהגותו של עורך-הדין קודם לניתוק." עוד נקבע בעל"ע 11/82 בן חרוץ כי "הניתוק בין עורך הדין ללשכה אינו מוחק את ''כל מה שאירע לפני פקיעת החברות או השעייתה'', אלא מרות הלשכה נשארת בתוקפה לגבי פעולותיו והתנהגותו של עורך הדין בתקופה שקדמה לניתוק." ראו סעיף 50 לחוק לשכת עורכי הדין, תשכ"א-1961, וכן על"ע 2531/01 שמעון חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו (16.3.2004), וכן על"ע 11/82 הוועד המחוזי של לשכת עורכי הדין בתל-אביב-יפו נ'' אריה בן חרוץ (12.4.1984).',
    'הטעות הנפוצה היא להניח שפרישה מרצון או פקיעת חברות מוחקת את האפשרות להעמיד לדין משמעתי בגין מעשים שבוצעו בעבר, מבלי להכיר בתכלית המניעתית של סעיף 50.', '["חוק לשכת עורכי הדין", "פקיעת חברות", "פרישה מרצון", "דין משמעתי", "שמירת מרות", "התחמקות מדין"]'::jsonb, '**וריאציה 1 — פרישה והליכי משמעת:** האם פרישה מהלשכה מונעת הליכי משמעת על מעשים קודמים? ← לא, סעיף 50 לחוק לשכת עורכי הדין שומר על מרות הלשכה (על"ע חרמון).
**וריאציה 2 — מועד פתיחת הליכים:** האם הליכי המשמעת חייבים להתחיל לפני הפרישה? ← לא, הלשכה מוסמכת לפתוח בהם גם לאחר הפרישה (על"ע חרמון).
**וריאציה 3 — היקף המרות:** האם המרות חלה רק על עבירות מקצועיות? ← לא, היא חלה גם על התנהגות שאינה הולמת את כבוד המקצוע, גם אם לא קשורה ישירות לעבודה (על"ע חרמון).
**וריאציה 4 — תכלית הסעיף:** מהי תכלית סעיף 50? ← למנוע התחמקות מדין משמעתי ולשמור על כבוד המקצוע ואמון הציבור (על"ע חרמון).', 'פקיעת חברות ← לא מוחקת מרות הלשכה ← ניתן להעמיד לדין משמעתי על מעשים קודמים.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 50", "על\"ע 2531/01 שמעון חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו (16.3.2004)", "על\"ע 11/82 הוועד המחוזי של לשכת עורכי הדין בתל-אביב-יפו נ'' אריה בן חרוץ (12.4.1984)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, עם פקיעת החברות חדלה סמכותה של הלשכה לדון בענייניו.', false, 'טענה זו שגויה. סעיף 50 לחוק לשכת עורכי הדין נועד בדיוק למנוע מצב כזה, וקובע כי מרות הלשכה נשמרת לגבי מעשים שקדמו לפקיעת החברות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, אך רק אם הליכי המשמעת כבר החלו לפני פקיעת החברות.', false, 'טענה זו שגויה. הפסיקה קבעה כי הלשכה מוסמכת להגיש קובלנה גם אם ההליכים טרם החלו, כל עוד המעשה אירע לפני פקיעת החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, על כל מעשה או מחדל שאירע לפני פקיעת החברות, גם אם הליכי המשמעת טרם החלו.', true, 'זוהי התשובה הנכונה. סעיף 50 לחוק לשכת עורכי הדין קובע כי עורך דין שחברותו פקעה נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות, וזאת ללא הגבלת זמן או תלות במועד פתיחת ההליכים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'רק אם העבירה קשורה ישירות לעיסוקו המקצועי כעורך דין.', false, 'טענה זו שגויה. הפסיקה קבעה כי מרות הלשכה חלה גם על התנהגות שאינה קשורה ישירות לעיסוק המקצועי, אם יש בה פגיעה בכבוד המקצוע.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 17, '2022-W-S-Q17';
END
$$;

