  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q18', v_chapter_id, v_subtopic_id, 'מי רשאי לקבוע את שכרו כתלות בתוצאות משפט?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 18}'::jsonb, 'השאלה עוסקת בכללים החלים על קביעת שכר טרחה מותנה בתוצאות משפט, תוך הבחנה בין משפטים פליליים לאזרחיים. היא מתבססת על סעיף 84 לחוק לשכת עורכי הדין, המהווה אבן יסוד באתיקה המקצועית של עורכי הדין בנושא שכר טרחה.', 'סעיף 84 לחוק לשכת עורכי הדין, תשכ"א-1961, קובע את הכללים לגבי שכר טרחה המותנה בתוצאות משפט. סעיף 84(א) אוסר באופן מוחלט על עורך דין להתנות או לקבל שכר טרחה התלוי בתוצאות המשפט הפלילי. איסור זה נועד להגן על הלקוח מפני ניצול מצוקתו, למנוע ניגוד עניינים בין עורך הדין ללקוח, ולשמור על טוהר ההליך הפלילי. לעומת זאת, סעיף 84(ב) מתייחס למשפט שאינו פלילי (כגון תביעת נזיקין), וקובע כי במקרים אלו מותר להתנות שכר טרחה בתוצאות המשפט, אך הלשכה רשאית, על פי בקשת הלקוח, לקבוע את השכר המתאים אם נראה לה כי השכר מופרז. מכאן, שעורכת דין בתביעת נזיקין רשאית לקבוע את שכרה כתלות בתוצאות המשפט. ראו סעיף 84(א) לחוק לשכת עורכי הדין, תשכ"א-1961, וכן סעיף 84(ב) לחוק לשכת עורכי הדין, תשכ"א-1961, וכן ע"א 2871/00 מועין דאוד ח''ורי נ'' בנק מרכנתיל דיסקונט (25.9.2003).', 'הטעות הנפוצה היא להכליל את האיסור על שכר טרחה מותנה גם למשפטים אזרחיים, או לחשוב שהאיסור במשפטים פליליים אינו מוחלט.',
    '["שכר טרחה מותנה", "חוק לשכת עורכי הדין", "משפט פלילי", "משפט אזרחי", "תביעת נזיקין", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — איסור בפלילי:** האם סנגור בתיק פלילי רשאי לקבוע שכר מותנה בתוצאות? ← לא, אסור לפי סעיף 84(א) לחוק לשכת עורכי הדין.
**וריאציה 2 — היתר באזרחי:** האם עורך דין בתביעת נזיקין רשאי לקבוע שכר מותנה בתוצאות? ← כן, מותר לפי סעיף 84(ב) לחוק לשכת עורכי הדין.
**וריאציה 3 — סמכות הלשכה:** האם הלשכה יכולה להתערב בשכר מותנה באזרחי? ← כן, אם נראה לה מופרז, על פי בקשת הלקוח (סעיף 84(ב) לחוק לשכת עורכי הדין).
**וריאציה 4 — עבירת משמעת:** האם התניית שכר בניגוד לסעיף 84 היא עבירת משמעת? ← כן, אך אין בכך כדי לשלול שכר ראוי (סעיף 86 לחוק לשכת עורכי הדין).', 'שכר טרחה מותנה ← אסור בפלילי (84(א)) ← מותר באזרחי (84(ב)) ← הלשכה יכולה להתערב אם מופרז.', '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 84, 86", "ע\"א 2871/00 מועין דאוד ח''ורי נ'' בנק מרכנתיל דיסקונט (25.9.2003)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | החלטות אחרות של בית הדין", "איל זמיר חוק חוזה הקבלנות, תשל\"ד-1974 פירוש לחוקי החוזים (1974) | 6. חוזי תיווך"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fees_client_funds_advertising'' | classifier_note: Contingent-fee arrangements — who may set them', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'סנגור בתיק פלילי.', false, 'טענה זו שגויה. סעיף 84(א) לחוק לשכת עורכי הדין אוסר על עורך דין להתנות את שכרו בתוצאות משפט פלילי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'תובע במשפט פלילי המייצג את המדינה במסגרת התקשרות חוזית ("מיקור חוץ").', false, 'טענה זו שגויה. האיסור על שכר טרחה מותנה בתוצאות משפט פלילי חל גם על עורך דין המלווה נפגע עבירה בהליך פלילי, ובהרחבה גם על תובע במיקור חוץ.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עורכת דין בתביעת נזיקין.', true, 'זוהי התשובה הנכונה. סעיף 84(ב) לחוק לשכת עורכי הדין מאפשר התניית שכר טרחה בתוצאות משפט שאינו פלילי, כגון תביעת נזיקין, בכפוף לסמכות הלשכה לבחון אם השכר מופרז.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כל עורך דין, ובלבד שהדבר נקבע מראש בהסכם כתוב.', false, 'טענה זו שגויה. למרות שרצוי הסכם כתוב, האיסור על שכר טרחה מותנה במשפט פלילי הוא מוחלט ואינו ניתן להתניה, גם לא בהסכם כתוב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שכר טרחה מותנה בתביעת נזיקין לאחר ערעור',
    1, 'עורך דין סיכם עם לקוחו על שכר טרחה מותנה בתוצאות בתביעת נזיקין. בית המשפט המחוזי פסק לטובת הלקוח סכום משמעותי, ועורך הדין גבה את שכרו. לאחר מכן, הוגש ערעור לבית המשפט העליון, וסכום הפיצויים הופחת באופן ניכר. מה הדין לגבי שכר הטרחה שגבה עורך הדין?', 'שאלה זו בוחנת את אופן חישוב שכר הטרחה המותנה בתוצאות כאשר התיק עובר הליכי ערעור. היא מדגישה את העיקרון לפיו שכר הטרחה המותנה מתייחס לתוצאה הסופית והחלוטה של ההליך המשפטי, ואת חובת עורך הדין להחזיר שכר שנגבה ביתר אם התוצאה משתנה.', 'הפסיקה קובעת כי שכר טרחה מותנה בתוצאות מתייחס לתוצאה הסופית והחלוטה של ההליך המשפטי. כלומר, אם הוגש ערעור, שכר הטרחה ייגזר מהסכום שנפסק לאחר קבלת פסק הדין בערעור. עורך דין שסיכם עם לקוחו על שכר טרחה מותנה בתוצאות, אשר חלה עליו המגבלה של שכר מרבי (כמו בתביעות פלת"ד), לא יגבה שכר נוסף תמורת הטיפול בערעור, מעבר לשכר המרבי. אם סכום הזכייה הופחת בערעור, עורך הדין חייב להחזיר את ההפרש. עורך דין המעצב הסכם שכר טרחה עם לקוחו צריך לחזות אחרית מראשית, ולהחליט אם כדאי לו ייצוג המותנה כולו בתוצאות, או שמא עליו לדרוש גם שכר טרחה מסוים המנותק מן התוצאות. אם החליט ליטול סיכון, נושא הוא בתוצאות. ראו רע"א 9955/16 עמירם רוזנר נ'' אברהם אוחיון (22.1.2017), וכן רע"א 7204/06 ישראלה ארליך נ'' עו"ד יהושע ברטל (22.8.2012), וכן רע"א 4723/05 עו"ד שלמה לוי נ'' יהונתן ברוש (12.9.2005).',
    'הטעות הנפוצה היא להניח ששכר הטרחה המותנה נגבה באופן סופי לאחר כל ערכאה, ולא רק לאחר הכרעה חלוטה, או להתעלם מהסיכון שעורך הדין נוטל על עצמו בהסכם כזה.', '["שכר טרחה מותנה", "ערעור", "תוצאה סופית", "החזר שכר טרחה", "סיכון מקצועי", "חובת עורך דין"]'::jsonb, '**וריאציה 1 — שכר מותנה וערעור:** האם שכר טרחה מותנה מתייחס לתוצאה בערכאה הראשונה או לתוצאה סופית? ← לתוצאה הסופית והחלוטה (רע"א 9955/16 רוזנר).
**וריאציה 2 — הפחתת סכום בערעור:** אם סכום הפיצוי הופחת בערעור, האם עורך הדין צריך להחזיר שכר? ← כן, את ההפרש (רע"א 7204/06 ארליך).
**וריאציה 3 — סיכון עורך הדין:** מי נושא בסיכון של שכר טרחה מותנה? ← עורך הדין, ועליו לחזות אחרית מראשית (רע"א 4723/05 לוי).
**וריאציה 4 — שכר ראוי בהפסקת ייצוג:** אם הלקוח מפטר את עורך הדין לפני סיום ההליך, מה מגיע לעורך הדין? ← שכר ראוי, אלא אם הפיטורים בחוסר תום לב (רע"א 7706/22 אטיה).', 'שכר מותנה ← תוצאה סופית ← אם הופחת בערעור, החזר ← עו"ד נוטל סיכון.',
    '["רע\"א 7394/07 עו\"ד אמיר גאנם נ'' רדא פאעור (8.10.2007)", "רע\"א 9955/16 עמירם רוזנר נ'' אברהם אוחיון (22.1.2017)", "רע\"א 7204/06 ישראלה ארליך נ'' עו\"ד יהושע ברטל (22.8.2012)", "רע\"א 4723/05 עו\"ד שלמה לוי נ'' יהונתן ברוש (12.9.2005)", "רע\"א 7706/22 ציפורה שרה סינגר אטיה נ'' עו\"ד אייל אבידן (7.3.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'עורך הדין זכאי לשכר שגבה, שכן הוא השיג תוצאה חיובית בערכאה הראשונה.', false, 'טענה זו שגויה. שכר טרחה מותנה בתוצאות מתייחס לרוב לתוצאה הסופית והחלוטה של ההליך המשפטי, כולל ערעורים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'עורך הדין חייב להחזיר ללקוח את ההפרש בין השכר שגבה לבין השכר המגיע לו לפי התוצאה הסופית בערעור.', true, 'זוהי התשובה הנכונה. הפסיקה קובעת כי שכר טרחה מותנה בתוצאות מתייחס לתוצאה הסופית של ההליך, ועל עורך הדין להחזיר את ההפרש אם התוצאה השתנתה בערעור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הלקוח אינו יכול לדרוש החזר, שכן עורך הדין נטל סיכון בהסכם שכר הטרחה המותנה.', false, 'טענה זו שגויה. למרות שעורך הדין נוטל סיכון, הסיכון מתייחס לתוצאה הסופית, והוא אינו פוטר אותו מהחזר שכר שנגבה ביתר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'עורך הדין זכאי לשכר ראוי בלבד עבור עבודתו, ללא קשר להסכם המותנה.', false, 'טענה זו שגויה. שכר ראוי נבחן לרוב במקרים של הפסקת ייצוג, אך כאשר יש הסכם מותנה, הוא מחייב ביחס לתוצאה הסופית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'התערבות הלשכה בשכר טרחה מופרז',
    2, 'עורך דין סיכם עם לקוחו על שכר טרחה מותנה בתוצאות בתביעה אזרחית. לאחר שהלקוח זכה בסכום גבוה, הוא פנה ללשכת עורכי הדין בטענה ששכר הטרחה שסוכם מופרז. מה סמכותה של לשכת עורכי הדין במקרה זה?', 'שאלה זו עוסקת בסמכותה של לשכת עורכי הדין להתערב בהסכמי שכר טרחה מותנים בתוצאות במשפטים אזרחיים, כאשר השכר נראה מופרז. היא מתבססת על סעיף 84(ב) לחוק לשכת עורכי הדין, המהווה מנגנון הגנה על לקוחות.', 'סעיף 84(ב) לחוק לשכת עורכי הדין, תשכ"א-1961, קובע כי "התנה או קיבל עורך דין שכר טרחה תלוי בתוצאות המשפט במשפט שאינו פלילי, ונראה ללשכה כי השכר מופרז, רשאית היא, על פי בקשת הלקוח, לקבוע את השכר המתאים." הוראה זו מעניקה ללשכה סמכות להתערב בהסכמי שכר טרחה מותנים במשפטים אזרחיים, אם הם נראים מופרזים, וזאת על מנת להגן על הלקוח. תכלית זו נובעת מהחשש שעורך הדין ינצל לרעה את מצוקת הלקוח ויגבה סכומים מוגזמים. הלשכה גם מוסמכת לחוות דעתה בכל שאלה בדבר שכר טרחתו של עורך דין אם נדרשה לכך על ידי בית משפט או גוף בעל סמכות שיפוטית. ראו סעיף 84(ב) לחוק לשכת עורכי הדין, תשכ"א-1961, וכן ע"א (מחוזי ת"א) 31746-02-11 יובל ליכטר נ'' גד קומרן (10.11.2011), וכן סעיף 89 לחוק לשכת עורכי הדין, תשכ"א-1961.',
    'הטעות הנפוצה היא לחשוב שסמכות הלשכה מוגבלת רק למקרים בהם נקבע תעריף מקסימלי, או שהיא אינה יכולה להתערב בהסכמים חופשיים.', '["שכר טרחה מופרז", "סמכות לשכת עורכי הדין", "הגנת הלקוח", "שכר טרחה מותנה", "חוק לשכת עורכי הדין", "תקנת הציבור"]'::jsonb, '**וריאציה 1 — סמכות הלשכה:** האם הלשכה יכולה להתערב בשכר טרחה מותנה באזרחי? ← כן, אם נראה לה מופרז, על פי בקשת הלקוח (סעיף 84(ב) לחוק לשכת עורכי הדין).
**וריאציה 2 — תכלית ההתערבות:** מהי תכלית התערבות הלשכה? ← הגנה על הלקוח ומניעת ניצול מצוקתו (ע"א 31746-02-11 ליכטר).
**וריאציה 3 — חוות דעת הלשכה:** האם חוות דעת הלשכה מחייבת את בית המשפט? ← לא, אך היא מהווה אינדיקציה חשובה (תאד"מ 68991-11-19 אינהורן).
**וריאציה 4 — שכר ראוי:** אם הלשכה קבעה שכר מתאים, האם הוא שכר ראוי? ← כן, הלשכה קובעת את השכר המתאים שהוא השכר הראוי בנסיבות העניין (סעיף 84(ב) לחוק לשכת עורכי הדין).', 'שכר מותנה מופרז באזרחי ← הלשכה יכולה לקבוע שכר מתאים ← הגנה על הלקוח.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 84(ב), 89", "ע\"א (מחוזי ת\"א) 31746-02-11 יובל ליכטר נ'' גד קומרן (10.11.2011)", "תאד\"מ (שלום ראשל\"צ) 68991-11-19 עו\"ד מרדכי אינהורן נ'' דודי לוי (6.11.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ללשכה אין סמכות להתערב בהסכם שכר טרחה שנחתם מרצון בין עורך דין ללקוחו.', false, 'טענה זו שגויה. סעיף 84(ב) לחוק לשכת עורכי הדין מקנה ללשכה סמכות להתערב בשכר טרחה מותנה שנראה מופרז.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הלשכה רשאית, על פי בקשת הלקוח, לקבוע את השכר המתאים אם נראה לה כי השכר המותנה מופרז.', true, 'זוהי התשובה הנכונה. סעיף 84(ב) לחוק לשכת עורכי הדין מעניק ללשכה סמכות זו, והיא נועדה להגן על הלקוח מפני ניצול.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הלשכה רשאית רק להמליץ לבית המשפט להתערב, אך אין לה סמכות לקבוע את השכר בעצמה.', false, 'טענה זו שגויה. סעיף 84(ב) מקנה ללשכה סמכות לקבוע את השכר המתאים, ולא רק להמליץ.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הלשכה רשאית להתערב רק אם מדובר בשכר טרחה שנקבע בניגוד לתעריף מקסימלי שנקבע בחוק.', false, 'טענה זו שגויה. סעיף 84(ב) מתייחס לשכר טרחה מותנה במשפט שאינו פלילי, גם אם לא נקבע לו תעריף מקסימלי, וסעיף 84(ג) מתייחס למקרים בהם נקבע תעריף מקסימלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שכר טרחה מותנה בהליכים מנהליים',
    3, 'עורך דין סיכם עם לקוחו על שכר טרחה מותנה בתוצאות עבור ייצוגו בהליך שימוע לפני הגשת כתב אישום. האם הסכם זה מותר על פי חוק לשכת עורכי הדין?', 'שאלה זו בוחנת את ההבחנה בין "משפט פלילי" לבין הליכים בעלי גוון מנהלי, לעניין האיסור על שכר טרחה מותנה בתוצאות. היא מדגישה את הפרשנות המצמצמת של המונח "משפט פלילי" בסעיף 84(א) לחוק לשכת עורכי הדין.', 'סעיף 84(א) לחוק לשכת עורכי הדין אוסר על עורך דין להתנות את שכרו בתוצאות "משפט פלילי". עם זאת, האיסור אינו חל על כל הליך שיש לו זיקה לעולם הפלילי. הספרות המשפטית והפסיקה מבחינות בין "משפט פלילי" במובנו הצר, לבין הליכים בעלי גוון מנהלי. ייצוג בהליך שימוע לפני הגשת כתב אישום, טיפול בבקשה למחיקת רישום פלילי או טיפול בהסרת צו מעצר בינלאומי, נחשבים לשירותים בעלי גוון מנהלי, ולכן מותר לעורך דין לקבל בגינם שכר טרחה המותנה בתוצאות. האיסור המוחלט חל על הליכי חקירה, מעצר ושחרור בערובה, וכן על ייצוג נפגעי עבירה בהליך פלילי, שכן אלו נחשבים לחלק מה"משפט הפלילי". ראו סעיף 84(א) לחוק לשכת עורכי הדין, תשכ"א-1961, וכן נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | החלטות אחרות של בית הדין.',
    'הטעות הנפוצה היא להרחיב את האיסור על שכר טרחה מותנה במשפט פלילי לכל הליך שיש לו קשר כלשהו לעבירה פלילית, מבלי להבחין בין הליכים פליליים מובהקים להליכים מנהליים.', '["שכר טרחה מותנה", "משפט פלילי", "הליך מנהלי", "שימוע", "חוק לשכת עורכי הדין", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — איסור בפלילי:** האם מותר שכר טרחה מותנה ב"משפט פלילי"? ← לא, אסור (סעיף 84(א) לחוק לשכת עורכי הדין).
**וריאציה 2 — שימוע:** האם שימוע לפני כתב אישום נחשב "משפט פלילי" לעניין זה? ← לא, הוא בעל גוון מנהלי ומותר שכר מותנה (אתיקה מקצועית: 39).
**וריאציה 3 — מחיקת רישום פלילי:** האם מותר שכר טרחה מותנה בטיפול במחיקת רישום פלילי? ← כן, זהו שירות בעל גוון מנהלי (אתיקה מקצועית: 39).
**וריאציה 4 — חקירה ומעצר:** האם מותר שכר טרחה מותנה בהליכי חקירה ומעצר? ← לא, אלו נחשבים חלק מה"משפט הפלילי" (אתיקה מקצועית: 39).', 'שכר מותנה ← אסור בפלילי (כולל חקירה) ← מותר במנהלי (שימוע, מחיקת רישום).',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 84(א)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | החלטות אחרות של בית הדין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, שכן הליך שימוע קשור למשפט פלילי, ולכן חל האיסור על שכר טרחה מותנה.', false, 'טענה זו שגויה. למרות הקשר למשפט פלילי, הליך שימוע נחשב להליך בעל גוון מנהלי, ולכן אינו נכלל באיסור המוחלט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, שכן הליך שימוע אינו נחשב ל"משפט פלילי" במובן סעיף 84(א) לחוק לשכת עורכי הדין, והוא בעל גוון מנהלי.', true, 'זוהי התשובה הנכונה. האיסור בסעיף 84(א) מתייחס ל"משפט פלילי" במובנו הצר, והליכים בעלי גוון מנהלי, כמו שימוע, אינם נכללים בו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הלקוח אינו חשוד בעבירה חמורה.', false, 'טענה זו שגויה. חומרת העבירה אינה משנה את סיווג ההליך כ"משפט פלילי" או הליך מנהלי לעניין זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן קיבל עורך הדין אישור מיוחד מלשכת עורכי הדין.', false, 'טענה זו שגויה. אין צורך באישור מיוחד מהלשכה עבור שכר טרחה מותנה בהליכים מנהליים, כל עוד הם אינם "משפט פלילי".', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חובת עורך הדין בניסוח הסכם שכר טרחה',
    4, 'עורך דין ניסח הסכם שכר טרחה מותנה בתוצאות עם לקוחו בתביעה אזרחית. ההסכם כלל סעיף מעורפל לגבי אופן חישוב השכר במקרה של פשרה. הלקוח טוען כי פרש את הסעיף באופן שונה מעורך הדין. כיצד יפורש הסעיף המעורפל?', 'שאלה זו עוסקת בחובותיו המוגברות של עורך הדין בניסוח הסכמי שכר טרחה, ובכללי הפרשנות החלים על הסכמים אלו במקרה של אי-בהירות. היא מדגישה את חובת האמון של עורך הדין ואת הכלל של פרשנות נגד המנסח.', 'היחסים בין עורך דין ללקוח מיוסדים על אמון עמוק ומתאפיינים בא-סימטריה מובהקת, שכן הלקוח הוא לרוב חסר ידע מקצועי. לכן, על עורך הדין מוטלת חובה מוגברת לנסח את הסכם שכר הטרחה באופן ברור ונהיר, ולוודא שהלקוח מבין את תוכנו. במקרה של אי-בהירות מהותית בהסכם שכר הטרחה, הפסיקה קובעת כי ההסכם יפורש באופן המיטיב עם הלקוח ולרעת עורך הדין, שהוא מנסח ההסכם. כלל זה נובע מחובת הנאמנות של עורך הדין כלפי לקוחו ומעקרון הפרשנות נגד המנסח. ראו תאד"מ (שלום ת"א) 49102-06-24 קטרין זרקה נ'' אילנדרי היממלי וג''ירה (21.8.2025), וכן ת"א (שלום ת"א) 36346-01-20 עמית פולק מטלון ושות'' נ'' טל רויטל ברוריה בסביץ בוגין (22.12.2024), וכן סעיף 54 לחוק לשכת עורכי הדין, תשכ"א-1961.',
    'הטעות הנפוצה היא להתעלם מהמעמד המיוחד של הסכמי שכר טרחה בין עורך דין ללקוח, ולהחיל עליהם כללי פרשנות כלליים של חוזים, מבלי לתת משקל לחובת האמון המוגברת.', '["חובת אמון", "פרשנות חוזים", "פרשנות נגד המנסח", "הסכם שכר טרחה", "א-סימטריה במידע", "חוק לשכת עורכי הדין"]'::jsonb, '**וריאציה 1 — חובת עורך הדין:** מהי חובת עורך הדין בניסוח הסכם שכר טרחה? ← לנסח אותו באופן ברור ונהיר, ולוודא שהלקוח מבין (תאד"מ 49102-06-24 זרקה).
**וריאציה 2 — פרשנות אי-בהירות:** כיצד תפורש אי-בהירות בהסכם שכר טרחה? ← לרעת עורך הדין ולטובת הלקוח (תאד"מ 49102-06-24 זרקה).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל נטל ההוכחה לגבי הסכמות בהסכם שכר טרחה? ← על עורך הדין (ת"א 36346-01-20 עמית פולק מטלון).
**וריאציה 4 — חובת נאמנות:** מהי חובת הנאמנות של עורך הדין? ← לפעול לטובת שולחו בנאמנות ובמסירות (סעיף 54 לחוק לשכת עורכי הדין).', 'עו"ד ← חובת אמון מוגברת ← הסכם שכר טרחה חייב להיות ברור ← אי בהירות תפורש לרעת עו"ד.',
    '["תאד\"מ (שלום ת\"א) 49102-06-24 קטרין זרקה נ'' אילנדרי היממלי וג''ירה (21.8.2025)", "ת\"א (שלום ת\"א) 36346-01-20 עמית פולק מטלון ושות'' נ'' טל רויטל ברוריה בסביץ בוגין (22.12.2024)", "חוק לשכת עורכי הדין, תשכ\"א-1961: סע'' 54", "רע\"א 7394/07 עו\"ד אמיר גאנם נ'' רדא פאעור (8.10.2007)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הסעיף יפורש לפי אומד דעתו של עורך הדין, שכן הוא בעל הידע המשפטי.', false, 'טענה זו שגויה. עורך הדין הוא מנסח ההסכם, וכלל הפרשנות הוא נגד המנסח, במיוחד לאור חובת האמון המוגברת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הסעיף יפורש באופן המיטיב עם הלקוח ולרעת עורך הדין, שכן עורך הדין הוא מנסח ההסכם וחב חובת אמון מוגברת.', true, 'זוהי התשובה הנכונה. הפסיקה קובעת כי במקרה של אי-בהירות מהותית בהסכם שכר טרחה, הוא יפורש באופן המיטיב עם הלקוח ולרעת עורך הדין, לאור חובת האמון והיותו מנסח ההסכם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הסעיף יפורש לפי כללי הפרשנות הרגילים של חוזים, ללא העדפה לאף צד.', false, 'טענה זו שגויה. יחסי עורך דין-לקוח הם יחסים מיוחדים המצדיקים כללי פרשנות ייחודיים, המטילים אחריות מוגברת על עורך הדין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הסעיף יבוטל, והצדדים יחויבו בשכר ראוי עבור עבודת עורך הדין.', false, 'טענה זו שגויה. אי-בהירות בסעיף אינה מובילה בהכרח לביטולו, אלא לפרשנותו לרעת המנסח, תוך ניסיון לקיים את ההסכם ככל הניתן.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 18, '2022-W-S-Q18';
END
$$;

-- ============================================================
-- Q19 — 2022-W-S-Q19 — chapter=administrative subtopic=constitutional_rights
-- classifier_note: BGZ petition over presidential clemency decisions — justiciability of presidential acts
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '927138e7-9094-4f75-8ae1-3c499fa566ec'::uuid;
  v_group_id uuid := '64a139b0-ad42-44ea-bbe1-d9d5a907d44c'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '6b959d64-0eda-45fe-9383-ade8807b2888'::uuid;
  v_ang_1 uuid := 'a34c02cd-0a54-4dc3-bda6-dec4020a6659'::uuid;
  v_ang_2 uuid := '465c667f-dd33-4aef-9001-d555641d56da'::uuid;
  v_ang_3 uuid := '3925089f-9a65-4d0f-834b-c42f410bb45b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q19';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 19, '2022-W-S-Q19';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'administrative';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'administrative';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'constitutional_rights' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'constitutional_rights', 'administrative';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q19', v_chapter_id, v_subtopic_id, 'יהורם הגיש עתירה לבג"ץ נגד נשיא המדינה, ולפיה יש לחייב את נשיא המדינה לנמק מדוע דחה הן את בקשתו לקיצור עונשו הן את בקשתו לעיכוב ביצוע עונשו. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 19}'::jsonb, 'השאלה עוסקת בחסינות נשיא המדינה ובסמכותו הייחודית לחון עבריינים ולהקל בעונשם, וכן בהיקף הביקורת השיפוטית על החלטותיו. היא מתמקדת בסעיפים 11(ב), 13(א) ו-14 לחוק יסוד: נשיא המדינה, ובפסיקת בג"ץ המפרשת סמכויות אלו.', 'נשיא המדינה נהנה מחסינות מהותית מפני תביעה ישירה בגין כל דבר הקשור בתפקידיו או בסמכויותיו, כקבוע בסעיף 13(א) לחוק יסוד: נשיא המדינה. סמכות החנינה והקלה בעונשים היא סמכות מובהקת של הנשיא, המעוגנת בסעיף 11(ב) לחוק יסוד: נשיא המדינה. סמכות זו מבוססת על שיקולי חסד ורחמים, ואינה כפופה לחובת הנמקה מפורטת. הפסיקה קבעה כי בג"ץ אינו יושב כערכאת ערעור על החלטות הנשיא בענייני חנינה, והביקורת השיפוטית עליהן מצומצמת ביותר, למעט במקרים חריגים של מרמה, הטעיה או חוסר סמכות קיצוני. בנוסף, לנשיא המדינה אין סמכות עצמאית לעכב ביצוע עונש, שכן זוהי סמכות שיפוטית. לפיכך, עתירה ישירה נגד נשיא המדינה, המבקשת לחייבו לנמק דחיית בקשה לקיצור עונש או לעיכוב ביצוע עונש, תידחה על הסף הן בשל חסינותו והן בשל היעדר סמכותו לעכב ביצוע עונש והיקף הביקורת המצומצם על סמכות החנינה. ראו סעיף 13(א) לחוק יסוד: נשיא המדינה, סעיף 11(ב) לחוק יסוד: נשיא המדינה, בג"ץ 7465/20 אביעד שמואל נ'' המדינה (2020), וכן בג"ץ 4/17 דידי סיבוני נ'' שרת המשפטים (2017).', 'הטעות הנפוצה היא להניח שניתן לתבוע את נשיא המדינה ישירות בבג"ץ, או שסמכות החנינה כפופה לביקורת שיפוטית רחבה כמו סמכויות מנהליות אחרות.',
    '["חסינות נשיא המדינה", "חסינות מהותית", "סמכות חנינה", "ביקורת שיפוטית מצומצמת", "עיכוב ביצוע עונש", "חוק יסוד: נשיא המדינה"]'::jsonb, '**וריאציה 1 — תביעה ישירה נגד הנשיא:** האם ניתן לתבוע את הנשיא ישירות בבג"ץ בגין החלטותיו בתפקיד? ← לא, בשל חסינותו המהותית (סעיף 13(א) לחוק יסוד: נשיא המדינה).
**וריאציה 2 — חובת הנמקה בחנינה:** האם הנשיא חייב לנמק את החלטותיו בענייני חנינה? ← לא, סמכות החנינה מבוססת על שיקולי חסד ורחמים ואינה מחייבת הנמקה (בג"ץ 4/17 סיבוני).
**וריאציה 3 — סמכות עיכוב ביצוע:** האם לנשיא סמכות לעכב ביצוע עונש? ← לא, זו סמכות שיפוטית, והעותר לא הצביע על מקור סמכות כזה לנשיא (בג"ץ 7465/20 שמואל).
**וריאציה 4 — היקף הביקורת השיפוטית:** מה היקף הביקורת השיפוטית על החלטות הנשיא? ← מצומצם מאוד, בג"ץ אינו יושב כערכאת ערעור (בג"ץ 4/17 סיבוני).', 'נשיא המדינה ← חסינות מוחלטת מביקורת ישירה על תפקידיו ← סמכות חנינה רחבה וביקורת מצומצמת ← אין סמכות לעכב ביצוע.', '["חוק-יסוד: נשיא המדינה: סע'' 11(ב), 13(א)", "בג\"ץ 7465/20 אביעד שמואל נ'' המדינה (1.11.2020)", "בג\"ץ 4/17 דידי סיבוני נ'' שרת המשפטים (29.5.2017)"]'::jsonb,
    'classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''ביטול סמכות בג"ץ'' → mapped chapter=''administrative'' subtopic=''constitutional_rights'' | classifier_note: BGZ petition over presidential clemency decisions — justiciability of presidential acts', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'דין העתירה בגין קיצור עונשו של יהורם להידחות על הסף, אולם דין העתירה בגין עיכוב הביצוע להתברר.', false, 'טענה זו שגויה. נשיא המדינה חסין מפני תביעה ישירה, ואין לו סמכות לעכב ביצוע עונש, ולכן גם חלק זה של העתירה יידחה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דין העתירה בגין קיצור עונשו של יהורם להתברר, אולם דין העתירה בגין עיכוב הביצוע להידחות על הסף.', false, 'טענה זו שגויה. נשיא המדינה חסין מפני תביעה ישירה, וסמכות החנינה נתונה לשיקול דעתו הרחב ואינה מחייבת הנמקה, ולכן גם חלק זה של העתירה יידחה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'דין שתי העתירות להתברר.', false, 'טענה זו שגויה. נשיא המדינה חסין מפני תביעה ישירה, ואין לו סמכות לעכב ביצוע עונש, וסמכות החנינה נתונה לשיקול דעת רחב ואינה מחייבת הנמקה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'דין שתי העתירות להידחות על הסף.', true, 'זוהי התשובה הנכונה. נשיא המדינה חסין מפני תביעה ישירה מכוח סעיף 13(א) לחוק יסוד: נשיא המדינה. בנוסף, סמכות החנינה (קיצור עונש) נתונה לשיקול דעת רחב ואינה מחייבת הנמקה, ואין לנשיא סמכות לעכב ביצוע עונש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'היקף הביקורת השיפוטית על החלטות הנשיא בענייני חנינה',
    1, 'פלוני הגיש עתירה לבג"ץ נגד שר המשפטים, בטענה כי המלצתו לנשיא המדינה לדחות את בקשתו לחנינה הייתה בלתי סבירה באופן קיצוני. מה הדין?', 'שאלה זו בוחנת את היקף הביקורת השיפוטית על החלטות הנשיא בענייני חנינה, כאשר העתירה מוגשת נגד גורם מנהלי המעורב בתהליך. היא מדגישה את עקרון התקיפה העקיפה ואת אופייה המצומצם של הביקורת בהקשר זה.', 'נשיא המדינה נהנה מחסינות מהותית מפני תקיפה ישירה בגין פעולות הקשורות לתפקידו, כקבוע בסעיף 13(א) לחוק יסוד: נשיא המדינה. עם זאת, מעשיו של הנשיא אינם חסינים מביקורת שיפוטית, וניתן לתקוף את חוקיותם בדרך עקיפה, למשל באמצעות עתירה נגד הגורמים המנהליים המעורבים בהליך החנינה, כגון שר המשפטים או מחלקת החנינות. אולם, היקף הביקורת השיפוטית על החלטות אלו, גם כשהן נתקפות בעקיפין, הוא מצומצם מאוד. בית המשפט אינו יושב כערכאת ערעור על החלטות הנשיא, ושיקול דעתו הרחב של הנשיא, המבוסס על שיקולי חסד ורחמים, זוכה למתחם סבירות רחב במיוחד. ראו בג"ץ 9631/07 משה כץ נ'' נשיא המדינה (2008), בג"ץ 4/17 דידי סיבוני נ'' שרת המשפטים (2017), וכן יצחק זמיר הסמכות המינהלית, כרך ג - הביקורת השיפוטית: כללי הסף (2014) | פרק 42: ערכאות הביקורת.',
    'הטעות הנפוצה היא להניח שביקורת עקיפה מאפשרת ביקורת שיפוטית מלאה על שיקול הדעת של הנשיא, בדומה לביקורת על רשויות מנהליות אחרות.', '["חסינות נשיא המדינה", "ביקורת שיפוטית עקיפה", "סמכות חנינה", "שיקול דעת מנהלי", "חוקיות", "מתחם סבירות"]'::jsonb, '**וריאציה 1 — תקיפה ישירה מול עקיפה:** האם ניתן לתקוף החלטת חנינה של הנשיא ישירות? ← לא, בשל חסינותו. ניתן לתקוף עקיפות דרך גורמים מנהליים (בג"ץ 9631/07 כץ).
**וריאציה 2 — היקף הביקורת העקיפה:** מה היקף הביקורת השיפוטית על פעולת השר בהליך החנינה? ← מצומצם מאוד, בדומה לביקורת על הנשיא (בג"ץ 4/17 סיבוני).
**וריאציה 3 — חובת הנמקה של השר:** האם השר חייב לנמק את המלצתו לנשיא? ← כן, כרשות מנהלית הוא כפוף לחובת הנמקה, אך הביקורת על סבירות ההנמקה מצומצמת.
**וריאציה 4 — מעמד הנשיא:** מדוע הביקורת מצומצמת? ← בשל מעמדו הייחודי של הנשיא כראש המדינה ואופי סמכות החנינה המבוססת על חסד ורחמים (בג"ץ 9631/07 כץ).', 'תקיפה עקיפה ← נגד גורם מנהלי ← ביקורת מצומצמת ← בשל מעמד הנשיא ואופי הסמכות.',
    '["חוק-יסוד: נשיא המדינה: סע'' 13(א)", "בג\"ץ 9631/07 משה כץ נ'' נשיא המדינה (14.4.2008)", "בג\"ץ 4/17 דידי סיבוני נ'' שרת המשפטים (29.5.2017)", "יצחק זמיר הסמכות המינהלית, כרך ג - הביקורת השיפוטית: כללי הסף (2014) | פרק 42: ערכאות הביקורת"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'העתירה תידחה על הסף, שכן החלטות חנינה אינן שפיטות כלל.', false, 'טענה זו שגויה. החלטות חנינה שפיטות, אך הביקורת עליהן מצומצמת מאוד, וניתן לתקוף אותן בעקיפין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'העתירה תידון, אך הביקורת השיפוטית תהיה מצומצמת מאוד, ותתמקד בחוקיות פעולת השר ולא בשיקול דעתו של הנשיא.', true, 'זוהי התשובה הנכונה. ניתן לתקוף את פעולות הנשיא בעקיפין דרך הגורמים המנהליים המעורבים, אך היקף הביקורת מצומצם בשל אופי סמכות החנינה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'העתירה תידון במלואה, שכן שר המשפטים כפוף לביקורת שיפוטית רגילה.', false, 'טענה זו שגויה. למרות ששר המשפטים כפוף לביקורת, בהקשר של חנינה, הביקורת מצומצמת בשל מעמד הנשיא ואופי הסמכות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'העתירה תידחה על הסף, שכן שר המשפטים חסין מפני תביעות בגין המלצותיו לנשיא.', false, 'טענה זו שגויה. שר המשפטים אינו חסין מפני תביעות בגין המלצותיו, אך הביקורת השיפוטית על המלצות אלו בהקשר של חנינה היא מצומצמת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'עילות התערבות בג"ץ בהחלטת חנינה של הנשיא',
    2, 'באילו נסיבות חריגות יתערב בג"ץ בהחלטת נשיא המדינה בעניין חנינה?', 'שאלה זו מתמקדת בעילות החריגות והמצומצמות ביותר שבהן בג"ץ עשוי להתערב בהחלטות חנינה של נשיא המדינה. היא מדגישה את אופייה הייחודי של סמכות החנינה ואת הגישה המרוסנת של בית המשפט בביקורתו עליה.', 'הביקורת השיפוטית על החלטות הנשיא בענייני חנינה היא מצומצמת ביותר, שכן סמכות זו מבוססת על שיקולי חסד ורחמים שאינם ניתנים למדידה כשיקולי משפט רגילים. עם זאת, הפסיקה קבעה כי במקרים חריגים ביותר, בג"ץ עשוי להתערב. המקרה הבולט ביותר שבו התערב בג"ץ היה בפרשת בג"ץ 706/94 רונן נ'' שר החינוך והתרבות (1999), שם בוטלה החלטת חנינה בשל מרמה והטעיה שהוצגו בפני הנשיא. עילות נוספות שעשויות להצדיק התערבות, אם כי נדירות ביותר, הן חוסר סמכות קיצוני, שיקולים זרים או חוסר סבירות קיצוני. ראו גם בג"ץ 9631/07 משה כץ נ'' נשיא המדינה (2008), וכן רע"ב 328/15 נידאל בן עבד אלרזאק זלום נ'' היועץ המשפטי לממשלה (2015).',
    'הטעות הנפוצה היא להרחיב את עילות ההתערבות מעבר למקרים החריגים שנקבעו בפסיקה, ולהתייחס לסמכות החנינה כאל סמכות מנהלית רגילה.', '["עילות התערבות", "מרמה", "הטעיה", "חוסר סמכות", "חוסר סבירות קיצוני", "שיקולים זרים", "סמכות חנינה"]'::jsonb, '**וריאציה 1 — עילת מרמה:** האם מרמה שהובילה להחלטת חנינה היא עילה להתערבות? ← כן, זו העילה העיקרית (בג"ץ 706/94 רונן).
**וריאציה 2 — טעות בשיקול דעת:** האם טעות בשיקול דעת הנשיא היא עילה להתערבות? ← לא, בג"ץ אינו יושב כערכאת ערעור (בג"ץ 4/17 סיבוני).
**וריאציה 3 — חוסר סמכות:** האם חוסר סמכות קיצוני של הנשיא הוא עילה להתערבות? ← כן, חריגה מסמכות תמיד תהווה עילה (בג"ץ 706/94 רונן).
**וריאציה 4 — שיקולים זרים:** האם שיקולים זרים הם עילה להתערבות? ← כן, במקרים חריגים ונדירים (דנג"ץ 219/09 שר המשפטים נ'' זוהר).', 'חנינה ← ביקורת מצומצמת ← התערבות רק במרמה, הטעיה, חוסר סמכות קיצוני או שיקולים זרים.',
    '["בג\"ץ 706/94 שפרה רונן נ'' פרופ'' אמנון רובינשטיין שר החינוך והתרבות (13.10.1999)", "בג\"ץ 9631/07 משה כץ נ'' נשיא המדינה (14.4.2008)", "רע\"ב 328/15 נידאל בן עבד אלרזאק זלום נ'' היועץ המשפטי לממשלה (3.12.2015)", "דנג\"ץ 219/09 שר המשפטים נ'' ניר זוהר (29.11.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'בכל מקרה שבו הנשיא טעה בשיקול דעתו או פעל על פי עצה מוטעית.', false, 'טענה זו שגויה. בג"ץ אינו יושב כערכאת ערעור על החלטות הנשיא, וטעות בשיקול דעת או עצה מוטעית אינן עילות להתערבות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'במקרה של מרמה או הטעיה שהובילו להחלטה, או חוסר סמכות קיצוני.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי עילות התערבות חריגות ביותר כוללות מרמה, הטעיה או חוסר סמכות קיצוני, כפי שאירע בפרשת רונן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'בכל מקרה שבו החלטת הנשיא אינה עולה בקנה אחד עם עקרונות הצדק והשוויון.', false, 'טענה זו שגויה. סמכות החנינה מבוססת על שיקולי חסד ורחמים, שאינם ניתנים למדידה כשיקולי משפט רגילים, ולכן עקרונות אלו אינם עילה להתערבות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'רק אם הנשיא פעל מתוך שיקולים פוליטיים מובהקים.', false, 'טענה זו שגויה. למרות ששיקולים פוליטיים אינם רצויים, הפסיקה לא קבעה אותם כעילה עצמאית להתערבות, אלא כחלק משיקולים זרים או חוסר סבירות קיצוני.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חסינות הנשיא לאחר סיום כהונתו',
    3, 'נשיא המדינה לשעבר נתבע בגין מעשה שביצע במהלך כהונתו, אשר אינו קשור לתפקידיו או סמכויותיו. האם הוא חסין מפני תביעה זו?', 'שאלה זו בוחנת את ההבחנה בין חסינות מהותית לחסינות דיונית של נשיא המדינה, ואת תחולתן לאחר סיום הכהונה. היא מדגישה כי החסינות המהותית היא קבועה ומתייחסת למעשים בתפקיד, בעוד שהחסינות הדיונית מפני דין פלילי היא זמנית ופוקעת עם תום הכהונה.', 'חוק יסוד: נשיא המדינה מבחין בין שני סוגי חסינות: חסינות מהותית וחסינות דיונית. סעיף 13(א) לחוק היסוד קובע חסינות מהותית לנשיא "בשל דבר הקשור בתפקידיו או בסמכויותיו", וחסינות זו עומדת לו גם לאחר תום כהונתו (סעיף 13(ג)). לעומת זאת, סעיף 14 לחוק היסוד קובע חסינות דיונית מפני דיון פלילי "למשך תקופת כהונתו בלבד". חסינות זו חלה על עניינים שאינם קשורים בתפקידיו או בסמכויותיו של הנשיא. לאחר סיום כהונתו, ניתן להעמידו לדין על עבירה שעבר, בין בזמן כהונתו ובין קודם לכן, ואשר אינה קשורה לתפקידו. לצורך כך, מוארכת תקופת ההתיישנות בגין אותה עבירה שאורכה כאורך תקופת החסינות. לפיכך, במקרה הנדון, הנשיא לשעבר אינו חסין מפני תביעה בגין מעשה שאינו קשור לתפקידיו או סמכויותיו, שכן חסינותו הדיונית פקעה עם תום כהונתו. ראו סעיף 13(א) לחוק יסוד: נשיא המדינה, סעיף 13(ג) לחוק יסוד: נשיא המדינה, וכן סעיף 14 לחוק יסוד: נשיא המדינה, וכן בג"ץ 962/07 עו"ד אמיר לירן נ'' היועץ המשפטי לממשלה (2007).',
    'הטעות הנפוצה היא לבלבל בין החסינות המהותית (קבועה, למעשים בתפקיד) לבין החסינות הדיונית (זמנית, למעשים שאינם בתפקיד), או להניח שכל מעשה שבוצע במהלך הכהונה חסין באופן מוחלט.', '["חסינות נשיא המדינה", "חסינות מהותית", "חסינות דיונית", "פקיעת חסינות", "תקופת כהונה", "התיישנות"]'::jsonb, '**וריאציה 1 — חסינות מהותית:** האם נשיא לשעבר חסין על מעשה שקשור לתפקידו? ← כן, החסינות המהותית קבועה (סעיף 13(ג) לחוק יסוד: נשיא המדינה).
**וריאציה 2 — חסינות דיונית:** האם נשיא לשעבר חסין על מעשה שאינו קשור לתפקידו? ← לא, החסינות הדיונית פוקעת עם תום הכהונה (סעיף 14 לחוק יסוד: נשיא המדינה).
**וריאציה 3 — הארכת התיישנות:** מה קורה לתקופת ההתיישנות של עבירה שאינה קשורה לתפקיד? ← היא מוארכת כאורך תקופת החסינות הדיונית (סעיף 14 לחוק יסוד: נשיא המדינה).
**וריאציה 4 — תכלית החסינות:** מה תכלית החסינות המהותית? ← להגן על מעמדו של הנשיא וכבוד משרתו ככל שהדבר נוגע לפעולותיו במסגרת תפקידו (בג"ץ 962/07 לירן).', 'חסינות נשיא ← מהותית (תפקיד, קבועה) ← דיונית (לא תפקיד, זמנית) ← פוקעת עם תום כהונה.',
    '["חוק-יסוד: נשיא המדינה: סע'' 13(א), 13(ג), 14", "בג\"ץ 962/07 עו\"ד אמיר לירן נ'' היועץ המשפטי לממשלה (1.4.2007)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, הוא חסין באופן מוחלט מפני כל תביעה בגין מעשים שבוצעו במהלך כהונתו.', false, 'טענה זו שגויה. החסינות המוחלטת חלה רק על מעשים הקשורים לתפקידו, ואילו חסינות דיונית מפני דין פלילי היא זמנית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, חסינותו המהותית חלה רק על מעשים הקשורים לתפקידו, וחסינותו הדיונית פוקעת עם תום כהונתו.', true, 'זוהי התשובה הנכונה. סעיף 13(א) לחוק יסוד: נשיא המדינה מעניק חסינות מהותית למעשים הקשורים לתפקיד, וסעיף 14 מעניק חסינות דיונית מפני דין פלילי רק במהלך הכהונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם מדובר בתביעה אזרחית ולא פלילית.', false, 'טענה זו שגויה. החסינות המהותית חלה על כל פעולה משפטית (אזרחית או פלילית) הקשורה לתפקיד, אך לא על מעשים שאינם קשורים לתפקיד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן עבר המעשה התיישנות.', false, 'טענה זו שגויה. תקופת ההתיישנות מוארכת בתקופת הכהונה לגבי עבירות פליליות שאינן קשורות לתפקיד, אך עצם החסינות אינה תלויה בהתיישנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חתימת קיום של שר המשפטים על החלטת חנינה',
    4, 'נשיא המדינה החליט לחון עבריין. האם שר המשפטים רשאי לסרב לחתום חתימת קיום על החלטה זו?', 'שאלה זו עוסקת בתפקידה של חתימת הקיום של שר המשפטים על החלטות חנינה של נשיא המדינה, ובפרט בהיקף שיקול הדעת הנתון לשר. היא מתבססת על ההלכה שנקבעה בדנג"ץ 219/09, המהווה אבן יסוד במנגנון האיזונים והבלמים על סמכות הנשיא.', 'סעיף 12 לחוק יסוד: נשיא המדינה קובע כי חתימתו של נשיא המדינה על מסמך רשמי, ובכלל זה כתב חנינה, טעונה חתימת קיום של ראש הממשלה או של שר אחר שהחליטה עליו הממשלה (בפועל, שר המשפטים). דנג"ץ 219/09 שר המשפטים נ'' ניר זוהר (2010) קבע, ברוב דעות, כי חתימת הקיום אינה טכנית בלבד, ולשר המשפטים נתון שיקול דעת מצומצם לסרב לחתום עליה. סירוב כזה אפשרי במקרים חריגים ויוצאי דופן שבהם עולה חשש כי החלטת הנשיא לוקה בחוסר סבירות קיצוני, מונעת משיקולים זרים, או ניתנה בחוסר תום לב או בחריגה מסמכות. תכלית חתימת הקיום היא להוות מנגנון בקרה ופיקוח על הפעלת סמכות החנינה של הנשיא, כדי למנוע מצב של סמכות מוחלטת ללא ביקורת. ראו סעיף 12 לחוק יסוד: נשיא המדינה, וכן דנג"ץ 219/09 שר המשפטים נ'' ניר זוהר (2010).',
    'הטעות הנפוצה היא לחשוב שחתימת הקיום היא טכנית בלבד, או לחלופין, שהיא מקנה לשר המשפטים זכות וטו רחבה על החלטות הנשיא.', '["חתימת קיום", "שר המשפטים", "סמכות חנינה", "איזונים ובלמים", "שיקול דעת מצומצם", "חוסר סבירות קיצוני", "שיקולים זרים"]'::jsonb, '**וריאציה 1 — תפקיד חתימת הקיום:** מה תפקיד חתימת הקיום של השר? ← מנגנון בקרה ופיקוח על החלטות הנשיא (דנג"ץ 219/09 שר המשפטים נ'' זוהר).
**וריאציה 2 — שיקול דעת השר:** האם לשר המשפטים יש שיקול דעת לסרב לחתום? ← כן, במקרים חריגים של חוסר סבירות קיצוני או שיקולים זרים (דנג"ץ 219/09 שר המשפטים נ'' זוהר).
**וריאציה 3 — חתימה טכנית:** האם חתימת הקיום היא טכנית בלבד? ← לא, זו לא עמדת הרוב בפסיקה (דנג"ץ 219/09 שר המשפטים נ'' זוהר).
**וריאציה 4 — ביקורת פרלמנטרית:** האם חתימת הקיום מאפשרת ביקורת פרלמנטרית? ← כן, היא מאפשרת ביקורת פרלמנטרית ושיפוטית (דנג"ץ 219/09 שר המשפטים נ'' זוהר).', 'חתימת קיום ← שר המשפטים ← שיקול דעת מצומצם ← בקרה על חנינה ← מניעת חוסר סבירות קיצוני/שיקולים זרים.',
    '["חוק-יסוד: נשיא המדינה: סע'' 12", "דנג\"ץ 219/09 שר המשפטים נ'' ניר זוהר (29.11.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, חתימת הקיום היא טכנית בלבד ואינה מקנה לשר שיקול דעת.', false, 'טענה זו שגויה. הפסיקה קבעה כי לשר המשפטים יש שיקול דעת מצומצם בנסיבות חריגות, ואין זו חתימה טכנית בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, במקרים חריגים שבהם עולה חשש כי החלטת הנשיא לוקה בחוסר סבירות קיצוני או מונעת משיקולים זרים.', true, 'זוהי התשובה הנכונה. דנג"ץ 219/09 קבע כי לשר המשפטים שיקול דעת מצומצם לסרב לחתום חתימת קיום במקרים חריגים אלו, כחלק ממנגנון בקרה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אם השר סבור שהחנינה אינה מוצדקת מבחינה משפטית.', false, 'טענה זו שגויה. שיקול דעתו של השר אינו רחב כדי לבחון את הצדקת החנינה מבחינה משפטית, אלא רק פגמים חמורים בהליך או בשיקולים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הנשיא עצמו ביקש את חוות דעתו של השר.', false, 'טענה זו שגויה. חתימת הקיום היא דרישה חוקתית, ושיקול דעתו של השר אינו תלוי בבקשת הנשיא.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 19, '2022-W-S-Q19';
END
$$;

-- ============================================================
-- Q20 — 2022-W-S-Q20 — chapter=ethics subtopic=fiduciary_privilege_conflict
-- classifier_note: Lawyer-spouse representing CEO of director-spouse's company in sexual-harassment case — concurrent representation / conflict
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b80cbc81-cb2b-4491-9dc0-2906636014e8'::uuid;
  v_group_id uuid := '82dafe1d-619c-4919-bf99-707a068475f4'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'd1ff9b54-4fa6-40d5-81f0-e1b0633c2971'::uuid;
  v_ang_1 uuid := 'd356561a-f704-4f81-a3c0-25cbf8e5b741'::uuid;
  v_ang_2 uuid := 'f6245af4-96aa-4ee7-a8db-8a8b570f3837'::uuid;
  v_ang_3 uuid := '42557840-ebce-409b-9527-b8945c25b6b4'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q20';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 20, '2022-W-S-Q20';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fiduciary_privilege_conflict' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_privilege_conflict', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q20', v_chapter_id, v_subtopic_id, 'עו"ד יעל, מומחית לדיני עבודה, היא רעייתו של עו"ד פבל, דירקטור בחברה התעופה הציבורית "ישראטוס". דירקטוריון החברה החליט במליאתו לבקש מעו"ד יעל לייצג את מנכ"ל החברה בתביעת הטרדה מינית שהגישה העוזרת האישית שלו. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 20}'::jsonb, 'השאלה עוסקת באיסור על דירקטורים בחברות ציבוריות, ובני משפחתם או שותפיהם, לייצג את החברה או לתת לה ייעוץ משפטי. היא מתבססת על כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), המהווים חלק מהאתיקה המקצועית של עורכי הדין ונועדו למנוע ניגודי עניינים ולשמור על טוהר המקצוע.', 'סעיף 2(א) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, קובע איסור על עורך דין שהוא דירקטור בחברה ציבורית לייצג אותה או לתת לה ייעוץ משפטי. סעיף 2(ג) מרחיב איסור זה וקובע כי הוראות הסעיף יחולו "גם על עורך דין שהוא בן זוגו, בנו, שותפו, מעסיקו או עובדו של עורך דין שהוא דירקטור כאמור ועל חברת עורכי דין, שעורך הדין חבר בה". במקרה הנדון, עו"ד יעל היא רעייתו של עו"ד פבל, דירקטור בחברה ציבורית, ולכן חל עליה האיסור העקרוני לייצג את החברה או את מנכ"לה. עם זאת, סעיף 4 לכללים קובע חריג לאיסור, לפיו הלשכה רשאית להתיר לעורך דין שחל עליו איסור לייצג חברה או נושא משרה בה, "אם הדירקטוריון של אותה חברה החליט במליאתו לבקש מעורך הדין לעשות כן בעניין מסוים שבתחום מומחיותו". לפיכך, עו"ד יעל אינה יכולה לקבל על עצמה את הייצוג באופן אוטומטי, אלא עליה לבקש היתר מיוחד מהוועד המחוזי של לשכת עורכי הדין, וזאת בכפוף להחלטת הדירקטוריון ולכך שמדובר ב"עניין מסוים" ובתחום מומחיותה. ראו סעיף 2(ג) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, וכן סעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988.', 'הטעות הנפוצה היא להניח שהאיסור חל רק על הדירקטור עצמו, ולא על בני משפחתו או שותפיו, או להתעלם מהאפשרות לקבל היתר מיוחד מהלשכה.',
    '["כללי לשכת עורכי הדין", "דירקטור בחברה ציבורית", "ניגוד עניינים", "היתר ייצוג", "בן זוג של דירקטור", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — איסור על בן זוג:** האם בן זוג של דירקטור בחברה ציבורית יכול לייצג את החברה? ← לא, האיסור חל גם עליו (סעיף 2(ג) לכללים).
**וריאציה 2 — תנאי להיתר:** מהם התנאים לקבלת היתר לייצוג על ידי בן זוג של דירקטור? ← החלטת דירקטוריון במליאתו ובקשה לעניין מסוים בתחום מומחיותו (סעיף 4 לכללים).
**וריאציה 3 — סמכות מתן היתר:** מי הגוף המוסמך לתת היתר? ← לשכת עורכי הדין (ועד המחוז) (סעיף 4 לכללים).
**וריאציה 4 — ייצוג מנכ"ל:** האם האיסור חל גם על ייצוג נושא משרה בחברה? ← כן, סעיף 4 לכללים מתייחס גם לייצוג נושא משרה בה.', 'בן זוג של דירקטור בחברה ציבורית ← איסור ייצוג/ייעוץ ← חריג: היתר מהלשכה לעניין מסוים.', '[]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fiduciary_privilege_conflict'' | classifier_note: Lawyer-spouse representing CEO of director-spouse''s company in sexual-harassment case — concurrent representation / conflict | source_review_note: הסיווג לתת-נושא ''משמעת עורכי דין'' תחת ''סדר דין פלילי'' הוא הולם ביותר מבין האפשרויות הסגורות, שכן הוא עוסק במעמד עורכי הדין ובכללי האתיקה והמשמעת החלים עליהם, נושאים הנמצאים בליבת דיני המשמעת המקצועיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אין כל מניעה שעו"ד יעל תקבל על עצמה את הייצוג.', false, 'טענה זו שגויה. סעיף 2(ג) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) מרחיב את האיסור גם לבן זוגו של הדירקטור, ולכן קיימת מניעה עקרונית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כדי לקבל על עצמה את הייצוג, על עו"ד יעל לבקש היתר מיוחד מהוועד המחוזי של לשכת עורכי הדין במחוז שאליו היא שייכת.', true, 'זוהי התשובה הנכונה. סעיף 2(ג) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) אוסר על בן זוג של דירקטור לייצג את החברה, אך סעיף 4 מאפשר ללשכה להתיר זאת בעניין מסוים, אם הדירקטוריון החליט לבקש זאת.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כדי לקבל על עצמה את הייצוג, על עו"ד יעל לבקש היתר מיוחד מבית המשפט לעניינים מינהליים.', false, 'טענה זו שגויה. הסמכות למתן היתר לייצוג במקרים אלו נתונה ללשכת עורכי הדין, ולא לבית המשפט לעניינים מינהליים, אשר דן בעתירות נגד החלטות הלשכה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות העניין עו"ד יעל לא תוכל לקבל על עצמה את ייצוגו של המנכ"ל.', false, 'טענה זו שגויה. למרות האיסור העקרוני, קיים חריג המאפשר קבלת היתר מהלשכה לייצוג בעניין מסוים, ולכן הייצוג אינו נשלל באופן מוחלט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ייצוג חברה ציבורית על ידי שותף של דירקטור',
    1, 'עו"ד דני הוא שותף במשרד עורכי דין. שותפתו, עו"ד רותי, מכהנת כדירקטורית בחברה ציבורית. דירקטוריון החברה החליט במליאתו לבקש מעו"ד דני לייצג את החברה בעסקה ספציפית לרכישת נכס. מה הדין?', 'שאלה זו בוחנת את תחולת האיסור על ייצוג חברה ציבורית על ידי עורך דין הקשור לדירקטור בה, כאשר הקשר הוא שותפות במשרד. היא מדגישה את הרחבת האיסור בסעיף 2(ג) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) ואת הצורך בהיתר מהלשכה.', 'סעיף 2(א) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, אוסר על עורך דין שהוא דירקטור בחברה ציבורית לייצג אותה או לתת לה ייעוץ משפטי. סעיף 2(ג) מרחיב איסור זה וקובע כי הוראות הסעיף יחולו "גם על עורך דין שהוא בן זוגו, בנו, שותפו, מעסיקו או עובדו של עורך דין שהוא דירקטור כאמור ועל חברת עורכי דין, שעורך הדין חבר בה". מכאן, ששותפו של דירקטור בחברה ציבורית כפוף לאותו איסור. עם זאת, סעיף 4 לכללים קובע חריג, לפיו הלשכה רשאית להתיר לעורך דין שחל עליו איסור לייצג חברה או לתת לה ייעוץ משפטי, "אם הדירקטוריון של אותה חברה החליט במליאתו לבקש מעורך הדין לעשות כן בעניין מסוים שבתחום מומחיותו". לפיכך, עו"ד דני, כשותפו של דירקטור בחברה ציבורית, נדרש לבקש היתר מהוועד המחוזי של לשכת עורכי הדין כדי לקבל על עצמו את הייצוג, וזאת בכפוף להחלטת הדירקטוריון ולכך שמדובר ב"עניין מסוים". ראו סעיף 2(ג) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, וכן סעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988.',
    'הטעות הנפוצה היא להניח שהאיסור חל רק על הדירקטור עצמו, ולא על גורמים קשורים כמו שותפים, או להתעלם מהאפשרות לקבל היתר מיוחד.', '["כללי לשכת עורכי הדין", "דירקטור בחברה ציבורית", "שותף לעורך דין", "ניגוד עניינים", "היתר ייצוג", "עניין מסוים"]'::jsonb, '**וריאציה 1 — שותף של דירקטור:** האם שותף של דירקטור בחברה ציבורית יכול לייצג את החברה? ← לא, אלא אם קיבל היתר (סעיף 2(ג) ו-4 לכללים).
**וריאציה 2 — תנאי להיתר:** מהם התנאים לקבלת היתר לייצוג על ידי שותף של דירקטור? ← החלטת דירקטוריון במליאתו ובקשה לעניין מסוים בתחום מומחיותו (סעיף 4 לכללים).
**וריאציה 3 — מטרת האיסור:** מהי מטרת האיסור על ייצוג על ידי גורמים קשורים? ← למנוע ניגוד עניינים ולשמור על טוהר המקצוע.
**וריאציה 4 — סמכות מתן היתר:** מי הגוף המוסמך לתת היתר? ← לשכת עורכי הדין (ועד המחוז) (סעיף 4 לכללים).', 'שותף של דירקטור בחברה ציבורית ← איסור ייצוג/ייעוץ ← חריג: היתר מהלשכה לעניין מסוים.',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988: סע'' 2(ג), 4"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'אין כל מניעה שעו"ד דני יקבל על עצמו את הייצוג.', false, 'טענה זו שגויה. סעיף 2(ג) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) מרחיב את האיסור גם לשותפו של הדירקטור, ולכן קיימת מניעה עקרונית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כדי לקבל על עצמו את הייצוג, על עו"ד דני לבקש היתר מיוחד מהוועד המחוזי של לשכת עורכי הדין במחוז שאליו הוא שייך.', true, 'זוהי התשובה הנכונה. סעיף 2(ג) לכללים אוסר על שותף של דירקטור לייצג את החברה, אך סעיף 4 מאפשר ללשכה להתיר זאת בעניין מסוים, אם הדירקטוריון החליט לבקש זאת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כדי לקבל על עצמו את הייצוג, על עו"ד דני לבקש היתר מיוחד מבית המשפט המחוזי.', false, 'טענה זו שגויה. הסמכות למתן היתר לייצוג במקרים אלו נתונה ללשכת עורכי הדין, ולא לבית המשפט המחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בנסיבות העניין עו"ד דני לא יוכל לקבל על עצמו את ייצוג החברה.', false, 'טענה זו שגויה. למרות האיסור העקרוני, קיים חריג המאפשר קבלת היתר מהלשכה לייצוג בעניין מסוים, ולכן הייצוג אינו נשלל באופן מוחלט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'פרשנות המונח "עניין מסוים"',
    2, 'לשכת עורכי הדין דחתה בקשה למתן היתר לייצוג חברה ציבורית בטענה שהבקשה אינה עוסקת ב"עניין מסוים" כנדרש בסעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית). מהי הפרשנות המקובלת למונח "עניין מסוים" בהקשר זה?', 'שאלה זו עוסקת בפרשנות המונח "עניין מסוים" בסעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), שהוא תנאי למתן היתר לייצוג. היא מדגישה את הפרשנות המצמצמת של לשכת עורכי הדין למונח זה, כפי שבאה לידי ביטוי בפסיקה.', 'סעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) מאפשר ללשכה להתיר ייצוג חברה ציבורית על ידי דירקטור או גורם קשור, אם הדירקטוריון החליט לבקש זאת "בעניין מסוים שבתחום מומחיותו". הפסיקה, ובפרט ההחלטה בת"א (מחוזי ת"א) 32152-01-24, מבהירה כי ועד המחוז של לשכת עורכי הדין מפרש את המונח "עניין מסוים" באופן מצמצם. ועד המחוז קבע כי "עניין מסוים" אינו טיפול ב"פרויקט" או בנכס, שכן פרויקט עשוי לכלול עניינים רבים לייצוג משפטי. לדידו של ועד המחוז, "עניין מסוים" הוא עניין חד פעמי מוגדר, כגון טיפול בעניין מיסוי בינלאומי בעסקה ספציפית על ידי דירקטור שהוא מומחה בענייני מיסוי בינלאומי. פרשנות זו נועדה למנוע ריקון מתוכן של האיסור העקרוני על ייצוג, אשר נועד למנוע ניגוד עניינים. ראו ת"א (מחוזי ת"א) 32152-01-24 ד"ר משה וינברג נ'' לשכת עורכי הדין - מחוז תל אביב (13.10.2024).',
    'הטעות הנפוצה היא להרחיב את הפרשנות של "עניין מסוים" כך שתכלול שירותים משפטיים רחבים או מתמשכים, ובכך לרוקן את האיסור מתוכנו.', '["כללי לשכת עורכי הדין", "עניין מסוים", "פרשנות חוק", "שיקול דעת מנהלי", "ניגוד עניינים", "היתר ייצוג"]'::jsonb, '**וריאציה 1 — הגדרת "עניין מסוים":** מהו "עניין מסוים" לפי לשכת עורכי הדין? ← עניין חד פעמי מוגדר וספציפי (ת"א 32152-01-24 וינברג).
**וריאציה 2 — פרויקט כ"עניין מסוים":** האם טיפול ב"פרויקט" נחשב ל"עניין מסוים"? ← לא, פרויקט עשוי לכלול עניינים רבים (ת"א 32152-01-24 וינברג).
**וריאציה 3 — דוגמה ל"עניין מסוים":** תן דוגמה ל"עניין מסוים". ← טיפול בעניין מיסוי בינלאומי בעסקה ספציפית (ת"א 32152-01-24 וינברג).
**וריאציה 4 — תכלית הפרשנות:** מדוע הלשכה מפרשת את המונח באופן מצמצם? ← כדי למנוע ריקון מתוכן של האיסור על ניגוד עניינים (ת"א 32152-01-24 וינברג).', '"עניין מסוים" ← פרשנות מצמצמת ← עניין חד פעמי מוגדר ← לא פרויקט רחב.',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988: סע'' 4", "ת\"א (מחוזי ת\"א) 32152-01-24 ד\"ר משה וינברג נ'' לשכת עורכי הדין - מחוז תל אביב (13.10.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המונח מתייחס לכל פרויקט או תחום פעילות ספציפי של החברה, גם אם הוא כולל מספר רב של עניינים משפטיים.', false, 'טענה זו שגויה. הפסיקה קבעה כי פרשנות רחבה כזו מרוקנת את הכלל מתוכנו, וכי ''פרויקט'' אינו נחשב ל''עניין מסוים''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המונח מתייחס לעניין חד פעמי מוגדר וספציפי, כגון טיפול בעניין מיסוי בינלאומי בעסקה ספציפית.', true, 'זוהי התשובה הנכונה. ועד המחוז מפרש את המונח באופן מצמצם כעניין חד פעמי ומוגדר, כדי לשמור על תכלית האיסור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המונח מתייחס לכל עניין שדירקטוריון החברה החליט במליאתו לבקש לגביו ייצוג, ללא הגבלה נוספת.', false, 'טענה זו שגויה. החלטת הדירקטוריון היא תנאי הכרחי אך לא מספיק; העניין עצמו חייב להיות ''מסוים'' על פי פרשנות הלשכה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'המונח מתייחס לעניין שבתחום מומחיותו של עורך הדין, ובלבד שהייצוג אינו יוצר ניגוד עניינים בפועל.', false, 'טענה זו שגויה. תחום המומחיות הוא תנאי נוסף, אך אינו מגדיר את ''עניין מסוים''. כמו כן, הכלל נקבע על יסוד חזקה של ניגוד עניינים, ללא קשר לקיומו בפועל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריג לאיסור: עורך דין עובד חברה ציבורית',
    3, 'עו"ד איתי הוא עובד בחברה ציבורית ומשמש כיועץ המשפטי הפנימי שלה. הוא גם מכהן כדירקטור בחברת בת של אותה חברה ציבורית. חברת הבת מקבלת ייעוץ משפטי שוטף ממשרד עורכי דין חיצוני. האם עו"ד איתי רשאי לייצג את חברת הבת בעניין משפטי?', 'שאלה זו בוחנת חריג ספציפי לאיסור על דירקטור בחברה ציבורית (או גורם קשור) לייצג את החברה. החריג, המעוגן בסעיף 2(ד) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), מתייחס לעורך דין שהוא עובד חברה ציבורית ומכהן כדירקטור בחברת בת או חברת אם שלה.', 'סעיף 2(א) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) אוסר על עורך דין שהוא דירקטור בחברה ציבורית לייצג אותה או לתת לה ייעוץ משפטי. סעיף 2(ד) לכללים קובע חריג מפורש לאיסור זה: "הוראות סעיף זה לא יחולו על עורך דין עובד חברה ציבורית המכהן מטעמה כדירקטור בחברה-בת או חברה-אם של אותה חברה, ובלבד שהחברה שבה הוא מכהן כאמור, מקבלת ייעוץ משפטי מעורך דין שאינו עובד החברה הציבורית." במקרה הנדון, עו"ד איתי הוא עובד בחברה הציבורית, מכהן כדירקטור בחברת בת שלה, וחברת הבת מקבלת ייעוץ משפטי חיצוני. לפיכך, מתקיימים כל תנאי החריג, ועו"ד איתי רשאי לייצג את חברת הבת בעניין משפטי ללא צורך בהיתר מיוחד מהלשכה. ראו סעיף 2(ד) לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988.',
    'הטעות הנפוצה היא להתעלם מהחריג הספציפי הקבוע בסעיף 2(ד) לכללים, או לחשוב שהוא דורש תנאים נוספים מעבר לאלו המפורטים בו.', '["כללי לשכת עורכי הדין", "חריג לכלל", "עורך דין עובד חברה", "דירקטור בחברת בת/אם", "ייעוץ משפטי חיצוני", "ניגוד עניינים"]'::jsonb, '**וריאציה 1 — עו"ד עובד ודירקטור בחברת בת:** האם עו"ד עובד חברה ציבורית יכול לכהן כדירקטור בחברת בת שלה ולייצגה? ← כן, אם חברת הבת מקבלת ייעוץ משפטי חיצוני (סעיף 2(ד) לכללים).
**וריאציה 2 — תנאי החריג:** מהו התנאי המרכזי לחריג בסעיף 2(ד)? ← שהחברה שבה הוא מכהן כדירקטור מקבלת ייעוץ משפטי מעורך דין שאינו עובד החברה הציבורית.
**וריאציה 3 — מטרת החריג:** מהי מטרת החריג? ← לאפשר מבנים תאגידיים מסוימים תוך שמירה על מנגנוני בקרה למניעת ניגוד עניינים.
**וריאציה 4 — היעדר ייעוץ חיצוני:** מה הדין אם חברת הבת אינה מקבלת ייעוץ משפטי חיצוני? ← אז החריג לא יחול, והאיסור הכללי יחול (סעיף 2(ד) לכללים).', 'עו"ד עובד חברה ציבורית ← דירקטור בחברת בת/אם ← מותר לייצג ← אם חברת הבת מקבלת ייעוץ חיצוני.',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988: סע'' 2(ד)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, האיסור על דירקטור בחברה ציבורית לייצג אותה חל גם על חברות בת.', false, 'טענה זו שגויה. קיים חריג ספציפי בסעיף 2(ד) לכללים המאפשר זאת בתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, שכן סעיף 2(ד) לכללים קובע חריג המאפשר לעורך דין עובד חברה ציבורית לכהן כדירקטור בחברת בת ולייצגה, ובלבד שחברת הבת מקבלת ייעוץ משפטי חיצוני.', true, 'זוהי התשובה הנכונה. סעיף 2(ד) לכללים קובע חריג מפורש לאיסור, המאפשר לעורך דין עובד חברה ציבורית לכהן כדירקטור בחברת בת או חברת אם שלה, ובלבד שהחברה שבה הוא מכהן מקבלת ייעוץ משפטי מעורך דין שאינו עובד החברה הציבורית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם קיבל היתר מיוחד מלשכת עורכי הדין.', false, 'טענה זו שגויה. במקרה זה, החריג בסעיף 2(ד) פוטר מהצורך בהיתר מיוחד, כל עוד התנאים מתקיימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הוא אינו מקבל שכר נוסף עבור תפקידו כדירקטור בחברת הבת.', false, 'טענה זו שגויה. תנאי החריג אינם מתייחסים לשכר נוסף, אלא לקבלת ייעוץ משפטי חיצוני על ידי חברת הבת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'דרך התקיפה של החלטת ועד המחוז',
    4, 'עו"ד ראובן הגיש בקשה לוועד המחוזי של לשכת עורכי הדין למתן היתר לייצוג חברה ציבורית, ובקשתו נדחתה. עו"ד ראובן סבור שההחלטה שגויה ומבקש לתקוף אותה. מהי הדרך הדיונית הנכונה לתקיפת החלטת ועד המחוז?', 'שאלה זו עוסקת בדרך הדיונית הנכונה לתקיפת החלטות מנהליות של ועד המחוז של לשכת עורכי הדין. היא מדגישה את ההבחנה בין סמכותו של בית המשפט לעניינים מינהליים לבין סמכותו של בית המשפט האזרחי, ואת עקרון ה"תקיפה הישירה במסווה".', 'החלטות ועד המחוז של לשכת עורכי הדין, כגון דחיית בקשה למתן היתר ייצוג, הן החלטות בעלות אופי מנהלי. סעיף 5 לחוק בתי משפט לעניינים מינהליים, תש"ס-2000, קובע כי הסמכות להשיג על החלטות רשות או גוף המנוי בתוספת מסורה לבית המשפט המחוזי בשבתו כבית משפט לעניינים מינהליים. פרט 21(5) לתוספת הראשונה לחוק זה קובע במפורש את הסמכות לדון בעתירה כנגד החלטת ועד המחוז. הפסיקה, כפי שבאה לידי ביטוי בת"א (מחוזי ת"א) 32152-01-24, קובעת כי הגשת תביעה אזרחית לסעד הצהרתי, שמטרתה האמיתית היא לתקוף את שיקול הדעת המנהלי של ועד המחוז, מהווה "תקיפה ישירה במסווה" של ההחלטה המנהלית. במקרים כאלה, בית המשפט האזרחי נעדר סמכות עניינית לדון בתובענה, והדרך הדיונית הראויה היא הגשת עתירה מנהלית. ראו ת"א (מחוזי ת"א) 32152-01-24 ד"ר משה וינברג נ'' לשכת עורכי הדין - מחוז תל אביב (13.10.2024), וכן ת"א (מחוזי ת"א) 32152-01-24 ד"ר משה וינברג נ'' לשכת עורכי הדין - מחוז תל אביב (13.10.2024).',
    'הטעות הנפוצה היא לנסות לעקוף את המסלול המנהלי באמצעות הגשת תביעה אזרחית לסעד הצהרתי, מתוך מחשבה שזו דרך קלה יותר או נוחה יותר לתקוף החלטות רשות.', '["סמכות עניינית", "עתירה מנהלית", "סעד הצהרתי", "תקיפה ישירה במסווה", "חוק בתי משפט לעניינים מינהליים", "ועד מחוז לשכת עורכי הדין"]'::jsonb, '**וריאציה 1 — תקיפת החלטת ועד מחוז:** כיצד תוקפים החלטה של ועד מחוז לשכת עורכי הדין? ← באמצעות עתירה מנהלית לבית המשפט לעניינים מינהליים (ת"א 32152-01-24 וינברג).
**וריאציה 2 — סעד הצהרתי כתחליף:** האם ניתן להגיש תביעה לסעד הצהרתי במקום עתירה מנהלית? ← לא, זו נחשבת "תקיפה ישירה במסווה" ובית המשפט האזרחי נעדר סמכות (ת"א 32152-01-24 וינברג).
**וריאציה 3 — סמכות בית המשפט לעניינים מינהליים:** מהו מקור הסמכות של בית המשפט לעניינים מינהליים לדון בעתירות נגד ועד המחוז? ← סעיף 5 לחוק בתי משפט לעניינים מינהליים ופרט 21(5) לתוספת הראשונה (ת"א 32152-01-24 וינברג).
**וריאציה 4 — אינטרס לגיטימי בסעד הצהרתי:** האם אינטרס בפרשנות חוק מצדיק סעד הצהרתי במקום עתירה מנהלית? ← לא, כאשר המחוקק קבע דרך דיונית ייעודית, יש לפעול לפיה (ת"א 32152-01-24 וינברג).', 'החלטת ועד מחוז ← תקיפה בעתירה מנהלית ← לא בסעד הצהרתי אזרחי ← חוסר סמכות עניינית.',
    '["חוק בתי משפט לעניינים מינהליים, תש\"ס-2000: סע'' 5, פרט 21(5) לתוספת הראשונה", "ת\"א (מחוזי ת\"א) 32152-01-24 ד\"ר משה וינברג נ'' לשכת עורכי הדין - מחוז תל אביב (13.10.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הגשת תביעה אזרחית לסעד הצהרתי לבית המשפט המחוזי, בטענה לפרשנות שגויה של הכללים.', false, 'טענה זו שגויה. הפסיקה קבעה כי זוהי "תקיפה ישירה במסווה" של החלטה מנהלית, ובית המשפט האזרחי נעדר סמכות עניינית לדון בה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הגשת עתירה מנהלית לבית המשפט לעניינים מינהליים, בטענה לחוסר סבירות או חוסר חוקיות בהחלטה.', true, 'זוהי התשובה הנכונה. החלטות ועד המחוז הן החלטות מנהליות, והדרך הדיונית הנכונה לתקוף אותן היא באמצעות עתירה מנהלית לבית המשפט לעניינים מינהליים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הגשת ערעור לבית הדין הארצי למשמעת של לשכת עורכי הדין.', false, 'טענה זו שגויה. בית הדין הארצי למשמעת דן בערעורים על החלטות בתי הדין המשמעתיים המחוזיים, ולא על החלטות מנהליות של ועד המחוז.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הגשת בקשה לצו עשה לבית משפט השלום, שיחייב את ועד המחוז לתת את ההיתר.', false, 'טענה זו שגויה. בית משפט השלום נעדר סמכות עניינית לדון בעניינים מנהליים, וצו עשה נגד רשות מנהלית נתבע בעתירה מנהלית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 20, '2022-W-S-Q20';
END
$$;

-- ============================================================
-- Q22 — 2022-W-S-Q22 — chapter=family_inheritance subtopic=inheritance_will
-- classifier_note: Estate administrators (מנהלי עיזבון) paying for minor's medical treatment from his estate share
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '13168009-591a-411b-b28d-e6d8d18c3afa'::uuid;
  v_group_id uuid := '0501eb21-4ded-498d-bc3a-074854fc2610'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f9c016e5-176f-45fb-8ccd-774fa7942a51'::uuid;
  v_ang_1 uuid := 'cf55b653-9619-4285-baf7-2940b68a0ebb'::uuid;
  v_ang_2 uuid := '90d19778-1942-4545-ad4f-84f7fcbd81d1'::uuid;
  v_ang_3 uuid := 'cc60006d-59c3-414a-96f1-950a5736bf2b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q22';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 22, '2022-W-S-Q22';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'family_inheritance';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'family_inheritance';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'inheritance_will' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'inheritance_will', 'family_inheritance';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q22', v_chapter_id, v_subtopic_id, 'בית המשפט מינה את מיכאלה ורונה למנהלות העיזבון של אביהן אשר הלך לעולמו ולא השאיר אחריו צוואה. מיכאלה החליטה לשלם מתוך חלקו המשוער של אחיהן הקטין בכספי העיזבון על טיפול רפואי דחוף שלו נזקק האח. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 22}'::jsonb, 'שאלה זו עוסקת בסמכויות מנהלי עיזבון אחדים, ובפרט בחריג לכלל הדורש הסכמה או אישור בית משפט, כאשר מדובר ב''עניין שאינו סובל דיחוי'', כפי שקבוע בסעיף 93(3) לחוק הירושה.', 'על פי סעיף 93 לחוק הירושה, תשכ"ה-1965, כאשר בית המשפט מינה שני מנהלי עיזבון או יותר, הם חייבים לפעול תוך הסכמה, ופעולה של אחד מהם טעונה הסכמת האחרים או אישור בית המשפט (סעיפים 93(1) ו-93(2)). עם זאת, סעיף 93(3) קובע חריג חשוב: ''בענין שאינו סובל דיחוי רשאי כל אחד ממנהלי העזבון לפעול על דעת עצמו''. טיפול רפואי דחוף לקטין נחשב ללא ספק לעניין שאינו סובל דיחוי, שכן אי-ביצועו המיידי עלול לגרום נזק בלתי הפיך. לכן, מיכאלה רשאית לפעול על דעת עצמה במקרה זה.', 'הטעות הנפוצה היא להתעלם מהחריג של ''עניין שאינו סובל דיחוי'' ולחשוב שכל פעולה של מנהל עיזבון מרובה דורשת הסכמה או אישור בית משפט, גם במקרים דחופים.',
    '["מנהלי עיזבון אחדים", "חוק הירושה", "עניין שאינו סובל דיחוי", "סמכויות מנהל עיזבון", "קטין"]'::jsonb, '**וריאציה 1 — מכירת נכס:** מיכאלה רוצה למכור נכס מהעיזבון שאינו מתכלה. האם רשאית לפעול לבד? ← לא, זו אינה פעולה דחופה ודורשת הסכמה או אישור בית משפט, לפי סעיף 93(2) לחוק הירושה.
**וריאציה 2 — תשלום חוב רגיל:** מיכאלה רוצה לשלם חוב רגיל של העיזבון שאינו דחוף. האם רשאית לפעול לבד? ← לא, זו אינה פעולה דחופה ודורשת הסכמה או אישור בית משפט, לפי סעיף 93(2) לחוק הירושה.
**וריאציה 3 — טיפול רפואי לא דחוף:** מיכאלה רוצה לממן טיפול רפואי אסתטי לאח הקטין. האם רשאית לפעול לבד? ← לא, זהו אינו עניין שאינו סובל דיחוי, ודורש הסכמה או אישור בית משפט, לפי סעיף 93(2) לחוק הירושה.
**וריאציה 4 — תיקון דחוף של נכס:** מיכאלה רוצה לתקן נזילה חמורה בנכס של העיזבון שעלולה לגרום נזק רב. האם רשאית לפעול לבד? ← כן, זהו עניין שאינו סובל דיחוי, לפי סעיף 93(3) לחוק הירושה.', 'מנהלי עיזבון ← פועלים בהסכמה/אישור ביהמ"ש ← חריג: עניין דחוף, כל אחד יכול לפעול לבד.', '["סעיף 93 לחוק הירושה, תשכ\"ה-1965"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Estate administrators (מנהלי עיזבון) paying for minor''s medical treatment from his estate share | source_review_note: השאלה עוסקת בדיני ירושה, ובפרט בסמכויות מנהלי עיזבון. נושא זה אינו משתלב באופן מלא באף אחד מהסאב-טופיקים הקיימים תחת ''סדר דין אזרחי''. הסאב-טופיק ''הליכים'' נבחר כברירת מחדל כללית. יש לשקול הוספת סאב-טופיק ייעודי לדיני ירושה או סמכויות מנהלי עיזבון.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מיכאלה תידרש לקבל את הסכמתה של רונה כדי לשלם על הטיפול הרפואי מכספי העיזבון.', false, 'אף שבדרך כלל נדרשת הסכמת מנהלי העיזבון, סעיף 93(3) לחוק הירושה קובע חריג לעניין שאינו סובל דיחוי, כמו טיפול רפואי דחוף.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מיכאלה תידרש לקבל את הסכמת בית המשפט כדי לשלם על הטיפול הרפואי מכספי העיזבון.', false, 'אף שבמקרים מסוימים נדרש אישור בית המשפט, סעיף 93(3) לחוק הירושה מאפשר פעולה עצמאית בעניין שאינו סובל דיחוי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מיכאלה תידרש לקבל את הסכמתם של רונה או של בית המשפט כדי לשלם על הטיפול הרפואי מכספי העיזבון.', false, 'התשובה אינה מדויקת, שכן במקרה של עניין שאינו סובל דיחוי, מיכאלה אינה נדרשת לקבל הסכמה או אישור כלל, אלא רשאית לפעול על דעת עצמה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות העניין מיכאלה לא תידרש לקבל את הסכמתם של רונה או של בית המשפט כדי לשלם על הטיפול הרפואי מכספי העיזבון.', true, 'סעיף 93(3) לחוק הירושה קובע כי בעניין שאינו סובל דיחוי, רשאי כל אחד ממנהלי העיזבון לפעול על דעת עצמו. טיפול רפואי דחוף לקטין נחשב לעניין כזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פעולה דחופה של מנהל עיזבון יחיד',
    1, 'בית המשפט מינה את מיכאלה למנהלת עיזבון יחידה. היא נדרשת לשלם חוב ארנונה דחוף כדי למנוע עיקול נכס של העיזבון. מה הדין?', 'שאלה זו בוחנת את סמכותו של מנהל עיזבון יחיד לבצע פעולות דחופות למען העיזבון, תוך התייחסות לעקרונות הנגזרים מסעיף 93(3) לחוק הירושה, אף שסעיף זה מתייחס למנהלים אחדים.', 'תפקידו של מנהל עיזבון, בין אם יחיד ובין אם מרובה, הוא לכנס את נכסי העיזבון, לנהלו, לסלק את חובותיו ולחלק את היתרה בין היורשים, כפי שקובע סעיף 82 לחוק הירושה. פעולה דחופה כמו תשלום חוב ארנונה למניעת עיקול נכס נחשבת ל''עניין שאינו סובל דיחוי'', אשר מנהל עיזבון רשאי לבצע על דעת עצמו, גם אם הוא יחיד, כדי למנוע נזק לעיזבון. עקרון זה נלמד מסעיף 93(3) לחוק הירושה, החל על מנהלים אחדים, אך משקף את הצורך המהותי של כל מנהל עיזבון לפעול לשמירת נכסי העיזבון.',
    'טעות נפוצה היא להניח שכל פעולה של מנהל עיזבון, גם אם היא דחופה, דורשת אישור בית משפט או הסכמת יורשים, מבלי להבחין בחריג של עניינים שאינם סובלים דיחוי.', '["מנהל עיזבון יחיד", "עניין שאינו סובל דיחוי", "חוק הירושה", "סמכויות מנהל עיזבון", "מניעת נזק לעיזבון"]'::jsonb, '**וריאציה 1 — מכירת נכס יחיד:** מנהלת עיזבון יחידה רוצה למכור נכס יחיד ומשמעותי של העיזבון. האם רשאית לפעול לבד? ← לא, זו אינה פעולה דחופה ודורשת אישור בית משפט, לפי סעיף 83 לחוק הירושה.
**וריאציה 2 — השקעה בסיכון גבוה:** מנהלת עיזבון יחידה רוצה להשקיע כספי עיזבון בהשקעה בעלת סיכון גבוה. האם רשאית לפעול לבד? ← לא, זו אינה פעולה דחופה ודורשת אישור בית משפט, כחלק מחובת הנאמנות והזהירות.
**וריאציה 3 — תשלום שכר טרחה לעורך דין:** מנהלת עיזבון יחידה רוצה לשלם שכר טרחה לעורך דין שייצג את העיזבון. האם רשאית לפעול לבד? ← כן, זו פעולה שגרתית בניהול עיזבון, אלא אם הסכום חריג ודורש אישור.
**וריאציה 4 — תיקון דחוף של רכב:** מנהלת עיזבון יחידה נדרשת לתקן רכב של העיזבון שנפגע בתאונה כדי למנוע נזק נוסף. האם רשאית לפעול לבד? ← כן, זהו עניין שאינו סובל דיחוי, לפי עקרון סעיף 93(3) לחוק הירושה.', 'מנהל עיזבון יחיד ← רשאי לפעול לבד בעניין דחוף ← למניעת נזק לעיזבון.',
    '["סעיף 82 לחוק הירושה, תשכ\"ה-1965", "סעיף 93 לחוק הירושה, תשכ\"ה-1965"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'מיכאלה רשאית לשלם את חוב הארנונה ללא אישור בית המשפט.', true, 'מנהל עיזבון יחיד, בדומה לחריג הקבוע בסעיף 93(3) לחוק הירושה, רשאי לפעול בעניין שאינו סובל דיחוי כדי למנוע נזק לעיזבון, כחלק מחובתו לנהל את העיזבון לפי סעיף 82 לחוק הירושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'מיכאלה חייבת לקבל אישור מבית המשפט לפני תשלום החוב.', false, 'אף שאישור בית המשפט נדרש לפעולות מסוימות, במקרה של דחיפות למניעת נזק לעיזבון, מנהל העיזבון רשאי לפעול באופן מיידי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'מיכאלה אינה רשאית לשלם חובות של העיזבון ללא הסכמת היורשים.', false, 'תפקידו של מנהל העיזבון הוא לנהל את העיזבון ולסלק את חובותיו, ואין הוא כפוף להסכמת היורשים לכל פעולה, במיוחד בעניינים דחופים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'מיכאלה צריכה להמתין למינוי מנהל עיזבון נוסף כדי לקבל החלטה משותפת.', false, 'מיכאלה מונתה כמנהלת עיזבון יחידה, ואין צורך במינוי נוסף לצורך פעולה דחופה למניעת נזק לעיזבון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן "עניין שאינו סובל דיחוי"',
    2, 'מהם הקריטריונים המרכזיים לקביעה האם פעולה של מנהל עיזבון נחשבת ל"עניין שאינו סובל דיחוי" לפי סעיף 93(3) לחוק הירושה?', 'שאלה זו בוחנת את ההבנה של המבחנים המשפטיים לקביעת דחיפות פעולה של מנהל עיזבון, כפי שמשתמע מסעיף 93(3) לחוק הירושה, ומדגישה את הצורך בפרשנות תכליתית של הוראות החוק.', 'המונח ''עניין שאינו סובל דיחוי'' בסעיף 93(3) לחוק הירושה, תשכ"ה-1965, מתפרש בפסיקה כפעולה שיש לבצעה באופן מיידי כדי למנוע נזק משמעותי לעיזבון או ליורשים, וזאת כאשר אין אפשרות מעשית לקבל הסכמה של מנהלי עיזבון אחרים או אישור מבית המשפט בפרק הזמן הנדרש. המבחן הוא אובייקטיבי ומתחשב בנסיבות העניין, במידת הנזק הפוטנציאלי ובאפשרות לקבל אישור מראש. לדוגמה, טיפול רפואי מציל חיים או מניעת קריסת נכס מתכלים ייחשבו כעניינים דחופים.',
    'הקושי הוא להבחין בין פעולה חשובה לפעולה דחופה באמת, ולהבין שהדחיפות נבחנת לא רק על פי חשיבות הפעולה אלא גם על פי ההשלכות של אי-ביצועה המיידי והיעדר חלופות לקבלת אישור.', '["עניין שאינו סובל דיחוי", "חוק הירושה", "מנהלי עיזבון", "מניעת נזק", "פרשנות תכליתית"]'::jsonb, '**וריאציה 1 — מכירת מניות יורדות:** מנהל עיזבון רוצה למכור מניות של העיזבון שצונחות בערכן. האם זה דחוף? ← כן, אם ההפסד מיידי ומשמעותי ואין זמן לקבל אישור, לפי מבחן הנזק והיעדר אפשרות.
**וריאציה 2 — תשלום חשבון חשמל:** מנהל עיזבון רוצה לשלם חשבון חשמל רגיל. האם זה דחוף? ← לא, אלא אם כן מדובר בניתוק מיידי שיגרום נזק חמור, לפי מבחן הנזק.
**וריאציה 3 — הגשת ערעור:** מנהל עיזבון רוצה להגיש ערעור על פסק דין נגד העיזבון. האם זה דחוף? ← כן, אם מועד הגשת הערעור קרוב ואי-הגשתו תגרום לאובדן זכות, לפי מבחן היעדר אפשרות.
**וריאציה 4 — שיפוץ יקר:** מנהל עיזבון רוצה לבצע שיפוץ יקר בנכס של העיזבון. האם זה דחוף? ← לא, אלא אם כן מדובר בתיקון ליקוי בטיחותי מיידי שעלול לגרום נזק פיזי או קריסת הנכס, לפי מבחן הנזק.', 'מבחן דחיפות ← מניעת נזק מיידי + היעדר אפשרות לאישור מראש.',
    '["סעיף 93 לחוק הירושה, תשכ\"ה-1965"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הקריטריונים כוללים את מידת הנזק שייגרם לעיזבון או ליורשים אם הפעולה לא תבוצע מיידית, ואת היעדר אפשרות מעשית לקבל הסכמה או אישור מראש.', true, 'הקביעה האם עניין אינו סובל דיחוי נבחנת על פי שני קריטריונים מרכזיים: הצורך המיידי בפעולה למניעת נזק משמעותי, והיעדר יכולת מעשית לקבל אישור מראש, כפי שעולה מהפרשנות התכליתית של סעיף 93(3) לחוק הירושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הקריטריונים נקבעים באופן בלעדי על ידי מנהל העיזבון הפועל, לפי שיקול דעתו הבלעדי.', false, 'אף שלמנהל העיזבון שיקול דעת, הוא אינו בלעדי וחייב לעמוד במבחנים אובייקטיביים של דחיפות וצורך, ונתון לביקורת שיפוטית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הקריטריונים מתייחסים רק לפעולות הקשורות לנכסים מתכלים או לפעולות שערכן הכספי נמוך.', false, 'הדחיפות אינה מוגבלת לסוג נכסים מסוים או לערך כספי נמוך, אלא לכל פעולה שאי-ביצועה המיידי יגרום נזק משמעותי לעיזבון או ליורשים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הקריטריונים כוללים את הסכמת כל היורשים לפעולה, גם אם היא דחופה.', false, 'הסכמת היורשים אינה קריטריון לדחיפות, ובמקרים דחופים סעיף 93(3) לחוק הירושה מאפשר פעולה ללא הסכמה מראש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות מנהלי עיזבון לפעולות חבריהם',
    3, 'מיכאלה ורונה הן מנהלות עיזבון. מיכאלה ביצעה פעולה דחופה ללא ידיעתה של רונה, אך רונה סברה שהפעולה לא הייתה נחוצה. מה הדין לגבי אחריותה של רונה לפעולה זו?', 'שאלה זו מתמקדת באחריותם של מנהלי עיזבון אחדים לפעולות שביצע אחד מהם, ובפרט בחריג הקבוע בסעיף 93(4) לחוק הירושה, המאפשר למנהל עיזבון להשתחרר מאחריות בתנאים מסוימים.', 'סעיף 93(4) לחוק הירושה, תשכ"ה-1965, קובע כי ''כל מנהל עזבון אחראי לפעולת חבריו זולת אם התנגד לה או לא ידע עליה''. משמעות הדבר היא שרונה, כמנהלת עיזבון, אינה נושאת באחריות אוטומטית לכל פעולה של מיכאלה. אם רונה תוכיח כי לא ידעה על הפעולה שביצעה מיכאלה, או שהתנגדה לה, היא תהיה פטורה מאחריות לפעולה זו. הוראה זו נועדה להגן על מנהל עיזבון שאינו שותף להחלטה או לפעולה מסוימת.',
    'הטעות הנפוצה היא להניח אחריות מוחלטת ובלתי ניתנת להפרדה של כל מנהלי העיזבון, מבלי להכיר בחריג המפורש הקבוע בחוק.', '["מנהלי עיזבון אחדים", "אחריות מנהלי עיזבון", "חוק הירושה", "התנגדות לפעולה", "חוסר ידיעה"]'::jsonb, '**וריאציה 1 — ידיעה והסכמה:** מיכאלה ביצעה פעולה דחופה בידיעתה ובהסכמתה של רונה. האם רונה אחראית? ← כן, לפי סעיף 93(4) לחוק הירושה, אם לא התנגדה.
**וריאציה 2 — התנגדות מפורשת:** רונה התנגדה מפורשות לפעולה של מיכאלה, אך מיכאלה ביצעה אותה בכל זאת. האם רונה אחראית? ← לא, אם תוכיח שהתנגדה, לפי סעיף 93(4) לחוק הירושה.
**וריאציה 3 — אי-ידיעה סבירה:** מיכאלה ביצעה פעולה דחופה, ורונה לא ידעה עליה ולא יכלה לדעת בנסיבות העניין. האם רונה אחראית? ← לא, אם תוכיח שלא ידעה, לפי סעיף 93(4) לחוק הירושה.
**וריאציה 4 — אי-ידיעה רשלנית:** מיכאלה ביצעה פעולה דחופה, ורונה לא ידעה עליה עקב רשלנותה. האם רונה אחראית? ← סעיף 93(4) אינו מתייחס לרשלנות, אך ייתכן שבית המשפט יטיל עליה אחריות אם חוסר הידיעה נבע מהפרת חובת פיקוח כללית.', 'אחריות מנהלי עיזבון ← כל אחד אחראי לפעולת חבריו ← אלא אם התנגד או לא ידע.',
    '["סעיף 93 לחוק הירושה, תשכ\"ה-1965"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'רונה לא תהיה אחראית לפעולה של מיכאלה אם תוכיח שהתנגדה לה או שלא ידעה עליה, וזאת בהתאם לסעיף 93(4) לחוק הירושה.', true, 'סעיף 93(4) לחוק הירושה קובע במפורש כי מנהל עיזבון אינו אחראי לפעולת חבריו אם התנגד לה או לא ידע עליה, ובכך מגן על מנהל עיזבון שלא היה שותף לפעולה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'רונה תהיה אחראית לפעולה של מיכאלה, שכן מנהלי עיזבון נושאים באחריות משותפת ובלתי נפרדת.', false, 'אף שקיימת אחריות משותפת, סעיף 93(4) לחוק הירושה קובע חריג מפורש המאפשר למנהל עיזבון להשתחרר מאחריות בתנאים מסוימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'רונה תהיה אחראית לפעולה של מיכאלה רק אם בית המשפט יקבע שהפעולה הייתה נחוצה.', false, 'האחריות של רונה אינה תלויה בקביעת בית המשפט בדיעבד לגבי נחיצות הפעולה, אלא בידיעתה או התנגדותה לפעולה בעת ביצועה, כאמור בסעיף 93(4) לחוק הירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'רונה תהיה אחראית לפעולה של מיכאלה רק אם לא הודיעה לבית המשפט על אי-הסכמתה לפעולה.', false, 'סעיף 93(4) לחוק הירושה אינו דורש הודעה אקטיבית לבית המשפט על אי-הסכמה כדי להשתחרר מאחריות, אלא מספיק להוכיח התנגדות או חוסר ידיעה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות בית המשפט במחלוקת בין מנהלי עיזבון',
    4, 'מיכאלה ורונה, מנהלות עיזבון, חלוקות בדעותיהן לגבי אופן ניהול נכס מסוים בעיזבון, ואין מדובר בעניין דחוף. מה עליהן לעשות?', 'שאלה זו עוסקת במנגנון ליישוב מחלוקות בין מנהלי עיזבון אחדים, כאשר אין מדובר בעניין דחוף, ומדגישה את תפקידו המכריע של בית המשפט במקרים אלו, בהתאם לסעיף 93(1) לחוק הירושה.', 'סעיף 93(1) לחוק הירושה, תשכ"ה-1965, קובע כי כאשר בית המשפט או הרשם לענייני ירושה מינה שני מנהלי עיזבון או יותר, הם ''חייבים לפעול תוך הסכמה; בענין שדעותיהם חלוקות, יפעלו כפי שיחליט בית המשפט''. לכן, במקרה של מחלוקת שאינה עניין דחוף, על מיכאלה ורונה לפנות לבית המשפט, והוא שיכריע כיצד יש לנהל את הנכס. בית המשפט משמש כגורם מכריע במצבים אלו כדי להבטיח את ניהולו התקין של העיזבון לטובת היורשים.',
    'הקושי הוא להבחין בין המקרים בהם מנהלי עיזבון יכולים לפעול לבד (עניין דחוף) לבין המקרים בהם נדרשת הסכמה או הכרעת בית משפט.', '["מנהלי עיזבון אחדים", "מחלוקת בין מנהלי עיזבון", "חוק הירושה", "סמכות בית המשפט", "ניהול עיזבון"]'::jsonb, '**וריאציה 1 — הסכמה חלקית:** מיכאלה ורונה מסכימות על חלק מהפעולות אך לא על כולן. מה הדין? ← יפעלו בהסכמה על מה שהסכימו, ועל השאר יפנו לבית המשפט, לפי סעיף 93(1).
**וריאציה 2 — אי-הסכמה על חלוקה:** מנהלי עיזבון חלוקים על אופן חלוקת העיזבון. מה הדין? ← יפנו לבית המשפט, שכן חלוקה היא פעולה מהותית שדורשת הסכמה או הכרעה שיפוטית.
**וריאציה 3 — אי-הסכמה על מכירה:** מנהלי עיזבון חלוקים על מכירת נכס שאינו דחוף. מה הדין? ← יפנו לבית המשפט, לפי סעיף 93(1) ו-93(2) לחוק הירושה.
**וריאציה 4 — אי-הסכמה על תביעה:** מנהלי עיזבון חלוקים על הגשת תביעה בשם העיזבון. מה הדין? ← יפנו לבית המשפט, שכן הגשת תביעה דורשת הסכמה או אישור, לפי סעיף 93(2) לחוק הירושה.', 'מחלוקת בין מנהלי עיזבון (לא דחוף) ← פנייה לבית המשפט להכרעה.',
    '["סעיף 93 לחוק הירושה, תשכ\"ה-1965"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'עליהן לפנות לבית המשפט כדי שיחליט כיצד לפעול בעניין, בהתאם לסעיף 93(1) לחוק הירושה.', true, 'סעיף 93(1) לחוק הירושה קובע במפורש כי כאשר דעותיהם של מנהלי עיזבון חלוקות, עליהם לפעול כפי שיחליט בית המשפט, וזאת במקרים שאינם דחופים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'עליהן להגיע להסכמה ביניהן, ובהיעדר הסכמה הפעולה לא תבוצע.', false, 'אף שנדרשת הסכמה, במקרה של מחלוקת שאינה נפתרת, החוק מספק מנגנון הכרעה באמצעות בית המשפט, ולא מונע את ביצוע הפעולה לחלוטין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'מיכאלה, כמנהלת עיזבון בכירה יותר, רשאית להכריע בעניין.', false, 'חוק הירושה אינו קובע היררכיה בין מנהלי עיזבון, ואין למנהל עיזבון אחד סמכות הכרעה על פני האחר במקרה של מחלוקת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'עליהן להמתין עד שיתמנה מנהל עיזבון יחיד שיכריע בעניין.', false, 'אין צורך במינוי מנהל עיזבון יחיד, שכן החוק מספק מנגנון הכרעה למנהלי עיזבון אחדים באמצעות בית המשפט.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 22, '2022-W-S-Q22';
END
$$;

