-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '8fb98d0f-3341-464c-b27f-b7b740e370fe'::uuid;
  v_group_id uuid := 'bc237424-5dd8-4854-bf0f-be4a258d28fc'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '4aa402a8-a79c-4d6f-b439-5b331dd4a290'::uuid;
  v_ang_1 uuid := '07635653-6257-4d9e-88ad-9899b4df90b1'::uuid;
  v_ang_2 uuid := '5db4db4a-9db2-4776-b5ec-50aab4f28660'::uuid;
  v_ang_3 uuid := '77ca37f1-6987-4b91-90c2-20c4ce2a3251'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q23';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 23, '2022-W-S-Q23';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'road_accident_victims' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'road_accident_victims', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q23', v_chapter_id, v_subtopic_id, 'במהלך נסיעה של סיוון, אזרחית ישראל, ברכבה הפרטי בשטחי האחריות האזרחית הפלסטינית פגעה בעוצמה ברכבם של רמזי, תושב מקום האירוע, ויקי, תיירת חוץ בריטית שהייתה בטיול, ואלדד, חייל ישראל בשירות סדיר, וגרמה לפציעתם. את מי חייבת סיוון לפצות בגין נזקי הגוף?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 23}'::jsonb, 'שאלה זו עוסקת בתחולת חוק הפיצויים לנפגעי תאונות דרכים, התשל"ה-1975 (חוק הפלת"ד), על תאונות שאירעו בשטחי האחריות האזרחית הפלסטינית, תוך התייחסות לחריגים הקבועים בסעיף 2(א1) לחוק, המרחיבים את תחולתו על נפגעים ישראלים ותיירי חוץ המעורבים ברכב ישראלי.', 'חוק הפיצויים לנפגעי תאונות דרכים הוא חוק בעל תחולה טריטוריאלית, כלומר חל ככלל רק בתחומי מדינת ישראל. עם זאת, סעיף 2(א1) לחוק קובע חריג חשוב: ''הנוהג ברכב ישראלי חייב לפצות נפגע שהוא ישראלי או תייר חוץ, על נזק גוף שנגרם לו בתאונת דרכים שבה מעורב הרכב אף אם התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית או באזורים ויראו את התאונה כאילו אירעה בישראל''. במקרה הנדון, סיוון נהגה ברכב ישראלי בשטחי האחריות האזרחית הפלסטינית. אלדד הוא חייל ישראלי, ולכן נחשב ל''ישראלי'' כהגדרתו בחוק. ויקי היא תיירת חוץ בריטית, ונכללת בהגדרת ''תייר חוץ'' בסעיף. לעומת זאת, רמזי הוא ''תושב מקום האירוע'', כלומר תושב שטחים, ואינו נכלל בהגדרות ''ישראלי'' או ''תייר חוץ'' לצורך סעיף זה. לכן, סיוון חייבת לפצות את ויקי ואלדד לפי חוק הפיצויים הישראלי, אך לא את רמזי, שעליו יחול דין המקום (הדין הפלסטיני).', 'הטעות הנפוצה היא להניח שתחולת חוק הפיצויים הישראלי בשטחי הרשות הפלסטינית תלויה רק בזהות הנהג או הרכב הישראלי, מבלי להתייחס לזהות הנפגע, או לחילופין, להתעלם מההבחנה בין ישראלים/תיירי חוץ לבין תושבי שטחים.',
    '["חוק פיצויים לנפגעי תאונות דרכים", "תחולה טריטוריאלית", "סעיף 2(א1)", "ישראלי", "תייר חוץ", "תושב שטחים", "רכב ישראלי", "דין המקום"]'::jsonb, '**וריאציה 1 — נפגע ישראלי:** ישראלי נפגע מרכב ישראלי בשטחי הרשות. האם חל חוק הפלת"ד? ← כן, לפי סעיף 2(א1) לחוק הפיצויים.
**וריאציה 2 — נפגע תושב שטחים:** תושב שטחים נפגע מרכב ישראלי בשטחי הרשות. האם חל חוק הפלת"ד? ← לא, סעיף 2(א1) אינו חל על תושב שטחים. יחול דין המקום.
**וריאציה 3 — נפגע תייר חוץ:** תייר חוץ נפגע מרכב ישראלי בשטחי הרשות. האם חל חוק הפלת"ד? ← כן, לפי סעיף 2(א1) לחוק הפיצויים.
**וריאציה 4 — נפגע ישראלי ברכב פלסטיני:** ישראלי נפגע מרכב פלסטיני בשטחי הרשות. האם חל חוק הפלת"ד? ← לא, סעיף 2(א1) דורש רכב ישראלי. ייתכן פיצוי מקרנית לפי סעיף 12(ה).', 'תאונת דרכים בשטחים עם רכב ישראלי ← פיצוי לפי חוק הפלת"ד רק לישראלים ותיירי חוץ (סעיף 2(א1)).', '["סעיף 2 לחוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975", "ת\"א (שלום טב'') 27897-11-13 מוחמד בני נמרה נ'' אמג''ד חאג'' עלי (13.09.2015)", "ת\"א (שלום פ\"ת) 28096-01-14 פלוני- ז.ר נ'' פלוני- א.א (06.06.2017)", "רע\"א 1667/09 פלונית נ'' פלונית (02.08.2010)", "נבו - המתמחה דיני נזיקין (2026) | סימן א'': פיצויים על נזקי גוף"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''אכיפת פסק חוץ'' → mapped chapter=''torts'' subtopic=''road_accident_victims'' | classifier_note: Israeli driver in Palestinian-controlled territory hits Palestinian + British tourist + IDF soldier — extraterritorial application of road-accident law (פלת''ד) | source_review_note: השאלה עוסקת בתחולה טריטוריאלית של חוק ישראלי (חוק הפלת"ד) בשטחי הרשות הפלסטינית, וברירת הדין במקרים אלו. נושא זה שייך לתחום המשפט הבינלאומי הפרטי (Conflict of Laws). הסאב-טופיק ''אכיפת פסק חוץ'' תחת ''חוקתי + בינלאומי פרטי'' נבחר כברירת מחדל הקרובה ביותר מתוך הרשימה הסגורה, אך אינו מתאר במדויק את הנושא. יש לשקול הוספת סאב-טופיק ייעודי לתחולת חוקים/ברירת דין במשפט הבינלאומי הפרטי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'את רמזי וויקי.', false, 'רמזי, כתושב מקום האירוע, אינו נכלל בחריג שבסעיף 2(א1) לחוק הפיצויים, ולכן חוק הפיצויים הישראלי אינו חל עליו. ויקי, כתיירת חוץ, כן נכללת.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'את ויקי ואלדד.', true, 'סעיף 2(א1) לחוק הפיצויים קובע כי הנוהג ברכב ישראלי חייב לפצות נפגע שהוא ישראלי (כמו אלדד) או תייר חוץ (כמו ויקי), גם אם התאונה אירעה בשטחי האחריות האזרחית הפלסטינית.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'את אלדד ורמזי.', false, 'רמזי, כתושב מקום האירוע, אינו נכלל בחריג שבסעיף 2(א1) לחוק הפיצויים, ולכן חוק הפיצויים הישראלי אינו חל עליו. אלדד, כישראלי, כן נכלל.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'את רמזי, ויקי ואלדד.', false, 'רמזי, כתושב מקום האירוע, אינו נכלל בחריג שבסעיף 2(א1) לחוק הפיצויים, ולכן חוק הפיצויים הישראלי אינו חל עליו. רק ויקי ואלדד זכאים לפיצויים לפי חוק הפיצויים הישראלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחולת חוק הפלת"ד על תייר חוץ ברכב פלסטיני',
    1, 'תייר חוץ בריטי נפגע בתאונת דרכים בשטחי האחריות האזרחית הפלסטינית, כאשר רכב פלסטיני פגע בו. האם חוק הפיצויים לנפגעי תאונות דרכים הישראלי חל עליו?', 'שאלה זו בוחנת את ההבנה המדויקת של תנאי התחולה של סעיף 2(א1) לחוק הפיצויים לנפגעי תאונות דרכים, ובפרט את הדרישה למעורבות ''רכב ישראלי'' כדי להחיל את החוק על תייר חוץ שנפגע בשטחי הרשות הפלסטינית.', 'חוק הפיצויים לנפגעי תאונות דרכים, התשל"ה-1975, הוא חוק בעל תחולה טריטוריאלית, כלומר חל ככלל רק בתחומי מדינת ישראל. סעיף 2(א1) לחוק קובע חריג לתחולה זו, לפיו הנוהג ב''רכב ישראלי'' חייב לפצות נפגע שהוא ''ישראלי'' או ''תייר חוץ'' על נזק גוף שנגרם לו בתאונת דרכים שבה מעורב הרכב, אף אם התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית. במקרה זה, אף שהנפגע הוא תייר חוץ והתאונה אירעה בשטחי הרשות, הרכב הפוגע אינו רכב ישראלי, ולכן החריג שבסעיף 2(א1) אינו חל. במצב כזה, יחול דין המקום, קרי הדין הפלסטיני.',
    'טעות נפוצה היא להתמקד רק בזהות הנפגע (תייר חוץ) ולהתעלם מהדרישה הנוספת למעורבות ''רכב ישראלי'' לצורך תחולת סעיף 2(א1) לחוק הפיצויים.', '["חוק פיצויים לנפגעי תאונות דרכים", "תחולה טריטוריאלית", "סעיף 2(א1)", "רכב ישראלי", "תייר חוץ", "דין המקום"]'::jsonb, '**וריאציה 1 — רכב ישראלי:** תייר חוץ נפגע מרכב ישראלי בשטחי הרשות. האם חל חוק הפלת"ד? ← כן, לפי סעיף 2(א1) לחוק הפיצויים.
**וריאציה 2 — ישראלי ברכב פלסטיני:** ישראלי נפגע מרכב פלסטיני בשטחי הרשות. האם חל חוק הפלת"ד? ← לא, סעיף 2(א1) דורש רכב ישראלי. ייתכן פיצוי מקרנית לפי סעיף 12(ה).
**וריאציה 3 — תושב שטחים ברכב ישראלי:** תושב שטחים נפגע מרכב ישראלי בשטחי הרשות. האם חל חוק הפלת"ד? ← לא, סעיף 2(א1) אינו חל על תושב שטחים. יחול דין המקום.
**וריאציה 4 — תייר חוץ בישראל:** תייר חוץ נפגע מרכב פלסטיני בישראל. האם חל חוק הפלת"ד? ← כן, כי התאונה אירעה בישראל, והחוק חל טריטוריאלית.', 'תחולת חוק הפלת"ד בשטחים על תייר חוץ ← רק אם מעורב רכב ישראלי.',
    '["סעיף 2 לחוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975", "ת\"א (שלום טב'') 27897-11-13 מוחמד בני נמרה נ'' אמג''ד חאג'' עלי (13.09.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שהוא תייר חוץ.', false, 'אף שהוא תייר חוץ, סעיף 2(א1) לחוק הפיצויים דורש שהתאונה תהיה מעורבת ב''רכב ישראלי'' כדי שהחוק יחול.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שהרכב הפוגע אינו רכב ישראלי.', true, 'סעיף 2(א1) לחוק הפיצויים קובע במפורש כי החריג לתחולה הטריטוריאלית חל רק כאשר מדובר ב''רכב ישראלי''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם התאונה אירעה באזור C.', false, 'מיקום התאונה בשטח C אינו מספיק להחלת חוק הפיצויים הישראלי על תייר חוץ, אם הרכב הפוגע אינו ישראלי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שהתאונה אירעה בשטחי האחריות האזרחית הפלסטינית.', false, 'התשובה אינה מדויקת, שכן סעיף 2(א1) לחוק הפיצויים כן מאפשר תחולה בשטחים אלו, אך בתנאים מסוימים, שאחד מהם הוא מעורבות רכב ישראלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי תחולת סעיף 2(א1) לחוק הפלת"ד',
    2, 'מהם התנאים המצטברים להחלת סעיף 2(א1) לחוק הפיצויים לנפגעי תאונות דרכים על תאונה שאירעה באזור או בשטחי האחריות האזרחית הפלסטינית?', 'שאלה זו בוחנת את הבקיאות בתנאים המפורטים בסעיף 2(א1) לחוק הפיצויים לנפגעי תאונות דרכים, המרחיבים את תחולת החוק מעבר לגבולות הטריטוריאליים של מדינת ישראל, ומדגישה את הצורך בהבנת כלל המרכיבים של הסעיף.', 'סעיף 2(א1) לחוק הפיצויים לנפגעי תאונות דרכים, התשל"ה-1975, קובע חריג לכלל התחולה הטריטוריאלית של החוק. על מנת שהחוק יחול על תאונת דרכים שאירעה באזור או בשטחי האחריות האזרחית הפלסטינית, יש צורך בקיומם של שלושה תנאים מצטברים: 1. התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית. 2. הנפגע הוא ''ישראלי'' או ''תייר חוץ'' (כהגדרתם בחוק). 3. הרכב המעורב בתאונה הוא ''רכב ישראלי'' (כהגדרתו בחוק). רק כאשר כל התנאים הללו מתקיימים, ''יראו את התאונה כאילו אירעה בישראל'' ויחול הדין הישראלי.',
    'הקושי הוא לזכור את כל שלושת התנאים המצטברים ולהימנע מהתמקדות חלקית באחד מהם בלבד.', '["חוק פיצויים לנפגעי תאונות דרכים", "סעיף 2(א1)", "תנאים מצטברים", "תחולה טריטוריאלית", "ישראלי", "תייר חוץ", "רכב ישראלי"]'::jsonb, '**וריאציה 1 — חסר תנאי:** תאונה בשטחים, נפגע ישראלי, רכב פלסטיני. האם חל סעיף 2(א1)? ← לא, חסר תנאי הרכב הישראלי.
**וריאציה 2 — חסר תנאי:** תאונה בשטחים, נפגע תושב שטחים, רכב ישראלי. האם חל סעיף 2(א1)? ← לא, חסר תנאי זהות הנפגע (ישראלי/תייר חוץ).
**וריאציה 3 — כל התנאים:** תאונה בשטחים, נפגע ישראלי, רכב ישראלי. האם חל סעיף 2(א1)? ← כן, כל התנאים מתקיימים.
**וריאציה 4 — תאונה בישראל:** תאונה בישראל, נפגע ישראלי, רכב פלסטיני. האם חל סעיף 2(א1)? ← לא, סעיף 2(א1) עוסק בתאונות מחוץ לישראל. במקרה זה חל חוק הפלת"ד מכוח תחולתו הטריטוריאלית הרגילה.', 'תנאי סעיף 2(א1) לחוק הפלת"ד ← תאונה בשטחים + נפגע ישראלי/תייר חוץ + רכב ישראלי.',
    '["סעיף 2 לחוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975", "נבו - המתמחה דיני נזיקין (2026) | סימן א'': פיצויים על נזקי גוף"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית, הנפגע הוא ישראלי או תייר חוץ, והרכב המעורב הוא רכב ישראלי.', true, 'אלו הם שלושת התנאים המצטברים המפורטים בסעיף 2(א1) לחוק הפיצויים, המרחיבים את תחולת החוק מעבר לגבולות ישראל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית, והנפגע הוא ישראלי או תייר חוץ, ללא קשר לסוג הרכב המעורב.', false, 'תשובה זו שגויה מכיוון שהיא מתעלמת מהדרישה המפורשת בסעיף 2(א1) לחוק הפיצויים כי הרכב המעורב יהיה ''רכב ישראלי''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית, והרכב המעורב הוא רכב ישראלי, ללא קשר לזהות הנפגע.', false, 'תשובה זו שגויה מכיוון שהיא מתעלמת מהדרישה המפורשת בסעיף 2(א1) לחוק הפיצויים כי הנפגע יהיה ''ישראלי'' או ''תייר חוץ''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'התאונה אירעה באזור או בשטחי האחריות האזרחית הפלסטינית, והנפגע אינו תושב האזור.', false, 'תשובה זו אינה מדויקת מספיק, שכן היא אינה מפרטת את זהות הנפגע באופן מלא (ישראלי או תייר חוץ) ומתעלמת מהדרישה למעורבות רכב ישראלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'נפגע ישראלי ברכב פלסטיני בשטחים',
    3, 'יוסי, אזרח ישראלי, נפגע בתאונת דרכים בשטחי האחריות האזרחית הפלסטינית, כאשר רכב פלסטיני פגע בו. הרכב הפלסטיני מבוטח בחברת ביטוח פלסטינית. מה הדין לגבי פיצויו של יוסי?', 'שאלה זו בוחנת את ההבנה של מנגנון הפיצויים המיוחד לישראלים שנפגעו בתאונות דרכים בשטחי הרשות הפלסטינית על ידי רכב פלסטיני, כפי שקבוע בסעיף 12(ה) לחוק הפיצויים לנפגעי תאונות דרכים, המאפשר השלמת פיצויים מקרנית.', 'כאשר אזרח ישראלי (יוסי) נפגע בתאונת דרכים בשטחי האחריות האזרחית הפלסטינית על ידי רכב פלסטיני, סעיף 2(א1) לחוק הפיצויים לנפגעי תאונות דרכים אינו חל, שכן הוא דורש מעורבות ''רכב ישראלי''. במקרה כזה, הדין החל על התאונה הוא הדין הפלסטיני. עם זאת, סעיף 12(ה) לחוק הפיצויים קובע מנגנון מיוחד לישראלים: קרנית תשלם לנפגע שהוא ישראלי, שנפגע בתאונת דרכים שאירעה באזור או בשטחי האחריות הפלסטינית, השלמת פיצויים בסכום ההפרש שבין הפיצויים שהיה זכאי להם אילו אירעה התאונה בישראל, לבין הפיצויים שהוא זכאי לקבל לפי הדין במקום התאונה. זאת, בתנאי שהחבות לגביה אינה מכוסה בפוליסה שהוציא מבטח ישראלי.',
    'הקושי הוא לזכור את ההוראה הספציפית של סעיף 12(ה) לחוק הפיצויים, המהווה מנגנון השלמה לישראלים במקרים בהם חוק הפיצויים אינו חל במלואו.', '["חוק פיצויים לנפגעי תאונות דרכים", "קרנית", "סעיף 12(ה)", "ישראלי", "שטחי האחריות האזרחית הפלסטינית", "השלמת פיצויים", "דין המקום"]'::jsonb, '**וריאציה 1 — רכב ישראלי:** יוסי נפגע מרכב ישראלי בשטחי הרשות. מה הדין? ← יפוצה לפי חוק הפלת"ד הישראלי, לפי סעיף 2(א1).
**וריאציה 2 — תושב שטחים:** רמזי, תושב שטחים, נפגע מרכב פלסטיני בשטחי הרשות. מה הדין? ← יפוצה לפי הדין הפלסטיני בלבד.
**וריאציה 3 — רכב פלסטיני לא מבוטח:** יוסי נפגע מרכב פלסטיני לא מבוטח בשטחי הרשות. מה הדין? ← יפוצה לפי הדין הפלסטיני, וקרנית תשלם השלמה לפי סעיף 12(ה).
**וריאציה 4 — תייר חוץ ברכב פלסטיני:** ויקי, תיירת חוץ, נפגעה מרכב פלסטיני בשטחי הרשות. מה הדין? ← תפוצה לפי הדין הפלסטיני בלבד, ללא השלמה מקרנית (סעיף 12(ה) חל רק על ישראלים).', 'ישראלי נפגע ברכב פלסטיני בשטחים ← פיצוי לפי דין פלסטיני + השלמה מקרנית (סעיף 12(ה)).',
    '["סעיף 12 לחוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975", "יצחק אנגלרד פיצויים לנפגעי תאונות דרכים (2022) | (1) פגיעה בשטחים בישראלי או בתייר חוץ על ידי רכב ישראלי", "נבו - המתמחה דיני נזיקין (2026) | פרק ג'' - קרן לפיצוי נפגעי תאונות דרכים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'יוסי יפוצה במלואו לפי חוק הפיצויים הישראלי על ידי חברת הביטוח הפלסטינית.', false, 'חוק הפיצויים הישראלי אינו חל במקרה זה מכיוון שהרכב הפוגע אינו ישראלי. הפיצוי מחברת הביטוח הפלסטינית יהיה לפי הדין הפלסטיני.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יוסי יפוצה לפי הדין הפלסטיני, וקרנית תשלם לו השלמת פיצויים עד לגובה הפיצויים שהיה זכאי להם אילו התאונה אירעה בישראל.', true, 'סעיף 12(ה) לחוק הפיצויים קובע כי קרנית תשלם לנפגע שהוא ישראלי, שנפגע בשטחים, השלמת פיצויים בסכום ההפרש בין הפיצויים שהיה זכאי להם לפי הדין הישראלי לבין הפיצויים שיקבל לפי דין המקום, אם החבות אינה מכוסה בפוליסה שהוציא מבטח ישראלי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'יוסי יפוצה במלואו לפי הדין הפלסטיני, ללא כל השלמה מקרנית.', false, 'תשובה זו מתעלמת מהוראת סעיף 12(ה) לחוק הפיצויים, המאפשרת לישראלי שנפגע בשטחים לקבל השלמת פיצויים מקרנית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'יוסי לא יהיה זכאי לפיצויים כלל, מכיוון שהתאונה אירעה מחוץ לישראל וברכב פלסטיני.', false, 'יוסי זכאי לפיצויים לפחות לפי הדין הפלסטיני, ובנוסף זכאי להשלמה מקרנית לפי סעיף 12(ה) לחוק הפיצויים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'פיצוי לתושב שטחים שנפגע מרכב ישראלי לא מבוטח',
    4, 'רמזי, תושב שטחי האחריות האזרחית הפלסטינית, נפגע בתאונת דרכים בשטחים על ידי רכב ישראלי לא מבוטח. מה הדין לגבי פיצויו של רמזי?', 'שאלה זו בוחנת את תפקידה של קרנית בפיצוי נפגעים שאינם ישראלים בתאונות דרכים בשטחי הרשות הפלסטינית, כאשר הרכב הפוגע הוא ישראלי ולא מבוטח, תוך הדגשת העיקרון של פיצוי לפי דין המקום, כפי שקבוע בסעיף 12(ד) לחוק הפיצויים לנפגעי תאונות דרכים.', 'סעיף 12(ד) לחוק הפיצויים לנפגעי תאונות דרכים, התשל"ה-1975, קובע כי אם אירעה תאונת דרכים באזור או בשטחי האחריות הפלסטינית, קרנית תפצה נפגע שאינו ישראלי (כמו רמזי) הזכאי לפיצויים ואין בידו לתבוע פיצויים מאת מבטח (למשל, במקרה של רכב לא מבוטח). הפיצוי יהיה בהתאם לדין החל במקום התאונה, כלומר לפי הדין הפלסטיני. תפקידה של קרנית הוא להבטיח פיצוי גם במקרים בהם אין מבטח זמין, תוך שמירה על עקרון ברירת הדין של מקום התאונה עבור נפגעים שאינם ישראלים או תיירי חוץ.',
    'הקושי הוא להבחין בין סעיף 12(ד) (פיצוי ללא ישראלים לפי דין המקום) לבין סעיף 12(ה) (השלמת פיצויים לישראלים).', '["חוק פיצויים לנפגעי תאונות דרכים", "קרנית", "סעיף 12(ד)", "תושב שטחים", "רכב לא מבוטח", "דין המקום", "שטחי האחריות האזרחית הפלסטינית"]'::jsonb, '**וריאציה 1 — רמזי נפגע מרכב ישראלי מבוטח:** רמזי נפגע מרכב ישראלי מבוטח בשטחים. מה הדין? ← יפוצה לפי הדין הפלסטיני על ידי המבטח הישראלי, שכן סעיף 2(א1) אינו חל עליו.
**וריאציה 2 — רמזי נפגע מרכב פלסטיני לא מבוטח:** רמזי נפגע מרכב פלסטיני לא מבוטח בשטחים. מה הדין? ← יפוצה על ידי הקרן הפלסטינית, אם קיימת, לפי הדין הפלסטיני.
**וריאציה 3 — ישראלי נפגע מרכב ישראלי לא מבוטח בשטחים:** יוסי, ישראלי, נפגע מרכב ישראלי לא מבוטח בשטחים. מה הדין? ← יפוצה על ידי קרנית לפי חוק הפלת"ד הישראלי, שכן סעיף 2(א1) חל עליו וקרנית נכנסת בנעלי המבטח.
**וריאציה 4 — תייר חוץ נפגע מרכב ישראלי לא מבוטח בשטחים:** ויקי, תיירת חוץ, נפגעה מרכב ישראלי לא מבוטח בשטחים. מה הדין? ← תפוצה על ידי קרנית לפי חוק הפלת"ד הישראלי, שכן סעיף 2(א1) חל עליה וקרנית נכנסת בנעלי המבטח.', 'תושב שטחים נפגע מרכב ישראלי לא מבוטח בשטחים ← קרנית תפצה לפי דין פלסטיני (סעיף 12(ד)).',
    '["סעיף 12 לחוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975", "נבו - המתמחה דיני נזיקין (2026) | פרק ג'' - קרן לפיצוי נפגעי תאונות דרכים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'רמזי יפוצה על ידי קרנית לפי הדין הפלסטיני.', true, 'סעיף 12(ד) לחוק הפיצויים קובע כי קרנית תפצה נפגע שאינו ישראלי (כמו רמזי) שנפגע בשטחים, אם אין בידו לתבוע פיצויים ממבטח (למשל, במקרה של רכב לא מבוטח), והפיצוי יהיה בהתאם לדין החל במקום התאונה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'רמזי יפוצה על ידי קרנית לפי חוק הפיצויים הישראלי.', false, 'אף שקרנית תפצה את רמזי, הפיצוי יהיה לפי הדין הפלסטיני (דין המקום), ולא לפי חוק הפיצויים הישראלי, מכיוון שרמזי אינו ישראלי או תייר חוץ.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'רמזי יפוצה על ידי בעל הרכב הישראלי הלא מבוטח, לפי הדין הפלסטיני.', false, 'אף שבעל הרכב הלא מבוטח חב בפיצויים, במקרה של רכב לא מבוטח, קרנית היא הגוף המפצה, והיא רשאית לחזור על בעל הרכב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'רמזי לא יהיה זכאי לפיצויים כלל, מכיוון שהרכב הפוגע לא היה מבוטח.', false, 'קרנית הוקמה בין היתר כדי לפצות נפגעים במקרים של היעדר ביטוח, ולכן רמזי כן זכאי לפיצויים מקרנית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 23, '2022-W-S-Q23';
END
$$;

-- ============================================================
-- Q24 — 2022-W-S-Q24 — chapter=corporate subtopic=companies_formation
-- classifier_note: 5%-shareholder demand to convene special meeting — minority shareholder rights
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'ca985ff9-6a3a-4b68-8db2-7a488f04101f'::uuid;
  v_group_id uuid := '48608148-d2cd-45d9-998a-22656b42dc62'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'cbef024d-d168-470d-8e02-4b468d8ab8b5'::uuid;
  v_ang_1 uuid := '4cb63026-76fd-4151-af55-80683beb0812'::uuid;
  v_ang_2 uuid := 'a9182b0b-9b19-4650-bb37-257663ba5b7e'::uuid;
  v_ang_3 uuid := 'baed66f6-35b7-4335-9727-1cb8ddb5da77'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q24';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 24, '2022-W-S-Q24';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'companies_formation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'companies_formation', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q24', v_chapter_id, v_subtopic_id, 'מר חרובי הוא בעל מניות שלו למעלה מ-5% מזכויות ההצבעה בחברה הציבורית "השותלים בע"מ". מר חרובי פנה לחברה בדרישה לכנס אסיפה מיוחדת של בעלי המניות, אך החברה לא נעתרה לדרישתו. מר חרובי מעוניין לפנות לבית המשפט כדי לקבל סעד. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 24}'::jsonb, 'שאלה זו עוסקת בזכויות בעלי מניות בחברה ציבורית לדרוש כינוס אסיפה מיוחדת, ובסעדים העומדים לרשותם כאשר הדירקטוריון מסרב לדרישה זו, בהתאם להוראות חוק החברות.', 'על פי סעיף 63(ב)(2) לחוק החברות, תשנ"ט-1999, בעל מניות שלו לפחות 5% מזכויות ההצבעה בחברה ציבורית רשאי לדרוש מהדירקטוריון לכנס אסיפה מיוחדת. אם הדירקטוריון לא זימן את האסיפה שנדרשה, סעיף 65(א) לחוק מאפשר לבעל המניות לפנות לבית המשפט בבקשה להורות על כינוסה. בנוסף, אי-כינוס אסיפה, במיוחד כאשר הוא פוגע בזכויות מהותיות של בעלי מניות, יכול להיחשב כקיפוח בעלי מניות המיעוט לפי סעיף 191 לחוק, המעניק לבית המשפט שיקול דעת רחב במתן סעדים. כמו כן, הפרת חובה סטטוטורית (כמו החובה לזמן אסיפה) נחשבת להפרת חוזה, וניתן לתבוע בגינה סעדים חוזיים מכוח סעיף 352(א) לחוק החברות.', 'הטעות הנפוצה היא להכיר רק בסעד אחד מבין מגוון הסעדים העומדים לרשות בעל המניות, או לבלבל בין התנאים לדרישת כינוס אסיפה לבין התנאים לכינוס עצמי או לפנייה לבית המשפט.',
    '["חוק החברות", "אסיפה מיוחדת", "דירקטוריון", "סמכות בית המשפט", "הסרת קיפוח", "הפרת חוזה", "זכויות בעלי מניות"]'::jsonb, '**וריאציה 1 — כינוס עצמי:** האם מר חרובי יכול לכנס את האסיפה בעצמו? ← כן, אם הוא עומד בתנאי סעיף 64 לחוק החברות, כלומר, אם הוא או חלק מבעלי המניות שדרשו את הכינוס מחזיקים ביותר ממחצית מזכויות ההצבעה שלהם.
**וריאציה 2 — דרישת 1% מההון המונפק:** מה אם למר חרובי יש 5% מזכויות ההצבעה אבל פחות מ-1% מההון המונפק? ← עדיין זכאי לדרוש כינוס אסיפה מיוחדת בחברה ציבורית, לפי סעיף 63(ב)(2) לחוק החברות.
**וריאציה 3 — חברה פרטית:** מה אם זו הייתה חברה פרטית? ← דרישת הכינוס הייתה דורשת לפחות 10% מההון המונפק ו-1% מזכויות ההצבעה, או 10% מזכויות ההצבעה, לפי סעיף 63(א)(2) לחוק החברות.
**וריאציה 4 — הוצאות משפטיות:** מי יישא בהוצאות המשפטיות אם בית המשפט יורה על כינוס האסיפה? ← החברה תישא בהוצאות סבירות, והדירקטורים האחראים לאי-כינוס יהיו חייבים להשיבן לחברה, לפי סעיף 65(ב) לחוק החברות.', 'אי-כינוס אסיפה מיוחדת ע"י דירקטוריון ← פנייה לביהמ"ש להורות על כינוס (ס'' 65) / תביעה להסרת קיפוח (ס'' 191) / תביעה על הפרת חוזה (ס'' 352).', '["סעיף 65 לחוק החברות, תשנ\"ט-1999", "סעיף 191 לחוק החברות, תשנ\"ט-1999", "סעיף 352 לחוק החברות, תשנ\"ט-1999", "ת\"א (מחוזי מרכז) 57198-03-23 Murchinson Ltd., Canadian נ'' ננו דיימנשן בע\"מ (21.11.2024)", "רע\"א 3104/23 ננו דיימנשן בע\"מ נ'' Murchinson Ltd. Canadian Comp (14.06.2023)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: 5%-shareholder demand to convene special meeting — minority shareholder rights | source_review_note: השאלה עוסקת בדיני חברות, ובפרט בזכויות בעלי מניות וכינוס אסיפות. סאב-טופיק ''הליכים'' תחת ''סדר דין אזרחי'' הוא כללי מדי. יש לשקול הוספת סאב-טופיק ייעודי לדיני חברות או לזכויות בעלי מניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מר חרובי יכול לפנות לבית המשפט בבקשה להסרת קיפוח. אם לא עשה כן, לא יעמוד לו כל סעד אחר.', false, 'אף שסעד של הסרת קיפוח אפשרי, הוא אינו הסעד היחיד. החוק מציע מספר חלופות, כולל פנייה לבית המשפט להורות על כינוס האסיפה או תביעה על הפרת חוזה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מר חרובי יכול לפנות לבית המשפט בבקשה להורות על כינוס האסיפה המיוחדת. באפשרותו גם לפנות לבית המשפט בבקשה להסרת קיפוח, וכן לתבוע על פי הדינים החלים על הפרת חוזה.', true, 'סעיף 65 לחוק החברות מאפשר פנייה לבית המשפט להורות על כינוס האסיפה. אי-כינוס אסיפה יכול להיחשב קיפוח מיעוט לפי סעיף 191, והפרת חובה סטטוטורית נחשבת הפרת חוזה לפי סעיף 352 לחוק החברות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מר חרובי לא יכול לבוא בטענות לחברה, שכן לא נתון כי הוא מחזיק בלמעלה מ-5% מההון המונפק.', false, 'סעיף 63(ב)(2) לחוק החברות קובע כי די בהחזקה של לפחות 5% מזכויות ההצבעה בחברה ציבורית כדי לדרוש כינוס אסיפה מיוחדת, גם ללא עמידה בתנאי ההון המונפק.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מר חרובי לא יכול לזכות בסעד מבית המשפט, שכן לא מדובר במצב של הסטת משאבי החברה לטובת חלק מבעלי מניותיה.', false, 'קיפוח מיעוט אינו מוגבל רק להסטת משאבים, אלא יכול לכלול גם פגיעה בזכויות מהותיות של בעלי מניות, כמו הזכות לדרוש כינוס אסיפה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'כינוס אסיפה עצמית על ידי בעלי מניות',
    1, 'מר חרובי, בעל מניות בחברה הציבורית "השותלים בע"מ", דרש לכנס אסיפה מיוחדת, אך הדירקטוריון לא נענה לדרישתו. מר חרובי מעוניין לכנס את האסיפה בעצמו. מהם התנאים לכך?', 'שאלה זו בוחנת את זכותם של בעלי מניות לכנס אסיפה כללית מיוחדת בעצמם, כאשר הדירקטוריון מסרב לדרישתם, ואת התנאים והמגבלות החלות על זכות זו לפי חוק החברות.', 'על פי סעיף 64(א) לחוק החברות, תשנ"ט-1999, אם הדירקטוריון לא זימן אסיפה מיוחדת שנדרשה לפי סעיף 63, רשאי הדורש, וכשמדובר בבעלי מניות – גם חלק מהם שיש לו יותר ממחצית מזכויות ההצבעה שלהם, לכנס את האסיפה בעצמו. כינוס זה מוגבל בזמן, ובלבד שהאסיפה לא תתקיים לאחר שלושה חודשים מהיום שהוגשה הדרישה. החברה תישא בהוצאות הסבירות שהוציא הדורש, והדירקטורים האחראים לאי-כינוסה יהיו חייבים להשיבן לחברה, כאמור בסעיף 64(ב).',
    'טעות נפוצה היא לבלבל בין התנאים לכינוס אסיפה עצמית לבין התנאים לדרישת כינוס אסיפה מהדירקטוריון, או להתעלם ממגבלת הזמן לכינוס העצמי.', '["חוק החברות", "אסיפה מיוחדת", "כינוס עצמי", "סעיף 64", "זכויות הצבעה", "הוצאות כינוס"]'::jsonb, '**וריאציה 1 — דרישה משותפת:** מר חרובי ועוד בעל מניות דרשו כינוס אסיפה, אך רק מר חרובי מעוניין לכנס בעצמו. האם הוא יכול? ← כן, אם הוא מחזיק ביותר ממחצית מזכויות ההצבעה של כלל הדורשים, לפי סעיף 64(א) לחוק החברות.
**וריאציה 2 — חריגה מ-3 חודשים:** האם ניתן לכנס אסיפה עצמית ארבעה חודשים לאחר הדרישה? ← לא, סעיף 64(א) לחוק החברות קובע מגבלה של שלושה חודשים.
**וריאציה 3 — הוצאות כינוס:** מי נושא בהוצאות כינוס אסיפה עצמית? ← החברה תישא בהוצאות סבירות, והדירקטורים האחראים לאי-כינוס חייבים להשיבן לחברה, לפי סעיף 64(ב) לחוק החברות.
**וריאציה 4 — סעיף קוגנטי:** האם ניתן להתנות על הזכות לכינוס אסיפה עצמית בתקנון החברה? ← לא, סעיף 64 לחוק החברות הוא קוגנטי ולא ניתן להתנות עליו, כפי שנקבע בפסיקה (ת"א (מחוזי מרכז) 57198-03-23).', 'דירקטוריון לא זימן אסיפה ← בעלי מניות יכולים לכנס בעצמם (ס'' 64) ← תוך 3 חודשים ← החברה מכסה הוצאות.',
    '["סעיף 64 לחוק החברות, תשנ\"ט-1999", "ת\"א (מחוזי מרכז) 57198-03-23 Murchinson Ltd., Canadian נ'' ננו דיימנשן בע\"מ (21.11.2024)", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | א. תביעה לכינוס אסיפה מיוחדת", "זוהר גושן אסף אקשטיין דיני חברות (2023) | 3.2 אסיפה מיוחדת"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'מר חרובי רשאי לכנס את האסיפה בעצמו, ובלבד שהיא תתקיים תוך שלושה חודשים מיום הגשת הדרישה לדירקטוריון, והוא מחזיק ביותר ממחצית מזכויות ההצבעה של בעלי המניות שדרשו את הכינוס.', true, 'סעיף 64(א) לחוק החברות קובע כי הדורש רשאי לכנס את האסיפה בעצמו, ובלבד שהיא תתקיים תוך שלושה חודשים מיום הדרישה, וכי הוא מחזיק ביותר ממחצית מזכויות ההצבעה של הדורשים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'מר חרובי רשאי לכנס את האסיפה בעצמו, ובלבד שהיא תתקיים תוך חודש ימים מיום הגשת הדרישה לדירקטוריון.', false, 'המועד הקבוע בחוק לכינוס אסיפה עצמית הוא שלושה חודשים, ולא חודש ימים, כפי שקבוע בסעיף 64(א) לחוק החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'מר חרובי רשאי לכנס את האסיפה בעצמו, ובלבד שיקבל אישור מבית המשפט לכך.', false, 'כינוס אסיפה עצמית לפי סעיף 64 לחוק החברות אינו דורש אישור מוקדם מבית המשפט, אלא הוא סעד עצמי הנתון לבעלי המניות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'מר חרובי אינו רשאי לכנס את האסיפה בעצמו, אלא רק לפנות לבית המשפט.', false, 'סעיף 64 לחוק החברות מעניק לבעלי מניות את הזכות לכנס אסיפה בעצמם, כחלופה לפנייה לבית המשפט לפי סעיף 65.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים לדרישת כינוס אסיפה מיוחדת בחברה ציבורית',
    2, 'מהם התנאים שבעל מניות בחברה ציבורית צריך לעמוד בהם כדי לדרוש מהדירקטוריון לכנס אסיפה מיוחדת?', 'שאלה זו בוחנת את היקף ההחזקות הנדרש מבעל מניות בחברה ציבורית כדי לדרוש מהדירקטוריון לכנס אסיפה מיוחדת, בהתאם להוראות חוק החברות.', 'סעיף 63(ב)(2) לחוק החברות, תשנ"ט-1999, קובע כי דירקטוריון חברה ציבורית יכנס אסיפה מיוחדת לדרישת בעל מניה, אחד או יותר, שלו לפחות חמישה אחוזים מההון המונפק ואחוז אחד לפחות מזכויות ההצבעה בחברה, או בעל מניה, אחד או יותר, שלו לפחות חמישה אחוזים מזכויות ההצבעה בחברה. כלומר, קיימות שתי חלופות לעמידה בתנאי הדרישה, והן מצטברות או חלופיות בהתאם לניסוח הסעיף.',
    'הקושי הוא לזכור את ההבדלים בין חברה ציבורית לפרטית לעניין שיעורי ההחזקה הנדרשים, וכן להבין את משמעות ה''או'' בסעיף 63(ב)(2).', '["חוק החברות", "אסיפה מיוחדת", "חברה ציבורית", "הון מונפק", "זכויות הצבעה", "סעיף 63"]'::jsonb, '**וריאציה 1 — חברה פרטית:** מהם התנאים לדרישת כינוס אסיפה מיוחדת בחברה פרטית? ← לפחות 10% מההון המונפק ו-1% מזכויות ההצבעה, או לפחות 10% מזכויות ההצבעה, לפי סעיף 63(א)(2) לחוק החברות.
**וריאציה 2 — דרישת דירקטורים:** מי מבין הדירקטורים יכול לדרוש כינוס אסיפה מיוחדת בחברה ציבורית? ← שני דירקטורים או רבע מהדירקטורים המכהנים, לפי סעיף 63(ב)(1) לחוק החברות.
**וריאציה 3 — מועד כינוס:** תוך כמה זמן חייב הדירקטוריון לזמן את האסיפה המיוחדת לאחר הדרישה? ← תוך 21 ימים מיום הדרישה, למועד שייקבע בהזמנה, ובלבד שמועד הכינוס לא יאוחר מ-35 ימים ממועד פרסום ההודעה, לפי סעיף 63(ג) לחוק החברות.
**וריאציה 4 — דרישות צורניות:** האם החברה יכולה לדרוש אישורים נוספים מעבר לנדרש בחוק כדי לדחות את כינוס האסיפה? ← לא, דרישות צורניות שאין להן בסיס בדין או בתקנון אינן יכולות לשמש עילה לדחיית כינוס אסיפה, כפי שנקבע בפסיקה (ת"א (מחוזי מרכז) 57198-03-23).', 'דרישת כינוס אסיפה מיוחדת בחברה ציבורית ← 5% הון מונפק + 1% זכויות הצבעה, או 5% זכויות הצבעה (ס'' 63(ב)(2)).',
    '["סעיף 63 לחוק החברות, תשנ\"ט-1999", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | א. תביעה לכינוס אסיפה מיוחדת", "יוסף גרוס חוק החברות (2016) | 5.1 הדירקטוריון", "זוהר גושן אסף אקשטיין דיני חברות (2023) | 3.2 אסיפה מיוחדת"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'בעל מניה, אחד או יותר, שלו לפחות חמישה אחוזים מההון המונפק ואחוז אחד לפחות מזכויות ההצבעה בחברה, או בעל מניה, אחד או יותר, שלו לפחות חמישה אחוזים מזכויות ההצבעה בחברה.', true, 'אלו הם התנאים המדויקים הקבועים בסעיף 63(ב)(2) לחוק החברות לדרישת כינוס אסיפה מיוחדת בחברה ציבורית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'בעל מניה, אחד או יותר, שלו לפחות עשרה אחוזים מההון המונפק ואחוז אחד לפחות מזכויות ההצבעה בחברה.', false, 'תנאים אלו מתייחסים לחברה פרטית, ולא לחברה ציבורית, כפי שקבוע בסעיף 63(א)(2) לחוק החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'בעל מניה, אחד או יותר, שלו לפחות אחוז אחד מזכויות ההצבעה בחברה, ללא קשר להיקף ההון המונפק.', false, 'תנאי זה אינו מספיק לדרישת כינוס אסיפה מיוחדת, שכן נדרש לפחות 5% מזכויות ההצבעה או שילוב של 5% הון מונפק ו-1% זכויות הצבעה, לפי סעיף 63(ב)(2) לחוק החברות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כל בעל מניות רשאי לדרוש כינוס אסיפה מיוחדת, ללא קשר להיקף החזקותיו.', false, 'הזכות לדרוש כינוס אסיפה מיוחדת אינה מוקנית לכל בעל מניות, אלא מותנית בהחזקה בשיעור מסוים מההון או מזכויות ההצבעה, כפי שקבוע בסעיף 63 לחוק החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סמכות בית המשפט לכינוס אסיפה שנתית',
    3, 'חברת "השותלים בע"מ" לא קיימה אסיפה שנתית במשך שנתיים. מר חרובי, בעל מניות, מעוניין לפעול לכינוס האסיפה. מה הדין?', 'שאלה זו בוחנת את הסמכות הייחודית של בית המשפט להורות על כינוס אסיפה שנתית שלא התקיימה, ואת זכותו של בעל מניות לפנות לבית המשפט בבקשה כזו, כפי שקבוע בחוק החברות.', 'על פי סעיף 62(א) לחוק החברות, תשנ"ט-1999, אם לא התקיימה אסיפה שנתית כנדרש, או לאחר שנדרש קיומה, רשאי בית המשפט, לבקשת בעל מניה או דירקטור בחברה, להורות על כינוסה. סעיף 62(ב) מוסיף כי אם הורה בית המשפט כאמור, תישא החברה בהוצאות סבירות שהוציא המבקש בהליך בבית המשפט, והדירקטורים האחראים לאי-כינוסה יהיו חייבים להשיבן לחברה. הוראה זו מבטיחה את קיומה של האסיפה השנתית, שהיא אבן יסוד בממשל התאגידי.',
    'הקושי הוא להבחין בין הסעדים השונים הניתנים לבעלי מניות במקרים של אי-כינוס אסיפות, ובפרט בין אסיפה שנתית לאסיפה מיוחדת.', '["חוק החברות", "אסיפה שנתית", "סמכות בית המשפט", "בעל מניות", "דירקטור", "סעיף 62"]'::jsonb, '**וריאציה 1 — הוצאות משפטיות:** מי יישא בהוצאות המשפטיות אם בית המשפט יורה על כינוס האסיפה השנתית? ← החברה תישא בהוצאות סבירות, והדירקטורים האחראים לאי-כינוס יהיו חייבים להשיבן לחברה, לפי סעיף 62(ב) לחוק החברות.
**וריאציה 2 — אסיפה שנתית מול מיוחדת:** מה ההבדל העיקרי בין אסיפה שנתית לאסיפה מיוחדת? ← אסיפה שנתית מתכנסת פעם בשנה לדון בנושאים קבועים, ואילו אסיפה מיוחדת מתכנסת לפי צורך לדון בנושאים ספציפיים, לפי סעיף 1 לחוק החברות.
**וריאציה 3 — דרישת דירקטור:** האם דירקטור יחיד יכול לפנות לבית המשפט בבקשה לכינוס אסיפה שנתית? ← כן, סעיף 62(א) לחוק החברות מאפשר זאת.
**וריאציה 4 — חברה פרטית:** האם סעיף 62 חל גם על חברה פרטית? ← כן, הסעיף אינו מבחין בין חברה פרטית לציבורית לעניין זה.', 'אי-כינוס אסיפה שנתית ← בעל מניות/דירקטור פונה לביהמ"ש להורות על כינוס (ס'' 62).',
    '["סעיף 62 לחוק החברות, תשנ\"ט-1999", "יוסף גרוס חוק החברות (2016) | 5.3 בית המשפט", "סעיף 1 לחוק החברות, תשנ\"ט-1999"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'מר חרובי רשאי לפנות לבית המשפט בבקשה להורות על כינוס האסיפה השנתית.', true, 'סעיף 62(א) לחוק החברות קובע במפורש כי אם לא התקיימה אסיפה שנתית, רשאי בית המשפט, לבקשת בעל מניה או דירקטור, להורות על כינוסה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'מר חרובי אינו רשאי לפנות לבית המשפט, שכן הזכות לכינוס אסיפה שנתית שמורה לדירקטוריון בלבד.', false, 'אף שהדירקטוריון אחראי לכינוס האסיפה השנתית, סעיף 62(א) לחוק החברות מעניק לבעל מניות את הזכות לפנות לבית המשפט במקרה של אי-כינוס.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'מר חרובי רשאי לכנס את האסיפה השנתית בעצמו, בדומה לכינוס אסיפה מיוחדת.', false, 'הזכות לכינוס עצמי לפי סעיף 64 לחוק החברות מתייחסת לאסיפה מיוחדת בלבד, ולא לאסיפה שנתית. במקרה של אסיפה שנתית, הסעד הוא פנייה לבית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'מר חרובי יכול רק להגיש תביעה להסרת קיפוח, אך לא לדרוש כינוס אסיפה שנתית.', false, 'אף שאי-כינוס אסיפה שנתית יכול להוות עילה לקיפוח, סעיף 62(א) לחוק החברות מעניק סעד ספציפי של פנייה לבית המשפט להורות על כינוסה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעד של הסרת קיפוח',
    4, 'מר חרובי טוען כי אי-כינוס האסיפה המיוחדת על ידי הדירקטוריון מהווה קיפוח של בעלי מניות המיעוט. אילו סעדים רשאי בית המשפט להעניק במקרה של קיפוח?', 'שאלה זו מתמקדת בסעדים הרחבים העומדים לרשות בית המשפט במקרים של קיפוח בעלי מניות, ובפרט קיפוח מיעוט, כפי שקבוע בסעיף 191 לחוק החברות, ומדגישה את גמישותו של בית המשפט בעיצוב הסעד.', 'סעיף 191(א) לחוק החברות, תשנ"ט-1999, קובע כי אם עניין מענייניה של חברה התנהל בדרך שיש בה משום קיפוח של בעלי המניות שלה, כולם או חלקם, או שיש חשש מהותי שיתנהל בדרך זו, רשאי בית המשפט, לפי בקשת בעל מניה, לתת הוראות הנראות לו לשם הסרתו של הקיפוח או מניעתו. הוראות אלו יכולות לכלול, בין היתר, הוראות שלפיהן יתנהלו ענייני החברה בעתיד, או הוראות לבעלי המניות בחברה, לפיהן ירכשו הם או החברה מניות ממניותיה (רכישה כפויה). הפסיקה מדגישה את שיקול הדעת הרחב של בית המשפט בעיצוב סעדים יצירתיים במקרים אלו.',
    'הקושי הוא להבין את מגוון הסעדים הרחב הנתון לבית המשפט במקרה של קיפוח, ולא להגביל את עצמך לסעדים ספציפיים או פחות דרסטיים.', '["חוק החברות", "קיפוח בעלי מניות", "קיפוח המיעוט", "סעיף 191", "סעדים", "רכישה כפויה", "שיקול דעת בית המשפט"]'::jsonb, '**וריאציה 1 — הפרדת כוחות:** האם בית המשפט יכול להורות על הפרדת כוחות בין בעלי המניות? ← כן, זהו סעד אפשרי במקרים של קיפוח, במיוחד בחברות שהן מעין שותפות, כפי שמוזכר בספרות (נבו - המתמחה, דיני תאגידים).
**וריאציה 2 — פירוק חברה:** האם בית המשפט יכול להורות על פירוק החברה כסעד לקיפוח? ← כן, במקרים קיצוניים, כסעד אחרון, כפי שמוזכר בספרות (נבו - המתמחה, דיני תאגידים).
**וריאציה 3 — חובת תום לב:** האם קיפוח קשור לחובת תום הלב של בעלי מניות? ← כן, סעיף 192(ב) לחוק החברות קובע שבעל מניה יימנע מלקפח בעלי מניות אחרים, ועל הפרת הוראה זו יחולו גם הוראות סעיף 191.
**וריאציה 4 — עסקאות בעלי עניין:** האם עסקאות בעלי עניין שלא אושרו כדין יכולות להוות קיפוח? ← כן, עסקאות כאלה, במיוחד אם הן מבוצעות ללא אישור האסיפה הכללית ומוסתרות מבעלי מניות המיעוט, מהוות דוגמה לקיפוח חמור, כפי שנקבע בפסיקה (ת"א (כלכלית) 11439-05-19 לילך טל נ'' אורלי גיא).', 'סעדים לקיפוח (ס'' 191) ← הוראות להסרת קיפוח/מניעתו ← רכישה כפויה ← הפרדת כוחות ← פירוק (במקרים קיצוניים).',
    '["סעיף 191 לחוק החברות, תשנ\"ט-1999", "נבו - המתמחה דיני תאגידים (2026) | קיפוח בעלי מניות (\"קיפוח המיעוט\")", "נבו - המתמחה דיני תאגידים (2026) | (+) הפרדת כוחות", "ת\"א (כלכלית) 11439-05-19 לילך טל נ'' אורלי גיא (21.01.2024)", "סעיף 192 לחוק החברות, תשנ\"ט-1999"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט רשאי לתת הוראות הנראות לו לשם הסרת הקיפוח או מניעתו, לרבות הוראות לרכישה כפויה של מניות המיעוט על ידי בעלי השליטה או החברה.', true, 'סעיף 191 לחוק החברות מעניק לבית המשפט שיקול דעת רחב במתן סעדים להסרת קיפוח, כולל הוראות לניהול ענייני החברה בעתיד ורכישה כפויה של מניות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט רשאי רק להורות על כינוס האסיפה המיוחדת, ואין לו סמכות להתערב בניהול החברה מעבר לכך.', false, 'סעד של הסרת קיפוח לפי סעיף 191 לחוק החברות מעניק לבית המשפט סמכויות רחבות בהרבה, כולל התערבות בניהול החברה ומתן סעדים יצירתיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט רשאי להורות על פירוק החברה בלבד, אם הקיפוח חמור במיוחד.', false, 'פירוק חברה הוא סעד קיצוני הניתן במקרים חמורים ביותר של קיפוח, אך הוא אינו הסעד היחיד או העיקרי, ובית המשפט מעדיף לרוב סעדים פחות דרסטיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט רשאי להטיל קנס כספי על הדירקטוריון, אך לא להתערב בזכויות הקניין של בעלי המניות.', false, 'סעיף 191 לחוק החברות מאפשר לבית המשפט להתערב בזכויות הקניין של בעלי המניות באמצעות סעדים כמו רכישה כפויה, והוא אינו מוגבל לקנסות בלבד.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 24, '2022-W-S-Q24';
END
$$;

-- ============================================================
-- Q25 — 2022-W-S-Q25 — chapter=corporate subtopic=interested_party_transactions
-- classifier_note: Tender offer accepted by 96%, dissatisfied minority shareholder — sec. 338 חוק החברות (full tender offer / squeeze-out)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'd9780413-c81f-4e64-b467-b7990fdc40a4'::uuid;
  v_group_id uuid := '080dd9f9-587d-41fa-8997-109938603e03'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '5e51c116-f528-4c76-ad3f-00617357dc38'::uuid;
  v_ang_1 uuid := '11e1d8e6-9dad-428d-bbfa-6bd6fedb266c'::uuid;
  v_ang_2 uuid := '3cdf9b01-1da0-4d83-8187-8cde87f21396'::uuid;
  v_ang_3 uuid := 'b96d0e89-998e-450c-92cc-3df05e292f4b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q25';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 25, '2022-W-S-Q25';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'interested_party_transactions' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'interested_party_transactions', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q25', v_chapter_id, v_subtopic_id, 'מר עפרוני פרסם הצעת רכש לרכישת מניות החברה הציבורית "המצויינים בע"מ". להצעה נענו 96% מבעלי המניות הניצעים. לא היו בין הניצעים בעלי עניין אישי בהצעה. אחד מבעלי המניות בחברה אינו מרוצה מהמחיר ששולם עבור כל מניה, והוא מעוניין להגיש תביעה ולקבל סעד. באלו תנאים בעל המניות זכאי לסעד?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 25}'::jsonb, 'שאלה זו עוסקת בזכותו של בעל מניות מיעוט בחברה ציבורית לבקש סעד מבית המשפט בגין מחיר מניותיו בהצעת רכש. היא מתמקדת בתנאים המאפשרים הגשת בקשה כזו, ובפרט בסייג הנוגע לויתור על זכות זו בתנאי ההצעה, בהתאם לחוק החברות.', 'סעיף 338(א) לחוק החברות, התשנ"ט-1999, קובע כי בעל מניה שלא נענה להצעת רכש רשאי לבקש מבית המשפט לקבוע את התמורה הראויה למניותיו. עם זאת, הסעיף קובע סייג חשוב: זכות זו אינה עומדת לבעל מניה אם המציע קבע בתנאי הצעת הרכש שמקבלי ההצעה יוותרו על סעד. כלומר, אם בעל המניות קיבל את ההצעה שכללה תנאי ויתור מפורש, הוא מנוע מלבקש סעד. השאלה מתייחסת להצעת רכש רגילה (ולא מיוחדת), ולכן הסייג בדבר ויתור תקף.', 'הטעות הנפוצה היא להתעלם מהסייג הקבוע בסעיף 338(א) לחוק החברות, המאפשר למציע לקבוע תנאי ויתור על סעד בהצעת הרכש, ובכך למנוע תביעות עתידיות ממקבלי ההצעה.',
    '["הצעת רכש", "זכות לסעד", "ויתור על זכות", "חוק החברות", "הגנת המיעוט"]'::jsonb, '**וריאציה 1 — מי זכאי לסעד?** מי זכאי לבקש סעד לפי סעיף 338(א)? ← בעל מניה שלא נענה להצעת רכש.
**וריאציה 2 — סייג לזכות:** מהו הסייג לזכות לסעד? ← אם המציע קבע בתנאי ההצעה שמקבלי ההצעה יוותרו על סעד.
**וריאציה 3 — התנגדות אקטיבית:** האם נדרשת התנגדות אקטיבית להצעה? ← לא, מספיק שלא נענה להצעה.
**וריאציה 4 — הצעת רכש מיוחדת:** האם הסייג בדבר ויתור חל גם על הצעת רכש מיוחדת? ← לא, בהצעת רכש מיוחדת זכות הסעד אינה ניתנת לויתור (סעיף 338(ב) לחוק החברות).', 'זכות לסעד בהצעת רכש רגילה ← למי שלא נענה ← אלא אם כן ויתר מפורשות (סעיף 338(א) לחוק החברות).', '["חוק החברות, התשנ\"ט-1999, סעיף 338"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''תובענות ייצוגיות'' → mapped chapter=''corporate'' subtopic=''interested_party_transactions'' | classifier_note: Tender offer accepted by 96%, dissatisfied minority shareholder — sec. 338 חוק החברות (full tender offer / squeeze-out) | source_review_note: השאלה עוסקת בדיני חברות (דין מהותי) ואינה מתאימה לאף אחד מהפרקים המוגדרים כ''דין דיוני''. סווגה תחת ''תובענות ייצוגיות'' כקירוב רחוק ביותר לנושא זכויות בעלי מניות, אך יש לשקול פרק מתאים יותר לדיני חברות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'רק אם התנגד להצעת הרכש.', false, 'תשובה זו אינה מדויקת. סעיף 338(א) לחוק החברות קובע כי הזכות לסעד ניתנת לבעל מניה "שלא נענה להצעת רכש", ואינו דורש התנגדות אקטיבית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בין שהתנגד להצעת הרכש ובין שלא, אלא אם כן קבע המציע בתנאי הצעת הרכש שמקבלי ההצעה יוותרו על סעד.', true, 'זוהי התשובה הנכונה. סעיף 338(א) לחוק החברות קובע כי בעל מניה שלא נענה להצעת רכש רשאי לבקש סעד, אלא אם כן נקבע בהצעה כי קבלתה מהווה ויתור על זכות זו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בין שהתנגד להצעת הרכש ובין שלא.', false, 'תשובה זו חלקית ואינה שלמה. היא מתעלמת מהסייג החשוב הקבוע בסעיף 338(א) לחוק החברות, לפיו ניתן לוותר על הזכות לסעד אם הדבר נקבע מפורשות בתנאי הצעת הרכש.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא ניתן לבקש סעד כאמור כאשר שיעור המתנגדים להצעת הרכש קטן מ-5%.', false, 'תשובה זו מתייחסת לתנאים להשלמת הצעת רכש מיוחדת לפי סעיף 337 לחוק החברות, ולא לתנאים לזכותו של בעל מניה לבקש סעד לפי סעיף 338 לחוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'זכות לסעד בהצעת רכש מיוחדת',
    1, 'חברת "השקעות עתיד" מחזיקה ב-92% ממניות חברת "הצלחה בע"מ" ופרסמה הצעת רכש מיוחדת לרכישת יתרת המניות. 98% מבעלי המניות הניצעים נענו להצעה, וכעת "השקעות עתיד" מחזיקה ב-99.8% מהמניות. בעל מניות מיעוט שלא נענה להצעה, ועתה מניותיו נרכשות בכפייה, מעוניין לבקש סעד בגין מחיר המניה. מה הדין?', 'שאלה זו עוסקת בזכותו של בעל מניות מיעוט לבקש סעד במקרה של הצעת רכש מיוחדת שהובילה לרכישה כפויה של מניותיו. היא בוחנת את ההבדלים בין הצעת רכש רגילה להצעת רכש מיוחדת בהקשר לזכויות בעלי המניות.', 'סעיף 338(ב) לחוק החברות קובע כי במקרה של הצעת רכש מיוחדת שהושלמה, ובעקבותיה נרכשו מניותיו של בעל מניה בכפייה (כאשר המציע הגיע ל-95% ומעלה מהמניות), רשאי בעל המניה לבקש מבית המשפט לקבוע את התמורה הראויה למניותיו. זכות זו אינה תלויה בכך שבעל המניה לא נענה להצעה, ואינה ניתנת לויתור. מטרת הסעיף היא להגן על בעלי מניות מיעוט מפני קיפוח במצבים של רכישה כפויה.',
    'הטעות הנפוצה היא לבלבל בין התנאים לזכות לסעד בהצעת רכש רגילה (סעיף 338(א)) לבין התנאים בהצעת רכש מיוחדת (סעיף 338(ב)), שם ההגנה על בעל המניות חזקה יותר.', '["הצעת רכש מיוחדת", "רכישה כפויה", "זכות לסעד", "הגנת המיעוט", "חוק החברות"]'::jsonb, '**וריאציה 1 — הצעת רכש רגילה:** האם בעל מניות שנענה להצעת רכש רגילה יכול לבקש סעד? ← כן, אלא אם כן ויתר על זכותו בהצעה (סעיף 338(א) לחוק החברות).
**וריאציה 2 — הצעת רכש מיוחדת:** האם בעל מניות שנענה להצעת רכש מיוחדת יכול לבקש סעד? ← כן, גם אם נענה, וזכותו אינה ניתנת לויתור (סעיף 338(ב) לחוק החברות).
**וריאציה 3 — סף 95%:** מה קורה אם המציע הגיע ל-95% מהמניות בהצעת רכש מיוחדת? ← הוא רשאי לרכוש את יתרת המניות בכפייה, אך בעלי המניות שנותרו זכאים לסעד (סעיפים 337 ו-338(ב) לחוק החברות).
**וריאציה 4 — התנגדות אקטיבית:** האם נדרשת התנגדות אקטיבית להצעה כדי לבקש סעד? ← לא, מספיק שלא נענה להצעה (סעיף 338(א) לחוק החברות) או שמניותיו נרכשו בכפייה (סעיף 338(ב) לחוק החברות).', 'הצעת רכש מיוחדת ← רכישה כפויה ← זכות לסעד מהותי למחיר הוגן ← זכות זו אינה ניתנת לויתור (סעיף 338(ב) לחוק החברות).',
    '["חוק החברות, התשנ\"ט-1999, סעיפים 337, 338(ב)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בעל המניות אינו זכאי לסעד, שכן מניותיו נרכשו בכפייה לאחר שהצעת הרכש המיוחדת הושלמה בהצלחה.', false, 'תשובה זו שגויה. גם במקרה של רכישה כפויה לאחר הצעת רכש מיוחדת, בעל המניות שנותר זכאי לבקש סעד מהותי לגבי מחיר המניה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בעל המניות זכאי לבקש סעד מהותי מבית המשפט לעניין מחיר המניה, ללא קשר לשאלה אם נענה להצעה או לא, וללא אפשרות ויתור על זכות זו.', true, 'זוהי התשובה הנכונה. סעיף 338(ב) לחוק החברות קובע כי במקרה של רכישה כפויה לאחר הצעת רכש מיוחדת, בעל מניה זכאי לבקש מבית המשפט לקבוע את התמורה הראויה למניותיו, וזכות זו אינה ניתנת לויתור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בעל המניות זכאי לסעד רק אם התנגד במפורש להצעת הרכש המיוחדת.', false, 'תשובה זו אינה נכונה. סעיף 338(ב) לחוק החברות אינו דורש התנגדות אקטיבית כתנאי לזכות לבקש סעד במקרה של רכישה כפויה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בעל המניות זכאי לסעד רק אם יוכיח שהמחיר שהוצע היה נמוך ב-20% לפחות מהמחיר הראוי.', false, 'תשובה זו אינה נכונה. חוק החברות אינו קובע סף כמותי ספציפי להפרש בין המחיר המוצע למחיר הראוי כתנאי לזכות לבקש סעד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'קביעת מחיר הוגן למניות',
    2, 'בית המשפט נדרש לקבוע את התמורה הראויה למניותיו של בעל מניות מיעוט שהגיש בקשה לסעד לפי סעיף 338 לחוק החברות. אילו עקרונות או שיקולים ינחו את בית המשפט בקביעת המחיר הראוי?', 'שאלה זו בוחנת את אמות המידה והשיקולים המנחים את בית המשפט בקביעת ''תמורה ראויה'' למניות, בהקשר של בקשת סעד לפי חוק החברות. היא נוגעת לעקרונות הערכת שווי חברות ודיני הגנת המיעוט.', 'הפסיקה בישראל, ובפרט ע"א 2128/09 הפניקס חברה לביטוח בע"מ נ'' אפריקה ישראל להשקעות בע"מ, קבעה כי בקביעת ''תמורה ראויה'' למניות, בית המשפט אינו כבול לשיטת הערכה אחת. עליו לבחון מגוון שיטות הערכה מקובלות, כגון שווי נכסי, תזרים מזומנים מהוון (DCF), מכפיל רווח, ומחיר השוק, תוך התחשבות בנסיבות הספציפיות של העסקה, מטרותיה והשפעתה על בעלי מניות המיעוט. המטרה היא להגיע למחיר המשקף את שווי החברה באופן הוגן לכלל בעלי המניות.',
    'הטעות הנפוצה היא לחשוב שיש שיטת הערכה אחת בלעדית או קריטריון יחיד לקביעת מחיר הוגן, במקום להבין שמדובר בבחינה רחבה ומורכבת של מכלול גורמים.', '["תמורה ראויה", "הערכת שווי חברות", "שיטות הערכה", "הגנת המיעוט", "פסיקת בתי המשפט"]'::jsonb, '**וריאציה 1 — שיטות הערכה:** אילו שיטות הערכה נבחנות? ← שווי נכסי, תזרים מזומנים מהוון, מכפיל רווח, מחיר שוק (ע"א 2128/09).
**וריאציה 2 — שיקולים נוספים:** אילו שיקולים נוספים נלקחים בחשבון? ← נסיבות העסקה הספציפית, מטרותיה, והשפעתה על בעלי מניות המיעוט (ע"א 2128/09).
**וריאציה 3 — בלעדיות מחיר שוק:** האם מחיר השוק הוא הקובע הבלעדי? ← לא, הוא שיקול חשוב אך לא בלעדי, במיוחד כשיש חשש לקיפוח (ע"א 2128/09).
**וריאציה 4 — מטרת בית המשפט:** מהי מטרת בית המשפט בקביעת המחיר? ← להגיע למחיר המשקף את שווי החברה באופן הוגן לכלל בעלי המניות, תוך הגנה על המיעוט.', 'קביעת מחיר הוגן ← מגוון שיטות הערכה + נסיבות העסקה ← הגנה על המיעוט (ע"א 2128/09).',
    '["ע\"א 2128/09 הפניקס חברה לביטוח בע\"מ נ'' אפריקה ישראל להשקעות בע\"מ, פ\"ד סה(1) 149 (2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'בית המשפט יתבסס אך ורק על מחיר השוק של המניה ביום פרסום הצעת הרכש.', false, 'תשובה זו שגויה. מחיר השוק הוא שיקול חשוב, אך אינו השיקול הבלעדי, ובית המשפט בוחן מגוון רחב של שיטות הערכה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'בית המשפט יתחשב במגוון שיטות הערכה מקובלות, לרבות שווי נכסי, תזרים מזומנים מהוון ומחיר השוק, וכן בנסיבות הספציפיות של העסקה.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי בית המשפט יבחן את המחיר הראוי תוך התחשבות במכלול שיטות הערכה ובנסיבות העסקה, במטרה להגן על בעל מניות המיעוט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'בית המשפט יקבע את המחיר הראוי על בסיס הערכת שווי שתוגש על ידי המציע בלבד.', false, 'תשובה זו שגויה. בית המשפט אינו כבול להערכת שווי של צד אחד בלבד, אלא יבחן את כל הראיות וההערכות שיוגשו לו, ואף רשאי למנות מומחה מטעמו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'בית המשפט יקבע את המחיר הראוי כ-10% מעל למחיר שהוצע בהצעת הרכש, כפיצוי לבעל המניות.', false, 'תשובה זו אינה נכונה. אין בחוק או בפסיקה קביעה אחוזית קבועה לפיצוי או להעלאת המחיר מעבר למחיר שהוצע.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תוקף ויתור על זכות לסעד',
    3, 'חברת "אלפא" פרסמה הצעת רכש למניות חברת "בטא". בתנאי הצעת הרכש נקבע מפורשות כי קבלת ההצעה מהווה ויתור מלא וסופי על כל טענה או דרישה עתידית לעניין מחיר המניה. מר כהן, בעל מניות ב"בטא", קיבל את ההצעה ומכר את מניותיו. כעת הוא מתחרט ומעוניין להגיש תביעה לקבלת סעד בטענה שהמחיר היה נמוך מדי. האם מר כהן יוכל לזכות בסעד?', 'שאלה זו מתמקדת בסייג לזכות לבקש סעד לפי סעיף 338(א) לחוק החברות, הנוגע לתוקפו של ויתור מפורש על זכות זו בתנאי הצעת הרכש. היא בוחנת את גבולות ההגנה על בעלי מניות מיעוט.', 'סעיף 338(א) לחוק החברות קובע כי בעל מניה שלא נענה להצעת רכש רשאי לבקש מבית המשפט לקבוע את התמורה הראויה למניותיו, ''אלא אם כן קבע המציע בתנאי הצעת הרכש שמקבלי ההצעה יוותרו על סעד''. במקרה זה, מר כהן קיבל את ההצעה שכללה תנאי ויתור מפורש, ולכן הוא מנוע מלבקש סעד. הוויתור תקף, אלא אם כן יוכח פגם מהותי בכריתת ההסכם (כגון הטעיה או עושק), אך זהו נטל הוכחה כבד שאינו ברירת המחדל.',
    'הטעות הנפוצה היא להניח שזכות לסעד היא תמיד קוגנטית ואינה ניתנת לויתור, מבלי לשים לב לסייג המפורש בסעיף 338(א) לחוק החברות.', '["ויתור על זכות", "הצעת רכש", "סעיף 338 לחוק החברות", "קוגנטיות מול דיספוזיטיביות", "תוקף הסכם"]'::jsonb, '**וריאציה 1 — ויתור מפורש:** האם ויתור מפורש על סעד בהצעת רכש תקף? ← כן, אם נקבע בתנאי ההצעה (סעיף 338(א) לחוק החברות).
**וריאציה 2 — ויתור בהצעת רכש מיוחדת:** האם ויתור על סעד תקף בהצעת רכש מיוחדת? ← לא, זכות זו אינה ניתנת לויתור בהצעת רכש מיוחדת (סעיף 338(ב) לחוק החברות).
**וריאציה 3 — נטל ההוכחה לביטול ויתור:** מי צריך להוכיח פגם בוויתור? ← בעל המניות הטוען לפגם (כגון עושק או הטעיה).
**וריאציה 4 — חשיבות ניסוח ההצעה:** מדוע חשוב ניסוח תנאי הצעת הרכש? ← ניסוח מפורש של ויתור יכול למנוע תביעות עתידיות לסעד.', 'ויתור על סעד בהצעת רכש רגילה ← תקף אם נקבע מפורשות בהצעה (סעיף 338(א) לחוק החברות).',
    '["חוק החברות, התשנ\"ט-1999, סעיף 338(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, זכותו של בעל מניות לבקש סעד לפי סעיף 338 לחוק החברות היא קוגנטית ואינה ניתנת לויתור.', false, 'תשובה זו שגויה. סעיף 338(א) לחוק החברות קובע במפורש כי ניתן לוותר על הזכות לסעד אם הדבר נקבע בתנאי הצעת הרכש.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מר כהן ויתר על זכותו לסעד בקבלת הצעת הרכש, שכן תנאי הויתור נקבעו מפורשות בהצעה.', true, 'זוהי התשובה הנכונה. סעיף 338(א) לחוק החברות קובע חריג לזכות לסעד, לפיו אם המציע קבע בתנאי הצעת הרכש שמקבלי ההצעה יוותרו על סעד, הוויתור תקף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן יוכיח המציע שמר כהן קיבל ייעוץ משפטי עצמאי לפני קבלת ההצעה.', false, 'תשובה זו אינה נכונה. חוק החברות אינו דורש קבלת ייעוץ משפטי עצמאי כתנאי לתוקף ויתור על זכות לסעד בהצעת רכש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן יוכיח מר כהן כי הוויתור נכפה עליו בנסיבות של עושק או הטעיה.', false, 'תשובה זו אינה נכונה באופן מוחלט. בעוד שטענות לעושק או הטעיה יכולות לבטל ויתור, ברירת המחדל היא שהוויתור תקף אם נקבע מפורשות, ונטל ההוכחה לביטולו מוטל על הטוען לכך.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים חלופיים לבעל מניות מיעוט',
    4, 'בעל מניות מיעוט בחברה ציבורית סבור כי הצעת רכש שפורסמה למניות החברה קיפחה אותו ואת יתר בעלי מניות המיעוט, אך הוא אינו מעוניין או אינו יכול להגיש בקשה לסעד לפי סעיף 338 לחוק החברות. אילו סעדים חלופיים עשויים לעמוד לרשותו של בעל מניות המיעוט במקרה זה?', 'שאלה זו בוחנת את מגוון הסעדים העומדים לרשות בעל מניות מיעוט בחברה ציבורית, מעבר לסעד הספציפי של סעיף 338 לחוק החברות, במקרים של קיפוח או נזק שנגרם לחברה כתוצאה מפעולות הרוב או הדירקטוריון.', 'חוק החברות מספק מספר מנגנוני הגנה לבעלי מניות מיעוט. סעיף 191 לחוק מאפשר לבית המשפט לתת סעדים שונים במקרה של קיפוח המיעוט על ידי החברה או בעלי השליטה בה. סעיף 198 לחוק מאפשר לבעל מניות להגיש תביעה נגזרת בשם החברה, כאשר נגרם לה נזק והיא אינה פועלת לתבוע את הנזק בעצמה. סעדים אלו יכולים להיות רלוונטיים גם בהקשר של הצעת רכש שבה נגרם נזק לחברה או קיפוח למיעוט.',
    'הטעות הנפוצה היא להתמקד רק בסעד הספציפי של סעיף 338 לחוק החברות, מבלי להכיר את מכלול הכלים המשפטיים העומדים לרשות בעלי מניות מיעוט להגנה על זכויותיהם.', '["קיפוח המיעוט", "תביעה נגזרת", "הגנת המיעוט", "חוק החברות", "סעדים משפטיים"]'::jsonb, '**וריאציה 1 — קיפוח מיעוט:** מהו הסעד העיקרי לקיפוח מיעוט? ← תביעה לפי סעיף 191 לחוק החברות, המאפשרת לבית המשפט לתת סעדים שונים.
**וריאציה 2 — נזק לחברה:** מהו הסעד כאשר נגרם נזק לחברה עצמה? ← תביעה נגזרת לפי סעיף 198 לחוק החברות, המוגשת על ידי בעל מניות בשם החברה.
**וריאציה 3 — תביעה אישית:** מתי ניתן להגיש תביעה אישית נגד דירקטורים? ← כאשר נגרם נזק אישי ישיר לבעל המניות עקב הפרת חובת אמונים או רשלנות של הדירקטורים.
**וריאציה 4 — תביעה ייצוגית:** מתי תביעה ייצוגית רלוונטית? ← כאשר קיימת קבוצה גדולה של נפגעים בעלי עילה דומה, אך היא אינה הסעד הספציפי ביותר לקיפוח מיעוט בחברה.', 'סעדים חלופיים למיעוט ← קיפוח (ס'' 191) או תביעה נגזרת (ס'' 198) ← הגנה רחבה יותר מזכות לסעד מחיר בלבד.',
    '["חוק החברות, התשנ\"ט-1999, סעיפים 191, 198"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הגשת תביעה ייצוגית נגד החברה בגין הפרת חובת תום הלב.', false, 'תביעה ייצוגית אפשרית במקרים מסוימים, אך לא כל הפרת חובת תום לב מצד החברה תצדיק תביעה ייצוגית בהקשר זה, וקיימים סעדים ספציפיים יותר לקיפוח מיעוט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הגשת תביעה בגין קיפוח המיעוט לפי סעיף 191 לחוק החברות, או תביעה נגזרת לפי סעיף 198 לחוק החברות.', true, 'זוהי התשובה הנכונה. סעיפים 191 ו-198 לחוק החברות מספקים כלים מרכזיים להגנה על בעלי מניות מיעוט מפני קיפוח או נזק שנגרם לחברה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'פנייה לרשות ניירות ערך בבקשה לבטל את הצעת הרכש.', false, 'תשובה זו אינה נכונה. רשות ניירות ערך אמונה על אכיפת דיני ניירות ערך וכללי הצעות רכש, אך אין בסמכותה לבטל הצעת רכש שהושלמה בגין טענות קיפוח של בעל מניות בודד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הגשת תביעה נזיקית אישית נגד הדירקטורים בחברה בגין רשלנות.', false, 'תביעה נזיקית אישית נגד דירקטורים אפשרית במקרים של רשלנות או הפרת חובת אמונים, אך היא דורשת הוכחת נזק אישי ישיר לבעל המניות, ואינה הסעד העיקרי לקיפוח מיעוט בהקשר של הצעת רכש.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 25, '2022-W-S-Q25';
END
$$;

-- ============================================================
-- Q26 — 2022-W-S-Q26 — chapter=property subtopic=real_estate
-- classifier_note: Municipal land, 40 years' passage by Shlomo — easement by prescription (זיקת הנאה)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b3af3a4f-4190-4e97-9bc5-98c6038d08f8'::uuid;
  v_group_id uuid := '3937633b-b120-474d-a7e0-c4372d9ddbb8'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '2e9a050d-736b-4934-a676-9494d967fe14'::uuid;
  v_ang_1 uuid := '46101731-80bc-49b2-bb68-7eefcb84d257'::uuid;
  v_ang_2 uuid := 'b2ae8fa6-5fbf-48c8-9932-4a98b15db41f'::uuid;
  v_ang_3 uuid := '57a6c112-8fa3-416c-834b-9e5ed83d2991'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 26, '2022-W-S-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'real_estate' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'real_estate', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q26', v_chapter_id, v_subtopic_id, 'בבעלות עיריית הוד השרון ישנה קרקע בקצה העיר. כבר למעלה מ-40 שנים ששלמה עובר בקרקע הזו בדרך לביתו. כעת הודיעה העירייה כי אינה מסכימה שיעברו דרך הקרקע וכי הכניסה לקרקע אסורה. שלמה מתנגד להודעת העירייה. מהו המשפט הנכון ביותר?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 26}'::jsonb, 'השאלה עוסקת בזיקת הנאה מכוח שנים, ובפרט בשאלת תחולתה על מקרקעי ציבור. סעיף 94 לחוק המקרקעין מאפשר רכישת זיקת הנאה מכוח שימוש רצוף של שלושים שנה, אך סעיף 113(ג) לחוק המקרקעין קובע חריג מפורש למקרקעי ציבור.', 'סעיף 113(ג) לחוק המקרקעין קובע מפורשות כי "במקרקעי ציבור לא יחול סעיף 94". סעיף 107 לחוק המקרקעין מגדיר "מקרקעי ציבור" כ"מקרקעי ישראל כמשמעותם בחוק-יסוד: מקרקעי ישראל, ומקרקעין של רשות מקומית או של תאגיד שהוקם על ידי חיקוק". מאחר שהקרקע בבעלות עיריית הוד השרון, היא נחשבת למקרקעי ציבור, ולכן לא יכולה להיווצר בה זיקת הנאה מכוח שנים. תכלית החריג היא להגן על מקרקעי ציבור מפני כרסום זכויות על ידי שימוש לא מורשה, בשל הקושי של הרשויות לפקח על שטחים נרחבים אלה.', 'הטעות הנפוצה היא להניח שכל שימוש ממושך של 30 שנה מקנה זיקת הנאה, מבלי להתייחס לסוג המקרקעין (פרטיים מול ציבוריים).',
    '["זיקת הנאה מכוח שנים", "מקרקעי ציבור", "חוק המקרקעין", "סעיף 94", "סעיף 107", "סעיף 113(ג)", "רשות מקומית"]'::jsonb, '**מקרקעין פרטיים:** שימוש של 30 שנה בקרקע פרטית ללא התנגדות ← זיקת הנאה מכוח שנים.
**מקרקעי ציבור:** שימוש של 30 שנה בקרקע ציבורית ← לא תקום זיקת הנאה מכוח שנים (סעיף 113(ג) לחוק המקרקעין).
**הודעת התנגדות:** הודעה בכתב של בעל המקרקעין מפסיקה את מרוץ 30 השנים (סעיף 94(ב) לחוק המקרקעין).
**הגדרת מקרקעי ציבור:** מקרקעי ישראל, מקרקעין של רשות מקומית או תאגיד שהוקם בחיקוק (סעיף 107 לחוק המקרקעין).', 'מקרקעי ציבור ← אין זיקת הנאה מכוח שנים (סעיף 113(ג) לחוק המקרקעין) ← גם אם השימוש נמשך מעל 30 שנה.', '["חוק המקרקעין, תשכ\"ט-1969, סעיפים 94, 107, 113(ג)", "ע\"א (מחוזי ת\"א) 38409-10-11 עזבון המנוחים יחזקאל ואלישבע הסה ז\"ל נ'' דניאל שאול (13.11.2013)", "ת\"א (מחוזי חי'') 18818-11-14 יהודה פרנקו נ'' אילן נצר (07.05.2015)", "ת\"א (מחוזי מרכז) 5613-09-20 אלי בן -מרגי נ'' עיריית נס ציונה (19.03.2021)", "ת\"א (שלום נצרת) 28378-06-19 רשות הפיתוח נ'' מוחמד מופלח אבו ראס (04.03.2024)", "ת\"א (מחוזי ת\"א) 34110-11-21 רוני כליפה נ'' מיכאל סנבטה (21.01.2024)", "ת\"א (שלום י-ם) 12943-12-10 נפתלי מרמלשטיין נ'' אלחנן ליכט (13.07.2017)", "ת\"א (שלום ראשל\"צ) 29400-06-11 בית יצחק-שער חפר, אגודה להתיישבות חקלאית בע\"מ נ'' אורי דים (27.07.2014)", "תא\"ק (שלום ת\"א) 6844-09-11 עיריית ת\"א נ'' אשר בן שמואל (11.09.2013)", "עת\"מ (מינהליים מרכז) 12635-08-23 איתן כהן נ'' עיריית גני תקווה (26.08.2024)", "ע\"א 1904/19 פיליפ בלאיש נ'' פרח דיב (22.03.2022)", "רע\"א 8910/13 שאול דניאל נ'' עזבון המנוחים יחזקאל ואלישבע הסה ז\"ל (16.11.2014)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הסדר מקרקעין'' → mapped chapter=''property'' subtopic=''real_estate'' | classifier_note: Municipal land, 40 years'' passage by Shlomo — easement by prescription (זיקת הנאה) | source_review_note: השאלה עוסקת בדיני קניין (זיקת הנאה), תחום שאינו נכלל במפורש ברשימת הפרקים של דין דיוני. מופתה ל''סדר דין אזרחי'' ו''הסדר מקרקעין'' כקירוב הטוב ביותר מתוך הרשימה הסגורה, אך יש לשקול הוספת פרק ''דיני קניין'' או סיווג מתאים יותר.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לשלמה יש זיקת הנאה מכוח שנים, ולכן העירייה אינה רשאית למנוע ממנו את המעבר בקרקע.', false, 'טענה זו שגויה, שכן סעיף 113(ג) לחוק המקרקעין שולל במפורש היווצרות זיקת הנאה מכוח שנים במקרקעי ציבור, גם אם השימוש נמשך מעל 30 שנה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לשלמה יש זיקת הנאה מכוח שנים רק אם רשם את הזיקה במרשם המקרקעין. בהיעדר רישום תוכל העירייה למנוע ממנו את המעבר.', false, 'טענה זו שגויה כפולה: ראשית, זיקת הנאה מכוח שנים אינה טעונה רישום לצורך קיומה (אלא רק לצורך דרישת הרישום). שנית, ובאופן מהותי יותר, במקרקעי ציבור לא יכולה להיווצר זיקת הנאה מכוח שנים כלל, ללא קשר לרישום.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'שלמה רשאי לדרוש את רישום הזיקה, ולאחר מכן יוכל להמשיך ולעשות שימוש בקרקע.', false, 'טענה זו שגויה, שכן שלמה אינו יכול לדרוש רישום זיקת הנאה במקרקעי ציבור, מאחר שזיקה כזו אינה יכולה להיווצר בהם מלכתחילה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לשלמה אין זיקת הנאה בקרקע.', true, 'תשובה זו נכונה. סעיף 113(ג) לחוק המקרקעין קובע כי סעיף 94 (העוסק בזיקת הנאה מכוח שנים) לא יחול במקרקעי ציבור. מקרקעין שבבעלות רשות מקומית נחשבים למקרקעי ציבור לפי סעיף 107 לחוק המקרקעין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'זיקת הנאה במקרקעין פרטיים',
    1, 'ראובן הוא בעל מקרקעין פרטיים. במשך 40 שנים, שמעון עובר דרך חלקת הקרקע של ראובן בדרכו לביתו, ללא הסכמתו המפורשת של ראובן וללא כל התנגדות מצדו. כעת, ראובן מבקש למנוע משמעון את המעבר. מה הדין?', 'זכות מעבר היא זכות הראויה להוות זיקת הנאה. במקרקעין פרטיים, שימוש רצוף של 30 שנה ללא התנגדות בעל המקרקעין מקנה זיקת הנאה מכוח שנים, המאפשרת למשתמש להמשיך בשימוש זה.', 'סעיף 94(א) לחוק המקרקעין קובע כי מי שהשתמש בזכות הראויה להוות זיקת הנאה במשך תקופה של שלושים שנים רצופות רכש את הזיקה והוא זכאי לדרוש רישומה. זכות מעבר היא דוגמה קלאסית לזכות הראויה להוות זיקת הנאה. במקרה זה, שמעון השתמש בדרך במשך 40 שנה, תקופה העולה על הנדרש, וללא התנגדות מצד ראובן. לכן, שמעון רכש זיקת הנאה מכוח שנים, וראובן אינו רשאי למנוע ממנו את המעבר. זיקת הנאה מכוח שנים אינה טעונה רישום לצורך קיומה, אלא רק לצורך דרישת הרישום.',
    'הבלבול בין זיקת הנאה מכוח שנים לבין רשות שימוש הניתנת לביטול. זיקת הנאה מכוח שנים היא זכות קניינית שאינה ניתנת לביטול חד-צדדי.', '["זיקת הנאה מכוח שנים", "מקרקעין פרטיים", "זכות מעבר", "שימוש רצוף", "סעיף 94 לחוק המקרקעין"]'::jsonb, '**שימוש בקרקע פרטית מעל 30 שנה ללא התנגדות:** האם נוצרת זיקת הנאה? ← כן, לפי סעיף 94(א) לחוק המקרקעין.
**האם זיקת הנאה מכוח שנים טעונה רישום לצורך קיומה?** ← לא, הרישום הוא לצורך דרישת הרישום, לא לצורך היווצרות הזכות.
**מהו ''שימוש נוגד'' לצורך זיקת הנאה?** ← שימוש שאינו בהסכמת הבעלים, אך הבעלים לא התנגד לו בכתב במשך 30 שנה.
**האם בעל המקרקעין יכול למנוע היווצרות זיקת הנאה?** ← כן, על ידי הודעה בכתב למשתמש שהוא מתנגד לשימוש, לפי סעיף 94(ב) לחוק המקרקעין.', 'מקרקעין פרטיים + שימוש נוגד וגלוי + 30 שנה רצופות ← זיקת הנאה מכוח שנים (סעיף 94 לחוק המקרקעין).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 94", "ע\"א 1904/19 פיליפ בלאיש נ'' פרח דיב (22.3.2022)", "ע\"א 9308/06 עיריית רמת גן נ'' עזבון המנוחה הגב'' ורדה בורשטיין ז\"ל (22.9.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לשמעון יש זיקת הנאה מכוח שנים, וראובן אינו רשאי למנוע ממנו את המעבר בקרקע.', true, 'תשובה זו נכונה. במקרקעין פרטיים, שימוש בזכות הראויה להוות זיקת הנאה במשך 30 שנים רצופות, ללא התנגדות בעל המקרקעין, מקנה זיקת הנאה מכוח שנים לפי סעיף 94(א) לחוק המקרקעין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לשמעון אין זיקת הנאה, שכן שימוש בקרקע פרטית דורש הסכמה מפורשת של הבעלים.', false, 'טענה זו שגויה. זיקת הנאה מכוח שנים נוצרת דווקא משימוש שאינו בהסכמה מפורשת (שימוש נוגד), אך ללא התנגדות בעל המקרקעין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לשמעון יש זיקת הנאה, אך ראובן רשאי לבטלה בכל עת בהודעה בכתב.', false, 'טענה זו שגויה. הודעה בכתב מפסיקה את מרוץ 30 השנים, אך אינה מבטלת זיקת הנאה שכבר נוצרה. ביטול זיקה קיימת דורש פנייה לבית המשפט לפי סעיף 96 לחוק המקרקעין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לשמעון יש זיקת הנאה רק אם רשם אותה במרשם המקרקעין.', false, 'טענה זו שגויה. זיקת הנאה מכוח שנים נוצרת עם השלמת תקופת השימוש, ואינה טעונה רישום לצורך קיומה, אלא רק לצורך דרישת הרישום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים מצטברים לזיקת הנאה מכוח שנים',
    2, 'מהם התנאים המצטברים הנדרשים להיווצרות זיקת הנאה מכוח שנים, כפי שנקבעו בחוק ובפסיקה?', 'היווצרות זיקת הנאה מכוח שנים מותנית בקיומם של שלושה תנאים מצטברים: טיב הזכות, אופי השימוש (נוגד וגלוי), ומשך השימוש (30 שנים רצופות).', 'סעיף 94 לחוק המקרקעין קובע שלושה תנאים מצטברים להשתכללות זיקת הנאה מכוח שנים: (1) הזכות נשוא השימוש היא ''זכות הראויה להוות זיקת הנאה'' (כגון זכות מעבר); (2) אופיו ותכונותיו של השימוש הם כאלה שמאפשרים לו להיכנס לגדר הוראות סעיף 94, כלומר שימוש נוגד לזכות הבעלים, גלוי וחשוף לעין כל, ושמקורו אינו בזכות חוזית או רשות; (3) תקופת השימוש היא בת שלושים שנים רצופות. תנאים אלו נדונו בהרחבה בפסיקה, למשל בעניין אסטרחאן ובעניין בלאיש.',
    'התעלמות מאחד התנאים המצטברים, במיוחד דרישת ה''שימוש הנוגד'' וה''גלוי'', או בלבול בין תקופת השימוש לבין הצורך ברישום.', '["זיקת הנאה", "סעיף 94 לחוק המקרקעין", "זכות הראויה לזיקת הנאה", "שימוש נוגד", "שימוש גלוי", "30 שנים רצופות"]'::jsonb, '**תנאי 1: זכות הראויה לזיקת הנאה:** מהי? ← שעבוד מקרקעין להנאה שאין עמו זכות להחזיק בהם (סעיף 5 לחוק המקרקעין).
**תנאי 2: אופי השימוש:** מהם מאפייניו? ← שימוש נוגד, גלוי, בידיעה קונסטרוקטיבית של הבעלים, ולא מכוח הסכם או רשות.
**תנאי 3: תקופת השימוש:** כמה זמן? ← 30 שנים רצופות (סעיף 94(א) לחוק המקרקעין).
**הפסקת מרוץ השנים:** כיצד? ← הודעה בכתב של בעל המקרקעין למשתמש שהוא מתנגד לשימוש (סעיף 94(ב) לחוק המקרקעין).', 'זיקת הנאה מכוח שנים ← 3 תנאים מצטברים: זכות ראויה + שימוש נוגד וגלוי + 30 שנה רצופות.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיפים 5, 94", "ע\"א 700/88 חוה אסטרחאן נ'' זאב בן-חורין, פ\"ד מה(3) 720 (1991)", "ע\"א 1904/19 פיליפ בלאיש נ'' פרח דיב (22.3.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הזכות ראויה להוות זיקת הנאה, שימוש גלוי ונוגד, ותקופת שימוש של 30 שנים רצופות.', true, 'תשובה זו נכונה. אלו הם שלושת התנאים המצטברים שנקבעו בסעיף 94 לחוק המקרקעין ובפסיקה (כגון פרשת אסטרחאן) להיווצרות זיקת הנאה מכוח שנים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הזכות ראויה להוות זיקת הנאה, שימוש בהסכמת הבעלים, ותקופת שימוש של 25 שנים רצופות.', false, 'טענה זו שגויה. השימוש צריך להיות ''נוגד'' ולא בהסכמה, ותקופת השימוש הנדרשת היא 30 שנה ולא 25.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הזכות ראויה להוות זיקת הנאה, שימוש סמוי, ותקופת שימוש של 30 שנים רצופות.', false, 'טענה זו שגויה. השימוש צריך להיות גלוי וחשוף לעין כל, ולא סמוי, כדי שבעל המקרקעין יוכל להתנגד לו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הזכות ראויה להוות זיקת הנאה, שימוש נוגד, ורישום הזיקה במרשם המקרקעין תוך 30 שנה.', false, 'טענה זו שגויה. הרישום אינו תנאי להיווצרות הזיקה, אלא זכות לדרוש רישום לאחר שהזיקה כבר נוצרה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'זיקת הנאה במקרקעי ציבור מוחכרים',
    3, 'קרקע בבעלות הקרן הקיימת לישראל (קק"ל) הוחכרה לדורות ליוסי. במשך 35 שנים, דני עובר דרך חלקת הקרקע המוחכרת ליוסי בדרכו לביתו, ללא הסכמתו של יוסי וללא התנגדות מצידו. כעת, יוסי מבקש למנוע מדני את המעבר. מה הדין?', 'השאלה בוחנת את החריג לכלל שלפיו לא נוצרת זיקת הנאה מכוח שנים במקרקעי ציבור, כאשר מדובר במקרקעי ציבור שהוחכרו לדורות לאדם פרטי. קיימת מחלוקת בפסיקה ובספרות לגבי אפשרות היווצרות זיקה כזו כנגד החוכר.', 'סעיף 113(ג) לחוק המקרקעין קובע כי סעיף 94 לא יחול במקרקעי ציבור. עם זאת, בפסיקת בתי המשפט המחוזיים ובספרות המשפטית הובעה דעה לפיה כאשר מקרקעי ציבור הוחכרו בחכירה לדורות, נחלש הרציונל שבבסיס סעיף 113(ג) (הקושי של המדינה לפקח על מקרקעיה). לפי גישה זו, ניתן להכיר בזיקת הנאה מכוח שנים כנגד החוכר לדורות, אך לא כנגד הבעלים (המדינה/קק"ל), ותוקפה של הזיקה מוגבל לתקופת החכירה. בית המשפט העליון הותיר שאלה זו בצריך עיון (רע"א 8910/13 דניאל נ'' עזבון המנוחים הסה ז"ל).',
    'הנחה גורפת כי סעיף 113(ג) שולל כל זיקת הנאה במקרקעי ציבור, מבלי להתייחס למצב של חכירה לדורות, או בלבול בין זיקה כנגד החוכר לבין זיקה כנגד הבעלים.', '["זיקת הנאה מכוח שנים", "מקרקעי ציבור", "חכירה לדורות", "סעיף 113(ג) לחוק המקרקעין", "רע\"א 8910/13 דניאל נ'' הסה"]'::jsonb, '**מקרקעי ציבור מוחכרים לדורות:** האם ניתן לרכוש זיקת הנאה מכוח שנים? ← יש גישה בפסיקה ובספרות שכן, כנגד החוכר בלבד.
**תוקף הזיקה כנגד חוכר:** עד מתי? ← עד תום תקופת החכירה.
**האם הזיקה מחייבת את הבעלים (המדינה/קק"ל)?** ← לא, רק את החוכר.
**עמדת בית המשפט העליון:** האם הכריע? ← הותיר את השאלה בצריך עיון (רע"א 8910/13).', 'מקרקעי ציבור מוחכרים לדורות ← זיקת הנאה מכוח שנים אפשרית כנגד החוכר בלבד ← תוקפה מוגבל לתקופת החכירה.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיפים 94, 113(ג)", "רע\"א 8910/13 שאול דניאל נ'' עזבון המנוחים יחזקאל ואלישבע הסה ז\"ל (16.11.2014)", "ע\"א (מחוזי ת\"א) 38409-10-11 עזבון המנוחים יחזקאל ואלישבע הסה ז\"ל נ'' דניאל שאול (2013)", "ת\"א (מחוזי ת\"א) 2789/07 פרייס לאה ואחרים נ'' שחר טליה ואחרים (2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לדני אין זיקת הנאה, שכן מדובר במקרקעי ציבור, וסעיף 113(ג) לחוק המקרקעין שולל זיקת הנאה מכוח שנים במקרקעין אלה.', false, 'טענה זו שגויה. אף שמדובר במקרקעי ציבור, קיימת בפסיקה ובספרות גישה לפיה ניתן להכיר בזיקת הנאה כנגד חוכר לדורות, שכן הנימוק שבבסיס סעיף 113(ג) (קושי פיקוח של המדינה) אינו מתקיים במקרה זה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לדני יש זיקת הנאה מכוח שנים, אך תוקפה יהיה כלפי יוסי בלבד ויפקע עם תום תקופת החכירה.', true, 'תשובה זו נכונה. אף שבית המשפט העליון הותיר את השאלה בצריך עיון, בפסיקת בתי המשפט המחוזיים ובספרות המשפטית הובעה גישה לפיה ניתן להכיר בזיקת הנאה מכוח שנים כנגד חוכר לדורות במקרקעי ציבור, כאשר תוקפה מוגבל לתקופת החכירה ואינה מחייבת את הבעלים (המדינה/קק"ל).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לדני יש זיקת הנאה מכוח שנים, והיא תחייב גם את קק"ל כבעלת המקרקעין.', false, 'טענה זו שגויה. גם לפי הגישה המקלה, זיקת ההנאה במקרקעי ציבור מוחכרים תחייב את החוכר בלבד, ולא את הבעלים (קק"ל), שכן הדבר נועד להגן על זכויות המדינה במקרקעין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לדני יש זיקת הנאה מכוח שנים רק אם קק"ל הסכימה לשימוש בכתב.', false, 'טענה זו שגויה. זיקת הנאה מכוח שנים נוצרת משימוש נוגד, ולא משימוש בהסכמה. הסכמה בכתב תיצור זיקת הנאה הסכמית, לא מכוח שנים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ביטול זיקת הנאה',
    4, 'לראובן יש זיקת הנאה רשומה למעבר דרך חלקת שמעון. כעת, נסללה דרך ציבורית חדשה המאפשרת לראובן גישה נוחה יותר לביתו, והשימוש בזיקת ההנאה בחלקת שמעון הפך למיותר. שמעון מעוניין לבטל את זיקת ההנאה. מה הדרך הנכונה לפעול?', 'השאלה עוסקת בסמכות בית המשפט לבטל או לשנות זיקת הנאה קיימת, במיוחד במקרים של שינוי נסיבות שהופך את הזיקה למיותרת או פוגענית באופן בלתי סביר.', 'סעיף 96 לחוק המקרקעין קובע כי ''זיקת הנאה היא לתקופה בלתי מוגבלת, זולת אם נקבעה לה תקופה בתנאי הזיקה; אולם בית המשפט רשאי, על פי בקשת צד מעוניין או היועץ המשפטי לממשלה, לבטל את הזיקה או לשנות תנאיה, אם ראה לעשות כן בגלל אי הפעלת הזיקה או בגלל שינוי בנסיבות השימוש בה או במצב המקרקעין הזכאים או הכפופים; ורשאי בית המשפט לפסוק פיצוי למי שנגרם לו נזק על ידי הביטול או השינוי''. במקרה זה, סלילת דרך ציבורית חדשה מהווה שינוי נסיבות המצדיק פנייה לבית המשפט בבקשה לביטול הזיקה.',
    'הנחה שזיקת הנאה היא זכות בלתי ניתנת לביטול, או בלבול בין ביטול זיקה קיימת לבין מניעת היווצרותה.', '["ביטול זיקת הנאה", "שינוי נסיבות", "סמכות בית המשפט", "סעיף 96 לחוק המקרקעין", "פיצויים"]'::jsonb, '**ביטול זיקת הנאה רשומה:** מי מוסמך? ← בית המשפט (סעיף 96 לחוק המקרקעין).
**עילות לביטול:** מהן? ← אי הפעלת הזיקה, שינוי בנסיבות השימוש, שינוי במצב המקרקעין הזכאים או הכפופים.
**האם נדרשת הסכמת בעל הזיקה?** ← לא, בית המשפט יכול לבטל גם ללא הסכמה.
**פיצויים:** האם ניתן לפסוק? ← כן, בית המשפט רשאי לפסוק פיצוי למי שנגרם לו נזק עקב הביטול או השינוי.', 'ביטול זיקת הנאה ← רק ע"י בית המשפט (סעיף 96 לחוק המקרקעין) ← עקב שינוי נסיבות או אי הפעלה.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 96"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'שמעון יכול להודיע לראובן בכתב על ביטול הזיקה, והיא תבוטל באופן מיידי.', false, 'טענה זו שגויה. הודעה חד-צדדית אינה יכולה לבטל זיקת הנאה קניינית שכבר נוצרה ונרשמה. הודעה בכתב רלוונטית רק להפסקת מרוץ 30 השנים לפני היווצרות הזיקה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'שמעון צריך להגיש בקשה לבית המשפט לביטול הזיקה, ובית המשפט רשאי לבטלה אם ראה שינוי בנסיבות השימוש.', true, 'תשובה זו נכונה. סעיף 96 לחוק המקרקעין מקנה לבית המשפט סמכות לבטל או לשנות זיקת הנאה, בין היתר, עקב שינוי בנסיבות השימוש בה או במצב המקרקעין הזכאים או הכפופים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'שמעון יכול לבטל את הזיקה רק אם ראובן מסכים לכך בכתב.', false, 'טענה זו שגויה. הסכמת ראובן תאפשר ביטול בהסכמה, אך גם בהיעדר הסכמה, שמעון יכול לפנות לבית המשפט בבקשה לביטול הזיקה עקב שינוי נסיבות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'זיקת הנאה רשומה אינה ניתנת לביטול בשום מקרה.', false, 'טענה זו שגויה. סעיף 96 לחוק המקרקעין קובע מפורשות את האפשרות לבטל או לשנות זיקת הנאה על ידי בית המשפט.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 26, '2022-W-S-Q26';
END
$$;

