DO $$
DECLARE
  v_sq_id uuid := 'a9536445-ae68-40e0-8ee0-aab7f4e185e9'::uuid;
  v_group_id uuid := '3bdcfccd-1141-417a-88e4-2db53d71f754'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '94db7cea-7c9d-409d-b102-164b806e3b25'::uuid;
  v_ang_1 uuid := 'f54b7976-89c1-4ded-93c0-7c3af55e6506'::uuid;
  v_ang_2 uuid := '9751c4f9-56b6-445a-9074-c9b6b49e7e5e'::uuid;
  v_ang_3 uuid := 'c34fb372-64a2-49bc-9ae7-b174d8c0578d'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 27, '2022-W-S-Q27';
