  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'mortgages_housing_loans' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'mortgages_housing_loans', 'property';
