  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q27', v_chapter_id, v_subtopic_id, 'דירת המגורים של משה (להלן: הנכס), שאותה ירש מהוריו המנוחים, שווה 7,000,000 ש"ח, והיא אינה משועבדת. בחודש ינואר 2022 לקח משה הלוואה בסך 2,000,000 ש"ח מבנק הממשכן בע"מ. לצורך הבטחת החזר החוב, שעבד משה את דירת המגורים שלו במשכנתה מדרגה ראשונה. כעת משה פונה אליכם לייעוץ ושואל אם הוא רשאי לקחת הלוואה נוספת בסך 1,000,000 ש"ח מחברת הביטוח "שמרית בע"מ", ולשעבד את הנכס בשעבוד נוסף לטובת החברה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 27}'::jsonb, 'השאלה עוסקת באפשרות החייב לשעבד נכס שכבר ממושכן במשכון נוסף, בהתאם להוראות סעיף 6(א) לחוק המשכון. הסעיף מאפשר זאת ככלל, אך קובע עדיפות לנושה הראשון, ומסייג את האפשרות אם הסכם המשכון הראשון קובע אחרת.', 'סעיף 6(א) לחוק המשכון, תשכ"ז-1967, קובע כי ''החייב רשאי לשעבד את הנכס הממושכן במישכון נוסף בלי נטילת רשות מאת הנושה; אולם נושה נוסף לא יוכל להיפרע מן המשכון אלא לאחר שסולק החיוב שהובטח במישכון שלפניו; והכל באין קביעה אחרת בהסכם המישכון הקודם''. כלומר, ככלל, משה רשאי לשעבד את הנכס במשכנתה נוספת ללא הסכמת הבנק, אך חברת הביטוח תוכל להיפרע מהנכס רק לאחר שהבנק ייפרע במלואו. אפשרות זו כפופה לכך שבהסכם המשכנתה הראשון עם הבנק לא נקבע תנאי האוסר על יצירת משכון נוסף. אם קיים תנאי כזה, האפשרות לשעבד את הנכס במשכון נוסף ללא הסכמת הבנק נשללת.', 'הבלבול בין הצורך בהסכמת הנושה הראשון לבין קיומו של תנאי מפורש בהסכם המשכון הראשון האוסר על משכון נוסף. ברירת המחדל היא שאין צורך בהסכמה, אלא אם יש איסור מפורש.',
    '["חוק המשכון סעיף 6(א)", "משכון נוסף", "משכנתה", "עדיפות נושים", "הסכם משכון"]'::jsonb, '**משכון נוסף ללא הסכמת הנושה הראשון:** האם מותר? ← כן, אלא אם הסכם המשכון הראשון אוסר זאת (סעיף 6(א) לחוק המשכון).
**סדר פירעון במשכון נוסף:** מי קודם? ← הנושה הראשון קודם, הנושה השני ייפרע רק לאחר סילוק חובו של הראשון.
**האם ניתן לקבוע דרגה שווה או עדיפה?** ← כן, אך רק בהסכמת הנושה הראשון (סעיף 6(ב) לחוק המשכון).
**האם איסור בהסכם המשכון הראשון מבטל את המשכון השני?** ← לא בטלות מוחלטת, אך הנושה הראשון יכול לתקוף אותו (פסק דין לוי).', 'משכון נוסף ← מותר ללא הסכמה (אלא אם נאסר בהסכם) ← הנושה הראשון קודם (סעיף 6(א) לחוק המשכון).', '["חוק המשכון, תשכ\"ז-1967, סעיף 6", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.1.2014)", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 6 - מישכון נוסף", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | ו. מישכון נוסף"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הסדר מקרקעין'' → mapped chapter=''property'' subtopic=''mortgages_housing_loans'' | classifier_note: Inherited apartment as collateral for 2M NIS loan — mortgage / debt security | source_review_note: השאלה עוסקת בדיני משכון ומשכנתאות, שהם חלק מדיני הקניין המהותיים. מופתה ל''סדר דין אזרחי'' ו''הסדר מקרקעין'' כקירוב הטוב ביותר מתוך הרשימה הסגורה, אך יש לשקול הוספת פרק ''דיני קניין'' או סיווג מתאים יותר.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן לשעבד נכס בשעבוד נוסף כלשהו אלא בהסכמת הנושה הראשון.', false, 'טענה זו שגויה, שכן סעיף 6(א) לחוק המשכון קובע כי החייב רשאי לשעבד נכס במשכון נוסף ללא נטילת רשות מהנושה הראשון, אלא אם נקבע אחרת בהסכם המשכון הקודם.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ניתן תמיד לשעבד נכס בשעבוד נוסף ללא הסכמת הנושה הראשון, אולם רק במשכנתה מדרגה שנייה.', false, 'טענה זו שגויה, שכן האפשרות לשעבד נכס בשעבוד נוסף ללא הסכמת הנושה הראשון אינה קיימת ''תמיד'', אלא רק אם אין קביעה אחרת בהסכם המשכון הקודם.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אם אין תנאי בהסכם ההלוואה עם הנושה הראשון האוסר על כך, ניתן לשעבד נכס בשעבוד נוסף ללא הסכמת הנושה הראשון, אך רק במשכנתה מדרגה פחותה מדרגתו של הנושה הראשון.', true, 'תשובה זו נכונה. סעיף 6(א) לחוק המשכון קובע כי החייב רשאי לשעבד נכס ממושכן במשכון נוסף ללא רשות הנושה הראשון, אלא אם נקבע אחרת בהסכם המשכון הקודם. במקרה כזה, הנושה הנוסף ייפרע רק לאחר סילוק החיוב של הנושה הראשון, כלומר המשכון הנוסף יהיה בדרגה נחותה.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אם אין תנאי בהסכם ההלוואה עם הנושה הראשון האוסר על כך, ניתן לשעבד נכס בשעבוד נוסף ללא הסכמת הנושה הראשון, בכל דרגה שהיא.', false, 'טענה זו שגויה. סעיף 6(א) לחוק המשכון קובע במפורש כי הנושה הנוסף ייפרע רק לאחר סילוק החיוב של הנושה הראשון, מה שמעיד על דרגה נחותה, ולא ''בכל דרגה שהיא''. דרגה שווה או עדיפה דורשת הסכמה מפורשת של הנושה הראשון לפי סעיף 6(ב).', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תוקף משכון שני בניגוד להסכם',
    1, 'משה שעבד את דירת המגורים שלו במשכנתה מדרגה ראשונה לבנק הממשכן בע"מ. בהסכם המשכנתה נקבע במפורש כי אסור למשה לשעבד את הנכס בשעבוד נוסף ללא הסכמת הבנק. למרות זאת, משה לקח הלוואה מחברת הביטוח "שמרית בע"מ" ושעבד את הנכס במשכנתה נוספת לטובתה, מבלי לקבל את הסכמת הבנק. כעת, משה מבקש לבטל את המשכנתה השנייה בטענה שהיא בטלה מעיקרה. הבנק הממשכן אינו מתנגד למשכנתה השנייה. מה הדין?', 'השאלה בוחנת את תוקפו של משכון שני שנוצר בניגוד לתניה מגבילה בהסכם המשכון הראשון, ובפרט את מעמדו של החייב לטעון לבטלותו. הלכת בית המשפט העליון קובעת כי החייב מנוע מלטעון לבטלות משכון כזה.', 'סעיף 6(א) לחוק המשכון קובע כי החייב רשאי לשעבד נכס ממושכן במשכון נוסף, אלא אם נקבע אחרת בהסכם המשכון הקודם. בית המשפט העליון ברע"א 8574/13 לוי נ'' עזבון המנוח פרדי זגורי ז"ל (פסק דין לוי) קבע כי העדר הסכמה ליצירת משכון נוסף בניגוד לתנאי המשכון המקורי אינו מוביל לבטלות מוחלטת של המשכון השני. נקבע כי המשכון השני אינו תקף ביחסים שבין בעל המשכון הראשון לבעל המשכון השני, אך הוא תקף ביחס לחייב עצמו, והחייב מנוע מלטעון לבטלותו. תכלית הסייג בסעיף 6(א) היא להגן על הנושה הראשון, ולא לתת הגנה לחייב מפני מעשיו שלו.',
    'הנחה שכל הפרה של תנאי בהסכם משכון מובילה לבטלות מוחלטת של המשכון המאוחר, מבלי להבחין בין הצדדים השונים ובין תכלית ההוראה.', '["חוק המשכון סעיף 6(א)", "משכון נוסף", "בטלות יחסית", "מניעות והשתק", "פסק דין לוי"]'::jsonb, '**משכון שני בניגוד לתנאי המשכון הראשון:** האם בטל בטלות מוחלטת? ← לא, בטלות יחסית (פסק דין לוי).
**האם החייב יכול לטעון לבטלות המשכון השני?** ← לא, החייב מנוע מלטעון זאת (פסק דין לוי).
**תכלית סעיף 6(א) לחוק המשכון:** מהי? ← להגן על הנושה הראשון, לא על החייב.
**היחסים בין הנושה הראשון לנושה השני:** האם המשכון השני תקף? ← לא תקף ביחסים אלה, הנושה הראשון יכול לתקוף אותו.', 'משכון שני בניגוד להסכם ראשון ← לא בטל מוחלטת ← החייב מנוע מלטעון לבטלותו (פסק דין לוי).',
    '["חוק המשכון, תשכ\"ז-1967, סעיף 6(א)", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.1.2014)", "ה\"פ (מחוזי ת\"א) 41927-12-13 כדורי שיווק ביצים בע\"מ ה נ'' בנק מזרחי טפחות בע\"מ (15.4.2015)", "ע\"א (מחוזי ת\"א) 4512-10-14 מס-קל ייעוץ כלכלי במיסוי בע\"מ נ'' עו\"ד יגאל וייס (8.8.2016)", "פש\"ר (מחוזי ת\"א) 10344-02-16 עו\"ד גילת שטיינברג נאמנת לנכסי החייב יצחק משולם לנדא, בפשיטת רגל נ'' דוד שמחה (1.6.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'המשכנתה השנייה בטלה מעיקרה, שכן היא נוצרה בניגוד לתנאי מפורש בהסכם המשכנתה הראשון.', false, 'טענה זו שגויה. הלכת בית המשפט העליון קובעת כי משכון שני שנוצר בניגוד לתנאי המשכון הראשון אינו בטל בטלות מוחלטת, ובמיוחד לא כלפי החייב עצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'משה מנוע מלטעון לבטלות המשכנתה השנייה, שכן תכלית סעיף 6(א) לחוק המשכון אינה להגן על החייב מפני מעשיו שלו.', true, 'תשובה זו נכונה. בית המשפט העליון בפסק דין לוי קבע כי החייב מנוע מלטעון לבטלות משכון שני שנוצר בניגוד לתנאי המשכון הראשון, שכן הסייג בסעיף 6(א) נועד להגן על הנושה הראשון ולא על החייב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'המשכנתה השנייה תקפה רק אם הבנק הממשכן נתן את הסכמתו בדיעבד.', false, 'טענה זו שגויה. תוקף המשכנתה השנייה כלפי החייב אינו תלוי בהסכמת הבנק, אלא במניעותו של החייב מלטעון לבטלותה. הסכמת הבנק רלוונטית ליחסים בין הבנק לנושה השני.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'המשכנתה השנייה תקפה רק אם חברת הביטוח לא ידעה על התנאי האוסר בהסכם המשכנתה הראשון.', false, 'טענה זו שגויה. ידיעת חברת הביטוח על התנאי האוסר אינה משפיעה על מניעותו של משה לטעון לבטלות המשכנתה השנייה. תום הלב של הנושה השני רלוונטי בעיקר לתקנת השוק, שאינה המקרה כאן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תכלית סעיף 6(א) לחוק המשכון',
    2, 'מהי התכלית העיקרית של סעיף 6(א) לחוק המשכון, המאפשר לחייב לשעבד נכס ממושכן במשכון נוסף?', 'השאלה מתמקדת בתכלית החקיקתית של סעיף 6(א) לחוק המשכון, המאזן בין הצורך לאפשר לחייב גמישות כלכלית לבין הגנה על זכויות הנושה הראשון בזמן.', 'תכליתו העיקרית של סעיף 6(א) לחוק המשכון היא לפתוח בפני החייב את הדרך לשעבד נכס ממושכן במשכון נוסף בלי נטילת רשות מאת הנושה הראשון בזמן. זאת, בכפוף לכך שהנושה השני בזמן ייפרע מהנכס רק לאחר שסולק החיוב שהובטח במשכון שלפניו. הסייג שבסיפא הסעיף (''והכל באין קביעה אחרת בהסכם המישכון הקודם'') נועד להגן על ההסכמה שניתנה לבעל המשכון הראשון ועל זכויותיו, במקרים שבהם המשכון השני עלול לפגוע בו. הסעיף לא נועד להגן על החייב עצמו מפני בעל המשכון השני.',
    'הבנה שגויה של תכלית הסעיף כהגנה על החייב או כאיסור גורף על משכונות נוספים, במקום איזון האינטרסים בין החייב לנושים.', '["חוק המשכון סעיף 6(א)", "תכלית חקיקה", "איזון אינטרסים", "עדיפות נושים", "גמישות כלכלית"]'::jsonb, '**מטרת סעיף 6(א):** מהי? ← לאפשר לחייב לשעבד נכס נוסף, תוך שמירה על עדיפות הנושה הראשון.
**הגנה על הנושה הראשון:** כיצד? ← הנושה השני ייפרע רק לאחר סילוק חוב הנושה הראשון.
**הגנה על החייב:** האם הסעיף מגן על החייב? ← לא, החייב מנוע מלטעון לבטלות המשכון השני.
**הסייג ''באין קביעה אחרת'':** למי נועד? ← להגן על הנושה הראשון מפני פגיעה בזכויותיו.', 'סעיף 6(א) לחוק המשכון ← מאפשר משכון נוסף ← מגן על עדיפות הנושה הראשון ← לא מגן על החייב.',
    '["חוק המשכון, תשכ\"ז-1967, סעיף 6(א)", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.1.2014)", "ה\"פ (מחוזי ת\"א) 41927-12-13 כדורי שיווק ביצים בע\"מ ה נ'' בנק מזרחי טפחות בע\"מ (15.4.2015)", "עחדל\"פ (שלום תל אביב-יפו) 1582-02-23 קוואלטי קרדיט פאנד נ'' עו\"ד חנן חדד (11.6.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לאפשר לחייב גמישות כלכלית ולפתוח בפניו את הדרך לשעבד נכס ממושכן במשכון נוסף, תוך הגנה על זכויות הנושה הראשון.', true, 'תשובה זו נכונה. תכלית סעיף 6(א) היא לאפשר לחייב למשכן נכסים נוספים, ובמקביל להבטיח את עדיפות הנושה הראשון, כך שהנושה השני ייפרע רק לאחר סילוק חובו של הנושה הראשון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'להגן על החייב מפני נושים נוספים, על ידי מתן אפשרות לבטל משכון שני שנוצר בניגוד לתנאי המשכון הראשון.', false, 'טענה זו שגויה. סעיף 6(א) אינו נועד להגן על החייב מפני נושים נוספים, והחייב אף מנוע מלטעון לבטלות משכון שני שנוצר בניגוד לתנאי המשכון הראשון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'למנוע יצירת משכונות נוספים על נכס, אלא אם כן ניתנה הסכמה מפורשת של כל הנושים הקודמים.', false, 'טענה זו שגויה. הסעיף דווקא מאפשר יצירת משכון נוסף ללא הסכמת הנושה הראשון, אלא אם נקבע אחרת בהסכם המשכון הקודם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לקבוע כי כל משכון שני שנוצר בניגוד לתנאי המשכון הראשון בטל בטלות מוחלטת כלפי כולי עלמא.', false, 'טענה זו שגויה. הפסיקה קבעה כי משכון שני שנוצר בניגוד לתנאי המשכון הראשון אינו בטל בטלות מוחלטת, אלא בטלות יחסית, בעיקר ביחסים שבין הנושה הראשון לנושה השני.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תוקף משכון שני כלפי נושים אחרים',
    3, 'משה שעבד את דירת המגורים שלו במשכנתה מדרגה ראשונה לבנק הממשכן בע"מ. בהסכם המשכנתה נקבע במפורש כי אסור למשה לשעבד את הנכס בשעבוד נוסף ללא הסכמת הבנק. למרות זאת, משה לקח הלוואה מחברת הביטוח "שמרית בע"מ" ושעבד את הנכס במשכנתה נוספת לטובתה, מבלי לקבל את הסכמת הבנק. המשכנתה השנייה נרשמה כדין. כעת, משה נקלע לחדלות פירעון, והנאמן לנכסיו טוען כי המשכנתה השנייה בטלה כלפי נושיו הכלליים של משה. מה הדין?', 'השאלה עוסקת בהיקף תחולתה של הלכת לוי, ובפרט בשאלה האם נושיו הכלליים של החייב (כמו נאמן בחדלות פירעון) רשאים לטעון לבטלותו של משכון שני שנוצר בניגוד לתנאי המשכון הראשון. בתי המשפט המחוזיים נוטים לקבוע כי המשכון תקף כלפי נושים אלה.', 'בית המשפט העליון בפסק דין לוי הותיר בצריך עיון את השאלה האם נושיו של החייב, להבדיל מהחייב עצמו, רשאים לטעון לבטלותו של המשכון השני. עם זאת, בתי המשפט המחוזיים, בהתבסס על הרציונל של פסק דין לוי, קבעו כי משכון שני שנרשם בניגוד להסכמת הנושה הראשון תקף כלפי נושיו הכלליים של החייב. הנימוק לכך הוא שהוראת סעיף 6(א) לחוק המשכון נועדה להגן על זכויותיו של בעל המשכון הראשון בלבד, ואין מקום להרחיבה באופן שתקים טענה לנושים כלליים, במיוחד כאשר המשכון רשום ודבר קיומו ידוע להם או צריך היה להיות ידוע. הנאמן בחדלות פירעון נכנס בנעלי החייב, ולכן המניעות החלה על החייב חלה גם עליו.',
    'הנחה שנושים כלליים נהנים מאותה הגנה כמו הנושה הראשון, או שהם יכולים לטעון לבטלות משכון רשום רק בגלל הפרת תנאי בהסכם קודם.', '["חוק המשכון סעיף 6(א)", "נושים כלליים", "נאמן בחדלות פירעון", "בטלות יחסית", "פומביות הרישום"]'::jsonb, '**משכון שני בניגוד להסכם כלפי נושים כלליים:** האם תקף? ← כן, אם רשום, שכן סעיף 6(א) מגן על הנושה הראשון בלבד.
**מעמד הנאמן בחדלות פירעון:** האם יכול לטעון לבטלות? ← לא, הוא נכנס בנעלי החייב, והחייב מנוע מלטעון זאת.
**האם רישום המשכון משנה?** ← כן, רישום מקנה פומביות ותוקף כלפי כולי עלמא, כולל נושים כלליים.
**הלכת לוי והרחבתה:** האם העליון הכריע לגבי נושים כלליים? ← לא, אך בתי המחוזיים הרחיבו את הרציונל.', 'משכון שני בניגוד להסכם ← תקף כלפי נושים כלליים (אם רשום) ← הנאמן מנוע מלטעון לבטלות.',
    '["חוק המשכון, תשכ\"ז-1967, סעיף 6(א)", "רע\"א 8574/13 ירון לוי נ'' עזבון המנוח פרדי זנזורי ז\"ל (28.1.2014)", "ה\"פ (מחוזי ת\"א) 41927-12-13 כדורי שיווק ביצים בע\"מ ה נ'' בנק מזרחי טפחות בע\"מ (15.4.2015)", "פש\"ר (מחוזי ת\"א) 58026-10-13 דוד גולבלט לוי, עו\"ד (מנהל מיוחד) נ'' לוי גוטמן (22.6.2016)", "ע\"א (מחוזי ת\"א) 4512-10-14 מס-קל ייעוץ כלכלי במיסוי בע\"מ נ'' עו\"ד יגאל וייס (8.8.2016)", "פש\"ר (מחוזי ת\"א) 10344-02-16 עו\"ד גילת שטיינברג נאמנת לנכסי החייב יצחק משולם לנדא, בפשיטת רגל נ'' דוד שמחה (1.6.2017)", "פש\"ר (מחוזי ת\"א) 11482-08-14 אודי חסון נ'' אברהם חי מכלוף (21.3.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'המשכנתה השנייה בטלה כלפי נושיו הכלליים של משה, שכן היא נוצרה בניגוד לתנאי מפורש בהסכם המשכנתה הראשון.', false, 'טענה זו שגויה. הפסיקה נוטה לראות במשכון שני שנוצר בניגוד לתנאי המשכון הראשון כתקף כלפי נושים כלליים, במיוחד אם הוא רשום, שכן התנאי נועד להגן על הנושה הראשון ולא על נושים אחרים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'המשכנתה השנייה תקפה כלפי נושיו הכלליים של משה, שכן הוראת סעיף 6(א) לחוק המשכון נועדה להגן על הנושה הראשון בלבד, ולא על נושים כלליים.', true, 'תשובה זו נכונה. בתי המשפט המחוזיים, בהתבסס על הרציונל של פסק דין לוי, קבעו כי משכון שני שנרשם בניגוד להסכמת הנושה הראשון תקף כלפי נושיו הכלליים של החייב, שכן סעיף 6(א) נועד להגן על הנושה הראשון בלבד, ורישום המשכון מספק פומביות לנושים האחרים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'תוקף המשכנתה השנייה כלפי נושיו הכלליים של משה תלוי בשאלה אם הנאמן ידע על קיומה בעת מינויו.', false, 'טענה זו שגויה. תוקף המשכנתה השנייה כלפי נושים כלליים אינו תלוי בידיעת הנאמן, אלא בעצם רישומה, המקנה לה תוקף כלפי כולי עלמא.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'המשכנתה השנייה תקפה רק אם הבנק הממשכן הודיע במפורש כי הוא מוותר על זכותו לטעון לבטלותה.', false, 'טענה זו שגויה. ויתור הבנק רלוונטי ליחסים בינו לבין הנושה השני, אך אינו תנאי לתוקף המשכנתה השנייה כלפי נושים כלליים, במיוחד כאשר היא רשומה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הגדלת חיוב במשכון קיים',
    4, 'משה שעבד את דירת המגורים שלו במשכנתה מדרגה ראשונה לבנק הממשכן בע"מ, להבטחת הלוואה בסך 2,000,000 ש"ח. כעת, משה מעוניין להגדיל את ההלוואה מהבנק בסך נוסף של 500,000 ש"ח. האם המשכנתה הקיימת תבטיח באופן אוטומטי גם את היתרה שנוספה?', 'השאלה עוסקת בהיקף תחומה של הערובה במשכון, ובפרט בשאלה האם משכון קיים מבטיח באופן אוטומטי הגדלה של החיוב המובטח. סעיף 7(ב) לחוק המשכון מסדיר סוגיה זו.', 'סעיף 7(ב) לחוק המשכון קובע מפורשות כי ''הוגדל היקפו של החיוב על פי הסכם בין החייב לבין הנושה, לא ישמש המשכון ערובה ליתרה שנוספה, זולת אם נוצר מישכון נוסף כערובה ליתרה''. כלומר, הגדלת החיוב אינה נכללת באופן אוטומטי תחת המשכון הקיים, אלא דורשת יצירת משכון חדש עבור היתרה שנוספה, על מנת שתהיה מובטחת.',
    'הנחה שמשכון רשום מכסה כל חוב עתידי או מוגדל כלפי אותו נושה, מבלי להתייחס לדרישה ליצירת משכון נוסף עבור היתרה.', '["חוק המשכון סעיף 7(ב)", "תחום הערובה", "הגדלת חיוב", "משכון נוסף", "הסכם משכון"]'::jsonb, '**הגדלת חיוב במשכון קיים:** האם מכוסה אוטומטית? ← לא, לפי סעיף 7(ב) לחוק המשכון.
**כיצד ניתן להבטיח חיוב מוגדל?** ← על ידי יצירת משכון נוסף כערובה ליתרה.
**האם הסכם בין הצדדים מספיק?** ← הסכם להגדלת החיוב אינו מספיק, נדרש משכון נוסף.
**האם יש איסור על הגדלת חיוב?** ← לא, אך ההגדלה לא תהיה מובטחת אלא אם נוצר משכון נוסף.', 'הגדלת חיוב במשכון קיים ← לא מכוסה אוטומטית ← דורש יצירת משכון נוסף (סעיף 7(ב) לחוק המשכון).',
    '["חוק המשכון, תשכ\"ז-1967, סעיף 7(ב)", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 7 - תחומה של הערובה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, המשכנתה הקיימת תבטיח באופן אוטומטי גם את היתרה שנוספה, שכן היא רשומה על הנכס.', false, 'טענה זו שגויה. סעיף 7(ב) לחוק המשכון קובע במפורש כי הגדלת היקף החיוב אינה מכוסה אוטומטית על ידי המשכון הקיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, המשכנתה הקיימת לא תבטיח באופן אוטומטי את היתרה שנוספה, אלא אם כן נוצר משכון נוסף כערובה ליתרה.', true, 'תשובה זו נכונה. סעיף 7(ב) לחוק המשכון קובע כי אם הוגדל היקפו של החיוב, המשכון הקיים לא ישמש ערובה ליתרה שנוספה, אלא אם כן נוצר משכון נוסף כערובה ליתרה זו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, המשכנתה הקיימת תבטיח את היתרה שנוספה, ובלבד שהבנק ירשום הערה על כך במרשם המקרקעין.', false, 'טענה זו שגויה. רישום הערה אינו מספיק; נדרשת יצירת משכון נוסף כדי שהיתרה תהיה מובטחת, כפי שקובע סעיף 7(ב) לחוק המשכון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, המשכנתה הקיימת לא תבטיח את היתרה שנוספה, שכן חוק המשכון אוסר על הגדלת חיוב במשכון קיים.', false, 'טענה זו שגויה. חוק המשכון אינו אוסר על הגדלת חיוב, אלא קובע כי הגדלה כזו דורשת יצירת משכון נוסף כדי שתהיה מובטחת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 27, '2022-W-S-Q27';
END
$$;

-- ============================================================
-- Q28 — 2022-W-S-Q28 — chapter=corporate subtopic=companies_formation
-- classifier_note: Two classes of shares — article amendment requiring class B holders to purchase more shares
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '571510e2-8f42-41ba-8ea0-20e2ef2e8dfe'::uuid;
  v_group_id uuid := '78fc8a1b-4f17-43eb-8ff5-47fe3f4ec8b3'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c40d4155-e241-4a17-bb11-d43a32e421e6'::uuid;
  v_ang_1 uuid := '18296e76-b238-484a-bdbd-35f20ecd1da4'::uuid;
  v_ang_2 uuid := '11f8c04e-f114-41ed-9b50-70bd76760896'::uuid;
  v_ang_3 uuid := '7042654f-57d4-4819-a61f-5c7edb68a220'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q28';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 28, '2022-W-S-Q28';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'companies_formation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'companies_formation', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q28', v_chapter_id, v_subtopic_id, 'מניות החברה "שיבולים בע"מ" מחולקות לשני סוגים, מניות רגילות א'' ומניות רגילות ב''. החברה מבקשת לשנות את אחד מסעיפי התקנון ולקבוע בו חובה על בעלי מניות רגילות ב'' לרכוש מניות נוספות. לשינוי אין השלכה על בעלי מניות רגילות א'', וכמו כן אין בתקנון החברה דרישות רוב מיוחדות לשינוי הוראות התקנון. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 28}'::jsonb, 'השאלה עוסקת באפשרות החברה לשנות את תקנונה באופן המטיל חובה כספית נוספת על בעלי מניות מסוימים. היא בוחנת את האיזון בין עקרון שלטון הרוב לבין הגנת המיעוט, ובפרט את החריג הקבוע בחוק החברות לעניין הגדלת חבות כספית של בעל מניות.', 'סעיף 20(א) לחוק החברות, תשנ"ט-1999, קובע כי חברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית, אלא אם כן נקבע בתקנון רוב אחר. במקרה זה, אין דרישות רוב מיוחדות בתקנון. עם זאת, סעיף 20(ב) לחוק קובע כי אם שינוי התקנון משפיע על זכויות סוג מניות מסוים, הוא טעון גם אישור אסיפת הסוג של אותו סוג מניות. במקרה הנדון, השינוי משפיע רק על בעלי מניות רגילות ב'', ולכן נדרשת אסיפת סוג שלהם. החשוב מכל הוא סעיף 22(א) לחוק החברות, הקובע כי ''שינוי בתקנון הדורש מבעל מניה לרכוש מניות נוספות, או המגדיל בדרך אחרת את חבותו כלפי החברה, לא יחייב אותו אלא אם כן הסכים לכך בכתב''. כלומר, גם אם ההחלטה מתקבלת ברוב הנדרש באסיפה הכללית ובאסיפת הסוג, היא לא תחייב את בעלי מניות רגילות ב'' שלא הסכימו לה בכתב, שכן היא מטילה עליהם חובה כספית נוספת.', 'הטעות הנפוצה היא להניח שכל החלטה שהתקבלה ברוב הנדרש באסיפה הכללית (ואולי גם באסיפת סוג) מחייבת את כל בעלי המניות, מבלי להתייחס לחריג הספציפי של הגדלת חבות כספית, הדורש הסכמה בכתב.',
    '["שינוי תקנון", "חוק החברות", "סעיף 20", "סעיף 22", "הגדלת חבות כספית", "הסכמה בכתב", "אסיפת סוג", "שלטון הרוב", "הגנת המיעוט"]'::jsonb, '**שינוי תקנון רגיל:** מה הרוב הנדרש? ← רוב רגיל באסיפה הכללית, אלא אם נקבע אחרת בתקנון (סעיף 20(א) לחוק החברות).
**שינוי המגדיל חבות כספית:** האם מחייב את כל בעלי המניות? ← לא, רק מי שהסכים בכתב (סעיף 22(א) לחוק החברות).
**האם נדרשת אסיפת סוג במקרה זה?** ← כן, אם השינוי משפיע על זכויות סוג מניות מסוים (סעיף 20(ב) לחוק החברות).
**האם בעל מניות יכול לחסום שינוי תקנון?** ← לא ניתן לחסום את עצם היכולת לשנות תקנון, אך ניתן לשריין הוראות (ע"א 6041/15 האמה בע"מ).', 'שינוי תקנון המגדיל חבות כספית ← דורש הסכמה בכתב של כל בעל מניות מושפע (סעיף 22(א) לחוק החברות) + אסיפת סוג אם משפיע על סוג מניות.', '["חוק החברות, תשנ\"ט-1999, סעיפים 20, 22", "ע\"א 524/88 \"פרי העמק\" - אגודה חקלאית שיתופית בע\"מ נ'' שדה יעקב - מושב עובדים של הפועל המזרחי להתיישבות, מה(4) 529 (15.8.1991)", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (25.9.2016)", "ה\"פ (מחוזי תל אביב-יפו) 986/07 עו\"ד אליהוד יערי נ'' חב'' מעוז הכרך (27.5.2009)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: Two classes of shares — article amendment requiring class B holders to purchase more shares | source_review_note: השאלה עוסקת בדיני חברות מהותיים (שינוי תקנון, זכויות בעלי מניות). מופתה ל''סדר דין אזרחי'' ו''הליכים'' כקירוב הטוב ביותר מתוך הרשימה הסגורה, אך יש לשקול הוספת פרק ''דיני תאגידים'' או סיווג מתאים יותר.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'החברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית. עם זאת, שינוי התקנון לא יחייב את בעלי מניות רגילות ב'' שלא הצביעו בעד.', false, 'טענה זו שגויה חלקית. אמנם שינוי המגדיל חבות כספית אינו מחייב בעל מניות שלא הסכים בכתב, אך לא די בכך שלא הצביע בעד. נדרשת הסכמה אקטיבית בכתב.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'החברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית ובשתי אסיפות הסוג של בעלי המניות.', false, 'טענה זו שגויה. נדרשת אסיפת סוג רק עבור סוג המניות שזכויותיו נפגעות או משתנות, ולא עבור כל סוגי המניות, במיוחד כאשר אין השלכה על סוג א''.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'החברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית ובאסיפת הסוג של בעלי מניות רגילות ב'' בלבד, ולאחר האישור כאמור התיקון יחייב את כל בעלי מניות רגילות ב''.', false, 'טענה זו שגויה. שינוי המגדיל חבות כספית אינו מחייב את כל בעלי המניות מאותו סוג, אלא רק את אלה שהסכימו לכך בכתב, גם אם התקבל ברוב הנדרש באסיפת הסוג.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'החברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית ובאסיפת הסוג של בעלי מניות רגילות ב'' בלבד. עם זאת, שינוי התקנון לא יחייב את בעלי מניות רגילות ב'' שלא הצביעו בעד.', true, 'תשובה זו נכונה. סעיף 20(ב) לחוק החברות מחייב אסיפת סוג נפרדת כאשר שינוי התקנון משפיע על זכויות סוג מניות מסוים. סעיף 22(א) לחוק קובע כי שינוי המגדיל חבות כספית של בעל מניות (כמו חובה לרכוש מניות נוספות) לא יחייב אותו אלא אם הסכים לכך בכתב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שינוי תקנון בחברה פרטית ללא הגדלת חבות',
    1, 'חברת "הצלחה בע"מ" היא חברה פרטית, שמניותיה מחולקות באופן שווה בין ראובן ושמעון. תקנון החברה קובע כי לכל אחד מהם זכות למנות דירקטור אחד. כעת, ראובן מעוניין לשנות את התקנון כך שלדירקטור מטעמו יהיה קול כפול בהצבעות הדירקטוריון. שמעון מתנגד לשינוי. מה הדין?', 'השאלה בוחנת את הכללים לשינוי תקנון בחברה פרטית כאשר השינוי משפיע על זכויות הצבעה, תוך התייחסות לעקרון שלטון הרוב ולמגבלותיו, כגון חובת תום הלב ואיסור קיפוח המיעוט.', 'סעיף 17(א) לחוק החברות קובע כי דין התקנון כדין חוזה בין החברה לבעלי מניותיה ובינם לבין עצמם. סעיף 20(א) לחוק קובע כי חברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית, אלא אם נקבע בתקנון רוב אחר. במקרה זה, אין דרישות רוב מיוחדות. עם זאת, סעיף 192(א)(1) לחוק מטיל חובה על בעל מניה לנהוג בתום לב ובדרך מקובלת בעת שינוי התקנון, ולהימנע מניצול לרעה של כוחו. בנוסף, סעיף 192(ב) אוסר על קיפוח בעלי מניות אחרים. גם אם השינוי מתקבל ברוב הנדרש, בית המשפט יכול להתערב אם יוכח שהשינוי נעשה בחוסר תום לב או מקפח את המיעוט (ראו ע"א 3432/17 טופז (יוכט) נ'' יוכט; ע"א 6041/15 האמה בע"מ נ'' מולר).',
    'הנחה שכל החלטת רוב באסיפה הכללית היא חסינה מפני התערבות, מבלי להתחשב בחובות תום הלב ואיסור קיפוח המיעוט המוטלות על בעלי המניות.', '["שינוי תקנון", "חברה פרטית", "רוב רגיל", "חובת תום לב", "קיפוח מיעוט", "סעיף 20 לחוק החברות", "סעיף 192 לחוק החברות"]'::jsonb, '**שינוי תקנון בחברה פרטית:** מה הרוב הנדרש? ← רוב רגיל, אלא אם התקנון קובע אחרת (סעיף 20(א) לחוק החברות).
**האם בעל מניות רוב יכול לשנות תקנון כרצונו?** ← לא, כפוף לחובת תום הלב ולאיסור קיפוח המיעוט (סעיף 192 לחוק החברות).
**מהי ''החלטה מקפחת''?** ← החלטה הפוגעת בציפיות הלגיטימיות של בעלי המניות, גם אם אינה מפרה זכות מוקנית (עניין טופז).
**האם ניתן לשריין הוראות בתקנון?** ← כן, על ידי קביעת רוב מיוחס לשינוי (עניין האמה).', 'שינוי תקנון בחברה פרטית (ללא הגדלת חבות) ← רוב רגיל + כפוף לתום לב ואי קיפוח מיעוט (סעיפים 20, 192 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 17, 20, 192", "ע\"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט (16.4.2020)", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (25.9.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'השינוי אינו אפשרי, שכן הוא פוגע בזכויותיו השוות של שמעון ודורש את הסכמתו המלאה.', false, 'טענה זו שגויה. שינוי תקנון אפשרי גם ללא הסכמה מלאה, בכפוף לרוב הנדרש ולחובת תום הלב ואי קיפוח המיעוט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'השינוי יחייב את שמעון רק אם יתקבל ברוב הנדרש באסיפה הכללית, ובתנאי שראובן פעל בתום לב ולא קיפח את שמעון.', true, 'תשובה זו נכונה. סעיף 20(א) לחוק החברות מאפשר שינוי תקנון ברוב רגיל, אך סעיף 192 לחוק מטיל חובת תום לב על בעל מניות ומונע קיפוח מיעוט, גם אם ההחלטה התקבלה ברוב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'השינוי אפשרי רק אם שמעון יסכים לו בכתב, שכן הוא משנה את זכויות ההצבעה שלו.', false, 'טענה זו שגויה. הסכמה בכתב נדרשת רק לשינוי המגדיל חבות כספית (סעיף 22 לחוק החברות), לא לשינוי זכויות הצבעה, אשר כפוף לרוב ולחובת תום הלב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'השינוי אפשרי ברוב רגיל באסיפה הכללית, ואין לשמעון כל עילה להתנגד לו.', false, 'טענה זו שגויה. גם אם השינוי מתקבל ברוב רגיל, שמעון יכול לטעון לקיפוח מיעוט או לחוסר תום לב מצד ראובן, בהתאם לסעיף 192 לחוק החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'עקרונות שינוי תקנון חברה',
    2, 'מהם העקרונות המנחים לשינוי תקנון חברה, כפי שבאים לידי ביטוי בחוק החברות ובפסיקה?', 'השאלה מתמקדת בעקרונות היסוד של שינוי תקנון חברה, המאזנים בין חופש ההתאגדות ושלטון הרוב לבין הצורך בהגנה על זכויות המיעוט ועל עקרונות יסוד של דיני החברות.', 'תקנון החברה הוא מסמך יסוד בעל אופי חוזי, המהווה חוזה בין החברה לבעלי מניותיה ובינם לבין עצמם (סעיף 17 לחוק החברות). ככלל, שינוי תקנון נעשה בהחלטת רוב רגיל באסיפה הכללית (סעיף 20(א) לחוק החברות), אלא אם התקנון קובע רוב אחר. עם זאת, על בעלי המניות לפעול בתום לב ובדרך מקובלת בעת שינוי התקנון, ולהימנע מניצול לרעה של כוחם או מקיפוח בעלי מניות אחרים (סעיף 192 לחוק החברות). הפסיקה מדגישה כי לא ניתן לחסום את עצם היכולת לשנות תקנון, אך ניתן לשריין הוראות מסוימות על ידי קביעת רוב מיוחס (ע"א 6041/15 האמה בע"מ נ'' מולר).',
    'התעלמות מהאיזון העדין בין עקרון שלטון הרוב לבין חובות תום הלב וההגינות כלפי המיעוט, או בלבול בין הרוב הנדרש לשינוי תקנון בחברות חדשות לעומת חברות ותיקות.', '["תקנון חברה", "חוזה סטטוטורי", "שינוי תקנון", "רוב רגיל", "רוב מיוחס", "חובת תום לב", "קיפוח מיעוט", "סעיפים 17, 20, 192 לחוק החברות"]'::jsonb, '**מעמד התקנון:** מהו? ← חוזה בין החברה לבעלי מניותיה ובינם לבין עצמם (סעיף 17 לחוק החברות).
**רוב לשינוי תקנון (ברירת מחדל):** מהו? ← רוב רגיל באסיפה הכללית (סעיף 20(א) לחוק החברות).
**מגבלות על שינוי תקנון:** מהן? ← חובת תום לב ואיסור קיפוח מיעוט (סעיף 192 לחוק החברות).
**האם ניתן למנוע שינוי תקנון לחלוטין?** ← לא, אך ניתן לשריין הוראות (ע"א 6041/15 האמה בע"מ).', 'שינוי תקנון ← רוב רגיל (ברירת מחדל) ← כפוף לתום לב ואי קיפוח ← לא ניתן לחסום את עצם השינוי.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 17, 20, 192", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (25.9.2016)", "ע\"א 2508/93 מ'' פלזן נ'' יהלומי אוליראן שאול בוארון בע\"מ, נ(3) 655 (11.12.1996)", "בג\"ץ 6460/02 משה אליאב נ'' בית הדין הארצי לעבודה, ס(4) 411 (8.2.2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'תקנון החברה הוא חוזה בין החברה לבעלי מניותיה ובינם לבין עצמם, הניתן לשינוי ברוב רגיל באסיפה הכללית, בכפוף לחובת תום הלב ולאיסור קיפוח המיעוט.', true, 'תשובה זו נכונה. היא משקפת את העקרונות המרכזיים לשינוי תקנון: מעמדו כחוזה, כלל הרוב הרגיל (ברירת מחדל), והמגבלות של תום לב ואי קיפוח המיעוט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'תקנון החברה הוא מסמך קוגנטי שאינו ניתן לשינוי, אלא בהסכמת כל בעלי המניות.', false, 'טענה זו שגויה. התקנון אינו קוגנטי במובן שאינו ניתן לשינוי, והוא ניתן לשינוי ברוב, לא בהכרח בהסכמת כל בעלי המניות (למעט חריגים ספציפיים).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'שינוי תקנון מחייב תמיד רוב מיוחס של 75% מבעלי המניות, כדי להגן על המיעוט.', false, 'טענה זו שגויה. רוב מיוחס של 75% הוא ברירת מחדל לשינוי תקנון בחברות שהתאגדו לפני חוק החברות (סעיף 24(3)), אך הכלל בחוק החברות הוא רוב רגיל, אלא אם נקבע אחרת בתקנון (סעיף 20(א)).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'החברה אינה יכולה להתנות על יכולתה לשנות את התקנון, וכל שינוי שנעשה ברוב רגיל תקף באופן מוחלט.', false, 'טענה זו שגויה. אמנם חברה אינה יכולה לחסום את עצם היכולת לשנות תקנון, אך שינוי ברוב רגיל אינו תקף באופן מוחלט, והוא כפוף לחובת תום הלב ולאיסור קיפוח המיעוט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שריון הוראות בתקנון והסכם בעלי מניות',
    3, 'חברת "השקעות חכמות בע"מ" היא חברה פרטית. תקנון החברה קובע כי כל שינוי בהוראות הנוגעות למינוי דירקטורים ידרוש הסכמה של 90% מבעלי המניות. בנוסף, קיים הסכם בעלי מניות בין כל בעלי המניות, הקובע כי שינוי כזה ידרוש הסכמה פה אחד. כעת, רוב של 80% מבעלי המניות מעוניין לשנות את הוראות מינוי הדירקטורים. מה הדין?', 'השאלה בוחנת את היחס בין הוראות שריון בתקנון לבין הסכם בעלי מניות, ואת הרוב הנדרש לשינוי הוראות משוריינות. היא מדגישה את חופש העיצוב של הצדדים במסמכי ההתאגדות ואת תוקפם המחייב.', 'סעיף 17(א) לחוק החברות קובע כי דין התקנון כדין חוזה בין החברה לבעלי מניותיה ובינם לבין עצמם. סעיף 20(א) לחוק קובע כי חברה רשאית לשנות את תקנונה ברוב רגיל, אלא אם נקבע בתקנון רוב אחר. במקרה זה, התקנון קובע רוב מיוחס של 90% לשינוי הוראות מינוי דירקטורים. בנוסף, קיים הסכם בעלי מניות בין כל בעלי המניות הקובע הסכמה פה אחד. הפסיקה מכירה בכך שהסכם בעלי מניות, במיוחד בחברה פרטית שכל בעלי מניותיה צד לו, יכול לחייב את החברה ואת בעלי מניותיה, גם אם הוראותיו אינן מעוגנות בתקנון (ע"א 6041/15 האמה בע"מ נ'' מולר). במצב כזה, יש לפעול לפי הדרישה המחמירה יותר, שהיא הסכמה פה אחד. מאחר שרק 80% מסכימים, השינוי אינו אפשרי.',
    'התעלמות מהתוקף המחייב של הסכם בעלי מניות, במיוחד כאשר הוא כולל את כל בעלי המניות, או אי הבחנה בין דרישות רוב שונות בתקנון ובהסכמים.', '["שריון הוראות בתקנון", "הסכם בעלי מניות", "רוב מיוחס", "הסכמה פה אחד", "חברה פרטית", "סעיף 17 לחוק החברות", "סעיף 20 לחוק החברות"]'::jsonb, '**הוראת שריון בתקנון:** מה תוקפה? ← מחייבת רוב מיוחס לשינוי (סעיף 20(א) לחוק החברות).
**הסכם בעלי מניות (כללי):** מה תוקפו? ← מחייב את הצדדים לו, ובחברה פרטית יכול לחייב את החברה (עניין האמה).
**סתירה בין תקנון להסכם בעלי מניות:** מה גובר? ← יש לפרש בהרמוניה, או שהדרישה המחמירה יותר תחול, במיוחד אם ההסכם כולל את כל בעלי המניות.
**האם ניתן לחסום שינוי תקנון לחלוטין?** ← לא ניתן לחסום את עצם היכולת לשנות, אך ניתן להקשות על השינוי (עניין האמה).', 'שריון בתקנון + הסכם בעלי מניות ← דרישה מחמירה יותר גוברת ← שינוי דורש עמידה בכל הדרישות.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 17, 20", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (25.9.2016)", "ה\"פ (כלכלית ) 12344-05-18 היי - סנטר - מרכז ליזמות עסקית טכנולוגיות בחיפה בע נ'' סונקרס בע\"מ (31.5.2018)", "ת\"א (מחוזי תל אביב-יפו) 53928-02-24 עלמא תשתיות קד בע\"מ נ'' טריפל-מ תחנות כוח בע\"מ (2.4.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'השינוי אינו אפשרי, שכן הוא דורש הסכמה של 90% מבעלי המניות לפי התקנון, וכן הסכמה פה אחד לפי הסכם בעלי המניות.', true, 'תשובה זו נכונה. התקנון קובע רוב מיוחס של 90%, והסכם בעלי המניות (שכל בעלי המניות צד לו) קובע הסכמה פה אחד. יש לפעול לפי הדרישה המחמירה יותר, והרוב הקיים אינו מספיק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'השינוי אפשרי ברוב של 80%, שכן הסכם בעלי המניות אינו מחייב את החברה, אלא רק את בעלי המניות שחתמו עליו.', false, 'טענה זו שגויה. הסכם בעלי מניות שנחתם על ידי כל בעלי המניות יכול לחייב את החברה ואת בעלי המניות, במיוחד בחברה פרטית, ודרישותיו גוברות על רוב נמוך יותר בתקנון אם הוא מחמיר יותר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'התקנון גובר על הסכם בעלי המניות, ולכן השינוי אפשרי ברוב של 90% מבעלי המניות.', false, 'טענה זו שגויה. הסכם בעלי מניות שנחתם על ידי כל בעלי המניות יכול לחייב את החברה ובעלי מניותיה, ובמקרים מסוימים אף לגבור על הוראות התקנון, או לכל הפחות להוסיף עליהן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'השינוי אינו אפשרי, שכן לא ניתן לשנות הוראות תקנון הנוגעות למינוי דירקטורים.', false, 'טענה זו שגויה. ניתן לשנות הוראות תקנון הנוגעות למינוי דירקטורים, אך הדבר כפוף לדרישות הרוב הקבועות בתקנון ובהסכמים מחייבים אחרים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים לבעל מניות מקופח',
    4, 'חברת "הצלחה בע"מ" היא חברה פרטית. אסיפה כללית של החברה קיבלה החלטה לשנות את התקנון באופן שפוגע בזכויותיו של מיעוט בעלי המניות, ללא הגדלת חבות כספית. מיעוט בעלי המניות טוען לקיפוח. איזה סעד יכול בית המשפט להעניק למיעוט המקופח?', 'השאלה עוסקת בסעדים הניתנים לבעל מניות מיעוט המקופח על ידי החלטות האסיפה הכללית, בהתאם לסעיף 191 לחוק החברות, המעניק לבית המשפט סמכות רחבה להסרת הקיפוח.', 'סעיף 191 לחוק החברות קובע כי ''התנהל ענין מענייניה של חברה בדרך שיש בה משום קיפוח של בעלי המניות שלה, כולם או חלקם, או שיש חשש מהותי שיתנהל בדרך זו, רשאי בית המשפט, לפי בקשת בעל מניה, לתת הוראות הנראות לו לשם הסרתו של הקיפוח או מניעתו''. הסעיף מעניק לבית המשפט סמכות רחבה ביותר, הכוללת, בין היתר, הוראות לניהול ענייני החברה בעתיד, או הוראות לבעלי המניות בחברה לפיהן ירכשו הם או החברה מניות מבעל המניות המקופח. מטרת הסעיף היא להגן על ציפיותיהם הלגיטימיות של בעלי המניות, גם אם אין בהתנהגות המקפחת הפרה של זכות מוקנית במסמכי היסוד (רע"א 779/06 קיטאל החזקות ופיתוח בינלאומי בע"מ נ'' שאול ממן).',
    'הגבלת הסעדים האפשריים לביטול ההחלטה או לפיצוי כספי בלבד, מבלי להכיר בסמכותו הרחבה של בית המשפט להתערב במבנה החברה וניהולה.', '["קיפוח מיעוט", "סעיף 191 לחוק החברות", "סעדים", "התערבות בית המשפט", "רכישת מניות", "ציפיות לגיטימיות"]'::jsonb, '**עילת קיפוח מיעוט:** מתי קמה? ← כאשר ענייני החברה מתנהלים בדרך שיש בה משום קיפוח בעלי מניות (סעיף 191 לחוק החברות).
**סמכות בית המשפט:** מה כוללת? ← מתן כל הוראה הנראית לו להסרת הקיפוח או מניעתו (סעיף 191(א) לחוק החברות).
**דוגמאות לסעדים:** מהם? ← הוראות לניהול עתידי, רכישת מניות המקופח על ידי החברה או בעלי מניות אחרים.
**האם נדרשת הפרת זכות מוקנית?** ← לא, מספיקה פגיעה בציפיות הלגיטימיות (רע"א 779/06 קיטאל).', 'קיפוח מיעוט ← סמכות רחבה לבית המשפט (סעיף 191 לחוק החברות) ← להסרת הקיפוח בכל דרך נאותה.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 191", "רע\"א 779/06 קיטאל החזקות ופיתוח בינלאומי בע\"מ נ'' שאול ממן (28.8.2012)", "ת\"א (מחוזי חיפה) 4806-06-22 שמואל גוטמן נ'' מאור להב (8.12.2024)", "ת\"א (מחוזי י-ם) 15198-07-20 שמואל נסים כהן נ'' הכהן יהונתן פנחס (3.10.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט רשאי לבטל את החלטת האסיפה הכללית ולחייב את החברה להחזיר את המצב לקדמותו.', false, 'טענה זו שגויה. ביטול החלטה הוא סעד אפשרי, אך בית המשפט מוסמך להעניק מגוון רחב יותר של סעדים, כולל כאלה שאינם מבטלים את ההחלטה אלא מסירים את הקיפוח בדרכים אחרות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט רשאי לתת הוראות להסרת הקיפוח, לרבות הוראות לניהול ענייני החברה בעתיד, או הוראות לרכישת מניות המיעוט על ידי החברה או בעלי המניות האחרים.', true, 'תשובה זו נכונה. סעיף 191 לחוק החברות מקנה לבית המשפט סמכות רחבה להעניק סעדים שונים להסרת קיפוח, כולל אלה המפורטים בתשובה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט רשאי רק לפסוק פיצוי כספי למיעוט המקופח, אך אינו יכול להתערב בניהול החברה.', false, 'טענה זו שגויה. פיצוי כספי הוא אחד הסעדים האפשריים, אך סמכות בית המשפט רחבה יותר וכוללת התערבות בניהול החברה ובמבנה הבעלות כדי להסיר את הקיפוח.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט אינו יכול להתערב בהחלטות שהתקבלו כדין באסיפה הכללית, גם אם הן מקפחות.', false, 'טענה זו שגויה. סעיף 191 לחוק החברות מעניק לבית המשפט סמכות מפורשת להתערב בהחלטות מקפחות, גם אם הן התקבלו ברוב הנדרש.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 28, '2022-W-S-Q28';
END
$$;

-- ============================================================
-- Q29 — 2022-W-S-Q29 — chapter=corporate subtopic=piercing_veil
-- classifier_note: Limited liability + separate legal entity protections — creditor competition
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '74a80955-ce12-46ca-8c21-bf7214c3087b'::uuid;
  v_group_id uuid := '019ed2e4-116e-4dc3-9713-98f24aa3ce3e'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'ab59081c-2707-4802-a8c5-c631066e6863'::uuid;
  v_ang_1 uuid := 'd2774588-5837-42d8-bc6d-2284e9f90237'::uuid;
  v_ang_2 uuid := 'c5288e95-e6a7-45b2-88b6-d2a00ba02b04'::uuid;
  v_ang_3 uuid := 'da16c7bb-42a2-49cf-9e98-b055cfb6844d'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q29';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 29, '2022-W-S-Q29';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'piercing_veil' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'piercing_veil', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q29', v_chapter_id, v_subtopic_id, 'שניים מהמאפיינים של חברה בע"מ הם ישות משפטית נפרדת והגבלת אחריות. נושים של חברה בע"מ ונושים של בעלי החברה מתחרים ביניהם על נכסי החברה ונכסי בעלי החברה. באופן רגיל, על מי מגן כל אחד מהמאפיינים ומפני מי?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 29}'::jsonb, 'השאלה עוסקת בשני עקרונות יסוד בדיני חברות: הישות המשפטית הנפרדת והגבלת האחריות. היא בוחנת את תפקידם של עקרונות אלה בהגנה על אינטרסים שונים של נושים – נושי החברה ונושי בעלי המניות – ומדגישה את ההבחנה ביניהם.', 'עקרון הישות המשפטית הנפרדת, הקבוע בסעיף 4 לחוק החברות, קובע כי חברה היא אישיות משפטית עצמאית ונפרדת מבעלי מניותיה. משמעות הדבר היא שלחברה יש נכסים משלה וחובות משלה. נכסי החברה מיועדים לפירעון חובותיה בלבד, ונושי בעלי המניות אינם יכולים להיפרע מהם. בכך, הישות המשפטית הנפרדת מגינה על נושי החברה מפני נושי בעלי המניות. עקרון הגבלת האחריות, הקבוע בסעיף 35 לחוק החברות, קובע כי בעלי המניות אינם אחראים לחובות החברה מעבר לסכום שהתחייבו להשקיע בה. כלומר, נכסיהם האישיים של בעלי המניות מוגנים מפני נושי החברה. בכך, הגבלת האחריות מגינה על נושי בעלי המניות מפני נושי החברה.', 'הבלבול בין שני העקרונות והנחה שהם מגינים על אותם אינטרסים או באותו אופן. חשוב להבין שכל אחד מהם מגן על צד אחר במערכת היחסים המורכבת של החברה ובעלי עניין בה.',
    '["ישות משפטית נפרדת", "הגבלת אחריות", "חוק החברות", "נושי חברה", "נושי בעלי מניות", "סעיף 4 לחוק החברות", "סעיף 35 לחוק החברות"]'::jsonb, '**ישות משפטית נפרדת:** מהי? ← החברה היא סובייקט משפטי עצמאי (סעיף 4 לחוק החברות).
**הגבלת אחריות:** מהי? ← בעלי המניות אינם אחראים לחובות החברה מעבר להשקעתם (סעיף 35 לחוק החברות).
**הגנה של ישות נפרדת:** על מי? ← על נושי החברה (מפני נושי בעלי המניות).
**הגנה של הגבלת אחריות:** על מי? ← על נושי בעלי המניות (מפני נושי החברה).', 'ישות נפרדת ← נכסי חברה לנושיה. הגבלת אחריות ← נכסי בעלים לנושיהם.', '["חוק החברות, תשנ\"ט-1999, סעיפים 4, 35", "ע\"א 460/77 מורדוב נ'' בנק ירושלים בע\"מ, פ\"ד לב(1) 500 (1978)", "א'' חביב-סגל, דיני חברות (2004), עמ'' 101-103"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''piercing_veil'' | classifier_note: Limited liability + separate legal entity protections — creditor competition | source_review_note: השאלה עוסקת בדיני חברות מהותיים (ישות נפרדת, הגבלת אחריות). מופתה ל''סדר דין אזרחי'' ו''הליכים'' כקירוב הטוב ביותר מתוך הרשימה הסגורה, אך יש לשקול הוספת פרק ''דיני תאגידים'' או סיווג מתאים יותר.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הישות המשפטית הנפרדת מגינה על נושי החברה מפני נושי בעלי החברה, והגבלת האחריות מגינה על נושי בעלי החברה מפני נושי החברה.', true, 'תשובה זו נכונה. הישות המשפטית הנפרדת (סעיף 4 לחוק החברות) מבטיחה שנכסי החברה ישמשו לפירעון חובותיה בלבד, ובכך מגינה על נושי החברה מפני נושי בעלי המניות. הגבלת האחריות (סעיף 35 לחוק החברות) מגינה על בעלי המניות מפני חובות החברה, ובכך מגינה על נושי בעלי המניות מפני נושי החברה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הישות המשפטית הנפרדת מגינה על נושי בעלי החברה מפני נושי החברה, והגבלת האחריות מגינה על נושי החברה מפני נושי בעלי החברה.', false, 'טענה זו שגויה, שכן היא הופכת את תפקידי ההגנה של שני המאפיינים. הישות הנפרדת מגינה על נושי החברה, והגבלת האחריות מגינה על נושי בעלי המניות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'שני המאפיינים מגינים על נושי בעלי החברה מפני נושי החברה.', false, 'טענה זו שגויה. הישות המשפטית הנפרדת מגינה על נושי החברה, ולא על נושי בעלי המניות, מפני נושי החברה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'שני המאפיינים מגינים על נושי החברה מפני נושי בעלי החברה.', false, 'טענה זו שגויה. הגבלת האחריות מגינה על נושי בעלי המניות, ולא על נושי החברה, מפני נושי בעלי החברה.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'השלכות הרמת מסך ההתאגדות',
    1, 'חברת "כשלונות בע"מ" נקלעה לחובות עתק. בעלי המניות בחברה, ראובן ושמעון, ניהלו את החברה באופן רשלני וחסר אחריות, תוך ערבוב נכסים אישיים עם נכסי החברה. נושי החברה מבקשים להטיל אחריות אישית על ראובן ושמעון. מה הדין?', 'השאלה עוסקת בחריג לעקרונות הישות המשפטית הנפרדת והגבלת האחריות – הרמת מסך ההתאגדות. היא בוחנת את העילות להרמת מסך, ובפרט את עילת השימוש לרעה בעיקרון הישות הנפרדת, כפי שנקבעה בסעיף 6 לחוק החברות ובפסיקה.', 'סעיף 6(א) לחוק החברות קובע כי בית המשפט רשאי לייחס חוב של חברה לבעל מניה בה, אם מצא כי התקיים אחד מהתנאים המפורטים בסעיף. אחד התנאים המרכזיים הוא ''שימוש לרעה במסך ההתאגדות''. ערבוב נכסים אישיים עם נכסי החברה, התנהלות רשלנית וחסרת אחריות, ואי-הפרדה בין החברה לבעליה, נחשבים לשימוש לרעה במסך ההתאגדות, המצדיק את הרמתו והטלת אחריות אישית על בעלי המניות (ראו ע"א 10581/02 ישראל בן אבו נ'' דלתות חמדיה בע"מ). תכלית הרמת המסך היא למנוע ניצול לרעה של עקרונות היסוד של דיני החברות.',
    'הנחה שרק במקרים של מרמה מובהקת ניתן להרים מסך, או אי-הבנה של היקף עילת ''שימוש לרעה'' במסך ההתאגדות.', '["הרמת מסך ההתאגדות", "ישות משפטית נפרדת", "הגבלת אחריות", "שימוש לרעה במסך ההתאגדות", "סעיף 6 לחוק החברות", "אחריות אישית"]'::jsonb, '**עילות להרמת מסך:** מהן? ← שימוש לרעה במסך ההתאגדות (לרבות ערבוב נכסים), או הברחת נכסים (סעיף 6 לחוק החברות).
**האם הרמת מסך היא סעד שבשגרה?** ← לא, זהו סעד חריג שבית המשפט מפעיל בזהירות.
**האם נדרשת כוונת מרמה?** ← לא תמיד, שימוש לרעה יכול להתקיים גם ללא כוונת מרמה מובהקת.
**האם הרמת מסך מבטלת את הישות הנפרדת?** ← לא, היא רק מטילה אחריות אישית על בעלי המניות לחובות ספציפיים.', 'הרמת מסך ← חריג לישות נפרדת והגבלת אחריות ← עילות: שימוש לרעה/הברחה (סעיף 6 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6", "ע\"א 10581/02 ישראל בן אבו נ'' דלתות חמדיה בע\"מ, פ\"ד נח(2) 233 (2004)", "ע\"א 9916/02 בנק לאומי לישראל בע\"מ נ'' שטיינמץ, פ\"ד נח(2) 907 (2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בית המשפט ירים את מסך ההתאגדות ויטיל אחריות אישית על ראובן ושמעון, שכן התנהלותם מהווה שימוש לרעה בעיקרון הישות הנפרדת.', true, 'תשובה זו נכונה. ערבוב נכסים והתנהלות רשלנית וחסרת אחריות, במיוחד כאשר היא מגיעה לכדי שימוש לרעה במסך ההתאגדות, מהווים עילה להרמת מסך לפי סעיף 6(א)(1) לחוק החברות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט לא ירים את מסך ההתאגדות, שכן הגבלת האחריות היא עיקרון יסוד בדיני חברות שאין לסטות ממנו.', false, 'טענה זו שגויה. הגבלת האחריות היא עיקרון יסוד, אך אינה מוחלטת. חוק החברות קובע חריגים לעיקרון זה, כגון הרמת מסך ההתאגדות במקרים של שימוש לרעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט יטיל אחריות אישית על ראובן ושמעון רק אם יוכח שהם התכוונו לרמות את הנושים.', false, 'טענה זו שגויה. כוונת מרמה היא עילה אחת להרמת מסך, אך לא היחידה. שימוש לרעה בעיקרון הישות הנפרדת, גם ללא כוונת מרמה מובהקת, יכול להוות עילה להרמת מסך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ראובן ושמעון יהיו אחראים באופן אישי רק אם החברה היא חברת יחיד.', false, 'טענה זו שגויה. הרמת מסך אפשרית בכל חברה, ללא קשר למספר בעלי המניות, אם מתקיימות העילות הקבועות בחוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הבחנה בין ישות נפרדת להגבלת אחריות',
    2, 'מהו ההבדל המהותי בין עקרון הישות המשפטית הנפרדת לבין עקרון הגבלת האחריות בחברה?', 'השאלה בוחנת את ההבחנה המושגית בין שני עקרונות יסוד בדיני חברות: הישות המשפטית הנפרדת והגבלת האחריות. הבנה נכונה של הבדלים אלה חיונית להבנת מבנה החברה והגנותיה.', 'עקרון הישות המשפטית הנפרדת (סעיף 4 לחוק החברות) קובע כי החברה היא אישיות משפטית עצמאית ונפרדת מבעלי מניותיה. משמעות הדבר היא שלחברה יש זכויות וחובות משלה, נכסים משלה, והיא יכולה לתבוע ולהיתבע בשמה. עקרון הגבלת האחריות (סעיף 35 לחוק החברות) קובע כי בעלי המניות אינם אחראים לחובות החברה מעבר לסכום שהתחייבו להשקיע בה. כלומר, נכסיהם האישיים של בעלי המניות מוגנים מפני נושי החברה. שני העקרונות משלימים זה את זה אך אינם זהים: הישות הנפרדת מגדירה את החברה כסובייקט משפטי, והגבלת האחריות מגדירה את היקף חבותם של בעלי המניות.',
    'התייחסות לשני העקרונות כאל מושג אחד או בלבול בין תפקידי ההגנה שהם מעניקים.', '["ישות משפטית נפרדת", "הגבלת אחריות", "חוק החברות", "סעיף 4 לחוק החברות", "סעיף 35 לחוק החברות", "סובייקט משפטי"]'::jsonb, '**ישות משפטית נפרדת:** מהי? ← החברה היא אישיות משפטית עצמאית, בעלת זכויות וחובות משלה (סעיף 4 לחוק החברות).
**הגבלת אחריות:** מהי? ← בעלי המניות אינם אחראים לחובות החברה מעבר להשקעתם (סעיף 35 לחוק החברות).
**הגנה של ישות נפרדת:** על מי? ← על נושי החברה (מפני נושי בעלי המניות).
**הגנה של הגבלת אחריות:** על מי? ← על בעלי המניות (מפני נושי החברה).', 'ישות נפרדת ← החברה סובייקט עצמאי. הגבלת אחריות ← בעלי מניות לא אחראים לחובות החברה מעבר להשקעה.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 4, 35", "ע\"א 460/77 מורדוב נ'' בנק ירושלים בע\"מ, פ\"ד לב(1) 500 (1978)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ישות משפטית נפרדת קובעת שהחברה היא אישיות משפטית עצמאית, ואילו הגבלת אחריות קובעת שבעלי המניות אינם אחראים לחובות החברה מעבר להשקעתם.', true, 'תשובה זו נכונה. הישות הנפרדת מתייחסת לעצמאות החברה כסובייקט משפטי, בעוד הגבלת האחריות מתייחסת להיקף אחריותם של בעלי המניות לחובות החברה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'ישות משפטית נפרדת מגינה על בעלי המניות מפני חובות החברה, ואילו הגבלת אחריות מגינה על החברה מפני חובות בעלי המניות.', false, 'טענה זו שגויה. היא הופכת את תפקידי ההגנה של שני העקרונות. הישות הנפרדת מגינה על החברה (ועל נושיה), והגבלת האחריות מגינה על בעלי המניות (ועל נושיהם).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'שני העקרונות זהים ומתייחסים שניהם להגנה על בעלי המניות מפני חובות החברה.', false, 'טענה זו שגויה. שני העקרונות אינם זהים ומגנים על אינטרסים שונים, גם אם הם משלימים זה את זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'ישות משפטית נפרדת חלה רק על חברות ציבוריות, ואילו הגבלת אחריות חלה על כל סוגי החברות.', false, 'טענה זו שגויה. שני העקרונות חלים על כל סוגי החברות, ציבוריות ופרטיות כאחד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הגבלת אחריות בחברת יחיד',
    3, 'יוסי הוא בעל המניות היחיד בחברת "יוסי שירותים בע"מ". החברה נקלעה לחובות כבדים. נושי החברה מבקשים לתבוע את יוסי באופן אישי בטענה שאין היגיון בהגבלת אחריות כאשר מדובר בחברת יחיד, שכן אין הפרדה מהותית בין החברה לבעליה. מה הדין?', 'השאלה בוחנת את תחולת עקרונות הישות המשפטית הנפרדת והגבלת האחריות על חברת יחיד. היא מדגישה כי גם חברת יחיד נהנית מעקרונות אלה, וכי הרמת מסך אפשרית רק בהתקיים העילות הקבועות בחוק, ולא מעצם היותה חברת יחיד.', 'חוק החברות אינו מבחין בין חברה רב-בעלים לבין חברת יחיד לעניין עקרונות הישות המשפטית הנפרדת והגבלת האחריות. גם חברת יחיד נהנית מעקרונות אלה, ובעל המניות היחיד אינו אחראי באופן אישי לחובות החברה, אלא אם כן מתקיימת עילה להרמת מסך ההתאגדות לפי סעיף 6 לחוק החברות. העובדה שקיים בעל מניות יחיד אינה מהווה כשלעצמה עילה להרמת מסך, אלא יש לבחון את התנהלותו הספציפית ואם היא עולה כדי שימוש לרעה במסך ההתאגדות (ראו ע"א 460/77 מורדוב נ'' בנק ירושלים בע"מ).',
    'הנחה שחברת יחיד אינה נהנית מהגבלת אחריות אוטומטית, או שקל יותר להרים את המסך בחברת יחיד ללא הוכחת עילה מובהקת.', '["חברת יחיד", "ישות משפטית נפרדת", "הגבלת אחריות", "הרמת מסך ההתאגדות", "סעיף 6 לחוק החברות"]'::jsonb, '**האם חברת יחיד נהנית מישות נפרדת והגבלת אחריות?** ← כן, כמו כל חברה (סעיפים 4, 35 לחוק החברות).
**מתי ניתן להרים מסך בחברת יחיד?** ← רק אם מתקיימות העילות הקבועות בסעיף 6 לחוק החברות (למשל, שימוש לרעה).
**האם עצם היותה חברת יחיד מהווה עילה להרמת מסך?** ← לא.
**האם יש דרישות מיוחדות לחברת יחיד?** ← כן, למשל ציון ''חברת יחיד'' בשמה, אך אי-עמידה בכך אינה מבטלת את הגבלת האחריות.', 'חברת יחיד ← נהנית מישות נפרדת והגבלת אחריות ← הרמת מסך רק בעילות חוקיות (סעיף 6 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 4, 6, 35", "ע\"א 460/77 מורדוב נ'' בנק ירושלים בע\"מ, פ\"ד לב(1) 500 (1978)", "ע\"א 10581/02 ישראל בן אבו נ'' דלתות חמדיה בע\"מ, פ\"ד נח(2) 233 (2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'יוסי יהיה אחראי באופן אישי, שכן בחברת יחיד אין הפרדה מהותית בין החברה לבעליה, ולכן אין תחולה לעקרון הגבלת האחריות.', false, 'טענה זו שגויה. חברת יחיד נהנית מאותם עקרונות של ישות נפרדת והגבלת אחריות כמו כל חברה אחרת, אלא אם מתקיימות עילות להרמת מסך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יוסי לא יהיה אחראי באופן אישי, אלא אם כן יוכח כי התקיימה עילה להרמת מסך ההתאגדות, כגון שימוש לרעה בעיקרון הישות הנפרדת.', true, 'תשובה זו נכונה. חברת יחיד נהנית מעקרונות הישות הנפרדת והגבלת האחריות. רק אם יוכח שימוש לרעה במסך ההתאגדות, ניתן יהיה להרים את המסך ולהטיל אחריות אישית על יוסי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'יוסי יהיה אחראי באופן אישי רק אם החברה לא רשמה את היותה חברת יחיד ברשם החברות.', false, 'טענה זו שגויה. רישום חברת יחיד הוא דרישה פורמלית, אך אי-רישום כשלעצמו אינו מבטל את הגבלת האחריות או מהווה עילה להרמת מסך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'יוסי יהיה אחראי באופן אישי רק אם החברה לא ניהלה ספרי חשבונות כנדרש בחוק.', false, 'טענה זו שגויה. אי-ניהול ספרי חשבונות כנדרש יכול להוות אינדיקציה לשימוש לרעה במסך ההתאגדות, אך אינו עילה עצמאית ומוחלטת להרמת מסך, ואינו מבטל את הגבלת האחריות באופן אוטומטי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות אישית של דירקטורים',
    4, 'חברת "השקעות בטוחות בע"מ" נקלעה להפסדים כבדים עקב החלטה עסקית שגויה של הדירקטורית הראשית, שרה, שהתקבלה ברשלנות חמורה. נושי החברה מבקשים לתבוע את שרה באופן אישי בגין נזקי החברה. מה הדין?', 'השאלה עוסקת באחריותם האישית של דירקטורים בחברה, ובפרט בהבחנה בין אחריותם כלפי החברה לבין אחריותם כלפי צדדים שלישיים (כגון נושים). היא מדגישה את עקרון הישות הנפרדת ואת חובות הדירקטורים לפי חוק החברות.', 'דירקטורים חבים חובות אמון וזהירות כלפי החברה (סעיפים 252 ו-253 לחוק החברות). הפרת חובות אלה עלולה להטיל עליהם אחריות אישית, אך אחריות זו היא כלפי החברה, ולא כלפי נושיה באופן ישיר. נושי החברה אינם יכולים לתבוע דירקטורים באופן אישי בגין נזקים שנגרמו לחברה עקב רשלנותם, אלא אם כן מתקיימת עילה נפרדת לתביעה ישירה (כגון תרמית, מצג שווא, או עוולה נזיקית ישירה כלפי הנושה). במקרה הרגיל, התביעה בגין הפרת חובות הדירקטור תוגש על ידי החברה עצמה, או על ידי בעלי מניותיה בתביעה נגזרת (סעיף 194 לחוק החברות).',
    'הבלבול בין אחריות דירקטורים כלפי החברה לבין אחריותם כלפי צדדים שלישיים, והנחה שרשלנות דירקטורית מאפשרת לנושים לתבוע אותם ישירות.', '["אחריות דירקטורים", "חובת זהירות", "חובת אמונים", "ישות משפטית נפרדת", "תביעה נגזרת", "סעיפים 252, 253 לחוק החברות"]'::jsonb, '**חובות דירקטורים:** כלפי מי? ← כלפי החברה (חובת אמונים וזהירות, סעיפים 252, 253 לחוק החברות).
**האם נושי החברה יכולים לתבוע דירקטורים ישירות?** ← ככלל לא, אלא אם קיימת עילה נפרדת (למשל, עוולה נזיקית ישירה).
**מי תובע דירקטורים על הפרת חובותיהם?** ← החברה, או בעלי מניותיה בתביעה נגזרת (סעיף 194 לחוק החברות).
**האם רשלנות דירקטורית היא עילה להרמת מסך?** ← לא, הרמת מסך מתייחסת לאחריות בעלי מניות.', 'אחריות דירקטורים ← כלפי החברה (חובות אמונים וזהירות) ← נושים לא תובעים ישירות (למעט חריגים).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 194, 252, 253", "ע\"א 610/94 בוכבינדר נ'' כונס הנכסים הרשמי, פ\"ד נז(4) 289 (2003)", "ע\"א 10581/02 ישראל בן אבו נ'' דלתות חמדיה בע\"מ, פ\"ד נח(2) 233 (2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'שרה אינה אחראית באופן אישי לנושי החברה, שכן אחריותה היא כלפי החברה בלבד, והחברה היא ישות משפטית נפרדת.', true, 'תשובה זו נכונה. ככלל, דירקטורים חבים חובות אמון וזהירות כלפי החברה, ולא כלפי נושיה. תביעה בגין הפרת חובות אלה תוגש על ידי החברה (או בעלי מניותיה בתביעה נגזרת), ולא על ידי הנושים ישירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'שרה אחראית באופן אישי לנושי החברה, שכן רשלנות חמורה של דירקטור מהווה עילה להרמת מסך ההתאגדות.', false, 'טענה זו שגויה. רשלנות דירקטור אינה עילה להרמת מסך ההתאגדות, אלא עילה להפרת חובת זהירות כלפי החברה. הרמת מסך מתייחסת לאחריות בעלי מניות, לא דירקטורים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'שרה אחראית באופן אישי לנושי החברה, שכן היא הפרה את חובת האמון שלה כלפי הנושים.', false, 'טענה זו שגויה. חובת האמון של דירקטור היא כלפי החברה, ולא כלפי נושיה. במקרים חריגים, כאשר החברה חדלת פירעון, עשויה לקום חובה עקיפה כלפי הנושים, אך לא חובת אמון ישירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'שרה אחראית באופן אישי לנושי החברה רק אם החברה היא חברת יחיד.', false, 'טענה זו שגויה. אחריות דירקטור אינה תלויה במספר בעלי המניות בחברה, אלא בהפרת חובותיו כלפי החברה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 29, '2022-W-S-Q29';
END
$$;

-- ============================================================
-- Q30 — 2022-W-S-Q30 — chapter=contracts subtopic=general_part
-- classifier_note: Tender, terms settled with bidder, board rejection — pre-contractual bad faith (חוסר תום לב במו"מ)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'eef43dd3-7bd9-40d8-92dc-a809dadee4ff'::uuid;
  v_group_id uuid := 'f3847f1c-19ca-41b2-bc85-e2a145a202b8'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '1b2c851b-9011-439c-97ce-226539ec76d4'::uuid;
  v_ang_1 uuid := 'c9ba20bd-9fdd-4977-a051-5345c836dd86'::uuid;
  v_ang_2 uuid := '6fb02862-caa2-492e-82e2-d4409c082f51'::uuid;
  v_ang_3 uuid := 'c51cec05-c6d4-46a3-a439-cbd3eebb9065'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q30';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 30, '2022-W-S-Q30';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q30', v_chapter_id, v_subtopic_id, 'חברה הזמינה הצעות לביצוע עבודה במסגרת מכרז. החברה ניהלה משא ומתן עם המציעים, ולאחריו סיכמה את כל התנאים עם דוד. כל שנותר הוא הצורך באישורה של מועצת המנהלים של החברה. מועצת המנהלים של החברה החליטה שלא לאשר את העסקה, ובהמשך כרתה חוזה עם יהונתן, שהוא מציע שלא נטל חלק במכרז ולא עמד בתנאים האמורים בו. דוד מעוניין לתבוע בגין ההפרה, אך מתלבט בין פיצויי קיום לפיצויי הסתמכות. מהם פיצויים אלה?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 30}'::jsonb, 'השאלה עוסקת בהבחנה בין שני סוגי פיצויים מרכזיים בדיני חוזים: פיצויי קיום (פיצויים חיוביים) ופיצויי הסתמכות (פיצויים שליליים). הבחנה זו רלוונטית במיוחד בהקשר של הפרת חובת תום הלב במשא ומתן לקראת כריתת חוזה, כפי שנדונה בהרחבה בפסק הדין קל בנין.', 'סעיף 12(ב) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי צד שנהג שלא בתום לב במשא ומתן חייב בפיצויים בעד הנזק שנגרם לו עקב המשא ומתן או עקב כריתת החוזה. בפסיקה, ובעיקר בפסק הדין המכונן בעניין ע"א 6370/00 קל בנין בע"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע"מ, הובהרה ההבחנה בין פיצויי קיום לפיצויי הסתמכות. פיצויי קיום (המכונים גם ''פיצויים חיוביים'') נועדו להעמיד את הנפגע במצב שבו היה אילו קוים החוזה. הם מפצים על הרווח שנמנע מהנפגע כתוצאה מאי-קיום החוזה. פיצויי הסתמכות (המכונים גם ''פיצויים שליליים'') נועדו להחזיר את הנפגע למצב שבו היה אילו לא נכנס כלל למשא ומתן. הם מפצים על ההוצאות שהוציא הנפגע בהסתמך על המשא ומתן. בעוד שפיצויי הסתמכות הם הסעד הרגיל בגין הפרת חובת תום הלב במשא ומתן, הלכת קל בנין קבעה כי במקרים חריגים, כאשר המשא ומתן הגיע לשלב מתקדם מאוד ותנאי החוזה גובשו, ניתן לפסוק גם פיצויי קיום.', 'הבלבול בין פיצויי קיום לפיצויי הסתמכות, והנחה שסעיף 12(ב) לחוק החוזים (חלק כללי) מאפשר רק סוג אחד של פיצויים, מבלי להכיר בהבחנה ובהרחבה שנקבעה בפסיקה.',
    '["פיצויי קיום", "פיצויי הסתמכות", "פיצויים חיוביים", "פיצויים שליליים", "חוסר תום לב במשא ומתן", "סעיף 12 לחוק החוזים (חלק כללי)", "הלכת קל בנין"]'::jsonb, '**פיצויי קיום (חיוביים):** מהי מטרתם? ← להעמיד את הנפגע במצב שבו היה אילו קוים החוזה.
**פיצויי הסתמכות (שליליים):** מהי מטרתם? ← להחזיר את הנפגע למצב שבו היה אילו לא נכנס למו"מ כלל.
**הסעד הרגיל בגין חוסר תום לב במו"מ:** מהו? ← פיצויי הסתמכות.
**הסעד החריג בגין חוסר תום לב במו"מ:** מהו? ← פיצויי קיום, במקרים חריגים של מו"מ בשל (הלכת קל בנין).', 'פיצויי קיום ← רווח נמנע (חיוביים). פיצויי הסתמכות ← הוצאות מו"מ (שליליים).', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 10", "ע\"א 6370/00 קל בנין בע\"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע\"מ, נו(3) 289 (2002)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Tender, terms settled with bidder, board rejection — pre-contractual bad faith (חוסר תום לב במו"מ) | source_review_note: השאלה עוסקת בדיני חוזים מהותיים (פיצויים בגין חוסר תום לב במשא ומתן). מופתה ל''סדר דין אזרחי'' ו''הליכים'' כקירוב הטוב ביותר מתוך הרשימה הסגורה, אך יש לשקול הוספת פרק ''דיני חוזים'' או סיווג מתאים יותר.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'פיצויי קיום הם פיצויים בגין הרווח שנמנע מדוד מאי-קיומו של החוזה ומכונים גם "פיצויים חיוביים". פיצויי הסתמכות הם פיצוי על הנזק שנגרם לדוד בהוצאות ניהול המשא ומתן ומכונים גם "פיצויים שליליים".', true, 'תשובה זו נכונה. פיצויי קיום (פיצויים חיוביים) נועדו להעמיד את הנפגע במצב שבו היה אילו קוים החוזה, ואילו פיצויי הסתמכות (פיצויים שליליים) נועדו להחזיר את הנפגע למצב שבו היה אילו לא נכנס למשא ומתן כלל.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'פיצויי קיום הם פיצויים בגין הרווח שנמנע מדוד מאי-קיומו של החוזה ומכונים גם "פיצויים שליליים". פיצויי הסתמכות הם פיצוי על הנזק שנגרם לדוד בהוצאות ניהול המשא ומתן ומכונים גם "פיצויים חיוביים".', false, 'טענה זו שגויה. היא מבלבלת בין המונחים ''חיוביים'' ו''שליליים'' ומשייכת אותם באופן הפוך לסוגי הפיצויים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'פיצויי קיום הם פיצוי על הנזק שנגרם לדוד בהוצאות ניהול המשא ומתן ומכונים גם "פיצויים חיוביים". פיצויי הסתמכות הם פיצויים בגין הרווח שנמנע מדוד מאי-קיומו של החוזה ומכונים גם "פיצויים שליליים".', false, 'טענה זו שגויה. היא מבלבלת בין פיצויי קיום לפיצויי הסתמכות ומשייכת אותם באופן הפוך להגדרותיהם.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'פיצויי קיום הם פיצוי על הנזק שנגרם לדוד בהוצאות ניהול המשא ומתן ומכונים גם "פיצויים שליליים". פיצויי הסתמכות הם פיצויים בגין הרווח שנמנע מדוד מאי-קיומו של החוזה ומכונים גם "פיצויים חיוביים".', false, 'טענה זו שגויה. היא מבלבלת בין פיצויי קיום לפיצויי הסתמכות ובין המונחים ''חיוביים'' ו''שליליים'' ומשייכת אותם באופן הפוך להגדרותיהם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פיצויי קיום במשא ומתן שלא בתום לב',
    1, 'חברה ניהלה משא ומתן מתקדם עם דוד לקראת כריתת חוזה לביצוע עבודה. כל תנאי החוזה סוכמו, ונותר רק אישור פורמלי של מועצת המנהלים. החברה, בחוסר תום לב, החליטה שלא לאשר את העסקה וכרתה חוזה עם מציע אחר. דוד תובע פיצויי קיום. מה הסיכוי שיזכה לפיצויים אלה?', 'השאלה בוחנת את היקף הסעדים בגין הפרת חובת תום הלב במשא ומתן, ובפרט את האפשרות לפסוק פיצויי קיום (פיצויים חיוביים) במקרים חריגים, כפי שנקבע בהלכת קל בנין.', 'על פי סעיף 12(ב) לחוק החוזים (חלק כללי), צד שנהג שלא בתום לב במשא ומתן חייב בפיצויים. בעבר, הפרשנות המקובלת הייתה כי סעיף זה מאפשר רק פיצויי הסתמכות (פיצויים שליליים). אולם, בפסק הדין בעניין ע"א 6370/00 קל בנין בע"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע"מ, קבע בית המשפט העליון כי במקרים חריגים, כאשר המשא ומתן הגיע לשלב מתקדם מאוד, תנאי החוזה גובשו, ולולא חוסר תום הלב היה החוזה נכרת, ניתן לפסוק גם פיצויי קיום (פיצויים חיוביים). המקרה המתואר בשאלה עונה על תנאים אלה, ולכן סיכוייו של דוד לזכות בפיצויי קיום גבוהים.',
    'הנחה שגויה כי סעיף 12(ב) לחוק החוזים (חלק כללי) מאפשר תמיד ורק פיצויי הסתמכות, מבלי להכיר בחריג שנקבע בהלכת קל בנין.', '["פיצויי קיום", "פיצויי הסתמכות", "חוסר תום לב במשא ומתן", "סעיף 12 לחוק החוזים (חלק כללי)", "הלכת קל בנין", "שלב מתקדם במשא ומתן"]'::jsonb, '**פיצויי קיום במשא ומתן:** מתי ייפסקו? ← במקרים חריגים, כשהמו"מ בשל לכדי חוזה ותנאיו גובשו, ולולא חוסר תום הלב היה נכרת (קל בנין).
**האם סעיף 12(ב) מאפשר פיצויי קיום?** ← כן, בשינויים המחויבים, על אף לשונו המקורית (קל בנין).
**מהי תכלית פיצויי קיום?** ← להעמיד את הנפגע במצב שבו היה אילו קוים החוזה.
**האם בית המשפט כורת חוזה?** ← לא, הוא מסיר את המחסום שנוצר בחוסר תום לב (קל בנין).', 'פיצויי קיום במו"מ שלא בתום לב ← רק במקרים חריגים ← כשהמו"מ בשל לכדי חוזה (הלכת קל בנין).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(ב)", "ע\"א 6370/00 קל בנין בע\"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע\"מ, נו(3) 289 (2002)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'סיכוייו גבוהים, שכן המשא ומתן הגיע לשלב מתקדם ותנאי החוזה גובשו, ולולא חוסר תום הלב היה החוזה נכרת.', true, 'תשובה זו נכונה. על פי הלכת קל בנין, במקרים חריגים בהם המשא ומתן הגיע לשלב מתקדם ותנאי החוזה גובשו, ולולא חוסר תום הלב היה החוזה נכרת, ניתן לפסוק פיצויי קיום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'סיכוייו נמוכים, שכן סעיף 12(ב) לחוק החוזים (חלק כללי) מאפשר רק פיצויי הסתמכות בגין חוסר תום לב במשא ומתן.', false, 'טענה זו שגויה. הלכת קל בנין הרחיבה את הסעדים האפשריים מכוח סעיף 12(ב) וקבעה כי במקרים חריגים ניתן לפסוק גם פיצויי קיום.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'סיכוייו תלויים בשאלה אם החברה התכוונה לרמות את דוד, ולא רק פעלה בחוסר תום לב.', false, 'טענה זו שגויה. חוסר תום לב, גם ללא כוונת מרמה מובהקת, יכול להצדיק פיצויי קיום אם מתקיימים התנאים שנקבעו בהלכת קל בנין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'סיכוייו נמוכים, שכן בית המשפט אינו כורת חוזה עבור הצדדים, ולכן לא יפסוק פיצויים על חוזה שלא נכרת.', false, 'טענה זו שגויה. אמנם בית המשפט אינו כורת חוזה, אך במקרים חריגים הוא מסיר את המחסום שנוצר בחוסר תום לב ומעמיד את הצדדים במצב כאילו החוזה נכרת, ובכך מאפשר פיצויי קיום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני פסיקת פיצויי קיום במשא ומתן',
    2, 'מהם המבחנים העיקריים שקבע בית המשפט העליון בפסק דין קל בנין לפסיקת פיצויי קיום בגין חוסר תום לב במשא ומתן?', 'השאלה מתמקדת במבחנים הספציפיים שנקבעו בפסק הדין קל בנין, המהווה אבן דרך בדיני החוזים בישראל, לצורך פסיקת פיצויי קיום בגין חוסר תום לב בשלב הטרום-חוזי.', 'פסק הדין קל בנין קבע כי במקרים חריגים, סעיף 12(ב) לחוק החוזים (חלק כללי) מאפשר פסיקת פיצויי קיום. המבחנים העיקריים לכך הם: א. המשא ומתן הגיע לשלב מתקדם מאוד, כמעט עד כדי כריתת חוזה. ב. תנאי החוזה גובשו והיו ידועים לצדדים. ג. לולא חוסר תום הלב של הצד הפוגע, היה החוזה נכרת. במצב דברים זה, החזרת המצב לקדמותו משמעותה העמדת הצדדים במצב שבו היו נתונים לולא חוסר תום הלב, כלומר, כאילו החוזה נכרת וקוים.',
    'אי-הבחנה בין המבחנים הכלליים לפיצויי הסתמכות לבין המבחנים הספציפיים והמחמירים יותר לפיצויי קיום, כפי שנקבעו בהלכת קל בנין.', '["מבחני קל בנין", "פיצויי קיום", "חוסר תום לב במשא ומתן", "סעיף 12 לחוק החוזים (חלק כללי)", "שלב מתקדם במשא ומתן", "גמירת דעת"]'::jsonb, '**מבחני קל בנין לפיצויי קיום:** מהם? ← מו"מ בשל, תנאים גובשו, חוסר תום לב מנע כריתה.
**האם המבחנים מחמירים?** ← כן, פיצויי קיום הם סעד חריג במו"מ.
**האם נדרש חוזה כתוב?** ← לא, מספיק שתנאיו גובשו והיו ידועים.
**מהי מטרת המבחנים?** ← לאזן בין חופש המו"מ לחובת תום הלב.', 'מבחני קל בנין לפיצויי קיום ← מו"מ בשל + תנאים גובשו + חוסר תום לב מנע כריתה.',
    '["ע\"א 6370/00 קל בנין בע\"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע\"מ, נו(3) 289 (2002)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המשא ומתן הגיע לשלב מתקדם, תנאי החוזה גובשו, ולולא חוסר תום הלב היה החוזה נכרת.', true, 'תשובה זו נכונה. אלו הם המבחנים המרכזיים שנקבעו בהלכת קל בנין כתנאי לפסיקת פיצויי קיום בגין חוסר תום לב במשא ומתן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הצד הנפגע הוכיח נזק ממשי שנגרם לו עקב ניהול המשא ומתן, ללא קשר לשלב שבו היה המשא ומתן.', false, 'טענה זו מתארת את המבחן לפיצויי הסתמכות, ולא לפיצויי קיום, אשר דורשים קשר הדוק יותר לחוזה שלא נכרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הצד הפוגע פעל במרמה מובהקת, ולא רק בחוסר תום לב רגיל.', false, 'טענה זו שגויה. אמנם מרמה היא חוסר תום לב חמור, אך הלכת קל בנין אינה דורשת מרמה מובהקת כתנאי לפיצויי קיום, אלא שימוש לרעה בחוסר תום לב שמנע כריתת חוזה בשלביו הסופיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הצד הנפגע ויתר על הזדמנויות עסקיות אחרות בעקבות המשא ומתן עם הצד הפוגע.', false, 'טענה זו מתארת נזק עקיף שנגרם כתוצאה מהסתמכות, אך אינה המבחן העיקרי לפסיקת פיצויי קיום, אשר מתמקדים ברווח שנמנע מהחוזה הספציפי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סעדים נוספים בגין חוסר תום לב',
    3, 'חברה ניהלה משא ומתן עם דוד לקראת כריתת חוזה לביצוע עבודה. המשא ומתן הגיע לשלב מתקדם מאוד, כל תנאי החוזה סוכמו, ונותר רק אישור פורמלי של מועצת המנהלים. החברה, בחוסר תום לב קיצוני, החליטה שלא לאשר את העסקה וכרתה חוזה עם מציע אחר. האם דוד יכול לדרוש אכיפה של החוזה שלא נכרת?', 'השאלה בוחנת את הסעדים האפשריים בגין חוסר תום לב במשא ומתן, ובפרט את האפשרות הנדירה לפסוק אכיפה של חוזה שלא נכרת, כפי שנדון בפסק הדין קל בנין.', 'סעיף 12(ב) לחוק החוזים (חלק כללי) מדבר על פיצויים בגין חוסר תום לב במשא ומתן. עם זאת, בפסק הדין קל בנין, צוין כי במקרים חריגים ביותר, כאשר המשא ומתן הגיע לשלב סופי, ותנאי החוזה גובשו, ולולא חוסר תום הלב היה החוזה נכרת, ניתן להגיע למסקנה כי הסעד המתאים הוא אכיפת החוזה שעמדו הצדדים לכרות. בית המשפט העליון התייחס לרעיון של ''הפיכת משא ומתן לחוזה כפוי'' במצבים אלה, כדרך להסיר את המחסום שאחד הצדדים הטיל שלא בתום לב על שכלול החוזה. מדובר בסעד נדיר ביותר, השמור למקרים של חוסר תום לב קיצוני.',
    'הנחה שסעיף 12(ב) לחוק החוזים (חלק כללי) מוגבל לפיצויים כספיים בלבד, מבלי להכיר באפשרות התיאורטית והחריגה של אכיפה.', '["אכיפה", "סעדים בגין חוסר תום לב", "חוסר תום לב קיצוני", "סעיף 12 לחוק החוזים (חלק כללי)", "הלכת קל בנין", "חוזה כפוי"]'::jsonb, '**אכיפה במו"מ שלא בתום לב:** מתי אפשרית? ← במקרים חריגים וקיצוניים, כשהמו"מ בשל לכדי חוזה (קל בנין).
**האם זה סעד נפוץ?** ← לא, סעד נדיר ביותר.
**מהי תכלית האכיפה במקרה זה?** ← להסיר את המחסום שנוצר בחוסר תום לב ולאפשר את שכלול החוזה.

**האם סעיף 12(ב) מזכיר אכיפה?** ← לא במפורש, אך הפסיקה הרחיבה את הסעדים האפשריים.', 'אכיפה במו"מ שלא בתום לב ← סעד נדיר וחריג ביותר ← רק בחוסר תום לב קיצוני ובשלות חוזית (קל בנין).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(ב)", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970", "ע\"א 6370/00 קל בנין בע\"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע\"מ, נו(3) 289 (2002)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, במקרים חריגים ביותר, כאשר חוסר תום הלב קיצוני והמשא ומתן הבשיל לכדי חוזה, ניתן לפסוק אכיפה.', true, 'תשובה זו נכונה. הלכת קל בנין הכירה באפשרות, במקרים חריגים וקיצוניים, לפסוק אכיפה של החוזה שלא נכרת, כסעד בגין חוסר תום לב במשא ומתן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, סעיף 12(ב) לחוק החוזים (חלק כללי) מאפשר רק פיצויים כספיים, ולא אכיפה.', false, 'טענה זו שגויה. על אף שלשונו של סעיף 12(ב) מדברת על פיצויים, הפסיקה הרחיבה את הסעדים האפשריים, ובמקרים חריגים ביותר ניתן לפסוק גם אכיפה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, אכיפה אפשרית רק כאשר חוזה נכרת והופר, ולא בשלב הטרום-חוזי.', false, 'טענה זו שגויה. אמנם אכיפה היא סעד נפוץ בהפרת חוזה, אך הלכת קל בנין פתחה פתח לאכיפה גם בשלב הטרום-חוזי במקרים חריגים של חוסר תום לב קיצוני.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם דוד יוכיח שהחברה התחייבה במפורש לכרות עמו חוזה, ולא רק ניהלה משא ומתן.', false, 'טענה זו שגויה. הדרישה היא לחוסר תום לב קיצוני בשלב מתקדם של המשא ומתן, ולא בהכרח להתחייבות מפורשת לכרות חוזה, שכן אז היה מדובר בהפרת חוזה ולא בחוסר תום לב במו"מ.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'פיצויי הסתמכות במשא ומתן שלא בתום לב',
    4, 'חברה ניהלה משא ומתן עם דוד לקראת כריתת חוזה לביצוע עבודה. המשא ומתן היה בשלביו הראשונים, וטרם גובשו תנאים מהותיים. החברה, בחוסר תום לב, פרשה מהמשא ומתן. דוד תובע פיצויים בגין הוצאות שהוציא במהלך המשא ומתן. מה הסיכוי שיזכה לפיצויים אלה?', 'השאלה עוסקת בסעד הרגיל והעיקרי בגין הפרת חובת תום הלב במשא ומתן – פיצויי הסתמכות (פיצויים שליליים). היא מדגישה את תחולתם של פיצויים אלה גם בשלבים מוקדמים של המשא ומתן.', 'סעיף 12(ב) לחוק החוזים (חלק כללי) קובע כי צד שנהג שלא בתום לב במשא ומתן חייב בפיצויים בעד הנזק שנגרם לו עקב המשא ומתן. במצב הדברים הרגיל, כאשר המשא ומתן לא הגיע לשלב מתקדם ולא גובשו תנאי החוזה, הסעד המקובל הוא פיצויי הסתמכות (פיצויים שליליים). מטרתם של פיצויים אלה היא להעמיד את הנפגע במצב שבו היה אילו לא נכנס כלל למשא ומתן, כלומר, להחזיר לו את ההוצאות שהוציא בהסתמך על המשא ומתן. חובת תום הלב חלה מתחילת המשא ומתן, ולכן הפרתה, גם בשלבים מוקדמים, מצדיקה פיצויי הסתמכות.',
    'הבלבול בין פיצויי הסתמכות לפיצויי קיום, והנחה שפיצויי הסתמכות הם סעד חריג או שאינם ניתנים בשלבים מוקדמים של המשא ומתן.', '["פיצויי הסתמכות", "פיצויים שליליים", "חוסר תום לב במשא ומתן", "סעיף 12 לחוק החוזים (חלק כללי)", "שלב מוקדם במשא ומתן", "השבת המצב לקדמותו"]'::jsonb, '**פיצויי הסתמכות:** מהי מטרתם? ← להחזיר את הנפגע למצב שלפני המו"מ (פיצויים שליליים).
**מתי ייפסקו?** ← זהו הסעד הרגיל בגין חוסר תום לב במו"מ, במיוחד בשלבים מוקדמים.
**האם חוסר תום לב בשלב מוקדם מצדיק פיצוי?** ← כן, פיצויי הסתמכות.
**האם סעיף 12(ב) מאפשר פיצויי הסתמכות?** ← כן, זוהי הפרשנות המקורית והעיקרית של הסעיף.', 'פיצויי הסתמכות ← סעד רגיל בגין חוסר תום לב במו"מ ← מחזיר למצב שלפני המו"מ.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12(ב)", "ע\"א 6370/00 קל בנין בע\"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע\"מ, נו(3) 289 (2002)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'סיכוייו גבוהים, שכן פיצויי הסתמכות הם הסעד הרגיל בגין חוסר תום לב במשא ומתן, במיוחד בשלבים מוקדמים.', true, 'תשובה זו נכונה. פיצויי הסתמכות (פיצויים שליליים) הם הסעד העיקרי והרגיל בגין חוסר תום לב במשא ומתן, ומטרתם להחזיר את הנפגע למצב שבו היה אילו לא נכנס למשא ומתן כלל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'סיכוייו נמוכים, שכן חוסר תום לב בשלבים מוקדמים אינו מצדיק פיצויים כלשהם.', false, 'טענה זו שגויה. חובת תום הלב חלה מתחילת המשא ומתן, והפרתה, גם בשלבים מוקדמים, מצדיקה פיצויי הסתמכות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'סיכוייו תלויים בשאלה אם החברה התכוונה לרמות את דוד, ולא רק פרשה בחוסר תום לב.', false, 'טענה זו שגויה. חוסר תום לב, גם ללא כוונת מרמה, מצדיק פיצויי הסתמכות. כוונת מרמה עשויה להשפיע על היקף הפיצויים, אך אינה תנאי לקבלתם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'סיכוייו נמוכים, שכן פיצויי הסתמכות ניתנים רק במקרים חריגים, כאשר המשא ומתן הגיע לשלב מתקדם.', false, 'טענה זו שגויה. פיצויי הסתמכות הם הסעד הרגיל, ואילו פיצויי קיום הם הסעד החריג השמור למקרים של משא ומתן מתקדם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 30, '2022-W-S-Q30';
END
$$;

-- ============================================================
-- Q31 — 2022-W-S-Q31 — chapter=property subtopic=real_estate
-- classifier_note: Mortgaged land owner sold passage rights to neighbor; neither lien nor easement registered — competing transactions (עסקאות נוגדות)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '032df1c7-0e32-4e06-ba30-967a5d0f73ed'::uuid;
  v_group_id uuid := '47609129-07f0-4406-aabd-88efd0ee8a5b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '6addb432-c925-4387-9d6f-cc44c051a526'::uuid;
  v_ang_1 uuid := '515b0818-6fd3-4a9f-80fb-30913eb8e15c'::uuid;
  v_ang_2 uuid := '95e45e65-7886-4689-88fc-297f100dd496'::uuid;
  v_ang_3 uuid := '620e138f-cfb1-4583-9b8f-fe753538e809'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q31';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 31, '2022-W-S-Q31';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'real_estate' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'real_estate', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q31', v_chapter_id, v_subtopic_id, 'יעל התקשרה בחוזה הלוואה עם בנק. כבטוחה להלוואה שעבדה יעל לבנק מקרקעין בבעלותה. בהסכם בין יעל לבנק נקבע שאסור ליעל לערוך עסקאות במקרקעין המשועבדים ללא הסכמה מראש של הבנק. שנה לאחר מכן נעמה, שלה חלקה סמוכה לחלקתה של יעל, פנתה ליעל והתקשרה עימה בחוזה המקנה לה זכות מעבר דרך החלקה של יעל המשועבדת לבנק אל החלקה שלה (של נעמה). הן השעבוד הן זכות המעבר לא נרשמו בלשכת רישום המקרקעין. הבנק הגיש תביעה לביטול החוזה בין יעל לנעמה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 31}'::jsonb, 'השאלה עוסקת בתחרות זכויות במקרקעין, כאשר קיימת התחייבות קודמת (משכנתה עם הגבלה על עסקאות נוספות) והתחייבות מאוחרת (זיקת הנאה), וכל הזכויות טרם נרשמו. היא בוחנת את תחולת סעיף 9 לחוק המקרקעין על עסקאות נוגדות ואת מעמדן של התחייבויות שטרם נרשמו.', 'עסקה במקרקעין היא הקנייה של בעלות או של זכות אחרת במקרקעין, למעט הורשה (סעיף 6 לחוק המקרקעין). משכנתה וזיקת הנאה הן זכויות במקרקעין. עסקה במקרקעין טעונה רישום, וכל עוד לא נגמרה העסקה ברישום, רואים אותה כהתחייבות לעשות עסקה (סעיף 7(ב) לחוק המקרקעין). במקרה זה, הן המשכנתה והן זכות המעבר לא נרשמו, ולכן מדובר בתחרות בין שתי התחייבויות לעשות עסקה במקרקעין. על מצב זה חל סעיף 9 לחוק המקרקעין, הקובע כי זכותו של בעל העסקה הראשונה עדיפה, אלא אם כן השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה בעודו תם לב. במקרה הנדון, הבנק הוא בעל העסקה הראשונה בזמן. נעמה היא בעלת העסקה השנייה. מאחר שזכותה של נעמה לא נרשמה (אף לא הערת אזהרה), היא אינה עומדת בתנאי הרישום הנדרש כדי לגבור על הבנק. לכן, זכותו של הבנק עדיפה. החוזה בין יעל לנעמה תקף בין הצדדים לו, אך הבנק יכול לתבוע את ביטולו או למנוע את אכיפתו כלפיו, מכוח עדיפות זכותו. (ראו: ה"פ (מחוזי ת"א) 31457-01-18 שמעון אלגרסי נ'' עמודי חצר בע"מ).', 'הנחה שגויה כי עסקה שטרם נרשמה אינה יוצרת זכות כלשהי, או בלבול בין תוקף החוזה בין הצדדים לבין עדיפותו בתחרות מול צד שלישי.',
    '["עסקאות נוגדות", "חוק המקרקעין", "סעיף 9 לחוק המקרקעין", "התחייבות לעשות עסקה", "משכנתה", "זיקת הנאה", "רישום", "תום לב", "תמורה"]'::jsonb, '**מהי עסקה במקרקעין?** ← הקניית בעלות או זכות אחרת (סעיף 6 לחוק המקרקעין).
**מה קורה לעסקה שלא נרשמה?** ← רואים אותה כהתחייבות לעשות עסקה (סעיף 7(ב) לחוק המקרקעין).
**כלל העדיפות בעסקאות נוגדות:** מי גובר? ← הראשון בזמן, אלא אם השני פעל בתום לב, בתמורה, ורשם את העסקה (סעיף 9 לחוק המקרקעין).
**האם חוזה שנוגד עסקה קודמת בטל?** ← לא בהכרח, הוא תקף בין הצדדים לו, אך עשוי להיות בלתי אכיף כלפי בעל הזכות הקודמת.', 'עסקאות נוגדות במקרקעין (לא רשומות) ← הראשון בזמן גובר (סעיף 9 לחוק המקרקעין) ← החוזה השני תקף בין הצדדים אך כפוף לראשון.', '["חוק המקרקעין, תשכ\"ט-1969, סעיפים 6, 7(ב), 9", "ה\"פ (מחוזי ת\"א) 31457-01-18 שמעון אלגרסי נ'' עמודי חצר בע\"מ (24.10.2018)", "ע\"א 3099/10 ראיף אבו שקרה נ'' נכלה זכריא חדאד (09.10.2012)", "ת\"א (מחוזי מרכז) 21515-03-15 אימאן נאשף נ'' עומר עבד אלקאדר (20.12.2023)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''property'' subtopic=''real_estate'' | classifier_note: Mortgaged land owner sold passage rights to neighbor; neither lien nor easement registered — competing transactions (עסקאות נוגדות) | source_review_note: השאלה עוסקת בדיני קניין מהותיים (עסקאות נוגדות במקרקעין). מופתה ל''סדר דין אזרחי'' ו''הליכים'' כקירוב הטוב ביותר מתוך הרשימה הסגורה, אך יש לשקול הוספת פרק ''דיני קניין'' או סיווג מתאים יותר.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מאחר שמדובר בזכות מעבר בלבד זו אינה עסקה במקרקעין, ואין לבנק כל עילה לתבוע את ביטול העסקה בין יעל לנעמה.', false, 'טענה זו שגויה. זכות מעבר (זיקת הנאה) היא זכות במקרקעין, והתחייבות להקנותה היא עסקה במקרקעין, הכפופה לדיני העסקאות הנוגדות.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'העסקה בין נעמה ליעל נוגדת את העסקה בין יעל לבין הבנק. החוזה בין יעל לבין נעמה אינו חוקי ובטל מעיקרו. לבנק עילה לתבוע את ביטול העסקה בין יעל לנעמה.', false, 'טענה זו שגויה. החוזה בין יעל לנעמה אינו בטל מעיקרו, אלא תקף בין הצדדים לו, אך הוא כפוף לזכותו הקודמת של הבנק ועלול להיות בלתי אכיף כלפיו.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'העסקה בין נעמה ליעל נוגדת את העסקה בין יעל לבין הבנק. לבנק עילה לתבוע את ביטול העסקה בין יעל לנעמה. עם זאת, החוזה שנכרת בין יעל לנעמה הוא חוזה תקף כל עוד לא יקבע בית המשפט אחרת.', true, 'תשובה זו נכונה. התחייבות למשכנתה והתחייבות לזיקת הנאה הן עסקאות נוגדות. זכותו של הבנק (הראשון בזמן) עדיפה, שכן זכותה של נעמה לא נרשמה. החוזה בין יעל לנעמה תקף ביניהן, אך הבנק יכול למנוע את השלמתו או אכיפתו כלפיו.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מאחר שמדובר בהתחייבויות לביצוע עסקה בלבד שטרם נרשמו בלשכת רישום המקרקעין, אין לבנק עדיפות על נעמה.', false, 'טענה זו שגויה. גם אם מדובר בהתחייבויות בלבד, סעיף 9 לחוק המקרקעין קובע כלל עדיפות לראשון בזמן, אלא אם השני עמד בתנאים מצטברים, כולל רישום.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחרות זכויות בין משכנתה והערת אזהרה',
    1, 'ראובן התחייב למשכן את מקרקעין שבבעלותו לבנק, אך המשכנתה לא נרשמה. לאחר מכן, ראובן התחייב למכור את המקרקעין לשמעון, ושמעון רשם הערת אזהרה לטובתו. שמעון פעל בתום לב ובתמורה. מי גובר בתחרות הזכויות?', 'השאלה בוחנת את כלל העדיפות בעסקאות נוגדות במקרקעין, תוך התמקדות בדרישת הרישום של הקונה השני בזמן. היא מדגישה כי רישום הערת אזהרה אינו שקול לרישום הזכות הקניינית עצמה לצורך סעיף 9 לחוק המקרקעין.', 'סעיף 9 לחוק המקרקעין קובע כי זכותו של בעל העסקה הראשונה עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה בעודו בתום לב. דרישת הרישום בסעיף זה מתייחסת לרישום הזכות הקניינית עצמה (כגון בעלות או משכנתה) ולא לרישום הערת אזהרה בלבד. רישום הערת אזהרה, אף שהוא חשוב למניעת ''תאונה משפטית'', אינו מקנה עדיפות לרוכש השני על פני הראשון בזמן אם הראשון לא התרשל באי-רישום הערת אזהרה בעצמו, והשני לא השלים את הרישום הקנייני. במקרה זה, הבנק הוא הראשון בזמן, ושמעון, אף שרשם הערת אזהרה, לא רשם את זכות הבעלות עצמה, ולכן זכותו של הבנק גוברת. (ראו: אבי וינרוט, דיני קניין - פרקי יסוד (2024), עמ'' 203-204).',
    'הנחה שגויה כי רישום הערת אזהרה מספיק כדי שהקונה השני יגבר על הקונה הראשון בזמן, מבלי להבחין בין רישום הערת אזהרה לרישום הזכות הקניינית.', '["עסקאות נוגדות", "סעיף 9 לחוק המקרקעין", "רישום", "הערת אזהרה", "משכנתה", "תום לב", "תמורה"]'::jsonb, '**תנאי לעדיפות השני בזמן:** מהו הרישום הנדרש? ← רישום הזכות הקניינית עצמה, לא הערת אזהרה (וינרוט, עמ'' 203).
**האם הערת אזהרה מקנה עדיפות על הראשון בזמן?** ← לא, אלא אם הראשון התרשל באי-רישומה (הלכת גנז).
**מהי מטרת הערת אזהרה?** ← להגן על זכותו של הזכאי ולמנוע עסקאות סותרות (סעיף 127 לחוק המקרקעין).
**האם משכנתה לא רשומה היא זכות קניינית?** ← לא, היא התחייבות לעשות עסקה (סעיף 7(ב) לחוק המקרקעין).', 'תחרות משכנתה לא רשומה מול הערת אזהרה ← הבנק (ראשון בזמן) גובר ← הערת אזהרה אינה רישום קנייני.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיפים 7(ב), 9, 127", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | רישום", "ע\"א 2643/97 שלמה גנז נ'' בריטיש וקולוניאל חברה בע\"מ, נז(2) 385 (2003)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הבנק גובר, שכן זכותו קודמת בזמן, והערת אזהרה אינה נחשבת לרישום לצורך סעיף 9 לחוק המקרקעין.', true, 'תשובה זו נכונה. סעיף 9 לחוק המקרקעין מעניק עדיפות לראשון בזמן, אלא אם השני רשם את העסקה עצמה. רישום הערת אזהרה אינו מספיק כדי לגבור על הראשון בזמן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'שמעון גובר, שכן הוא רשם הערת אזהרה בתום לב ובתמורה, ובכך מנע ''תאונה משפטית''.', false, 'טענה זו שגויה. רישום הערת אזהרה מגן על שמעון מפני עסקאות מאוחרות יותר, אך אינו מקנה לו עדיפות על הבנק (הראשון בזמן) אם הבנק לא התרשל באי-רישום הערת אזהרה בעצמו, ובהיעדר רישום מלא של זכותו של שמעון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הבנק גובר, שכן משכנתה היא זכות קניינית חזקה יותר מהתחייבות למכור.', false, 'טענה זו שגויה. כל עוד המשכנתה לא נרשמה, היא בגדר התחייבות לעשות עסקה, ולא זכות קניינית מוגמרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בית המשפט יחלק את המקרקעין בין הבנק לשמעון באופן יחסי.', false, 'טענה זו שגויה. דיני עסקאות נוגדות קובעים עדיפות לאחד הצדדים, ולא חלוקה יחסית של הנכס.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי סעיף 9 לחוק המקרקעין',
    2, 'מהם התנאים המצטברים שבהם נדרש הקונה השני בזמן לעמוד, על מנת שזכותו תגבר על זכותו של הקונה הראשון בזמן, לפי סעיף 9 לחוק המקרקעין?', 'השאלה מתמקדת בתנאים המפורשים הקבועים בסעיף 9 לחוק המקרקעין, המאפשרים לקונה השני בזמן לגבור על הקונה הראשון בתחרות זכויות במקרקעין. היא בוחנת את הבנת המונחים ''תום לב'', ''תמורה'' ו''רישום''.', 'סעיף 9 לחוק המקרקעין קובע כלל לפיו בתחרות בין שתי עסקאות תקפות, יש להעדיף את העסקה הראשונה, אלא אם כן העסקה השנייה נעשתה בתמורה ובתום לב והסתיימה ברישום בעוד הקונה הינו תם-לב. שלושת התנאים הללו – תום לב, תמורה ורישום – הם מצטברים. תום הלב הנדרש מהקונה השני הוא תום לב סובייקטיבי (אי ידיעה על העסקה הראשונה) ואובייקטיבי (בדיקת המרשם ומצב ההחזקה). התמורה צריכה להיות ממשית. הרישום הנדרש הוא רישום הזכות הקניינית עצמה בפנקסי המקרקעין, ולא רישום הערת אזהרה בלבד. (ראו: אבי וינרוט, דיני קניין - פרקי יסוד (2024), עמ'' 10).',
    'הבלבול בין רישום הערת אזהרה לבין רישום הזכות הקניינית עצמה, או אי-הבנה של אופי התנאים המצטברים.', '["עסקאות נוגדות", "סעיף 9 לחוק המקרקעין", "תום לב", "תמורה", "רישום", "תנאים מצטברים", "זכות קניינית"]'::jsonb, '**תנאי עדיפות השני בזמן:** מהם? ← תום לב, תמורה, רישום (סעיף 9 לחוק המקרקעין).
**מהו ''רישום'' לצורך סעיף 9?** ← רישום הזכות הקניינית עצמה, לא הערת אזהרה (וינרוט, עמ'' 203).
**מהו ''תום לב'' הנדרש?** ← סובייקטיבי (אי ידיעה) ואובייקטיבי (בדיקה) (וינרוט, עמ'' 10).
**מהי ''תמורה'' הנדרשת?** ← תמורה ממשית, לא סמלית (וינרוט, עמ'' 10).', 'סעיף 9 לחוק המקרקעין ← שני בזמן גובר אם: תום לב + תמורה + רישום (מלא).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 9", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | עסקאות נוגדות", "ת\"א (מחוזי מרכז) 21515-03-15 אימאן נאשף נ'' עומר עבד אלקאדר (20.12.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הקונה השני פעל בתום לב, נתן תמורה, והעסקה לטובתו נרשמה בעודו תם לב.', true, 'תשובה זו נכונה. אלו הם שלושת התנאים המצטברים הקבועים בסיפא של סעיף 9 לחוק המקרקעין, המאפשרים לקונה השני בזמן לגבור על הקונה הראשון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הקונה השני פעל בתום לב, נתן תמורה, ורשם הערת אזהרה לטובתו.', false, 'טענה זו שגויה. רישום הערת אזהרה אינו מספיק; נדרש רישום מלא של הזכות הקניינית עצמה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הקונה השני פעל בתום לב, נתן תמורה, והחזיק במקרקעין.', false, 'טענה זו שגויה. תפיסת חזקה אינה שקולה לרישום הזכות הקניינית לצורך סעיף 9 לחוק המקרקעין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הקונה השני פעל בתום לב, והקונה הראשון התרשל באי-רישום הערת אזהרה.', false, 'טענה זו שגויה. התרשלות הקונה הראשון היא חריג לכלל העדיפות של הראשון בזמן (הלכת גנז), אך אינה אחד מהתנאים המצטברים הנדרשים מהקונה השני כדי לגבור על הראשון לפי לשון סעיף 9.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'השפעת אי-רישום הערת אזהרה על תום הלב',
    3, 'ראובן התחייב למכור מקרקעין לשמעון, אך שמעון לא רשם הערת אזהרה. לאחר מכן, ראובן התחייב למכור את אותם מקרקעין ללוי. לוי ידע על העסקה עם שמעון, אך בכל זאת התקשר בחוזה ושילם תמורה. לוי טוען כי שמעון התרשל באי-רישום הערת אזהרה, ולכן זכותו של לוי עדיפה. מה הדין?', 'השאלה בוחנת את הלכת גנז ואת חובת תום הלב של הקונה הראשון והשני בעסקאות נוגדות. היא מדגישה כי גם אם הקונה הראשון התרשל באי-רישום הערת אזהרה, הקונה השני לא יגבר אם פעל בחוסר תום לב, למשל, בידיעה על העסקה הקודמת.', 'על פי סעיף 9 לחוק המקרקעין, זכותו של בעל העסקה הראשונה עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה בעודו תם לב. הלכת גנז (ע"א 2643/97) קבעה כי אי-רישום הערת אזהרה על ידי הקונה הראשון, כאשר הדבר אפשרי, יכול להיחשב כחוסר תום לב מצידו, ובכך לאפשר לקונה השני לגבור עליו, גם אם לא השלים את הרישום. אולם, תנאי יסודי לעדיפות הקונה השני הוא תום ליבו. תום לב זה כולל הן תום לב סובייקטיבי (אי-ידיעה בפועל על העסקה הראשונה) והן תום לב אובייקטיבי (בדיקת המרשם ומצב ההחזקה). במקרה שלפנינו, לוי ידע על העסקה עם שמעון. ידיעה זו שוללת את תום ליבו של לוי, ולכן הוא לא יוכל לגבור על שמעון, גם אם שמעון התרשל באי-רישום הערת אזהרה. (ראו: ע"א 8609/15 עמאר מוסטפא נ'' המועצה המקומית דלית אל כרמל, פסקה 9).',
    'הנחה שגויה כי התרשלות הקונה הראשון באי-רישום הערת אזהרה מבטלת אוטומטית את זכותו, מבלי לבחון את תום ליבו של הקונה השני.', '["עסקאות נוגדות", "סעיף 9 לחוק המקרקעין", "הלכת גנז", "תום לב סובייקטיבי", "תום לב אובייקטיבי", "הערת אזהרה", "רשלנות"]'::jsonb, '**הלכת גנז:** מה קובעת? ← אי-רישום הערת אזהרה עשוי להיחשב חוסר תום לב של הראשון (ע"א 2643/97 גנז).
**תום לב של השני:** מה כולל? ← אי-ידיעה בפועל על העסקה הראשונה (ע"א 8609/15 מוסטפא).
**האם ידיעה על העסקה הראשונה שוללת תום לב?** ← כן, באופן מוחלט (ע"א 8609/15 מוסטפא).
**מי גובר אם השני ידע על הראשון?** ← הראשון בזמן, גם אם התרשל באי-רישום הערת אזהרה.', 'הלכת גנז ← הראשון התרשל באי-רישום ← השני ידע ← הראשון גובר (כי השני חסר תום לב).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 9", "ע\"א 2643/97 שלמה גנז נ'' בריטיש וקולוניאל חברה בע\"מ, נז(2) 385 (2003)", "ע\"א 8609/15 עמאר מוסטפא נ'' המועצה המקומית דלית אל כרמל (03.05.2017)", "ת\"א (מחוזי מרכז) 21515-03-15 אימאן נאשף נ'' עומר עבד אלקאדר (20.12.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'שמעון גובר, שכן ידיעתו של לוי על העסקה הראשונה שוללת את תום ליבו, גם אם שמעון התרשל באי-רישום הערת אזהרה.', true, 'תשובה זו נכונה. על פי הלכת גנז, חובת תום הלב חלה גם על הקונה השני. אם הקונה השני ידע על העסקה הראשונה, הוא אינו תם לב, ולכן לא יוכל לגבור על הקונה הראשון, גם אם הראשון התרשל באי-רישום הערת אזהרה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לוי גובר, שכן שמעון התרשל באי-רישום הערת אזהרה, ובכך גרם ל''תאונה המשפטית''.', false, 'טענה זו שגויה. התרשלות הקונה הראשון אינה מקנה עדיפות אוטומטית לקונה השני, אם הקונה השני עצמו פעל בחוסר תום לב (בידיעה על העסקה הראשונה).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'בית המשפט יחלק את המקרקעין בין שמעון ללוי באופן יחסי, בהתחשב ברשלנות של שמעון ובידיעה של לוי.', false, 'טענה זו שגויה. דיני עסקאות נוגדות קובעים עדיפות לאחד הצדדים, ולא חלוקה יחסית של הנכס.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'העסקה בין ראובן ללוי בטלה מעיקרה, שכן היא נכרתה בחוסר תום לב.', false, 'טענה זו שגויה. העסקה אינה בטלה מעיקרה, אלא בלתי אכיפה כלפי שמעון, והיא כפופה לזכותו הקודמת של שמעון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תחרות זכויות בזכויות אובליגטוריות במקרקעין',
    4, 'ראובן הוא בעל זכות חוזית בלבד לקבלת בעלות במקרקעין (זכותו אינה רשומה). ראובן התחייב למכור את זכותו החוזית זו לשמעון. לאחר מכן, ראובן התחייב למכור את אותה זכות חוזית ללוי. לוי פעל בתום לב, נתן תמורה, וקיבל את הזכות החוזית לידיו. מי גובר בתחרות הזכויות?', 'השאלה עוסקת בהבחנה בין עסקאות נוגדות במקרקעין (סעיף 9 לחוק המקרקעין) לבין עסקאות נוגדות בזכויות אובליגטוריות במקרקעין (סעיף 12 לחוק המיטלטלין). היא מדגישה את הקריטריון המבחין בין שני המצבים: האם המוכר התחייב להקנות בעלות במקרקעין או זכות חוזית בלבד.', 'כאשר אדם מתחייב למכור מקרקעין שאינם רשומים על שמו, יש לבחון את מהות ההתחייבות. אם המוכר התחייב להקנות לקונה את זכות הקניין במקרקעין (לאחר שהזכות תירשם על שמו של המוכר במרשם), אזי התחרות בין העסקאות הנוגדות תיבחן לפי סעיף 9 לחוק המקרקעין. לעומת זאת, אם המוכר התחייב להקנות לקונה את זכותו החוזית בלבד במקרקעין, אזי התחרות תיבחן לפי סעיף 12 לחוק המיטלטלין, החל בשינויים המחויבים גם על זכויות (סעיף 13 לחוק המיטלטלין). במקרה זה, ראובן התחייב למכור את ''זכותו החוזית'', ולכן חל סעיף 12 לחוק המיטלטלין. סעיף זה קובע כי זכותו של הראשון עדיפה, אך אם השני התקשר בעסקה וקיבל את המיטלטלין או את הזכות בתום לב ובתמורה, זכותו עדיפה. לוי עמד בתנאים אלה, ולכן זכותו גוברת. (ראו: אבי וינרוט, דיני קניין - פרקי יסוד (2024), עמ'' 76).',
    'הנחה שגויה כי כל עסקה הנוגעת למקרקעין כפופה אוטומטית לסעיף 9 לחוק המקרקעין, מבלי להבחין בין התחייבות להקנות בעלות במקרקעין לבין התחייבות להקנות זכות חוזית במקרקעין.', '["עסקאות נוגדות", "זכות חוזית במקרקעין", "חוק המיטלטלין", "סעיף 12 לחוק המיטלטלין", "סעיף 9 לחוק המקרקעין", "המחאת זכויות", "תום לב", "תמורה"]'::jsonb, '**התחייבות למכור מקרקעין (לא רשומים):** מה בוחנים? ← האם התחייבות להקנות בעלות או זכות חוזית (וינרוט, עמ'' 76).
**התחייבות להקנות בעלות:** איזה סעיף חל? ← סעיף 9 לחוק המקרקעין (וינרוט, עמ'' 76).
**התחייבות להקנות זכות חוזית:** איזה סעיף חל? ← סעיף 12 לחוק המיטלטלין (וינרוט, עמ'' 76).
**תנאי עדיפות השני בזמן (במיטלטלין/זכויות):** מהם? ← תום לב, תמורה, קבלת הזכות (סעיף 12 לחוק המיטלטלין).', 'תחרות זכויות אובליגטוריות במקרקעין ← סעיף 12 לחוק המיטלטלין ← השני גובר אם תם לב, תמורה, וקיבל את הזכות.',
    '["חוק המיטלטלין, תשל\"א-1971, סעיפים 12, 13", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | הקדמה", "ת\"א (מחוזי חי'') 13092-01-16 הודא אבו עישה נ'' סמיר פראן (04.08.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לוי גובר, שכן מדובר בתחרות זכויות חוזיות, והוא עמד בתנאי סעיף 12 לחוק המיטלטלין.', true, 'תשובה זו נכונה. כאשר המוכר מתחייב להקנות זכות חוזית במקרקעין (ולא את המקרקעין עצמם), התחרות נבחנת לפי סעיף 12 לחוק המיטלטלין, המעניק עדיפות לשני בזמן אם פעל בתום לב, בתמורה וקיבל את הזכות לידיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'שמעון גובר, שכן זכותו קודמת בזמן, וסעיף 9 לחוק המקרקעין חל גם על זכויות חוזיות.', false, 'טענה זו שגויה. סעיף 9 לחוק המקרקעין חל כאשר ההתחייבות היא להקנות בעלות במקרקעין. כאשר ההתחייבות היא להקנות זכות חוזית, חל סעיף 12 לחוק המיטלטלין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'שמעון גובר, שכן לוי לא רשם את זכותו בלשכת רישום המקרקעין.', false, 'טענה זו שגויה. כאשר מדובר בזכות חוזית, אין רישום בלשכת רישום המקרקעין, והתנאי המקביל בסעיף 12 לחוק המיטלטלין הוא קבלת הזכות לידי הקונה השני.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט יקבע כי שתי העסקאות בטלות, שכן ראובן לא היה בעל המקרקעין הרשום.', false, 'טענה זו שגויה. ניתן להתחייב למכור זכות חוזית במקרקעין גם אם המוכר אינו הבעלים הרשום, והעסקאות תקפות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 31, '2022-W-S-Q31';
END
$$;

-- ============================================================
-- Q33 — 2022-W-S-Q33 — chapter=contracts subtopic=construction_contract
-- classifier_note: Construction contract — landowner + contractor for apartment-building development
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'c2b35ca6-e94d-499f-8da8-5b8eac2bb041'::uuid;
  v_group_id uuid := '7995c519-c536-4921-8dd7-a362db56c4bd'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '62846116-caf3-47b5-8efa-4a1428fdc298'::uuid;
  v_ang_1 uuid := '0b9f5064-b712-47ff-9555-34267622ac02'::uuid;
  v_ang_2 uuid := '32be00ad-a28c-4eeb-8f52-93a5d39232c0'::uuid;
  v_ang_3 uuid := '14a6dc91-66bf-4d24-b93b-823ab081093c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q33';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 33, '2022-W-S-Q33';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'construction_contract' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'construction_contract', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q33', v_chapter_id, v_subtopic_id, 'בבעלות רוני מגרש מופשר לבניה שמצוי בעפולה. רוני פנה לקבלן בשם שון כדי שזה יקים על המגרש בניין מגורים ובתמורה ישולמו לו שירותי בנייה לפי מ"ר בנייה. שון התחייב במסגרת ההסכם שנחתם בין הצדדים להקים בתוך שנתיים בניין בן 6 קומות שכולל 24 דירות, כל אחת בגודל של 155 מ"ר. בחלוף שנה מאז שהחלה הבנייה הסתבר לרוני כי שון ידע כבר בשעה שחתם על ההסכם שלא ניתן להתחייב לדירות בגודל של 155 מ"ר וכי גודל הדירה המרבי המאושר עומד על 140 מ"ר, אלא ששון התחייב לכך בהסכם משום שתכנן לבנות את הבניין עם חריגות בנייה מתוך אמונה כי הדבר יתאפשר לנוכח קשריו בעיריית עפולה. רוני מחליט להגיש תביעה נגד שון לאכיפת התחייבותו המדויקת והמלאה על פי ההסכם ולחלופין לביטולו של ההסכם והשבת מלוא התמורה על פיו. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 33}'::jsonb, 'השאלה עוסקת בסוגיית חוזה פסול עקב אי-חוקיות, ובפרט בשאלת היקף הבטלות - האם החוזה בטל כולו או שניתן לבטלו באופן חלקי ולאכוף את יתר הוראותיו. היא בוחנת את יישום סעיפים 30 ו-31 לחוק החוזים (חלק כללי) יחד עם עקרון הבטלות החלקית.', 'סעיף 30 לחוק החוזים קובע כי חוזה שכריתתו, תוכנו או מטרתו בלתי חוקיים, בלתי מוסריים או סותרים את תקנת הציבור – בטל. סעיף 31 קובע כי הוראות סעיפים 19 ו-21 יחולו, בשינויים המחויבים, גם על בטלות לפי סעיף 30. סעיף 19 מאפשר ביטול חלקי של חוזה, אם עילת הביטול נוגעת לחלק הניתן להפרדה מיתר החוזה, ואין להניח שהצדדים היו מתקשרים בחוזה גם ללא החלק הפסול. במקרה זה, החלק הבלתי חוקי (גודל הדירות) ניתן להפרדה, ומהות העסקה (בניית בניין) נשמרת. לכן, בית המשפט יורה על ביטול חלקי של ההוראה הבלתי חוקית ואכיפת יתר החוזה, תוך התאמת התמורה.', 'טעות נפוצה היא להניח שכל אי-חוקיות בחוזה גוררת בטלות מוחלטת של החוזה כולו, מבלי לבחון את האפשרות לבטלות חלקית ואכיפת יתר החוזה. יש לזכור את עקרון "הפרדת העיקר מהטפל" ואת העדפת בתי המשפט לאכיפת חוזים ככל הניתן.',
    '["חוזה פסול", "אי-חוקיות בחוזה", "בטלות חלקית", "אכיפת חוזה", "השבה", "סעיף 30 לחוק החוזים", "סעיף 31 לחוק החוזים", "סעיף 19 לחוק החוזים"]'::jsonb, '**וריאציה 1 — חוזה עם תנאי בלתי חוקי:** ראובן ושמעון חתמו על חוזה למכירת דירה, כאשר אחד התנאים הוא ששמעון ישלם חלק מהתמורה "מתחת לשולחן" כדי להתחמק ממס. מה דין החוזה? ← החוזה פסול בשל אי-חוקיות (סעיף 30 לחוק החוזים). אם התנאי ניתן להפרדה ואין להניח שהצדדים לא היו מתקשרים בלעדיו, ייתכן ביטול חלקי (סעיף 19 לחוק החוזים).
**וריאציה 2 — חוזה למטרה בלתי חוקית:** לוי שכר דירה מיהודה במטרה להפעיל בה קזינו לא חוקי. יהודה ידע על המטרה. מה דין חוזה השכירות? ← החוזה פסול בשל מטרה בלתי חוקית (סעיף 30 לחוק החוזים) ובטל כולו, שכן המטרה היא לב ליבו של החוזה ואינה ניתנת להפרדה.
**וריאציה 3 — חוזה עם סעיף הסותר את תקנת הציבור:** חברה התקשרה עם עובד בחוזה עבודה שכלל סעיף גורף המונע ממנו לעבוד בתחום כלשהו במשך 10 שנים לאחר סיום העבודה. מה דין הסעיף? ← סעיף זה עלול להיחשב כסותר את תקנת הציבור (סעיף 30 לחוק החוזים) בשל פגיעה בחופש העיסוק. בית המשפט עשוי לבטלו חלקית או לצמצם את היקפו (סעיף 19 לחוק החוזים).

**וריאציה 4 — השבה בחוזה פסול:** ראובן שילם לשמעון מקדמה עבור שירות בלתי חוקי. השירות לא בוצע. האם ראובן זכאי להשבה? ← כן, סעיף 31 לחוק החוזים קובע כי הוראות סעיף 21 (השבה לאחר ביטול) יחולו גם על חוזה פסול, אלא אם בית המשפט ראה לנכון לפטור צד מהשבה, כולה או מקצתה, מטעמי צדק.', 'חוזה פסול עקב אי-חוקיות (סעיף 30) ← בטל. אם החלק הבלתי חוקי ניתן להפרדה ואינו פוגע במהות ← בטלות חלקית (סעיף 19) ואכיפת היתר, בתוספת השבה (סעיף 21).', '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 19, 21, 30, 31"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''construction_contract'' | classifier_note: Construction contract — landowner + contractor for apartment-building development | source_review_note: שאלת המקור עוסקת בדיני חוזים (דין מהותי) ואינה מתאימה לסיווג תחת ''סדר דין אזרחי'' או ''הליכים''. סווגה כך כברירת מחדל בהיעדר קטגוריה מתאימה לדיני חוזים ברשימה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט יורה רק על ביטול חלקי ההסכם הנגועים באי-חוקיות ואכיפת יתר ההסכם תוך השבת התמורה היחסית, שכן הבטלות החלקית לא פוגעת במהות החוזה (העסקה עצמה).', true, 'תשובה זו נכונה. במקרה של חוזה פסול שחלקו ניתן להפרדה, בית המשפט יעדיף ביטול חלקי ואכיפת יתר החוזה, תוך התאמת התמורה, בהתאם לסעיפים 19 ו-31 לחוק החוזים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט יורה על אכיפת ההסכם כלשונו ויחייב את שון למלא את חיוביו על פי ההסכם, קרי הקמת בניין בן 6 קומות שכולל 24 דירות, כל אחת בגודל של 155 מ"ר.', false, 'תשובה זו שגויה. בית המשפט לא יאכוף חיוב בלתי חוקי, שכן חוזה שכזה פסול לפי סעיף 30 לחוק החוזים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט יורה על ביטולו של ההסכם כולו היות שמדובר בחוזה פסול שמכיל חיובים בלתי חוקיים, כדוגמת בנייה בחריגה.', false, 'תשובה זו שגויה. אף שהחוזה מכיל חיובים בלתי חוקיים, אם החלק הבלתי חוקי ניתן להפרדה ואינו פוגע במהות העסקה, בית המשפט יעדיף ביטול חלקי ולא ביטול מלא של החוזה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט יורה על אכיפת ההסכם במלואו וכלשונו היות שהשינוי בגודל הדירות הוא בגדר זוטי דברים.', false, 'תשובה זו שגויה. חריגה של 15 מ"ר לדירה בבניין של 24 דירות אינה בגדר זוטי דברים, אלא הפרה מהותית של דיני התכנון והבנייה, והיא הופכת את החיוב לבלתי חוקי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חוזה פסול עם ביצוע חלקי',
    1, 'ראובן ושמעון התקשרו בחוזה לבניית תוספת לבית, כאשר חלק מהתוספת חורג מהיתר הבנייה. שמעון, הקבלן, בנה את החלק החוקי של התוספת ודרש תשלום. ראובן מסרב לשלם בטענה שהחוזה כולו פסול. מה הדין?', 'שאלה זו בוחנת את עקרון הבטלות החלקית של חוזה פסול, במיוחד כאשר חלקו החוקי של החוזה כבר בוצע. היא מדגישה את העדפת בתי המשפט לאכיפת החלקים הכשרים של חוזה, אם הם ניתנים להפרדה.', 'כאשר חוזה מכיל חלקים בלתי חוקיים וחלקים חוקיים, וניתן להפריד בין החלקים הבלתי חוקיים לבין החלקים החוקיים, בית המשפט נוטה לבטל רק את החלקים הבלתי חוקיים ולאכוף את יתר החוזה. זאת בהתאם לסעיפים 19 ו-31 לחוק החוזים (חלק כללי). במקרה זה, בניית החלק החוקי היא פעולה כשרה, ואין סיבה לבטל את כל החוזה ולמנוע מהקבלן תשלום עבור עבודתו החוקית, תוך התאמת התמורה.',
    'הנטייה לבטל את כל החוזה במקרה של אי-חוקיות, גם כאשר ניתן להפריד בין החלקים החוקיים לבלתי חוקיים, היא טעות נפוצה. יש לזכור את העדפת המחוקק והפסיקה לאכיפת חוזים ככל הניתן.', '["חוזה פסול", "בטלות חלקית", "אכיפה חלקית", "השבה", "סעיף 19 לחוק החוזים", "סעיף 31 לחוק החוזים"]'::jsonb, '**וריאציה 1 — חוזה עם תנאי בלתי חוקי שבוצע חלקית:** ראובן ושמעון חתמו על חוזה לבניית גדר, כאשר חלק מהגדר חורג מקו הבניין המותר. שמעון בנה את החלק החוקי. האם ראובן חייב לשלם? ← כן, עבור החלק החוקי, בטלות חלקית (סעיפים 19, 31 לחוק החוזים).
**וריאציה 2 — חוזה למטרה בלתי חוקית שבוצע חלקית:** לוי שכר דירה מיהודה במטרה להפעיל בה קזינו. יהודה ידע. לוי שילם חודש שכירות והחל לשפץ. האם יהודה זכאי לתשלום? ← לא, החוזה בטל כולו בשל מטרה בלתי חוקית (סעיף 30 לחוק החוזים), ואין מקום לאכיפה חלקית.
**וריאציה 3 — חוזה עם סעיף הסותר את תקנת הציבור שבוצע:** חברה התקשרה עם עובד בחוזה עבודה שכלל סעיף הגבלת עיסוק דרקוני. העובד עבד שנה ופוטר. האם סעיף הגבלת העיסוק תקף? ← לא, בית המשפט יבטל או יצמצם את הסעיף (סעיפים 19, 30 לחוק החוזים) בשל סתירה לתקנת הציבור.
**וריאציה 4 — השבה בחוזה פסול שבוצע חלקית:** ראובן שילם לשמעון מקדמה עבור שירות בלתי חוקי. השירות בוצע חלקית. האם ראובן זכאי להשבה? ← כן, סעיף 31 לחוק החוזים קובע תחולת סעיף 21 (השבה), אך בית המשפט רשאי לפטור מהשבה מטעמי צדק.', 'חוזה פסול שבוצע חלקית ← אם החלק החוקי ניתן להפרדה ואינו פוגע במהות ← אכיפה חלקית ותשלום יחסי (סעיפים 19, 31 לחוק החוזים).',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 19, 30, 31"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בית המשפט יורה על ביטול החוזה כולו, ושמעון לא יהיה זכאי לתשלום כלשהו.', false, 'שגוי. במקרה של בטלות חלקית, הצד שביצע את החלק החוקי זכאי לתמורה עבורו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט יורה על אכיפת החוזה במלואו, ושמעון יהיה זכאי לתשלום מלא.', false, 'שגוי. לא ניתן לאכוף חלק בלתי חוקי בחוזה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט יורה על ביטול החלק הבלתי חוקי בלבד, ויחייב את ראובן לשלם לשמעון עבור החלק החוקי שבוצע, תוך התאמת התמורה.', true, 'נכון. החלק הבלתי חוקי ניתן להפרדה, ובית המשפט יעדיף בטלות חלקית ואכיפת החלק החוקי, תוך התאמת התמורה, בהתאם לסעיפים 19 ו-31 לחוק החוזים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בית המשפט יורה על השבה הדדית של מה שניתן, אך לא יאכוף את החוזה.', false, 'שגוי. השבה הדדית היא סעד אפשרי, אך במקרה זה, כאשר החלק החוקי בוצע, יש מקום לאכיפה חלקית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני בטלות חלקית של חוזה פסול',
    2, 'מהם התנאים המצטברים שבית המשפט בוחן כדי להורות על בטלות חלקית של חוזה פסול, במקום ביטולו המלא?', 'שאלה זו מתמקדת במבחנים המשפטיים הקבועים בחוק להחלת בטלות חלקית על חוזה פסול. היא בוחנת את הבנת התנאים המצטברים הנדרשים כדי שבית המשפט יבחר בפתרון של בטלות חלקית על פני ביטול מלא.', 'סעיף 31 לחוק החוזים (חלק כללי) קובע כי הוראות סעיפים 19 ו-21 יחולו, בשינויים המחויבים, גם על בטלות לפי סעיף 30. סעיף 19 קובע שני תנאים מצטברים לבטלות חלקית: (1) עילת הביטול נוגעת לחלק הניתן להפרדה מיתר החוזה; ו-(2) אין להניח שהצדדים היו מתקשרים בחוזה גם ללא החלק הפסול. רק אם שני התנאים מתקיימים, בית המשפט רשאי להורות על ביטול חלקי.',
    'הבלבול בין התנאים לבטלות חלקית לבין שיקולי צדק או מהותיות החלק הפסול. יש לזכור את שני המבחנים המפורשים בסעיף 19 לחוק החוזים.', '["בטלות חלקית", "חוזה פסול", "הפרדת חלקים", "אומד דעת הצדדים", "סעיף 19 לחוק החוזים", "סעיף 31 לחוק החוזים"]'::jsonb, '**וריאציה 1 — חוזה עם סעיף בלתי חוקי שולי:** חוזה מכר דירה כלל סעיף לפיו המוכר יסייע לקונה להעלים מס. האם ניתן לבטל רק את הסעיף? ← כן, אם הסעיף ניתן להפרדה ואין להניח שהצדדים לא היו מתקשרים בלעדיו (סעיף 19 לחוק החוזים).
**וריאציה 2 — חוזה עם סעיף בלתי חוקי מהותי:** חוזה למכירת סמים כלל סעיף על אופן התשלום. האם ניתן לבטל רק את סעיף התשלום? ← לא, החוזה כולו פסול, שכן המטרה בלתי חוקית ואינה ניתנת להפרדה (סעיף 30 לחוק החוזים).
**וריאציה 3 — מבחן ההפרדה:** מהו המבחן לקביעה אם חלק בחוזה ניתן להפרדה? ← המבחן הוא אם ניתן להוציא את החלק הפסול מבלי לפגוע במהות העסקה הכוללת ובמבנה החוזי (סעיף 19 לחוק החוזים).
**וריאציה 4 — מבחן אומד דעת הצדדים:** כיצד בוחנים אם הצדדים היו מתקשרים בחוזה גם ללא החלק הפסול? ← בוחנים את כוונתם הסובייקטיבית והאובייקטיבית של הצדדים בעת כריתת החוזה (סעיף 19 לחוק החוזים).', 'בטלות חלקית של חוזה פסול (סעיף 31) ← רק אם החלק הפסול ניתן להפרדה + אין להניח שהצדדים לא היו מתקשרים בלעדיו (סעיף 19).',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 19, 30, 31"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'החלק הפסול ניתן להפרדה מיתר החוזה, ואין להניח שהצדדים לא היו מתקשרים בחוזה ללא החלק הפסול.', true, 'תשובה זו נכונה. אלו הם שני התנאים המצטברים הקבועים בסעיף 19 לחוק החוזים, החלים גם על חוזה פסול מכוח סעיף 31.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'החלק הפסול אינו מהותי לחוזה, וביטולו לא יגרום נזק לצד הנפגע.', false, 'שגוי. המבחן אינו נזק לצד הנפגע, אלא אם הצדדים היו מתקשרים בחוזה גם ללא החלק הפסול.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הצדדים הסכימו מראש על בטלות חלקית במקרה של אי-חוקיות, וביטול מלא יפגע באינטרס הציבורי.', false, 'שגוי. הסכמה מראש אינה תנאי לבטלות חלקית, ופגיעה באינטרס הציבורי היא שיקול כללי אך לא תנאי מצטבר לבטלות חלקית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'החלק הפסול נוגע לעניין טכני בלבד, וניתן לתקנו בקלות ללא שינוי מהותי בחוזה.', false, 'שגוי. המבחן אינו טכני או קלות תיקון, אלא יכולת ההפרדה וההנחה לגבי רצון הצדדים המקורי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'השבה בחוזה פסול שבוצע',
    3, 'ראובן שילם לשמעון 100,000 ש"ח עבור שירותי תיווך במקרקעין, כאשר שמעון אינו בעל רישיון תיווך כנדרש בחוק. שמעון ביצע את שירותי התיווך בהצלחה, אך כעת ראובן דורש את כספו בחזרה בטענה שהחוזה פסול. מה הדין לעניין ההשבה?', 'שאלה זו עוסקת בסוגיית ההשבה בחוזה פסול שבוצע, תוך התמקדות בסמכות בית המשפט לסטות מחובת ההשבה המלאה מטעמי צדק. היא בוחנת את יישום סעיף 31 לחוק החוזים ואת שיקולי הצדק הרלוונטיים.', 'סעיף 31 לחוק החוזים (חלק כללי) קובע כי הוראות סעיף 21 יחולו, בשינויים המחויבים, גם על בטלות לפי סעיף 30. סעיף 21 קובע חובת השבה הדדית לאחר ביטול חוזה. אולם, סעיף 31 מוסיף כי במקרה של חוזה פסול, רשאי בית המשפט, אם ראה שמן הצדק לעשות כן, לפטור צד מחובת השבה, כולה או מקצתה, ובמידה שצד אחד קיים את חיובו לפי החוזה, לחייב את הצד השני בקיום התמורה שכנגד, כולה או מקצתה. במקרה זה, שמעון ביצע את השירות, ובית המשפט ישקול שיקולי צדק.',
    'ההנחה כי בחוזה פסול תמיד תהיה השבה מלאה, מבלי להתחשב בסמכות בית המשפט לפטור מהשבה מטעמי צדק, במיוחד כאשר צד אחד קיים את חיובו.', '["חוזה פסול", "השבה", "שיקולי צדק", "חוק המתווכים במקרקעין", "סעיף 21 לחוק החוזים", "סעיף 31 לחוק החוזים"]'::jsonb, '**וריאציה 1 — חוזה פסול שבוצע במלואו:** ראובן שילם לשמעון עבור שירותי ייעוץ מס בלתי חוקיים. שמעון ביצע את הייעוץ. האם ראובן זכאי להשבה? ← בית המשפט רשאי לפטור את שמעון מהשבה, כולה או מקצתה, מטעמי צדק, או לחייב את ראובן בתשלום שווי השירות (סעיף 31 לחוק החוזים).
**וריאציה 2 — חוזה פסול שלא בוצע:** ראובן שילם לשמעון מקדמה עבור שירות בלתי חוקי. השירות לא בוצע. האם ראובן זכאי להשבה? ← כן, ככלל, קמה חובת השבה הדדית (סעיפים 21, 31 לחוק החוזים).
**וריאציה 3 — שיקולי צדק בהשבה:** מהם השיקולים שבית המשפט יביא בחשבון בפטור מהשבה בחוזה פסול? ← בין היתר: מידת האשמה של כל צד, מידת הביצוע של החוזה, חומרת אי-החוקיות, והאם הפטור יגרום עושר ולא במשפט (פס"ד סולימני נ'' כץ).
**וריאציה 4 — תשלום שווי שירות:** האם בית המשפט יכול לחייב צד לשלם שווי שירות שקיבל בחוזה פסול? ← כן, סעיף 31 לחוק החוזים מאפשר זאת, אם ראה שמן הצדק לעשות כן, ובמידה שצד אחד קיים את חיובו.', 'השבה בחוזה פסול (סעיף 31) ← ככלל השבה הדדית (סעיף 21) ← אך בית המשפט רשאי לפטור מהשבה או לחייב בתשלום שווי שירות מטעמי צדק.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 21, 30, 31", "ע\"א 666/87 סולימני נ'' כץ, פ\"ד מג(4) 705"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'ראובן זכאי להשבה מלאה של הסכום ששילם, ללא קשר לביצוע השירות, שכן החוזה בטל מעיקרו.', false, 'שגוי. אף שהחוזה בטל, בית המשפט רשאי לשקול שיקולי צדק ולפטור מהשבה מלאה או חלקית, במיוחד כאשר השירות בוצע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'שמעון זכאי לשמור את הכסף שקיבל, שכן הוא ביצע את השירות בהצלחה, ואין מקום להשבה.', false, 'שגוי. החוזה פסול, ולכן ככלל קמה חובת השבה. עם זאת, בית המשפט יכול לפטור מהשבה מטעמי צדק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'בית המשפט יורה על השבה הדדית, אך רשאי, מטעמי צדק, לפטור את שמעון מחובת השבה, כולה או מקצתה, או לחייב את ראובן בתשלום שווי השירות שקיבל.', true, 'נכון. סעיף 31 לחוק החוזים מפנה לסעיף 21, המורה על השבה הדדית, אך מסמיך את בית המשפט לפטור מהשבה מטעמי צדק, או לחייב בתשלום שווי שירות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'החוזה אינו פסול, אלא ניתן לביטול בלבד, ולכן ראובן זכאי להשבה רק אם יוכיח נזק.', false, 'שגוי. חוזה תיווך ללא רישיון הוא חוזה פסול בשל אי-חוקיות, ולא רק ניתן לביטול. הזכות להשבה אינה תלויה בהוכחת נזק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים נוספים בחוזה פסול',
    4, 'בנוסף לסעדי הביטול וההשבה, אילו סעדים נוספים עשוי בית המשפט להעניק לצדדים לחוזה פסול?', 'שאלה זו מרחיבה את הדיון מעבר לביטול והשבה, ובוחנת את מגוון הסעדים שבית המשפט רשאי להעניק לצדדים לחוזה פסול, תוך דגש על שיקולי צדק והגמישות הנתונה לבית המשפט מכוח סעיף 31 לחוק החוזים.', 'סעיף 31 לחוק החוזים (חלק כללי) מעניק לבית המשפט סמכות רחבה להסדיר את היחסים בין הצדדים לחוזה פסול. בנוסף להשבה הדדית (מכוח סעיף 21), בית המשפט רשאי, מטעמי צדק, לפטור צד מחובת השבה, כולה או מקצתה. יתרה מכך, אם צד אחד קיים את חיובו לפי החוזה, רשאי בית המשפט לחייב את הצד השני בקיום התמורה שכנגד, כולה או מקצתה. סמכות זו מאפשרת לבית המשפט לאכוף למעשה חלקים מהחוזה, או לחייב בתשלום שווי שירות/נכס שניתן, גם בחוזה פסול, כדי למנוע עושר ולא במשפט.',
    'ההנחה שחוזה פסול אינו יכול להוליד כל סעד למעט ביטול והשבה. יש לזכור את הגמישות שמעניק סעיף 31 לבית המשפט, המאפשרת לו להעניק סעדים נוספים מטעמי צדק.', '["חוזה פסול", "סעדים בחוזה פסול", "אכיפה חלקית", "חיוב בתמורה", "שיקולי צדק", "עושר ולא במשפט", "סעיף 31 לחוק החוזים"]'::jsonb, '**וריאציה 1 — חוזה פסול עם ביצוע מלא:** ראובן שילם לשמעון עבור שירותי בנייה בלתי חוקיים, ושמעון ביצע את כל העבודה. האם בית המשפט יכול לחייב את ראובן לשלם את מלוא התמורה? ← כן, מטעמי צדק, בית המשפט רשאי לחייב את ראובן בקיום התמורה שכנגד, כולה או מקצתה (סעיף 31 לחוק החוזים).
**וריאציה 2 — חוזה פסול עם אשמה הדדית:** ראובן ושמעון התקשרו בחוזה פסול, ושניהם ידעו על אי-החוקיות. האם בית המשפט יאכוף את החוזה? ← ככלל לא יאכוף, אך רשאי להורות על השבה או חיוב בתמורה מטעמי צדק, תוך התחשבות במידת האשמה של כל צד (סעיף 31 לחוק החוזים).
**וריאציה 3 — מניעת עושר ולא במשפט:** כיצד סעיף 31 מונע עושר ולא במשפט? ← הוא מאפשר לבית המשפט לחייב צד שקיבל תמורה בחוזה פסול לשלם עבורה, גם אם החוזה בטל, ובכך למנוע ממנו להתעשר על חשבון הצד השני (סעיף 31 לחוק החוזים).
**וריאציה 4 — סעדים בחוזה פסול לעומת חוזה שהופר:** מה ההבדל העיקרי בסעדים בין חוזה פסול לחוזה שהופר? ← בחוזה שהופר ניתן לתבוע אכיפה ופיצויים (חוק החוזים (תרופות)), בעוד שבחוזה פסול הסעדים העיקריים הם בטלות והשבה, עם גמישות לבית המשפט להורות על אכיפה חלקית או חיוב בתמורה מטעמי צדק (סעיף 31 לחוק החוזים).', 'סעדים בחוזה פסול (סעיף 31) ← בטלות והשבה (סעיף 21) + סמכות בית המשפט לפטור מהשבה או לחייב בתמורה שכנגד מטעמי צדק.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 21, 30, 31"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'פיצויים בגין הפרת חוזה, ככל חוזה תקף אחר.', false, 'שגוי. חוזה פסול בטל מעיקרו, ולכן לא ניתן לתבוע פיצויים בגין הפרתו כחוזה תקף.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'אכיפה חלקית של החוזה, או חיוב צד לקיים את התמורה שכנגד, כולה או מקצתה, מטעמי צדק.', true, 'נכון. סעיף 31 לחוק החוזים מאפשר לבית המשפט, מטעמי צדק, לאכוף חלקים מהחוזה או לחייב בתשלום שווי תמורה שבוצעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הצהרה על בטלות החוזה בלבד, ללא כל סעד נוסף.', false, 'שגוי. הצהרה על בטלות היא אכן סעד, אך בית המשפט יכול וצריך להעניק סעדים נוספים כדי להסדיר את היחסים בין הצדדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'צו מניעה קבוע המונע מהצדדים לבצע כל פעולה הקשורה לחוזה.', false, 'שגוי. צו מניעה עשוי להיות רלוונטי במקרים מסוימים, אך הוא אינו סעד כללי ובלעדי לחוזה פסול, ואינו פותר את סוגיית ההשבה או התמורה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 33, '2022-W-S-Q33';
END
$$;

