DO $$
DECLARE
  v_sq_id uuid := '12ffd81d-e768-4239-918d-ce3ffb4db934'::uuid;
  v_group_id uuid := 'b312ba62-6973-42f3-acfc-c391c5bd919f'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '2a543c68-1a4e-4e73-9d3e-9c6b49bf55db'::uuid;
  v_ang_1 uuid := 'b16a9fb0-8f2b-4fbc-b7ef-86ea344d329f'::uuid;
  v_ang_2 uuid := '57c53c50-dc97-4e33-a596-1f06793a26f8'::uuid;
  v_ang_3 uuid := '30ce985c-6e4d-4fdc-bccd-f8fec625be6b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q34';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 34, '2022-W-S-Q34';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
