  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q34', v_chapter_id, v_subtopic_id, 'בקאנטרי שכונתי בבעלות פרטית שמצוי בעיר רעננה נערכה תחרות התעמלות מכשירים שנתית שבה התחרו מיטב המתעמלים בעיר והתמודדו על התואר הנכסף "אלוף העיר". מעבר להכרה ולגאווה שמלווה לזכייה כאמור ולקבלת התואר, הזוכה בתחרות אף נהנה מפרס בשווי של 5,000 ש"ח. דני, מתעמל מכשירים מיומן, החליט לקחת חלק בתחרות. בתקנון הקאנטרי צוין כי חבר השופטים מורכב מוותיקי העיר שמבינים בהתעמלות מכשירים. בתחרות השתתפו 8 מתמודדים, ובסופה הכריעו השופטים ששמוליק הוא הזוכה. דני התאכזב מהבחירה, והוא סבור כי שמוליק זכה בתחרות משום שאביו הוא איש עסקים ידוע ומוכר בעיר, ולפיכך ההכרעה בתחרות הייתה מוטה וידועה מראש. דני מחליט לפתוח בהליך משפטי נגד זכייה זו ולעתור לביטולה של הזכייה של שמוליק. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 34}'::jsonb, 'השאלה עוסקת בשפיטותם של חוזים למתן פרס, תואר או ציון, בהתאם לסעיף 33 לחוק החוזים. סעיף זה קובע כי הכרעה או הערכה הניתנת על ידי צד או אדם שלישי אינה נושא לדיון בבית המשפט, מתוך רצון למנוע התערבות בשיקול דעת מקצועי.', 'סעיף 33 לחוק החuזים (חלק כללי) קובע כי חוזה שלפיו יינתן ציון, תואר, פרס וכיוצא באלה על פי הכרעה או הערכה של אחד הצדדים או של אדם שלישי, אין ההכרעה או ההערכה לפי החוזה נושא לדיון בבית משפט. מטרת הסעיף היא למנוע התערבות שיפוטית בשיקול דעת מקצועי. הפסיקה קבעה כי בית המשפט לא ישים עצמו כ''בוחן על'' ולא יחליף את שיקול דעתם המקצועי של הגורמים המוסמכים, אלא אם נפלו פגמים מהותיים בהליך קבלת ההחלטה כגון חוסר סמכות, שרירות לב, אפליה או שיקולים זרים. במקרה זה, הטענה היא להכרעה מוטה, אך לא לחוסר סמכות או אפליה מובהקת, אלא לשיקול דעת מוטעה לכאורה, שבית המשפט לא יתערב בו.', 'טעות נפוצה היא לבלבל בין טענות על שיקול דעת מוטעה או שגוי לבין טענות על פגמים מהותיים בהליך (כגון חוסר סמכות, שרירות או אפליה) שכן מצדיקים התערבות שיפוטית. סעיף 33 חוסם את הראשונים אך לא את האחרונים.',
    '["חוזה בלתי שפיט", "סעיף 33 לחוק החוזים", "שיקול דעת מקצועי", "התערבות שיפוטית", "פרס"]'::jsonb, '**וריאציה 1 — תחרות יופי:** בתחרות יופי, המתמודדת שהגיעה למקום השני טוענת שהשופטים העדיפו את הזוכה בגלל קשריה המשפחתיים. האם בית המשפט יתערב? ← לא, סעיף 33 לחוק החוזים קובע אי-שפיטות של הכרעות למתן פרס/תואר.
**וריאציה 2 — תחרות בישול:** בתחרות בישול, אחד המתמודדים טוען שהשופטים פסלו את מנתו מטעמים אישיים ולא מקצועיים. האם בית המשפט יתערב? ← כן, אם הוכח שההחלטה נגועה בשיקולים זרים או שרירותיים, בית המשפט עשוי להתערב (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 3 — תחרות ספורט עם כללים אובייקטיביים:** בתחרות ריצה, המתמודד שהגיע שני טוען שהשופטים טעו בחישוב הזמנים. האם בית המשפט יתערב? ← כן, אם מדובר בטעות חשבונית או טעות אובייקטיבית שאינה נוגעת לשיקול דעת מקצועי, בית המשפט עשוי להתערב (ע"א 338/65 מדינת ישראל נ'' קראסניאנסקי).
**וריאציה 4 — תחרות עם תקנון לא ברור:** בתחרות שירה, המתמודד שהודח טוען שהתקנון לא היה ברור לגבי קריטריוני השיפוט. האם בית המשפט יתערב? ← כן, בית המשפט יכול לדון בשאלות פרשנות תקנון או פגמים פרוצדורליים שאינם נוגעים לשיקול דעת מקצועי (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).', 'סעיף 33 לחוק החוזים ← אי-שפיטות הכרעות מקצועיות למתן ציון/תואר/פרס ← למעט פגמים מינהליים (שרירות, אפליה, חוסר סמכות).', '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 33", "ע\"א 838/87 רחל שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380", "ה\"פ (מחוזי ת\"א) 15024-09-18 אברהם פרל נ'' אוניברסיטת תל אביב (2019)", "בג\"ץ 2769/04 ח\"כ שאול יהלום נ'' שרת החינוך, התרבות והספורט, נח(4) 823", "דניאל פרידמן ונילי כהן חוזים כרך א'' (2018) | פרק 9 שפיטות וכוונה ליצור יחסים משפטיים"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Community sports-club gymnastics contest, prize promise — unilateral promise / award contract | source_review_note: שאלת המקור עוסקת בדיני חוזים (דין מהותי) ואינה מתאימה לסיווג תחת ''סדר דין אזרחי'' או ''הליכים''. סווגה כך כברירת מחדל בהיעדר קטגוריה מתאימה לדיני חוזים ברשימה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט לא יידרש לעניין היות שמדובר בחוזה בלתי שפיט.', true, 'תשובה זו נכונה. סעיף 33 לחוק החוזים קובע כי הכרעה או הערכה למתן ציון, תואר או פרס אינה נושא לדיון בבית המשפט, למעט מקרים חריגים של פגמים מינהליים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט יבחן את נסיבות העניין, והיה וישתכנע כי מדובר בהכרעה שגויה ומוטה, יורה על ביטול זכייתו של שמוליק בתחרות.', false, 'תשובה זו שגויה. בית המשפט אינו מחליף את שיקול הדעת המקצועי של הגורם המעריך, ואינו משמש כ''בוחן על'' או ''שופט על'' בתחרויות מסוג זה, אלא אם הוכחו פגמים מהותיים בהליך.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט יידרש לעניין. בסמכותו ליתן הוראות לחבר השופטים בדבר בדיקה חוזרת של הזכייה ואולם לא להורות על ביטולה.', false, 'תשובה זו שגויה. בית המשפט לא יתערב בהכרעה לגופה, וגם הוראה לבדיקה חוזרת תינתן רק במקרים חריגים של פגם מינהלי, ולא בטענה כללית להכרעה מוטה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט לא יידרש לעניין רק מהטעם שמדובר בעתירה "טורדנית".', false, 'תשובה זו שגויה. הסיבה העיקרית לאי-התערבות היא עקרון אי-השפיטות הקבוע בסעיף 33 לחוק החוזים, ולא רק אופי העתירה כ''טורדנית''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אי-שפיטות בבחינות אקדמיות',
    1, 'סטודנט לרפואה נכשל בבחינה פנימית קריטית באוניברסיטה. הוא טוען כי נפלה טעות בבדיקת הבחינה וכי תשובותיו לא הוערכו כראוי. הסטודנט פונה לבית המשפט בבקשה שיורה לאוניברסיטה להעניק לו ציון עובר. מה הדין?', 'שאלה זו בוחנת את תחולת סעיף 33 לחוק החוזים על החלטות אקדמיות הנוגעות לציונים, ומדגישה את העיקרון של אי-התערבות שיפוטית בשיקול דעת מקצועי טהור של מוסדות להשכלה גבוהה.', 'סעיף 33 לחוק החוזים (חלק כללי) קובע כי חוזה שלפיו יינתן ציון, תואר, פרס וכיוצא באלה על פי הכרעה או הערכה של אחד הצדדים או של אדם שלישי, אין ההכרעה או ההערכה לפי החוזה נושא לדיון בבית משפט. הפסיקה קבעה כי בית המשפט לא יתערב בשיקול דעת מקצועי של מוסדות אקדמיים בנוגע לציונים, אלא אם הוכח פגם מהותי בהליך קבלת ההחלטה, כגון חוסר סמכות, שרירות לב, אפליה או שיקולים זרים. טענה לטעות בבדיקה, כשלעצמה, אינה מצדיקה התערבות שיפוטית, שכן בית המשפט אינו משמש כ''בוחן על''.',
    'הנטייה לחשוב שכל טעות בבדיקה או הערכה מקצועית מצדיקה התערבות שיפוטית, מבלי להבחין בין טעות אובייקטיבית (כגון טעות חישוב) לבין טעות בשיקול דעת מקצועי, שבה בית המשפט לא יתערב.', '["סעיף 33 לחוק החוזים", "אי-שפיטות", "שיקול דעת אקדמי", "התערבות שיפוטית", "ציונים"]'::jsonb, '**וריאציה 1 — טעות חישוב ציון:** סטודנט טוען שהציון הסופי שלו חושב באופן שגוי. האם בית המשפט יתערב? ← כן, טעות חשבונית אינה שיקול דעת מקצועי וניתן להתערב בה (ע"א 338/65 מדינת ישראל נ'' קראסניאנסקי).
**וריאציה 2 — אפליה בבחינה:** סטודנטית טוענת שהופלתה לרעה בבחינה בגלל מינה. האם בית המשפט יתערב? ← כן, טענת אפליה היא פגם מינהלי המצדיק התערבות שיפוטית (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 3 — שינוי קריטריונים רטרואקטיבי:** אוניברסיטה שינתה קריטריונים למעבר שנה באופן רטרואקטיבי. האם בית המשפט יתערב? ← כן, שינוי רטרואקטיבי של כללים הוא פגם מינהלי המצדיק התערבות (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 4 — אי-התאמה בין סילבוס לבחינה:** סטודנט טוען שהבחינה כללה חומר שלא נלמד בסילבוס. האם בית המשפט יתערב? ← לא, זוהי טענה הנוגעת לשיקול דעת אקדמי טהור, ובית המשפט לא יתערב בה (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב).', 'סעיף 33 לחוק החוזים ← אי-שפיטות הכרעות אקדמיות (ציונים, תארים) ← למעט פגמים מינהליים (אפליה, שרירות, חוסר סמכות).',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 33", "ע\"א 838/87 רחל שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380", "ה\"פ (מחוזי ת\"א) 15024-09-18 אברהם פרל נ'' אוניברסיטת תל אביב (2019)", "ע\"א 4106/11 ד''''ר יצחק רויזמן נ'' הפקולטה לרפואה, אוניברסיטת תל-אביב (2013)", "ה\"פ (מחוזי חי'') 26804-11-19 שימאא איבראהים נ'' ביה\"ס לאחיות מוסמכות שליד בי\"ח \"בני ציון\" (2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בית המשפט יורה לאוניברסיטה לבדוק מחדש את הבחינה, שכן זכותו של סטודנט להערכה הוגנת.', false, 'שגוי. בית המשפט אינו מתערב בשיקול דעת מקצועי של מוסדות אקדמיים בנוגע לציונים, אלא אם הוכח פגם מהותי בהליך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט לא יתערב בהחלטת האוניברסיטה, שכן מדובר בשיקול דעת אקדמי מקצועי שאינו שפיט.', true, 'נכון. סעיף 33 לחוק החוזים קובע אי-שפיטות של הכרעות למתן ציון, והפסיקה קבעה כי בית המשפט אינו משמש כ''בוחן על'' בהחלטות אקדמיות מקצועיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט יתערב רק אם הסטודנט יוכיח שהאוניברסיטה פעלה בחוסר תום לב קיצוני או במניעים זרים.', false, 'שגוי. אף שטענות לחוסר תום לב או מניעים זרים עשויות להצדיק התערבות, התשובה הנכונה מתייחסת לעיקרון הכללי של אי-שפיטות במקרה של טענה לטעות בבדיקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בית המשפט יורה על ביטול הבחינה כולה וקיום בחינה חוזרת, כדי להבטיח הוגנות.', false, 'שגוי. סעד כזה הוא התערבות עמוקה בשיקול הדעת האקדמי, ואינו נהוג במקרים של טענה לטעות בבדיקה, אלא אם הוכחו פגמים חמורים בהליך.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'היקף אי-השפיטות לפי סעיף 33',
    2, 'סעיף 33 לחוק החוזים קובע כי הכרעה או הערכה למתן ציון, תואר או פרס אינה נושא לדיון בבית משפט. באילו מקרים, למרות הוראה זו, בית המשפט כן יתערב בהחלטות מסוג זה?', 'שאלה זו מתמקדת בגבולות סמכותו של בית המשפט להתערב בהחלטות הנתונות לסעיף 33 לחוק החוזים, ומבהירה כי למרות עקרון אי-השפיטות, קיימים מקרים בהם בית המשפט כן יתערב, אך רק כאשר מדובר בפגמים מינהליים בהליך קבלת ההחלטה.', 'סעיף 33 לחוק החוזים (חלק כללי) קובע עקרון אי-שפיטות לגבי הכרעות או הערכות למתן ציון, תואר או פרס. עם זאת, הפסיקה הבהירה כי הוראה זו אינה מונעת התערבות שיפוטית במקרים בהם נפל פגם בהליך קבלת ההחלטה, כגון חוסר סמכות, שרירות לב, אפליה, או שיקולים זרים. בית המשפט אינו מחליף את שיקול הדעת המקצועי לגופו, אך הוא בוחן את תקינות ההליך המינהלי. כך למשל, נקבע כי בית המשפט רשאי לדון בשאלות של מיהו האורגן המוסמך לקבל החלטה, והאם ההחלטה התקבלה על ידיו.',
    'ההנחה שסעיף 33 חוסם כל ביקורת שיפוטית על החלטות אלו. יש לזכור את ההבחנה בין ביקורת על שיקול הדעת המקצועי לגופו (שאינה מותרת) לבין ביקורת על פגמים מינהליים בהליך קבלת ההחלטה (שכן מותרת).', '["סעיף 33 לחוק החוזים", "אי-שפיטות", "ביקורת שיפוטית", "פגמים מינהליים", "חוסר סמכות", "שרירות לב", "אפליה"]'::jsonb, '**וריאציה 1 — טעות חישוב:** בתחרות ידע, המתמודד טוען לטעות בחישוב הניקוד. האם בית המשפט יתערב? ← כן, טעות חשבונית אינה שיקול דעת מקצועי וניתן להתערב בה (ע"א 338/65 מדינת ישראל נ'' קראסניאנסקי).
**וריאציה 2 — שיקולים זרים:** ועדת פרס העניקה פרס לאדם שתרם כספים לוועדה. האם בית המשפט יתערב? ← כן, אם הוכח שההחלטה נגועה בשיקולים זרים, בית המשפט יתערב (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 3 — חוסר סמכות:** החלטה על מתן תואר התקבלה על ידי גורם באוניברסיטה שאינו מוסמך לכך. האם בית המשפט יתערב? ← כן, בית המשפט יבחן את שאלת הסמכות (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 4 — אי-התערבות בשיקול דעת:** סטודנט טוען שהמרצה העניק לו ציון נמוך מדי בעבודה. האם בית המשפט יתערב? ← לא, זוהי הערכה מקצועית טהורה שבית המשפט לא יתערב בה (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב).', 'סעיף 33 לחוק החוזים ← אי-שפיטות הכרעות מקצועיות ← התערבות רק בפגמים מינהליים (חוסר סמכות, שרירות, אפליה, שיקולים זרים).',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 33", "ע\"א 838/87 רחל שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380", "ה\"פ (מחוזי ת\"א) 15024-09-18 אברהם פרל נ'' אוניברסיטת תל אביב (2019)", "בג\"ץ 2769/04 ח\"כ שאול יהלום נ'' שרת החינוך, התרבות והספורט, נח(4) 823", "דניאל פרידמן ונילי כהן חוזים כרך א'' (2018) | פרק 9 שפיטות וכוונה ליצור יחסים משפטיים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'רק אם ההחלטה ניתנה בחוסר סמכות או נגועה בשרירות לב או באפליה.', true, 'נכון. הפסיקה קבעה כי סעיף 33 אינו חוסם דיון משפטי במקרים של חוסר סמכות, שרירות, אפליה או פגמים אחרים הפוגעים בשיקול הדעת של רשות מקצועית מחליטה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'רק אם ההחלטה שגויה באופן מובהק ואינה עולה בקנה אחד עם הראיות שהוצגו.', false, 'שגוי. בית המשפט אינו מתערב בשיקול דעת מקצועי לגופו, גם אם הוא סבור שההחלטה שגויה, אלא אם מדובר בפגם מינהלי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'רק אם ההחלטה גורמת נזק כלכלי משמעותי לצד הנפגע.', false, 'שגוי. הנזק הכלכלי אינו קריטריון להתערבות שיפוטית בהחלטות הנתונות לסעיף 33, אלא הפגמים המינהליים בהליך קבלת ההחלטה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'רק אם הצדדים הסכימו מראש בחוזה על סמכות בית המשפט לדון בהכרעה או בהערכה.', false, 'שגוי. סעיף 33 הוא הוראה קוגנטית, וצדדים אינם יכולים להתנות עליה ולהקנות לבית המשפט סמכות לדון בהכרעה או הערכה מקצועית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התערבות חריגה בפרס ממלכתי',
    3, 'ועדת שופטים המליצה להעניק פרס ישראל לאמן ידוע. עתירה הוגשה לבג"ץ בטענה שהוועדה לא הייתה מודעת להתבטאויות גזעניות חמורות של האמן בעבר, וכי לו הייתה מודעת, לא הייתה ממליצה על הענקת הפרס. מה עמדת בית המשפט במקרה כזה?', 'שאלה זו עוסקת במקרים החריגים בהם בית המשפט הגבוה לצדק יתערב בהחלטות על הענקת פרסים ממלכתיים, למרות עקרון אי-השפיטות הנגזר מסעיף 33 לחוק החוזים. היא מדגישה את ההבחנה בין ביקורת על שיקול דעת מקצועי לגופו לבין ביקורת על פגמים דיוניים מהותיים.', 'אף שלסעיף 33 לחוק החוזים (חלק כללי) אין תחולה ישירה על החלטות ועדות השופטים לעניין פרס ישראל (הכפופות לכללי המשפט הציבורי), הרציונל שביסודו מקרין על מדיניות בית המשפט שלא להתערב בהחלטות אלו. עם זאת, הפסיקה הכירה במקרים חריגים ויוצאי דופן בהם תיתכן התערבות. מקרה מובהק לכך הוא כאשר הוועדה לא הייתה מודעת לעובדות מהותיות ורלוונטיות בעת קבלת החלטתה. במקרים כאלה, בג"ץ עשוי להורות על החזרת העניין לדיון חוזר בוועדה, כדי לאפשר לה לשקול את כלל הנתונים הרלוונטיים. זאת, תוך שמירה על עקרון שיקול הדעת המקצועי של הוועדה.',
    'ההנחה שפרס ממלכתי חסין לחלוטין מביקורת שיפוטית, או לחלופין, שכל טענה לגבי אי-התאמה ערכית תצדיק התערבות. יש לזכור את המקרים המצומצמים בהם בג"ץ יתערב, בעיקר בפגמים דיוניים מהותיים.', '["פרס ישראל", "אי-שפיטות", "ביקורת שיפוטית", "פגמים דיוניים", "עובדות מהותיות", "סעיף 33 לחוק החוזים", "משפט מינהלי"]'::jsonb, '**וריאציה 1 — אי-מודעות לעובדות:** ועדת פרס לא הייתה מודעת להרשעה פלילית חמורה של מועמד. האם בג"ץ יתערב? ← כן, יורה על החזרת העניין לדיון חוזר בוועדה (בג"ץ 2205/97 מסאלה נ'' שר החינוך והתרבות).
**וריאציה 2 — מודעות לעובדות:** ועדת פרס הייתה מודעת להתבטאויות שנויות במחלוקת של מועמד, ובכל זאת המליצה עליו. האם בג"ץ יתערב? ← לא, אם הוועדה הייתה מודעת לעובדות, בג"ץ לא יתערב בשיקול דעתה (בג"ץ 1933/98 ח"כ הנדל נ'' שר החינוך והתרבות).
**וריאציה 3 — שיקולים זרים:** ועדת פרס המליצה על מועמד משיקולים פוליטיים ולא מקצועיים. האם בג"ץ יתערב? ← כן, אם הוכחו שיקולים זרים, בג"ץ יתערב (בג"ץ 2769/04 ח"כ שאול יהלום נ'' שרת החינוך).
**וריאציה 4 — סמכות שר החינוך:** שר החינוך סירב לאשר המלצת ועדת פרס מטעמים ערכיים. האם בג"ץ יתערב? ← כן, סמכות השר מוגבלת לבחינת תקינות מינהלית ולא להתערבות בהכרעה לגופה (בג"ץ 2769/04 ח"כ שאול יהלום נ'' שרת החינוך).', 'פרס ממלכתי ← כמעט חסין מביקורת (רציונל סעיף 33) ← התערבות בג"ץ רק במקרים חריגים (פגם דיוני מהותי, אי-מודעות לעובדות רלוונטיות) ← החזרה לדיון חוזר בוועדה.',
    '["בג\"ץ 5746174 ועדת השופטים להענקת פרס ישראל לשנת תשפ\"א בתחום חקר מדעי המחשב נ'' שרת החינוך (2022)", "בג\"ץ 2769/04 ח\"כ שאול יהלום נ'' שרת החינוך, התרבות והספורט, נח(4) 823", "בג\"ץ 2205/97 מסאלה נ'' שר החינוך והתרבות, פ\"ד נא(1) 233 (1997)", "בג\"ץ 5545690 ועדת השופטים להענקת פרס ישראל לשנת תשפ\"א בתחום חקר המתמטיקה, חקר מדעי המחשב נ'' שר החינוך (2021)", "דניאל פרידמן ונילי כהן חוזים כרך א'' (2018) | פרק 9 שפיטות וכוונה ליצור יחסים משפטיים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'בית המשפט לא יתערב, שכן פרס ישראל הוא עניין של שיקול דעת מקצועי ואינו שפיט.', false, 'שגוי. אף שפרס ישראל נחשב כמעט חסין מהתערבות, במקרים חריגים של פגם דיוני מהותי, כגון אי-מודעות לעובדות רלוונטיות, בג"ץ עשוי להתערב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'בית המשפט יורה על החזרת העניין לדיון חוזר בוועדה, אם יתברר שהוועדה לא הייתה מודעת לעובדות מהותיות ורלוונטיות.', true, 'נכון. הפסיקה קבעה כי במקרים חריגים, כגון אי-מודעות של הוועדה לעובדות מהותיות, בג"ץ עשוי להחזיר את העניין לדיון חוזר בוועדה (בג"ץ 2205/97 מסאלה נ'' שר החינוך והתרבות (עניין שניצר)).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'בית המשפט יורה על ביטול מיידי של המלצת הוועדה, שכן התבטאויות גזעניות סותרות את ערכי המדינה.', false, 'שגוי. בית המשפט אינו מבטל את ההמלצה ישירות, אלא מחזיר את העניין לוועדה לדיון חוזר, תוך שמירה על עקרון שיקול הדעת המקצועי של הוועדה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'בית המשפט יתערב רק אם שר החינוך עצמו יבקש את התערבותו.', false, 'שגוי. סמכות ההתערבות של בג"ץ נובעת מעקרונות המשפט המינהלי, ואינה תלויה בבקשת שר החינוך.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים חלופיים בחוזה בלתי שפיט',
    4, 'ראובן השתתף בתחרות שירה, אך הודח בשלב מוקדם. הוא טוען כי ההדחה הייתה שרירותית ונגרמה עקב יחסים אישיים עכורים עם אחד השופטים. ראובן מעוניין לתבוע פיצויים בגין עוגמת נפש והוצאות שהוציא לצורך ההשתתפות בתחרות. האם בית המשפט ידון בתביעה זו?', 'שאלה זו בוחנת את היקף אי-השפיטות של סעיף 33 לחוק החוזים, ומדגישה כי למרות שההכרעה או ההערכה עצמה אינה שפיטה, בית המשפט כן ידון בסעדים אחרים, כגון פיצויים, הנובעים מפגמים מינהליים או התנהלות שלא בתום לב, שאינם נוגעים לשיקול הדעת המקצועי הטהור.', 'סעיף 33 לחוק החוזים (חלק כללי) קובע כי ההכרעה או ההערכה למתן ציון, תואר או פרס אינה נושא לדיון בבית משפט. עם זאת, הפסיקה הבהירה כי סעיף זה אינו חוסם דיון משפטי בשאלות שאינן נוגעות לשיקול הדעת המקצועי הטהור. כך, בית המשפט רשאי לדון בטענות בדבר פגמים מינהליים, שרירות לב, אפליה או שיקולים זרים בהליך קבלת ההחלטה. במקרים אלו, ניתן לתבוע סעדים שאינם אכיפת ההכרעה או שינויה, אלא פיצויים בגין נזקים שנגרמו כתוצאה מהתנהלות פסולה, כגון עוגמת נפש והוצאות. החלק המינהלי-כספי של החוזה שפיט לחלוטין.',
    'ההנחה שאי-שפיטות ההכרעה המקצועית משמעותה חסינות מוחלטת מכל תביעה משפטית. יש לזכור את ההבחנה בין אי-שפיטות ההכרעה לגופה לבין שפיטות פגמים בהתנהלות או בהליך, המאפשרת תביעת סעדים כספיים.', '["סעיף 33 לחוק החוזים", "אי-שפיטות", "סעדים כספיים", "פיצויים", "פגמים מינהליים", "שרירות לב", "שיקולים זרים"]'::jsonb, '**וריאציה 1 — תביעת פיצויים על אפליה:** סטודנטית הופלתה בקבלה לתואר. האם היא יכולה לתבוע פיצויים? ← כן, טענת אפליה היא פגם מינהלי המצדיק תביעת פיצויים, גם אם לא ניתן לאכוף את הקבלה לתואר (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 2 — תביעת פיצויים על חוסר תום לב:** מארגני תחרות ביטלו אותה ברגע האחרון בחוסר תום לב, וגרמו למתמודדים הוצאות. האם ניתן לתבוע פיצויים? ← כן, סעיף 33 אינו חוסם תביעות על חוסר תום לב בהתנהלות שאינן נוגעות להכרעה המקצועית (דניאל פרידמן ונילי כהן חוזים כרך א'' (2018)).
**וריאציה 3 — תביעת פיצויים על טעות חישוב:** מתמודד בתחרות ידע טוען לטעות בחישוב הניקוד שגרמה לו להפסיד פרס כספי. האם הוא יכול לתבוע פיצויים? ← כן, טעות חשבונית ניתנת לביקורת שיפוטית, וניתן לתבוע פיצויים על נזק שנגרם ממנה (ע"א 338/65 מדינת ישראל נ'' קראסניאנסקי).
**וריאציה 4 — תביעת פיצויים על שיקול דעת מקצועי:** מתמודד בתחרות שירה טוען שהשופטים העניקו לו ציון נמוך מדי. האם הוא יכול לתבוע פיצויים? ← לא, בית המשפט לא יתערב בשיקול דעת מקצועי טהור, ואין עילה לפיצויים על הערכה כזו (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב).', 'סעיף 33 לחוק החוזים ← אי-שפיטות הכרעה/הערכה ← אך שפיטות פגמים בהתנהלות (שרירות, אפליה, חוסר תום לב) ← ניתן לתבוע פיצויים על נזקים שאינם נוגעים להכרעה לגופה.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 33", "ע\"א 838/87 רחל שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380", "דניאל פרידמן ונילי כהן חוזים כרך א'' (2018) | פרק 9 שפיטות וכוונה ליצור יחסים משפטיים", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | פרק 21 חוזים בלתי אכיפים וחוזים בלתי שפיטים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, סעיף 33 לחוק החוזים חוסם כל דיון משפטי הקשור לחוזה למתן פרס, כולל תביעות לפיצויים.', false, 'שגוי. סעיף 33 חוסם דיון בהכרעה או הערכה עצמה, אך לא בהכרח בתביעות לסעדים אחרים הנובעים מפגמים מינהליים או התנהלות שלא בתום לב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בית המשפט ידון בתביעה לפיצויים, שכן סעיף 33 חל רק על ההכרעה או ההערכה עצמה, ולא על סעדים כספיים הנובעים מפגמים בהתנהלות.', true, 'נכון. סעיף 33 אינו חוסם דיון משפטי בשאלות שאינן נוגעות לשיקול הדעת המקצועי, כגון פגמים מינהליים, שרירות לב או אפליה, וניתן לתבוע פיצויים בגין נזקים שנגרמו כתוצאה מהתנהלות כזו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם ראובן יוכיח שההדחה הייתה מכוונת ונועדה לפגוע בו אישית.', false, 'שגוי. אף שכוונת פגיעה עשויה לחזק את התביעה, די בהוכחת שרירות לב או שיקולים זרים כדי להצדיק התערבות שיפוטית בסעדים שאינם נוגעים להכרעה לגופה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן התחרות הייתה מאורגנת על ידי גוף ציבורי, שאז יחולו עליה כללי המשפט המינהלי.', false, 'שגוי. אף שכללי המשפט המינהלי רלוונטיים לגופים ציבוריים, גם בגופים פרטיים ניתן לתבוע סעדים שאינם נוגעים להכרעה המקצועית לגופה, אם הוכחו פגמים בהתנהלות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 34, '2022-W-S-Q34';
END
$$;

-- ============================================================
-- Q35 — 2022-W-S-Q35 — chapter=contracts subtopic=general_part  [needs_review]
-- classifier_note: Elderly man with chronic anxiety signing under pressure; shop ownership transfer — duress/capacity in contract; no dedicated capacity subtopic in contracts
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'aa99b880-8383-4b3c-93d8-2fdb779b7457'::uuid;
  v_group_id uuid := '6891e181-1d07-498a-8d36-c24e580349aa'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '66b54dca-57e4-4b65-9364-9ff95373194f'::uuid;
  v_ang_1 uuid := '9f7f17d5-23f8-4b6b-913b-e34bd7bcc224'::uuid;
  v_ang_2 uuid := '04740455-ed4f-487c-9752-8de2d0958621'::uuid;
  v_ang_3 uuid := '41700c36-dede-4ca1-8356-f191bc9d714e'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q35';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 35, '2022-W-S-Q35';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q35', v_chapter_id, v_subtopic_id, 'ירוחם, בן 70, שבני משפחתו הגרעינית נהרגו בתאונת דרכים לפני 20 שנה, מעורער מאז וסובל מחרדות ופחדים באופן כרוני. ירוחם מנהל חנות ששייכת לדני. יום אחד הגיע דני לביתו של ירוחם עם עורך דין. השניים הודיעו לירוחם כי הם גילו שהוא רימה את דני ברישומי החשבונות, וכן מודיעים לו כי כדי שהם לא יתלוננו נגדו ודבר המרמה יתפרסם, עליו לחתום על התחייבות בלתי ניתנת לחזרה ולפיה הוא ישלם לדני פיצוי כספי משמעותי. ירוחם נענה לדרישה מיד, ללא כל היסוס, וחתם על ההתחייבות. בחלוף האירוע מבין ירוחם כי הוא חתם על ההתחייבות תוך ניצול מצבו, ולפיכך מחליט להגיש לבית המשפט תביעה לביטולה של ההתחייבות. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 35}'::jsonb, 'השאלה עוסקת בפגמים ברצון בכריתת חוזה, ובפרט בעילות העושק והכפייה לפי חוק החוזים (חלק כללי). היא בוחנת את היכולת לבטל חוזה שנחתם תחת לחץ וניצול מצוקה, תוך התייחסות ליסודות המצטברים של עילות אלו.', 'סעיף 18 לחוק החוזים (חלק כללי) קובע את עילת העושק, המאפשרת ביטול חוזה אם התקשרות בו הייתה עקב ניצול מצוקה, חולשה שכלית או גופנית, או חוסר ניסיון של המתקשר, ותנאי החוזה גרועים במידה בלתי סבירה מן המקובל. במקרה של ירוחם, מצבו הנפשי המעורער וסבלו מחרדות ופחדים כרוניים, במיוחד לאור טרגדיה משפחתית, עשויים לעלות כדי מצוקה או חולשה שכלית כבדת משקל. האיום בחשיפת מרמה והליכים משפטיים, במיוחד כשהוא מלווה בעורך דין, מהווה ניצול של מצוקה זו. אם תנאי ההתחייבות (פיצוי כספי משמעותי) גרועים במידה בלתי סבירה, מתקיימים כל יסודות העושק. גם עילת הכפייה (סעיף 17) עשויה להיות רלוונטית, שכן איום בהליכים פליליים למימוש זכות אזרחית אינו נחשב אזהרה בתום לב (ע"א 784/81 שפיר נ'' אפל).', 'ההנחה כי רק מצוקה כלכלית או פיזית מיידית יכולה להקים עילת עושק, או כי חתימה ''ללא היסוס'' שוללת פגם ברצון. יש לזכור כי מצוקה נפשית כרונית ופגיעה בשיקול הדעת עשויות להיות כבדות משקל לא פחות.',
    '["עושק", "כפייה", "פגם ברצון", "מצוקה נפשית", "ניצול מצוקה", "תנאי חוזה גרועים", "סעיף 17 לחוק החוזים", "סעיף 18 לחוק החוזים"]'::jsonb, '**וריאציה 1 — מצוקה כרונית:** האם מצוקה כרונית, שאינה קשורה ישירות לאירוע החתימה, יכולה להקים עילת עושק? ← כן, אם היא כבדת משקל ונוצלה, היא יכולה להיחשב כמצוקה לצורך סעיף 18 (ע"א 403/80 סאסי נ'' קיקאון).
**וריאציה 2 — איום בחשיפת מידע:** האם איום בחשיפת מידע מביך או פלילי יכול להוות כפייה? ← כן, אם האיום אינו אזהרה בתום לב על הפעלת זכות, הוא יכול להיחשב ככפייה (ע"א 784/81 שפיר נ'' אפל).
**וריאציה 3 — חתימה ללא היסוס:** האם חתימה מהירה וללא היסוס שוללת טענת עושק או כפייה? ← לא בהכרח, היא יכולה דווקא להעיד על עוצמת הלחץ או המצוקה שפגעה ביכולת שיקול הדעת (ת"א (מחוזי מרכז) 12877-10-19 ד"ר טליה האן נ'' שמואל חרסט).
**וריאציה 4 — תנאי חוזה גרועים:** האם תנאי חוזה גרועים הם יסוד הכרחי לעילת הכפייה? ← לא, תנאי חוזה גרועים הם יסוד הכרחי לעילת העושק, אך לא לעילת הכפייה (ע"א 5806/02 ארביב נ'' קרני).', 'חוזה שנחתם עקב ניצול מצוקה נפשית כרונית (מעורער, חרדות) ואיום בחשיפת מרמה ← עשוי להתבטל בעילת עושק (סעיף 18) או כפייה (סעיף 17), אם תנאי החוזה גרועים והניצול/לחץ פגע ברצון החופשי.', '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 17, 18", "ע\"א 784/81 ישראל שפיר נ'' מרטין אפל, לט(4) 149 (1985)", "ע\"א 403/80 סאסי נ'' קיקאון, פ\"ד לו(1) 762 (1981)", "ע\"א 5806/02 אריאל ארביב נ'' יעקב קרני, נח(5) 193 (2004)", "ת\"א (מחוזי מרכז) 12877-10-19 ד\"ר טליה האן נ'' שמואל חרסט (2025)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Elderly man with chronic anxiety signing under pressure; shop ownership transfer — duress/capacity in contract; no dedicated capacity subtopic in contracts | source_review_note: שאלת המקור עוסקת בדיני חוזים (דין מהותי) ואינה מתאימה לסיווג תחת ''סדר דין אזרחי'' או ''הליכים''. סווגה כך כברירת מחדל בהיעדר קטגוריה מתאימה לדיני חוזים ברשימה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט לא יורה על ביטול ההתחייבות היות שזו נחתמה על ידי ירוחם ללא כל היסוס.', false, 'תשובה זו שגויה. העובדה שירוחם חתם ללא היסוס דווקא מחזקת את הטענה למצוקה חמורה וניצולה, שכן היא מעידה על פגיעה קשה בשיקול הדעת וברצון החופשי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט יורה על ביטול ההתחייבות היות שזו נחתמה על ידי ירוחם שהוא מעורער וסובל באופן כרוני מפחדים וחרדות, ולפיכך היה שרוי במצוקה בעת חתימתו על כתב ההתחייבות.', true, 'תשובה זו נכונה. מצבו הנפשי של ירוחם (מעורער, חרדות ופחדים כרוניים) עשוי לעלות כדי מצוקה או חולשה שכלית כבדת משקל, אשר נוצלה על ידי דני ועורך דינו, ותנאי החוזה (פיצוי כספי משמעותי ללא הוכחת מרמה) גרועים במידה בלתי סבירה, ובכך מתקיימים יסודות עילת העושק לפי סעיף 18 לחוק החוזים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט לא יורה על ביטול ההתחייבות היות שהפחדים והחרדות שמהם סבל ירוחם לא קשורים באופן ישיר לנסיבות האירוע שבהן חתם ירוחם על כתב ההתחייבות.', false, 'תשובה זו שגויה. מצוקה לצורך עילת העושק אינה חייבת לנבוע ישירות מהצד העושק, אלא יכולה להיות מצוקה קיימת (כרונית) שנוצלה על ידו. נסיבות האירוע (איום בחשיפת מרמה) רק החריפו את המצוקה הקיימת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ניתן לבטל את ההתחייבות, אך מהטעם שדני היה מלווה בעורך דין וירוחם לא.', false, 'תשובה זו שגויה. אף שייצוג משפטי לא שוויוני הוא שיקול רלוונטי, הוא אינו עילה עצמאית לביטול חוזה. הביטול נובע מקיומן של עילות פגם ברצון, כגון עושק או כפייה, ולא רק מחוסר ייצוג.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'עושק עקב חולשה גופנית',
    1, 'שושנה, קשישה בת 85, חולה ומרותקת למיטתה, תלויה לחלוטין בבנה יואל לטיפול יומיומי. יואל, המודע למצבה, משכנע אותה לחתום על חוזה למכירת דירתה היחידה אליו, בתמורה לסכום הנמוך בחצי משווי השוק, בטענה שזה יקל עליה את הנטל הכלכלי. שושנה חותמת על החוזה. האם שושנה יכולה לבטל את החוזה בטענת עושק?', 'שאלה זו בוחנת את יישום עילת העושק (סעיף 18 לחוק החוזים) במקרים של חולשה גופנית ותלות, תוך התייחסות ליסודות המצטברים של העילה: מצב העשוק, ניצול מצבו, ותנאי חוזה גרועים. היא מדגישה את ההגנה על אוכלוסיות פגיעות.', 'סעיף 18 לחוק החוזים (חלק כללי) קובע כי מי שהתקשר בחוזה עקב ניצול שניצל הצד השני את מצוקת המתקשר, חולשתו השכלית או הגופנית או חוסר ניסיונו, ותנאי החוזה גרועים במידה בלתי סבירה מן המקובל, רשאי לבטל את החוזה. במקרה זה, שושנה סובלת מחולשה גופנית כבדת משקל (קשישה, חולה, מרותקת למיטה) ותלויה בבנה. יואל ניצל מצב זה כדי להשיג חוזה בתנאים גרועים (מחיר נמוך בחצי משווי השוק). כל היסודות המצטברים של עילת העושק מתקיימים, ולכן שושנה יכולה לבטל את החוזה. הפסיקה מכירה בכך שמצוקה או חולשה אינן חייבות להגיע לכדי פסלות דין, אלא די בכך שהן כבדות משקל ומסיטות את שיקול הדעת מנתיבו הנכון (ע"א 403/80 סאסי נ'' קיקאון).',
    'הבלבול בין עילת העושק לעילת הכפייה, וההנחה כי נדרש איום אקטיבי או שהעשוק יהיה פסול דין. יש לזכור שעושק מתמקד בניצול מצוקה קיימת ובתנאי חוזה גרועים.', '["עושק", "חולשה גופנית", "ניצול מצוקה", "תנאי חוזה גרועים", "סעיף 18 לחוק החוזים", "פגם ברצון"]'::jsonb, '**וריאציה 1 — קשיש חסר ניסיון:** קשיש בן 90, שמעולם לא עסק בענייני כספים, חותם על חוזה השקעה מסוכן בתנאים גרועים. האם ניתן לבטל? ← כן, עקב חוסר ניסיון וניצולו, אם תנאי החוזה גרועים (סעיף 18 לחוק החוזים).
**וריאציה 2 — חולה נפש שאינו פסול דין:** אדם הסובל ממחלת נפש קשה, אך לא הוכרז פסול דין, חותם על חוזה מכר דירה במחיר נמוך. האם ניתן לבטל? ← כן, אם מצבו עולה כדי חולשה שכלית כבדת משקל שנוצלה, ותנאי החוזה גרועים (ע"א 403/80 סאסי נ'' קיקאון).
**וריאציה 3 — מצוקה כלכלית חמורה:** אדם שנקלע לחובות כבדים וזקוק נואשות לכסף, חותם על חוזה הלוואה בריבית קצוצה. האם ניתן לבטל? ← כן, אם המצוקה הכלכלית חמורה ונוצלה, ותנאי החוזה גרועים במידה בלתי סבירה (ע"א 784/81 שפיר נ'' אפל).
**וריאציה 4 — מצוקה זמנית:** אדם שאיבד את כל רכושו בשריפה, חותם על חוזה למכירת חלקת אדמה יקרה במחיר נמוך כדי לממן את שיקום ביתו. האם ניתן לבטל? ← כן, מצוקה ארעית וחולפת יכולה להיחשב כמצוקה לצורך עושק, אם היא כבדת משקל ונוצלה (פרידמן וכהן, חוזים, כרך ב'', עמ'' 983).', 'עושק (סעיף 18) ← מצב העשוק (מצוקה/חולשה שכלית/גופנית/חוסר ניסיון כבדת משקל) + ניצול מצב זה + תנאי חוזה גרועים במידה בלתי סבירה.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 18", "ע\"א 403/80 סאסי נ'' קיקאון, פ\"ד לו(1) 762 (1981)", "ע\"א 784/81 ישראל שפיר נ'' מרטין אפל, לט(4) 149 (1985)", "דניאל פרידמן ונילי כהן חוזים כרך ב (2018) | פרק 17 עושק והשפעה לא הוגנת"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן יואל טיפל בה במסירות, ואין לראות בכך ניצול מצוקה.', false, 'שגוי. אף שטיפול מסור הוא חיובי, ניצול תלות וחולשה כדי להשיג תנאי חוזה גרועים עדיין יכול להוות עושק. הטיפול אינו מצדיק תמורה נמוכה משמעותית משווי השוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, שכן מצבה הגופני והתלות שלה ביואל מהווים חולשה כבדת משקל, יואל ניצל זאת, ותנאי החוזה גרועים במידה בלתי סבירה.', true, 'נכון. מצבה של שושנה (קשישה, חולה, מרותקת למיטה, תלויה) עונה על יסוד החולשה הגופנית/מצוקה. יואל ניצל זאת, והתמורה הנמוכה משמעותית עונה על יסוד תנאי חוזה גרועים, ובכך מתקיימים יסודות העושק לפי סעיף 18 לחוק החוזים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן שושנה הוכרזה כפסולת דין לפני חתימת החוזה.', false, 'שגוי. עילת העושק אינה דורשת שהעשוק יהיה פסול דין, אלא די בפגם ברצון הנובע ממצוקה או חולשה כבדת משקל (ע"א 403/80 סאסי נ'' קיקאון).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם יואל איים עליה באלימות פיזית או מילולית.', false, 'שגוי. איום באלימות פיזית או מילולית מתייחס לעילת הכפייה (סעיף 17), בעוד שעילת העושק (סעיף 18) מתמקדת בניצול מצוקה קיימת, גם ללא איום אקטיבי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'יסודות עילת העושק',
    2, 'מהם התנאים המצטברים הנדרשים להוכחת עילת העושק לפי סעיף 18 לחוק החוזים (חלק כללי)?', 'שאלה זו בוחנת את הידע הבסיסי וההבנה של יסודות עילת העושק כפי שהיא מוגדרת בסעיף 18 לחוק החוזים (חלק כללי) וכפי שפורשה בפסיקה. היא מדגישה את שלושת התנאים המצטברים הנדרשים להוכחת העילה.', 'סעיף 18 לחוק החוזים (חלק כללי) קובע שלושה יסודות מצטברים לעילת העושק: א. מצבו של העשוק – מצוקה, חולשה שכלית או גופנית, או חוסר ניסיון. מצב זה צריך להיות כבד משקל ולגרום לסטייה של ממש בשיקול הדעת. ב. התנהגות העושק – ניצול מצבו של העשוק. נדרשת ידיעה של העושק על מצבו של העשוק ושימוש בה כדי להביא ליצירת ההתקשרות. ג. תנאי החוזה – תנאי החוזה גרועים במידה בלתי סבירה מן המקובל. בנוסף ליסודות אלו, נדרש גם קשר סיבתי בין הניצול לבין ההתקשרות בחוזה (ע"א 719/78 איליט בע"מ נ'' אלקו בע"מ).',
    'הבלבול בין יסודות עילת העושק ליסודות עילות פגם אחרות ברצון (כפייה, טעות, הטעיה) או לעילות אחרות בדיני חוזים (חוסר תום לב). יש לזכור את הייחודיות של כל עילה.', '["עושק", "יסודות העושק", "מצוקה", "חולשה שכלית/גופנית", "חוסר ניסיון", "ניצול", "תנאי חוזה גרועים", "סעיף 18 לחוק החוזים"]'::jsonb, '**וריאציה 1 — מצוקה כבדת משקל:** האם כל קושי כלכלי נחשב למצוקה לצורך עושק? ← לא, המצוקה צריכה להיות כבדת משקל, ממשית ומשמעותית, ולא קושי ארעי או חולף (רע"א 617/08 מלון עדן נהריה בע"מ נ'' קסל).
**וריאציה 2 — ניצול מודע:** האם העושק חייב להיות מודע למצוקת העשוק? ← כן, נדרש ניצול מודע של המצוקה (ת"א (שלום חי'') 36673-09-16 ז'' י'' נ'' י'' ב'').
**וריאציה 3 — תנאי חוזה גרועים:** מהו המבחן לתנאי חוזה גרועים במידה בלתי סבירה? ← המבחן הוא אובייקטיבי, בהשוואה למקובל בשוק או בעסקאות דומות, תוך התחשבות בנסיבות (ע"א 719/78 איליט בע"מ נ'' אלקו בע"מ).
**וריאציה 4 — קשר סיבתי:** האם נדרש קשר סיבתי בין הניצול לחתימה על החוזה? ← כן, ההתקשרות בחוזה צריכה להיות עקב ניצול המצוקה, כלומר, אלמלא הניצול, החוזה לא היה נכרת (ע"א 719/78 איליט בע"מ נ'' אלקו בע"מ).', 'יסודות עילת העושק (סעיף 18) ← מצב העשוק (מצוקה/חולשה/חוסר ניסיון) + ניצול מצב זה + תנאי חוזה גרועים + קשר סיבתי.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 18", "ע\"א 403/80 סאסי נ'' קיקאון, פ\"ד לו(1) 762 (1981)", "ע\"א 719/78 איליט בע\"מ נ'' אלקו בע\"מ, פ\"ד לד(4) 673 (1980)", "רע\"א 617/08 מלון עדן נהריה בע\"מ נ'' יוסף קסל (21.9.2014)", "ת\"א (שלום חי'') 36673-09-16 ז'' י'' נ'' י'' ב'' (2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מצוקה של המתקשר, ניצול מצוקה זו על ידי הצד השני, ותנאי חוזה גרועים במידה בלתי סבירה מן המקובל.', true, 'נכון. אלו הם שלושת היסודות המצטברים של עילת העושק, כפי שנקבעו בסעיף 18 לחוק החוזים וכפי שפורשו בפסיקה (ע"א 403/80 סאסי נ'' קיקאון).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'איום בכוח או באיום על המתקשר, קשר סיבתי בין האיום לחתימה, ותנאי חוזה גרועים במידה בלתי סבירה מן המקובל.', false, 'שגוי. איום בכוח או באיום מתייחס לעילת הכפייה (סעיף 17), ולא לעילת העושק. כמו כן, בעילת הכפייה אין דרישה לתנאי חוזה גרועים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'טעות מהותית של המתקשר, ידיעת הצד השני על הטעות, ותנאי חוזה גרועים במידה בלתי סבירה מן המקובל.', false, 'שגוי. טעות מהותית וידיעת הצד השני מתייחסים לעילת הטעות (סעיף 14), ולא לעילת העושק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'חוסר תום לב במשא ומתן, קשר סיבתי לנזק, ודרישה לפיצויים.', false, 'שגוי. חוסר תום לב במשא ומתן (סעיף 12) הוא עילה לפיצויים, אך אינו עילת ביטול חוזה בשל פגם ברצון, ואינו כולל את יסודות העושק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'השפעת ייעוץ משפטי על עושק',
    3, 'ראובן, שנקלע למצוקה כלכלית קשה, נאלץ לחתום על חוזה הלוואה בתנאים דרקוניים עם שמעון. לפני החתימה, ראובן קיבל ייעוץ משפטי מעורך דין שהסביר לו את כל תנאי החוזה ואת הסיכונים הכרוכים בו. למרות הייעוץ, ראובן חתם על החוזה. האם קבלת הייעוץ המשפטי שוללת מראובן את האפשרות לטעון לעושק?', 'שאלה זו בוחנת את השפעת קבלת ייעוץ משפטי על טענת עושק. היא מדגישה כי אף שייעוץ משפטי מחליש את הטענה, הוא אינו שולל אותה באופן מוחלט, ובית המשפט יבחן את נסיבות המקרה, כולל עוצמת המצוקה והאם הייעוץ הציע חלופה מעשית.', 'קבלת ייעוץ משפטי לפני חתימה על חוזה נחשבת כגורם המחליש טענות כפייה ועושק, שכן היא מעידה על כך שהמתקשר היה מודע לתנאי החוזה ולסיכונים הכרוכים בו. עם זאת, הפסיקה והספרות המשפטית קובעות כי קבלת ייעוץ אינה שוללת את טענת העושק באופן אוטומטי. בית המשפט יבחן את מכלול הנסיבות, ובכלל זה את עוצמת המצוקה של המתקשר ואת יעילות הייעוץ – האם הייעוץ הציע לראובן פתרון סביר אחר מלבד כניעה לדרישות הצד העושק? אם המצוקה הייתה כה חמורה שלא הייתה לראובן ברירה מעשית, ייתכן שטענת העושק עדיין תתקבל (פרידמן וכהן, חוזים, כרך ב'', עמ'' 14).',
    'ההנחה שייעוץ משפטי הוא ''מגן קסם'' מפני טענות פגם ברצון. יש לזכור כי גם לאחר ייעוץ, מצוקה קיצונית עדיין יכולה לפגוע ברצון החופשי.', '["עושק", "ייעוץ משפטי", "מצוקה כלכלית", "פגם ברצון", "סעיף 18 לחוק החוזים", "גמירת דעת"]'::jsonb, '**וריאציה 1 — ייעוץ שלא הציע חלופה:** אדם במצוקה קיבל ייעוץ, אך עורך הדין אמר לו שאין לו ברירה אלא לחתום. האם ניתן לטעון לעושק? ← כן, אם הייעוץ לא הציע פתרון סביר מלבד כניעה, הוא לא בהכרח שולל עושק (פרידמן וכהן, חוזים, כרך ב'', עמ'' 14).
**וריאציה 2 — ייעוץ שניתן בחטף:** אדם במצוקה חתם על חוזה לאחר ייעוץ קצר ושטחי שניתן לו במשרד העושק. האם ניתן לטעון לעושק? ← כן, איכות הייעוץ ונסיבות קבלתו רלוונטיות לבחינת השפעתו על גמירת הדעת (ע"א 6234/00 ש.א.פ. בע"מ נ'' בנק לאומי לישראל בע"מ).
**וריאציה 3 — ייעוץ מקיף ומוצלח:** אדם במצוקה קיבל ייעוץ מקיף, ועורך הדין הצליח לשפר את תנאי החוזה באופן משמעותי. האם ניתן לטעון לעושק? ← לא, במקרה כזה, הייעוץ ככל הנראה שלל את יסוד תנאי החוזה הגרועים ואת הפגם ברצון.
**וריאציה 4 — ייעוץ משפטי כהגנה מפני כפייה:** האם קבלת ייעוץ משפטי מחלישה טענת כפייה? ← כן, קבלת ייעוץ משפטי קודם ההסכמה להתקשר בחוזה מחלישה טענה שההתקשרות נעשתה עקב כפייה (ת"א (שלום ת"א) 62131-11-15 ריטה קוברינסקי נ'' עו"ד מיכל הלפרין).', 'ייעוץ משפטי ← מחליש טענת עושק/כפייה ← אך לא שולל אוטומטית ← ביהמ"ש יבחן עוצמת מצוקה ויעילות ייעוץ (האם הוצע פתרון סביר).',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 18", "דניאל פרידמן ונילי כהן חוזים כרך ב (2018) | פרק 17 עושק והשפעה לא הוגנת", "ת\"א (שלום ת\"א) 62131-11-15 ריטה קוברינסקי נ'' עו\"ד מיכל הלפרין (2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, קבלת ייעוץ משפטי תמיד שוללת טענת עושק, שכן היא מעידה על גמירת דעת מלאה.', false, 'שגוי. קבלת ייעוץ משפטי מחלישה את טענת העושק, אך אינה שוללת אותה באופן מוחלט, במיוחד אם המצוקה הייתה כה חמורה שהייעוץ לא הציע חלופה מעשית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, קבלת ייעוץ משפטי אינה שוללת טענת עושק באופן אוטומטי, אך היא מחלישה אותה, ובית המשפט יבחן אם הייעוץ הציע פתרון סביר מלבד כניעה לחוזה.', true, 'נכון. הפסיקה קובעת כי קבלת ייעוץ משפטי מחלישה טענות כפייה ועושק, אך לא שוללת אותן לחלוטין. בית המשפט יבחן את נסיבות המקרה, כולל עוצמת המצוקה והאם הייעוץ הציע חלופה מעשית (פרידמן וכהן, חוזים, כרך ב'', עמ'' 14).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן עורך הדין שייעץ לראובן פעל בחוסר תום לב או בניגוד עניינים.', false, 'שגוי. אף שחוסר תום לב או ניגוד עניינים של עורך הדין עשויים להשפיע, השאלה המרכזית היא האם הייעוץ, כשלעצמו, היה מספק כדי לאפשר לראובן להיחלץ מהמצוקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, שכן עילת העושק מתמקדת במצבו הסובייקטיבי של המתקשר, וייעוץ חיצוני אינו משנה זאת.', false, 'שגוי. אף שעילת העושק מתחשבת במצב הסובייקטיבי, ייעוץ משפטי הוא גורם אובייקטיבי המשפיע על יכולת קבלת ההחלטות ועל מידת הפגם ברצון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'עושק מול כפייה',
    4, 'מהו ההבדל העיקרי בין עילת העושק (סעיף 18 לחוק החוזים) לעילת הכפייה (סעיף 17 לחוק החוזים)?', 'שאלה זו עוסקת בהבחנה בין שתי עילות מרכזיות לביטול חוזה בשל פגם ברצון – עושק וכפייה. היא מדגישה את ההבדלים ביסודות הנדרשים להוכחת כל אחת מהעילות, ובפרט את הדרישה לתנאי חוזה גרועים בעושק לעומת אי-הדרישה לכך בכפייה.', 'עילת הכפייה (סעיף 17 לחוק החוזים) מתמקדת בלחץ בלתי מוצדק שהופעל על המתקשר על ידי הצד השני או אחר מטעמו, בכוח או באיום, אשר גרם לו להתקשר בחוזה. בעילת הכפייה, אין צורך לבחון את תנאי החוזה, ולמתקשר תקום עילת ביטול גם אם תנאי החוזה הוגנים. לעומת זאת, עילת העושק (סעיף 18 לחוק החוזים) מושתתת על שלושה יסודות מצטברים: מצוקה, חולשה שכלית או גופנית, או חוסר ניסיון של המתקשר; ניצול מצב זה על ידי הצד השני; ותנאי חוזה גרועים במידה בלתי סבירה מן המקובל. ההבדל המרכזי הוא שבעושק נדרש יסוד אובייקטיבי של גריעות תנאי החוזה, בעוד שבכפייה לא (ע"א 5806/02 ארביב נ'' קרני; ת"א (מחוזי חיפה) 5137-01-21 מיכאל רדקוב נ'' יניב לוי).',
    'הנטייה לראות את שתי העילות כזהות או כחופפות לחלוטין. יש להבין את ההבחנות הדקות ביניהן, במיוחד לגבי מקור המצוקה והדרישה לתנאי חוזה גרועים.', '["עושק", "כפייה", "פגם ברצון", "סעיף 17 לחוק החוזים", "סעיף 18 לחוק החוזים", "תנאי חוזה גרועים", "לחץ בלתי מוצדק"]'::jsonb, '**וריאציה 1 — מקור המצוקה:** האם בעושק המצוקה חייבת להיגרם על ידי הצד השני? ← לא, המצוקה יכולה לנבוע מגורמים חיצוניים, בעוד שבכפייה הלחץ נגרם על ידי הצד השני (פרידמן וכהן, דיני עשיית עושר ולא במשפט, כרך ב'', פרק 27).
**וריאציה 2 — חומרת הפגם ברצון:** איזה פגם ברצון חמור יותר, בעושק או בכפייה? ← הפגם ברצון בכפייה נחשב חמור יותר, שכן הוא נובע מלחץ אקטיבי (ע"א 5806/02 ארביב נ'' קרני).
**וריאציה 3 — איום בהליכים פליליים:** האם איום בהליכים פליליים יכול להוות כפייה? ← כן, איום כזה יכול להיחשב ככפייה, במיוחד אם הוא לא בתום לב (ע"א 784/81 שפיר נ'' אפל).
**וריאציה 4 — השבה בחוזה שבוטל עקב כפייה/עושק:** מהו הסעד העיקרי בחוזה שבוטל עקב כפייה או עושק? ← הסעד העיקרי הוא השבה הדדית של מה שניתן על פי החוזה (סעיף 21 לחוק החוזים, החל מכוח סעיף 20).', 'עושק (סעיף 18) ← מצוקה + ניצול + תנאים גרועים. כפייה (סעיף 17) ← לחץ בלתי מוצדק (בכוח/איום) + קשר סיבתי. בכפייה אין דרישה לתנאים גרועים.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיפים 17, 18", "ע\"א 5806/02 אריאל ארביב נ'' יעקב קרני, נח(5) 193 (2004)", "ת\"א (מחוזי חיפה) 5137-01-21 מיכאל רדקוב נ'' יניב לוי (2023)", "דניאל פרידמן ואלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך ב (2017) | פרק 27: עושק והשפעה בלתי הוגנת", "ע\"א 784/81 ישראל שפיר נ'' מרטין אפל, לט(4) 149 (1985)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בעושק נדרש שהצד השני יהיה אחראי למצוקה, ואילו בכפייה לא.', false, 'שגוי. ההפך הוא הנכון: בכפייה נדרש שהלחץ יופעל על ידי הצד השני, ואילו בעושק המצוקה יכולה לנבוע מגורמים חיצוניים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בעושק נדרש שתנאי החוזה יהיו גרועים במידה בלתי סבירה, ואילו בכפייה לא נדרש תנאי זה.', true, 'נכון. זהו הבדל מהותי בין שתי העילות. עילת העושק דורשת יסוד אובייקטיבי של גריעות תנאי החוזה, בעוד שעילת הכפייה מתמקדת בפגם ברצון הנובע מהלחץ, ללא קשר להוגנות תנאי החוזה (ע"א 5806/02 ארביב נ'' קרני).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כפייה מאפשרת ביטול חוזה רק אם הופעל איום פיזי, בעוד עושק כולל גם איום כלכלי.', false, 'שגוי. כפייה יכולה לכלול גם איום כלכלי (לחץ כלכלי פסול), בעוד שעושק אינו דורש איום כלל, אלא ניצול מצוקה קיימת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'עושק הוא עילה לביטול חוזה, ואילו כפייה היא עילה לפיצויים בלבד.', false, 'שגוי. גם עושק וגם כפייה הן עילות לביטול חוזה בשל פגם בכריתתו.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 35, '2022-W-S-Q35';
END
$$;

