  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '2783fb1a-ec46-4335-82a7-1fcdd7adf44d'::uuid;
  v_ang_1 uuid := '9382416d-4640-4cc9-b98c-63e691a50373'::uuid;
  v_ang_2 uuid := '4eb04a1c-26ae-4f6a-8933-fc1d504ba3a9'::uuid;
  v_ang_3 uuid := '9a48b52c-b7b4-4273-9759-d4fbd25cd4c8'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q36';
