  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q36', v_chapter_id, v_subtopic_id, 'לפני שנים רבות ביצע פלוני, אזרח ארצות הברית ותושב מדינת ניו יורק המחזיק גם באזרחות ישראלית, עבירות מין במדינת ניו יורק בפלונית, קטינה, אזרחית ותושבת ישראל ששהתה בביקור במדינת ניו יורק. לפני חודש נודע לפלונית כי פלוני נמצא בביקור בישראל. היא פנתה לתחנת המשטרה והגישה נגדו תלונה בגין המעשים שביצע בה לפני שנים רבות בעת ביקורה האמור במדינת ניו יורק. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 36}'::jsonb, 'שאלה זו בוחנת את תחולת דיני העונשין של ישראל על עבירות חוץ, ובפרט את התנאים הקבועים בסעיף 14(ב) לחוק העונשין, התשל"ז-1977. היא מתמקדת בדרישת ''הפליליות הכפולה'' ובפרשנות המונח ''סייג לאחריות פלילית'' בהקשר של התיישנות עבירה לפי הדין הזר.', 'סעיף 14(ב) לחוק העונשין קובע תנאים מצטברים לתחולת דיני העונשין של ישראל על עבירת חוץ שנעברה בשטח מדינה אחרת נגד אזרח ישראלי או תושב ישראל. אחד התנאים הוא ש''אין חל לגבי העבירה סייג לאחריות פלילית לפי דיני אותה מדינה'' (סעיף 14(ב)(2)). בית המשפט העליון, ברע"פ 5717/15, קבע כי התיישנות שחלה על עבירה שבוצעה במדינה זרה מהווה ''סייג לאחריות פלילית'' במובן סעיף זה. לפיכך, אם העבירות התיישנו לפי דיני מדינת ניו יורק, דיני העונשין של ישראל לא יחולו, ולא תהיה סמכות שיפוט בישראל.', 'הטעות הנפוצה היא להניח כי אם העבירה לא התיישנה לפי הדין הישראלי, קיימת סמכות שיפוט, תוך התעלמות מהדרישה המפורשת להתחשב בסייגים לאחריות פלילית לפי הדין הזר.',
    '["תחולה אקסטרה-טריטוריאלית", "סמכות שיפוט בינלאומית", "חוק העונשין", "סעיף 14", "פליליות כפולה", "סייג לאחריות פלילית", "התיישנות עבירה", "כיבוד הדדי בין מדינות"]'::jsonb, '**וריאציה 1 — עבירה נגד ישראלי בחו"ל:** האם ישראל יכולה להעמיד לדין אזרח ישראלי שביצע עבירה נגד אזרח ישראלי אחר בחו"ל, אם העבירה התיישנה במדינה הזרה? ← לא, אם העבירה התיישנה לפי דיני המדינה הזרה, היא מהווה ''סייג לאחריות פלילית'' לפי סעיף 14(ב)(2) לחוק העונשין, ולכן דיני העונשין של ישראל לא יחולו (רע"פ 5717/15).
**וריאציה 2 — חשיבות הדין הזר:** מדוע הדין הישראלי מתחשב בהתיישנות לפי הדין הזר בעבירות חוץ? ← מתוך כיבוד הדדי בין מדינות והנחה שמדינת הביצוע מספקת הגנה נאותה לערכים החברתיים, וכן כדי למנוע פגיעה בציפייה לגיטימית של מבצע העבירה (רע"פ 5717/15).
**וריאציה 3 — פליליות כפולה:** מהי דרישת הפליליות הכפולה בהקשר זה? ← המעשה צריך להוות עבירה גם לפי הדין הישראלי וגם לפי הדין הזר, וכן שלא יחול לגביו סייג לאחריות פלילית לפי הדין הזר (סעיף 14(ב)(1) ו-(2) לחוק העונשין).
**וריאציה 4 — עונש חמור:** האם ניתן להטיל על פלוני עונש חמור יותר מזה שבניו יורק? ← לא, סעיף 14(ג) לחוק העונשין קובע שלא יוטל עונש חמור מזה שניתן היה להטיל לפי דיני המדינה בה נעברה העבירה.', 'עבירת חוץ נגד ישראלי (סעיף 14) → תחולת הדין הישראלי מותנית בפליליות כפולה ובהיעדר סייג לאחריות פלילית לפי הדין הזר → התיישנות לפי הדין הזר נחשבת לסייג כזה (רע"פ 5717/15).', '["סעיף 14 לחוק העונשין, תשל\"ז-1977", "רע\"פ 5717/15 מדינת ישראל נ'' פלוני (24.11.2015)", "ת\"פ (שלום ירושלים) 34003-09-14 מדינת ישראל נ'' פלוני (18.5.2015)", "ע\"פ (מחוזי ירושלים) 43019-05-15 מדינת ישראל נ'' פלוני (21.7.2015)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''sex_offenses'' | classifier_note: US-Israeli dual national committed sex offense in NY against Israeli minor — extraterritorial jurisdiction in penal law | source_review_note: השאלה עוסקת בתחולה אקסטרה-טריטוריאלית של דיני העונשין הישראליים, נושא המצוי בליבת דיני העונשין (חוק העונשין, פרק ב''). נושא זה אינו מיוצג באופן ישיר ברשימת תתי הנושאים הקיימת תחת פרק ''סדר דין פלילי'' או ''חוקתי + בינלאומי פרטי''. נבחר תת-הנושא ''ערעור פלילי'' כהצבה זמנית, אך יש לשקול הוספת תת-נושא ייעודי כגון ''סמכות בינלאומית'' או ''תחולת דיני העונשין במקום''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בכל מקרה אפשר להעמיד לדין את פלוני במדינת ישראל.', false, 'טענה זו שגויה, שכן תחולת דיני העונשין של ישראל על עבירות חוץ מסויגת בתנאים שונים, כולל דרישת הפליליות הכפולה והיעדר סייג לאחריות פלילית לפי הדין הזר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בכל מקרה אי אפשר להעמיד לדין את פלוני במדינת ישראל.', false, 'טענה זו שגויה, שכן קיימים מקרים בהם דיני העונשין של ישראל יחולו על עבירות חוץ, בכפוף להתקיימות התנאים הקבועים בחוק העונשין, כגון סעיפים 14 ו-15.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אפשר להעמיד את פלוני לדין בישראל אם העבירות לא התיישנו לפי הדין הישראלי, גם אם התיישנו לפי דיני מדינת ניו יורק.', false, 'טענה זו שגויה, שכן הפסיקה קבעה כי התיישנות העבירה לפי דיני המדינה הזרה מהווה ''סייג לאחריות פלילית'' השולל את תחולת הדין הישראלי, גם אם העבירה לא התיישנה לפי הדין הישראלי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אפשר להעמיד את פלוני לדין בישראל רק אם העבירות לא התיישנו גם לפי דיני מדינת ניו יורק וגם לפי הדין הישראלי.', true, 'זוהי התשובה הנכונה. סעיף 14(ב)(2) לחוק העונשין קובע כי דיני העונשין של ישראל יחולו על עבירת חוץ רק אם ''אין חל לגבי העבירה סייג לאחריות פלילית לפי דיני אותה מדינה''. הפסיקה קבעה כי התיישנות לפי הדין הזר נחשבת לסייג כזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחולה פרסונלית אקטיבית',
    1, 'ראובן, אזרח ישראלי, ביצע עבירת הונאה חמורה (פשע) בגרמניה, שאינה קשורה לאזרח ישראלי אחר. העבירה התיישנה לפי הדין הגרמני, אך לא לפי הדין הישראלי. ראובן שב לישראל. האם ניתן להעמיד את ראובן לדין בישראל בגין עבירת ההונאה?', 'שאלה זו בוחנת את תחולת דיני העונשין של ישראל על עבירות חוץ שבוצעו על ידי אזרח ישראלי (תחולה פרסונלית-אקטיבית) לפי סעיף 15 לחוק העונשין. היא מדגישה את הקשר בין סעיף 15 לסייגים הקבועים בסעיף 14(ב), ובפרט את דרישת היעדר סייג לאחריות פלילית לפי הדין הזר, הכוללת התיישנות.', 'סעיף 15(א) לחוק העונשין קובע כי דיני העונשין של ישראל יחולו על עבירת חוץ מסוג פשע או עוון שנעברה בידי אדם שהיה אזרח ישראלי או תושב ישראל. סעיף 15(ב) מפנה לסייגים הקבועים בסעיף 14(ב) ו-(ג), ובכללם התנאי שבסעיף 14(ב)(2) – ''אין חל לגבי העבירה סייג לאחריות פלילית לפי דיני אותה מדינה''. הפסיקה קבעה כי התיישנות העבירה לפי הדין הזר נחשבת לסייג כזה (רע"פ 5717/15). לפיכך, אם העבירה התיישנה בגרמניה, לא ניתן להעמיד את ראובן לדין בישראל.',
    'הטעות הנפוצה היא לחשוב שתחולה פרסונלית-אקטיבית מעניקה לישראל סמכות שיפוט בלתי מסויגת, או שהחריגים בסעיף 15(ב) מבטלים את כלל הסייגים שבסעיף 14(ב).', '["חוק העונשין", "סעיף 15", "תחולה פרסונלית-אקטיבית", "עבירת חוץ", "סייג לאחריות פלילית", "התיישנות עבירה"]'::jsonb, '**וריאציה 1 — עבירת פשע בחו"ל:** ראובן, אזרח ישראלי, ביצע פשע בחו"ל. האם ישראל יכולה להעמיד אותו לדין? ← כן, בכפוף לתנאי סעיף 15 לחוק העונשין, כולל הסייגים שבסעיף 14(ב).

**וריאציה 2 — התיישנות בחו"ל:** אם העבירה התיישנה במדינה הזרה, האם זה משפיע על סמכות ישראל? ← כן, התיישנות לפי הדין הזר נחשבת ל''סייג לאחריות פלילית'' לפי סעיף 14(ב)(2), השולל את תחולת הדין הישראלי (רע"פ 5717/15).
**וריאציה 3 — חריגים בסעיף 15(ב):** האם יש מקרים בהם סעיף 15(ב) מאפשר העמדה לדין גם אם אין פליליות כפולה? ← כן, עבור עבירות ספציפיות המנויות בסעיף 15(ב), אין דרישה לפליליות כפולה (סעיף 14(ב)(1)), אך עדיין נדרש היעדר סייג לאחריות פלילית לפי הדין הזר (סעיף 14(ב)(2)).
**וריאציה 4 — עונש חמור:** האם ניתן להטיל על ראובן עונש חמור יותר מזה שבגרמניה? ← לא, סעיף 14(ג) (החל גם על סעיף 15) קובע שלא יוטל עונש חמור מזה שניתן היה להטיל לפי דיני המדינה בה נעברה העבירה.', 'תחולה פרסונלית-אקטיבית (סעיף 15) → חלה על פשע או עוון שבוצעו על ידי אזרח/תושב ישראלי בחו"ל → בכפוף לסייגים שבסעיף 14(ב), כולל התיישנות לפי הדין הזר.',
    '["סעיף 15 לחוק העונשין, תשל\"ז-1977", "סעיף 14 לחוק העונשין, תשל\"ז-1977", "רע\"פ 5717/15 מדינת ישראל נ'' פלוני (24.11.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שראובן אזרח ישראלי והעבירה היא פשע, ואין חשיבות להתיישנות לפי הדין הגרמני.', false, 'טענה זו שגויה. גם בתחולה פרסונלית-אקטיבית (סעיף 15 לחוק העונשין), חלים הסייגים שבסעיף 14(ב), ובכללם היעדר סייג לאחריות פלילית לפי הדין הזר, הכולל התיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שהעבירה התיישנה לפי הדין הגרמני, וזה מהווה סייג לאחריות פלילית גם לעניין תחולת הדין הישראלי.', true, 'זוהי התשובה הנכונה. סעיף 15(ב) לחוק העונשין מפנה לסייגים שבסעיף 14(ב), ובכללם סעיף 14(ב)(2) הקובע כי לא יחולו דיני העונשין של ישראל אם חל סייג לאחריות פלילית לפי דיני המדינה הזרה, והתיישנות נחשבת לסייג כזה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם העבירה נחשבת לעבירה גם לפי הדין הגרמני, ללא קשר להתיישנות.', false, 'טענה זו חלקית. אמנם נדרשת פליליות כפולה (המעשה עבירה גם לפי הדין הזר), אך גם היעדר סייג לאחריות פלילית לפי הדין הזר הוא תנאי מצטבר, והתיישנות היא סייג כזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן העבירה היא אחת מהעבירות המנויות בסעיף 15(ב) לחוק העונשין, שאז אין דרישה לפליליות כפולה.', false, 'טענה זו שגויה. סעיף 15(ב) אכן קובע חריג לדרישת הפליליות הכפולה (סעיף 14(ב)(1)) עבור עבירות מסוימות, אך הוא אינו מבטל את הדרישה להיעדר סייג לאחריות פלילית לפי הדין הזר (סעיף 14(ב)(2)).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת ''סייג לאחריות פלילית''',
    2, 'מהי הפרשנות הנכונה למונח ''סייג לאחריות פלילית לפי דיני אותה מדינה'' הקבוע בסעיף 14(ב)(2) לחוק העונשין, התשל"ז-1977?', 'שאלה זו מתמקדת בפרשנות המונח ''סייג לאחריות פלילית'' בסעיף 14(ב)(2) לחוק העונשין, שהוא תנאי מרכזי לתחולת הדין הישראלי על עבירות חוץ. היא בוחנת את ההלכה הפסוקה בנוגע לשאלה האם התיישנות עבירה לפי הדין הזר נכללת בהגדרה זו.', 'בית המשפט העליון, ברע"פ 5717/15, קבע כי התיישנות שחלה על עבירה שבוצעה במדינה זרה מהווה ''סייג לאחריות פלילית לפי דיני אותה מדינה'' במובן סעיף 14(ב)(2) לחוק העונשין. פירוש זה מתיישב עם תכליות החוק ועקרונות של כיבוד הדדי בין מדינות, ומוביל למסקנה כי במצב כזה נשללת תחולת דיני העונשין של ישראל על העבירה הנטענת, וממילא נשללת גם סמכות השיפוט של מערכת המשפט הישראלית.',
    'הבלבול בין סייגים מהותיים לסייגים דיוניים, וההנחה שרק סייגים מהותיים נכללים במונח ''סייג לאחריות פלילית''.', '["סייג לאחריות פלילית", "חוק העונשין", "סעיף 14(ב)(2)", "התיישנות עבירה", "פליליות כפולה", "כיבוד הדדי"]'::jsonb, '**וריאציה 1 — סייג מהותי:** האם הגנה עצמית לפי הדין הזר היא ''סייג לאחריות פלילית''? ← כן, זהו סייג מהותי המונע אחריות פלילית.
**וריאציה 2 — סייג דיוני:** האם התיישנות לפי הדין הזר היא ''סייג לאחריות פלילית''? ← כן, הפסיקה קבעה שהתיישנות היא סייג כזה (רע"פ 5717/15).
**וריאציה 3 — חוסר פליליות:** האם מעשה שאינו עבירה כלל לפי הדין הזר הוא ''סייג לאחריות פלילית''? ← לא, זה נופל תחת סעיף 14(ב)(1) – דרישת הפליליות הכפולה, ולא תחת סעיף 14(ב)(2).
**וריאציה 4 — סייג ישראלי:** האם סייג לאחריות פלילית לפי הדין הישראלי רלוונטי לסעיף 14(ב)(2)? ← לא, הסעיף מתייחס במפורש ל''דיני אותה מדינה'', כלומר לדין הזר.', '''סייג לאחריות פלילית'' בסעיף 14(ב)(2) → כולל סייגים מהותיים ודיוניים (כמו התיישנות) לפי הדין הזר → שולל תחולת הדין הישראלי (רע"פ 5717/15).',
    '["סעיף 14 לחוק העונשין, תשל\"ז-1977", "רע\"פ 5717/15 מדינת ישראל נ'' פלוני (24.11.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המונח מתייחס רק לסייגים מהותיים לאחריות פלילית, כגון הגנה עצמית או צורך, ואינו כולל סייגים דיוניים כמו התיישנות.', false, 'טענה זו שגויה. הפסיקה קבעה כי המונח כולל גם סייגים דיוניים כמו התיישנות, ולא רק סייגים מהותיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המונח כולל כל הוראה בדין הזר המונעת העמדה לדין, בין אם היא מהותית (כגון הגנה עצמית) ובין אם היא דיונית (כגון התיישנות).', true, 'זוהי התשובה הנכונה. בית המשפט העליון קבע כי התיישנות לפי הדין הזר נחשבת ל''סייג לאחריות פלילית'' במובן סעיף 14(ב)(2) לחוק העונשין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המונח מתייחס רק למקרים בהם המעשה אינו מהווה עבירה כלל לפי הדין הזר, ולא לסייגים המונעים העמדה לדין על עבירה קיימת.', false, 'טענה זו שגויה. המונח ''סייג לאחריות פלילית'' שונה מדרישת ''היא עבירה גם לפי דיני אותה מדינה'' (סעיף 14(ב)(1)), והוא מתייחס למצבים בהם קיימת עבירה אך לא ניתן לממש את האחריות הפלילית בגינה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'המונח מתייחס רק לסייגים הקבועים בחוק העונשין הישראלי, ולא לסייגים הקבועים בדין הזר.', false, 'טענה זו שגויה. סעיף 14(ב)(2) מתייחס במפורש ל''דיני אותה מדינה'', כלומר לדין הזר, ולא לדין הישראלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריג: עבירות נגד המדינה או העם היהודי',
    3, 'דני, אזרח ישראלי, ביצע בצרפת עבירה של תקיפת יהודים על רקע אנטישמי. העבירה התיישנה לפי הדין הצרפתי. האם ניתן להעמיד את דני לדין בישראל בגין עבירה זו?', 'שאלה זו עוסקת בחריג לתנאי התחולה השיורית של הדין הישראלי על עבירות חוץ, כפי שנקבע בסעיף 13 לחוק העונשין. סעיף זה קובע תחולה רחבה יותר לעבירות בעלות זיקה מיוחדת למדינת ישראל או לעם היהודי, ללא כפיפות לדרישת הפליליות הכפולה או לסייגים לאחריות פלילית לפי הדין הזר.', 'סעיף 13(ב)(2) לחוק העונשין קובע כי דיני העונשין של ישראל יחולו על עבירות חוץ נגד חיי יהודי, גופו, בריאותו, חירותו או רכושו, באשר הוא יהודי. בניגוד לסעיפים 14 ו-15, תחולת דיני העונשין של ישראל על עבירות לפי סעיף 13 אינה מסויגת בתנאים הקבועים בסעיף 14(ב), ובכלל זה דרישת הפליליות הכפולה או היעדר סייג לאחריות פלילית לפי הדין הזר. לכן, גם אם העבירה התיישנה לפי הדין הצרפתי, ניתן להעמיד את דני לדין בישראל.',
    'הטעות הנפוצה היא להחיל את כלל הסייגים של סעיף 14(ב) גם על עבירות לפי סעיף 13, למרות שאלו מהוות חריג מפורש.', '["חוק העונשין", "סעיף 13", "תחולה אוניברסלית", "עבירות נגד העם היהודי", "פליליות כפולה", "סייג לאחריות פלילית"]'::jsonb, '**וריאציה 1 — עבירה אנטישמית:** האם עבירה אנטישמית בחו"ל כפופה להתיישנות לפי הדין הזר? ← לא, עבירות לפי סעיף 13 לחוק העונשין אינן כפופות לסייגים של הדין הזר (למשל, התיישנות).
**וריאציה 2 — עבירה נגד ביטחון המדינה:** האם עבירה נגד ביטחון המדינה שבוצעה בחו"ל כפופה לדרישת פליליות כפולה? ← לא, עבירות לפי סעיף 13(א) לחוק העונשין אינן כפופות לדרישת פליליות כפולה.
**וריאציה 3 — עונש חמור:** האם ניתן להטיל עונש חמור יותר מזה שבמדינה הזרה על עבירה לפי סעיף 13? ← כן, סעיף 14(ג) המגביל את העונש אינו חל על עבירות לפי סעיף 13.
**וריאציה 4 — אזרחות העבריין:** האם אזרחות העבריין רלוונטית לתחולת סעיף 13? ← לא, סעיף 13 חל ללא קשר לאזרחות או תושבות העבריין, כל עוד העבירה היא נגד המדינה או העם היהודי.', 'עבירות לפי סעיף 13 (נגד המדינה/העם היהודי) → תחולה רחבה ללא סייגים של הדין הזר (פליליות כפולה, התיישנות) → עונש לפי דיני ישראל.',
    '["סעיף 13 לחוק העונשין, תשל\"ז-1977", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | עבירות נגד המדינה או העם היהודי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מכיוון שהעבירה התיישנה לפי הדין הצרפתי, וזה מהווה סייג לאחריות פלילית.', false, 'טענה זו שגויה. עבירות לפי סעיף 13 לחוק העונשין אינן מסויגות בתנאי היעדר סייג לאחריות פלילית לפי הדין הזר, ולכן התיישנות בצרפת אינה מונעת העמדה לדין בישראל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, מכיוון שמדובר בעבירה נגד יהודים באשר הם יהודים, ולכן דיני העונשין של ישראל חלים ללא סייגים של הדין הזר.', true, 'זוהי התשובה הנכונה. סעיף 13(ב)(2) לחוק העונשין קובע תחולה לדיני העונשין של ישראל על עבירות חוץ נגד חיי יהודי, גופו, בריאותו, חירותו או רכושו, באשר הוא יהודי. תחולה זו אינה מסויגת בתנאים הקבועים בסעיף 14(ב), כולל דרישת היעדר סייג לאחריות פלילית לפי הדין הזר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם העבירה נחשבת לעבירה גם לפי הדין הצרפתי, ללא קשר להתיישנות.', false, 'טענה זו שגויה. עבירות לפי סעיף 13 לחוק העונשין אינן כפופות לדרישת הפליליות הכפולה (סעיף 14(ב)(1)), ולכן אין חובה שהמעשה יהווה עבירה גם לפי הדין הצרפתי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן דני היה תושב ישראל בעת ביצוע העבירה, ולא רק אזרח ישראלי.', false, 'טענה זו שגויה. סעיף 13 לחוק העונשין חל על עבירות חוץ מסוימות ללא קשר לאזרחות או תושבות העבריין, ובוודאי שאינו דורש תושבות בנוסף לאזרחות במקרה זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הסגרה מול העמדה לדין בישראל',
    4, 'מהו ההבדל העיקרי בין דרישת ''הפליליות הכפולה'' בהליכי הסגרה לבין דרישה זו בהקשר של העמדה לדין בישראל על עבירת חוץ לפי סעיף 14 לחוק העונשין?', 'שאלה זו משווה בין דרישת ''הפליליות הכפולה'' בהליכי הסגרה לבין דרישה זו בהקשר של העמדה לדין בישראל על עבירת חוץ לפי סעיף 14 לחוק העונשין. היא מדגישה את הדמיון בפרשנות המונח ''סייג לאחריות פלילית'' בשני ההקשרים, ובפרט את מעמד ההתיישנות.', 'עיקרון ''הפליליות הכפולה'' בדיני ההסגרה דורש כי המעשה המיוחס למבוקש יהווה עבירה גם לפי דיני המדינה המתבקשת, וכי תתקיים יכולת ממשית להעמידו לדין. בית המשפט העליון קבע בעניין מונדרוביץ כי עיקרון זה אינו מוגשם במלואו כאשר במדינה המתבקשת (ישראל) לא ניתן להעמיד את האדם לדין פלילי בשל התיישנות העבירות המיוחסות לו. פרשנות זו דומה לפרשנות שניתנה ל''סייג לאחריות פלילית'' בסעיף 14(ב)(2) לחוק העונשין, לפיה התיישנות לפי הדין הזר שוללת את תחולת הדין הישראלי (רע"פ 5717/15).',
    'הטעות הנפוצה היא להפריד באופן מוחלט בין דיני הסגרה לבין דיני תחולה אקסטרה-טריטוריאלית, מבלי להכיר בדמיון בפרשנות עקרונות יסוד כמו ''פליליות כפולה'' ו''סייג לאחריות פלילית''.', '["הסגרה", "פליליות כפולה", "סייג לאחריות פלילית", "חוק העונשין", "סעיף 14", "התיישנות עבירה"]'::jsonb, '**וריאציה 1 — פליליות כפולה בהסגרה:** מהי דרישת הפליליות הכפולה בהסגרה? ← המעשה צריך להוות עבירה גם במדינה המבקשת וגם במדינה המתבקשת, ושתהיה יכולת ממשית להעמיד לדין בשתיהן (ע"פ 2144/08 מונדרוביץ).
**וריאציה 2 — פליליות כפולה בעבירת חוץ:** מהי דרישת הפליליות הכפולה לפי סעיף 14 לחוק העונשין? ← המעשה צריך להוות עבירה גם לפי הדין הישראלי וגם לפי הדין הזר, ושלא יחול סייג לאחריות פלילית לפי הדין הזר (סעיף 14(ב)(1) ו-(2)).
**וריאציה 3 — התיישנות בהסגרה:** האם התיישנות בישראל מונעת הסגרה? ← כן, אם העבירה התיישנה בישראל, לא ניתן להסגיר את המבוקש (ע"פ 2144/08 מונדרוביץ).
**וריאציה 4 — התיישנות בעבירת חוץ:** האם התיישנות במדינה הזרה מונעת העמדה לדין בישראל? ← כן, התיישנות לפי הדין הזר נחשבת ל''סייג לאחריות פלילית'' לפי סעיף 14(ב)(2), השולל את תחולת הדין הישראלי (רע"פ 5717/15).', 'פליליות כפולה בהסגרה ובעבירות חוץ → דורשת שהמעשה יהווה עבירה בשתי המדינות ושתהיה יכולת ממשית להעמיד לדין → התיישנות באחת המדינות שוללת את היכולת.',
    '["ע\"פ 2144/08 אברהם מונדרוביץ נ'' מדינת ישראל (14.1.2010)", "רע\"פ 5717/15 מדינת ישראל נ'' פלוני (24.11.2015)", "סעיף 14 לחוק העונשין, תשל\"ז-1977"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בהליכי הסגרה נדרשת פליליות כפולה רק בממד הגדרת העבירה, בעוד שבהעמדה לדין בישראל נדרשת פליליות כפולה גם בממד מיקום העבירה.', false, 'טענה זו שגויה. דרישת הפליליות הכפולה בהליכי הסגרה יכולה לכלול גם את ממד מיקום העבירה, בהתאם לאמנת ההסגרה הרלוונטית, והיא אינה מוגבלת רק לממד הגדרת העבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בהליכי הסגרה נדרשת פליליות אפקטיבית בשתי המדינות, בעוד שבהעמדה לדין בישראל די בפליליות היפותטית במדינת הימצאותו של העושה.', false, 'טענה זו שגויה. ההבחנה בין פליליות אפקטיבית להיפותטית רלוונטית לשאלה האם המעשה מהווה עבירה, אך אינה ההבדל העיקרי בין הסגרה להעמדה לדין בישראל בהקשר של פליליות כפולה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בהליכי הסגרה, דרישת הפליליות הכפולה כוללת גם את היכולת הממשית להעמיד לדין במדינה המתבקשת (למשל, היעדר התיישנות), בדומה לדרישה לפי סעיף 14(ב)(2) לחוק העונשין.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי עיקרון הפליליות הכפולה בהסגרה אינו מוגשם במלואו כאשר במדינה המתבקשת (ישראל) לא ניתן להעמיד את האדם לדין בשל התיישנות, בדומה לפרשנות סעיף 14(ב)(2) לחוק העונשין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בהליכי הסגרה, דרישת הפליליות הכפולה מתייחסת רק לכך שהמעשה מהווה עבירה בשתי המדינות, ללא קשר לסייגים לאחריות פלילית או התיישנות.', false, 'טענה זו שגויה. דרישת הפליליות הכפולה בהליכי הסגרה רחבה יותר וכוללת גם את היכולת הממשית להעמיד לדין, לרבות היעדר התיישנות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 36, '2022-W-S-Q36';
END
$$;

