  v_ang_0 uuid := '77455ad2-c082-4f8f-9f73-7333025d7daf'::uuid;
  v_ang_1 uuid := 'd71fd3d7-0df6-480e-9b52-5152b0b86ab1'::uuid;
  v_ang_2 uuid := '21189223-994c-4d67-8997-91c4e5d9a241'::uuid;
  v_ang_3 uuid := 'ac700de8-a893-4f9e-9ac0-ad2df6a76cd0'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q37';
