  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q37', v_chapter_id, v_subtopic_id, 'ביום 1.1.2020 נגזר דינו של יצחק והוטלו עליו 10 חודשי מאסר בפועל ו-3 חודשי מאסר, שלא ירוצו אלא אם יעבור תוך 3 שנים מיום שחרורו ממאסר עבירה של איומים (להלן: ההרשעה הקודמת). יצחק הגיש ערעור על גזר הדין ובית המשפט עיכב את ריצוי העונש עד למתן פסק דין בערעור. ביום 1.12.2020, בעת שגזר הדין היה מעוכב, ובטרם נידון הערעור בהרשעה הקודמת, עבר יצחק עבירה נוספת של איומים, הועמד לדין והורשע (להלן: העבירה הנוכחית). בטיעוניו לעונש ביקש התובע להפעיל את המאסר על תנאי שהוטל על יצחק בהרשעה הקודמת. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 37}'::jsonb, 'שאלה זו עוסקת במועד תחילת תקופת המאסר על תנאי, ובפרט במצב שבו עונש המאסר בפועל עוכב בשל ערעור. היא בוחנת את פרשנות סעיף 52(ג) לחוק העונשין, התשל"ז-1977, ואת ההלכה הפסוקה בעניין זה, בדגש על הלכת במנוקלר, הקובעת כי בתקופת עיכוב ביצוע עונש מאסר, המאסר על תנאי אינו חל.', 'סעיף 52(ג) לחוק העונשין קובע כי תקופת התנאי תתחיל ביום מתן גזר הדין, ואם הנידון נושא אותו זמן עונש מאסר – ביום שחרורו מן המאסר. הלכת במנוקלר (ע"פ 7510/00) קבעה כי ככלל, בעת תקופת עיכוב ביצוע עונש המאסר לפי סעיף 87 לחוק העונשין, לא תחול תקופת התנאי השיפוטית, ואף לא תקופת התנאי הסטטוטורית, אלא אם כן קבע בית המשפט שגזר את העונש אחרת במפורש. הטעם לכך הוא שעונשי המאסר בפועל ועל תנאי מהווים יחידה עונשית אחת, ודחיית ביצוע המאסר בפועל מצדיקה גם דחיית המאסר על תנאי, וכן כדי למנוע פיצול של תקופת התנאי ואי-בהירות. במקרה הנדון, יצחק ביצע את העבירה הנוספת בתקופה שבה עונש המאסר בפועל היה מעוכב, ולכן המאסר על תנאי לא חל ולא ניתן להפעילו.', 'הטעות הנפוצה היא להניח כי תקופת התנאי מתחילה תמיד ביום מתן גזר הדין, או שהיא חלה גם בתקופת עיכוב הביצוע, מבלי להבחין בין סוגי התקופות השונות (שיפוטית, סטטוטורית) ובין מצבים של עיכוב ביצוע לבין ריצוי מאסר בפועל.',
    '["מאסר על תנאי", "תקופת תנאי", "עיכוב ביצוע", "הלכת במנוקלר", "סעיף 52(ג) לחוק העונשין", "הפעלת תנאי", "תקופת תנאי שיפוטית", "תקופת תנאי סטטוטורית"]'::jsonb, '**וריאציה 1 — עיכוב ביצוע:** האם מאסר על תנאי חל בתקופת עיכוב ביצוע עונש מאסר בפועל? ← לא, הלכת במנוקלר קבעה כי בתקופה זו לא חלה תקופת התנאי השיפוטית ואף לא הסטטוטורית (ע"פ 7510/00 במנוקלר).
**וריאציה 2 — הוראה מפורשת:** האם בית המשפט יכול לקבוע שהתנאי יחול בתקופת עיכוב הביצוע? ← כן, אם בית המשפט שגזר את העונש קבע זאת במפורש (ע"פ 7510/00 במנוקלר).
**וריאציה 3 — תחילת תנאי כללית:** מתי מתחילה תקופת תנאי ככלל? ← ביום מתן גזר הדין, אלא אם הנידון נושא מאסר בפועל, שאז מיום שחרורו (סעיף 52(ג) לחוק העונשין).
**וריאציה 4 — עבודות שירות:** האם הלכת במנוקלר חלה גם על מאסר בעבודות שירות? ← לא, במקרה של הפסקת עבודות שירות, התנאי יכול לחול בתקופת הביניים (רע"פ 3209/24 פלוני), בניגוד לעיכוב ביצוע מאסר בפועל בכלא.', 'עיכוב ביצוע מאסר בפועל (בשל ערעור) → המאסר על תנאי אינו חל בתקופה זו (הלכת במנוקלר) → אלא אם נקבע אחרת במפורש → מטרתו: שמירה על ודאות ומניעת פיצול התנאי.', '["סעיף 52 לחוק העונשין, תשל\"ז-1977", "ע\"פ 7510/00 אליהו במנוקלר נ'' מדינת ישראל, נו(4) 258 (2002)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (8.2.2022)", "ת\"פ (שלום קריות) 38511-04-19 מדינת ישראל נ'' סרגיי רוזנבוים (15.7.2019)", "רע\"פ 2524114/12 רינה צדוק נ'' מדינת ישראל (22.10.2012)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Activation of suspended sentence after appeal-period stay | source_review_note: השאלה עוסקת במועד תחילת תקופת המאסר על תנאי ובפרט במצב של עיכוב ביצוע עונש מאסר בפועל. נושא זה קשור באופן הדוק לדיני הענישה ולפרשנות חוק העונשין, אך אינו מתאים באופן מושלם לאף אחד מתתי הנושאים הקיימים תחת ''סדר דין פלילי''. ''ערעור פלילי'' נבחר כברירת מחדל בשל הקשר לעיכוב ביצוע עקב ערעור, אך יש לשקול הוספת תת-נושא ייעודי כגון ''דיני ענישה'' או ''מאסר על תנאי''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'המאסר על תנאי אינו חל.', true, 'זוהי התשובה הנכונה. הלכת במנוקלר קבעה כי בתקופת עיכוב ביצוע עונש מאסר, לא תחול תקופת התנאי השיפוטית ואף לא תקופת התנאי הסטטוטורית, אלא אם בית המשפט קבע אחרת במפורש.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'המאסר על תנאי חל, והתקופה נמנית כחלק מתקופת התנאי שהטיל בית המשפט.', false, 'טענה זו שגויה. הלכת במנוקלר קבעה במפורש כי בתקופת עיכוב ביצוע עונש מאסר, המאסר על תנאי אינו חל, וזאת כדי למנוע פיצול של תקופת התנאי וכדי לשמור על ודאות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'המאסר על תנאי חל, והתקופה אינה נמנית בתקופת התנאי שהטיל בית המשפט.', false, 'טענה זו שגויה. המאסר על תנאי אינו חל כלל בתקופת עיכוב הביצוע, ולא רק שאינו נמנה בתקופת התנאי השיפוטית. תקופות התנאי הסטטוטוריות אינן חלות במצב זה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'המאסר על תנאי חל רק אם צוין בכתב האישום הנוכחי כי אם יצחק יורשע יתבקש בית המשפט להפעיל את המאסר על תנאי.', false, 'טענה זו שגויה. שאלת תחולת המאסר על תנאי בתקופת עיכוב הביצוע אינה תלויה בציון בכתב האישום, אלא בהלכה הפסוקה ובפרשנות סעיף 52(ג) לחוק העונשין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחילת תקופת תנאי ללא עיכוב ביצוע',
    1, 'ראובן נידון ל-6 חודשי מאסר על תנאי, שלא ירוצו אלא אם יעבור עבירת רכוש תוך שנתיים מיום מתן גזר הדין. ראובן לא נשא עונש מאסר בפועל. חצי שנה לאחר מתן גזר הדין, ביצע ראובן עבירת רכוש והורשע. האם המאסר על תנאי יופעל?', 'שאלה זו בוחנת את הכלל הבסיסי הקבוע בסעיף 52(ג) לחוק העונשין לעניין מועד תחילת תקופת התנאי. היא מדגישה את ההבחנה בין מצב שבו הנידון אינו נושא עונש מאסר בפועל לבין מצב שבו הוא כן נושא עונש כזה.', 'סעיף 52(ג) לחוק העונשין קובע כי תקופת התנאי תתחיל ביום מתן גזר הדין, אלא אם הנידון נושא באותו זמן עונש מאסר, שאז תחל ביום שחרורו מן המאסר. במקרה זה, ראובן לא נשא עונש מאסר בפועל בעת מתן גזר הדין, ולכן תקופת התנאי החלה ביום מתן גזר הדין. מאחר שביצע את העבירה הנוספת בתוך תקופת התנאי, המאסר על תנאי יופעל.',
    'הטעות הנפוצה היא לבלבל בין הכלל לבין החריג שבסעיף 52(ג), ולהניח שתקופת התנאי תמיד מתחילה מיום השחרור ממאסר, גם כשאין מאסר בפועל.', '["מאסר על תנאי", "תקופת תנאי", "סעיף 52(ג) לחוק העונשין", "מועד תחילת תנאי", "הפעלת תנאי"]'::jsonb, '**וריאציה 1 — ללא מאסר בפועל:** מתי מתחילה תקופת תנאי אם לא נגזר מאסר בפועל? ← ביום מתן גזר הדין (סעיף 52(ג) רישא לחוק העונשין).
**וריאציה 2 — עם מאסר בפועל:** מתי מתחילה תקופת תנאי אם נגזר מאסר בפועל? ← ביום השחרור מן המאסר (סעיף 52(ג) סיפא לחוק העונשין).
**וריאציה 3 — הוראה מפורשת:** האם בית המשפט יכול לקבוע מועד אחר לתחילת התנאי? ← כן, סעיף 52(ג) מאפשר לבית המשפט להורות אחרת.
**וריאציה 4 — עבירה נוספת:** מה קורה אם עבירה נוספת בוצעה לאחר תום תקופת התנאי? ← המאסר על תנאי לא יופעל, שכן התנאי פקע.', 'תקופת תנאי → מתחילה ביום גזר הדין (כלל) ← חריג: מיום שחרור ממאסר (אם נושא מאסר בפועל) → אלא אם נקבע אחרת.',
    '["סעיף 52 לחוק העונשין, תשל\"ז-1977", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | מועד תחילת תקופת התנאי (סעיף 52(ג) רישה)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, המאסר על תנאי יופעל, שכן תקופת התנאי החלה ביום מתן גזר הדין והעבירה בוצעה במהלכה.', true, 'זוהי התשובה הנכונה. סעיף 52(ג) לחוק העונשין קובע כי תקופת התנאי תתחיל ביום מתן גזר הדין, אלא אם הנידון נושא באותו זמן עונש מאסר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, המאסר על תנאי לא יופעל, שכן תקופת התנאי מתחילה רק מיום שחרורו של הנידון ממאסר, גם אם לא נגזר עליו מאסר בפועל.', false, 'טענה זו שגויה. הכלל לפיו תקופת התנאי מתחילה מיום השחרור ממאסר חל רק אם הנידון נושא עונש מאסר בפועל בעת מתן גזר הדין, או אם נגזר עליו מאסר בפועל לצד המאסר על תנאי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם בית המשפט קבע במפורש בגזר הדין שהתנאי יחל מיום מתן גזר הדין.', false, 'טענה זו שגויה. הכלל הוא שתקופת התנאי מתחילה מיום מתן גזר הדין, אלא אם בית המשפט הורה אחרת או אם הנידון נושא עונש מאסר בפועל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שמאסר על תנאי אינו חל על עבירות רכוש קלות.', false, 'טענה זו שגויה. המאסר על תנאי יכול לחול על כל סוג עבירה שנקבעה בגזר הדין, כולל עבירות רכוש, ואין הגבלה על חומרת העבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'פיצול תקופת התנאי',
    2, 'מהי התכלית העיקרית העומדת בבסיס ההלכה לפיה לא ניתן לפצל את תקופת התנאי השיפוטית, כפי שנקבעה בהלכת במנוקלר?', 'שאלה זו עוסקת בתכלית העומדת בבסיס ההלכה המשפטית לפיה לא ניתן לפצל את תקופת התנאי השיפוטית, כפי שנקבעה בהלכת במנוקלר. היא בוחנת את ההיגיון מאחורי הכלל שקובע כי בתקופת עיכוב ביצוע מאסר, המאסר על תנאי אינו חל.', 'הלכת במנוקלר (ע"פ 7510/00) קבעה כי בתקופת עיכוב ביצוע עונש מאסר, לא תחול תקופת התנאי השיפוטית ואף לא תקופת התנאי הסטטוטורית. אחד הטעמים המרכזיים לכך הוא הרצון לשמור על ודאות ובהירות בעיני הנידון ביחס לתחולת התנאי. פיצול תקופת התנאי, כך שחלקו יחול לפני תחילת המאסר בפועל וחלקו לאחר מכן, עלול להביא לאי-בהירות שתפחית מכוחה המרתיע של תקופת תנאי רצופה וברורה. בנוסף, עונשי המאסר בפועל ועל תנאי נתפסים כיחידה עונשית אחת, ודחיית ביצוע המאסר בפועל מצדיקה גם דחיית המאסר על תנאי.',
    'הטעות הנפוצה היא להתמקד רק בהיבט ההרתעתי של המאסר על תנאי, מבלי להבין את החשיבות של ודאות ובהירות עבור הנידון ואת מניעת פיצול התנאי.', '["הלכת במנוקלר", "פיצול תקופת תנאי", "ודאות משפטית", "אפקט הרתעתי", "עיכוב ביצוע", "מאסר על תנאי"]'::jsonb, '**וריאציה 1 — ודאות לנידון:** מדוע חשובה הוודאות לנידון לגבי תקופת התנאי? ← כדי שהתנאי ישמש כגורם מרתיע אפקטיבי, על הנידון לדעת בבירור מתי הוא חל (ע"פ 7510/00 במנוקלר).
**וריאציה 2 — יחידה עונשית אחת:** מהי המשמעות של ראיית מאסר בפועל ומאסר על תנאי כיחידה עונשית אחת? ← דחיית ביצוע המאסר בפועל מצדיקה גם דחיית המאסר על תנאי, כדי למנוע פיצול (ע"פ 7510/00 במנוקלר).
**וריאציה 3 — מניעת פיצול:** מהם הקשיים בפיצול תקופת התנאי? ← פיצול עלול להוביל לאי-בהירות, להפחית את האפקטיביות ההרתעתית ולהתמשך על פני תקופות ארוכות שלא כראוי (ת"פ (שלום רמ'') 62099-03-17).
**וריאציה 4 — חוטא נשכר:** האם התוצאה של אי-החלת התנאי בתקופת עיכוב הביצוע אינה יוצרת ''חוטא נשכר''? ← בית המשפט העליון מודע לקושי זה, אך מעדיף את עקרון הוודאות ומניעת הפיצול (ת"פ (שלום רמ'') 62099-03-17).', 'הלכת במנוקלר → מניעת פיצול תקופת התנאי → לשמירה על ודאות והרתעה → מאסר בפועל ותנאי כיחידה אחת.',
    '["ע\"פ 7510/00 אליהו במנוקלר נ'' מדינת ישראל, נו(4) 258 (2002)", "ת\"פ (שלום רמ'') 62099-03-17 מדינת ישראל נ'' מחמד דאר עאצי (25.5.2017)", "רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (8.2.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'למנוע מצב שבו נאשם ירצה מאסר על תנאי במקביל לריצוי מאסר בפועל, דבר המרוקן את התנאי מתוכן הרתעתי.', false, 'טענה זו שגויה. אמנם התנאי לא חל במקביל למאסר בפועל, אך זו תוצאה של הכלל ולא התכלית העיקרית למניעת פיצול התנאי השיפוטי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לשמור על ודאות ובהירות בעיני הנידון ביחס לתחולת התנאי, ולמנוע מצב של אי-בהירות שתפגע בכוחו המרתיע של התנאי.', true, 'זוהי התשובה הנכונה. בית המשפט העליון הדגיש את חשיבות הוודאות והבהירות עבור הנידון, וכי פיצול התנאי עלול לפגוע באפקטיביות ההרתעתית שלו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'להבטיח שהמאסר על תנאי יופעל תמיד במצטבר למאסר בפועל, ולא בחופף.', false, 'טענה זו שגויה. שאלת הפעלת התנאי במצטבר או בחופף היא שאלה נפרדת, ואינה התכלית העיקרית למניעת פיצול תקופת התנאי השיפוטית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לאפשר לבית המשפט שיקול דעת רחב יותר בהחלטה אם להפעיל את המאסר על תנאי או להאריכו.', false, 'טענה זו שגויה. מניעת פיצול התנאי דווקא מצמצמת את שיקול הדעת במובן של מועד תחולת התנאי, ולא מרחיבה אותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'מאסר בעבודות שירות ותנאי',
    3, 'דוד נידון ל-6 חודשי מאסר בפועל לריצוי בעבודות שירות, וכן ל-6 חודשי מאסר על תנאי, שלא ירוצו אלא אם יעבור עבירת אלימות תוך שנתיים מיום סיום ריצוי עבודות השירות. דוד החל לרצות את עבודות השירות, אך לאחר חודש הפסיק להגיע. חודשיים לאחר מכן, ובטרם ניתנה החלטה שיפוטית על הפסקת עבודות השירות, ביצע דוד עבירת אלימות והורשע. האם המאסר על תנאי יופעל?', 'שאלה זו עוסקת במצב מורכב של תחולת מאסר על תנאי כאשר הנידון מרצה עונש מאסר בדרך של עבודות שירות, ומפסיק את ביצוען. היא בוחנת את ההבחנה בין מאסר בפועל בכלא לבין עבודות שירות, ואת תחולת התנאי בתקופת ביניים שנוצרת עקב הפסקת עבודות השירות.', 'הפסיקה קבעה כי במקרה של נידון שנגזר עליו מאסר על תנאי לצד עונש מאסר בפועל לריצוי בעבודות שירות, תקופת התנאי השיפוטית תחל להימנות רק מיום סיום עבודות השירות (רע"פ 8597/20 אשקר). עם זאת, במקרה של הפסקת עבודות שירות, נוצרת ''תקופת ביניים'' שבה הנידון אינו נמצא במאסר בפועל ואינו מבצע את עבודות השירות. בית המשפט העליון קבע (רע"פ 3209/24 פלוני) כי בתקופה זו, האפקט המרתיע של המאסר על תנאי צריך לחול, ולכן התנאי בר הפעלה. זאת, בניגוד למצב של עיכוב ביצוע מאסר בפועל בכלא (הלכת במנוקלר).',
    'הטעות הנפוצה היא להחיל את הלכת במנוקלר (אי-תחולת תנאי בעיכוב ביצוע) באופן גורף גם על מצבים של עבודות שירות שהופסקו, מבלי להבחין בין הנסיבות השונות.', '["מאסר על תנאי", "עבודות שירות", "סעיף 52(ג) לחוק העונשין", "תקופת ביניים", "הפעלת תנאי", "הלכת אשקר", "הלכת פלוני (רע\"פ 3209/24)"]'::jsonb, '**וריאציה 1 — תחילת תנאי בעבודות שירות:** מתי מתחילה תקופת תנאי אם נגזר מאסר בעבודות שירות? ← ביום סיום עבודות השירות (רע"פ 8597/20 אשקר).
**וריאציה 2 — הפסקת עבודות שירות:** מה קורה אם הנידון מפסיק עבודות שירות וטרם ניתנה החלטה שיפוטית? ← בתקופת הביניים שנוצרת, המאסר על תנאי חל ובר הפעלה (רע"פ 3209/24 פלוני).
**וריאציה 3 — השוואה לבמנוקלר:** האם הלכת במנוקלר חלה על הפסקת עבודות שירות? ← לא, הלכת במנוקלר עוסקת בעיכוב ביצוע מאסר בפועל בכלא, ולא במצב של הפסקת עבודות שירות (רע"פ 3209/24 פלוני).
**וריאציה 4 — תכלית הרתעתית:** מדוע התנאי חל בתקופת הביניים של הפסקת עבודות שירות? ← כדי שהאפקט המרתיע של המאסר על תנאי יחול כאשר הנידון אינו בכלא ואינו מבצע את עונשו (רע"פ 3209/24 פלוני).', 'מאסר בעבודות שירות → תנאי מתחיל בסיום עבודות השירות → אם הופסקו עבודות השירות, התנאי חל בתקופת הביניים → שונה מעיכוב ביצוע מאסר בפועל.',
    '["רע\"פ 58943-09-19 אליאס אשקר נ'' מדינת ישראל (8.2.2022)", "רע\"פ 3209/24 פלוני נ'' מדינת ישראל (13.6.2024)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | מועד תחילת תקופת התנאי (סעיף 52(ג) רישה)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, המאסר על תנאי לא יופעל, שכן תקופת התנאי נקבעה מיום סיום ריצוי עבודות השירות, ומועד זה טרם הגיע.', false, 'טענה זו שגויה. למרות הקביעה בגזר הדין, הפסיקה קבעה כי במקרה של הפסקת עבודות שירות, המאסר על תנאי יכול לחול בתקופת הביניים, שכן הנידון אינו נמצא במאסר בפועל ואינו מבצע את עבודות השירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, המאסר על תנאי יופעל, שכן בתקופת הביניים שבין הפסקת עבודות השירות לבין תחילת ריצוי מאסר בפועל, התנאי חל.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי במצב של הפסקת עבודות שירות, התנאי חל בתקופת הביניים, שכן האפקט המרתיע של המאסר על תנאי צריך לחול כאשר הנידון אינו בכלא ואינו מבצע את עבודות השירות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, המאסר על תנאי לא יופעל, שכן הלכת במנוקלר חלה גם על מאסר בעבודות שירות, ולכן בתקופת עיכוב הביצוע התנאי אינו חל.', false, 'טענה זו שגויה. הלכת במנוקלר עוסקת בעיכוב ביצוע מאסר בפועל בכלא, ולא במצב של הפסקת עבודות שירות, שם הנידון אינו בכלא ואינו מבצע את העונש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם בית המשפט המחוזי יורה על כך במפורש לאחר שמיעת טיעוני הצדדים.', false, 'טענה זו שגויה. שאלת תחולת התנאי במצב זה נקבעת על פי הפסיקה, ואינה דורשת הוראה מפורשת נוספת מבית המשפט המחוזי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הארכת תנאי במקום הפעלה',
    4, 'שרה נידונה ל-4 חודשי מאסר על תנאי, שלא ירוצו אלא אם תעבור עבירת תקיפה תוך שנתיים. שרה ביצעה עבירת תקיפה נוספת, אך בית המשפט המרשיע אותה בעבירה זו לא הטיל עליה עונש מאסר בפועל. האם בית המשפט רשאי להאריך את תקופת התנאי במקום להפעיל את המאסר על תנאי?', 'שאלה זו עוסקת בסמכות בית המשפט להאריך את תקופת התנאי במקום להפעיל את המאסר על תנאי, בהתאם לסעיף 56 לחוק העונשין. היא בוחנת את התנאים המצטברים הנדרשים להפעלת סמכות זו, ובפרט את הדרישה לאי-הטלת עונש מאסר בפועל ואת היותה הרשעה ראשונה בעבירה נוספת.', 'סעיף 56(א) לחוק העונשין קובע כי בית המשפט שהרשיע נאשם בשל עבירה נוספת ולא הטיל עליו בשל אותה עבירה עונש מאסר, רשאי, מטעמים שיירשמו, להאריך את תקופת התנאי או לחדשה לתקופה נוספת שלא תעלה על שנתיים, אם שוכנע שבנסיבות העניין לא יהיה צודק להפעיל את המאסר על תנאי. סעיף 56(ב) מוסיף כי סמכות זו תופעל רק לגבי ההרשעה הראשונה של הנאשם בשל עבירה נוספת. במקרה של שרה, לא הוטל עליה עונש מאסר בפועל בגין עבירת התקיפה הנוספת, ובהנחה שזו הרשעתה הראשונה בעבירה נוספת, בית המשפט רשאי להאריך את התנאי.',
    'הטעות הנפוצה היא לחשוב שחובת ההפעלה לפי סעיף 55 היא מוחלטת, או להתעלם מהתנאים המצטברים להארכת התנאי לפי סעיף 56.', '["מאסר על תנאי", "הארכת תקופת תנאי", "סעיף 56 לחוק העונשין", "עבירה נוספת", "שיקול דעת שיפוטי", "הפעלת תנאי"]'::jsonb, '**וריאציה 1 — תנאים להארכה:** מהם התנאים להארכת תנאי במקום הפעלה? ← אי-הטלת מאסר בפועל בגין העבירה הנוספת, ושהיא הרשעה ראשונה בעבירה נוספת (סעיף 56(א) ו-(ב) לחוק העונשין).
**וריאציה 2 — עונש מאסר:** האם ''עונש מאסר'' בסעיף 56 כולל גם מאסר על תנאי? ← כן, הפסיקה קבעה כי הדיבור ''עונש מאסר'' כולל גם מאסר על תנאי (רבין וואקי, דיני עונשין, כרך ג, עמ'' 58).

**וריאציה 3 — שינוי תנאים:** האם בית המשפט יכול לשנות את תנאי המאסר המותנה בעת הארכה? ← לא, בית המשפט מוסמך להאריך את תקופת התנאי אך אינו מוסמך לשנות את התנאים עצמם (רבין וואקי, דיני עונשין, כרך ג, עמ'' 58).
**וריאציה 4 — מספר הרשעות:** מה קורה אם זו ההרשעה השנייה בעבירה נוספת? ← בית המשפט לא ישתמש בסמכות להאריך את התנאי, אלא יחויב להפעילו (סעיף 56(ב) לחוק העונשין).', 'הארכת תנאי (סעיף 56) → חריג להפעלת תנאי → בתנאי שלא הוטל מאסר בפועל על העבירה הנוספת + הרשעה ראשונה → לא ניתן לשנות את תנאי התנאי.',
    '["סעיף 56 לחוק העונשין, תשל\"ז-1977", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | ה. סעיף 56 - הארכת תקופת התנאי", "רע\"פ 4266861/15 ח''ליל דיב עיסא נ'' הועדה המקומית לתכנון ובניה \"השומרון\" (31.10.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, בית המשפט רשאי להאריך את תקופת התנאי, ובלבד שזו ההרשעה הראשונה של שרה בעבירה נוספת, וכי לא הוטל עליה עונש מאסר בפועל בגין העבירה הנוספת.', true, 'זוהי התשובה הנכונה. סעיף 56(א) ו-(ב) לחוק העונשין קובעים כי בית המשפט רשאי להאריך את תקופת התנאי אם לא הוטל עונש מאסר בגין העבירה הנוספת, וזו ההרשעה הראשונה בעבירה נוספת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, בית המשפט חייב להפעיל את המאסר על תנאי, שכן סעיף 55 לחוק העונשין קובע חובת הפעלה במקרה של הרשעה בעבירה נוספת.', false, 'טענה זו שגויה. סעיף 56 לחוק העונשין מהווה חריג לסעיף 55, ומאפשר לבית המשפט להאריך את התנאי במקום להפעילו, בתנאים מסוימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, בית המשפט רשאי להאריך את תקופת התנאי, אך רק אם שרה הביעה חרטה עמוקה והתחייבה לטיפול שיקומי.', false, 'טענה זו שגויה. אמנם שיקולים שיקומיים יכולים להשפיע על שיקול הדעת, אך התנאים המפורשים בחוק להארכת תנאי הם אי-הטלת מאסר בפועל ושהיא הרשעה ראשונה בעבירה נוספת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, בית המשפט אינו מוסמך להאריך את תקופת התנאי, אלא רק לשנות את תנאי המאסר המותנה.', false, 'טענה זו שגויה. סעיף 56 לחוק העונשין מאפשר הארכה או חידוש של תקופת התנאי, אך בית המשפט אינו מוסמך לשנות את תנאי המאסר המותנה עצמם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 37, '2022-W-S-Q37';
END
$$;

-- ============================================================
-- Q38 — 2022-W-S-Q38 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: De minimis defense (זוטי דברים) — sec. 34יז to threats charge
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'cbc71417-5964-4ae8-b9fb-bdaf2d7b1f5e'::uuid;
  v_group_id uuid := 'aab7aa1c-dc6b-4ae9-9999-59b8a37e36f9'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f97e190a-a06e-4818-b9aa-a2325366522f'::uuid;
  v_ang_1 uuid := '79fc011b-83b9-43c9-ad0d-1f4ecd32458b'::uuid;
  v_ang_2 uuid := 'b651d449-0607-4216-98bd-7cc9cd6c72c4'::uuid;
  v_ang_3 uuid := 'c25f5650-b5cf-4abd-aea8-44f7acbb1572'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q38';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 38, '2022-W-S-Q38';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q38', v_chapter_id, v_subtopic_id, 'במהלך ויכוח בין יצחק לבת זוגו רינה אמר יצחק לרינה: "אני אתן לך אגרוף, אני אהרוג אותך". יצחק הועמד לדין ויוחסה לו עבירה של איומים. יצחק הודה באמירת הדברים, אך טען כי מדובר ב"זוטי דברים". בית המשפט קיבל את טענתו וקבע כי בנסיבות העניין יש לראות באמירה זוטי דברים. מה הדין?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 38}'::jsonb, 'שאלה זו בוחנת את סייג זוטי דברים (סעיף 34יז לחוק העונשין, התשל"ז-1977), שהוא הגנה מהותית במשפט הפלילי. היא מתמקדת בתוצאה המשפטית של קבלת טענה זו – זיכוי מלא של הנאשם – ומבחינה בינה לבין חלופות אחרות כמו הרשעה או אי-הרשעה.', 'סעיף 34יז לחוק העונשין קובע כי "לא יישא אדם באחריות פלילית למעשה, אם, לאור טיבו של המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, המעשה הוא קל ערך". סייג זה הוא הגנה מהותית, כלומר, אם בית המשפט מקבל את הטענה, הוא קובע שהמעשה אינו מצדיק הטלת אחריות פלילית, והתוצאה היא זיכוי מלא של הנאשם (ת"פ (שלום ת"א) 64890-10-21, ת"פ (שלום נת'') 48951-01-22, ת"פ (שלום רח'') 29347-06-15). בניגוד לאי-הרשעה, שבה הממצא העובדתי של ביצוע העבירה נותר אך הנאשם פטור מהרשעה, קבלת זוטי דברים שוללת את עצם האחריות הפלילית.', 'הטעות הנפוצה היא לבלבל בין סייג זוטי דברים, שמוביל לזיכוי, לבין סיום הליך ללא הרשעה (אי-הרשעה), שבו הנאשם פטור מהרשעה אך הממצא העובדתי של ביצוע העבירה נותר.',
    '["זוטי דברים", "סייג לאחריות פלילית", "סעיף 34יז לחוק העונשין", "זיכוי", "קל ערך", "אי-הרשעה", "הגנה מהותית"]'::jsonb, '**וריאציה 1 — תוצאת קבלת זוטי דברים:** מהי התוצאה המשפטית של קבלת טענת זוטי דברים? ← זיכוי הנאשם, שכן זו הגנה מהותית השוללת אחריות פלילית (סעיף 34יז לחוק העונשין).
**וריאציה 2 — הבדל מאי-הרשעה:** מה ההבדל העיקרי בין זוטי דברים לאי-הרשעה? ← זוטי דברים מוביל לזיכוי מלא, בעוד אי-הרשעה משאירה את הממצא העובדתי של ביצוע העבירה אך פוטרת מהרשעה (יורם רבין, יניב ואקי, דיני עונשין - כרך ב, עמ'' 17).
**וריאציה 3 — האם זוטי דברים מבטל את העבירה?** ← לא, זוטי דברים אינו מבטל את העבירה הפורמלית, אלא קובע שהמעשה אינו מצדיק אחריות פלילית בשל קלות ערכו (ת"פ (שלום רח'') 29347-06-15).
**וריאציה 4 — שיקול דעת בית המשפט:** האם בית המשפט חייב לקבל טענת זוטי דברים אם התנאים מתקיימים? ← כן, אם התנאים מתקיימים, בית המשפט חייב לזכות את הנאשם, שכן זו הגנה מהותית ולא שיקול דעת דיוני (יורם רבין, יניב ואקי, דיני עונשין - כרך ב, עמ'' 15).', 'זוטי דברים (סעיף 34יז) ← הגנה מהותית ← מובילה לזיכוי ← בוחנת טיב, נסיבות, תוצאות ואינטרס ציבורי ← לא שיקול דעת דיוני.', '["סעיף 34יז לחוק העונשין, תשל\"ז-1977", "ת\"פ (שלום ת\"א) 64890-10-21 מדינת ישראל נ'' בוריס מושייב (7.12.2022)", "ת\"פ (שלום נת'') 48951-01-22 מדינת ישראל נ'' פלוני (3.12.2022)", "יורם רבין, יניב ואקי, דיני עונשין - כרך ב (2014) | פרק 28 - זוטי דברים", "ישגב נקדימון, הגנה מן הצדק (2025) | פרק אחד-עשר הגנה מן הצדק אל מול זוטי דברים"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: De minimis defense (זוטי דברים) — sec. 34יז to threats charge | source_review_note: השאלה עוסקת בסייג לאחריות פלילית (''זוטי דברים'') שהוא נושא מהותי בדיני עונשין (חלק מקדמי). נושא זה אינו מתאים באופן ישיר לאף אחד מתתי הנושאים הקיימים תחת פרק ''סדר דין פלילי'' או ''חוקתי + בינלאומי פרטי''. ''ערעור פלילי'' נבחר כהצבה זמנית, אך יש לשקול הוספת תת-נושא ייעודי כגון ''סייגים לאחריות פלילית'' או ''הגנות במשפט הפלילי''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יצחק יורשע ויוטל עליו לחתום על התחייבות להימנע מעבירה.', false, 'טענה זו שגויה. קבלת טענת זוטי דברים מובילה לזיכוי מלא של הנאשם, ולא להרשעה עם הטלת אמצעי ענישה או שיקום.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יצחק יזוכה.', true, 'זוהי התשובה הנכונה. סייג זוטי דברים (סעיף 34יז לחוק העונשין) הוא הגנה מהותית השוללת אחריות פלילית, ולכן קבלתה מחייבת זיכוי של הנאשם.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'יצחק יורשע ויוטל עליו עונש של קנס בלבד.', false, 'טענה זו שגויה. קבלת טענת זוטי דברים שוללת את האחריות הפלילית ומובילה לזיכוי, ולא להרשעה עם הטלת קנס.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'יצחק יופנה לשירות המבחן לצורך בחינת אפשרות סיום ההליך ללא הרשעה.', false, 'טענה זו שגויה. סיום הליך ללא הרשעה (אי-הרשעה) שונה מהגנת זוטי דברים. אי-הרשעה משאירה את הממצא העובדתי של ביצוע העבירה אך פוטרת מהרשעה, בעוד זוטי דברים מוביל לזיכוי מלא.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'זוטי דברים בעבירת רכוש',
    1, 'ראובן, אדם מבוגר וחסר עבר פלילי, נכנס לחנות נוחות וגנב עט פשוטה בשווי 5 ש"ח. הוא נתפס מיד והודה במעשה. האם בית המשפט יכול לזכותו מחמת זוטי דברים?', 'שאלה זו בוחנת את יישום סייג זוטי דברים (סעיף 34יז לחוק העונשין) בעבירות רכוש קלות. היא מדגישה כי גם בעבירות אלו, ניתן לזכות נאשם אם המעשה נחשב קל ערך לאור טיבו, נסיבותיו, תוצאותיו והאינטרס הציבורי.', 'סעיף 34יז לחוק העונשין קובע כי לא יישא אדם באחריות פלילית למעשה, אם לאור טיבו של המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, המעשה הוא קל ערך. הפסיקה הכירה באפשרות להחיל סייג זה גם על עבירות רכוש, כפי שניתן לראות במקרים של גניבת כלי איפור משומשים (ע"פ 807/99 עזיזיאן) או גניבת רכב לפירוק (ת"פ (שלום נת'') 35016-03-21). במקרה של גניבת עט פשוטה, בית המשפט יבחן את כלל הנסיבות כדי לקבוע אם המעשה עולה כדי ''קל ערך'' המצדיק זיכוי.',
    'הטעות הנפוצה היא לחשוב שכל עבירת רכוש, מעצם טיבה, אינה יכולה להיחשב ''זוטי דברים'', מבלי לבחון את קלות הערך הספציפית של המעשה.', '["זוטי דברים", "סעיף 34יז לחוק העונשין", "עבירות רכוש", "קל ערך", "אינטרס ציבורי", "זיכוי"]'::jsonb, '**וריאציה 1 — גניבת לחם מרעב:** האם גניבת לחם מרעב יכולה להיחשב זוטי דברים? ← כן, המניע (רעב) יכול להשפיע על בחינת הסיכון החברתי והאינטרס הציבורי (פרופ'' הלוי, תורת דיני העונשין, עמ'' 595).
**וריאציה 2 — גניבת עט יקרה:** האם גניבת עט יקרה מאוד יכולה להיחשב זוטי דברים? ← פחות סביר, שכן ''טיב המעשה'' ו''תוצאותיו'' (שווי הנזק) יהיו בעלי משקל רב יותר ויפחיתו את קלות הערך.
**וריאציה 3 — גניבת עט פשוטה:** האם גניבת עט פשוטה מחנות יכולה להיחשב זוטי דברים? ← כן, אם טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי מצביעים על קלות ערך (סעיף 34יז).
**וריאציה 4 — גניבה חוזרת:** האם גניבת עט פשוטה, אם זו עבירה חוזרת, יכולה להיחשב זוטי דברים? ← פחות סביר, שכן חזרתיות עלולה להשפיע על האינטרס הציבורי ועל הערכת ''טיב המעשה'' כקל ערך.', 'זוטי דברים בעבירות רכוש ← אפשרי במקרים קלי ערך ← בחינת טיב, נסיבות, תוצאות ואינטרס ציבורי.',
    '["סעיף 34יז לחוק העונשין, תשל\"ז-1977", "ע\"פ 807/99 מדינת ישראל נ'' עזיזיאן, פ\"ד נג(5) 747 (1999)", "ת\"פ (שלום נת'') 35016-03-21 מדינת ישראל נ'' מאיר גולן (13.3.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, גניבה, גם אם קלת ערך, אינה יכולה להיחשב זוטי דברים בשל הפגיעה בקניין.', false, 'טענה זו שגויה. הפסיקה הכירה באפשרות להחיל את סייג זוטי דברים גם על עבירות רכוש, אם טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי מצביעים על קלות ערך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, אם בית המשפט ימצא כי טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי מצביעים על כך שהמעשה הוא קל ערך.', true, 'זוהי התשובה הנכונה. סעיף 34יז לחוק העונשין מאפשר זיכוי מחמת זוטי דברים אם ארבעת התנאים המצטברים מתקיימים, גם בעבירות רכוש קלות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם ראובן יפצה את בעל החנות על העט שנגנבה.', false, 'טענה זו שגויה. פיצוי הקורבן יכול להוות שיקול לקולא, אך אינו תנאי הכרחי לקבלת טענת זוטי דברים, שהיא הגנה מהותית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן התביעה תסכים לביטול כתב האישום מחוסר עניין לציבור.', false, 'טענה זו שגויה. זוטי דברים היא הגנה מהותית שבית המשפט מוסמך להכריע בה, ללא תלות בעמדת התביעה, והיא מובילה לזיכוי ולא לביטול כתב אישום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני זוטי דברים',
    2, 'מהם ארבעת התנאים המצטברים לבחינת תחולת סייג זוטי דברים, ומהו משקלם היחסי?', 'שאלה זו מתמקדת במבחנים המשפטיים לבחינת תחולת סייג זוטי דברים, כפי שנקבעו בסעיף 34יז לחוק העונשין וכפי שפורשו בפסיקה. היא בוחנת את ארבעת התנאים המצטברים ואת משקלו היחסי של האינטרס הציבורי.', 'סעיף 34יז לחוק העונשין קובע ארבעה תנאים מצטברים לבחינת תחולת סייג זוטי דברים: טיבו של המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי. הפסיקה, ובפרט ע"פ 7829/03 מדינת ישראל נ'' אריאל הנדסת חשמל רמזורים ובקרה בע"מ, קבעה כי משקלו של התנאי האחרון, בדבר האינטרס הציבורי, רב יותר משל השאר. השאלה המכריעה היא אם סיכום כל ארבעת התנאים מוביל למסקנה כי לא קיימת סכנה מזערית לציבור המצדיקה הטלת אחריות בפלילים.',
    'הטעות הנפוצה היא לייחס משקל שווה לכל התנאים, או להתעלם מכך שהם תנאים מצטברים, ולא חלופיים.', '["זוטי דברים", "סעיף 34יז לחוק העונשין", "טיב המעשה", "נסיבות המעשה", "תוצאות המעשה", "אינטרס ציבורי", "תנאים מצטברים"]'::jsonb, '**וריאציה 1 — תנאים מצטברים:** האם ארבעת התנאים של זוטי דברים הם מצטברים או חלופיים? ← מצטברים (ע"פ 7829/03 אריאל).
**וריאציה 2 — משקל האינטרס הציבורי:** מהו משקלו של האינטרס הציבורי ביחס לשאר התנאים? ← משקלו רב יותר מהשאר (ע"פ 7829/03 אריאל).
**וריאציה 3 — סכנה לציבור:** מהי השאלה המרכזית הנבחנת במסגרת האינטרס הציבורי? ← האם מעשה העבירה הצמיח מידה מזערית של סכנה לציבור (ע"פ 7829/03 אריאל).
**וריאציה 4 — נסיבות אישיות:** האם נסיבותיו האישיות של הנאשם נלקחות בחשבון? ← כן, לעיתים השפעתן של נסיבות אלו תשנה את התמונה מן הקצה אל הקצה, והרשעתו לאורן לא תשרת כל מטרה ראויה (ע"פ 7829/03 אריאל).', 'מבחני זוטי דברים (סעיף 34יז) ← טיב, נסיבות, תוצאות, אינטרס ציבורי ← מצטברים ← אינטרס ציבורי בעל משקל בכורה.',
    '["סעיף 34יז לחוק העונשין, תשל\"ז-1977", "ע\"פ 7829/03 מדינת ישראל נ'' אריאל הנדסת חשמל רמזורים ובקרה בע\"מ, פ\"ד ס(2) 120 (2005)", "ע\"פ 807/99 מדינת ישראל נ'' עזיזיאן, פ\"ד נג(5) 747 (1999)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, כולם בעלי משקל שווה.', false, 'טענה זו שגויה. למרות שכל ארבעת התנאים מצטברים, הפסיקה קבעה כי משקלו של האינטרס הציבורי רב יותר משל השאר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, כאשר משקלו של האינטרס הציבורי רב יותר מהשאר.', true, 'זוהי התשובה הנכונה. סעיף 34יז לחוק העונשין מונה את ארבעת התנאים, והפסיקה (עניין אריאל) קבעה כי הם מצטברים וכי לאינטרס הציבורי משקל בכורה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, כאשר משקלו של טיב המעשה הוא העיקרי.', false, 'טענה זו שגויה. למרות שטיב המעשה חשוב, הפסיקה קבעה כי האינטרס הציבורי הוא בעל המשקל העיקרי מבין ארבעת התנאים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, אך הם אינם תנאים מצטברים.', false, 'טענה זו שגויה. הפסיקה קבעה במפורש כי ארבעת התנאים המנויים בסעיף 34יז לחוק העונשין הם תנאים מצטברים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'זוטי דברים בעבירות אלימות במשפחה',
    3, 'במהלך ויכוח סוער בבית הדין הרבני, ירקה אישה בפניו של בעלה לשעבר. האישה הואשמה בתקיפה סתם. האם בית המשפט יכול לזכותה מחמת זוטי דברים, בהתחשב בכך שמדובר בעבירת אלימות במשפחה?', 'שאלה זו בוחנת את תחולת סייג זוטי דברים בעבירות אלימות במשפחה, נושא רגיש שבו האינטרס הציבורי הוא בעל משקל רב. היא מדגישה את הצורך בזהירות רבה בהפעלת הסייג במקרים אלו, אך גם את העובדה שאין איסור גורף להחילו.', 'הפסיקה קבעה כי לא ניתן לקבוע כקביעה גורפת שכל מקרה של עבירה לפי סעיף 382(ב) לחוק העונשין (תקיפת בן זוג) אינו יכול להיחשב כ''זוטי דברים''. עם זאת, יש להפעיל את הסייג בזהירות ובמתינות, במיוחד בעבירות אלימות במשפחה, כדי שלא לרוקן מתוכן את האיסורים הנורמטיביים (ת"פ (שלום רח'') 29347-06-15). במקרה של יריקה, בית המשפט יכול לראות בכך מעשה שיש בו ביזוי והשפלה יותר מאשר תקיפה פיזית חמורה, ובנסיבות מסוימות, לזכות מחמת זוטי דברים (ת"פ (שלום רח'') 29347-06-15).',
    'הטעות הנפוצה היא להניח כי עבירות אלימות במשפחה הן תמיד חמורות מכדי להיחשב זוטי דברים, מבלי לבחון את נסיבות המקרה הספציפיות.', '["זוטי דברים", "אלימות במשפחה", "סעיף 34יז לחוק העונשין", "אינטרס ציבורי", "תקיפה סתם", "זהירות בהחלה"]'::jsonb, '**וריאציה 1 — יריקה בבית הדין:** האם יריקה בפני בן זוג בבית הדין הרבני יכולה להיחשב זוטי דברים? ← כן, במקרים מסוימים, אם בית המשפט רואה בכך ביזוי והשפלה יותר מתקיפה פיזית חמורה (ת"פ (שלום רח'') 29347-06-15).
**וריאציה 2 — דחיפה קלה:** האם דחיפה קלה של בן זוג יכולה להיחשב זוטי דברים? ← כן, הפסיקה הכירה במקרים של דחיפה או דריכה על רגל כזוטי דברים, תוך בחינה קפדנית של הנסיבות (ת"פ (שלום כ"ס) 69294-01-23).
**וריאציה 3 — איומים קלים:** האם איומים קלים בתוך המשפחה יכולים להיחשב זוטי דברים? ← כן, כפי שקרה במקרה המקור, אם טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי מצדיקים זאת.
**וריאציה 4 — פגיעה בילדים:** האם אלימות במשפחה בנוכחות ילדים יכולה להיחשב זוטי דברים? ← פחות סביר, שכן נוכחות ילדים מחמירה את נסיבות המעשה ופוגעת באינטרס הציבורי (ת"פ (שלום נת'') 48951-01-22).', 'זוטי דברים באלימות במשפחה ← אפשרי במקרים חריגים וקלי ערך ← בזהירות רבה ← בחינת טיב, נסיבות, תוצאות ואינטרס ציבורי.',
    '["סעיף 34יז לחוק העונשין, תשל\"ז-1977", "ת\"פ (שלום רח'') 29347-06-15 מדינת ישראל נ'' ציפורה עדי סרוסו (8.2.2017)", "ת\"פ (שלום נת'') 48951-01-22 מדינת ישראל נ'' פלוני (3.12.2022)", "ת\"פ (שלום חד'') 40193-10-23 מדינת ישראל נ'' פלונית (12.9.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, עבירות אלימות במשפחה, מעצם חומרתן והאינטרס הציבורי בהן, אינן יכולות להיחשב זוטי דברים.', false, 'טענה זו שגויה. הפסיקה הכירה באפשרות להחיל את סייג זוטי דברים גם על עבירות אלימות במשפחה, אם כי בזהירות רבה ובמקרים חריגים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אם בית המשפט ימצא כי המעשה הוא קל ערך, גם אם מדובר בעבירת אלימות במשפחה, אך בזהירות רבה.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי לא ניתן לקבוע כקביעה גורפת שכל מקרה של אלימות במשפחה אינו יכול להיחשב זוטי דברים, אך יש להפעיל את הסייג בזהירות רבה (ת"פ (שלום רח'') 29347-06-15).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם המתלונן יסכים לביטול התלונה.', false, 'טענה זו שגויה. הסכמת המתלונן לביטול התלונה אינה תנאי לקבלת טענת זוטי דברים, ואינה שיקול מכריע, במיוחד בעבירות אלימות במשפחה (ת"פ (שלום נת'') 48951-01-22).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן לא נגרמה כל פגיעה פיזית למתלונן.', false, 'טענה זו שגויה. אמנם היעדר פגיעה פיזית הוא שיקול, אך גם במקרים בהם נגרמה פגיעה מינורית, ניתן לזכות מחמת זוטי דברים, אם שאר התנאים מתקיימים (ת"פ (שלום חד'') 40193-10-23).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'זוטי דברים מול אי-הרשעה',
    4, 'מהו ההבדל המהותי בין קבלת טענת ''זוטי דברים'' לבין סיום הליך פלילי ב''אי-הרשעה''?', 'שאלה זו עורכת השוואה בין שני מנגנונים משפטיים שונים במשפט הפלילי: סייג זוטי דברים (סעיף 34יז לחוק העונשין) וסיום הליך ב''אי-הרשעה''. היא מדגישה את ההבדל המהותי בתוצאה המשפטית ובשיקולים העומדים בבסיס כל אחד מהם.', 'הגנת זוטי דברים היא הגנה מהותית השוללת את האחריות הפלילית למעשה, וקבלתה מחייבת זיכוי של הנאשם (יורם רבין, יניב ואקי, דיני עונשין - כרך ב, עמ'' 17). היא מתמקדת בטיבו של המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי. לעומת זאת, אי-הרשעה היא סעד שיקומי המאפשר לבית המשפט להימנע מהרשעה פלילית, גם אם הוכח שהנאשם ביצע את העבירה, וזאת מטעמים של שיקום הנאשם ומניעת פגיעה עתידית בו, תוך התחשבות בנסיבותיו האישיות ובהשלכות ההרשעה. במקרה של אי-הרשעה, הממצא העובדתי של ביצוע העבירה נותר, אך לא נרשמת הרשעה פלילית.',
    'הטעות הנפוצה היא לבלבל בין זוטי דברים לאי-הרשעה, ולחשוב ששניהם מובילים לאותה תוצאה משפטית או מבוססים על אותם שיקולים.', '["זוטי דברים", "אי-הרשעה", "סייג לאחריות פלילית", "זיכוי", "סעד שיקומי", "השלכות הרשעה"]'::jsonb, '**וריאציה 1 — תוצאה משפטית:** מהי התוצאה המשפטית של קבלת זוטי דברים? ← זיכוי מלא של הנאשם (סעיף 34יז לחוק העונשין).
**וריאציה 2 — תוצאה משפטית (אי-הרשעה):** מהי התוצאה המשפטית של אי-הרשעה? ← הממצא העובדתי של ביצוע העבירה נותר, אך לא נרשמת הרשעה פלילית.
**וריאציה 3 — שיקולים (זוטי דברים):** על מה מתמקד בית המשפט בבחינת זוטי דברים? ← טיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי (סעיף 34יז לחוק העונשין).

**וריאציה 4 — שיקולים (אי-הרשעה):** על מה מתמקד בית המשפט בבחינת אי-הרשעה? ← נסיבותיו האישיות של הנאשם, השלכות ההרשעה עליו, ואינטרס שיקומי (סעיף 192 לחוק סדר הדין הפלילי).', 'זוטי דברים ← הגנה מהותית ← זיכוי מלא. אי-הרשעה ← סעד שיקומי ← אין הרשעה אך יש ממצא עובדתי.',
    '["סעיף 34יז לחוק העונשין, תשל\"ז-1977", "יורם רבין, יניב ואקי, דיני עונשין - כרך ב (2014) | פרק 28 - זוטי דברים", "ישגב נקדימון, הגנה מן הצדק (2025) | פרק אחד-עשר הגנה מן הצדק אל מול זוטי דברים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'זוטי דברים מוביל לזיכוי מלא, בעוד אי-הרשעה משאירה את הממצא העובדתי של ביצוע העבירה אך פוטרת מהרשעה.', true, 'זוהי התשובה הנכונה. זוטי דברים היא הגנה מהותית השוללת אחריות פלילית ומובילה לזיכוי, בעוד אי-הרשעה היא סעד שיקומי המותיר את הממצא העובדתי אך נמנע מהרשעה פלילית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'זוטי דברים הוא סעד דיוני הנתון לשיקול דעת התביעה, בעוד אי-הרשעה היא סעד מהותי הנתון לשיקול דעת בית המשפט.', false, 'טענה זו שגויה. זוטי דברים היא הגנה מהותית הנתונה לשיקול דעת בית המשפט, בעוד אי-הרשעה היא סעד שיקומי הנתון לשיקול דעת בית המשפט, אך אינה הגנה מהותית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'זוטי דברים חל רק על עבירות קלות, בעוד אי-הרשעה יכולה לחול גם על עבירות חמורות.', false, 'טענה זו שגויה. זוטי דברים חל על מעשים קלי ערך, בעוד אי-הרשעה יכולה לחול על מגוון רחב יותר של עבירות, בהתאם לנסיבות הנאשם והאינטרס הציבורי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'זוטי דברים מתמקד בנסיבותיו האישיות של הנאשם, בעוד אי-הרשעה מתמקדת בטיב המעשה.', false, 'טענה זו שגויה. זוטי דברים מתמקד בטיב המעשה, נסיבותיו, תוצאותיו והאינטרס הציבורי, בעוד אי-הרשעה מתחשבת בנסיבותיו האישיות של הנאשם ובהשלכות ההרשעה עליו.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 38, '2022-W-S-Q38';
END
$$;

-- ============================================================
-- Q39 — 2022-W-S-Q39 — chapter=torts subtopic=negligence
-- classifier_note: Volunteer-operating organization, sexual-harassment policy — duty of care + policy considerations
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '473bc238-9499-4825-bc61-064974a98ec7'::uuid;
  v_group_id uuid := 'a84e322c-2320-42ba-bd4b-aee9626b764c'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c876ab3a-846c-4fe1-8c85-bfe1fc4b9429'::uuid;
  v_ang_1 uuid := '43c5779e-f4c4-4431-92c5-e795af99e743'::uuid;
  v_ang_2 uuid := '175ae56a-0eab-4a12-bef8-d54d8cf234e1'::uuid;
  v_ang_3 uuid := 'e1f74495-6380-4f76-b8eb-9e9a73a68936'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q39';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 39, '2022-W-S-Q39';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'negligence' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'negligence', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q39', v_chapter_id, v_subtopic_id, 'הניחו כי בית המשפט העליון קבע מטעמים של מדיניות משפטית הלכה שלפיה לא ניתן יהיה לתבוע בגין רשלנות ארגון המפעיל מתנדבים בגין מעשים המתייחסים להטרדה מינית בין המתנדבים, אף שהתרחשותם של מקרים מעין אלה אינה נדירה. איזה מבין המשפטים שלהלן מתאר נכונה את החלטת בית המשפט?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 39}'::jsonb, 'שאלה זו עוסקת ביסודות עוולת הרשלנות, ובפרט בחובת הזהירות המושגית. היא בוחנת כיצד שיקולי מדיניות משפטית יכולים להשפיע על קביעת קיומה של חובת זהירות זו, גם כאשר קיימת צפיות טכנית לנזק. השאלה מדגישה את תפקידו של בית המשפט בעיצוב גבולות האחריות הנזיקית.', 'עוולת הרשלנות מורכבת משלושה יסודות: חובת זהירות (מושגית וקונקרטית), הפרת חובה זו (התרשלות) ונזק שנגרם כתוצאה מההפרה. חובת הזהירות המושגית נקבעת על פי מבחן הצפיות, המורכב מצפיות טכנית (האם אדם סביר יכול היה לצפות את הנזק) וצפיות נורמטיבית (האם אדם סביר צריך היה לצפות את הנזק). שיקולי מדיניות משפטית נכנסים לתמונה בשלב הצפיות הנורמטיבית, והם יכולים לשלול את קיומה של חובת זהירות מושגית, גם אם הנזק צפוי מבחינה טכנית. במקרה הנדון, בית המשפט קבע מטעמי מדיניות שלא להטיל חובת זהירות מושגית על ארגון המפעיל מתנדבים בגין הטרדה מינית בין מתנדבים, למרות שהמקרים אינם נדירים (כלומר, קיימת צפיות טכנית).', 'הטעות הנפוצה היא להניח כי כל נזק שניתן לצפותו מבחינה טכנית, יגרור בהכרח הטלת חובת זהירות, מבלי להביא בחשבון את שיקולי המדיניות המשפטית שיכולים לשלול חובה זו.',
    '["עוולת הרשלנות", "חובת זהירות מושגית", "מבחן הצפיות", "צפיות טכנית", "צפיות נורמטיבית", "שיקולי מדיניות משפטית", "הפרת חובה", "נזק"]'::jsonb, '**וריאציה 1 — צפיות טכנית מול נורמטיבית:** האם כל נזק שניתן לצפותו מבחינה טכנית, צריך לצפותו מבחינה נורמטיבית? ← לא, שיקולי מדיניות משפטית יכולים לשלול את הצורך לצפות נזק, גם אם הוא צפוי טכנית (ע"א 145/80 ועקנין).
**וריאציה 2 — תפקיד המדיניות:** מתי שיקולי מדיניות משפטית נכנסים לבחינת חובת הזהירות? ← בעיקר בשלב קביעת חובת הזהירות המושגית, כדי להגביל את היקף האחריות (ע"א 145/80 ועקנין).
**וריאציה 3 — שלילת חובה מושגית:** אילו שיקולי מדיניות יכולים להביא לשלילת חובת זהירות מושגית? ← הרתעת יתר, עלויות התדיינות, ריבוי תביעות, פגיעה בפעילויות רצויות (נבו - המתמחה, דיני נזיקין, עמ'' 27).
**וריאציה 4 — חובת זהירות קונקרטית:** האם שלילת חובת זהירות מושגית משפיעה על חובת הזהירות הקונקרטית? ← כן, אם אין חובת זהירות מושגית, אין גם חובת זהירות קונקרטית (ע"א 145/80 ועקנין).', 'שלילת חובת זהירות מושגית → מטעמי מדיניות משפטית → גם אם הנזק צפוי טכנית → בית המשפט מאזן אינטרסים.', '["סעיף 35 לפקודת הנזיקין [נוסח חדש]", "סעיף 36 לפקודת הנזיקין [נוסח חדש]", "ע\"א 145/80 שלמה ועקנין נ'' המועצה המקומית בית שמש, פ\"ד לז(1) 113 (1982)", "ע\"א 3463/23 חאתם פאיז אלמע''ארי נ'' התביעה הצבאית (13.8.2025)", "נבו - המתמחה, דיני נזיקין (2026) | פקודת הנזיקין [נוסח חדש], עמ'' 27"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Volunteer-operating organization, sexual-harassment policy — duty of care + policy considerations | source_review_note: השאלה עוסקת ביסודות עוולת הרשלנות, ובפרט בחובת הזהירות המושגית ושיקולי מדיניות. נושא זה שייך באופן מובהק לדיני נזיקין. מבין תתי הנושאים הקיימים, ''הליכים'' תחת ''סדר דין אזרחי'' הוא הקרוב ביותר, אך אינו מדויק לחלוטין. יש לשקול הוספת תת-נושא ייעודי ל''דיני נזיקין'' או ''עוולת הרשלנות''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט קבע שלא מתקיים מבחן הצפיות בנוגע למקרים מסוג זה.', false, 'טענה זו שגויה. השאלה מציינת כי "התרחשותם של מקרים מעין אלה אינה נדירה", מה שמרמז על קיומה של צפיות טכנית. שלילת החובה במקרה זה נובעת משיקולי מדיניות, ולא מחוסר צפיות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט שינה את ההגדרה של נזק במקרים מסוג זה.', false, 'טענה זו שגויה. השאלה אינה מתייחסת לשינוי בהגדרת הנזק, אלא לשלילת חובת הזהירות מטעמי מדיניות משפטית.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט קבע שלא קיימת חובת אחריות מושגית במקרים מסוג זה.', true, 'זוהי התשובה הנכונה. חובת הזהירות המושגית נקבעת על פי מבחן הצפיות, אך שיקולי מדיניות משפטית יכולים לשלול אותה, גם אם הנזק צפוי מבחינה טכנית. קביעה זו מתארת בדיוק את המצב שבו בית המשפט מחליט, מטעמי מדיניות, שלא להטיל חובת זהירות על סוג מסוים של מזיקים כלפי סוג מסוים של ניזוקים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט קבע שלא קיימת חובת אחריות קונקרטית במקרים מסוג זה.', false, 'טענה זו שגויה. חובת הזהירות הקונקרטית נבחנת רק לאחר שנקבעה חובת זהירות מושגית. אם חובת הזהירות המושגית נשללה מטעמי מדיניות, אין צורך לבחון את החובה הקונקרטית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שלילת חובת זהירות מושגית',
    1, 'עירייה החליטה, משיקולי תקציב, לצמצם באופן דרסטי את תדירות בדיקות הבטיחות במתקני שעשועים ציבוריים. כתוצאה מכך, ילד נפגע במתקן תקול. האם ניתן לשלול את חובת הזהירות המושגית של העירייה כלפי הילד בגין שיקולי מדיניות תקציביים?', 'שאלה זו בוחנת את שלילת חובת הזהירות המושגית של רשות ציבורית מטעמי מדיניות, תוך התייחסות למשקלם של שיקולים תקציביים אל מול פגיעה פיזית. היא מדגישה את האיזון העדין בין אינטרסים שונים בקביעת גבולות האחריות הנזיקית.', 'חובת הזהירות המושגית של רשות מקומית כלפי משתמשי מתקנים ציבוריים היא חזקה ומוכרת בפסיקה. בעוד ששיקולי מדיניות משפטית יכולים לשלול חובת זהירות מושגית, שיקולים תקציביים בלבד אינם מספיקים בדרך כלל כדי לשלול חובה זו במקרים של פגיעה פיזית. בית המשפט מאזן בין האינטרסים השונים, ובמקרה של פגיעה בגוף, האינטרס הציבורי בהגנה על שלום הציבור גובר על שיקולים תקציביים גרידא. (ראו: ע"א 145/80 שלמה ועקנין נ'' המועצה המקומית בית שמש).',
    'הטעות הנפוצה היא לבלבל בין שיקולי מדיניות לגיטימיים באופן כללי לבין שיקולים שיכולים בפועל לשלול חובת זהירות מושגית במקרים של נזקי גוף.', '["חובת זהירות מושגית", "רשות ציבורית", "שיקולי מדיניות", "נזקי גוף", "איזון אינטרסים", "מבחן הצפיות"]'::jsonb, '**וריאציה 1 — שיקולי תקציב:** האם שיקולי תקציב יכולים לשלול חובת זהירות מושגית של עירייה? ← לא בקלות, במיוחד לא כשמדובר בנזקי גוף, שכן האינטרס הציבורי בהגנה על שלום הציבור גובר (ע"א 145/80 ועקנין).
**וריאציה 2 — נזק כלכלי:** האם שיקולי תקציב יכולים לשלול חובת זהירות מושגית במקרה של נזק כלכלי טהור? ← ייתכן שכן, במקרים של נזק כלכלי טהור, שיקולי מדיניות נוטים לצמצם את חובת הזהירות (ע"א 209/85 עיריית קרית-אתא נ'' אילנקו).
**וריאציה 3 — חובת זהירות מושגית של רשות:** מהי נקודת המוצא לגבי חובת זהירות מושגית של רשות ציבורית? ← ככלל, עקרון השוויון בפני החוק מחייב הטלת אחריות ברשלנות על רשות ציבורית על פי אותן אמות מידה החלות על הפרט (ע"א 243/83 עיריית ירושלים נ'' גורדון).
**וריאציה 4 — איזון אינטרסים:** אילו אינטרסים מאזן בית המשפט בקביעת חובת זהירות מושגית? ← חופש פעולה מול הגנה על הגוף והרכוש, סוג הנזק, דרכי התרחשותו, והשפעת הפסיקה על התנהגות הבריות והמעמסה הכספית (ע"א 2061/90 מרצלי).', 'שלילת חובת זהירות מושגית של רשות → מטעמי מדיניות → קשה במיוחד בנזקי גוף → שיקולי תקציב לבדם אינם מספיקים.',
    '["ע\"א 145/80 שלמה ועקנין נ'' המועצה המקומית בית שמש, פ\"ד לז(1) 113 (1982)", "ע\"א 209/85 עיריית קרית-אתא נ'' אילנקו בע\"מ, פ\"ד מב(1) 190 (1988)", "ע\"א 243/83 עיריית ירושלים נ'' גורדון, פ\"ד לט(1) 113 (1985)", "ע\"א 2061/90 אילנה מרצלי נ'' מדינת ישראל, משרד החינוך והתרבות, פ\"ד מז(1) 802 (1993)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון ששיקולי מדיניות תקציביים הם לגיטימיים ויכולים להצדיק שלילת חובת זהירות מושגית.', false, 'טענה זו שגויה. בעוד ששיקולי מדיניות יכולים לשלול חובת זהירות, שיקולים תקציביים בלבד אינם מספיקים בדרך כלל כדי לשלול חובת זהירות מושגית במקרים של פגיעה פיזית, שכן האינטרס הציבורי בהגנה על שלום הציבור גובר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שחובת הזהירות המושגית של עירייה כלפי משתמשי מתקנים ציבוריים היא מוחלטת ואינה ניתנת לשלילה.', false, 'טענה זו שגויה. חובת הזהירות המושגית אינה מוחלטת וניתנת לשלילה מטעמי מדיניות, אך לא בקלות במקרים של נזקי גוף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם העירייה תוכיח כי לא יכלה לצפות את הנזק הספציפי שנגרם לילד.', false, 'טענה זו שגויה. חוסר צפיות הנזק הספציפי מתייחס לחובת הזהירות הקונקרטית, ולא לשלילת חובת הזהירות המושגית מטעמי מדיניות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שיקולי מדיניות תקציביים אינם שוללים ככלל חובת זהירות מושגית במקרים של פגיעה פיזית ממתקן ציבורי.', true, 'זוהי התשובה הנכונה. חובת הזהירות המושגית של רשות מקומית כלפי משתמשי מתקנים ציבוריים היא חזקה. בעוד ששיקולי מדיניות יכולים לשלול חובה זו, שיקולים תקציביים בלבד אינם מספיקים בדרך כלל כדי לשלול אותה במקרים של פגיעה פיזית, שכן האינטרס הציבורי בהגנה על שלום הציבור גובר (ע"א 145/80 ועקנין).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני חובת הזהירות',
    2, 'מהם שני ההיבטים של מבחן הצפיות בקביעת חובת זהירות מושגית, וכיצד הם נבדלים זה מזה?', 'שאלה זו בוחנת את הבנת המבחנים לקביעת חובת זהירות מושגית, ובפרט את ההבחנה בין צפיות טכנית לצפיות נורמטיבית ואת תפקידם של שיקולי מדיניות משפטית. היא נוגעת לליבת עוולת הרשלנות.', 'הפסיקה מבחינה בין שני היבטים במבחן הצפיות לקביעת חובת זהירות מושגית: צפיות טכנית (או פיזית) וצפיות נורמטיבית. צפיות טכנית מתייחסת ליכולת האובייקטיבית של אדם סביר לצפות את התרחשות הנזק. צפיות נורמטיבית מתייחסת לשאלה האם אדם סביר *צריך היה* לצפות את הנזק, והיא נבחנת באמצעות שיקולי מדיניות משפטית. לא כל נזק שניתן לצפותו מבחינה טכנית, צריך לצפותו מבחינה נורמטיבית (ע"א 145/80 ועקנין).',
    'בלבול בין יכולת לצפות (צפיות טכנית) לבין צורך לצפות (צפיות נורמטיבית), והתעלמות מתפקידם המכריע של שיקולי מדיניות.', '["חובת זהירות מושגית", "מבחן הצפיות", "צפיות טכנית", "צפיות נורמטיבית", "שיקולי מדיניות משפטית", "אדם סביר"]'::jsonb, '**וריאציה 1 — יכולת מול צורך:** מה ההבדל בין ''יכול לצפות'' ל''צריך לצפות''? ← ''יכול לצפות'' היא צפיות טכנית/פיזית, ''צריך לצפות'' היא צפיות נורמטיבית המושפעת משיקולי מדיניות (ע"א 145/80 ועקנין).
**וריאציה 2 — תפקיד המדיניות:** מתי שיקולי מדיניות נכנסים לתמונה במבחן הצפיות? ← בעיקר בשלב הצפיות הנורמטיבית, כדי להגביל את היקף האחריות (ע"א 145/80 ועקנין).
**וריאציה 3 — חזקת הצפיות:** מהי חזקת הצפיות? ← מקום שקיימת צפיות במישור הטכני, מתקיימת גם צפיות במישור הנורמטיבי, אלא אם כן שיקולי מדיניות שוללים את החובה (תמ"ש (משפחה אשדוד) 52292-12-14).
**וריאציה 4 — איזון אינטרסים:** אילו שיקולים מאזנים בתי המשפט בקביעת הצפיות הנורמטיבית? ← הצורך להבטיח חופש פעולה מול הצורך להגן על הרכוש והגוף, סוג הנזק, דרכי התרחשותו, והשפעת הפסיקה על התנהגות הבריות (ע"א 2061/90 מרצלי).', 'חובת זהירות מושגית → מבחן הצפיות → צפיות טכנית (יכול) + צפיות נורמטיבית (צריך) → נורמטיבית מושפעת משיקולי מדיניות.',
    '["ע\"א 145/80 שלמה ועקנין נ'' המועצה המקומית בית שמש, פ\"ד לז(1) 113 (1982)", "ע\"א 2061/90 אילנה מרצלי נ'' מדינת ישראל, משרד החינוך והתרבות, פ\"ד מז(1) 802 (1993)", "תמ\"ש (משפחה אשדוד) 52292-12-14 א.ג נ'' א.ק (6.4.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ההיבט הראשון הוא צפיות סובייקטיבית של המזיק, וההיבט השני הוא צפיות אובייקטיבית של האדם הסביר.', false, 'טענה זו שגויה. מבחן הצפיות הוא אובייקטיבי ומתייחס לאדם הסביר, ולא לצפיות סובייקטיבית של המזיק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'ההיבט הראשון הוא צפיות טכנית (יכולת לצפות את הנזק), וההיבט השני הוא צפיות נורמטיבית (צורך לצפות את הנזק), הנבחנת באמצעות שיקולי מדיניות משפטית.', true, 'זוהי התשובה הנכונה. הפסיקה מבחינה בין צפיות טכנית (יכולת פיזית לצפות) לבין צפיות נורמטיבית (צורך נורמטיבי לצפות), כאשר האחרונה מושפעת משיקולי מדיניות משפטית (ע"א 145/80 ועקנין).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'ההיבט הראשון הוא צפיות הנזק הישיר, וההיבט השני הוא צפיות הנזק העקיף.', false, 'טענה זו שגויה. ההבחנה בין נזק ישיר לעקיף אינה מתארת את שני ההיבטים של מבחן הצפיות בקביעת חובת זהירות מושגית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'ההיבט הראשון הוא צפיות הנזק הפיזי, וההיבט השני הוא צפיות הנזק הכלכלי.', false, 'טענה זו שגויה. ההבחנה בין נזק פיזי לכלכלי היא סוג של נזק, ולא היבטים של מבחן הצפיות לקביעת חובת זהירות מושגית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'גישת השופט עמית',
    3, 'לפי גישת השופט י'' עמית, כפי שהוצגה בעניין פלוני, מהו סדר הבחינה של יסודות עוולת הרשלנות, ובאיזה שלב נבחנת חובת הזהירות?', 'שאלה זו עוסקת בגישה חדשנית לניתוח יסודות עוולת הרשלנות, כפי שהוצעה על ידי השופט י'' עמית. היא בוחנת את סדר הבחינה המוצע על ידו, המקדים את ההתרשלות לחובת הזהירות, ואת תפקידה של חובת הזהירות כמסננת שיקולי מדיניות.', 'השופט י'' עמית הציג גישה לפיה אין מקום להבחנה בין חובת זהירות מושגית לקונקרטית, ויש להקדים את בחינת ההתרשלות לבחינת החובה. לשיטתו, יש לבחון תחילה את ההתרשלות, לאחר מכן את הקשר הסיבתי, ורק בסוף לבחון את חובת הזהירות כמסננת של שיקולי מדיניות השוללים אחריות, חרף קיומה של התרשלות. הוא טען כי במקרים המצויים ב''ליבת דיני הנזיקין'' (נזקים פיזיים לניזוקים ישירים), ניתן להתחיל בבחינת ההתרשלות, ואילו במקרים ''באזור הדמדומים'' (נזק נפשי, נזק כלכלי טהור), יש להקדים את בחינת החובה (ע"א 3521/11 עו"ד דניאל וגנר נ'' מזל עבדי; עמוס הרמן, דיני נזיקין, עמ'' 32, 35).',
    'הטעות הנפוצה היא לבלבל בין גישת השופט עמית לבין הגישה המסורתית (גישת השופט ברק) לגבי סדר בחינת יסודות הרשלנות.', '["גישת השופט עמית", "עוולת הרשלנות", "חובת זהירות", "התרשלות", "קשר סיבתי", "שיקולי מדיניות", "ליבת דיני הנזיקין"]'::jsonb, '**וריאציה 1 — סדר בחינה:** מהו סדר הבחינה של יסודות הרשלנות לפי השופט עמית? ← התרשלות, קשר סיבתי, חובת זהירות כמסננת (ע"א 3521/11 וגנר נ'' עבדי).
**וריאציה 2 — חובת זהירות כמסננת:** מה תפקידה של חובת הזהירות בגישת עמית? ← מסננת של שיקולי מדיניות השוללים אחריות, חרף קיומה של התרשלות (עמוס הרמן, דיני נזיקין, עמ'' 32).
**וריאציה 3 — ליבת דיני הנזיקין:** מתי ניתן להתחיל בבחינת ההתרשלות לפי עמית? ← במקרים שב''ליבת דיני הנזיקין'' (נזקים פיזיים לניזוקים ישירים) (עמוס הרמן, דיני נזיקין, עמ'' 32).
**וריאציה 4 — אזור הדמדומים:** מתי יש להקדים את בחינת החובה לפי עמית? ← במקרים ''באזור הדמדומים'' (נזק נפשי, נזק כלכלי טהור, ניזוק עקיף) (עמוס הרמן, דיני נזיקין, עמ'' 32).', 'גישת השופט עמית → סדר בחינה: התרשלות ← קשר סיבתי ← חובת זהירות (מסננת) → חובת זהירות כללית.',
    '["ע\"א 3521/11 עו\"ד דניאל וגנר נ'' מזל עבדי, פ\"ד סז(1) 84 (2014)", "עמוס הרמן, דיני נזיקין (2020) | פרק ה עוולת הרשלנות, עמ'' 32, 35", "ע\"א 4486/11 פלוני נ'' פלוני (15.7.2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'חובת הזהירות נבחנת תחילה, ולאחר מכן ההתרשלות והקשר הסיבתי.', false, 'טענה זו מתארת את הגישה המסורתית (גישת השופט ברק), ולא את גישת השופט עמית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'ההתרשלות נבחנת תחילה, לאחר מכן הקשר הסיבתי, ורק בסוף נבחנת חובת הזהירות כמסננת של שיקולי מדיניות שוללי אחריות.', true, 'זוהי התשובה הנכונה. השופט עמית הציע להקדים את בחינת ההתרשלות לבחינת החובה, ולבחון את חובת הזהירות בסוף, כמסננת של שיקולי מדיניות השוללים אחריות (ע"א 3521/11 וגנר נ'' עבדי; עמוס הרמן, דיני נזיקין, עמ'' 32).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'חובת הזהירות וההתרשלות נבחנות כמקשה אחת, ולאחר מכן הקשר הסיבתי.', false, 'טענה זו שגויה. למרות שקיימות גישות המאחדות את חובת הזהירות, גישת השופט עמית מציעה סדר בחינה שונה, ולא איחוד של חובה והתרשלות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'חובת הזהירות נבחנת רק במקרים של נזק כלכלי טהור, ולא במקרים של נזקי גוף.', false, 'טענה זו שגויה. השופט עמית ציין כי במקרים ''באזור הדמדומים'' (כמו נזק כלכלי טהור) יש להקדים את בחינת החובה, אך הוא לא שלל את בחינת החובה בנזקי גוף, אלא הציע סדר בחינה שונה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חובת זהירות של רשויות אכיפה',
    4, 'התביעה הצבאית לא מסרה לנאשם מידע על החלטות להימנע מהעמדה לדין של שוטרים אחרים שהיו מעורבים באותו אירוע, מידע שיכול היה לסייע לו בערעור. הנאשם הורשע, ורק לאחר מכן זוכה במשפט חוזר בהסדר טיעון. האם התביעה הצבאית חבה בחובת זהירות כלפי הנאשם בנסיבות אלו?', 'שאלה זו עוסקת בחובת הזהירות של רשויות אכיפת החוק (כגון התביעה) כלפי נאשמים, ובפרט בשאלת היקף חובה זו בשלבים מתקדמים של ההליך הפלילי, כגון שלב הערעור, כאשר מתגלה מידע מזכה. היא מתייחסת לדעת המיעוט בפסק דין עליון עדכני.', 'דעת המיעוט בע"א 3463/23 (השופט ח'' כבוב) סברה כי יש להכיר בחובת זהירות מושגית וקונקרטית של גורמי האכיפה והתביעה כלפי נאשם, גם בשלב הערעור. לשיטתו, על התובע לפעול באופן סביר כדי להביא לגילוי האמת ולנקוט אמצעי זהירות סבירים כדי לשמור על זכויות חשודים ונאשמים. במקרים שבהם גורמי האכיפה נחשפים לראיה שיש בכוחה לזכות נאשם, התביעה מחויבת להביא את הראיה לידיעת הנאשם ולאפשר לו לעשות בה שימוש. דעת הרוב, לעומת זאת, סברה כי לא הוכחה התרשלות ולא קשר סיבתי במקרה הנדון, וכי הרחבת חובת הזהירות עלולה להיות מוגזמת.',
    'הטעות הנפוצה היא להניח שחובת הזהירות של התביעה מסתיימת עם ההרשעה, או להתעלם מהחשיבות של גילוי ראיות מזכות גם בשלבים מאוחרים של ההליך.', '["חובת זהירות", "רשויות אכיפה", "תביעה פלילית", "ראיה מזכה", "הליך פלילי", "ערעור", "גילוי האמת"]'::jsonb, '**וריאציה 1 — חובת גילוי ראיות:** האם התביעה חייבת לגלות ראיות מזכות לנאשם? ← כן, חובה זו חלה גם בשלבים מתקדמים של ההליך, כולל ערעור (ע"א 3463/23, דעת מיעוט).
**וריאציה 2 — היקף חובת הזהירות:** מהו היקף חובת הזהירות של התביעה כלפי נאשם? ← על התביעה לפעול באופן סביר כדי להביא לגילוי האמת ולשמור על זכויות נאשמים (ע"א 3463/23, דעת מיעוט).
**וריאציה 3 — שיקולי מדיניות:** אילו שיקולי מדיניות מובילים להטלת חובת זהירות על גורמי אכיפה? ← הצורך להבטיח שימוש סביר בכוח הרב המצוי בידי התביעה, וגילוי האמת (ע"א 3463/23, דעת מיעוט).
**וריאציה 4 — אחריות המדינה:** האם המדינה יכולה לרחוץ בניקיון כפיה כאשר היא מודעת לראיות שיש בכוחן להוכיח חפותו של נאשם? ← לא, המדינה אינה יכולה לרחוץ בניקיון כפיה במצב כזה (ע"א 3463/23, דעת מיעוט).', 'חובת זהירות של רשויות אכיפה → חלה גם בשלב הערעור → מחייבת גילוי ראיות מזכות → מבוססת על גילוי האמת ושמירה על זכויות נאשמים.',
    '["ע\"א 3463/23 חאתם פאיז אלמע''ארי נ'' התביעה הצבאית (13.8.2025)", "נבו - המתמחה, דיני נזיקין (2026) | פקודת הנזיקין [נוסח חדש], עמ'' 27"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, מכיוון שחובת הזהירות של התביעה מסתיימת עם קבלת ההחלטה על העמדה לדין, ואינה חלה בשלב הערעור.', false, 'טענה זו שגויה. דעת המיעוט בע"א 3463/23 קבעה כי חובת הזהירות של גורמי האכיפה חלה גם בשלב הערעור, במקרים בהם נחשפים לראיה מזכה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, מכיוון שעל התביעה לפעול באופן סביר כדי להביא לגילוי האמת ולשמור על זכויות נאשמים, גם בשלב הערעור, אם נחשפת לראיה מזכה.', true, 'זוהי התשובה הנכונה. דעת המיעוט בע"א 3463/23 (השופט כבוב) קבעה כי קיימת חובת זהירות מושגית וקונקרטית של גורמי האכיפה כלפי נאשם, המחייבת אותם למסור ראיה מזכה גם בשלב הערעור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, מכיוון שהזיכוי במשפט החוזר התבסס על הסדר טיעון ולא על קביעה שיפוטית של חפותו.', false, 'טענה זו שגויה. למרות שהזיכוי היה בהסדר טיעון, השאלה היא האם הייתה חובת זהירות למסור את המידע מלכתחילה, ללא קשר לתוצאת המשפט החוזר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם הוכח קשר סיבתי ודאי בין אי-מסירת המידע לבין הרשעתו של הנאשם.', false, 'טענה זו שגויה. קשר סיבתי הוא יסוד נפרד בעוולת הרשלנות. השאלה היא קודם כל האם קיימת חובת זהירות, ורק לאחר מכן בוחנים את הקשר הסיבתי.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 39, '2022-W-S-Q39';
END
$$;

-- ============================================================
-- Q40 — 2022-W-S-Q40 — chapter=torts subtopic=negligence  [needs_review]
-- classifier_note: Tort liability of mentally-ill attacker after criminal court found him unfit — civil-vs-criminal liability boundary
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'c8121e89-37a3-42f7-a9b4-49ffdad25366'::uuid;
  v_group_id uuid := '86854762-46d1-4fe0-9c4b-72b5a7218f1a'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'ab471419-87ca-424d-99f2-beb826f444f5'::uuid;
  v_ang_1 uuid := '964214be-c68e-4601-a9f6-a92d80a9b36a'::uuid;
  v_ang_2 uuid := '68bdc352-9a8a-4ccf-96b6-51346f362d51'::uuid;
  v_ang_3 uuid := '4decdfa6-39a7-406a-be3c-54c58a581975'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-W-S-Q40';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 40, '2022-W-S-Q40';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'negligence' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'negligence', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-W-S-Q40', v_chapter_id, v_subtopic_id, 'פלוני תקף את אלמוני וגרם לו נזק גוף. פלוני הועמד לדין על המעשה ונקבע כי בעת האירוע וכן בעת העמדתו לדין הוא סבל ממחלת נפש, ולפיכך אינו בר עונשין. בית המשפט הורה על אשפוזו של פלוני במחלקה סגורה. אלמוני תבע את פלוני בגין נזקיו. איזה מבין המשפטים הבאים מבטא נכונה את המצב המשפטי?',
    '{"exam_year": 2022, "exam_season": "winter", "exam_part": 2, "exam_question_number": 40}'::jsonb, 'השאלה עוסקת בהבחנה בין אחריות פלילית לאחריות נזיקית, ובפרט בשאלת השפעת קביעת אי-כשירות פלילית מחמת מחלת נפש על חבות בנזיקין. היא מתייחסת להלכה המנחה שנקבעה ברע"א 1272/05 כרמי נ'' סבג, לפיה מחלת נפש כשלעצמה אינה פוטרת מאחריות נזיקית, אלא אם היא שללה לחלוטין את השליטה על תנועות הגוף.', 'הלכת כרמי (רע"א 1272/05 גד כרמי נ'' דניאל סבג) קבעה כי הגנת אי שפיות הדעת, כפי שהיא מוגדרת בסעיף 34ח לחוק העונשין, אינה מהווה כשלעצמה הגנה בדיני נזיקין. אחריות בנזיקין תוטל על חולה נפש, אלא אם כן מחלת הנפש שללה ממנו לחלוטין את השליטה על תנועות גופו (אוטומטיזם), בדומה לסייג ''היעדר שליטה'' שבסעיף 34ז לחוק העונשין. תכלית דיני הנזיקין היא פיצוי הניזוק והשבת המצב לקדמותו, ולכן, באיזון בין המזיק הלא-שפוי לניזוק התמים, יד הניזוק על העליונה. לפיכך, קביעת בית המשפט בתיק הפלילי כי פלוני אינו בר עונשין בשל מחלת נפש, אינה פוטרת אותו כשלעצמה מאחריות בנזיקין.', 'הבלבול בין סייג אי-שפיות הדעת במשפט הפלילי, שמוביל לפטור מאחריות פלילית, לבין אחריות בנזיקין, שבה הפטור ניתן רק במקרים חריגים של היעדר שליטה פיזית.',
    '["אחריות פלילית", "אחריות נזיקית", "אי שפיות הדעת", "סעיף 34ח לחוק העונשין", "הלכת כרמי", "היעדר שליטה", "אוטומטיזם", "פיצוי ניזוק"]'::jsonb, '**וריאציה 1 — פטור פלילי:** האם פטור מאחריות פלילית בשל אי שפיות פוטר גם מאחריות נזיקית? ← לא, ככלל, הלכת כרמי קובעת שאין פטור אוטומטי בנזיקין (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 2 — מתי כן פטור בנזיקין?** ← רק אם מחלת הנפש שללה לחלוטין את השליטה על תנועות הגוף (אוטומטיזם) (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 3 — תכלית דיני נזיקין:** מדוע אין פטור אוטומטי בנזיקין? ← תכלית דיני הנזיקין היא פיצוי הניזוק, ובאיזון בין מזיק לא שפוי לניזוק תמים, יד הניזוק על העליונה (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 4 — סעיף 34ח מול 34ז:** איזו הגנה פלילית דומה להגנה בנזיקין? ← הגנת היעדר שליטה (סעיף 34ז לחוק העונשין) דומה יותר להגנה בנזיקין מאשר הגנת אי שפיות (סעיף 34ח) (ת"א (שלום עכו) 1395-07-08 חתחות).', 'אי שפיות פלילית (34ח) ← לא פוטרת אוטומטית בנזיקין → פטור בנזיקין רק במקרה של היעדר שליטה פיזית (אוטומטיזם) → הלכת כרמי.', '["רע\"א 1272/05 גד כרמי נ'' דניאל סבג (2.12.2007)", "סעיף 34ח לחוק העונשין, תשל\"ז-1977", "סעיף 34ז לחוק העונשין, תשל\"ז-1977", "ת\"א (שלום בת ים) 34735-07-16 פלוני נ'' ר'' ב'' כ'' סלאמה (29.9.2021)", "ת\"א (שלום עכו) 1395-07-08 עמאד חתחות נ'' ח''אלד חתחות (9.9.2013)", "תא\"מ (שלום ת\"א) 63499-05-17 ניר סער נ'' מדינת ישראל (משטרת ישראל) (25.9.2017)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Tort liability of mentally-ill attacker after criminal court found him unfit — civil-vs-criminal liability boundary | source_review_note: השאלה עוסקת בהבחנה בין אחריות פלילית לאחריות נזיקית של חולה נפש, נושא מהותי בדיני נזיקין. מבין תתי הנושאים הקיימים, ''הליכים'' תחת ''סדר דין אזרחי'' הוא הקרוב ביותר, אך אינו מדויק לחלוטין. יש לשקול הוספת תת-נושא ייעודי ל''דיני נזיקין'' או ''עוולת הרשלנות/התקיפה''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'קביעת בית המשפט בתיק הפלילי פוטרת את פלוני מכל אחריות בנזיקין.', false, 'טענה זו שגויה. הלכת כרמי קבעה כי הגנת אי שפיות הדעת במשפט הפלילי אינה פוטרת כשלעצמה מאחריות בנזיקין, אלא אם נשללה לחלוטין השליטה על תנועות הגוף.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'קביעת בית המשפט בתיק הפלילי פוטרת את פלוני מאחריות בנזיקין רק לעוולות הדורשות יסוד נפשי כדוגמת זדון או כוונה.', false, 'טענה זו שגויה. גם בעוולות הדורשות יסוד נפשי של כוונה, הפסיקה קבעה כי ניתן לייחס כוונה זו לחולה נפש, אלא אם נשללה ממנו השליטה על תנועות גופו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'קביעת בית המשפט בתיק הפלילי אינה פוטרת כשלעצמה את פלוני מאחריות בנזיקין.', true, 'זוהי התשובה הנכונה. הלכת כרמי קבעה כי הגנת אי שפיות הדעת (סעיף 34ח לחוק העונשין) אינה מהווה כשלעצמה הגנה בדיני נזיקין, שכן תכלית דיני הנזיקין היא פיצוי הניזוק.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בשום נסיבות אין בכוחה של קביעת בית המשפט בתיק הפלילי לפטור את פלוני מאחריות בנזיקין.', false, 'טענה זו שגויה. קביעת בית המשפט בתיק הפלילי יכולה לפטור מאחריות בנזיקין אם היא מלמדת על מצב של היעדר שליטה מוחלט על תנועות הגוף (אוטומטיזם), כפי שנקבע בהלכת כרמי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות בנזיקין במצב של אוטומטיזם',
    1, 'ראובן, חולה אפילפסיה, נהג ברכבו. במהלך נהיגתו, לקה בהתקף אפילפטי פתאומי ובלתי צפוי, איבד שליטה על הרכב ופגע בהולך רגל. האם ראובן יישא באחריות נזיקית כלפי הולך הרגל?', 'שאלה זו בוחנת את החריג להלכת כרמי, לפיו חולה נפש (או אדם הלוקה במחלה פיזית) יכול להיות פטור מאחריות נזיקית אם הוכח כי פעל במצב של אוטומטיזם, כלומר, חוסר שליטה מוחלט על תנועות גופו. היא מדגישה את ההבחנה בין אי-שפיות לבין היעדר שליטה פיזית.', 'הלכת כרמי (רע"א 1272/05) קבעה כי הגנת אי שפיות הדעת אינה פוטרת מאחריות נזיקית, אלא אם מחלת הנפש (או מחלה פיזית) שללה לחלוטין את השליטה על תנועות הגוף, מצב המכונה אוטומטיזם. במקרה כזה, אין ''מעשה'' במובן הנזיקי, שכן לא הייתה בחירה חופשית. נטל ההוכחה לקיומו של אוטומטיזם מוטל על הטוען לו. אם ראובן לקה בהתקף אפילפטי פתאומי ובלתי צפוי שגרם לו לאבד שליטה מוחלטת על תנועות גופו, הוא יהיה פטור מאחריות נזיקית, שכן לא ביצע ''מעשה'' במובן המשפטי.',
    'הטעות הנפוצה היא לחשוב שכל מחלה, נפשית או פיזית, פוטרת מאחריות נזיקית, מבלי להבחין בין חוסר יכולת להבין את המעשה לבין חוסר שליטה מוחלט על תנועות הגוף.', '["אוטומטיזם", "היעדר שליטה", "הלכת כרמי", "אחריות נזיקית", "מחלת נפש", "מחלה פיזית", "סעיף 34ז לחוק העונשין"]'::jsonb, '**וריאציה 1 — אוטומטיזם:** מהו אוטומטיזם בהקשר נזיקי? ← חוסר שליטה מוחלט על תנועות הגוף, השולל את יסוד ה''מעשה'' (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 2 — נטל ההוכחה:** מי נושא בנטל ההוכחה לאוטומטיזם? ← הטוען לו, במאזן הסתברויות (ת"א (שלום עכו) 1395-07-08 חתחות).
**וריאציה 3 — מחלת נפש מול פיזית:** האם יש הבדל בין אוטומטיזם ממחלת נפש לאוטומטיזם ממחלה פיזית? ← לא, הפטור חל בשני המקרים אם נשללה השליטה על תנועות הגוף (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 4 — הבאת עצמו למצב:** מה קורה אם המזיק הביא עצמו למצב של אוטומטיזם מרצון (למשל, לא נטל תרופות)? ← הפטור לא יחול (תזכיר חוק דיני ממונות, סעיף 374, מצוטט בת"א (שלום עכו) 1395-07-08 חתחות).', 'אוטומטיזם (חוסר שליטה מוחלט) ← פטור מאחריות נזיקית → גם אם נגרם נזק → חריג להלכת כרמי.',
    '["רע\"א 1272/05 גד כרמי נ'' דניאל סבג (2.12.2007)", "ת\"א (שלום עכו) 1395-07-08 עמאד חתחות נ'' ח''אלד חתחות (9.9.2013)", "סעיף 34ז לחוק העונשין, תשל\"ז-1977"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, אם יוכח כי איבד שליטה מוחלטת על תנועות גופו עקב ההתקף, הוא יהיה פטור מאחריות בנזיקין.', true, 'זוהי התשובה הנכונה. הלכת כרמי קבעה כי פטור מאחריות נזיקית יינתן רק במקרה של היעדר שליטה מוחלט על תנועות הגוף (אוטומטיזם), בין אם מקורו במחלת נפש או במחלה פיזית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, מכיוון שמחלת אפילפסיה אינה פוטרת מאחריות נזיקית, שכן היא אינה שוללת את כושר השיפוט.', false, 'טענה זו שגויה. הפטור אינו תלוי בשלילת כושר השיפוט, אלא בשלילת השליטה על תנועות הגוף. אם נשללה שליטה מוחלטת, קיים פטור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך בית המשפט יפחית את גובה הפיצויים משיקולי צדק בשל מצבו הרפואי.', false, 'טענה זו שגויה. אם מתקיים פטור מלא מאחריות בשל אוטומטיזם, אין מקום להטיל אחריות ולהפחית פיצויים. הפחתה משיקולי צדק רלוונטית רק כאשר קיימת אחריות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אך רק אם יוכיח כי לא ידע על מחלתו או על הסיכון להתקף.', false, 'טענה זו שגויה. ידיעה על המחלה או הסיכון רלוונטית לשאלת ההתרשלות (האם נהג בסבירות), אך לא לשאלת היעדר השליטה המוחלטת על תנועות הגוף בעת המעשה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'יסוד הכוונה בעוולת התקיפה',
    2, 'מהי הפרשנות המקובלת ליסוד ה"כוונה" הנדרש בעוולת התקיפה לפי סעיף 23 לפקודת הנזיקין, ובפרט בהקשר של מזיק הלוקה במחלת נפש?', 'שאלה זו מתמקדת ביסוד הנפשי של עוולת התקיפה – ה"כוונה" – ומבהירה כי אין מדובר ב"זדון" או "רצון לגרום נזק", אלא במודעות לעצם השימוש בכוח. היא בוחנת כיצד יסוד זה מפורש בהקשר של מזיק הלוקה במחלת נפש, בהתאם להלכת כרמי.', 'סעיף 23(א) לפקודת הנזיקין מגדיר תקיפה כ"שימוש בכוח מכל סוג שהוא, ובמתכוון, נגד גופו של אדם". הפסיקה, ובפרט הלכת כרמי (רע"א 1272/05), פירשה את יסוד ה"כוונה" בעוולת התקיפה כמתייחס למודעות לעצם השימוש בכוח נגד גופו של אדם, ואין דרישה לזדון או לרצון לגרום נזק. כלומר, די בכך שהמזיק צפה את התוצאה של מעשיו וחפץ בהתרחשותה. ניתן לייחס כוונה זו גם לחולה נפש, אלא אם מחלתו שללה ממנו לחלוטין את השליטה על תנועות גופו (אוטומטיזם).',
    'הטעות הנפוצה היא להשוות את יסוד ה"כוונה" בעוולת התקיפה ליסוד ה"כוונה" במשפט הפלילי, הדורש לעיתים קרובות רצון לגרום לתוצאה מסוימת או זדון.', '["עוולת התקיפה", "יסוד הכוונה", "פקודת הנזיקין", "הלכת כרמי", "מודעות למעשה", "היעדר שליטה", "מחלת נפש"]'::jsonb, '**וריאציה 1 — כוונה בנזיקין:** מהי כוונה בעוולת התקיפה? ← מודעות לעצם השימוש בכוח נגד גופו של אדם, ללא דרישה לזדון (רע"א 1272/05 כרמי נ'' סבג).

**וריאציה 2 — כוונה וחולה נפש:** האם ניתן לייחס כוונה לחולה נפש? ← כן, אלא אם נשללה ממנו השליטה על תנועות גופו (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 3 — צפיית תוצאה:** האם צפיית תוצאה ורצון בהתרחשותה מספיקים? ← כן, זהו הפירוש המקובל ל"כוונה" (ת"א (שלום ירושלים) 17359-10-21 ע.ח נ'' א.ח).
**וריאציה 4 — מניע:** האם המניע למעשה רלוונטי ליסוד הכוונה? ← לא, שאלת המניע אינה רלוונטית לבחינת התקיימות יסוד הכוונה (ת"א (שלום עפ'') 21156-06-18 פלוני נ'' מחמוד איהב זיאדאת).', 'כוונה בתקיפה (נזיקין) → מודעות לשימוש בכוח → לא דורשת זדון → חלה גם על חולה נפש (אלא אם אוטומטיזם).',
    '["סעיף 23 לפקודת הנזיקין [נוסח חדש]", "רע\"א 1272/05 גד כרמי נ'' דניאל סבג (2.12.2007)", "ת\"א (שלום בת ים) 34735-07-16 פלוני נ'' ר'' ב'' כ'' סלאמה (29.9.2021)", "ת\"א (שלום ירושלים) 17359-10-21 ע.ח נ'' א.ח (12.1.2025)", "ת\"א (שלום עפ'') 21156-06-18 פלוני נ'' מחמוד איהב זיאדאת (7.12.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הכוונה מתייחסת לזדון ולרצון מפורש לגרום נזק, ואינה יכולה להתקיים אצל חולה נפש.', false, 'טענה זו שגויה. הפסיקה קבעה כי הכוונה בעוולת התקיפה אינה דורשת זדון או רצון לגרום נזק, אלא מודעות לעצם המעשה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הכוונה מתייחסת ליכולת להבחין בין טוב לרע, ובהיעדרה, חולה נפש פטור מאחריות.', false, 'טענה זו שגויה. היכולת להבחין בין טוב לרע רלוונטית להגנת אי שפיות הדעת במשפט הפלילי, אך לא ליסוד הכוונה בעוולת התקיפה בנזיקין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הכוונה מתייחסת למודעות לעצם השימוש בכוח נגד גופו של אדם, ואין דרישה לזדון או לרצון לגרום נזק, וניתן לייחס כוונה זו גם לחולה נפש אלא אם נשללה שליטה על תנועות גופו.', true, 'זוהי התשובה הנכונה. הפסיקה (הלכת כרמי) קבעה כי יסוד הכוונה בעוולת התקיפה מתמקד במודעות לעצם המעשה, וניתן לייחסו לחולה נפש, אלא אם נשללה ממנו השליטה על תנועות גופו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הכוונה מתייחסת למניע שמאחורי המעשה, ובהיעדר מניע פסול, חולה נפש פטור מאחריות.', false, 'טענה זו שגויה. המניע שמאחורי המעשה אינו רלוונטי ליסוד הכוונה בעוולת התקיפה, אלא רק לעצם המודעות לשימוש בכוח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שיקולי צדק בהפחתת פיצוי',
    3, 'דוד, הלוקה במחלת נפש, תקף את שרה וגרם לה נזקי גוף. בית המשפט קבע כי דוד אחראי בנזיקין למעשיו. האם בית המשפט רשאי להפחית את גובה הפיצויים שיוטלו על דוד משיקולי צדק, בהתחשב במצבו הנפשי הקשה?', 'שאלה זו עוסקת בסמכות בית המשפט להפחית פיצויים בנזיקין משיקולי צדק, גם לאחר שנקבעה אחריות, ובפרט במקרים בהם המזיק לוקה במחלת נפש. היא בוחנת את האיזון בין הצורך לפצות את הניזוק לבין שיקולים הומניטריים ושיקומיים הנוגעים למזיק.', 'הלכת כרמי (רע"א 1272/05) קבעה כי הגנת אי שפיות הדעת אינה פוטרת מאחריות נזיקית, אך כב'' השופטת ארבל ציינה כי ייתכנו מקרים בהם שיקולי צדק יצדיקו מתן פטור מסוים למזיק חולה הנפש מחובת פיצויו של הניזוק, ואין הכרח כי מדובר יהיה בפטור מלא. בתי המשפט לענייני משפחה, למשל, הפחיתו פיצויים משיקולי צדק במקרים של חולי נפש שפגעו בבני משפחתם, תוך התחשבות בסיפור המשפחתי, מצבו הכלכלי של המזיק והשפעת החיוב על שיקומו (תמ"ש (פ"ת) 41058-03-11 ינ. א נ'' י. א).',
    'הטעות הנפוצה היא לחשוב שמרגע שנקבעה אחריות, גובה הפיצוי הוא קבוע ואינו נתון לשיקולי צדק, או להתעלם מהאפשרות להפחתה חלקית.', '["שיקולי צדק", "הפחתת פיצויים", "אחריות נזיקית", "מחלת נפש", "הלכת כרמי", "איזון אינטרסים", "שיקום המזיק"]'::jsonb, '**וריאציה 1 — פטור מלא מול הפחתה:** האם שיקולי צדק יכולים להוביל לפטור מלא? ← לא בהכרח, לעיתים מדובר בהפחתה חלקית של הפיצוי (רע"א 1272/05 כרמי נ'' סבג, דעת השופטת ארבל).
**וריאציה 2 — איזון אינטרסים:** אילו אינטרסים מאזנים בתי המשפט בהפחתת פיצויים? ← הצורך בפיצוי הניזוק מול שיקום המזיק, מצבו הכלכלי של המזיק, והסיפור המשפחתי (תמ"ש (פ"ת) 41058-03-11 ינ. א נ'' י. א).
**וריאציה 3 — תפקיד צד שלישי:** האם קיום צד שלישי (מבטח) משפיע? ← כן, השופטת ארבל הציעה לשקול פטור כאשר הפיצוי מתאפשר על ידי צד שלישי (רע"א 1272/05 כרמי נ'' סבג).
**וריאציה 4 — חומרת המעשה:** האם חומרת המעשה משפיעה על שיקולי הצדק? ← כן, מעשה אכזרי במיוחד יכול להפחית את נטיית בית המשפט להפחית פיצויים, אך עדיין יש לאזן עם שיקולי שיקום (תמ"ש (פ"ת) 41058-03-11 ינ. א נ'' י. א).', 'שיקולי צדק → הפחתת פיצויים → אפשרי במקרים חריגים (חולי נפש) → איזון בין ניזוק למזיק → לא בהכרח פטור מלא.',
    '["רע\"א 1272/05 גד כרמי נ'' דניאל סבג (2.12.2007)", "תמ\"ש (משפחה פתח תקוה) 41058-03-11 ינ. א נ'' י. א (1.9.2015)", "תמ\"ש (משפחה פתח תקוה) 41058-03-11 ינ. א נ'' יו. א (20.1.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מרגע שנקבעה אחריות בנזיקין, אין לבית המשפט שיקול דעת להפחית פיצויים משיקולי צדק.', false, 'טענה זו שגויה. הפסיקה הכירה באפשרות להפחית פיצויים משיקולי צדק, גם לאחר קביעת אחריות, במקרים חריגים ובהתחשב בנסיבות המיוחדות של המזיק והניזוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, בית המשפט רשאי להפחית את גובה הפיצויים משיקולי צדק, אך רק במקרים חריגים ובהתחשב באיזון בין עניינו של המזיק לעניינו של הניזוק.', true, 'זוהי התשובה הנכונה. הפסיקה (כב'' השופטת ארבל בעניין כרמי, וכן תמ"ש (פ"ת) 41058-03-11) הכירה באפשרות להפחית פיצויים משיקולי צדק, במיוחד במקרים של חולי נפש, תוך איזון בין הצורך בפיצוי הניזוק לבין שיקום המזיק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הפיצויים מתאפשרים על ידי צד שלישי (כגון חברת ביטוח), ולא על ידי המזיק עצמו.', false, 'טענה זו שגויה. אמנם שיקול זה הוצע בפסיקה, אך הוא אינו תנאי בלעדי להפחתת פיצויים משיקולי צדק. הפחתה יכולה להיעשות גם כאשר המזיק עצמו נושא בנטל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הניזוק הסכים להפחתה מראש.', false, 'טענה זו שגויה. שיקולי צדק הם שיקולים של בית המשפט, ואינם תלויים בהסכמת הניזוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות בנזיקין של חולה נפש בלשון הרע',
    4, 'דנה, הסובלת מסכיזופרניה פרנואידית, הגישה תלונת שווא במשטרה נגד שכנה, בטענה כי הוא תקף אותה. דנה האמינה בכנות בנכונות התלונה עקב מחלתה. השכן תבע את דנה בגין לשון הרע. האם דנה תהיה אחראית בנזיקין על לשון הרע?', 'שאלה זו בוחנת את תחולת הגנת תום הלב בעוולת לשון הרע כאשר המזיק לוקה במחלת נפש המשפיעה על תפיסת המציאות שלו. היא מדגישה את ההבדל בין יסוד ה"כוונה" בעוולת התקיפה לבין יסוד ה"אמונה בכנות" בעוולת לשון הרע.', 'בעוולת לשון הרע, הגנת תום הלב (למשל, סעיף 15(8) לחוק איסור לשון הרע לגבי תלונה לרשות מוסמכת) חלה כאשר המפרסם האמין בכנות בנכונות הפרסום. הפסיקה קבעה כי אם אמונה זו נובעת ממחלת נפש המשפיעה על תפיסת המציאות, והמזיק אכן סבר בכנות שהדברים נכונים, עשויה לעמוד לו הגנת תום הלב, גם אם הפרסום אינו נכון עובדתית. זאת, בניגוד לעוולת התקיפה, שם נדרשת שלילה מוחלטת של שליטה על תנועות הגוף (ת"א (שלום ראשל"צ) 57762-04-18 פלוני נ'' אלמוני).',
    'הטעות הנפוצה היא להחיל את הלכת כרמי (היעדר שליטה פיזית) באופן גורף על כל עוולות הנזיקין, מבלי לבחון את היסוד הנפשי הספציפי הנדרש בכל עוולה.', '["לשון הרע", "הגנת תום לב", "חוק איסור לשון הרע", "מחלת נפש", "תפיסת מציאות", "אמונה בכנות", "אחריות נזיקית"]'::jsonb, '**וריאציה 1 — אמונה כנה:** האם אמונה כנה בנכונות הפרסום מספיקה להגנת תום לב בלשון הרע? ← כן, גם אם האמונה נובעת ממחלת נפש (ת"א (שלום ראשל"צ) 57762-04-18 פלוני נ'' אלמוני).
**וריאציה 2 — תלונה במשטרה:** האם הגשת תלונת שווא במשטרה על ידי חולה נפש פטורה מלשון הרע? ← כן, אם האמין בכנות בנכונותה, עומדת לו הגנת סעיף 15(8) לחוק איסור לשון הרע (ת"א (שלום ראשל"צ) 57762-04-18 פלוני נ'' אלמוני).
**וריאציה 3 — השוואה לתקיפה:** מה ההבדל בין אחריות חולה נפש בתקיפה ללשון הרע? ← בתקיפה נדרש היעדר שליטה פיזית, בלשון הרע נדרשת אמונה כנה בנכונות הפרסום (ת"א (שלום ראשל"צ) 57762-04-18 פלוני נ'' אלמוני).
**וריאציה 4 — אי-כשירות נפשית:** האם אי-כשירות נפשית כשלעצמה פוטרת מלשון הרע? ← לא, יש להוכיח שהיא הובילה לאמונה כנה בנכונות הפרסום, ולא רק מצוקה נפשית כללית (ת"א (שלום הרצ'') 39291-06-18 שי תירם נ'' אבלין כאליף כהן).', 'לשון הרע (חולה נפש) → הגנת תום לב → אם האמין בכנות בנכונות הפרסום → גם אם האמונה נובעת ממחלה → שונה מתקיפה.',
    '["חוק איסור לשון הרע, תשכ\"ה-1965", "ת\"א (שלום ראשל\"צ) 57762-04-18 פלוני נ'' אלמוני (14.9.2020)", "ת\"א (שלום הרצ'') 39291-06-18 שי תירם נ'' אבלין כאליף כהן (3.8.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, מכיוון שמחלת נפש אינה פוטרת מאחריות בנזיקין, אלא אם נשללה שליטה על תנועות הגוף.', false, 'טענה זו שגויה. בעוולת לשון הרע, יסוד ה"כוונה" או "תום הלב" שונה מעוולת התקיפה, ואינו דורש בהכרח היעדר שליטה פיזית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, מכיוון שהגנת תום הלב לפי חוק איסור לשון הרע חלה כאשר המתלונן האמין בכנות בנכונות התלונה, גם אם אמונה זו נובעת ממחלת נפש.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי בעוולת לשון הרע, אם המזיק האמין בכנות בנכונות הפרסום, גם אם אמונה זו נובעת ממחלת נפש המשפיעה על תפיסת המציאות, עשויה לעמוד לו הגנת תום הלב (ת"א (שלום ראשל"צ) 57762-04-18 פלוני נ'' אלמוני).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך בית המשפט יפחית את גובה הפיצויים משיקולי צדק בשל מצבה הנפשי.', false, 'טענה זו שגויה. אם עומדת הגנת תום הלב, דנה תהיה פטורה מאחריות לחלוטין, ולא רק שהפיצויים יופחתו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אך רק אם הוכרזה כפסולת דין על ידי בית המשפט.', false, 'טענה זו שגויה. הכרזה כפסול דין אינה תנאי להחלת הגנת תום הלב בעוולת לשון הרע, ואינה פוטרת אוטומטית מאחריות נזיקית (תא"מ (שלום ת"א) 63499-05-17 ניר סער נ'' מדינת ישראל).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 40, '2022-W-S-Q40';
END
$$;


